P.entries["subzone:sanctum-stromgarde-keep"] = {n="Sanctum (Stromgarde Keep)",s="密室是位于激流堡教堂后方的一处神圣堡垒。它坐落在摇摇欲坠的要塞之中，守卫着通往托尔贝恩家族先祖陵墓的入口，在阿拉希的废墟中，这里是圣光仅存的堡垒之一。",h="密室是位于激流堡教堂后方的一处神圣堡垒。它坐落在摇摇欲坠的要塞之中，守卫着通往托尔贝恩家族先祖陵墓的入口，在阿拉希的废墟中，这里是圣光仅存的堡垒之一。",kw={"阿拉希","教堂","圣光大教堂","陵墓","加林","密室","激流堡","托尔贝恩"},ang={["class:Paladin"]="教堂和密室是阿拉希沦陷的都城中最后未被玷污的圣光避难所，因此保卫这里是一项庄严的职责。",["faction:Alliance"]="守住密室确保了托尔贝恩王室能够继续维持对先祖领地的控制，让联盟在激流堡的争夺废墟中依然保有一席之地。"},sec={{t="废墟中的堡垒",b="尽管激流堡的大部分地区已经落入辛迪加渗透者和巨石食人魔之手，但密室及其相邻的教堂在激流堡幸存守军的殊死保卫下依然未被攻陷。密室位于礼拜堂后方，与要塞的墓地接壤，是通往激流堡历代国王安息的皇家陵墓的必经之地。对于簇拥在加林·托尔贝恩王子麾下的残部忠诚者来说，守住这片神圣的土地不仅仅是一个战术据点的问题；更是一场为了守护王国先祖传承与信仰不被入侵者践踏而进行的绝望之战。"},{t="国王的门槛",b="密室的石板之下通往皇家陵墓。这里的土地是神圣的，原本是人们静思和崇拜圣光的地方。在索拉斯·托尔贝恩国王遇刺及王国随之崩溃后，密室反而成为了一个防御性的撤退点。那些试图闯入The Inner Sanctum的人不仅要面对遍布大厅的皇家卫兵，还要面对这个古老的人类血脉在神圣门槛上苦苦求存的凄凉现实。"}},faq={{q="什么是密室？",a="密室是激流堡内圣光大教堂后方的内部区域。它与要塞的墓地相连，并直接通往托尔贝恩家族的先祖陵墓。",al={"什么是密室","激流堡密室"}},{q="现在是谁控制着密室？",a="密室由忠于联盟和加林·托尔贝恩王子的幸存激流堡士兵把守。与被辛迪加匪徒和巨石食人魔占领的城市其他地区不同，教堂和密室仍在人类的守卫之下。",al={"谁在密室里","密室守卫","谁控制了密室"}},{q="密室后面有什么？",a="穿过密室便是托尔贝恩家族的陵墓，激流堡历代陨落的统治者，包括最近遇害的索拉斯·托尔贝恩国王，都安葬于此。",al={"密室通向哪里","密室陵墓","密室后面有什么"}},{q="为什么这个区域对激流堡很重要？",a="密室不仅是崇拜圣光的神圣中心，还守护着激流堡国王的皇家安息之地。对于幸存的守军来说，放弃这里就意味着任由入侵者亵渎先祖的坟墓。",al={"为什么要在意密室","密室的意义","为什么要保卫密室"}}},fp="25,272,22.618.0,22.542.0,20.183.0,35.238.0,29.154.0,41.249.0"}
P.entries["subzone:sandsorrow-watch"] = {n="流沙岗哨",s="流沙岗哨是一个位于塔纳利斯加基森以西的广阔沙漠前哨站。周围的沙丘和废墟被敌对的沙怒巨魔及其复活的亡者所占领，他们还控制着俯瞰荒地的东侧瞭望塔。",h="流沙岗哨是一个位于塔纳利斯加基森以西的广阔沙漠前哨站。周围的沙丘和废墟被敌对的沙怒巨魔及其复活的亡者所占领，他们还控制着俯瞰荒地的东侧瞭望塔。",kw={"加基森","沙巨魔","沙怒","流沙岗哨","塔纳利斯"},ang={["profession:Blacksmithing"]="在沙怒控制的瞭望塔里没有铁匠工作；沙漠铁匠们都聚集在东面加基森的城墙内。",["race:Troll"]="暗矛巨魔在这里找不到任何亲属关系：敌对的沙怒部族将所有外来者视为必须被粉碎并复活为行尸走肉的入侵者。"},sec={{t="危险的栖木",b="流沙岗哨位于繁华的地精贸易枢纽加基森的正西方，是塔纳利斯沙漠中一处严峻的边境。这片广袤的区域主要由沙怒部族控制，他们与成群结队的行尸巨魔一起，积极捍卫着这片荒凉的领土。位于东侧边缘的一座高耸瞭望塔巩固了他们的阵地，在这片不断侵蚀的沙漠荒野和敌对的土著部族之间，提供了一个坚固的有利位置。"},{t="边境前哨",b="即使是位于东侧边缘、在加基森城墙视线范围内的瞭望塔，也被沙怒部族所把持。他们从高处警惕地注视着这座地精城镇，而从加基森西门离开的旅行者几乎会直接走进他们的领地，这时刻提醒着人们塔纳利斯投机定居者与当地沙巨魔之间不稳定的边境紧张局势。"}},faq={{q="流沙岗哨位于何处？",a="流沙岗哨位于塔纳利斯北部沙漠平原，加基森的正西方。从加基森西门出发的旅行者几乎会立即遇到它。",al={"流沙岗哨位置","流沙岗哨在哪里","如何前往流沙岗哨"}},{q="谁控制着流沙岗哨？",a="废墟、周围的沙丘以及东侧的瞭望塔全部被敌对的沙怒巨魔及其亡灵爪牙所占领。",al={"谁住在流沙岗哨","流沙岗哨阵营","谁占领了流沙岗哨"}},{q="为什么流沙岗哨会有亡灵巨魔？",a="沙怒部族修炼邪恶的死灵法术和巫毒，经常将阵亡的沙怒勇士复活为沙怒僵尸，以守卫他们遍布塔纳利斯的荒凉领土和前哨站。",al={"沙怒僵尸","为什么塔纳利斯有巨魔僵尸","流沙岗哨僵尸"}},{q="冒险者在周围的沙丘中会遇到什么威胁？",a="该地区有大量的沙怒投斧手、火法师和剥皮者巡逻，随行的还有他们复活的巨魔僵尸。未经准备的旅行者如果走出加基森西侧的主路，很容易被游荡的沙怒战团所淹没。",al={"流沙岗哨怪物","流沙岗哨敌人","流沙岗哨敌对巨魔"}}},fp="16,248,18.453.0,16.387.0,34.189.0,30.130.0,48.189.0,61.250.0"}
P.entries["subzone:sar-theris-strand"] = {n="萨瑟里斯海岸",s="萨瑟里斯海岸构成了凄凉之地的西海岸线，面朝迷雾之海。与贫瘠灰暗的内陆荒野形成鲜明对比的是，这里的海岸阳光明媚、绿草如茵，但由于徘徊的娜迦、海巨人以及马库拉，这里依然危机四伏。",h="萨瑟里斯海岸构成了凄凉之地的西海岸线，面朝迷雾之海。与贫瘠灰暗的内陆荒野形成鲜明对比的是，这里的海岸阳光明媚、绿草如茵，但由于徘徊的娜迦、海巨人以及马库拉，这里依然危机四伏。",kw={"凄凉之地","karnitol","马库拉","萨瑟里斯","海岸","虎鱼"},ang={["profession:Cooking"]="萨瑟里斯海岸及周边水域拥有丰富的海洋猎物，包括马库拉和珍稀海鱼，但生火烹饪时必须时刻提防徘徊的娜迦。"},sec={{t="灰色荒野上的绿色边缘",b="萨瑟里斯海岸绵延在凄凉之地的西侧，为内陆平原的尘灰提供了一处离奇的休憩之所。这里的崖顶和海滩明亮而翠绿。然而，这片海岸绝非善地：蛇形的娜迦与高大的海巨人及领地意识极强的马库拉一同巡视着浪潮。浅滩上散落着沉船残骸，包括北方的Karnitol号残骸，以及艾瑟雷索高塔下方破碎的小艇，证明了海洋与海岸一样险恶。"},{t="残骸与珍稀水域",b="除了娜迦和巨人的持续威胁外，海岸外的水域因其独特的馈赠而在老练的旅行者中闻名。崎岖的近海浅滩中隐藏着来自失踪探险队和商队的打捞物，而深处的浪潮中栖息着珍稀的海洋生物，最著名的便是卡利姆多各地的钓鱼大师们苦苦追寻的珍贵鱼类——萨瑟里斯虎鱼。"}},faq={{q="为什么凄凉之地的其他地方一片死寂，而萨瑟里斯海岸却是绿色的？",a="与凄凉之地贫瘠灰暗的内陆相比，这段海岸线阳光明媚，绿草如茵。来源中并未解释造成这种反差的原因。",al={"为什么海岸是绿色的","凄凉之地沿海草地","萨瑟里斯天气"}},{q="萨瑟里斯海岸栖息着哪些生物？",a="这片海岸的主要居民是两栖的Slitherblade娜迦、游荡的海巨人以及横行的马库拉。旅行者必须时刻留意浪潮，因为巡逻队经常在水边出没。",al={"这里住着谁","萨瑟里斯怪物","海岸上有哪些怪物"}},{q="海岸边有哪些沉船残骸？",a="Karnitol沉船位于海岸北侧的水域中，而在艾瑟雷索精灵遗迹高塔下方的海滩断崖上，则散落着较小船只的残骸。",al={"karnitol沉船","海岸沉船","海滩残骸"}},{q="为什么渔夫们会前往萨瑟里斯海岸？",a="这里的沿海水域是萨瑟里斯虎鱼的唯一栖息地，这种难以捕捉的鱼类被著名的垂钓者纳特·帕格公认为是考验钓鱼技艺的终极挑战之一。",al={"萨瑟里斯虎鱼","凄凉之地海岸钓鱼","纳特·帕格鱼类"}}},fp="17,241,28.496.0,24.369.0,65.143.0,41.190.0,36.169.0,44.178.0"}
P.entries["subzone:sardor-isle"] = {n="萨尔多岛",s="萨尔多岛是一座郁郁葱葱的岛屿，坐落于菲拉斯西海岸外，恐怖之岛的北部。它是羽月要塞的所在地，而羽月要塞是卡利姆多南部主要的暗夜精灵军事堡垒。尽管有大量的哨兵驻守，岛屿的部分地区仍有野兽出没，并有从浅滩爬上来的敌对纳迦潜伏。",h="萨尔多岛是一座郁郁葱葱的岛屿，坐落于菲拉斯西海岸外，恐怖之岛的北部。它是羽月要塞的所在地，而羽月要塞是卡利姆多南部主要的暗夜精灵军事堡垒。尽管有大量的哨兵驻守，岛屿的部分地区仍有野兽出没，并有从浅滩爬上来的敌对纳迦潜伏。",kw={"羽月要塞","菲拉斯","恐怖之岛","纳迦","萨尔多岛","哨兵","珊蒂斯·羽月"},ang={["faction:Alliance"]="萨尔多岛是联盟在菲拉斯的主要权力支点，在羽月要塞内提供安全的港湾、补给和飞行管理员。",["race:NightElf"]="在珊蒂斯·羽月将军的领导下，萨尔多岛上的哨兵们密切关注着整个菲拉斯的古代遗迹以及新出现的纳迦威胁。"},sec={{t="哨兵堡垒与荒野海岸",b="萨尔多岛隔水与菲拉斯大陆相望，岛上坐落着羽月要塞，这是一座由珊蒂斯·羽月将军指挥的雄伟精灵驻军点。虽然要塞本身防御森严，并有定期渡轮与大陆相连，但整座岛屿远未被完全驯服。成群的狼在树木繁茂的山坡上游荡，而入侵的纳迦则潜伏在岩石嶙峋的西岸和北岸，不断试探着暗夜精灵哨兵的底线。"}},faq={{q="萨尔多岛位于哪里？",a="萨尔多岛位于卡利姆多南部的菲拉斯西海岸外，就在恐怖之岛的北面。可以通过从大陆被遗忘的海岸出发的船只抵达。",al={"萨尔多岛位置","萨尔多在哪里","寻找萨尔多岛"}},{q="萨尔多岛上的主要定居点是什么？",a="岛上由羽月要塞占据主导地位，这是暗夜精灵和联盟在菲拉斯的主要堡垒和集结地，由珊蒂斯·羽月将军指挥。",al={"谁住在萨尔多岛","萨尔多岛城镇","萨尔多暗夜精灵基地"}},{q="要塞之外的岛上有什么威胁？",a="在羽月要塞的保护墙之外，旅行者会面临在树林中游荡的野狼群，以及潜伏在沿海礁石和沙滩上的敌对纳迦。",al={"萨尔多岛敌人","萨尔多岛上的危险","萨尔多怪物"}},{q="萨尔多岛与恐怖之岛有何不同？",a="萨尔多岛位于北面，主要由羽月要塞的暗夜精灵占据。恐怖之岛位于更南边，是一片更加严酷、未被驯服的领土，到处都是危险的奇美拉和纳迦。",al={"萨尔多岛与恐怖之岛的区别","与恐怖之岛的不同之处"}}},fp="11,355,32.491.0,29.184.0,43.181.0,60.181.0,51.221.0"}
P.entries["subzone:sargeron"] = {n="萨格隆",s="萨格隆是位于凄凉之地北部的一座古老暗夜精灵城市的废墟。在天崩地裂中，这座城市分崩离析，其前身为艾露恩神殿的地方如今已被愤怒的萨特占领并亵渎，他们以其主人萨格拉斯之名重新命名了这片土地。",h="萨格隆是位于凄凉之地北部的一座古老暗夜精灵城市的废墟。在天崩地裂中，这座城市分崩离析，其前身为艾露恩神殿的地方如今已被愤怒的萨特占领并亵渎，他们以其主人萨格拉斯之名重新命名了这片土地。",kw={"艾露恩之杯","凄凉之地","艾露恩","愤怒萨特","卡多雷","萨格拉斯","萨格隆","萨特"},ang={["class:Priest"]="月亮祭司们会认出散落在破碎石块间的艾露恩大教堂遗迹和圣物，并敦促对其进行净化。",["race:NightElf"]="对任何卡多雷来说，这些废墟都是令人心痛的景象，因为神圣的艾露恩祭坛正被恶魔萨特公然亵渎，他们以萨格拉斯的名义嘲弄着女神。"},sec={{t="一处被亵渎的圣所",b="在上古之战摧毁这片大陆之前，这处定居点是一座繁荣的艾露恩崇拜中心，供奉着艾露恩神殿、圣所和大教堂等圣地。它原本的名称早已湮没在历史中。当世界破碎时，城市化为废墟，留下了如艾露恩之杯、艾露恩火盆和艾露恩侍女等圣物。在随后的数千年里，堕落的愤怒萨特占领了这些石头建筑，将神圣的卡多雷建筑改造成了供奉泰坦萨格拉斯的据点。"}},faq={{q="大分裂前萨格隆叫什么名字？",a="它原本的暗夜精灵名称早已被时间遗忘。现名“萨格隆”是愤怒萨特为了向堕落泰坦萨格拉斯致敬，而给这些废墟取的名字。",al={"原始名称","萨格隆原始名称","它过去叫什么"}},{q="现在是谁占据着萨格隆？",a="这些废墟被愤怒萨特占据，他们是上古之战期间产生的堕落恶魔生物，一直在积极亵渎这些古老的精灵遗迹。",al={"谁住在这里","萨格隆怪物","萨格隆的敌人"}},{q="这里最初有哪些圣地？",a="这座城市曾拥有多处供奉月亮女神的重要场所，包括艾露恩神殿、艾露恩圣所和艾露恩大教堂，这里曾存放着如艾露恩之杯等受人崇敬的圣物。",al={"艾露恩神殿","圣地","这里曾有什么建筑"}},{q="为什么萨格隆对暗夜精灵很重要？",a="它作为上古之战的残酷提醒，见证了恶魔势力对卡多雷神圣空间的亵渎，并保存着古老的精灵神器，这些神器面临着丢失或被腐化的风险。",al={"萨格隆暗夜精灵传说","为什么暗夜精灵在意"}}},fp="8,270,19.549.0,46.166.0,26.156.0,45.192.0,43.186.0"}
P.entries["subzone:satyrnaar"] = {n="萨提纳尔",s="萨提纳尔是一处位于灰谷东北部的古老暗夜精灵废墟定居点，现已完全落入邪心萨特的手中。它坐落在碎木岗哨与艾萨拉之间的主干道旁，是森林中保存最完好且最容易进入的萨特据点。",h="萨提纳尔是一处位于灰谷东北部的古老暗夜精灵废墟定居点，现已完全落入邪心萨特的手中。它坐落在碎木岗哨与艾萨拉之间的主干道旁，是森林中保存最完好且最容易进入的萨特据点。",kw={"灰谷","邪心","暗滩","林歌神殿","萨特","萨提纳尔","灵魂宝石","碎木"},ang={["class:Druid"]="邪心萨特散布的扭曲邪能正在不断扼杀灰谷的自然之灵，必须尽快净化。",["race:NightElf"]="看着祖先的石刻遭到邪能腐蚀，并被诅咒的上层精灵遗民所占据，这对任何途经灰谷的暗夜精灵来说都是一种沉重的冒犯。"},sec={{t="邪能与暗影的巢穴",b="萨提纳尔位于碎木岗哨东北方、林歌神殿西南方，与萨维亚和夜道谷并列为灰谷的三大主要萨特定居点之一。与其他深处的荒野遗迹不同，萨提纳尔相对保存完好，在崩塌的精灵建筑中搭建着帐篷。它是邪心萨特的繁忙营地，导致前往艾萨拉的附近贸易路线对旅行者来说充满了危险。此外，黑暗的勾当在此滋生：萨特们与阴暗的暗滩教派结成了同盟，并将他们邪恶的灵魂宝石之一藏在这些腐化的石块之中。"}},faq={{q="萨提纳尔是什么地方？",a="萨提纳尔是灰谷东北部的一处暗夜精灵遗迹，已被邪心萨特占据。它是该地区萨特的主要据点之一。",al={"萨提纳尔概况","这是什么地方","萨特营地"}},{q="谁居住在萨提纳尔？",a="该定居点由邪心萨特部族占据。他们在古老的遗迹中搭建帐篷，并与暗滩教派勾结在一起。",al={"谁在这里","萨提纳尔怪物","邪心萨特"}},{q="为什么萨提纳尔比其他萨特遗迹更重要？",a="在灰谷的三大萨特据点——萨提纳尔、夜道谷和萨维亚中，萨提纳尔保存最完好且位置最居中，就在通往艾萨拉的大路旁。",al={"萨提纳尔与萨维亚","为什么选择萨提纳尔"}},{q="藏在萨提纳尔的黑暗神器是什么？",a="萨提纳尔藏有一枚属于暗滩教派的腐化灵魂宝石，这是一个与邪心萨特结盟的凡人暗影教派。",al={"暗滩灵魂宝石","萨提纳尔水晶","灵魂宝石"}}},fx={["2ba518f9"]={q="萨提纳尔危险吗？",a="对于经过灰谷东北部的旅人来说，萨提纳尔极其危险。它位于碎木岗哨与艾萨拉之间的主路旁，居住着凶残的枯心萨特，他们与暗滩教派结盟。由于位置便利且居于要冲，它是森林里争夺最激烈、防守最严密的萨特据点。擅闯者可能遭遇邪能魔法、伏击，以及围绕被腐化的灵魂宝石进行的阴险暗影仪式。",al={"萨提纳尔安全吗","萨提纳尔有多危险","萨提纳尔的威胁"}}},fp="9,298,23.645.0,18.184.0,23.158.0,59.172.0,46.144.0"}
P.entries["subzone:savage-coast"] = {n="野人海岸",s="野人海岸是北荆棘谷崎岖的西海岸线，从西部荒野的南部边界一直延伸至格罗姆高营地。这里徘徊着淡水鳄、海岸蛇颈龙以及充满敌意的巨魔部落，这片滩涂正如其名，每一次潮汐都伴随着残酷的杀戮。",h="野人海岸是北荆棘谷崎岖的西海岸线，从西部荒野的南部边界一直延伸至格罗姆高营地。这里徘徊着淡水鳄、海岸蛇颈龙以及充满敌意的巨魔部落，这片滩涂正如其名，每一次潮汐都伴随着残酷的杀戮。",kw={"蛇颈龙","淡水鳄","格罗姆高","野人海岸","荆棘谷","暗礁海","西部荒野"},ang={["class:Hunter"]="这片海岸线上拥有大量的淡水鳄和蛇颈龙，适合进行追踪、剥皮以及野兽驯服。",["faction:Horde"]="海岸的北段位于格罗姆高营地上方，作为抵御靠近无尽之海的野生动物和激进巨魔团体的外围缓冲区。"},sec={{t="危险的滩涂",b="野人海岸从与西部荒野接壤的悬崖向南一直延伸到格罗姆高营地，构成了北荆棘谷险恶的西缘。这片沙滩绝非善地：鳄鱼、淡水鳄和石 stalkers 在潮汐池和漂流木间自由游荡。稍往内陆走，便是领地意识极强的丛林巨魔营地，这使得在这片海滩上任何漫不经心的散步都成了生存之战。近海处，水域向下沉没，直逼潜伏着暗礁海危险的水域，确保了无论是沙滩上还是波浪下，处处皆是危机。"}},faq={{q="野人海岸在哪里？",a="野人海岸位于北荆棘谷的西侧大洋边缘。它始于北部的西部荒野边界，向南延伸经过暗礁海附近的水域，直达格罗姆高营地。",al={"野人海岸位置","野人海岸在哪里","野人海岸地图"}},{q="野人海岸生活着哪些生物？",a="海岸上到处是危险的野生动物，其中最常见的是在沙滩上晒太阳的极具攻击性的淡水鳄和蛇颈龙。在水线之外和附近的丛林悬崖边，敌对的巨魔部落建立了俯瞰冲浪点的营地。",al={"野人海岸怪物","野人海岸有什么","野人海岸野兽"}},{q="对于从西部荒野向南旅行的游客来说，野人海岸安全吗？",a="一点也不。虽然沿着海岸进入荆棘谷可以避开茂密的丛林树冠，但野人海岸挤满了凶猛的两栖捕食者和当地的巨魔战士，他们会迅速淹没那些不加防备的旅行者。",al={"可以从西部荒野走到荆棘谷吗","西部荒野到野人海岸的路径"}},{q="野人海岸附近有什么地标？",a="近海处是沉没的暗礁海，沿着海岸线向下走则是部落的防御据点格罗姆高营地。向北，悬崖升起，连接着西部荒野的农田和海岸。",al={"野人海岸兴趣点","野人海岸附近有什么"}}},fp="12,282,20.539.0,26.227.0,43.251.0,66.215.0,41.207.0"}
P.entries["subzone:scarab-dais"] = {n="甲虫之台",s="甲虫之台是一座位于希利苏斯南部、甲虫之墙西北方的古老高台。这里安放着传说中的甲虫之锣，这种仪式器具直接与封印安其拉其拉虫人帝国的魔法结界相连。",h="甲虫之台是一座位于希利苏斯南部、甲虫之墙西北方的古老高台。这里安放着传说中的甲虫之锣，这种仪式器具直接与封印安其拉其拉虫人帝国的魔法结界相连。",kw={"安其拉","乔纳森·启示者","甲虫之台","甲虫之锣","甲虫之墙","流沙之战","希利苏斯"},ang={["race:NightElf"]="对于卡多雷而言，甲虫之台是一段关于一千年前惨烈流沙之战的深刻记忆，在那场战争中，暗夜精灵和龙族付出了血的代价，才将其拉虫人封印在墙后。"},sec={{t="安其拉之锣",b="Overlooking the shifting sands before the colossal barrier of the Scarab Wall, the Scarab Dais serves as the focal point for the seal placed upon Ahn'Qiraj a millennium ago. Upon this stone dais rests the Scarab Gong, a relic forged during the War of the Shifting Sands. According to ancient night elven history and the bronze dragonflight, striking this gong with the reconstructed Scepter of the Shifting Sands is the only means to shatter the magical barrier and breach the gates. Until that fateful moment arrives, the platform remains an ominous vigil over the sealed insectoid horrors slumbering beyond the wall."}},faq={{q="甲虫之台是什么？",a="甲虫之台是位于希利苏斯南部的一座石制礼仪露台，坐落在甲虫之墙的西北方。它的建造是为了安放甲虫之锣，以此控制封印安其拉的魔法结界。",al={"这是什么平台","甲虫之台信息","铜锣平台"}},{q="如果有人在台上敲响铜锣会发生什么？",a="传说用修复后的流沙节杖敲响甲虫之锣，将会击碎横跨甲虫之墙的结界，解开安其拉之门，释放被囚禁在内的其拉虫人大军。",al={"铜锣有什么用","敲响甲虫之锣","敲锣"}},{q="谁在看守甲虫之台？",a="乔纳森·启示者，一位青铜龙族的人类守望者，也是甲虫之锣的看守人，他伫立在台顶，守望着铜锣和其后被封印的大门。",al={"台上有什么人","台上的青铜龙","乔纳森·启示者"}}},fp="11,242,21.618.0,24.207.0,51.220.0,33.174.0"}
P.entries["subzone:scarab-wall"] = {n="甲虫之墙",s="甲虫之墙是位于希利苏斯南境，安其拉虫人帝国前方的一道巨大壁垒。它在流沙之战末期被创造出来，这道屏障结合了岩石与青铜龙军团的魔法，用以封印古老的虫群。它耸立在那里，无声地提醒着人们那场战争惨痛的代价。",h="甲虫之墙是位于希利苏斯南境，安其拉虫人帝国前方的一道巨大壁垒。它在流沙之战末期被创造出来，这道屏障结合了岩石与青铜龙军团的魔法，用以封印古老的虫群。它耸立在那里，无声地提醒着人们那场战争惨痛的代价。",kw={"安其拉","青铜龙军团","其拉虫人","甲虫之墙","希利苏斯","流沙之战"},ang={["class:Druid"]="德鲁伊们能感受到墙体周围生命力的不自然压制，那里古老的结界正竭力遏制着一股腐蚀性的地下枯萎之力。",["race:NightElf"]="对于暗夜精灵来说，这堵墙是一座神圣的纪念碑，铭记着在流沙之战中做出的惨烈牺牲，在那场战争中，整整一代人为了阻挡虫群而陨落。"},sec={{t="对抗阴影的护盾",b="甲虫之墙横贯沙漠东西，于千年前灾难性的流沙之战结束后矗立而起。在被其拉虫人逼近毁灭边缘后，暗夜精灵军队及其巨龙盟友将虫群赶回了它们古老的王国。为了永久封印它们，一道巨大的沙漠石壁拔地而起，上方笼罩着由青铜龙军团编织的宏大魔法屏障。这堵墙成功地将虫人军队与卡利姆多隔绝开来，尽管封印在石墙后的恐怖气息依然清晰可感。"},{t="被封印的废墟",b="在砂岩石工和巨龙结界之后，便是古其拉虫人的据点——安其拉。这堵墙是在流沙之战后为囚禁其军队而建的。使用流沙节杖敲响甲虫之锣便可打开它的大门，这是一件与巨龙和范达尔·鹿盔有关的圣物。"}},faq={{q="什么是甲虫之墙？",a="甲虫之墙是一道位于希利苏斯南缘的巨大石质魔法屏障。它的建立是为了封印古老的安其拉虫人王国，并将那些贪婪的虫群困在沙漠废墟之中。",al={"甲虫之墙的目的","希利苏斯的这堵墙是什么","安其拉之墙"}},{q="谁建造了甲虫之墙？",a="它是由暗夜精灵和青铜龙军团在流沙之战达到高潮时共同创造的。一道石墙封住了其拉虫人，而巨龙们在墙上投射了一道巨大的魔法屏障。",al={"谁建造了这堵墙","谁创造了甲虫之墙"}},{q="为什么要建造甲虫之墙？",a="为了结束流沙之战。在暗夜精灵及其巨龙盟友将其拉虫群赶回安其拉后，建造了这堵墙以将它们封印在内。",al={"为什么要建造甲虫之墙","甲虫之墙的用途"}},{q="玩家可以穿过这堵墙吗？",a="甲虫之墙是为了封印安其拉而建，但使用流沙节杖敲响甲虫之锣可以打开它的大门。",al={"能穿过甲虫之墙吗","如何穿过希利苏斯的墙"}}},fp="11,329,25.580.0,13.322.1,24.223.0,26.222.0,31.176.0,29.140.0"}
P.entries["subzone:scarlet-base-camp"] = {n="血色十字军营地",s="血色十字军营地是位于东瘟疫之地米雷达尔湖东岸的一处防御前哨，就在提尔之手以西。这里的路障标志着血色十字军的一处外围防御阵地。",h="血色十字军营地是位于东瘟疫之地米雷达尔湖东岸的一处防御前哨，就在提尔之手以西。这里的路障标志着血色十字军的一处外围防御阵地。",kw={"东瘟疫之地","米雷达尔湖","血色十字军营地","血色十字军","提尔之手"},ang={["class:Paladin"]="这座营地反映了白银之手遗产的可悲堕落，他们本应是为了捍卫洛丹伦圣地而产生的正义狂热，如今却已扭曲为针对其他幸存者的激进偏执。",["race:Undead"]="这个前哨站时刻提醒着人们，这些狂热者不仅无情地猎杀无脑的天灾军团，也同样希望将亡灵从洛丹伦彻底清除。"},sec={{t="米雷达尔湖的前线",b="血色十字军营地坐落在米雷达尔湖的东岸，是一座位于提尔之手西侧的加固工事。它标志着血色十字军在这片荒芜土地上的一处外围据点。"},{t="堡垒的屏障",b="提尔之手是血色十字军在洛丹伦的据点之一。这座营地位于其西侧的进军路线上，在这片区域中，十字军试图从亡灵手中收复失地，并对外来者持怀疑态度。"}},faq={{q="血色十字军营地的目的是什么？",a="这座营地是血色十字军在米雷达尔湖东岸的一处加固工事，就在提尔之手以西。",al={"什么是血色十字军营地","为什么血色十字军营地会在这里","营地的目的"}},{q="谁在指挥驻扎在营地的部队？",a="在最初的经典版游戏中，该营地没有明确的指挥官。它只是提尔之手附近的一处血色十字军阵地。",al={"谁领导血色十字军营地","营地指挥官","血色营地领导人"}},{q="营地里的人对旅行者怀有敌意吗？",a="血色十字军对两个阵营的外来者都持有敌意，认为他们可能是瘟疫的携带者或天灾军团的代理人。",al={"血色十字军营地会攻击我吗","血色营地有敌意吗","他们是友好的吗"}},{q="营地相对于米雷达尔湖的位置在哪里？",a="它矗立在米雷达尔湖的东岸，位于提尔之手以西。",al={"血色十字军营地 湖","血色营地在哪里","提尔之手附近的营地"}}},fp="17,203,31.197.0,21.221.0,45.117.0,43.107.0,39.138.0,47.67.0"}
P.entries["subzone:scarlet-basilica"] = {n="血色十字军教堂",s="血色十字军教堂是一座宏伟的大教堂，矗立在东瘟疫之地的提尔之手中心。它作为血色十字军在东部的精神和军事权力中心。在十字军领主瓦德玛的监督下，教堂大厅象征着这些狂热者对抗天灾军团的不屈堡垒。",h="血色十字军教堂是一座宏伟的大教堂，矗立在东瘟疫之地的提尔之手中心。它作为血色十字军在东部的精神和军事权力中心。在十字军领主瓦德玛的监督下，教堂大厅象征着这些狂热者对抗天灾军团的不屈堡垒。",kw={"大教堂","十字军领主瓦德玛","东瘟疫之地","血色十字军教堂","血色十字军","提尔之手"},ang={["class:Paladin"]="这座大教堂是一座扭曲的纪念碑，见证了虔诚信仰的误入歧途，昔日的白银之手骑士们将他们的热忱变成了冷酷的狂热。",["race:Undead"]="对于被遗忘者来说，这座大教堂是那些狂热分子最坚固的据点之一，他们积极寻求彻底根除所有的亡灵，无论其是否拥有自由意志。"},sec={{t="东方十字军的核心",b="血色十字军教堂矗立在提尔之手的防御堡垒之上，是血色十字军在东瘟疫之地行动的中央大教堂和指挥中心。虽然远在西边提瑞斯法林地的血色修道院是该组织的精神核心，但这座大教堂是他们抵御洛丹伦被瘟疫侵蚀的恐怖生物、仅存的领土据点。大教堂由精锐的十字军严密守卫，十字军领主瓦德玛在此坐镇，指挥当地防御，并狂热地清洗任何胆敢靠近的外来者。"}},faq={{q="血色十字军教堂是什么？",a="血色十字军教堂是位于东瘟疫之地提尔之手要塞城市内的大教堂。它是血色十字军在该地区的主要宗教和军事权力中心。",al={"血色十字军教堂信息","这是什么教堂","提尔之手教堂"}},{q="谁领导着教堂内的军队？",a="十字军领主瓦德玛指挥着血色十字军教堂内的军队，作为血色十字军的高级领导人之一，他驻守提尔之手，对抗天灾军团和其他被视为敌人的势力。",al={"血色十字军教堂里有谁","瓦德玛","血色十字军教堂首领"}},{q="这与血色修道院相比如何？",a="虽然提瑞斯法林地的血色修道院是该组织的主要精神总部，但血色十字军教堂是他们在东部的对应机构，在瘟疫之地深处提供了一个军事化的宗教指挥中心。",al={"修道院与教堂的区别","这是血色修道院吗"}},{q="旅行者在教堂内受欢迎吗？",a="不。血色十字军已经陷入了排外的疯狂，认为任何没有身穿他们深红色制服的人都受到了亡灵瘟疫的污染。无论是联盟还是部落的入侵者，都会在看到后立即受到攻击。",al={"联盟可以进入吗","血色十字军教堂是敌对的吗","我可以访问吗"}}},fp="16,315,28.565.0,29.223.0,41.202.0,47.237.0,42.209.0"}
P.entries["subzone:scarlet-monastery"] = {n="血色修道院",s="血色修道院坐落在提瑞斯法林地的东北丘陵中，这里曾经是圣光教会进行学术研究和礼拜的和平中心。在洛丹伦陷落之后，这里已经成为狂热的血色十字军重兵把守的堡垒。任何没有身着红色制服的人在接近这里时，都会被视为携带瘟疫的感染者并被当场处决。",h="血色修道院坐落在提瑞斯法林地的东北丘陵中，这里曾经是圣光教会进行学术研究和礼拜的和平中心。在洛丹伦陷落之后，这里已经成为狂热的血色十字军重兵把守的堡垒。任何没有身着红色制服的人在接近这里时，都会被视为携带瘟疫的感染者并被...",kw={"军械库","大教堂","墓地","图书馆","莫格莱尼","旧修道院","血色十字军","血色修道院","提瑞斯法林地","怀特迈恩"},ang={["class:Paladin"]="这座建筑群曾经在白银之手麾下训练圣骑士，因此它堕落成为一个充满偏执狂热的堡垒，令忠诚的圣光战士们感到痛心。",["faction:Horde"]="修道院就坐落在幽暗城的家门口，这使得其武装严密的十字军对被遗忘者的领土构成了实质性的生存威胁。"},sec={{t="从圣所到要塞",b="在第三次战争之前，这座建筑群是洛丹伦祭司阶层引以为傲的堡垒，曾是神学研究、圣物典藏和圣骑士训练的重要中心。当洛丹伦王国陷落于天灾军团之手时，幸存的守军在这里抵抗着亡灵的入侵。随着他们堕落为狂热的血色十字军，他们加固了修道院，将其宁静的图书馆、花园和教堂变成了一座武装堡垒。"},{t="狂热的堡垒",b="修道院分为四个不同的区域——亵渎的墓地、广阔的图书馆、军械库以及宏伟的大教堂。这里驻扎着由血色十字军指挥官莫格莱尼和大检察官怀特迈恩领导的庞大守军。这里的十字军将所有外来者，无论生者还是亡灵，联盟还是部落，都视为瘟疫携带者。虽然被遗忘者试图消除这支威胁到他们家门口的守军，但联盟领导层也越来越将十字军的暴力极端主义视为对圣光的一种危险扭曲。"}},faq={{q="为什么血色修道院会在这里？",a="它最初是在洛丹伦统治时期建造的，作为一个供人学习的宁静圣所，用于存放神圣的经文和训练圣骑士。在王国陷落后，幸存的十字军占领并加固了这里，将其作为在提瑞斯法林地对抗亡灵的军事集结地。",al={"什么是血色修道院","为什么在提瑞斯法建造修道院","修道院的用途"}},{q="为什么血色十字军会攻击联盟成员？",a="十字军的狂热已经演变成彻底的偏执。他们认为任何在他们严密防守的营地之外旅行过的人都可能是天灾瘟疫的携带者，因此他们拒绝在对待外来者时抱有侥幸心理，无论对方的种族或效忠对象为何。",al={"为什么血色十字军敌视联盟","血色十字军属于联盟吗","为什么十字军攻击人类"}},{q="谁在领导修道院内的部队？",a="修道院的守军由血色十字军指挥官莫格莱尼和血色十字军指挥官莫格莱尼共同领导，前者在大教堂内指挥军事行动，后者是一位以虔诚和复活能力而闻名的狂热女祭司。",al={"谁是血色修道院的首领","修道院领导者","谁在这里领导血色十字军"}},{q="这座建筑群的四个区域分别是什么？",a="该建筑群被分为四个不同的区域：墓地，那里充斥着躁动的亡灵和刑讯室；图书馆，保存着历史档案和书籍；军械库，十字军在此制造武器和盔甲；以及大教堂，那是精神核心和指挥官的驻地。",al={"修道院分区","血色修道院有哪些区域","修道院布局"}}},fx={b123b1b5={q="血色修道院是什么地方？",a="血色修道院坐落在提瑞斯法林地东北部的丘陵中，曾是洛丹伦牧师团的一座宁静大教堂和学术中心。第三次战争后，王国遭到毁灭，血色十字军夺取了这座古老圣地，并将其改造成戒备森严的据点。这里的大厅曾用于启迪教义、训练圣骑士，如今却回荡着狂热的声音。",al={"血色修道院是什么地方","血色修道院的背景","介绍一下血色修道院"}},["5fcbefd1"]={q="血色修道院发生了什么？",a="修道院曾是洛丹伦牧师团引以为傲的堡垒，是传播知识与启迪教义的中心，也负责训练圣骑士。第三次战争期间，天灾军团席卷洛丹伦，血色十字军的幸存狂热者夺取了这座建筑群，将宁静的圣地改造成了武装堡垒。",al={"血色修道院的历史","这里发生了什么","修道院的过往"}},["73cac1e2"]={q="血色修道院危险吗？",a="那里极其危险。数百名全副武装的狂热十字军驻守在修道院中，他们将任何外来者都视为可能携带亡灵瘟疫的人。无论你属于部落还是联盟，他们接到的命令都是毫不留情地处决来者。除了这些作战人员，内层圣所还由高级审讯官把守，他们拥有神圣力量，能够让倒下的人复活并重返战斗。",al={"血色修道院危险吗","修道院有多危险","可以安全进入吗"}},a14a0fc8={q="为什么叫血色修道院？",a="这个名字源自它的主人。天灾军团席卷洛丹伦时，激进的血色十字军夺取了修道院，并将其加固为自己的据点。如今，这里便以他们的赤色教团命名。",al={"血色修道院为何得名","血色修道院名称的由来","这个名字从何而来"}}},fp="17,382,28.432.0,23.524.0,34.281.0,53.264.0,42.212.0,39.286.0"}
P.entries["subzone:scarlet-monastery-armory"] = {n="Scarlet Monastery Armory",s="武器库是血色修道院的军事强化侧翼，专门用于为血色十字军制造武器和训练新兵。在锁住的铁门后，成群狂热的步兵和十字军在血色冠军赫洛德的严厉指挥下进行演练。",h="武器库是血色修道院的军事强化侧翼，专门用于为血色十字军制造武器和训练新兵。在锁住的铁门后，成群狂热的步兵和十字军在血色冠军赫洛德的严厉指挥下进行演练。",kw={"武器库","crusader's armory","步兵武器库","hall of champions","赫洛德","血色冠军","血色十字军钥匙","scarlet monastery armory"},ang={["class:Warrior"]="武器库是冷兵器格斗的典型试验场，血色战士们在这里演示致命的架势、缴械技巧以及赫洛德那著名的旋风斩技术。",["faction:Horde"]="随着血色十字军在幽暗城大门外集结军队，掠夺他们的军械并屠杀他们的冠军对于被遗忘者的生存至关重要。"},sec={{t="狂热铸造厂",b="修道院曾经是洛丹伦牧师们的一处静修之地，但在第三次战争后被彻底改造。武器库现在作为十字军的主要锻造厂、武器仓库和战斗试验场。从露天训练场到深处的武器大厅，成群的血色步兵、法师和十字军不断进行演练，准备肃清天灾军团以及任何他们认为被玷污的人。该侧翼与Grand Vestibule之间保持封闭，只有携带在邻近图书馆中发现的血色十字军钥匙的人才能进入。"},{t="Hall of Champions",b="武器库中心坐落着Hall of Champions，两旁矗立着纪念十字军历史上传奇英雄的高大雕像。该大厅由赫洛德负责监管，他是一位残暴的战士，以其凶猛和旋风斩在十字军中闻名。赫洛德亲自训练下一代狂热者；当战斗陷入苦战时，他那些绝望的新兵会涌入大厅，为他们的冠军而战并献出生命。"}},faq={{q="如何进入武器库？",a="Grand Vestibule里的武器库大门紧锁。要打开它，你必须进入图书馆侧翼，从Athenaeum奥法师杜安身后的箱子里取回血色十字军钥匙，或者带上一位开锁技能足够高的潜行者。",al={"武器库上锁","如何解锁武器库","武器库血色十字军钥匙","打开武器库大门"}},{q="谁在武器库中统领部队？",a="该侧翼由被称为血色冠军的赫洛德指挥。他驻守在Hall of Champions内，负责操练士兵并让新加入的征召兵接受高强度的战斗考验。",al={"武器库首领","谁负责武器库","谁管理武器库","赫洛德武器库"}},{q="这个侧翼对血色十字军有什么用途？",a="它作为十字军的主要军械库和训练学院。建筑群内设有大型武器锻造厂、步兵和十字军的装备库，以及用于在将士兵派往提瑞斯法和瘟疫之地前进行体能训练的户外操练场。",al={"武器库存在目的","他们在这里做什么","武器库用途"}},{q="Hall of Champions里纪念的是谁的雕像？",a="这些雕像纪念的是该组织最受推崇的殉道者和英雄，在训练新兵进行反抗亡灵的战争时，十字军们常会引用这些冠军的事迹。",al={"武器库雕像","hall of champions雕像","赫洛德房间里的雕像"}}},fx={["469efc8f"]={q="什么是Scarlet Monastery Armory？",a="武器库是位于提瑞斯法林地的血色修道院建筑群内一处戒备森严的区域。这里曾是洛丹伦牧师团用于虔诚崇拜和研习圣光的场所，如今则成为血色十字军激进战士的训练营房、武器库和集结地。",al={"什么是武器库","血色修道院武器库背景","武器库介绍"}},cd55d42c={q="武器库发生了什么？",a="第三次战争期间，天灾军团蹂躏了洛丹伦，席卷这片地区，将这座宁静的学府变成了孤注一掷的堡垒。幸存的神职人员和士兵逐渐激进化，组建了血色十字军。他们武装自己，将此地筑成坚不可摧的堡垒，誓要消灭任何他们怀疑染上瘟疫的人。",al={"武器库历史","武器库发生了什么","血色修道院武器库背景"}},edfdc72e={q="武器库危险吗？",a="这里极其危险。大厅里挤满了狂热的十字军士兵、步兵和受过见人便杀训练的战斗法师。十字军认为所有外来者都可能是天灾瘟疫的携带者，因此任何闯入训练场或大厅的人，都会遭遇纪律严明、战斗到底的士兵。",al={"武器库有多危险","武器库安全吗","武器库威胁"}}},fp="24,276,19.544.0,21.418.0,33.236.0,35.179.0,57.256.0,51.169.0"}
P.entries["subzone:scarlet-monastery-cathedral"] = {n="Scarlet Monastery Cathedral",s="大教堂是血色修道院的精神与军事核心，也是血色十字军的圣所所在。这里曾经是洛丹伦祭司们宁静的礼拜殿堂，如今却成了大检察官怀特迈恩和血色十字军指挥官莫格莱尼的指挥中心，由十字军中最虔诚的狂热者守卫。",h="大教堂是血色修道院的精神与军事核心，也是血色十字军的圣所所在。这里曾经是洛丹伦祭司们宁静的礼拜殿堂，如今却成了大检察官怀特迈恩和血色十字军指挥官莫格莱尼的指挥中心，由十字军中最虔诚的狂热者守卫。",kw={"大教堂","礼拜堂庭院","十字军大教堂","大检察官","莫格莱尼","血色修道院","怀特迈恩"},ang={["faction:Alliance"]="对联盟而言，十字军代表着对圣光和洛丹伦光荣传统的悲剧性扭曲，这促使南海镇的指挥官们派遣勇士前去终结他们的疯狂。",["faction:Horde"]="大教堂坐落于幽暗城附近，极其危险，这里聚集着致力于彻底铲除被遗忘者及其任何部落盟友的狂热者。"},sec={{t="狂热圣所",b="大教堂曾是洛丹伦祭司们启迪心智与祈祷的宁静中心，但在第三次战争之后陷入了疯狂。随着王国在天灾军团的铁蹄下沦陷，幸存的狂热者将这一建筑群改造成了一座充满不屈仇恨的堡垒。穿过修葺整齐的礼拜堂庭院，便是宏伟的十字军大教堂，祭司和战士们聚集于此，向他们的十字军事业表达忠诚。他们视所有外来者——无论其种族或阵营——为亡灵瘟疫的携带者，必须用刀剑和圣火予以净化。"},{t="大检察官与她的指挥官",b="驻扎在大教堂内的部队直接听命于血色十字军指挥官莫格莱尼，他以铁腕纪律管理着守军。然而，该据点狂热信仰的核心是大检察官怀特迈恩。作为一名强大的圣光使用者，怀特迈恩虔诚的信仰使她能在激战中复活阵亡的勇士。她与莫格莱尼共同守卫着内殿，阻挡任何胆敢闯入修道院大门的人，证明了血色十字军对北洛丹伦的控制依然坚不可摧。"}},faq={{q="大教堂的用途是什么？",a="它是血色十字军在血色修道院内的内堡和神圣的高层指挥所。在这里，该组织最高领导人主持宗教仪式，并指挥他们在整个提瑞斯法林地的军事行动。",al={"大教堂用途","为什么要参观大教堂","这是什么地方"}},{q="谁在这里领导血色十字军？",a="守军由血色十字军指挥官莫格莱尼指挥，而精神领袖则是大检察官怀特迈恩，一位令人敬畏且狂热的女祭司。",al={"这里的首领是谁","大教堂首领","怀特迈恩 莫格莱尼"}},{q="为什么大教堂的门锁着？",a="通往大教堂侧厅的沉重铁门被锁上，是为了防止入侵者冲击圣所。进入需要血色十字军钥匙，该钥匙由修道院图书馆侧厅内的守卫看管。",al={"大教堂门锁","如何进入大教堂","钥匙在哪里"}},{q="为什么十字军要攻击其他活着的凡人？",a="受天灾军团毁灭洛丹伦的影响而陷入妄想，血色十字军坚信所有外来者都是亡灵瘟疫的携带者。他们拒绝与外部阵营接触，并处决任何靠近其堡垒的人。",al={"为什么要攻击联盟","血色十字军邪恶","为什么十字军敌对"}}},fx={["9962382e"]={q="什么是Scarlet Monastery Cathedral？",a="大教堂是提瑞斯法林地血色修道院建筑群的核心，也是其中最宏伟的部分。这里曾是备受尊崇的洛丹伦牧师团圣所，致力于求知和精神启迪，如今则成为血色十字军狂热分子的至圣之所和指挥中心。",al={"什么是大教堂","血色大教堂","大教堂区域"}},d9fd8161={q="Scarlet Monastery Cathedral发生了什么？",a="第三次战争之前，这座宁静的修道院是洛丹伦圣光信仰的骄傲堡垒，致力于研习与救治。当天灾军团席卷王国时，幸存的守卫加固了这处圣地，将宁静的大厅和庭院改造成一座戒备森严的要塞，充斥着偏执与狂热的仇恨。",al={"大教堂历史","这里发生了什么","修道院往事"}},["09ab4f6a"]={q="Scarlet Monastery Cathedral危险吗？",a="这里远比修道院其他区域危险。穿过庭院，便是一座宏伟的礼拜堂，里面挤满了精锐十字军、虔诚的修士和致命的术士。守卫们怀着狂热的怒火作战，闯入者将面对指挥官莫格莱尼与强大的大检察官怀特迈恩联手出击。",al={"大教堂危险吗","这里安全吗","大教堂有多危险"}}},fp="27,313,15.561.0,37.517.1,31.224.0,35.160.0,40.190.0,52.243.0"}
P.entries["subzone:scarlet-monastery-graveyard"] = {n="Scarlet Monastery Graveyard",s="Scarlet Monastery Graveyard是位于提瑞斯法林地东北部的宏大宗教建筑群中的墓地区域。曾经是洛丹伦神职人员和贵族的宁静安息之所，如今却陷入了令人不寒而栗的荒废中，被徘徊的亡灵和骷髅血法师萨尔诺斯所腐化的魔法所占据。",h="Scarlet Monastery...",kw={"chamber of atonement","forlorn cloister","墓地苔","墓地","honor's tomb","血色修道院","萨尔诺斯"},ang={["profession:Herbalism"]="Forlorn Cloister潮湿、被玷污的土壤是北洛丹伦采集墓地苔最可靠的来源之一。",["race:Undead"]="被遗忘者的施法者和药剂师将这座墓地视为十字军虚伪的残酷证明：这群狂热分子谴责被遗忘者，而一个亡灵血法师却在他们的地下室里腐烂。"},sec={{t="一个被玷污的圣所",b="在第三次战争之前，这座修道院式墓地曾是洛丹伦神职人员宁静的安息之所。当血色十字军为了抵御亡灵而加固这座修道院时，他们狂热的警惕性却未能净化他们自己的地下墓穴。如今，这座墓地被废弃并深深地受到诅咒。徘徊的幽灵、不安的尸体和蹒跚的恐怖生物游荡在Chamber of Atonement和雾气缭绕的Forlorn Cloister中。死者在这里没有得到神圣的安息，却在十字军漠不关心的注视下遭受着无尽的折磨。"},{t="内部的腐化",b="在墓地后方矗立着Honor's Tomb，那里滋生着对十字军教条最大的嘲弄：血法师萨尔诺斯。没有任何记录说明他生前是谁，但他死于亡灵瘟疫，并作为施展暗影箭和火焰魔法的骷髅怪物复活。上面的十字军宣扬要彻底根除亡灵瘟疫，却在他们自己神圣的土地上包庇着一个腐烂堕落的施法者。"}},faq={{q="为什么血色十字军的据点里会有亡灵？",a="十字军的领导层沉迷于狂热之中，指挥着他们的十字军向外杀戮活着的局外人，并在提瑞斯法进行战争。因此，修道院的地下墓穴和墓葬区被彻底忽视，这使得残留的瘟疫和死去的教士们不安的灵魂得以在无人阻挡的情况下复活。",al={"为什么血色修道院墓地有亡灵","血色修道院里的亡灵","为什么这里有鬼魂"}},{q="血法师萨尔诺斯是谁？",a="关于萨尔诺斯生前是谁并无记载。亡灵瘟疫夺走了他的生命，他作为一名骷髅施法者复活，现在统治着Honor's Tomb那被亵渎的地下墓穴。",al={"萨尔诺斯背景故事","血法师萨尔诺斯是谁","墓地首领"}},{q="墓地区域位于修道院内的什么位置？",a="进入血色修道院的Grand Vestibule后，墓地的入口是最左侧的副本传送门。与军械库和大教堂区域不同，进入它不需要钥匙。",al={"血色修道院墓地在哪里","如何找到墓地区域","哪扇门是墓地"}},{q="什么是Forlorn Cloister？",a="Forlorn Cloister是位于入口墓穴和Honor's Tomb之间的露天花园和墓地。那里散落着墓碑，游荡着食尸鬼，泥土中长满了墓地苔。",al={"forlorn cloister","墓地庭院"}}},fx={["2ee90fec"]={q="什么是Scarlet Monastery Graveyard？",a="这里是血色修道院建筑群最左侧的区域，位于提瑞斯法林地东北部。它曾是洛丹伦圣职团的墓地和地下墓穴，如今已腐化、荒废，遍布墓穴、陵墓和不得安息的亡者。",al={"什么是墓园","墓园区域","血色墓园"}},d7efe218={q="Scarlet Monastery Graveyard发生了什么？",a="这里原本是洛丹伦受尊崇的牧师和勇士安息的宁静之地。修道院为抵御天灾军团而加固后，墓园便落入血色十字军控制之下。埋葬于此的尸体非但没有安息，反而开始化为亡灵复起，十字军只得将这片受污染的墓地封锁起来。",al={"墓园历史","这里发生了什么","墓园的由来"}},["35b34413"]={q="谁控制着Scarlet Monastery Graveyard？",a="虽然十字军声称控制着整座修道院建筑群，但墓园区域大多已被遗弃，任由躁动的亡灵盘踞。堕落的法师萨尔诺斯如今化作嗜血的骷髅施法者，盘踞在最深处的墓穴中，统领着散布各处的食尸鬼、鬼魂和游荡的亡者。",al={"谁管理墓园","这里由谁负责","墓园首领"}},c4dc5010={q="为什么Scarlet Monastery Graveyard荒废破败？",a="十字军狂热的圣光之力也无法阻止天灾瘟疫亵渎他们的亡者。他们无法彻底净化复起的尸体，活着的十字军只好撤回戒备森严的礼拜堂和武器库，任由墓地杂草丛生，被复生的尸体占据。",al={"墓园为何破败","为何被遗弃","为何荒废"}},["2daa3a11"]={q="Scarlet Monastery Graveyard危险吗？",a="是的。这里的组织程度不及占据修道院其他区域的武装力量，但墓园中满是凶猛的亡灵、恶毒的灵体和黑暗施法者，例如血法师萨尔诺斯。他们会无情地攻击任何擅闯墓地的活人。",al={"墓园危险吗","墓园中的危险","墓园有多危险"}},cfbfb429={q="为什么叫Scarlet Monastery Graveyard？",a="这里是血色修道院专用的墓地和陵园，其中有古老的地下墓穴、荣誉之墓一类的陵墓，以及Forlorn Cloister——洛丹伦的圣职守卫传统上安葬于此。",al={"为何叫墓园","墓园名称","为何叫血色修道院墓园"}}},fp="27,303,19.531.0,22.412.0,57.314.0,25.166.0,57.190.0,29.185.0"}
P.entries["subzone:scarlet-monastery-library"] = {n="Scarlet Monastery Library",s="图书馆是提瑞斯法林地血色修道院的东翼，曾经致力于神圣学术和洛丹伦的牧师事业。如今这里由战犬和狂热者守卫，收藏着珍贵的古籍和文献，令两个阵营的学者和法师垂涎不已。",h="图书馆是提瑞斯法林地血色修道院的东翼，曾经致力于神圣学术和洛丹伦的牧师事业。如今这里由战犬和狂热者守卫，收藏着珍贵的古籍和文献，令两个阵营的学者和法师垂涎不已。",kw={"奥法师杜安","雅典娜神殿","堕落者纲要","驯犬者洛克希","图书馆","血色十字军钥匙","血色修道院","提瑞斯法林地"},ang={["class:Mage"]="雅典娜神殿是那些寻求远古能量仪祭并希望通过挑战奥法师杜安的毁灭性奥术来磨练自身能力的雄心勃勃的法师们必须朝圣之地。",["faction:Alliance"]="图书馆保存着洛丹伦阵亡英雄的神圣记录和泰坦历史，这些都是铁炉堡的Hall of Explorers迫切希望从十字军手中夺回的资料。"},sec={{t="洛丹伦档案馆",b="第三次战争前，这座修道院是洛丹伦牧师学习和启迪的中心。东侧的回廊中收藏着浩如烟海的宗教思想、历史记录和奥术论著。当血色十字军为了防御天灾军团而加固修道院时，他们保留了这些藏书库，并将安静的厅堂变成了一座武装堡垒。如今，驯兽师带着追踪犬在庭院中巡逻，战斗法师在书架间往来，守卫着《堕落者纲要》等历史卷宗以及关于泰坦的远古研究，防范外来者。"},{t="雅典娜神殿的守卫者",b="想要闯入图书馆，必须穿过狩猎者回廊，避开驯犬者洛克希，他驯养的猎犬会嗅出试图进入内室的潜入者。在Gallery of Treasures之后便是雅典娜神殿，由奥法师杜安监管。杜安是一位强大的法师，擅长施展毁灭性的火焰和防护奥术，他隐居于此进行研究，顽强地守卫着十字军私藏的知识，抵御任何敢于深入建筑群核心的人。"}},faq={{q="图书馆位于血色修道院的什么位置？",a="当你进入提瑞斯法林地血色修道院建筑群的Grand Vestibule时，可以通过最右侧的副本入口进入图书馆区域。",al={"图书馆入口","哪扇门是图书馆","如何找到图书馆区域"}},{q="为什么冒险者会被派往图书馆？",a="联盟和部落的学者、牧师和法师都在寻找保存在其高墙内的珍贵文献。重要的目标包括《堕落者纲要》、铁炉堡历史学家寻求的泰坦传说，以及供进阶奥法师研习的远古魔法手册。",al={"为什么要前往图书馆","图书馆任务","图书馆里有什么"}},{q="谁统治着图书馆区域？",a="图书馆的内圣所，即雅典娜神殿，由血色十字军强大的施法者奥法师杜安统领。外庭院则由驯犬者洛克希和他的凶猛追踪兽负责守卫。",al={"图书馆首领","谁在管理图书馆","谁领导图书馆"}},{q="这里能找到什么血色十字军钥匙？",a="奥法师杜安的雅典娜神殿中的一个锁盒里装着血色十字军钥匙，这是打开沉重的铁门，进入修道院军械库和教堂区域所必需的。",al={"杜安钥匙","血色十字军钥匙掉落","血色十字军钥匙在哪里"}}},fx={["10860e43"]={q="什么是Scarlet Monastery Library？",a="图书馆是提瑞斯法林地血色修道院广阔建筑群最右侧的区域。这里曾是洛丹伦安静的研习和神职启蒙中心，如今则收藏着血色十字军搜集的典籍、军事珍宝，并设有猎犬犬舍。此区域分为猎手回廊、Gallery of Treasures和雅典娜神殿。",al={"什么是图书馆","血色图书馆区域","修道院图书馆概况"}},["05144c18"]={q="Scarlet Monastery Library发生了什么？",a="图书馆原本是洛丹伦牧师团引以为傲的堡垒之一，致力于求知、神学研究和启迪。第三次战争期间，亡灵天灾军团席卷王国，幸存的人类狂热分子加固了整座建筑群。他们将原本宁静、收藏书籍与圣洁知识的场所，改造成血色十字军的武装据点。",al={"血色修道院图书馆历史","图书馆往事","这里发生了什么"}},a62144f3={q="Scarlet Monastery Library危险吗？",a="这里极其危险。图书馆由狂热的血色士兵、牧师和战斗法师驻守，他们视所有外来者为必须当场铲除的天灾瘟疫携带者。闯入者必须先击败驯犬者洛克希指挥的受训攻击猎犬，之后还要面对内侧雅典娜神殿中奥法师杜安施展的致命法术。",al={"血色修道院图书馆危险吗","图书馆中的威胁","图书馆有多危险"}}},fp="25,282,21.587.0,26.457.0,50.155.0,40.258.0,27.198.0,35.175.0"}
P.entries["subzone:scarlet-raven-tavern"] = {n="Scarlet Raven Tavern",s="Scarlet Raven Tavern是夜色镇的社交中心和主要旅店，在暮色森林的阴霾中提供了一处炉火边的避难所。旅店老板斯密茨坐镇于此，这里也是饱受困扰的当地人、过往的冒险者以及试图逃离城镇周边恐怖威胁的惊恐旅人们的聚集地。",h="Scarlet Raven...",kw={"夜色镇","暮色森林","黑蟹蛋糕","哈加德","基特斯","scarlet raven","斯密茨","旅店老板斯密茨"},ang={["faction:Alliance"]="对于穿越南部边界的联盟旅行者来说，Scarlet Raven提供了在艾尔文森林和逆风小径之间为数不多的安全炉火和休息站之一。",["profession:Cooking"]="旅店的菜单上提供诸如黑蟹蛋糕之类的当地美食，这是一种当地主食，即使是像基特斯这样躲在墓地里的绝望流浪者也对其垂涎三尺。"},sec={{t="昏暗的避难所",b="Scarlet Raven Tavern位于夜色镇的中心附近，当永恒的暮色笼罩着周围的森林时，旅店依然点燃着炉火。多年前，这里曾是一个热闹的歇脚点，哈加德元帅和暴风城卫兵在巡逻后会在这里共饮。如今，随着城镇治安的恶化，生意也日渐萧条。旅店老板斯密茨为一群在寒冷与恐惧中蜷缩的阴郁、焦虑的顾客提供服务。即便如此，这家旅店仍然是搜集传闻不可或缺的交汇点，也是那些试图寻找困扰该地区的黑暗现象真相的旅人们的出发点。"},{t="秘密与被窃取的麦酒",b="除了作为避难所，这家旅店还隐藏着几起谜案的线索。隐居的流浪者基特斯曾在这里租住多日，他每天夜里疯狂地在日记中记录，随后在恐怖的黑暗骑士到达前逃离了城镇。旅店屋檐下保存的数十年前的城镇八卦和客房记录，也指向了斯塔文·密斯特曼托等早已被遗忘的人物，这使得斯密茨的酒吧成为了好奇的调查者在追寻暮色森林那些不安的亡者历史时的首选之地。"}},faq={{q="谁经营着Scarlet Raven Tavern？",a="旅店老板斯密茨是这家旅店的经营者。此外，旅店还有其他工作人员为夜色镇的旅客服务。",al={"夜色镇旅店老板","谁拥有scarlet raven","旅店老板斯密茨"}},{q="为什么旅店的氛围如此阴郁？",a="笼罩在暮色森林上的诅咒阻塞了贸易路线，令当地人感到恐惧。由于亡灵、野性狼人以及阴影骑士在林间游荡，顾客多是惊恐的镇民和绝望的佣兵，而非无忧无虑的游客。",al={"为什么scarlet raven让人沮丧","夜色镇旅店氛围"}},{q="基特斯住在Scarlet Raven吗？",a="基特斯确实住在旅店，他在逃离城镇前曾在日记中疯狂书写。通过对暮色森林的调查，可以揭开他这样做的原因。",al={"基特斯的房间","基特斯的旅店","基特斯住在这里吗"}},{q="这家旅店与斯塔文传说有什么联系？",a="旅店内存放的老主顾和往昔城镇记录包含了关于斯塔文·密斯特曼托的线索，他在陷入悲剧并声名狼藉之前，曾频繁出入于此。",al={"斯塔文与旅店的联系","斯塔文·密斯特曼托夜色镇旅店"}}},fx={["81b305d7"]={q="什么是Scarlet Raven Tavern？",a="Scarlet Raven Tavern是夜色镇当地的旅店，为暮色森林饱受困扰的居民提供屋檐、温暖的壁炉和冰凉的饮品。在阴影蔓延、恐怖横行的地区，它仍是镇民、疲惫的旅客和四处游历的冒险者聚集的主要场所，人们在此交换传闻或歇歇脚。",al={"什么是scarlet raven tavern","夜色镇的scarlet raven","夜色镇旅店"}},["27f7fada"]={q="Scarlet Raven Tavern危险吗？",a="在其围墙之内，Scarlet Raven是暮色森林仅存的几处安全避难所之一。夜色镇守夜人近在咫尺，加上夜色镇本身的庇护，旅店能将林中的恐怖挡在门外，尽管店里的客人仍忧心忡忡、时刻警惕。",al={"scarlet raven危险吗","夜色镇旅店安全吗","scarlet raven安全吗"}}},fp="20,330,12.576.0,24.516.1,34.117.0,41.266.0,38.153.0,63.184.0"}
P.entries["subzone:scarlet-watch-post"] = {n="血色十字军哨岗",s="血色十字军哨岗是一座位于提瑞斯法林地东北部岩石丘陵中的孤立瞭望塔，位于血色修道院的正北方。它由一支警惕的十字军卫戍部队驻守，其唯一目的就是保卫修道院脆弱的北翼，防止侧翼攻击。",h="血色十字军哨岗是一座位于提瑞斯法林地东北部岩石丘陵中的孤立瞭望塔，位于血色修道院的正北方。它由一支警惕的十字军卫戍部队驻守，其唯一目的就是保卫修道院脆弱的北翼，防止侧翼攻击。",kw={"melrache队长","十字军前哨","血色十字军","血色修道院","血色十字军哨岗","提瑞斯法林地"},ang={["faction:Horde"]="十字军将所有外来者——无论生死——都视为被亡灵瘟疫污染的携带者，因此对于任何冒险进入这些丘陵的部落旅行者来说，这个哨岗是绝对的敌对区域。",["race:Undead"]="对于被遗忘者来说，血色十字军是一个盘踞在幽暗城家门口的生存威胁；清除像这样的孤立塔楼可以破坏这些狂热分子的通讯网络，并确保提瑞斯法北部的安全。"},sec={{t="守卫北部通道",b="血色十字军哨岗矗立在血色修道院后方的崎岖高地上，是修道院狂热者们关键的早期预警堡垒。虽然通往修道院大门的南部道路交通繁忙且防御严密，但提瑞斯法北海岸线沿途崎岖的悬崖却为潜入者提供了一条诱人的后路。为了消除这一盲点，血色十字军维护着这座坚固的石塔——这是散布在提瑞斯法林地的数个十字军前哨站之一。在Melrache队长的严厉指挥下，由新兵、先锋和虔诚的修士组成的混合部队在悬崖上日夜守望，确保天灾军团和被遗忘者无法从后方突袭该组织。"}},faq={{q="血色十字军哨岗的目的是什么？",a="该哨岗保护血色修道院免受侧翼攻击。虽然修道院的正门朝向南方的提瑞斯法道路，但其后方斜坡朝向北部荒野，使其容易受到协调一致的攻击。这座哨岗确保了哨兵能够发现并拦截任何试图从北部绕行的入侵者。",al={"为什么血色十字军哨岗会在这里","血色十字军哨岗的目的","十字军的角色"}},{q="谁在指挥血色十字军哨岗？",a="Melrache队长负责监管驻扎在塔楼的卫戍部队。他指挥着一支防御性随从队伍，包括私人保镖、前线先锋、有抱负的新兵以及施法的修士。",al={"血色十字军哨岗的领袖","谁领导血色十字军哨岗","melrache队长"}},{q="血色十字军哨岗与提瑞斯法的其他塔楼有关系吗？",a="是的。它是环绕提瑞斯法林地北部和西部区域的四个独立的十字军前哨站之一。这些石塔构成了一道防御周界，用于监视天灾军团的活动并遏制被遗忘者从幽暗城扩张。",al={"提瑞斯法塔楼","提瑞斯法的十字军前哨站","其他血色十字军塔楼"}}},fx={["24ad1453"]={q="什么是血色十字军哨岗？",a="血色十字军哨岗是一座孤立的瞭望塔，驻守在提瑞斯法林地东北部崎岖的山丘上，就在血色修道院以北。它是一处设防的侦察哨站，负责守卫通往十字军强大堡垒的脆弱北侧入口。",al={"什么是血色十字军哨岗","血色十字军哨岗背景","这座塔是什么"}},["1857b7a1"]={q="血色十字军哨岗危险吗？",a="是的，对任何外来者而言都极其危险。哨岗驻扎着狂热的血色十字军，包括修士、新兵，以及全副武装的先锋和护卫。他们发誓要当场屠杀任何闯入者，无论对方是活人还是亡灵。",al={"血色十字军哨岗危险吗","血色十字军哨岗威胁","哨岗危险吗"}}},fp="18,297,30.721.0,46.327.0,36.192.0,66.241.0"}
P.entries["subzone:scholomance"] = {n="通灵学院",s="通灵学院深藏在凯尔达隆地下的墓穴中，是天灾军团首屈一指的黑暗技艺与通灵术学院。在这里，凡人与亡灵一同在黑暗院长加丁那残酷的指导下，以及巫妖莱斯·霜语那警惕的目光注视下，学习亡灵瘟疫与血肉塑形术。",h="通灵学院深藏在凯尔达隆地下的墓穴中，是天灾军团首屈一指的黑暗技艺与通灵术学院。在这里，凡人与亡灵一同在黑暗院长加丁那残酷的指导下，以及巫妖莱斯·霜语那警惕的目光注视下，学习亡灵瘟疫与血肉塑形术。",kw={"巴罗夫","凯尔达隆","the cult of the damned","黑暗院长加丁","克尔苏加德","通灵术","莱斯·霜语","通灵学院"},ang={["class:Mage"]="通灵学院内教授的扭曲课程代表了对奥术学术的彻底扭曲，在这里，对魔法理论的探究已被腐朽、阴影和邪恶的亵渎所取代。",["race:Undead"]="被遗忘者施法者们以冷漠的熟悉感和厌恶感看待通灵学院；天灾军团最卑劣的奴役与生物战手段中，有许多就是在这些教室里完善的。"},sec={{t="毁灭契约",b="在第三次战争之前，凯尔达隆是巴罗夫家族引以为傲的宅邸，这是一个在洛丹伦拥有广袤土地的富有贵族王朝，其领地包括布瑞尔、塔伦米尔和南海镇。巴罗夫家族因害怕失去财富与生命，屈服于克尔苏加德那永恒生命的诱惑。他们将自己的堡垒与家族陵墓割让给了The Cult of the Damned，而后者随即通过屠杀这些贵族并将广阔的地下墓穴改造成隐藏的亡灵法术训练场，作为对他们的“报答”。"},{t="通灵术学校",b="在凯尔达隆那闹鬼的地表废墟之下，坐落着一个繁荣的天灾军团工业中心。在这些潮湿的大厅里，早期的瘟疫菌株曾在巴罗夫家族的仆人身上进行过测试。今天，凡人侍僧们蜂拥至此，在院长黑暗院长加丁和冰冷的哨兵莱斯·霜语的监督下磨练他们对黑暗魔法的掌控，而巴罗夫家族那不得安息的亡灵残骸仍在永恒的折磨中徘徊。"}},faq={{q="通灵学院是什么？",a="通灵学院是一所由The Cult of the Damned和天灾军团开办的秘密通灵术学院。它位于凯尔达隆岛屿堡垒的地下，是凡人通灵师、瘟疫研究员和血肉塑形师的训练设施。",al={"这里是什么地方","通灵学院背景故事","通灵学院介绍"}},{q="谁拥有凯尔达隆和这些地下墓穴？",a="这座城堡最初属于巴罗夫家族，这是洛丹伦最富有的贵族家族之一。他们为了寻求永生，将祖居之地交给了克尔苏加德，结果却在自己的大厅中被杀害并复活成了亡灵奴仆。",al={"谁拥有这里","巴罗夫家族"}},{q="现在谁在管理这所学院？",a="黑暗院长加丁担任这所学校阴险的凡人院长，负责监督教学与折磨。代表天灾军团的巫妖莱斯·霜语也在此地严密守卫。",al={"谁是首领","谁领导通灵学院","院长"}},{q="这里开发了什么恐怖的东西？",a="通灵学院是The Cult of the Damned早期的试验场。当侍僧们在大厅里学习技艺时，邪教徒们会在巴罗夫家的仆人身上测试亡灵瘟疫的各种原型变体。",al={"这里制造了什么","通灵学院的实验","憎恶"}}},fp="11,304,14.507.0,24.424.1,20.241.0,36.242.0,25.195.0,33.207.0"}
P.entries["subzone:scholomance-classic"] = {n="Scholomance (Classic)",s="通灵学院是一所隐藏在西瘟疫之地凯尔达隆地下墓穴中的地下通灵术学院。它由克尔苏加德和The Cult of the Damned建立，是天灾军团训练那些寻求掌握死亡之力的凡人施法者的首要场所。",h="通灵学院是一所隐藏在西瘟疫之地凯尔达隆地下墓穴中的地下通灵术学院。它由克尔苏加德和The Cult of the Damned建立，是天灾军团训练那些寻求掌握死亡之力的凡人施法者的首要场所。",kw={"巴罗夫","凯尔达隆","the cult of the damned","加丁","通灵术","莱斯·霜语","通灵学院"},ang={["class:Mage"]="通灵学院是对达拉然学术传统的怪诞歪曲，它展示了当肯瑞托的专业知识完全转向通灵术和腐朽时会发生什么。",["class:Paladin"]="对于白银之手骑士团的骑士们来说，净化凯尔达隆下被玷污的大厅是一项紧迫的职责，这是直接打击天灾军团凡人领导层的源头。"},sec={{t="墓穴中的学院",b="在第三次战争摧毁洛丹伦之前，叛逆的大法师克尔苏加德正为他的The Cult of the Damned招募成员。他从凯尔达隆的领主，富有的巴罗夫家族那里找到了愿意资助他的人，他们用自己的土地和墓穴换取了永生的承诺。然而，该教派不仅没有兑现承诺，反而屠杀了他们，并将他们复活为可怕的亡灵。在废墟要塞之下，该教派将古老的阿拉索地下墓穴改造成了一所黑暗艺术学院。在这里，凡人侍僧们远离人们的视线，研究瘟疫学、灵魂绑定和血肉塑形，磨练那些摧毁了洛丹伦的邪恶魔法。"},{t="巫妖与院长",b="虽然克尔苏加德已经转而在上方指挥天灾军团的行动，但这所学校依然在全面运作。永恒的巫妖莱斯·霜语以天灾军团的名义守护着这里，而凡人死灵法师黑暗院长加丁则担任院长，指导雄心勃勃的术士们进行可怕的实验。那些表现出软弱的学生会被丢弃到地下墓穴中，喂给潜伏在下层拱顶里的贪婪尸妖——拉文尼亚。"}},faq={{q="什么是通灵学院？",a="通灵学院是由The Cult of the Damned运营的一所秘密通灵术学院。它坐落在凯尔达隆岛屿要塞深处的地下墓穴中，负责培训凡人施法者掌握天灾军团的黑暗艺术。",al={"这里是什么地方","通灵学院背景故事","通灵学院介绍"}},{q="现在是谁在统治通灵学院？",a="巫妖莱斯·霜语代表天灾军团监督着这座要塞，但凡人的事务和教学工作由学校冷酷的院长黑暗院长加丁负责指挥。",al={"谁领导通灵学院","谁在负责","通灵学院首领"}},{q="天灾军团是如何得到凯尔达隆的？",a="第二次战争后，高贵的巴罗夫家族一直把守着这座要塞。在克尔苏加德永生承诺的诱惑下，他们将自己的祖居和墓穴转让给了The Cult of the Damned。该教派通过屠杀巴罗夫家族成员并将他们转化为亡灵的方式，“完成”了这笔交易。",al={"巴罗夫家族背景","凯尔达隆的主人是谁","诅咒教派如何获得通灵学院"}},{q="为什么学校大门是锁着的？",a="那扇巨大的铁门被封印起来，是为了保护学院的研究成果和召唤师免受入侵者的干扰。打开这扇门需要骷髅钥匙，这种钥匙是通过跨越整个瘟疫之地的复杂仪式锻造而成的。",al={"通灵学院大门紧锁","如何进入通灵学院","通灵学院骷髅钥匙"}}},fp="21,270,21.603.0,19.465.0,20.211.0,26.179.0,40.271.0,25.208.0"}
P.entries["subzone:screaming-gully"] = {n="Screaming Gully",s="Screaming Gully是穿过哀嚎洞穴入口后遇到的第一个广阔地下洞穴。这里沐浴在不自然的真菌微光和浅水中，作为堕落的尖牙德鲁伊及其变异野兽的外围据点。",h="Screaming Gully是穿过哀嚎洞穴入口后遇到的第一个广阔地下洞穴。这里沐浴在不自然的真菌微光和浅水中，作为堕落的尖牙德鲁伊及其变异野兽的外围据点。",kw={"贫瘠之地","变异迅猛龙","尖牙领主","克雷什","安娜科德拉","screaming gully","哀嚎洞穴"},ang={["class:Druid"]="对于塞纳里奥德鲁伊来说，Screaming Gully展现了他们堕落兄弟们令人心碎的一面，他们放弃了爪与翼的道路，拥抱了蛇形的腐化。"},sec={{t="梦魇的门槛",b="跨入哀嚎洞穴的门槛，便直接进入了Screaming Gully，这是一个回声阵阵的深渊，风在地下裂隙中哀鸣。这里与上方干旱的贫瘠之地截然不同，沟壑中充斥着潮湿的植被、潮湿的雾气，以及被翡翠梦魇扭曲的凶猛野生生物。尖牙领主安娜科德拉掌管着此洞室，周围环绕着尖牙德鲁伊的侍僧和凶残的变异迅猛龙，而像克雷什这样的古老龟类则在下方浅水中巡游。"}},faq={{q="Screaming Gully位于哪里？",a="Screaming Gully是穿过哀嚎洞穴内的传送门后进入的第一个主要洞室，位于北贫瘠之地下方。",al={"screaming gully位置","screaming gully在哪里","如何找到screaming gully"}},{q="为什么它被称为Screaming Gully？",a="哀嚎洞穴的名字来源于地下蒸汽和风穿过岩石裂隙时发出的呼啸和呻吟声，而这个宽阔的入口深渊正是这些回荡哀鸣的主要汇集处。",al={"为什么叫screaming gully","screaming gully名字由来"}},{q="谁统治着Screaming Gully？",a="该洞室由安娜科德拉掌管，她是与纳拉雷克斯一同堕入翡翠梦魇腐化的主要尖牙领主之一。",al={"screaming gully首领","screaming gully里有什么人","screaming gully领袖"}},{q="什么生物在此洞室中徘徊？",a="沟壑中栖息着变异迅猛龙、被腐化的尖牙德鲁伊以及游荡的水生生物，包括在洪水淹没的地面上漫步的古老龟类克雷什。",al={"screaming gully怪物","screaming gully里的敌人"}}},fx={edd75ba3={q="什么是Screaming Gully？",a="Screaming Gully是越过哀嚎洞穴入口后遇到的第一处广阔地下洞室。地下溪流汇入洞底，积成浅水；这道巨大的裂谷回荡着诡异的自然声响和被腐化野兽的嘶鸣，是深处逐渐滋生的噩梦最前沿。",al={"什么是screaming gully","screaming gully概况","screaming gully背景"}}},fp="15,265,26.511.0,37.165.0,37.209.0,35.145.0,33.162.0"}
P.entries["subzone:scuttle-coast"] = {n="流亡海岸",s="流亡海岸是杜隆塔尔东部遭受海浪拍打的海岸线，位于剃刀岭和提拉加德城堡之间。多岩石的海滩上散布着来自戴林·普罗德摩尔海军上将的库尔提拉斯舰队的沉船残骸，使其成为了部落积极搜寻物资的场所，也是近期海军战争挥之不去的印记。",h="流亡海岸是杜隆塔尔东部遭受海浪拍打的海岸线，位于剃刀岭和提拉加德城堡之间。多岩石的海滩上散布着来自戴林·普罗德摩尔海军上将的库尔提拉斯舰队的沉船残骸，使其成为了部落积极搜寻物资的场所，也是近期海军战争挥之不去的印记。",kw={"戴林·普罗德摩尔","杜隆塔尔","库尔提拉斯","马库拉","剃刀岭","流亡海岸","沉船","提拉加德城堡"},ang={["faction:Horde"]="散落在沙滩上的残破船体，是杜隆塔尔防御戴林·普罗德摩尔入侵海军的鲜明纪念碑。"},sec={{t="舰队残骸",b="流亡海岸沿着杜隆塔尔东部边缘延伸至无尽之海，它在戴林·普罗德摩尔海军上将领导的入侵期间获得了其严峻的特质。当库尔提拉斯舰队袭击尚在起步阶段的杜隆塔尔国家时，与部落的激烈战斗导致许多人类战舰冲向了锯齿状的浅滩，撞成了破碎的残骸。如今，海岸线上挤满了覆盖着藤壶的木材、断裂的索具和被抢救出来的货物桶。对于附近的剃刀岭营地来说，这片海岸依然是一个挥之不去的提醒，时刻告诫着人们库尔提拉斯的威胁离他们有多近。"},{t="拾荒者与潮汐",b="“流亡海岸”这个名字可能指的是在战斗中被凿沉或搁浅的战舰，也可能指的是那些在腐烂的废墟中觅食的螃蟹群和马库拉群。海岸野生生物和危险的潮汐让普通的旅行者远离这些残骸。"}},faq={{q="这些沉船都是从哪里来的？",a="这些破碎的船只属于戴林·普罗德摩尔海军上将麾下的库尔提拉斯海军舰队。在海军上将针对新建立的部落发动的失败军事行动中，它们被撞毁在杜隆塔尔多岩的浅滩上。",al={"这里为什么会有船只","沉船属于谁","杜隆塔尔沉船"}},{q="为什么它被称为流亡海岸？",a="没有人能确定。这个名字可能指的是在海战中被凿沉在沿岸的战舰，也可能指的是在岩石沙滩上横行（scuttle）的无数马库拉和螃蟹。",al={"为什么叫流亡海岸","流亡海岸名称由来"}},{q="流亡海岸旅行安全吗？",a="不安全。除了险恶的海浪和锯齿状的岩石外，像马库拉这样的敌对海岸野兽在浪花中潜行，而武装的库尔提拉斯幸存者仍然驻扎在南部的提拉加德城堡。",al={"流亡海岸的危险","流亡海岸危险吗"}}},fx={d351211f={q="流亡海岸是什么地方？",a="流亡海岸是杜隆塔尔东部多岩石的海岸线，面朝无尽之海，位于剃刀岭东南方、提拉加德城堡北方。这里是一片常年风袭的海滩和崎岖浅滩，以海难频发、水域险恶而闻名。",al={"流亡海岸是什么","流亡海岸背景","介绍流亡海岸"}}},fp="13,315,21.584.0,20.260.0,41.229.0,35.177.0,36.187.0"}
P.entries["subzone:sea-of-cinders"] = {n="灰烬之海",s="灰烬之海是一片焦灼且饱经风霜的荒原，位于灼热峡谷的南部，黑石山的北侧。这里饱受元素之火与肆虐狂风的摧残，平坦的地面不断喷涌着灰烬和余火，形成了一片几乎无法生存的窒息荒原。",h="灰烬之海是一片焦灼且饱经风霜的荒原，位于灼热峡谷的南部，黑石山的北侧。这里饱受元素之火与肆虐狂风的摧残，平坦的地面不断喷涌着灰烬和余火，形成了一片几乎无法生存的窒息荒原。",kw={"灰烬","黑石山","黑铁","余火","拉格纳罗斯","灰烬之海","灼热峡谷","荒原"},ang={["profession:Mining"]="黑石山边缘那些易变、受热开裂的岩石中经常露出丰富的矿藏和黑铁矿脉，供那些敢于在飘扬的灰烬中进行勘探的人发掘。",["race:Dwarf"]="对于铜须和蛮锤矮人来说，穿过这片燃烧的荒原，会让他们严峻地想起索瑞森的愚行，以及那些撕裂了赤脊山的黑暗力量。"},sec={{t="余火荒原",b="Stretching between the rocky cliffs of the Searing Gorge and the imposing bulk of Blackrock Mountain, the Sea of Cinders earns its name from the suffocating haze of particulate and burning grit that constantly sweeps its plains. When the Firelord Ragnaros was summoned into the mortal world centuries ago, the violent upheaval fractured the Redridge Mountains and transformed the surrounding landscape into an arid slag heap. The Sea of Cinders is among the most barren remnants of that cataclysm, an uninhabitable plain where the earth itself refuses to cool."},{t="山麓之下的危机",b="由于灰烬之海毗邻黑石山的北侧入口，旅者和拾荒者往往别无选择，只能穿过这片灼热的平原。这里的风卷起阵阵浓厚的灰烬，遮蔽了视线，掩盖了突然出现的裂隙、元素惊骇以及适应了酷热的游荡捕食者。恶劣的环境，加上占据此地的黑铁矮人带来的威胁，使得穿越灰烬之海的每一段旅程都必须保持警惕并尽快通过。"}},faq={{q="什么是灰烬之海？",a="它是一片位于灼热峡谷南部，紧贴黑石山北麓的荒凉平原，上面覆盖着厚厚的灰烬。地面上铺满了闷烧的尘土和飞舞的余火。",al={"什么是灰烬之海","灰烬之海背景故事","灰烬之海位置"}},{q="为什么地面一直在燃烧？",a="数个世纪前，在三锤之战期间，索瑞森大帝召唤了炎魔之王拉格纳罗斯，导致该地区遭受了彻底的破坏。灾难性的喷发使大地过热并震碎了山脉，留下的平原至今仍在闷烧。",al={"为什么着火","为什么会有灰烬","为什么地面会冒烟"}},{q="有人住在这里吗？",a="灰烬之海内不存在任何定居点。窒息的高温、浑浊的空气以及淡水的匮乏使永久居住变得不可能。这里只被游荡的野兽、火元素，以及隶属于黑石山的巡逻队所占据。",al={"谁住在这里","灰烬之海居民","定居点"}},{q="为什么穿越这里很危险？",a="除了潜伏在山附近的敌对生物和黑铁矮人之外，环境本身也是致命的。空气中充斥着遮天蔽日的煤烟和灼热的灰烬，平坦的地形上布满了深邃的地热裂隙。",al={"安全吗","灰烬之海的危险"}}},fp="14,313,21.560.0,24.462.0,27.182.0,37.270.0,22.272.0,44.212.0"}
P.entries["subzone:sen-jin-village"] = {n="森金村",s="森金村是杜隆塔尔南海岸的一个沿海定居点，也是暗矛巨魔的避难所。在沃金酋长带领族人被迫离开回音群岛的祖居地后，他建立了这个村庄，以此纪念他已故的父亲，巫医森金。如今，这里已成为一个专注于生存、草药学和收复失地的脆弱港湾。",h="森金村是杜隆塔尔南海岸的一个沿海定居点，也是暗矛巨魔的避难所。在沃金酋长带领族人被迫离开回音群岛的祖居地后，他建立了这个村庄，以此纪念他已故的父亲，巫医森金。如今，这里已成为一个专注于生存、草药学和收复失地的脆弱港湾。",kw={"暗矛部族","杜隆塔尔","回音群岛","森金村","森金","沃金","扎拉赞"},ang={["profession:Herbalism"]="这个村庄是天然药物的重要中心，周围遍布着当地巫医用来治疗中毒和诅咒的海岸宁神花、银叶草和地根草。",["race:Troll"]="对于从试炼谷走出的暗矛巨魔来说，这个避难所是他们流离失所的人民的中心，承载着他们对已故酋长的记忆，以及扎拉赞背叛所带来的长久痛苦。"},sec={{t="难民的海岸",b="当邪恶的巫医扎拉赞背叛了暗矛部族并夺取了回音群岛的控制权后，沃金酋长被迫带领幸存者横跨海峡，来到了杜隆塔尔的内陆。在那里，他们依托海岸悬崖，眺望着大海，搭建起简陋的茅屋，建立了森金村。这个定居点以沃金的父亲、那位在第三次战争中被鱼人俘虏并献祭的受人尊敬的长者——森金的名字命名。尽管他们与萨尔的部落结成了紧密的联盟，但这里的巨魔仍生活在流亡的阴影之下，每天隔着浅滩凝望着他们失去的家园。"},{t="注视着群岛",b="森金村的日常生活围绕着备战和防御展开。面对当地的野猪人袭击、凶猛的海兽以及从海上飘来的扎拉赞的诅咒，村民们严重依赖草药和强效的炼金药剂。当沃金在部落主城协调更大范围的部族防御时，当地的萨满、猎人和斥候聚集在这里，招募从试炼谷走出的新冒险者。他们的目标很明确：收集资源，保护杜隆塔尔的南翼，并策划最终击败叛徒扎拉赞。"}},faq={{q="暗矛部族为什么要在森金村这里定居？",a="在巫医扎拉赞发疯并控制了回音群岛的家园后，暗矛部族逃过了海峡，抵达了杜隆塔尔海岸。沃金建立了森金村，作为隔海眺望他们被窃土地的临时避难所和集结地。",al={"为什么会有森金村","为什么巨魔会在杜隆塔尔","为什么巨魔离开了回音群岛"}},{q="谁是森金？",a="森金是一位受人尊敬的巫医，也是暗矛部族的酋长，同时还是沃金的父亲。在第三次战争期间，他预见到了萨尔的到来，但在萨尔赶来营救他之前，他被南海的鱼人俘虏，并被献祭给了他们的海巫。",al={"谁是森金","森金的名字由来","森金背景故事"}},{q="为什么这里有这么多的草药师和炼金师？",a="当地的巫医和治疗师严重依赖杜隆塔尔的海岸植物和蝎毒来调制护身符、解毒剂和进行仪式。这些草药药剂维系着伤者，并提供了抵御从回音群岛飘来的黑暗诅咒的护盾。",al={"森金村训练师","森金村的专业技能","为什么这里有炼金术"}},{q="可以从森金村前往回音群岛吗？",a="回音群岛位于村庄东方，隔水相望。冒险者经常游泳或涉水穿过浅水航道，去反击扎拉赞的巫毒教徒，找回被窃的文物，或为村庄的防御者收集资源。",al={"如何前往回音群岛","森金海岸外的群岛","游向回音群岛"}}},fx={["8cd2719d"]={q="森金村是什么地方？",a="森金村是杜隆塔尔南岸的一处沿海渔村，也是暗矛巨魔在大陆上的主要避难所。部族被逐出回音群岛后，这里便建立起来。村中散布着简陋的棚屋、码头和迅猛龙圈，巨魔难民、巫医和斥候在此守望着失去的故土。",al={"森金村是什么","森金村概况","森金村背景"}},fb8d4411={q="森金村发生过什么事？",a="巫医扎拉赞背叛暗矛部族，并以黑暗巫毒控制了回音群岛。沃金于是带领幸存的巨魔渡海来到杜隆塔尔南岸。他们在那里建立了这座村庄，作为临时庇护所和军事据点，并以沃金逝去的父亲之名为村庄命名，同时谋划着夺回故土。",al={"森金村历史","森金村的历史","森金村如何建立"}},f928ac6d={q="森金村住着哪些人？",a="村中几乎全是被流放的暗矛巨魔。当地的猎手、暗影猎手、草药师和炼金师在棚屋与码头间活动，守卫海岸、收集物资，支援沃金酋长领导下的暗矛部族整体战事。",al={"森金村住着谁","谁管理森金村","森金村首领"}},["5cc89452"]={q="森金村危险吗？",a="森金村本身由森金村掷斧手和萨满严密守卫，村界之内相对安全。然而，危险就在村外：扎拉赞控制的巨魔盘踞在附近的回音群岛，周边海岸也受到凶猛野兽和来袭海洋生物的侵扰。",al={"森金村安全吗","森金村面临的威胁","森金村的危险"}}},fp="15,393,15.612.0,17.570.0,49.282.0,16.269.0,53.258.0,50.247.0"}
P.entries["subzone:sentinel-hill"] = {n="哨兵岭",s="哨兵岭是联盟在西部荒野的主要堡垒，也是人民民兵的Command Center。这里被荒废的田野、拾荒的豺狼人和敌对的暴徒所包围，这座坚固的高地是该地区守法公民唯一的安全立足点。",h="哨兵岭是联盟在西部荒野的主要堡垒，也是人民民兵的Command Center。这里被荒废的田野、拾荒的豺狼人和敌对的暴徒所包围，这座坚固的高地是该地区守法公民唯一的安全立足点。",kw={"格里安·斯托曼","gryphon roost","人民民兵","河爪豺狼人","哨兵岭","sentinel tower","西部荒野"},ang={["faction:Alliance"]="哨兵岭是你在西部荒野唯一的防御哨站和补给中心，维系着联盟在此地对抗法外之徒和劫掠者的存在。",["race:Human"]="看到西部荒野的农夫被迫在此组建自己的民兵，反映出王国在王位空缺期间日益加深的危机。"},sec={{t="沙尘中的堡垒",b="哨兵岭坐落在西部荒野中央的高地上，是这片无法之地的关键避难所。这里设有兵营风格的旅店、连接旅客往返暴风城及更远地区的Gryphon Roost、铁匠铺和伐木场，所有设施都以巍峨的Sentinel Tower为核心。虽然周边的土地已经沦为强盗和贪婪野兽的乐园，但这个营地维持着脆弱的防线，让旅客、受困的农夫和新兵可以在老兵的注视下重新集结。"},{t="民兵之心",b="由于皇家军队被困在暴风城，无法抽调士兵保护边远领土，格里安·斯托曼便在这座山上建立了人民民兵。以此为据点，志愿者战士们组织侦察，协调针对河爪豺狼人的打击行动，并调查那些在西部荒野废弃农场中肆虐的有组织劫匪。哨兵岭既不是豪华的堡垒，也不是舒适的避难所，而是一个致力于收复王国昔日粮仓的前线作战营地。"}},faq={{q="为什么暴风城没有派兵保卫哨兵岭？",a="由于瓦里安·乌瑞恩国王下落不明，且王国各地的资源捉襟见肘，暴风城的摄政当局很大程度上放弃了西部各省，任其自生自灭。当地公民和退伍军人不得不自发组成人民民兵来坚守哨兵岭，保护西部荒野残存的一切。",al={"为什么没有暴风城卫兵","暴风城军队在哪里","为什么这里有民兵"}},{q="谁负责哨兵岭？",a="格里安·斯托曼在Sentinel Tower的基座指挥着人民民兵。他负责协调当地防御，收集周边威胁的情报，并引导到访的冒险者对抗侵扰定居点的豺狼人和强盗。",al={"谁领导哨兵岭","哨兵岭指挥官","格里安·斯托曼"}},{q="哪些威胁正在危及哨兵岭？",a="该营地面临着来自在西部平原游荡的侵略性河爪豺狼人的持续压力，以及潜伏在废弃农场各处的迪菲亚潜行者所进行的阴险且有组织的破坏活动。",al={"什么在攻击哨兵岭","哨兵岭的敌人","谁在进攻"}},{q="这里为旅客提供哪些服务？",a="哨兵岭提供全套的前沿补给设施：一名提供前往暴风城及其他联盟哨站旅行服务的狮鹫管理员、一名旅店老板、一个邮箱、商业补给商贩，以及当地铁匠铺周边的修理设施。",al={"哨兵岭的设施","哨兵岭的飞行点","这里有旅店吗"}}},fx={["3c1a5a7a"]={q="哨兵岭是什么地方？",a="哨兵岭是西部荒野的联盟中央哨站。这里以一座醒目的瞭望塔为中心修建，可俯瞰整片平原，也是人民军的行动总部。山岭周围有不法之徒和豺狼人步步逼近；这里有飞行点、旅店、熔炉和必需品，难得地为疲惫的旅人提供了一处安全据点。",al={"哨兵岭是什么","关于哨兵岭","西部荒野哨兵岭"}},fc9f9bfd={q="哨兵岭危险吗？",a="在瞭望塔和旅店附近的区域内，守卫会保护你免受伤害。然而，周围的山坡和平原极其危险。河爪豺狼人常在道路附近出没，失控的收割傀儡在附近的田地间游荡，迪菲亚强盗则在哨站边界外积极巡逻。",al={"哨兵岭安全吗","哨兵岭的危险","哨兵岭的安全情况"}}},fp="13,276,21.516.0,20.514.0,59.292.0,34.253.0,40.211.0,47.234.0"}
P.entries["subzone:sentinel-tower"] = {n="Sentinel Tower",s="Sentinel Tower矗立在哨兵岭的顶峰，是西部荒野守军的主要瞭望点和指挥部。站在高塔之上，格里安·斯托曼和人民民兵组织起绝望的防线，抵御强盗、豺狼人和日益壮大的迪菲亚潜行者的威胁。",h="Sentinel Tower矗立在哨兵岭的顶峰，是西部荒野守军的主要瞭望点和指挥部。站在高塔之上，格里安·斯托曼和人民民兵组织起绝望的防线，抵御强盗、豺狼人和日益壮大的迪菲亚潜行者的威胁。",kw={"迪菲亚潜行者","格里安·斯托曼","人民民兵","哨兵岭","sentinel tower","瞭望塔","西部荒野"},ang={["faction:Alliance"]="Sentinel Tower代表了普通的联盟子民在暴风城的高层视而不见时，为保卫家园而展现出的坚韧。",["race:Human"]="对于王国的平民来说，这座塔是一个令人痛苦的提醒：暴风城的农业粮仓在本土叛乱的冲击下已岌岌可危。"},sec={{t="守护西部荒野",b="Sentinel Tower建在哨兵岭的山脊上，是动荡的西部荒野的军事心脏。由于暴风城的正规军大多缺席且拒绝提供援助，当地的志愿者和老兵联合起来，建立了一个中央堡垒。这座石塔让瞭望员能够俯瞰尘土飞扬的平原，从废弃的南瓜田到雾气弥漫的海岸，都能尽收眼底，从而在流寇或豺狼人突袭队开始出没时发出预警。"},{t="民兵指挥部",b="这座塔是格里安·斯托曼及其核心领导团队的指挥所。塔周围环绕着临时防御工事、受伤的难民和疲惫的士兵，它既是一个行政中心，也是为被赶出家园的农户提供的紧急避难所。在这里，有关迪菲亚潜行者的情报被汇总，民兵被组织起来，对这个让该省陷入废墟的组织进行协同打击。"}},faq={{q="谁在负责Sentinel Tower？",a="格里安·斯托曼在塔内指挥行动。作为人民民兵的领袖，他负责协调西部荒野流离失所的农民的防御工作，并招募愿意帮忙的冒险者。",al={"sentinel tower领袖","谁领导sentinel tower","谁管理这座塔"}},{q="为什么这座塔对西部荒野如此重要？",a="它是中原地区仅存的防御工事和瞭望哨。由于暴风城基本放弃了对西部荒野的防守，这座塔成为了该地区难民最后的秩序与安全堡垒。",al={"sentinel tower为何重要","sentinel tower的用途"}},{q="谁住在塔内及其周围？",a="你会发现民兵军官、守望的哨兵、军需官，以及那些因为家园被毁而逃难至此，寻求在坚固石墙旁避难的农户家庭。",al={"sentinel tower里的人","sentinel tower的住户"}},{q="塔上监视着哪些威胁？",a="哨兵们时刻监视着河爪豺狼人的动向、从海岸爬向内陆的鱼人，以及最主要的威胁——迪菲亚潜行者的流浪强盗和匪徒。",al={"sentinel tower的敌人","塔防守的目标"}}},fx={["226a51b2"]={q="Sentinel Tower是什么地方？",a="Sentinel Tower是一座醒目的斥候塔，矗立在西部荒野中央的哨兵岭顶端。它是人民军坚固的据点和指挥中心，格里安·斯托曼与他的斥候可以借此俯瞰草海平原，并监视整个地区的敌方动向。",al={"sentinel tower是什么","西部荒野的sentinel tower","关于sentinel tower"}},["7792f636"]={q="Sentinel Tower发生过什么事？",a="Sentinel Tower最初是一座瞭望塔，用来保护西部荒野的农户。暴风城撤走驻军后，它便成为主要防御据点。流离失所的农民和难民多次在人民军的庇护下，进入塔中避难。",al={"sentinel tower的历史","sentinel tower发生过什么"}},["3b2e4075"]={q="Sentinel Tower危险吗？",a="对于联盟旅人来说，塔内很安全，这里是人民军守卫森严的核心据点。然而，周围的山丘危机四伏，不断遭到迪菲亚强盗、敌对的河爪豺狼人和游荡的机械收割傀儡侵扰。",al={"sentinel tower安全吗","sentinel tower危险吗","sentinel tower的危险"}}},fp="14,299,24.456.0,27.450.0,35.196.0,42.229.0,34.188.0,40.185.0"}
P.entries["subzone:sentry-point"] = {n="警戒哨岗",s="警戒哨岗是一座人类瞭望塔，位于尘泥沼泽的大陆边缘，守卫着通往塞拉摩岛的堤道桥。它由塞拉摩的部队维持，负责监视进出吉安娜·普罗德摩尔的岛屿要塞的人流。",h="警戒哨岗是一座人类瞭望塔，位于尘泥沼泽的大陆边缘，守卫着通往塞拉摩岛的堤道桥。它由塞拉摩的部队维持，负责监视进出吉安娜·普罗德摩尔的岛屿要塞的人流。",kw={"桥梁","尘泥沼泽","哨塔","jaina proudmoore","警戒哨岗","塞拉摩","瞭望塔"},ang={["faction:Alliance"]="对于从尘泥沼泽危险的泥沼中赶来的旅行者而言，警戒哨岗是进入塞拉摩岛安全区域的欢迎之门。",["faction:Horde"]="这座塔楼清晰地提醒着人们塞拉摩在卡利姆多大陆上的军事存在，它戒备森严，严防任何接近的部落侦察兵。"},sec={{t="塞拉摩之门",b="警戒哨岗位于连接塞拉摩岛与尘泥沼泽危险湿地的长桥西端，是该要塞在大陆上的第一道防线。这座石砌的侦察塔监视着沼泽道路，确保敌对的沼泽野兽或部落突袭者无法在不被察觉的情况下接近这座岛屿城市。"}},faq={{q="警戒哨岗有什么用？",a="它是塞拉摩岛的预警哨所和边境检查站。驻扎在这里的卫兵负责监视在沼泽道路上通行的人流，并向城市卫兵通报临近的威胁。",al={"警戒哨岗用途","这是什么塔","为什么这里有警戒哨岗"}},{q="谁控制着这个哨站？",a="该哨站由塞拉摩卫兵驻守和维护，在吉安娜·普罗德摩尔及其军事长官的指挥下运作。",al={"谁拥有警戒哨岗","警戒哨岗是联盟的吗","塞拉摩卫兵塔"}},{q="警戒哨岗对部落旅行者安全吗？",a="不安全。尽管吉安娜·普罗德摩尔致力于与部落实现和平，但驻扎在这个哨站的军事卫兵负责保卫联盟领土，并会攻击视线内的入侵部落成员。",al={"部落能去警戒哨岗吗","部落友好的警戒哨岗"}}},fp="12,269,22.349.0,30.193.0,26.140.0,41.190.0"}
P.entries["subzone:sepulcher"] = {n="瑟伯切尔",s="瑟伯切尔是银松森林中被遗忘者的主要定居点和据点。这里曾是俯瞰西海岸的普通洛丹伦墓地和墓穴，如今已成为部落抵御周边区域威胁的防御性避难所。",h="瑟伯切尔是银松森林中被遗忘者的主要定居点和据点。这里曾是俯瞰西海岸的普通洛丹伦墓地和墓穴，如今已成为部落抵御周边区域威胁的防御性避难所。",kw={"墓穴","死亡卫士","被遗忘者前哨站","墓地","瑟伯切尔","银松森林","银松森林瑟伯切尔"},ang={["faction:Horde"]="对于任何从提瑞斯法林地向南冒险的部落旅行者来说，瑟伯切尔是方圆数英里内唯一可靠的避难所、维修点和飞行枢纽。",["race:Undead"]="瑟伯切尔是被遗忘者在银松森林开展平定行动的集结地，指导针对残留的天灾忠诚者、肯瑞托残部和野蛮狼人的作战行动。"},sec={{t="迷雾中的圣所",b="瑟伯切尔坐落在洛丹伦海岸线上方的山丘中，原本是西侧道路旁的一处安静的墓地和墓穴。在第三次战争之后，刚获得解放的被遗忘者将这座古老的石库及其周边区域改造成了一个重要的前哨站。瑟伯切尔四周受敌——南面是野蛮的狼人，东面是游荡的天灾余孽，而安伯米尔的肯瑞托法师也虎视眈眈——因此它成为了在银松森林行进的旅人们难得的安全、补给与指挥中心。"}},faq={{q="在被遗忘者入驻之前，瑟伯切尔是什么地方？",a="在第三次战争和洛丹伦王国覆灭之前，它仅仅是一处路边的墓地和石质墓穴，当地村民会将死者安葬于此。",al={"瑟伯切尔历史","瑟伯切尔的前身","瑟伯切尔的建造者"}},{q="为什么瑟伯切尔对被遗忘者如此重要？",a="它是被遗忘者在银松森林唯一的防御中心。从这个中心位置，被遗忘者的斥候和指挥官们可以监视逼近的达拉然法师、天灾残党，以及潜伏在影牙城堡附近的狼人威胁。",al={"瑟伯切尔为何重要","银松森林的被遗忘者","瑟伯切尔的角色"}},{q="其他部落种族的旅行者在这里受欢迎吗？",a="是的。虽然该基地完全由被遗忘者死亡卫士、商人和药剂师管理和居住，但它作为部落的官方避难所，为途经该地区的兽人、巨魔和牛头人提供休憩与贸易服务。",al={"兽人可以去瑟伯切尔吗","瑟伯切尔对部落友好吗","瑟伯切尔的部落"}},{q="有哪些威胁围绕着瑟伯切尔？",a="该定居点被敌对势力团团包围：东面游荡着天灾军团，东南面的安伯米尔由肯瑞托把持，南面的森林中则潜伏着凶残的狼人。",al={"瑟伯切尔面临的威胁","银松森林的敌人","瑟伯切尔受到什么攻击"}}},fx={["70fd5666"]={q="瑟伯切尔是什么地方？",a="瑟伯切尔是银松森林中被遗忘者的主要聚居地和据点。它坐落在俯瞰洛丹伦西部海岸线的山丘上，是部落在该地区行动的中心，设有斥候、商人和训练师，为人们提供一处安全的落脚点。",al={"瑟伯切尔是什么","银松森林瑟伯切尔","瑟伯切尔是什么地方"}},["2b930170"]={q="为什么叫瑟伯切尔？",a="被遗忘者将此地设为哨站并加以防御之前，这里只是银松森林道路旁的一处墓地和地下墓穴。Sepulcher意为陵墓或墓室。被遗忘者将这座古老墓穴改建为军事基地时，保留了这个贴切的名字。",al={"为什么叫瑟伯切尔","瑟伯切尔名称含义","瑟伯切尔名称由来"}},d7b2f06c={q="瑟伯切尔危险吗？",a="瑟伯切尔界内有被遗忘者哨兵守卫，是一处安全的避难所。然而，界外的区域危机四伏：敌对的狼人潜伏在南方，天灾军团在东方出没，肯瑞托特工则在东南方监视，使这座哨站成为敌境中的孤立避难所。",al={"瑟伯切尔安全吗","瑟伯切尔的危险"}}},fp="9,261,20.549.0,52.153.0,46.254.0,58.231.0,36.178.0"}
P.entries["subzone:serpent-s-coil"] = {n="盘蛇谷",s="盘蛇谷是一处位于诅咒之地东部山脊的蜿蜒洞穴网络和烧毁的营地。这里到处都是从旧时代战争中遗留下来的被烧焦的兽人建筑，成为了黑暗教徒们的隐秘据点。",h="盘蛇谷是一处位于诅咒之地东部山脊的蜿蜒洞穴网络和烧毁的营地。这里到处都是从旧时代战争中遗留下来的被烧焦的兽人建筑，成为了黑暗教徒们的隐秘据点。",kw={"奥利斯塔","诅咒之地","被诅咒的基里斯","盘蛇谷","影誓者"},ang={["class:Warlock"]="在盘蛇谷内活动的影誓教徒进行着束缚仪式并藏匿着强大的神器，使该洞穴成为了肆无忌惮的恶魔研究的阴暗缩影。"},sec={{t="灰烬与岩石的迷宫",b="盘蛇谷凿刻在诅咒之地崎岖的东部悬崖上，其蜿蜒的路径和洞穴经过了追溯到第一次和第二次战争时期的废弃兽人小屋。这些隧道中潜藏的不是普通的野兽，而是被弥漫在红色荒原中的残留恶魔能量所吸引的影誓教徒和黑暗艺术修行者。在深邃蜿蜒的空洞中，他们远离了守望堡的监视，进行着各种勾当。"},{t="邪教徒巢穴",b="这些洞穴长期以来一直是大法师奥利斯塔的教徒们的集结地，他们崇拜恶魔领主，并试验着像奥利斯塔的护符这样的邪恶神器。即使在他们主人的掌控力动摇时，忠诚的影誓狂热者们依然在洞穴的转角处巡逻，在被诅咒的基里斯的麾下维持着仪式，并躲藏在焦黑的路障后。"}},faq={{q="什么是盘蛇谷？",a="盘蛇谷是一处位于诅咒之地东部的蜿蜒洞穴网络和峡谷，因其焦黑的兽人遗迹和邪恶的居住者而闻名。",al={"盘蛇谷","这个洞穴是什么","诅咒之地盘蛇谷"}},{q="为什么这里有古老的兽人建筑？",a="这些营地建筑可以追溯到第一次和第二次战争时期，当时旧部落穿过附近的黑暗之门，并在战败前加固了周边地区。",al={"为什么有兽人遗迹","诅咒之地的兽人建筑","烧毁的小屋"}},{q="谁居住在盘蛇谷内？",a="洞穴被效忠于大法师奥利斯塔及其所侍奉的恶魔力量的影誓教徒所占据。",al={"这里有什么人","盘蛇谷的敌人","谁控制着这个洞穴"}}},fp="14,249,28.446.0,16.369.1,23.148.0,38.180.0,32.115.0"}
P.entries["subzone:sewers"] = {n="Sewers",s="下水道是一个庞大的地下排水网络，提供了直接通往幽暗城的第二入口。这条通道位于洛丹伦废墟宫殿西侧的山丘下方，让蝙蝠管理员和潜行的旅行者可以绕过从王座大厅向下延伸的危险电梯。",h="下水道是一个庞大的地下排水网络，提供了直接通往幽暗城的第二入口。这条通道位于洛丹伦废墟宫殿西侧的山丘下方，让蝙蝠管理员和潜行的旅行者可以绕过从王座大厅向下延伸的危险电梯。",kw={"后门","蝙蝠管理员","排水","飞行路线","洛丹伦","下水道","提瑞斯法林地","幽暗城"},ang={["faction:Alliance"]="任何足够愚蠢或勇敢去突袭被遗忘者首都的人都知道，下水道是绕过防御严密的地面废墟的唯一隐蔽路径。",["race:Undead"]="对于被遗忘者来说，下水道是一条至关重要的生命线和飞行走廊，它使幽暗城能够与洛丹伦的其他地区保持联系，而不会让交通拥堵在庭院电梯处。"},sec={{t="通往地下墓穴的后门",b="在瘟疫摧毁洛丹伦之前，这些石质涵洞曾是皇家首都的普通下水道。然而，在Sylvanas Windrunner的被遗忘者手中，这些径流隧道已被整合到幽暗城的外部防御系统中。该通道在地面废墟西侧、提瑞斯法林地一处有争议的血色十字军岗哨附近通向地面，提供了一条平坦、直接的下坡路。被遗忘者的蝙蝠管理员利用这条巨大的管道，将乘客快速运送到地下环形区，完全避开了缓慢的铁笼电梯。由于它绕过了防御严密的地面庭院，这里仍然是一个敌对渗透者不断试图利用的危险漏洞。"}},faq={{q="下水道隧道在外部通向哪里？",a="该管道通向提瑞斯法林地的起伏丘陵，就在洛丹伦废墟正门的西侧。它距离俯瞰湖泊的血色十字军岗哨不远。",al={"幽暗城下水道出口","下水道通向哪里","下水道后门"}},{q="为什么有人会使用下水道而不是正门？",a="进入幽暗城的主要方式需要乘坐从宫殿废墟向下延伸的铁笼电梯，这在受到攻击时既缓慢又危险。下水道是一条直接的斜坡路线，既能处理被遗忘者的蝙蝠运输，又允许在无需等待电梯的情况下快速撤离。",al={"为什么使用下水道","下水道与电梯","幽暗城后门"}},{q="下水道对联盟袭击者来说安全吗？",a="绝不安全。因为它绕过了洛丹伦防御严密的门楼和王座大厅，下水道成为了大胆的联盟侦察兵和突击队试图直接潜入被遗忘者首都的首选突破点。",al={"联盟攻击下水道","下水道有守卫吗","幽暗城下水道防御"}}},fx={["833a18e0"]={q="幽暗城的下水道是什么地方？",a="这片庞大的排水系统位于洛丹伦废墟下方，最终流入提瑞斯法林地，出口就在宫殿大门以西。许多被遗忘者旅人和蝙蝠驯养员不愿使用不稳固的宫殿升降梯，转而穿过这些污秽的隧道，直接进入幽暗城地下深处。",al={"下水道是什么","幽暗城下水道"}}},fp="6,312,29.696.0,41.190.0,61.273.0,40.221.0"}
P.entries["subzone:shadow-grave"] = {n="灰影墓穴",s="灰影墓穴是一座坐落在提瑞斯法林地丧钟镇上方斜坡墓地顶部的石砌墓穴。它是新获得自由的被遗忘者摆脱死亡带来的迟钝和巫妖王逐渐消退的控制，从而获得觉醒的物理起点。",h="灰影墓穴是一座坐落在提瑞斯法林地丧钟镇上方斜坡墓地顶部的石砌墓穴。它是新获得自由的被遗忘者摆脱死亡带来的迟钝和巫妖王逐渐消退的控制，从而获得觉醒的物理起点。",kw={"觉醒","墓穴","丧钟镇","灰影墓穴","初始之墓","提瑞斯法林地","管理员摩尔多"},ang={["race:Undead"]="每一位被遗忘者冒险者都是从这座墓穴冰冷的石板上开始他们的旅程，睁开双眼面对不死与自由意志的严酷现实。"},sec={{t="被遗忘者的摇篮",b="灰影墓穴隐藏在丧钟镇上方墓地斜坡顶端的岩石山脚下，这是一座简单的石制陵墓，却有着非凡的用途。在它潮湿的拱顶内，被复活为天灾军团无心奴仆的尸体逐渐觉醒并获得自由意志。在像管理员摩尔多这样的看管者的注视下，这些新近获得自由的亡灵从石板上站起来，向着一个厌恶他们的世界迈出战栗的第一步，然后沿着小路走向丧钟镇，向黑暗游侠女王宣誓效忠。"}},faq={{q="灰影墓穴是用来做什么的？",a="它是新觉醒的被遗忘者苏醒意识的墓穴。这些复活的个体没有像尘土中毫无思想的天灾爪牙那样继续存在，而是在墓穴内恢复了自由意志，并开始了服务于Sylvanas Windrunner的第二次生命。",al={"灰影墓穴用途","什么是灰影墓穴","灰影墓穴陵墓"}},{q="灰影墓穴位于哪里？",a="灰影墓穴坐落在丧钟镇上方的墓地斜坡顶部，背靠提瑞斯法林地的南部山脉。一条土路从入口处蜿蜒下行，通往丧钟镇的定居点。",al={"灰影墓穴在哪里","灰影墓穴位置","灰影墓穴地图"}},{q="谁在这里看管新觉醒者？",a="管理员摩尔多负责照看墓穴内新觉醒的亡灵，评估那些从石板上爬起来的人是否已经恢复了神智，并足以投身于被遗忘者的大业。",al={"灰影墓穴里有什么人","灰影墓穴npc","管理员摩尔多位置"}}},fx={f1e0774e={q="灰影墓穴是什么地方？",a="灰影墓穴是一座僻静的石砌地下墓室，坐落在提瑞斯法林地西部、丧钟镇上方的墓园斜坡高处。一条蜿蜒向下的小路将墓穴与丧钟镇相连。这座肃穆的墓穴是新近苏醒的被遗忘者重返意识的静谧起点，他们在这里从泥土中挣扎而出，远离林地周围的威胁。",al={"灰影墓穴是什么","灰影墓穴背景","介绍灰影墓穴"}},["742f7843"]={q="灰影墓穴危险吗？",a="墓穴本身相对安全，驻守在此的被遗忘者侍从会尽心照料新近苏醒的人。然而，石门之外便是提瑞斯法林地的险境：漫无目的游荡的天灾亡灵、食腐者，以及时刻警惕的血色十字军特工，都会威胁准备不足、走得太远的人。",al={"灰影墓穴危险吗","灰影墓穴安全吗","灰影墓穴里有敌人吗"}}},fp="12,244,22.557.0,34.255.0,34.217.0,37.174.0"}
P.entries["subzone:shadow-hold"] = {n="暗影堡",s="暗影堡是隐藏在费伍德森林西部加德纳尔腐化峡谷中的一座庞大的地下建筑群。这里曾是一座神圣的暗夜精灵古墓，后被暗影议会占领并亵渎，成为了他们在卡利姆多的主要堡垒。",h="暗影堡是隐藏在费伍德森林西部加德纳尔腐化峡谷中的一座庞大的地下建筑群。这里曾是一座神圣的暗夜精灵古墓，后被暗影议会占领并亵渎，成为了他们在卡利姆多的主要堡垒。",kw={"阿可娜琳","贝恩霍勒","古墓","费尔丹","费伍德森林","加德纳尔","暗影议会","暗影堡","崔伊·光铸"},ang={["class:Warlock"]="暗影堡的最深处藏有像克索诺斯星尘这样稀有的恶魔试剂，只有通过巧妙的潜入赢得贝恩霍勒领主的青睐，才能获得这些试剂。",["race:NightElf"]="对于暗夜精灵来说，这座堡垒是一个恐怖的地方——一座被邪能污泥、囚笼和恶魔仪式所亵渎的祖先古墓。"},sec={{t="一座被亵渎的圣所",b="在加德纳尔被腐蚀的红土地之下，坐落着暗影堡。这是一个巨大的地下迷宫，由古代暗夜精灵古墓改造而成。曾经有沉睡的德鲁伊在此休息并照看翡翠梦境，而如今，黑暗术士和恶魔仆从在魔火照亮的蜿蜒走廊中潜行。在最深处，该邪教在恐惧魔王贝恩霍勒领主、萨瓦里斯王子和暗影领主费尔丹的统领下，掌握着一支强大的武装力量，使其成为了该地区恶魔势力的最高据点。"},{t="深处的恐怖",b="暗影议会利用这些洞穴来协调他们对费伍德森林的腐化，并进行残酷的审讯。包括暗夜精灵阿可娜琳·星影和人类圣骑士崔伊·光铸在内的联盟斥候在暗影堡深处落入了邪教徒手中。虽然阿可娜琳及时获救而幸存，但崔伊却被邪教的刑吏折磨致死，他的灵魂在安息前曾一度被扭曲成邪恶之物。翡翠之环和当地的萨满祭司一直在努力穿透保护着暗影堡的黑暗屏障，希望能一举击溃这里的恶魔主人。"}},faq={{q="暗影议会占领之前，暗影堡是什么地方？",a="暗影堡最初是一座古老的暗夜精灵古墓，供奉着那些沉睡的德鲁伊，他们曾在此照看大地并与翡翠梦境进行交流。在第三次战争和费伍德森林遭受恶魔腐化之后，暗影议会占领了这座地下建筑群，并将这些神圣的大厅亵渎为一座邪能堡垒。",al={"暗影堡历史","谁建造了暗影堡","暗影堡最初是什么"}},{q="谁统治着暗影堡？",a="这座堡垒由恐惧魔王贝恩霍勒领主监管，同时还有强大的副手协助，包括萨特萨瓦里斯王子和指挥凡人邪教徒的术士暗影领主费尔丹。",al={"暗影堡首领","谁在掌管暗影堡","暗影堡的领袖"}},{q="冒险者为何要潜入暗影堡？",a="寻求强大召唤试剂（如克索诺斯星尘）的黑魔法修行者有时会伪装成忠诚的暗影议会邪教徒进入堡垒。只有当外来者通过铲除其队伍中的间谍和叛徒来证明忠诚时，贝恩霍勒领主才会允许他们与堡垒进行贸易。",al={"潜入暗影堡","伪装成暗影议会进入暗影堡","克索诺斯星尘 暗影堡"}},{q="堡垒中的俘虏遭遇了什么？",a="暗夜精灵阿可娜琳·星影和圣骑士崔伊·光铸在侦察暗影议会时被俘。崔伊被邪教徒拉凯亚折磨致死，而阿可娜琳则被冒险者从笼中救出，随后冒险者又寻回了崔伊的遗骸，使其得以安葬。",al={"加德纳尔的俘虏","崔伊·光铸与阿可娜琳","暗影堡的囚笼"}}},fp="11,252,19.501.0,19.573.1,60.318.0,29.197.0,58.293.1,42.281.1"}
P.entries["subzone:shadowbreak-ravine"] = {n="破影峡谷",s="破影峡谷是一处位于凄凉之地东南部的隐蔽山谷。这处阴森的峡谷掩藏在玛格拉姆村附近嶙峋的峭壁之中，是火刃氏族的恶魔势力和凡人狂热者的秘密据点。",h="破影峡谷是一处位于凄凉之地东南部的隐蔽山谷。这处阴森的峡谷掩藏在玛格拉姆村附近嶙峋的峭壁之中，是火刃氏族的恶魔势力和凡人狂热者的秘密据点。",kw={"火刃氏族","邪教徒","恶魔","凄凉之地","邪能","破影峡谷","玛格拉姆村"},ang={["class:Warlock"]="黑暗的召唤法阵和浓郁的邪能气息，使得这座隐秘的峡谷成为了火刃氏族黑暗魔法触角深远的明证。"},sec={{t="一处邪能的隐秘飞地",b="破影峡谷深藏在玛格拉姆村东南方贫瘠的山脊之中，为火刃氏族提供了一个远离游荡的半人马部落视线的隐蔽集结地。在奇异的巨型蘑菇和阴森的仪式营地之间，邪教徒们与被召唤出的恶魔并肩劳作。在这里，黑暗修行者们调用邪能，维护着沉重的仪式锁链，利用峡谷天然的隔离环境，集结援军，并在凄凉之地的荒原中稳固其恶魔据点。"}},faq={{q="破影峡谷是什么地方？",a="破影峡谷是一处位于凄凉之地东南部、玛格拉姆村外围的隐蔽山谷。它是火刃氏族的恶魔爪牙和邪教徒的隐秘营地与集结地。",al={"破影峡谷信息","这是什么地方","破影峡谷在哪里"}},{q="谁占据了这座峡谷？",a="这座峡谷被火刃氏族的邪教徒占据，他们直接与恶魔并肩作战。他们利用峡谷受遮蔽的地形进行黑暗仪式，并为他们在该地区发动的更广泛的攻势提供支援。",al={"谁住在这里","破影峡谷怪物","破影峡谷的敌人"}},{q="在峡谷内可以发现哪些特征？",a="峡谷内有黑暗仪式建筑、巨大的铁链，以及在隐藏于山缝中的邪能营地间生长的醒目巨型蘑菇。",al={"破影峡谷里面有什么","破影峡谷地标"}}},fp="18,243,23.515.0,27.218.0,24.209.0,45.176.0"}
P.entries["subzone:shadowfang-keep"] = {n="影牙城堡",s="影牙城堡坐落在银松森林南部，俯瞰着焚木村的一处崎岖峭壁之上，是疯狂的大法师阿鲁高和他那些野性狼人的黑暗巢穴。这座要塞原名为席瓦莱恩城堡，在第三次战争期间被召唤出的贪婪狼群攻陷，如今其古老的厅堂里游荡着被杀害的贵族的亡魂，到处爬满了狼形的怪物。",h="影牙城堡坐落在银松森林南部，俯瞰着焚木村的一处崎岖峭壁之上，是疯狂的大法师阿鲁高和他那些野性狼人的黑暗巢穴。这座要塞原名为席瓦莱恩城堡，在第三次战争期间被召唤出的贪婪狼群攻陷，如今其古老的厅堂里游荡着被杀害的贵族的亡魂，...",kw={"阿鲁高","芬鲁斯","焚木村","影牙","席瓦莱恩","银松森林","斯普林瓦尔","狼人"},ang={["class:Mage"]="影牙城堡是肯瑞托傲慢行径的一个残酷警示，展现了无节制地进行异维度召唤所带来的灾难。",["faction:Horde"]="对于被遗忘者来说，阿鲁高的狼人是一个不可预测的威胁，它们就盘踞在银松森林中幽暗城外围领地的家门口，必须尽快予以铲除。"},sec={{t="席瓦莱恩家族的陨落",b="在第三次战争之前，这座高耸的要塞被称为席瓦莱恩城堡，是席瓦莱恩男爵的祖宅，也是附近焚木村的权力中心。当天灾军团席卷洛丹伦时，绝望的法师们寻求禁忌手段来遏制这股亡灵浪潮。依靠达拉然法师乌尔的空间维度研究，大法师阿鲁高将异维度的狼人召唤到了艾泽拉斯。这些野蛮的野兽撕碎了天灾军团，但很快就失控了。狼群在银松森林南部横冲直撞，围攻了这座要塞，屠杀了席瓦莱恩男爵、他的家人以及指挥官斯普林瓦尔的守军。内疚与悲伤摧毁了阿鲁高的理智；他没有逃走，而是占领了这座要塞，将其更名为影牙城堡，并收养了这些凶残的掠食者作为他的“孩子”。"},{t="被诅咒的堡垒",b="今天，影牙城堡已成为瘟疫般肆虐银松森林的狼人诅咒的中心。阿鲁高居住在最高的观星台，身旁簇拥着他那贪婪的狼人——包括月怒狼群和影牙狼群——以及像他巨大的宠物狼芬鲁斯那样的邪恶野兽。在他的圣所之下，城堡昔日领主们那不安的灵魂，例如席瓦莱恩男爵和指挥官斯普林瓦尔，依然被困在痛苦之中，被诅咒着去无休止地守卫那些他们在生前未能守护的厅堂。阿鲁高站在城墙之上，将他险恶的影响力延伸至焚木村和周边的林地，对试图清除森林中疯狂之源的邻近被遗忘者构成了可怕的威胁。"}},faq={{q="在阿鲁高接管之前，影牙城堡叫什么名字？",a="它最初名为席瓦莱恩城堡。它是席瓦莱恩男爵的祖传要塞，他在狼人入侵之前一直管理着焚木村和周边的土地。",al={"原名","谁曾经拥有影牙城堡","席瓦莱恩城堡"}},{q="为什么阿鲁高要在这里召唤狼人？",a="在第三次战争期间，天灾军团无情地碾压了达拉然的军队，并将被杀害的法师复活为亡灵。不顾肯瑞托的警告，大法师阿鲁高利用法师乌尔的研究召唤了异维度的狼人来扭转战局。虽然它们消灭了亡灵，但这些野兽很快就转向了活人，并在银松森林中横行。",al={"阿鲁高为什么要召唤狼人","阿鲁高背景故事","狼人是如何来到这里的"}},{q="现在是谁统治着影牙城堡？",a="这座城堡由大法师阿鲁高把持。因释放这些怪物而产生的内疚感让他陷入疯狂，他将狼人视为自己的“孩子”，并在要塞高处与他那致命的狼群一起进行统治。",al={"影牙城堡的现任主人","谁住在影牙城堡","阿鲁高的城堡"}},{q="为什么影牙城堡里会有鬼魂？",a="这些鬼魂属于席瓦莱恩男爵、指挥官斯普林瓦尔和城堡以前的家臣。当狼群涌入城堡并屠杀了里面的所有人时，居民们的灵魂被困在了石头之中，被诅咒着在废墟般的走廊里游荡。",al={"席瓦莱恩男爵的鬼魂","指挥官斯普林瓦尔的鬼魂","影牙城堡内的亡灵"}},{q="焚木村与这座城堡有什么联系？",a="焚木村坐落在城堡的阴影之下，历史上一直由席瓦莱恩男爵管理。在阿鲁高蔓延的影响下，村民们受到了狼人诅咒的折磨，白天表现为普通的凡人，但在夜幕降临时会变身为狂暴的野兽。",al={"焚木村与影牙城堡","焚木村的诅咒"}}},fx={["26793205"]={q="为什么叫影牙城堡？",a="这座要塞最初以统治它的贵族命名为Silverlaine Keep。阿鲁高召唤的狼人攻占要塞后，他将其改名为影牙城堡，以纪念他视若珍宝、收为养子的凶残暗影狼兽，以及如今游荡在城堡厅堂中的黑暗狼群。",al={"影牙城堡名称","为什么叫影牙","影牙城堡名称由来"}},b733cd78={q="影牙城堡是什么地方？",a="影牙城堡是一座闹鬼的要塞，矗立在银松森林南部的高耸岩崖上，俯瞰格雷迈恩之墙附近的焚木村。它原本是席瓦莱恩男爵的祖居城堡，后来在第三次战争期间被召唤而来的野性狼人攻占。如今，这里是疯狂的大法师阿鲁高隐居的巢穴，由贪婪的兽人、幽灵守卫和扭曲的巫术把守。",al={"影牙城堡是什么","影牙城堡背景","影牙城堡"}},cc8ad05a={q="影牙城堡发生过什么事？",a="第三次战争期间，大法师阿鲁高试图借助乌尔的研究召唤异次元狼人来到艾泽拉斯，以击退天灾军团。尽管这些野兽屠杀了亡灵，却很快在银松森林四处肆虐，并围攻席瓦莱恩男爵的要塞。狼人杀害了男爵、他的家人和卫兵。阿鲁高因愧疚与恐惧而发疯，将这些野兽当作自己的“孩子”，占据了这座沦陷的城堡，并将其更名为影牙城堡。",al={"影牙城堡历史","席瓦莱恩城堡发生了什么","影牙城堡的陷落"}},ee32dcde={q="影牙城堡为什么变成了废墟？",a="阿鲁高麾下的狼人四处肆虐，围困城堡并击溃守军，杀害了席瓦莱恩男爵及其全家，最终使这座要塞沦为废墟。疯狂的大法师没有修复这座贵族庄园，反而任由厅堂陷入黑暗，庭院和城垛间遍布野蛮的野兽，以及在屠杀中丧生的贵族们饱受折磨的幽魂。",al={"影牙城堡为什么变成废墟","影牙城堡被摧毁","它为什么被遗弃"}},["5c468b05"]={q="影牙城堡危险吗？",a="影牙城堡极其致命。铁门后潜伏着成群的凶猛狼人、阿鲁高体型庞大的宠物狼芬鲁斯，以及嗜血的教徒。除了活着的野兽，席瓦莱恩男爵和被杀士兵那躁动而复仇的灵魂也在厅堂中徘徊；大法师阿鲁高则在城堡城垛之上施展致命的奥术诅咒。",al={"影牙城堡危险吗","影牙城堡的危险","影牙城堡有多危险"}}},fp="15,366,24.815.0,17.707.0,56.186.0,38.369.0,36.195.0,40.253.0,55.270.1"}
P.entries["subzone:shadowglen"] = {n="幽影谷",s="幽影谷是坐落在泰达希尔东北部枝干间的一处幽静而昏暗的山谷。巨大的古树奥达希尔在此耸立，这里也是年轻的暗夜精灵在奔赴广阔世界开启冒险生涯前，迈出第一步的安全避风港。",h="幽影谷是坐落在泰达希尔东北部枝干间的一处幽静而昏暗的山谷。巨大的古树奥达希尔在此耸立，这里也是年轻的暗夜精灵在奔赴广阔世界开启冒险生涯前，迈出第一步的安全避风港。",kw={"奥达希尔","卡多雷","暗夜精灵新手区","幽影谷","黑丝洞","泰达希尔"},ang={["faction:Alliance"]="幽影谷坐落在泰达希尔高耸的枝干上，处于严密守卫的港口深处，是联盟最隐蔽、防御最森严的圣地幽谷之一。",["race:NightElf"]="每一位年轻的暗夜精灵都是从奥达希尔那受庇护的根系间开启他们的冒险旅程，在面对卡利姆多的危险之前，在这里接受最初的祝福和指引。"},sec={{t="一处隐蔽的摇篮",b="幽影谷藏在泰达希尔的东北部树冠中，被高耸的山脊环绕，与世隔绝。幽谷终日沐浴在暮色之中，以奥达希尔为中心，这是一棵巨大的古树，其中空的树干内住着长者、女祭司和导师，为刚刚开始训练的年轻暗夜精灵提供指导。走出山谷的唯一路线是向南穿过一条狭窄的山道，通往星风村和多兰纳尔。这使得幽影谷成为世界之树上防御最自然、最宁静的圣地之一。"},{t="蔓延的阴影",b="尽管幽影谷静谧隐蔽，但也并非完全没有危险。在极西北处坐落着黑丝洞，这是一个阴暗的洞穴，遍布着毒蜘蛛，时刻威胁着这片宁静的林地。即使在泰达希尔这片纯净的枝干上，也需要保持警惕。初出茅庐的保卫者们肩负着击退入侵的害虫和野兽的任务，然后才能前往枝干上更广阔的世界。"}},faq={{q="什么是幽影谷？",a="幽影谷是暗夜精灵的隐蔽新手村，位于泰达希尔的东北部。这是一个以大树奥达希尔为中心的宁静隐蔽的避风港，新手们在导师的指导下进行训练，随后便会踏上探索世界之树的旅程。",al={"这是什么地方","幽影谷背景故事","关于幽影谷"}},{q="山谷中心那棵巨大的树是什么？",a="这棵树是奥达希尔，它是构成幽影谷核心的古树。其中空的内部作为行政小屋和训练中心，年轻的暗夜精灵在这里会见职业训练师、导师和看护者。",al={"幽影谷的大树","奥达希尔","幽影谷树木"}},{q="幽影谷存在哪些威胁？",a="主要威胁来自西北部的黑丝洞，这是一个遍布毒蜘蛛的洞穴，这些蜘蛛经常爬到山谷中。年轻的保卫者们的任务是清除这些蜘蛛，并安抚躁动的当地野生动物。",al={"为什么这里有蜘蛛","幽影谷的危险","黑丝洞"}},{q="如何离开幽影谷？",a="幽影谷四面环山，只有一条向南的小路。穿过这个狭窄的山隘，向南可以前往星风村和多兰纳尔聚居地。",al={"离开幽影谷","小路通向哪里","走出幽影谷的路径"}}},fx={ceaa8c71={q="什么是泰达希尔？",a="泰达希尔是一棵巨大的世界之树，生长在卡利姆多西北海岸附近。它的名字在达纳苏斯语中意为“Crown of the Earth”。第三次战争结束后，远古议会和强大的德鲁伊们将它培育起来，作为卡多雷的新家园。它庞大的枝干从海中直插天际，枝头承载着一整片森林覆盖的陆地，以及达纳苏斯城。",al={"这棵巨树是什么","泰达希尔世界之树","泰达希尔介绍"}},c8ee90fe={q="是谁培育了泰达希尔？",a="玛法里奥·怒风失踪后，大德鲁伊范达尔·鹿盔说服远古议会种下一棵新的世界之树。强大的德鲁伊们汇聚魔法，使它从海中升起，希望借此恢复卡多雷失去的永生。然而，巨龙军团守护巨龙拒绝为它的枝干赐福，其中尤以曾赐予卡多雷远古永生的诺兹多姆为甚，因此这棵树的成长并不完美。",al={"谁建造了泰达希尔","谁种下了泰达希尔","谁创造了世界之树"}},["8fe22cbd"]={q="为什么暗夜精灵现在住在树上？",a="第三次战争期间，暗夜精灵牺牲了海加尔山上的诺达希尔，因此失去了祖先的不朽之力。卡多雷希望重获永生，并在远离大陆威胁的地方找到安全的庇护所，于是培育了泰达希尔作为圣所，并在高耸的枝干间建立了光辉的首都达纳苏斯。",al={"为什么住在树上","暗夜精灵为何住在泰达希尔","为什么住在泰达希尔"}},["5b09454b"]={q="谁住在奥达希尔顶端？",a="幽影谷的领袖特纳隆·雷拳住在奥达希尔的树冠之中。他在这棵大树的高枝上主持年轻暗夜精灵守护者的训练与入门仪式。",al={"奥达希尔顶端","谁在奥达希尔","特纳隆·雷拳奥达希尔"}},["27b05a0e"]={q="奥达希尔和泰达希尔是同一棵树吗？",a="不是。泰达希尔是一棵巨大的世界之树，从海洋中升起，枝头托起一整座岛屿大小的森林、山脉和城市。奥达希尔则是一棵独立而巨大的古树，扎根于幽影谷的土地上，坐落在泰达希尔之上。",al={"奥达希尔与泰达希尔的区别","奥达希尔是泰达希尔吗","奥达希尔和泰达希尔有什么区别"}},["0792cbea"]={q="这附近由谁负责？",a="特纳隆·雷拳在奥达希尔顶端的居所中统领幽影谷。他负责山谷的防务，协调当地的德鲁伊、哨兵和导师，指导新来者，并处理当地野生动物日益严重的腐化问题。",al={"谁领导幽影谷","幽影谷领袖","幽影谷由谁负责"}},["3fc160d4"]={q="谁统领整个暗夜精灵族？",a="高阶女祭司泰兰德·语风通过艾露恩姐妹会领导卡多雷；玛法里奥·怒风不在期间，大德鲁伊范达尔·鹿盔负责统领塞纳里奥议会。女祭司与德鲁伊携手在达纳苏斯首都引领暗夜精灵族。",al={"暗夜精灵领袖","谁统治暗夜精灵","卡多雷领袖"}},["003c713a"]={q="林木蜘蛛是什么？它们为什么会在这里？",a="林木蜘蛛是栖居在年轻世界之树中的黑丝洞里的巨型蛛类。它们过去大多深居简出，但泰达希尔上蔓延的黑暗腐化使它们陷入狂暴，迫使它们离开巢穴，攻击任何在北部区域游荡的人。",al={"泰达希尔林木蜘蛛","蜘蛛为何在幽影谷","幽影谷蜘蛛"}},["19b22b7f"]={q="林木蜘蛛一直住在那个洞穴里吗？",a="是的。西北方的黑丝洞是泰达希尔巨型蜘蛛的天然栖息地。然而，近来在凶残的母蛛吉提希斯的带领下，它们的敌意急剧增长，使洞穴成了新手游荡者的致命险地。",al={"蜘蛛一直住在黑丝洞吗","黑丝洞历史","蜘蛛一直在这里吗"}},b0a66f5b={q="艾露恩是谁？",a="艾露恩是暗夜精灵敬奉的月亮女神，象征和平、星光与治愈。卡多雷自远古时代起便崇拜她，而由泰兰德·语风领导的高阶女祭司们则借助她的天界之力保护族人、惩戒敌人。",al={"月亮女神艾露恩","艾露恩与暗夜精灵","女神艾露恩"}},["2f0ec344"]={q="多兰纳尔是什么？为什么大家总让我去那里？",a="多兰纳尔是最近的一处大型聚居地，位于幽影谷西南方，需穿过南部山口才能抵达。山谷中的导师考验过你的能力后，会派你前往多兰纳尔继续训练、学习专业技能，并协助处理泰达希尔各地的危机。",al={"什么是多兰纳尔","为什么去多兰纳尔","多兰纳尔村庄"}},["94588242"]={q="暗夜精灵为什么失去了永生？",a="第三次战争期间，燃烧军团进军海加尔山，企图吞噬最初的世界之树诺达希尔。玛法里奥·怒风引导森林之灵和古树的力量，彻底消灭了恶魔领主阿克蒙德。诺达希尔的牺牲摧毁了巨龙军团守护巨龙赐予的魔法，使卡多雷失去了永葆青春的能力。",al={"暗夜精灵失去永生","暗夜精灵为何会老去","暗夜精灵失去永生的原因"}},b6ffca43={q="我怎么会来到幽影谷？",a="你身处泰达希尔东北部高处枝头间的一处僻静林间空地。这棵年轻的世界之树生长在卡利姆多北部海岸附近。幽影谷藏在大树奥达希尔之下，与外界隔绝，是新晋卡多雷的安全庇护所和训练场。你响应长者的召唤来到这里，在宁静隐居之处磨炼本领，然后再踏上族中新家园更广阔的枝干。",al={"我是怎么到这里的","我是怎么来到这里的","我为什么在这里"}},e332bd9f={q="我在幽影谷应该做什么？",a="你要协助奥达希尔的守卫和长者，处理扰乱这片林间空地的日益严重的问题。最近，一股邪恶的腐化开始侵扰当地野生动物，使原生的林木蜘蛛和林地野兽变得敌对。与大树附近的训练师和领袖交谈，清除黑丝洞中滋生的病灶，并恢复森林的平衡，然后沿着小路南行，继续前往多兰纳尔。",al={"我在这里该做什么","我在这里的目的是什么","我在幽影谷做什么"}},["3011769b"]={q="为什么新创建的暗夜精灵从幽影谷开始？",a="第三次战争结束、诺达希尔牺牲后，暗夜精灵渡海迁往泰达希尔，开始新的生活。幽影谷是树冠中守卫最严密、最隐蔽的一处区域，环绕的山脊将它与外界隔开，经验丰富的哨兵则守护着这里。你刚开始学习德鲁伊之道、战斗技艺或艾露恩的恩泽，因此族人会在奥达希尔的庇护下培养你，之后再将你送入更广阔、危险更多的世界。",al={"暗夜精灵为什么从这里开始","我的暗夜精灵为什么从幽影谷开始","为什么从幽影谷开始"}}},fp="10,269,18.533.0,16.444.0,19.264.0,51.216.0,33.239.0,28.197.0"}
P.entries["subzone:shadowprey-village"] = {n="葬影村",s="葬影村是部落位于凄凉之地萨瑟里斯海岸南部岩石海岸线上的一处偏远渔业定居点。这里居住着大量暗矛巨魔渔民，并有牛头人后勤人员提供支持，它在荒凉的废土中作为至关重要的海岸前哨站和贸易生命线发挥着作用。",h="葬影村是部落位于凄凉之地萨瑟里斯海岸南部岩石海岸线上的一处偏远渔业定居点。这里居住着大量暗矛巨魔渔民，并有牛头人后勤人员提供支持，它在荒凉的废土中作为至关重要的海岸前哨站和贸易生命线发挥着作用。",kw={"凄凉之地","萨瑟里斯海岸","葬影村","泰迦·慧鬃","巨魔捕鱼"},ang={["faction:Horde"]="对于穿越凄凉之地的部落旅行者来说，葬影村提供了科多兽坟场以南唯一的海岸休息站、飞行枢纽和安全的补给基地。",["race:Troll"]="葬影村是卡利姆多中部少有的暗矛海岸文化避风港，展示了该部族传统的长矛捕鱼、潜水和海岸生存技巧。"},sec={{t="海岸上的避风港",b="葬影村依偎在凄凉之地南部的悬崖边，为这个以半人马部族和荒芜废土而闻名的地区提供了一处安全的避风港。该定居点主要由巨魔渔民的营地组成，他们的捕获物不仅维持了村庄自身的生存，也为幽灵岗哨等内陆哨所提供了补给。尽管海岸线崎岖不平，但高耸的木制码头延伸至海洋中，让当地的垂钓者能够深入深海，并在散布于萨瑟里斯海岸的沉船残骸间潜水捕捞贝类。"},{t="海岸的磨难",b="在凄凉之地维持一个前线港口充满了危险。除了内陆肆虐的半人马和召唤恶魔的火刃氏族带来的威胁外，海洋本身也用汹涌的浅滩和饥饿的海洋生物考验着村庄的生存能力。包括泰迦·慧鬃以及旅店和双足飞龙管理员在内的牛头人盟友，正协助加强防御，并保持着连接整个卡利姆多的贸易路线畅通。"}},faq={{q="为什么葬影村对部落很重要？",a="凄凉之地是一片缺乏自然资源的荒凉废土。葬影村是部落在该地区唯一的海岸港口，它运送着至关重要的鱼类和贝类捕获物来供养幽灵岗哨等驻军，同时提供了一个连接石爪山脉、雷霆崖和菲拉斯的双足飞龙旅行枢纽。",al={"葬影村的目的","为什么葬影村在这里","葬影村在部落中的角色"}},{q="谁领导着葬影村？",a="该定居点没有记载有单一的首领。村庄以一种松散的巨魔渔民社区形式运作，而像泰迦·慧鬃这样的牛头人居民则协助防守，抵御着在凄凉之地蠢蠢欲动的火刃氏族邪教徒。",al={"葬影村的首领","谁负责葬影村"}},{q="为什么在巨魔村庄里会有牛头人负责服务工作？",a="葬影村最初是作为土著暗矛部族的渔业前哨站建立的，但它作为区域供应枢纽的角色吸引了部落更广泛的后勤机构。牛头人负责监督重要的共享基础设施，维护旅店，管理马厩，并指挥连接港口与莫高雷及其他地区的双足飞龙管理员。",al={"葬影村的牛头人","为什么牛头人在这里"}},{q="有哪些威胁在困扰着渔民？",a="除了内陆敌对的半人马之外，村庄还必须面对火刃氏族的威胁，他们的召唤恶魔的邪教徒盘踞在雷斧堡垒中，此外还有海岸汹涌的水域和危险的海洋生物。",al={"葬影村的问题","葬影村的威胁"}}},fp="18,298,21.503.0,20.389.0,49.317.0,29.224.0,61.319.0,41.205.0"}
P.entries["subzone:shadowsong-shrine"] = {n="影歌神殿",s="影歌神殿是一处位于艾萨拉西部山坡上的废弃圣地，距离灰谷边境不远。这里不仅有古代上层精灵不安的灵魂徘徊，更承载着影歌家族那显赫的名号，尽管它与该家族真正的历史渊源至今仍笼罩在迷雾之中。",h="影歌神殿是一处位于艾萨拉西部山坡上的废弃圣地，距离灰谷边境不远。这里不仅有古代上层精灵不安的灵魂徘徊，更承载着影歌家族那显赫的名号，尽管它与该家族真正的历史渊源至今仍笼罩在迷雾之中。",kw={"艾萨拉","鬼魂","上层精灵","玛维","废墟","影歌","神殿"},ang={["race:NightElf"]="对于暗夜精灵来说，影歌这个名字因守望者玛维而令人肃然起敬，因此这处遗迹被备受折磨的上层精灵鬼魂所亵渎，显得格外令人悲伤。"},sec={{t="被诅咒的遗产",b="影歌神殿坐落于艾萨拉破碎大地之上的一处高坡，如今已成了一片长满杂草的古老废墟。与周围大部分海岸地区一样，这里也饱受徘徊在倒塌石柱间的上层精灵鬼魂的侵扰，它们试图消灭任何胆敢踏入其领地的凡人生命。这座神殿与伊利丹·怒风那毫不留情的守望者玛维·影歌同名。至于这座圣地究竟是为了纪念她的家族，还是在大分裂之前就已经存在，这已是一个被岁月掩埋的秘密。"}},faq={{q="影歌神殿是什么地方？",a="它是一处位于艾萨拉西部高地上的暗夜精灵古迹。如今它已残破不堪，被敌对的上层精灵幽灵所占据。",al={"这是什么地方","影歌神殿信息","艾萨拉山坡上的废墟"}},{q="这座神殿是以谁的名字命名的？",a="它与曾经囚禁伊利丹·怒风的著名守望者玛维·影歌同名。然而，这座神殿是否是为了纪念她或她的家族，并没有明确的记载。",al={"玛维·影歌","为何叫影歌"}},{q="为什么这座神殿闹鬼？",a="和艾萨拉各处的许多废墟一样，该遗迹在一万年前的大分裂中遭受了毁灭。在大灾变中丧生的上层精灵的灵魂被束缚在这些石头上，陷入了疯狂，并对生者怀有敌意。",al={"这里为什么会有鬼魂","艾萨拉的上层精灵鬼魂","影歌神殿的鬼魂"}},{q="这座神殿位于哪里？",a="它位于艾萨拉西部的一座山丘之上，在灰谷森林边界的东面，距离塔伦迪斯营地并不远。",al={"影歌神殿在哪里","影歌神殿位置","如何找到影歌神殿"}}},fp="17,306,16.538.0,26.158.0,30.170.0,26.242.0,28.131.0"}
P.entries["subzone:shadowthread-cave"] = {n="黑丝洞",s="黑丝洞是位于泰达希尔幽影谷西北部悬崖上的一处潮湿洞穴。这里传统上栖息着原生的Webwood蜘蛛，但最近在它们的虫母“Githyiss the Vile”的统治下，洞穴变得极其危险且富有攻击性。",h="黑丝洞是位于泰达希尔幽影谷西北部悬崖上的一处潮湿洞穴。这里传统上栖息着原生的Webwood蜘蛛，但最近在它们的虫母“Githyiss the Vile”的统治下，洞穴变得极其危险且富有攻击性。",kw={"githyiss the vile","幽影谷","黑丝洞","蜘蛛丝","泰达希尔","webwood蜘蛛"},ang={["class:Druid"]="黑丝洞中Webwood巢群无法遏制的攻击性对于德鲁伊来说是一个令人不安的信号，表明泰达希尔的自然和谐受到了严重的破坏。",["race:NightElf"]="对于年轻的暗夜精灵来说，清理黑丝洞并击杀Githyiss the Vile是他们保卫神圣家园免受腐蚀蔓延的最初考验之一。"},sec={{t="不安的巢群",b="黑丝洞隐匿在幽影谷的阴影边缘，长期以来一直是泰达希尔巨型蜘蛛的天然巢穴。早些年，这些节肢动物与世界之树的新生枝桠和谐共存。然而最近，它们的性情变得极具领地意识。厚厚的Webwood丝网如今充斥着石质走廊，而这些巢群的攻击性对于刚刚踏出奥达希尔的年轻kaldorei来说构成了直接的威胁。"},{t="Githyiss the Vile",b="潜伏在洞穴最深处的首要威胁是Githyiss the Vile，这是一只巨大的虫母，其凶猛程度远超普通的Webwood爬行者。新手暗夜精灵哨兵和德鲁伊被派往洞穴以遏制蜘蛛的泛滥并击杀Githyiss，确保泰达希尔野生生物所受到的腐蚀不会完全侵蚀幽影谷这片圣地。"}},faq={{q="黑丝洞位于哪里？",a="黑丝洞位于幽影谷的西北角，坐落在泰达希尔暗夜精灵新手谷边缘的岩石山坡旁。",al={"黑丝洞位置","黑丝洞在哪里","寻找黑丝洞"}},{q="为什么洞穴里的蜘蛛如此具有攻击性？",a="虽然蜘蛛一直栖息在洞穴中，但泰达希尔各地出现的一种邪恶疾病和日益加剧的不平衡已经使当地的野生生物陷入疯狂，使得Webwood蜘蛛变得异常狂暴。",al={"蜘蛛为什么具有敌意","黑丝洞的蜘蛛腐蚀","蜘蛛为什么攻击"}},{q="Githyiss the Vile是谁？",a="Githyiss the Vile是一只巨大的、有毒的Webwood蜘蛛虫母，盘踞在黑丝洞的最深处。她是威胁着幽影谷年轻kaldorei的那些极具攻击性的巢群的母亲。",al={"githyiss","githyiss是谁","黑丝洞蜘蛛首领"}},{q="尽管有危险，为什么这个洞穴很有价值？",a="洞穴里堆积着一层层厚实、天然纺成的Webwood丝，这是一种由栖息在黑暗洞室中无尽的节肢动物群所编织的珍贵且坚韧的制作材料。",al={"黑丝洞丝绸","幽影谷蜘蛛丝"}}},fx={["3bee1b1c"]={q="什么是黑丝洞？",a="黑丝洞是位于泰达希尔幽影谷西北部峭壁中的地下洞穴。它传统上是岛上林木蜘蛛的天然筑巢地，也是一个僻静巢穴，蛛类在此编织错综复杂的蛛网、养育幼蛛，远离世界之树的枝头。",al={"什么是黑丝洞","黑丝洞背景","黑丝洞"}},aa654c4e={q="谁住在黑丝洞里？",a="洞穴里几乎全是泰达希尔的原生林木蜘蛛。巢穴中心由体型巨大的母蛛吉提希斯统治，她指挥成群的蛛类，用密密麻麻的蛛网覆盖石壁。",al={"谁住在黑丝洞里","黑丝洞居民","黑丝洞里的蜘蛛"}}},fp="17,263,24.490.0,17.400.0,35.151.0,46.192.0,25.200.0,48.183.0"}
P.entries["subzone:shady-rest-inn"] = {n="树荫旅店",s="树荫旅店曾是一处温馨的驿站，由人类建造，坐落在贫瘠之地与塞拉摩岛之间的道路旁。如今，这里只剩下焦黑的木材和余烬，此前发生了一起突如其来的暴力纵火事件。这场悲剧令旅店老板心碎不已，并导致整个沼泽地区的局势变得紧张，调查人员仍在废墟中搜寻线索。",h="树荫旅店曾是一处温馨的驿站，由人类建造，坐落在贫瘠之地与塞拉摩岛之间的道路旁。如今，这里只剩下焦黑的木材和余烬，此前发生了一起突如其来的暴力纵火事件。这场悲剧令旅店老板心碎不已，并导致整个沼泽地区的局势变得紧张，调查人员...",kw={"纵火","贫瘠之地边界","尘泥沼泽","恐怖图腾","james hyal","paval reethe","树荫旅店","塞拉摩"},ang={["faction:Alliance"]="旅店的毁坏代表着通往塞拉摩岛的主要陆路交通遭到了严重的安全威胁，不仅威胁着往来的旅客，也加剧了对潜伏敌人的恐惧。",["race:Tauren"]="关于谁烧毁了旅店的猜疑，威胁着要破坏部落与Jaina Proudmoore在尘泥沼泽势力之间脆弱的和平。"},sec={{t="边界的灰烬",b="树荫旅店旨在为往来于尘泥沼泽和贫瘠之地之间危险路段的旅人提供服务，是这片荒凉之地中一处文明而舒适的据点。然而，随着旅店在一次毁灭性的大火中被夷为平地，这一切戛然而止。旅店老板James Hyal在大火中幸存，但他的妻子和孩子却不幸丧生。遭受创伤和悲痛的Hyal一无所有，而这片废墟成了犯罪现场，受到塞拉摩当局的严密调查，他们急于查明纵火的真凶。"},{t="疑云重重",b="最初的纵火调查指向人类逃兵和可疑士兵，Paval Reethe和Caldwell中尉等人都曾被列为重大嫌疑对象，但随后都遭遇了不幸。然而，从灰烬中发现的物证（包括独特的蹄印和仪式徽记）表明，这不仅仅是一次内部背叛。纵火行径是由冷酷无情的恐怖图腾牛头人实施的，他们从沼泽深处发动袭击，意在挑拨塞拉摩与其邻国之间的关系。"}},faq={{q="树荫旅店发生了什么？",a="旅店遭到袭击并被烧毁。起初人们怀疑是逃兵和流氓联盟士兵所为，调查人员仍在废墟中搜寻线索，以查明纵火的真正幕后黑手。",al={"为什么树荫旅店被烧","旅店发生了什么","谁烧毁了树荫旅店"}},{q="谁拥有并经营这家旅店？",a="James Hyal经营着树荫旅店。他在大火中幸存，但他的妻子和孩子在火海中丧生，这让他遭受了极大的创伤。",al={"树荫旅店老板","谁经营树荫旅店","james hyal"}},{q="树荫旅店位于哪里？",a="废墟位于尘泥沼泽西部的主要道路旁，就在沼泽与贫瘠之地交界的附近。",al={"树荫旅店位置","树荫旅店在哪里"}},{q="Paval Reethe和Caldwell中尉是谁？",a="他们是在火灾初步调查中被牵连的人类嫌疑人。两人都在调查人员获得供词或最终查明他们参与程度之前就死了。",al={"reethe是谁","树荫旅店 caldwell中尉","reethe和caldwell"}}},fp="14,361,19.565.0,18.526.1,36.201.1,31.136.0,36.126.0,45.200.1"}
P.entries["subzone:shalzaru-s-lair"] = {n="沙尔扎鲁的巢穴",s="沙尔扎鲁的巢穴是一处蔓延的深水洞穴，位于菲拉斯恐怖之岛的北端。它是仇恨之脊纳迦的一座主要据点，也是其强大的主人沙尔扎鲁的藏身处。这些蛇形入侵者在潮湿的隧道中策划着侵略行动，就在羽月要塞的南面。",h="沙尔扎鲁的巢穴是一处蔓延的深水洞穴，位于菲拉斯恐怖之岛的北端。它是仇恨之脊纳迦的一座主要据点，也是其强大的主人沙尔扎鲁的藏身处。这些蛇形入侵者在潮湿的隧道中策划着侵略行动，就在羽月要塞的南面。",kw={"羽月要塞","菲拉斯","仇恨之脊","恐怖之岛","纳迦洞穴","沙尔扎鲁","沙尔扎鲁的巢穴"},ang={["faction:Alliance"]="仇恨之脊在洞穴中的集结威胁到了羽月要塞的补给线和和平，这使得清除沙尔扎鲁和他的族群成为哨兵及其盟友的首要任务。",["race:NightElf"]="纳迦亵渎菲拉斯古老海岸遗迹的邪恶行径，痛苦地提醒着人们大分裂的往事，以及上层精灵堕落并变异为怪物的过程。"},sec={{t="浅滩中的蛇穴",b="沙尔扎鲁的巢穴开凿在恐怖之岛北端的崎岖悬崖中，分为一个巨大的主洞穴和一个较小的附属室，由淹没的地下水道相连。洞内遍布着保持高度警惕的仇恨之脊蛇卫和施法女巫。在深处居住着领主沙尔扎鲁，这位蛇形霸主指挥着整个岛上的仇恨之脊族群。它距离萨尔多岛很近，对驻扎在海峡对岸羽月要塞的暗夜精灵哨兵构成了直接且持续的威胁。"}},faq={{q="沙尔扎鲁的巢穴位于何处？",a="沙尔扎鲁的巢穴位于恐怖之岛的北端，该岛位于萨尔多岛和羽月要塞正南方的菲拉斯西海岸外。",al={"沙尔扎鲁的巢穴位置","沙尔扎鲁巢穴位置","如何找到沙尔扎鲁的巢穴"}},{q="沙尔扎鲁是谁？",a="沙尔扎鲁是一位强大的纳迦督军，也是栖息在恐怖之岛的仇恨之脊部族的主人。他从巢穴内被淹没的深处指挥着他的部队。",al={"沙尔扎鲁是谁","沙尔扎鲁背景故事","沙尔扎鲁的巢穴首领"}},{q="这座洞穴里居住着什么生物？",a="洞穴中到处都是仇恨之脊纳迦，主要是看守干燥路径的警惕的仇恨之脊蛇卫，以及在地下水域中引导魔法的仇恨之脊女巫。",al={"沙尔扎鲁的巢穴敌人","仇恨之脊纳迦洞穴怪物"}},{q="为什么这座巢穴对当地的暗夜精灵很重要？",a="因为恐怖之岛位于羽月要塞隔水相望的地方，沙尔扎鲁的巢穴内集结的纳迦部队对珊蒂斯·羽月的军队以及萨尔多岛的安全构成了直接的军事威胁。",al={"为什么暗夜精灵关注沙尔扎鲁","羽月要塞的纳迦威胁"}}},fp="15,343,29.575.0,33.177.0,16.176.0,33.185.0,52.245.0"}
P.entries["subzone:shaper-s-terrace"] = {n="塑造者之台",s="塑造者之台位于马绍尔营地上方的北部峭壁高处，是一处以古老泰坦建筑为标志的神秘观景台。它以塑造者卡兹格罗斯命名，默默见证了塑造安戈洛环形山的原始实验。",h="塑造者之台位于马绍尔营地上方的北部峭壁高处，是一处以古老泰坦建筑为标志的神秘观景台。它以塑造者卡兹格罗斯命名，默默见证了塑造安戈洛环形山的原始实验。",kw={"环形山","卡兹格罗斯","马绍尔营地","塑造者","塑造者之台","泰坦","安戈洛"},ang={["race:Dwarf"]="对于探寻自身泰坦血统的矮人来说，塑造者之台提供了又一个窥探卡兹格罗斯建筑风格和创造者宏伟杰作的迷人视角。"},sec={{t="泰坦的遗产",b="塑造者之台俯瞰着安戈洛环形山郁郁葱葱的史前盆地，保留着泰坦留下的宏伟石制建筑。据信此处是献给塑造者卡兹格罗斯的，这座高耸的平台见证了那些曾将环形山培育为艾泽拉斯早期生命活体实验室的星界建筑师。从这些高耸的石块上，古老的实体曾在此观察并引导下方的动植物。其冰冷的石拱门和巨大的金属基座与下方繁茂的原始荒野形成了鲜明而神秘的对比。"}},faq={{q="塑造者之台是什么？",a="塑造者之台是一处位于安戈洛环形山北部峭壁沿线、马绍尔营地正上方的高处泰坦遗迹。它拥有与曾经塑造这片土地的泰坦相关的石制建筑。",al={"塑造者之台","这是什么平台","安戈洛平台"}},{q="“塑造者”是谁？",a="该平台指的是塑造者卡兹格罗斯，他是帮助在遥远的过去创造和培育艾泽拉斯世界的泰坦创造者之一。",al={"塑造者是谁","卡兹格罗斯","谁建造了塑造者之台"}}},fp="16,272,22.577.0,29.204.0,21.143.0"}
P.entries["subzone:shatter-scar-vale"] = {n="碎痕谷",s="碎痕谷是位于费伍德森林中部的一片焦土盆地，就在血毒瀑布的正北方。它是第三次战争期间恶魔地狱火坠入卡利姆多北部的中心地带。时至今日，这些陨坑仍在燃烧着魔火，并残留着燃烧军团的余孽。",h="碎痕谷是位于费伍德森林中部的一片焦土盆地，就在血毒瀑布的正北方。它是第三次战争期间恶魔地狱火坠入卡利姆多北部的中心地带。时至今日，这些陨坑仍在燃烧着魔火，并残留着燃烧军团的余孽。",kw={"血毒瀑布","燃烧军团","陨坑","费伍德森林","地狱火","碎痕谷"},ang={["class:Druid"]="山谷中阴燃的伤痕是卡利姆多大地上久久未能愈合的创口，只要军团的构装体还在燃烧，它们就无法痊愈。",["class:Warlock"]="游荡在这些陨坑中的地狱火，其体内注入了邪能的核心，代表了军团入侵后留下的混乱魔法的强力传导源。"},sec={{t="地狱火的冲击",b="第三次战争期间，燃烧军团向卡利姆多北部投下了活体攻城武器。碎痕谷承受了这场天外打击的主要冲击。恶魔地狱火从天而降，撕裂了古老的树冠，在大地上砸出了深深的坑洞。猛烈的撞击摧毁了地形，留下了至今仍在燃烧着邪恶之火的焦黑深坑。尽管军团在海加尔山战败，但地狱火和残留的小型恶魔从未真正散去，始终在这片伤痕累累的土地上固守着据点。"}},faq={{q="为什么地面上到处都是陨坑？",a="这些陨坑是在第三次战争中形成的，当时燃烧军团用地狱火轰炸了这片森林。这些巨大的邪能石构体像流星一样从天而降，砸入地面，在山谷中留下了阴燃的撞击痕迹。",al={"费伍德森林的陨坑","为什么碎痕谷会有陨坑","是什么造成了陨坑"}},{q="碎痕谷里游荡着什么生物？",a="山谷中依然充斥着燃烧军团的构装体和仆从。活体地狱火仍守卫着阴燃的撞击坑，与入侵失败后留下的其他游荡的小型恶魔一起驻扎于此。",al={"这里有什么怪物","碎痕谷的敌人"}},{q="碎痕谷位于何处？",a="碎痕谷位于费伍德森林的中部区域，坐落在血毒瀑布的正北方，森林主路东侧。",al={"碎痕谷的位置","碎痕谷在哪里"}}},fp="17,294,23.559.0,37.260.0,38.214.0,35.153.0"}
P.entries["subzone:shattered-strand"] = {n="破碎海岸",s="破碎海岸是艾萨拉风暴海湾北缘的一片荒凉而崎岖的海岸线。这里巨浪拍岸，古老的遗迹随处可见，沙滩上到处都是危险的海洋野兽和部落制的海洋生物。",h="破碎海岸是艾萨拉风暴海湾北缘的一片荒凉而崎岖的海岸线。这里巨浪拍岸，古老的遗迹随处可见，沙滩上到处都是危险的海洋野兽和部落制的海洋生物。",kw={"艾萨拉","风暴海湾","九头蛇","麦克罗拉","鱼人","海巨人","破碎海岸","亚考兰神殿","埃达拉之塔"},ang={["class:Hunter"]="这片海岸提供了一个未驯服的试炼场，充满了强大的九头蛇和沿海野兽，非常适合那些寻找强大野兽或研究卡利姆多海岸掠食性动物群的冒险者。"},sec={{t="危险的海岸线",b="破碎海岸沿着风暴海湾的北缘延伸，绝非一片宁静的海岸。岩石遍布的沙滩和潮汐浅滩上栖息着大量的攻击性野生生物，包括高大的海巨人、多头九头蛇和凶猛的麦克罗拉，旁边还有沿海鱼人的营地。破碎的精灵建筑俯瞰着波涛，以古老的亚考兰神殿和孤耸的埃达拉之塔等地标为中心。对于在艾萨拉险峻的悬崖间穿行的旅行者来说，降落到这片孤立的海岸意味着要面对该地区最致命的某些两栖威胁。"}},faq={{q="破碎海岸位于哪里？",a="破碎海岸构成了风暴海湾的北岸，位于艾萨拉的东部地区，耸立在巨大的悬崖之下。",al={"破碎海岸位置","破碎海岸在哪里","破碎海岸地图"}},{q="哪些生物栖息在破碎海岸？",a="海岸线上到处出没着凶恶的九头蛇、巨大的海巨人、披甲的麦克罗拉以及成群结队的敌对鱼人，它们在潮滩上巡逻。",al={"破碎海岸怪物","破碎海岸生物","破碎海岸野兽"}},{q="在海滩上能发现哪些著名的遗迹？",a="海岸上有古老的上层精灵建筑，其中最著名的是亚考兰神殿，以及附近俯瞰海湾的埃达拉之塔。",al={"破碎海岸遗迹","破碎海岸建筑","破碎海岸地标"}},{q="破碎海岸适合随意探索吗？",a="不适合。海滩位置偏僻，由于周围悬崖峭壁林立，难以迅速逃离，而且挤满了掠食性水生野兽和强大的巨人。",al={"破碎海岸危险吗","破碎海岸等级"}}},fp="16,239,23.622.0,38.149.0,44.148.0,48.144.0,52.161.0"}
P.entries["subzone:shifting-mire"] = {n="流沙泥潭",s="流沙泥潭构成了悲伤沼泽那片广袤而泥泞的核心区域，位于泪水之池的西侧。它的名字源于浑浊水底那种奇异且不安分的淤泥，这些淤泥似乎受到某种无形力量的影响，不断漂移和堆积。",h="流沙泥潭构成了悲伤沼泽那片广袤而泥泞的核心区域，位于泪水之池的西侧。它的名字源于浑浊水底那种奇异且不安分的淤泥，这些淤泥似乎受到某种无形力量的影响，不断漂移和堆积。",kw={"鳄鱼","美洲豹","失落者","流沙泥潭","淤泥","悲伤织网蛛","悲伤沼泽"},ang={["class:Hunter"]="纠缠的灌木丛和漂移的水域使得追踪变得危险重重，这要求猎人们必须保持警惕，提防隐藏在叶丛中的隐秘沼泽美洲豹和剧毒的悲伤织网蛛。"},sec={{t="生机勃勃的沼泽",b="流沙泥潭横跨沼泽地带的中心区域，是一片令人不安的广阔地带，在这里很难找到坚实的立足点。沼泽底部的淤泥仿佛被一种活生生的意志所驱使，不断移动和聚集，这股意志是由渗透在泥炭中奇异的环境能量所驱动。在漂移的泥沼中，潜伏着捕食性的沼泽美洲豹、巨大的悲伤织网蛛和饥饿的锯齿鳄鱼，而被称为“失落者”的破碎德莱尼部族也在这些沉没的小径中徘徊。"}},faq={{q="为什么它被称为流沙泥潭？",a="该区域的名字源于沼泽底部那层极其细软的淤泥。不同于普通的沉积物，一股神秘的能量流使得这些泥土像是有生命一样在湿地中聚集、漂移和流动。",al={"流沙泥潭名字由来","为什么叫流沙泥潭","为什么地面会移动"}},{q="流沙泥潭里生活着什么生物？",a="这片泥潭中满是危险的野生动物，包括潜伏在浅滩的锯齿鳄鱼、在树枝间织网的巨型悲伤织网蛛，以及隐秘的沼泽美洲豹。这里也常有徘徊的失落者出没，他们是被家园流放并发生了扭曲的德莱尼人。",al={"流沙泥潭怪物","流沙泥潭有什么"}},{q="流沙泥潭位于哪里？",a="它涵盖了悲伤沼泽的中心地带，位于被誉为“泪水之池”的巨大湖泊正西侧。",al={"流沙泥潭位置","流沙泥潭在哪里"}}},fp="13,252,12.460.0,35.237.0,41.269.0,35.139.0"}
P.entries["subzone:shimmer-ridge"] = {n="闪光岭",s="闪光岭是一处坐落在丹莫罗北部的高地，位于铁炉堡大门正西方。这里被敌对的霜鬃巨魔占据，其岩石高地上有两个营地，由一座摇摇欲坠的桥连接。这里因是获取强效闪光草的唯一产地而闻名。",h="闪光岭是一处坐落在丹莫罗北部的高地，位于铁炉堡大门正西方。这里被敌对的霜鬃巨魔占据，其岩石高地上有两个营地，由一座摇摇欲坠的桥连接。这里因是获取强效闪光草的唯一产地而闻名。",kw={"丹莫罗","霜鬃巨魔","铁炉堡","登山者","闪光岭","闪光草","巨魔"},ang={["profession:Herbalism"]="虽然普通的植物很难在丹莫罗的零下气候中生存，但闪光岭却独一无二地支持着在霜鬃巨魔营地间培育的珍贵闪光草篮。",["race:Dwarf"]="闪光岭坐落在铁炉堡大门的阴影下，是一个令人恼火的提醒，时刻警示着持续存在的霜鬃巨魔威胁，同时也是矮人传奇烈性黑啤酒所需的优质闪光草的危险来源。"},sec={{t="霜鬃据点",b="Perched along the craggy slopes just west of Ironforge's mighty entryway, Shimmer Ridge serves as an active redoubt for the Frostmane troll tribe. Divided into twin camps straddling a chasm and linked by a wooden span, the enclave is heavily guarded by troll scavengers and their tamed mountain boars. Their proximity to the main roadway and the dwarven capital poses a continuous nuisance to travelers and mountain patrols, who must constantly remain on guard against opportunistic raids from the high ground."},{t="闪光草的代价",b="除了战略位置外，山岭还以种植闪光草而闻名，这种植物由霜鬃巨魔培育。当地矮人酿酒师非常看重这种药草，将其用于酿造强效且风味独特的高地麦酒，而这种药草在其他地方很难采摘。勇敢的登山者和新兵经常冒着遭遇霜鬃巨魔伏击和野兽袭击的危险，只为直接从巨魔的种植地采摘一篮篮珍贵的植物。"}},faq={{q="闪光岭在哪里？",a="闪光岭位于丹莫罗北部，就在通往矮人首都的巨大铁炉堡大门正西方。",al={"闪光岭位置","闪光岭在哪里","寻找闪光岭"}},{q="谁控制着闪光岭？",a="该山岭由当地的霜鬃巨魔部族占据，他们建立了两个由桥梁连接的营地，并与他们驯养的野猪一起保卫着这片高地。",al={"谁住在闪光岭","闪光岭的敌人","闪光岭的巨魔"}},{q="什么是闪光草，为什么要寻找它？",a="闪光草是一种独特的山地草药，生长在山岭寒冷的山坡上。当地矮人酿酒师非常珍视它，将其作为酿造特制、风味独特的高地麦酒的必备原料。",al={"闪光草用途","什么是闪光草","闪光草目的"}},{q="为什么矮人不彻底清除这些巨魔？",a="铁炉堡的军队忙于更广泛的防御和外部事务，使得丹莫罗当地的霜鬃巨魔据点等威胁只能由区域内的登山者和四处游荡的新兵来应对。",al={"为什么铁炉堡无视闪光岭","铁炉堡与霜鬃巨魔","矮人对闪光岭的反应"}}},fx={["92b9c418"]={q="什么是闪光岭？",a="闪光岭是丹莫罗北部的一片崎岖高地，位于宏伟的铁炉堡大门以西。这里危机四伏，由霜鬃巨魔盘踞；它们在高地上开辟了两处营地，并用一座木桥将其连接起来。除了巨魔战团和它们驯养的野猪，这里还以出产闪光草而闻名，这种功效强劲的本地植物深受附近的矮人酿酒师珍视。",al={"什么是闪光岭","闪光岭概况","介绍一下闪光岭"}},aaffe09f={q="闪光岭危险吗？",a="是的，对经验不足的旅行者而言，这里相当危险。盘踞在山脊上的霜鬃巨魔对外来者极具敌意，并严密守卫营地和闪光草丛。凶暴的巨魔守卫加上它们豢养和驯服的野猪，任何不加防备就登上高地的人都有可能很快被当地战团压制。",al={"闪光岭安全吗","闪光岭的危险","闪光岭有多危险"}},e59eca35={q="为什么叫闪光岭？",a="这个名字的由来已不可考。这座山岭以闪光草闻名，霜鬃巨魔会种植这种植物，矮人酿酒师则会寻找它来酿造麦酒。",al={"闪光岭名称由来","为什么叫闪光岭","闪光岭这个名字的由来"}}},fp="13,282,22.510.0,24.439.0,31.140.0,27.168.0,47.205.0,54.202.0"}
P.entries["subzone:shimmering-flats"] = {n="闪光平原",s="闪光平原是一片广阔的盐碱滩，位于千针石林的东南端，毗邻塔纳利斯沙漠。这里曾经是一个古老湖泊的湖床，如今这片被太阳炙烤的荒原以沙漠赛道的高速机械竞赛和凶猛的沙漠野兽而闻名。",h="闪光平原是一片广阔的盐碱滩，位于千针石林的东南端，毗邻塔纳利斯沙漠。这里曾经是一个古老湖泊的湖床，如今这片被太阳炙烤的荒原以沙漠赛道的高速机械竞赛和凶猛的沙漠野兽而闻名。",kw={"沙漠赛道","普兹克","锈锤","盐滩","闪光平原","其拉虫人","塔纳利斯","千针石林"},ang={["profession:Engineering"]="这片盐滩是工程师们的朝圣之地，到处都是废料、燃料实验品，以及在地精和侏儒机械师之间无休止的竞争下进行的高速载具试运行。",["race:Gnome"]="在沙漠赛道上，侏儒驾驶员和机械陆行鸟勇敢地捍卫着侏儒工程学的骄傲，对抗着地精对手那些不稳定且具有爆炸性的设计。"},sec={{t="盐滩与极速",b="闪光平原在耀眼的南方烈日下绵延开来，是一片广袤、植被稀疏的干涸湖床，点缀着被太阳晒白的龟骨，甚至还有一艘古代帆船的木质残骸。其平坦而连续的表面使它成为卡利姆多测试实验性载具的首选之地。平原中央坐落着沙漠赛道，侏儒和地精技师们在这里不断较量，看谁的火箭车、旋翼机和引擎能达到最高速度——这往往导致在这片白色地壳上留下火光冲天的坠毁残骸和冒烟的坑洞。"},{t="盐滩的危险",b="除了赛道上轰鸣的引擎声外，这片盆地远非宁静之地。坚硬的石化蜥蜴、好斗的蝎形虫和盘旋的秃鹫捕食着在这片开阔地上减速的任何生物。再往南，锈锤挖掘场周围的地面变得愈发危险。这里最初由矮人勘探者开采，后来遭到部落争夺。当鹤嘴锄凿穿地下隧道，释放出一群凶猛的其拉虫人涌入平原南缘时，该采石场被彻底废弃。"}},faq={{q="为什么沙漠中间会有一艘破船？",a="闪光平原曾经是一个巨大的内陆湖，早已干涸。平原北部那艘破损的船只正是那片古老水域的遗迹，是湖水蒸发并形成如今广阔盐滩后留下的残骸。",al={"闪光平原的船","盐滩上的船","千针石林的沉船"}},{q="为什么侏儒和地精会聚在一起？",a="平坦且连续的盐碱地壳为测试火箭车和尖端机械装置提供了完美的场地。当地的侏儒和地精并没有为了领土而争斗，而是建立了沙漠赛道来激发他们的技术对抗，无休止地在速度、工程学和鲁莽的勇气上试图胜过对方。",al={"赛道背景故事","他们为什么要赛车","盐滩上的侏儒和地精"}},{q="南部的矮人挖掘场发生了什么事？",a="锈锤挖掘场由矮人考古学家建立，但很快就遭到了由摩克塔·克林领导的部落突袭队的攻击。随后，挖掘者无意中凿穿了一个地下的其拉虫人巢穴，释放出的蜂群般的昆虫怪物将所有人驱逐，并占领了南部平原。",al={"锈锤挖掘场背景故事","锈锤挖掘场发生了什么","盐滩上的虫子"}},{q="穿过闪光平原的道路通向哪里？",a="沿着穿过盐滩的东南方向轨道走，可以直接通往通往广阔的塔纳利斯沙漠和中立港口加基森的山隘。",al={"闪光平原通往何处","如何前往塔纳利斯","塔纳利斯出口"}}},fx={a9a42c0c={q="什么是闪光平原？",a="闪光平原是一片广阔、白得刺眼的盐碱地，位于千针石林东南端，与塔纳利斯沙漠接壤。这里原本是湖床，如今已完全干涸，寸草不生。平坦辽阔的地面吸引发明家前来测试他们最疯狂的发明，凶猛的沙漠野兽也在龟裂的大地上游荡。",al={"什么是闪光平原","闪光平原传说","关于闪光平原"}},bc39548e={q="闪光平原危险吗？",a="尽管这里看起来荒凉，却相当凶险。盐壳蜥、蝎子和秃鹫等致命的本地捕食者在开阔的盆地中出没，而地精和侏儒赛车手驾驶的不稳定火箭车，以及测试事故，也让遍地都是燃烧的残骸。此外，最近南部地区一座地下异种虫巢穴破土而出，席卷了一处古老的矮人挖掘场。",al={"闪光平原危险吗","闪光平原的危险","闪光平原有多危险"}},b2b7f543={q="为什么叫闪光平原？",a="这个名字源自阳光照射在古老的结晶盐床上时产生的刺眼景象。白色干燥矿物结壳反射出强烈的光芒，在地平线上形成耀眼闪烁的海市蜃楼，从干涸的盆地各处都能看见，绵延数英里。",al={"为什么叫闪光平原","闪光平原名称由来"}}},fp="16,303,23.588.0,19.504.0,59.255.0,41.336.0,51.298.0,54.164.0"}
P.entries["subzone:shining-strand"] = {n="闪光湖岸",s="闪光湖岸是银松森林东侧紧邻洛丹米尔湖的一片狭长湖岸，从洛丹伦废墟向南一直延伸至奥特兰克山脉崎岖的山麓地带。浅滩上聚居着充满攻击性的邪鳍鱼人，使得这段湖岸成为了毫无经验的旅行者的险地。",h="闪光湖岸是银松森林东侧紧邻洛丹米尔湖的一片狭长湖岸，从洛丹伦废墟向南一直延伸至奥特兰克山脉崎岖的山麓地带。浅滩上聚居着充满攻击性的邪鳍鱼人，使得这段湖岸成为了毫无经验的旅行者的险地。",kw={"药剂师贝拉德","黎明岛","洛丹米尔湖","闪光湖岸","银松森林","邪鳍","狼人"},ang={["faction:Horde"]="这条湖岸提供了一条清晰但危险的通道，沿着洛丹米尔湖连接着银松森林的北部入口与通往奥特兰克山脉的道路。",["race:Undead"]="对于被遗忘者来说，闪光湖岸的邪鳍鱼人是皇家药剂师学会研究新瘟疫所需宝贵样本的来源。"},sec={{t="一片有争议的海岸",b="闪光湖岸沿着银松森林的东缘延伸，与烟波浩渺的洛丹米尔湖接壤。邪鳍鱼人部族在这片浅滩上建立了多个充满攻击性的定居点，对任何试图走湖畔道路的旅行者构成了致命威胁，而野性的狼人则在岸边后方的银松森林深处游荡。"},{t="炼金收获",b="除了位于洛丹伦和南部边境之间的战略位置外，闪光湖岸及其邻近水域还引起了皇家药剂师学会的早期关注。已故的药剂师贝拉德记录了关于从当地邪鳍鱼人身上采集的奇特硬化肿瘤的研究笔记，并推测它们发生突变的生理结构可以作为研制新瘟疫的宝贵催化剂，以供Sylvanas Windrunner新生的国家使用。"}},faq={{q="闪光湖岸位于哪里？",a="闪光湖岸是银松森林的东部湖岸，与洛丹米尔湖接壤。它起始于洛丹伦废墟以南，终止于将银松森林与奥特兰克山脉隔开的崎岖丘陵。",al={"闪光湖岸位置","闪光湖岸在哪里","银松海岸"}},{q="在闪光湖岸能发现什么威胁？",a="邪鳍鱼人在岸边拥有多个定居点并会攻击不慎的旅行者，而野性的狼人则在岸边的银松森林中出没。",al={"闪光湖岸怪物","闪光湖岸有什么","闪光湖岸敌人"}},{q="为什么皇家药剂师学会对这个地区感兴趣？",a="已故的药剂师贝拉德记录了当地的邪鳍鱼人身上带有具有独特生理特征的硬化肿瘤。学会认为这些增生物在他们持续进行的致命新瘟疫研究中是很有前景的成分。",al={"药剂师贝拉德","闪光湖岸瘟疫","新瘟疫肿瘤"}},{q="邪鳍是谁？",a="邪鳍是一个在闪光湖岸边建立了多个定居点的鱼人部族，这使得湖岸对毫无经验的旅行者来说非常危险。",al={"银松森林的鱼人在哪里","邪鳍位置","闪光湖岸鱼人"}}},fx={["1e20c8b8"]={q="什么是闪光湖岸？",a="闪光湖岸是银松森林沿洛丹米尔湖延伸的东岸。从洛丹伦废墟郊外一路向南延伸，直到银松森林与奥特兰克山脉之间的崎岖山丘。",al={"什么是闪光湖岸","闪光湖岸传说","湖岸在哪里"}},["59cd2470"]={q="闪光湖岸发生过什么？",a="湖岸一带遍布邪鳍鱼人的聚居地，对旅行者来说十分危险；而在湖岸之外的银松森林中，野生狼人也四处游荡。",al={"闪光湖岸的历史","湖岸发生过什么"}},["6739e2d5"]={q="闪光湖岸危险吗？",a="危险。具有攻击性的邪鳍鱼人占据着沿岸的聚居地，会袭击任何靠近水边的人；附近的树林里也有野生狼人出没。",al={"闪光湖岸危险吗","闪光湖岸的危险"}}},fp="14,318,21.354.0,18.433.1,36.238.0,48.155.0,60.241.0,21.156.0"}
P.entries["subzone:shrine-of-aessina"] = {n="艾森娜神殿",s="艾森娜神殿是一处隐秘在灰谷西南部森林中的神圣精灵地标，供奉着这位古老的自然与野生生物的森林之灵。它坐落在迈斯特拉岗哨与阿斯特兰纳之间，在地区边界摩擦日益加剧的环境下，这里是一片宁静的庇护所。",h="艾森娜神殿是一处隐秘在灰谷西南部森林中的神圣精灵地标，供奉着这位古老的自然与野生生物的森林之灵。它坐落在迈斯特拉岗哨与阿斯特兰纳之间，在地区边界摩擦日益加剧的环境下，这里是一片宁静的庇护所。",kw={"艾森娜","灰谷","阿斯特兰纳","卡多雷","迈斯特拉岗哨","自然神殿","艾森娜神殿","荒野之神"},ang={["class:Druid"]="作为供奉荒野活体之灵的古老圣所，对于那些致力于维护卡利姆多自然平衡的人来说，这座神殿具有极其深远的意义。",["race:NightElf"]="对于卡多雷而言，这座神殿代表了他们与灰谷本土灵魂数个世纪以来的和谐共处，而这种和谐现在不断受到外界入侵势力的威胁。"},sec={{t="深林之中的圣所",b="艾森娜神殿位于阿斯特兰纳以西，隐蔽于深林之中，供奉着那位象征着深林之心与灵魂的神秘荒野之神。世世代代以来，暗夜精灵及其林地盟友一直尊崇着这片宁静之地，远离繁忙的主路与自然进行沟通。然而，随着部落为了收集木材和建立据点而不断向灰谷推进，整个地区内这些神圣的土地正面临着和平的不确定性。"}},faq={{q="艾森娜是谁？",a="艾森娜是一位受人尊崇的古老自然之灵和荒野之神，与原始森林的核心息息相关。暗夜精灵和林地生物视她为自然的活化之魂，代表着原始的荒野。",al={"艾森娜背景故事","艾森娜是谁","艾森娜神殿女神"}},{q="艾森娜神殿位于哪里？",a="该神殿位于灰谷西南部，坐落在迈斯特拉岗哨的西南方，以及阿斯特兰纳定居点的西侧。",al={"艾森娜神殿位置","艾森娜神殿在哪里","寻找艾森娜神殿"}},{q="为什么这个地方对暗夜精灵很重要？",a="该神殿是供奉林地之灵的古老圣地。像这样的地点将暗夜精灵社会和德鲁伊传统与卡利姆多原始的荒野直接联系在了一起。",al={"艾森娜神殿的重要性","暗夜精灵圣地"}}},fx={a3085ee2={q="什么是艾森娜神殿？",a="艾森娜神殿是一处古老而神圣的林间圣地，坐落在灰谷西南部，位于迈斯特拉岗哨西南方、阿斯特兰纳以西。神殿供奉神秘的森林之灵、荒野之神艾森娜，四周环绕着幽深的荒野，宁静而神秘，映照出暗夜精灵与卡利姆多森林生灵之魂之间古老的羁绊。",al={"什么是艾森娜神殿","艾森娜神殿传说","关于艾森娜神殿"}},d41b0789={q="为什么叫艾森娜神殿？",a="神殿以艾森娜命名。她是一位行踪隐秘的荒野之神，深受暗夜精灵德鲁伊和林中居民敬仰。古老传说称她是幽深森林跳动的心脏；据说她的存在为卡利姆多最茂密的林地注入生机与静谧的神秘气息，因此这片僻静的林地自然成为供奉她的场所。",al={"为什么叫艾森娜神殿","艾森娜神殿名称由来"}},["5764d345"]={q="艾森娜神殿危险吗？",a="神殿本身是一处宁静的天然林间空地，但整个灰谷都危机四伏。受魔法庇护的森林中有些区域正遭受蔓延的腐化侵蚀，战歌氏族与暗夜精灵哨兵之间也时常爆发激烈的领地冲突，因此独自在幽深的森林中徘徊始终十分危险。",al={"艾森娜神殿危险吗","艾森娜神殿的危险","艾森娜神殿附近的威胁"}}},fp="17,295,29.432.0,15.208.0,39.121.0,49.188.0"}
P.entries["subzone:shrine-of-the-dormant-flame"] = {n="眠炎圣殿",s="眠炎圣殿坐落在试炼谷西北方的最高峰顶端，是一处深受部落萨满祭司尊崇的隐秘圣地。在孤独的守望者泰尔夫·祖拉姆的指引下，新晋者们会踏上艰险的攀登之路，以求与火焰元素沟通，证明他们的精神掌控力。",h="眠炎圣殿坐落在试炼谷西北方的最高峰顶端，是一处深受部落萨满祭司尊崇的隐秘圣地。在孤独的守望者泰尔夫·祖拉姆的指引下，新晋者们会踏上艰险的攀登之路，以求与火焰元素沟通，证明他们的精神掌控力。",kw={"call of fire","眠炎圣殿","杜隆塔尔","火焰图腾","圣殿","怒水河流域","泰尔夫·祖拉姆","试炼谷"},ang={["class:Shaman"]="每一位年轻的兽人和巨魔萨满都必须踏上这段艰苦的旅程，攀登至这座峭壁之巅，以点燃他们与火焰之间的精神联系，并赢得他们的火焰图腾。",["faction:Horde"]="这座孤立的圣殿隐藏在杜隆塔尔上方的群山之中，守护着古老的元素仪式，这对新部落的精神核心至关重要。"},sec={{t="试炼与火焰之巅",b="想要抵达眠炎圣殿，必须勇敢地穿越一条蜿蜒狭窄的小径，起点位于怒水河沿岸，即怒水河流域的西南边缘。山顶高踞于杜隆塔尔的红色峭壁之上，可以俯瞰周围的大片土地，但如果沿着悬崖行走时稍有不慎，便会坠入深渊。在这个宁静的避难所中，徘徊着泰尔夫·祖拉姆，这是一位负责监督神圣仪式的孤独隐士。对于进行“Call of Fire”试炼的兽人和巨魔萨满新晋者来说，圣殿的火盆就是他们的熔炉，他们必须在此利用被击败的元素生物留下的余烬点燃沉睡的煤炭，以此证明他们有能力与充满破坏力的火焰之灵沟通并保持敬畏。"}},faq={{q="如何才能抵达眠炎圣殿？",a="路径始于怒水河畔，位于怒水河流域的西南边缘，就在试炼谷的西北方。一条狭窄的山路盘旋在山峰周围，直接通往山顶。",al={"如何前往眠炎圣殿","眠炎圣殿路径","攀登眠炎圣殿山峰"}},{q="为什么这座圣殿对萨满祭司如此重要？",a="这座圣殿是一处神圣的场所，在此，部落的萨满学徒们能够学习如何理解并驾驭火焰元素。作为“Call of Fire”修行之旅的一部分，新晋者们必须前往这座山顶来准备仪式药剂，并点燃沉睡的火盆。",al={"眠炎圣殿的用途","萨满祭司为何要去这里","call of fire 圣殿"}},{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一位孤独的巨魔隐士，担任着圣殿守护者的职责。他指导年轻的萨满完成他们的试炼，调制火焰药剂以唤醒他们的精神视野，并考验他们的决心。",al={"泰尔夫·祖拉姆是谁","眠炎圣殿npc","圣殿守护者"}},{q="点燃火盆后会发生什么？",a="收集了所需仪式材料并击败了敌对火焰元素的萨满祭司，会将火焰余烬放入火盆中。这是一种祭品，旨在证明他们拥有驾驭狂暴火焰之灵的力量与纪律。",al={"眠炎圣殿的火盆","点燃火焰","圣殿火盆任务"}}},fx={["9edb20fb"]={q="什么是眠炎圣殿？",a="眠炎圣殿坐落在试炼谷西北方最高的山峰之巅，是部落萨满沟通灵界的圣地。那里只能沿着怒水河上方一条蜿蜒狭窄的小径抵达；新晋萨满必须点燃圣火盆，以证明自己拥有驾驭火元素的灵性力量。",al={"什么是眠炎圣殿","什么是眠炎神殿","杜隆塔尔的眠炎圣殿"}},["0def2f7d"]={q="眠炎圣殿发生过什么？",a="自从部落在杜隆塔尔定居以来，年轻的兽人和巨魔萨满便世代攀上这座狂风呼啸的山峰，接受试炼。在这里，试炼者会带来从击败的火元素身上取得的余烬，点燃山上的仪式火盆，以证明自己掌握了原始之火，并在守护者的见证下获得火焰图腾。",al={"眠炎圣殿的历史","眠炎圣殿的过往","眠炎神殿发生过什么"}},b2d73685={q="眠炎圣殿危险吗？",a="圣殿本身很平静，但前往那里的路途十分险峻。盘绕山崖的小径狭窄而令人眩晕，稍有不慎便会坠落到下方的岩石上，当场丧命。此外，在山巅召唤并束缚火元素需要全神贯注，否则就可能被火焰吞噬。",al={"眠炎圣殿的危险","眠炎神殿安全吗","这里危险吗"}},a82c700c={q="为什么叫眠炎圣殿？",a="这座山峰因圣火盆而得名。火盆平时冰冷而沉寂，只有值得信赖的萨满才能将它唤醒。火焰仍在沉睡，等待着从元素战斗中赢得的余烬将其点燃；只有在火焰试炼中受到召唤时，它才会熊熊燃起。",al={"为什么叫眠炎","眠炎圣殿名称由来","为什么叫眠炎圣殿"}}},fp="27,297,27.723.0,49.218.0,39.242.0,19.211.0,41.245.0"}
P.entries["subzone:shrine-of-the-fallen-warrior"] = {n="战士之魂神殿",s="战士之魂神殿坐落于十字路口以西的一处偏僻山脊上，是一座静谧的纪念碑，俯瞰着贫瘠之地广袤的红色稀树草原。纪念碑上有一块刻有“MK”首字母的石基，旁边躺着一名阵亡的兽人战士，并由一位名为Koiter的灵魂医者温柔地守护着。",h="战士之魂神殿坐落于十字路口以西的一处偏僻山脊上，是一座静谧的纪念碑，俯瞰着贫瘠之地广袤的红色稀树草原。纪念碑上有一块刻有“MK”首字母的石基，旁边躺着一名阵亡的兽人战士，并由一位名为Koiter的灵魂医者温柔地守护着。",kw={"贫瘠之地","十字路口","koiter","纪念碑","michel koiter","战士之魂神殿","twincruiser"},ang={["class:Warrior"]="各个种族的战士经常会静静地朝圣这座山丘，向一位在成为传奇之前英勇作战、随后阵亡的战友致敬。",["faction:Horde"]="这处静谧的安息之所坐落在部落领地的中心地带，展现了卡利姆多萨满与战士传统核心中的荣誉、职责与牺牲精神。"},sec={{t="寂静的守望",b="战士之魂神殿深藏于十字路口西北方的高山上，在贫瘠之地尘土飞扬、危机四伏的环境中，它是一处格外肃穆的避难所。想要找到它，旅行者必须沿着山顶西南方蜿蜒的山脊小径攀登，直到抵达一个平缓的土丘。山顶上矗立着一座雕刻过的石碑，石基上刻着“MK”的首字母。碑前躺着一具穿着盔甲的兽人战士遗体，一位名为Koiter的灵魂医者日夜守护于此。这里没有战斗的号角，只有为了纪念一位曾经行走在卡利姆多大地上的勇士而进行的静默沉思。"},{t="纪念碑的意义",b="在游戏世界中，这座神殿是向一位部落已故勇士致以永恒敬意的纪念，他的灵魂在灵魂的照拂下长存。在现实中，这座纪念碑是游戏美术团队为了纪念Michel Koiter而创作的深情致敬，他是一位备受爱戴的插画师，在游戏开发期间不幸离世。沉睡的战士正是以Koiter自己的测试版角色“Twincruiser”为原型塑造的，让他的身影在卡利姆多开阔的天空下永垂不朽。"}},faq={{q="战士之魂神殿位于哪里？",a="该神殿位于贫瘠之地北部，十字路口以西的一座小山上。旅行者可以通过寻找高地西南方的山脊底部，并沿着蜿蜒的小路向上走，即可到达那片草丘。",al={"神殿位置","神殿在哪里","如何前往战士之魂神殿"}},{q="躺在石基上的兽人是谁？",a="在游戏中，他代表着一位备受尊敬的阵亡战士。在现实中，他是直接以Twincruiser为原型塑造的，那是已故暴雪美术师Michel Koiter在早期开发阶段所扮演的兽人战士角色。",al={"死去的兽人是谁","阵亡战士的身份","twincruiser"}},{q="石碑上刻的“MK”代表什么意思？",a="卢恩字母首字母缩写“MK”是为了纪念Michel Koiter，他是一位在2004年游戏开发期间离世的资深美术师。",al={"mk首字母","mk代表什么","石头上的字母"}},{q="站在神殿旁边的灵魂医者是谁？",a="这位灵魂医者的名字叫Koiter。与普通只在灵魂死亡时才显现的灵魂医者不同，Koiter始终在此守望，任何跋涉上山的活着的漫游者都能清楚地看到他。",al={"灵魂医者koiter","神殿的天使","幽灵是谁"}},{q="与这座神殿相关的任务吗？",a="没有。战士之魂神殿不属于任何任务线或阵营冲突的一部分。它仅仅作为一个肃穆的沉思、怀念与致敬之地而存在。",al={"神殿任务","战士之魂神殿的任务","这里有任务吗"}}},fx={["7e92bc4e"]={q="什么是战士之魂神殿？",a="战士之魂神殿是一座宁静而庄严的纪念圣地，坐落在十字路口以西的一座高山之上。这里有一座精雕细琢的石台，上面安放着一位受人敬仰的兽人战士；一座方尖碑和一名幽灵守卫守护着石台。艾泽拉斯各地的旅行者都会来到这里，在远离贫瘠之地纷争的地方静静致敬。",al={"什么是战士之魂神殿","贫瘠之地的战士之魂神殿","贫瘠之地山上的纪念碑"}},a34bf1b4={q="战士之魂神殿危险吗？",a="不危险。神殿是一处神圣的圣地，不受敌对生物或交战阵营侵扰。尽管下方的贫瘠之地遍布徘徊的野兽、刺背野猪人和敌对士兵，但山顶的纪念地始终宁静祥和，任何登上山顶的旅行者都能在此安然停留。",al={"战士之魂神殿安全吗","神殿危险吗","神殿里的敌人"}}},fp="28,327,14.608.0,27.487.0,50.210.0,37.199.0,46.121.0,52.209.0,49.162.0"}
P.entries["subzone:si-7-stormwind-city"] = {n="SI:7 (Stormwind City)",s="这座不起眼的石砌庄园位于Old Town的东角，是暴风城王国精英情报和间谍机构——军情七处（SI:7）的总部所在地。在那扇沉重的大门后，间谍大师马迪亚斯·肖尔和他的高级特工们静静地监视着威胁王国的敌人，协调着遍布王国各地的卧底特工。",h="这座不起眼的石砌庄园位于Old...",kw={"军营","迪菲亚","间谍活动","mathias shaw","old town","潜行者","军情七处","si:7","间谍大师","暴风城"},ang={["class:Rogue"]="对于联盟的潜行者来说，SI:7建筑是一个至关重要的职业中心，提供高级职业训练、毒药补给以及直接来自间谍大师马迪亚斯·肖尔的秘密任务。",["faction:Alliance"]="作为暴风城防御体系中不可见的基石，SI:7的情报网络为联盟军队提供了应对王座威胁的关键侦察信息。"},sec={{t="王国间谍活动的核心",b="对于Old Town的普通路人来说，这座坚固的石砌建筑看起来与普通的庄园或军营没什么两样。但事实上，它是暴风城情报局第七处（SI:7）的指挥中枢。在马迪亚斯·肖尔大师的领导下，SI:7负责收集情报、进行监视并执行隐秘行动，以保护王国免受颠覆。当城市卫兵在鹅卵石街道上巡逻，皇家卫兵守卫着Stormwind Keep时，SI:7在暗处工作，训练联络员并派遣隐秘特工去应对外国敌人、破坏者以及国内的动荡。"},{t="阴影中的警惕之眼",b="随着国王瓦里安·乌瑞恩离奇失踪，迪菲亚潜行者在西部荒野和暮色森林制造混乱，总部内始终回荡着忙碌的秘密活动。来自人类领地深处的深潜侦察兵不断将情报汇入这座建筑。在底层的地窖和武器林立的训练室中，致命的技术被不断完善，任务被分配出去，在威胁到达小国王的王座厅之前就将其消灭。"}},faq={{q="什么是SI:7？",a="SI:7代表暴风城情报局第七处。它是为暴风城王权服务的一流秘密间谍、侦察和刺杀机构。",al={"什么是军情七处","谁是军情七处","军情七处含义"}},{q="谁在暴风城领导SI:7？",a="马迪亚斯·肖尔大师在建筑内领导着该组织。Mathias Shaw负责监督王权所有的外勤任务、情报网络和战略侦察。",al={"谁是军情七处的领导","军情七处首领","谁管理军情七处"}},{q="这座建筑位于城中的什么位置？",a="总部位于Old Town，坐落在该区的东南部边缘，靠近运河和训练场。",al={"军情七处在哪里","军情七处位置","如何前往军情七处"}},{q="为什么SI:7对西部荒野如此感兴趣？",a="SI:7负责追踪整个暴风城领土内的颠覆活动，而迪菲亚潜行者代表了王国境内最危险的暴动势力。",al={"迪菲亚潜行者与军情七处","为什么军情七处监视迪菲亚"}}},fx={["3c33de19"]={q="军情七处危险吗？",a="对于忠于暴风城的公民和盟友来说，军情七处并不构成威胁。在其内部，王国的秘密情报网络负责训练和协调特工。不过，若是与他们为敌或威胁王权，你就会发现，他们的大师级盗贼、斥候和刺客是东部王国最致命的对手之一。",al={"军情七处危险吗","军情七处的危险","军情七处安全吗"}}},fp="21,345,32.605.0,29.438.1,13.159.0,28.175.0,43.127.0,38.157.0"}
P.entries["subzone:silver-stream-mine"] = {n="银泉矿洞",s="银泉矿洞是一座位于洛克莫丹北部的废弃矮人矿洞，坐落在奥加兹岗哨和巨石水坝之间。这里曾经是铁炉堡王国的一处富饶银矿脉，在矿藏枯竭后，这片挖掘出的空洞被重新规划为矿工同盟的补给仓库，随后被害虫占领。如今，隧道鼠狗头人蹲守在矿道内，囤积着偷来的装备和稀有的矿物珍品。",h="银泉矿洞是一座位于洛克莫丹北部的废弃矮人矿洞，坐落在奥加兹岗哨和巨石水坝之间。这里曾经是铁炉堡王国的一处富饶银矿脉，在矿藏枯竭后，这片挖掘出的空洞被重新规划为矿工同盟的补给仓库，随后被害虫占领。如今，隧道鼠狗头人蹲守在矿...",kw={"充能裂隙宝石","狗头人","洛克莫丹","矿工同盟","银泉矿洞","隧道鼠"},ang={["class:Mage"]="法师学徒们深入危险的、狗头人出没的矿道，专门为了采集充能裂隙宝石，这是制作仪式服装不可或缺的原料。",["race:Dwarf"]="对于矮人来说，银泉矿洞是一项来之不易的基础设施的令人恼火的损失，笨拙的狗头人现在玷污了受人尊敬的铁炉堡矿工同盟仓库。"},sec={{t="从富矿脉到储藏仓库",b="银泉矿洞曾流淌着珍贵的矿石，为铁炉堡的白银储备做出了巨大贡献。久而久之，矮人的鹤嘴锄挖掘得足够深，耗尽了主要矿脉，将这片广阔的矿室变成了一座空荡荡的地下建筑群。矿工同盟没有放弃这些来之不易的工程，而是将矿井改造成了一个安全的储藏仓库，用于存放工具、采矿箱和区域性设备。这里也是目前已知的稀有充能裂隙宝石的唯一产地，吸引着那些寻找精致裁缝材料的好奇奥术师们。"},{t="狗头人的入侵",b="这个安静的仓库没能安全太久。好斗的隧道鼠狗头人被无人看管的工具、蜡烛油和被遗忘的地下缝隙的气味所吸引，成群结队地涌入了矿井。矿工同盟的管理员们很快就被赶到了洛克莫丹的寒风中。现在，狗头人们以近乎狂热的劲头守卫着偷来的矮人板条箱，而在后门外，破损的兽人投石车和马车被遗忘在那里，静静地诉说着往昔的边境冲突。"}},faq={{q="银泉矿洞最初的用途是什么？",a="它最初是由铁炉堡的矮人开采的一座高产银矿。在矿脉枯竭后，铁炉堡矿工同盟将这些空旷的地下大厅改造成了存放工具和挖掘物资的仓库。",al={"银泉矿洞是什么","银泉矿洞历史","银泉矿洞的建造原因"}},{q="谁目前占据着这座矿洞？",a="这座矿洞已经被隧道鼠狗头人彻底占领了。他们赶走了矮人管理员，现在守卫着矿道，囤积着同盟废弃的补给箱，并挖掘着残余的矿渣。",al={"谁住在银泉矿洞","银泉矿洞怪物","银泉矿洞里有什么"}},{q="为什么法师要前往银泉矿洞？",a="这座矿洞是目前已知的充能裂隙宝石的唯一产地。这种不稳定的、具有魔法反应的宝石受到联盟奥术师的追捧，用以编织强大的附魔长袍。",al={"银泉矿洞法师任务","充能裂隙宝石","银泉矿洞法师长袍"}},{q="矿洞后面的破损投石车是什么？",a="矿洞后面停放着损坏的兽人马车和破烂的投石车，这是早期战争冲突的风化残骸，那些冲突曾威胁到连接洛克莫丹和北部山口的通道。",al={"银泉矿洞后的兽人马车","洛克莫丹矿洞破损投石车","洛克莫丹的部落攻城武器"}}},fx={fbe48c53={q="什么是银泉矿洞？",a="银泉矿洞是一处废弃的矮人挖掘场，坐落在洛克莫丹北部的山崖间，位于奥加兹岗哨以东、巨石水坝西南方。这里曾是铁炉堡矮人开采的富饶银矿，后来被改作矿工联盟的补给仓库，最终落入敌对势力之手。",al={"银泉矿洞信息","什么是银泉矿洞","关于银泉矿洞"}},["6efdd539"]={q="银泉矿洞为什么被废弃？",a="很久以前，银矿脉枯竭后，矿洞便不再继续开采。矿工联盟仍将这些隧道用作有守卫的储藏仓库，但凶残的隧道鼠狗头人蜂拥而至，抢夺洞内剩余的资源，矮人矿工因此被彻底赶走。",al={"银泉矿洞为什么被废弃","矮人为什么离开银泉矿洞","银泉矿洞为何被废弃"}},["339be7ce"]={q="银泉矿洞危险吗？",a="危险。矿洞已被敌对的隧道鼠狗头人彻底占据。这些地下害虫领地意识极强，拼命囤积矿洞里的东西，会攻击任何胆敢靠近入口或深入洞穴的旅行者和矿工。",al={"银泉矿洞危险吗","银泉矿洞里的威胁","银泉矿洞里的怪物"}}},fp="18,394,31.556.0,20.490.0,52.233.0,32.202.0,42.169.0,46.195.0"}
P.entries["subzone:silverwind-refuge"] = {n="银风避难所",s="银风避难所是坐落在灰谷中南部的一处宁静的暗夜精灵定居点，位于密斯特拉湖正北。在哨兵的保护下，这里为行走在林间小径上的旅人们提供了一处温馨的避风港。",h="银风避难所是坐落在灰谷中南部的一处宁静的暗夜精灵定居点，位于密斯特拉湖正北。在哨兵的保护下，这里为行走在林间小径上的旅人们提供了一处温馨的避风港。",kw={"灰谷","伊瑞斯湖","密斯特拉湖","暗夜精灵","哨兵","银风避难所"},ang={["faction:Alliance"]="对于穿行在灰谷的联盟旅者来说，银风避难所提供了一个可靠的营地，让他们可以休息、补充补给并精进荒野贸易技能，而不必大老远赶去阿斯特兰纳。",["profession:Herbalism"]="该避难所是灰谷采集者的一处重要停靠点，周围环绕着密斯特拉湖丰富的植被，并提供现场的草药学训练。"},sec={{t="林地圣所",b="银风避难所坐落在平静的密斯特拉湖与北面的伊瑞斯湖之间，与阿斯特兰纳一样，是灰谷中部主要的暗夜精灵中转站之一。这里有教授草药学、炼金术、剥皮和狩猎的工匠与荒野训练师。在坚定的哨兵守卫下，这处避难所成为了盟友们穿梭在阴郁古木林中时的安宁休憩点。"}},faq={{q="谁控制着银风避难所？",a="银风避难所是一个联盟定居点，由暗夜精灵建造并维护。这里由哨兵严密守卫，保护着这片宁静的土地。",al={"谁拥有银风避难所","银风避难所是联盟还是部落","谁住在银风避难所"}},{q="银风避难所位于何处？",a="它位于灰谷的中南部，位置在密斯特拉湖正北、伊瑞斯湖以南。",al={"银风避难所位置","银风避难所在哪","如何前往银风避难所"}},{q="避难所有什么服务？",a="旅人们可以在这里找到贸易供应商，以及提供草药学、炼金术、剥皮和猎人技能指导的专业训练师。",al={"银风避难所有什么","银风避难所训练师","银风避难所供应商"}}},fx={["18c4c00c"]={q="什么是银风避难所？",a="银风避难所是位于灰谷中南部的一处宁静的暗夜精灵哨站，就在密斯特拉湖以北。它与阿斯特兰纳并列，是联盟在该地区的重要据点之一。这里有工匠和训练师，并由哨兵严密守护。",al={"银风避难所是什么","银风避难所背景","银翼哨站"}},["86e68a41"]={q="谁住在银风避难所，或由谁管理？",a="避难所里住着暗夜精灵商人和猎人，由阿斯特兰纳的哨兵忠诚守卫。草药师、炼金师、剥皮师和驯兽师在此安居，照料穿行于古老森林的旅人。",al={"谁住在银风避难所","银风避难所的居民","银风避难所里有哪些人"}},["099e4cfb"]={q="银风避难所危险吗？",a="对联盟成员而言，银风避难所是一处安全的庇护所，有警惕的哨兵守卫。然而，对部落闯入者来说，卫兵会一发现他们便发动猛烈攻击，以确保这片森林中的安全之地不受侵扰。",al={"银风避难所安全吗","银风避难所的危险","银风安全吗"}}},fp="17,225,18.427.0,31.159.0,35.107.0,38.138.0"}
P.entries["subzone:silverwing-grove"] = {n="银翼树林",s="银翼树林坐落在灰谷中南部，靠近坠星湖，是银翼要塞的集结地。在这个堡垒般的林中空地，暗夜精灵战士召集联盟部队，以击退正在森林中大肆砍伐的战歌氏族伐木工。",h="银翼树林坐落在灰谷中南部，靠近坠星湖，是银翼要塞的集结地。在这个堡垒般的林中空地，暗夜精灵战士召集联盟部队，以击退正在森林中大肆砍伐的战歌氏族伐木工。",kw={"灰谷","坠星湖","哨兵艾蒂亚·轻歌","银翼树林","银翼要塞","战歌峡谷"},ang={["faction:Alliance"]="这座树林是联盟勇士召集并进入战歌峡谷惨烈战斗的主要集结地。",["race:NightElf"]="对于卡多雷来说，银翼树林代表了他们誓要阻止战歌氏族的战斧亵渎神圣树木的坚定决心。"},sec={{t="森林战争的前线",b="银翼树林隐藏在银翼哨站西南方向的翡翠树冠之下，是银翼要塞至关重要的军事集结哨所。它并非一处宁静的林地避风港，而是暗夜精灵在战歌峡谷抵御部落伐木行动的残酷领土争夺战中的作战核心。联盟的高级军官、补给品和侦察兵汇集于此，组织小规模冲突并召集勇士，保卫古老的灰谷免受兽人的扩张威胁。"}},faq={{q="银翼树林的作用是什么？",a="银翼树林是银翼要塞的集结基地。暗夜精灵军队和他们的联盟盟友在这里组织行动，以对抗战歌氏族的乱砍滥伐，并由此进入战歌峡谷参与持续不断的冲突。",al={"银翼树林为什么在这里","什么是银翼树林","银翼树林的作用"}},{q="银翼树林在哪里？",a="它位于灰谷中南部，坐落在银翼哨站西南方，紧邻坠星湖以西。",al={"银翼树林的位置","银翼树林在哪里","如何找到银翼树林"}},{q="谁在银翼树林中进行活动？",a="这座树林由银翼要塞负责驻守，同时还有联盟军事指挥官、联盟准将、后勤商人和诸如哨兵艾蒂亚·轻歌等协调对抗部落行动的军官。",al={"谁在银翼树林","银翼树林的npc","谁管理银翼树林"}},{q="部落玩家可以进入银翼树林吗？",a="不能。这座树林是一个活跃的军事哨所，驻扎着敌对的联盟哨兵和卫兵，他们会立即攻击任何入侵的部落成员。",al={"银翼树林是敌对的吗","部落可以去银翼树林吗","部落 银翼树林"}}},fx={["92f0e5de"]={q="什么是银翼树林？",a="银翼树林是位于灰谷中南部的一处设防暗夜精灵聚居地，也是银翼要塞的主要前线基地。哨兵以这处林荫掩护的据点为依托，组织联盟部队，并协调他们在邻近的战歌峡谷与战歌氏族持续交战。",al={"银翼树林是什么","银翼树林背景","关于银翼树林"}},e4f50e36={q="银翼树林危险吗？",a="对联盟勇士而言，银翼树林是一处由经验丰富的哨兵和指挥官严密守卫的庇护所。然而，对部落入侵者来说，这里危机四伏。作为对抗战歌氏族的主要集结地，树林的守军会一发现部落闯入者便将其击倒。",al={"银翼树林安全吗","银翼树林的危险","银翼树林面临的威胁"}}},fp="16,273,28.504.0,40.250.0,34.116.0,37.228.0,41.159.0"}
P.entries["subzone:silverwing-outpost"] = {n="银翼哨站",s="银翼哨站是位于灰谷中南部，弗伦河以东的一座防御严密的暗夜精灵驻地。它由杜瑞尔·月火指挥，是联盟在这一争议林地中抵御部落的最东端堡垒。",h="银翼哨站是位于灰谷中南部，弗伦河以东的一座防御严密的暗夜精灵驻地。它由杜瑞尔·月火指挥，是联盟在这一争议林地中抵御部落的最东端堡垒。",kw={"灰谷","杜瑞尔·月火","弗伦河","银翼哨站","银翼要塞","碎木岗哨","托雷克"},ang={["faction:Alliance"]="银翼哨站作为你在河对岸的重要前哨据点，牵制着从碎木岗哨向外扩张的兽人势力。",["faction:Horde"]="对于部落来说，该哨站是碎木岗哨心腹之患，直接阻碍了你在灰谷南部的行动和补给线。"},sec={{t="弗伦河以东",b="银翼哨站位于碎木岗哨西南方，紧邻贫瘠之地边境线以北，其战略位置极其险要。由于地处弗伦河东岸——这一区域受到部落的激烈争夺与巡逻——该哨站成为了暗夜精灵在森林深处领地的直接屏障。杜瑞尔·月火和她的银翼要塞部队始终面临着附近兽人的持续围攻，这些兽人誓要将暗夜精灵势力从该地区彻底清除。"},{t="永恒的前线",b="围绕银翼哨站的冲突是灰谷中最激烈的。以碎木岗哨为基地的兽人战争小队（例如托雷克率领的劫掠者）不断对哨站的城墙发动突袭。对于部落而言，清除这个哨站是确保道路安全、在不受哨兵部队持续反击威胁的情况下扩展资源开采行动的关键。"}},faq={{q="银翼哨站位于何处？",a="它位于灰谷中南部，碎木岗哨西南方，贫瘠之地边境线以北，且处于弗伦河的东岸。",al={"银翼位置","银翼在哪里","银翼哨站地图"}},{q="谁在指挥银翼哨站？",a="该哨站由杜瑞尔·月火指挥，这是一名统领银翼要塞部队、负责保卫森林东部边陲的暗夜精灵军官。",al={"银翼指挥官","谁领导银翼哨站","杜瑞尔·月火"}},{q="为什么部落如此猛烈地攻击这个哨站？",a="银翼哨站直接坐落在弗伦河东岸，靠近碎木岗哨。它的存在使哨兵部队能够切断部落的补给线，并直接威胁兽人在灰谷的行动。",al={"为什么要攻击银翼","部落对银翼的兴趣","碎木岗哨与银翼的冲突"}},{q="什么是银翼要塞部队？",a="银翼要塞部队是一个由暗夜精灵战士和女猎手组成的军事组织，致力于保护灰谷免受侵犯，特别是对抗不断扩张的伐木场和部落的战争小队。",al={"什么是银翼部队","银翼要塞部队背景","银翼阵营"}}},fx={["478d573a"]={q="什么是银翼哨站？",a="银翼哨站是灰谷最东端的联盟军事据点，建来抵御部落，守护暗夜精灵的土地。它位于弗伦河对岸、碎木岗哨西南方，是一处至关重要的前线驻军地，银翼要塞的哨兵在此阻遏部落从贫瘠之地和战歌伐木营地向外扩张。",al={"银翼哨站是什么","银翼哨站的用途","关于银翼哨站"}},ad619a65={q="银翼哨站危险吗？",a="这里是活跃的战区。哨站孤悬在弗伦河东岸，持续遭到附近战歌兽人和来自碎木岗哨的劫掠队袭击。联盟旅人可以在城墙后找到庇护和武装守卫；而部落部队则会遇到警惕且敌对的哨兵，他们一发现敌人便会放箭。",al={"银翼哨站危险吗","银翼哨站面临的威胁","银翼哨站的危险"}},b348ef17={q="为什么叫银翼哨站？",a="这座驻军地直接以银翼要塞命名。银翼要塞是一支精锐的暗夜精灵军队，驻扎于此，负责守护灰谷并遏制部落越界砍伐木材。",al={"为什么叫银翼哨站","银翼哨站名称由来","银翼的含义"}}},fp="18,248,21.501.0,18.384.1,36.150.0,32.142.0,55.217.0,33.213.0"}
P.entries["subzone:sishir-canyon"] = {n="希塞尔山谷",s="希塞尔山谷是石爪山脉中一条崎岖的峡谷，向东穿过了嶙峋的山峰。这里不仅布满了可怕的深苔蜘蛛和厚重的蛛网，还是前往埃雷萨废墟的危险通道。踏入这片纠结深渊的旅者必须面对剧毒蜘蛛以及它们那正在孵卵的蛛后。",h="希塞尔山谷是石爪山脉中一条崎岖的峡谷，向东穿过了嶙峋的山峰。这里不仅布满了可怕的深苔蜘蛛和厚重的蛛网，还是前往埃雷萨废墟的危险通道。踏入这片纠结深渊的旅者必须面对剧毒蜘蛛以及它们那正在孵卵的蛛后。",kw={"贝瑟雷斯","深苔","埃雷萨","希塞尔山谷","蜘蛛","石爪","蛛网"},ang={["class:Hunter"]="危险的蛛网和剧毒的深苔蜘蛛使希塞尔山谷成为了猎人们的艰巨试炼场，让他们在此狭窄的峡谷环境中磨练追踪与捕捉野兽的技巧。",["race:NightElf"]="被占据的峡谷阻断了通往埃雷萨祖先遗迹的安全便捷通道，使得卡多雷哨兵和学者们必须穿过密集的蜘蛛巢穴，才能到达属于他们的文化遗产。"},sec={{t="蛛网通道",b="希塞尔山谷从石爪山脉的山路分支而出，是一条通往古老埃雷萨废墟的险恶天然走廊。这道峡谷并非平静的山间小径，而是早已被深苔蜘蛛彻底占领。黏稠的蛛丝和成堆的卵囊覆盖了石地与岩壁，将这道峡谷变成了一个活生生的巢穴。试图前往前方暗夜精灵遗迹的旅者和哨兵，必须杀出一条血路，穿过成群结队的攻击性织网蛛。"},{t="贝瑟雷斯的领地",b="潜伏在峡谷最深处的是深苔蛛群庞大而致命的族长——贝瑟雷斯。她的剧毒和巨大的体型，让任何试图通过此通道的人都感到恐惧。石爪山脉的当地势力对这座峡谷保持着警惕，警告冒险者们，进入那些布满蛛网的深处不仅意味着要面对零散的蜘蛛，还要面对守护蛛群的顶级掠食者。"}},faq={{q="什么是希塞尔山谷？",a="希塞尔山谷是位于石爪山脉中一处被蜘蛛占据的峡谷，它从主要山路蜿蜒延伸至古老的埃雷萨废墟。",al={"希塞尔山谷在哪里","希塞尔山谷位置"}},{q="峡谷里居住着什么生物？",a="这座峡谷被捕食性的深苔蜘蛛完全占据。这些蛛形生物在峡谷中覆盖了厚厚的蛛网和卵囊，捕食着任何进入它们领地的生物。",al={"希塞尔山谷中的怪物","石爪峡谷中的蜘蛛"}},{q="贝瑟雷斯是谁？",a="贝瑟雷斯是栖息在希塞尔山谷深处的强大蛛后。她统领着深苔蛛群，是该地区对过往旅者最大的威胁。",al={"贝瑟雷斯位置","希塞尔山谷巨型蜘蛛"}},{q="希塞尔山谷通往哪里？",a="沿着峡谷向东走，可以直接到达埃雷萨废墟，这是一个隐藏在高山之上的古老暗夜精灵遗迹。",al={"希塞尔山谷尽头有什么","穿过希塞尔山谷的路径"}}},fx={["8c6e4ccd"]={q="希塞尔山谷危险吗？",a="对任何没有做好应对蜘蛛准备的旅人来说，希塞尔山谷都极其危险。山谷里到处都是具有攻击性的深苔蜘蛛，它们在岩壁间结起厚厚的蛛网，并守护着成堆的蛛卵。若深入其中，就会进入它们那只名为贝瑟莱斯的巨型母蜘蛛的猎杀范围。",al={"希塞尔山谷的危险","希塞尔山谷安全吗","希塞尔山谷面临的威胁"}}},fp="13,352,15.507.0,18.412.0,22.148.0,34.180.0,17.178.0,30.134.0"}
P.entries["subzone:skittering-dark"] = {n="粘丝洞",s="粘丝洞是一处位于银松森林西部的废弃矿井和阴暗林地洼地。由于受到具有攻击性的巨型蜘蛛的侵扰，这座洞穴及其周边树林布满了蛛网，对毫无防备的野兽和旅行者来说充满危险。",h="粘丝洞是一处位于银松森林西部的废弃矿井和阴暗林地洼地。由于受到具有攻击性的巨型蜘蛛的侵扰，这座洞穴及其周边树林布满了蛛网，对毫无防备的野兽和旅行者来说充满危险。",kw={"krethis","矿井","北流海岸","银松森林","粘丝洞","蜘蛛"},ang={["faction:Horde"]="进入银松森林的部落旅行者们请注意：粘丝洞的蜘蛛会伏击那些从周边树林误入它们蛛网巢穴的毫无防备的猎物。"},sec={{t="蛛网密布的洼地",b="粘丝洞坐落在北流海岸西岸以东的山丘中，曾经是一座运作中的矿井。如今，矿井通道完全被蛛网堵塞，成为了巨型蜘蛛的庞大巢穴。阴影编织者Krethis出没在洞穴外部，这些蜘蛛会猎杀任何靠得太近的目标。"}},faq={{q="什么是粘丝洞？",a="这是位于银松森林西部的一处废弃矿井，已被巨型蜘蛛完全占领。洞穴网络和周边的树木上覆盖着厚厚的黏性蛛网，还有许多捕食性的蛛形纲生物。",al={"粘丝洞矿井","这是什么矿井","银松森林蜘蛛洞"}},{q="矿井里的蜘蛛由谁领导？",a="目前还没有已知的单一蜘蛛首领。其中最令人恐惧的是暗影织网者Krethis，这是一种稀有且危险的织网者，经常在矿井内外徘徊。",al={"蜘蛛首领","粘丝洞首领","蛛后"}},{q="粘丝洞在哪里？",a="它坐落在银松森林西部的群山之中，就在被称为北流海岸的岸线以东。",al={"粘丝洞位置","如何找到粘丝洞"}}},fx={["958edcba"]={q="谁住在粘丝洞？",a="矿洞及周围的洼地都被巨型蜘蛛占据。它们潜伏在黑暗的裂隙中，在岩坡和隧道间织起厚厚的蛛网。据说还有一只名为克雷希斯·影织者的强大稀有蜘蛛在矿洞内外出没。",al={"谁住在粘丝洞","粘丝洞的居民","粘丝洞里有什么生物"}},["040a6057"]={q="粘丝洞危险吗？",a="极其危险。只要有人蠢到靠近巢穴，这些凶猛的蜘蛛就会发动伏击，把毫无防备的猎物拖进老矿道深处的蛛网里。",al={"粘丝洞有多危险","粘丝洞危险吗","粘丝洞的危险"}},ecb7b94e={q="为什么粘丝洞的矿坑废弃了？",a="在瘟疫和战争蹂躏洛丹伦之前，这座矿坑曾有人开采；但曾在此采矿的凡人产业早已消亡。王国覆灭期间，地下矿道和幽暗隧道彻底无人看管，成了怪异蜘蛛繁殖的理想隐蔽之所，残存的采矿活动也因此完全消失。",al={"粘丝洞为何废弃","谁开采过粘丝洞","矿工为何离开粘丝洞"}},["0b1ef10a"]={q="为什么叫粘丝洞？",a="这个名字既反映了废弃矿道的阴森，也描绘了洞中虫群永不停歇的窸窣声。在银松森林阴影笼罩的山丘和洞壁下，唯一持续不断的声音，便是成千上万条蜘蛛腿在黑暗中爬行时发出的咔嗒声和沙沙声。",al={"为什么叫粘丝洞","粘丝洞名称由来","粘丝洞的名字是怎么来的"}}},fp="15,240,15.324.0,28.197.0,34.159.0,37.117.0"}
P.entries["subzone:skull-rock"] = {n="骷髅石",s="骷髅石是位于杜隆塔尔东海岸悬崖中的一处洞穴，就在奥格瑞玛的东边。它充当了火刃氏族这一恶魔崇拜组织的堡垒，其位置就在奥格瑞玛的眼皮底下。",h="骷髅石是位于杜隆塔尔东海岸悬崖中的一处洞穴，就在奥格瑞玛的东边。它充当了火刃氏族这一恶魔崇拜组织的堡垒，其位置就在奥格瑞玛的眼皮底下。",kw={"火刃氏族","邪教徒","杜隆塔尔","加祖兹","奥格瑞玛","骷髅石"},ang={["class:Warlock"]="在骷髅石内练习的黑暗魔法展示了恶魔影响力的肆意蔓延，这是萨尔的部落竭力想要根除和控制的。",["faction:Horde"]="清除骷髅石内的邪教徒对于确保杜隆塔尔沿海通道的安全，以及保护奥格瑞玛免受内部颠覆至关重要。"},sec={{t="邪教徒的巢穴",b="骷髅石隐藏在杜隆塔尔东北部的岩礁之下，是该地区火刃氏族最危险的据点之一。黑暗的邪教徒、崇拜邪能的兽人和召唤师们聚集在蜿蜒的隧道深处，练习恶魔魔法，并密谋对抗新生的部落。该组织由危险的术士加祖兹领导，他的行动对附近的奥格瑞玛大门和往来东海岸的旅者构成了迫在眉睫的威胁。"}},faq={{q="什么是骷髅石？",a="骷髅石是一处位于杜隆塔尔东北部沿海的洞穴系统。这里被火刃氏族的邪教徒所占据，他们利用天然的掩体来策划对抗萨尔的部落。",al={"骷髅石洞穴","骷髅石在哪里","骷髅石里有什么"}},{q="谁控制着骷髅石？",a="洞穴被火刃氏族渗透，兽人术士加祖兹在洞穴的最深处指挥着一切。",al={"谁领导骷髅石","谁在运作骷髅石","骷髅石首领"}},{q="为什么部落关心这个洞穴？",a="它靠近奥格瑞玛，构成了严重的安全隐患。火刃氏族积极寻求破坏萨尔的新国度，并试图让兽人重新陷入恶魔的奴役之中。",al={"为什么要清理骷髅石","为什么骷髅石很危险"}}},fp="10,195,17.478.0,19.183.0,24.118.0,40.175.0"}
P.entries["subzone:slag-pit"] = {n="熔渣之池",s="熔渣之池是一处深埋于灼热峡谷大熔炉内部的巨大地下矿坑。在冷酷的黑铁矮人工头和奴隶贩子的监管下，这些充满烈焰的隧道在黑石山的阴影下依靠强制劳役维持运作。入侵者不仅要面对敌对的矮人监工，还要提防在底层游荡的贪婪燃火龙。",h="熔渣之池是一处深埋于灼热峡谷大熔炉内部的巨大地下矿坑。在冷酷的黑铁矮人工头和奴隶贩子的监管下，这些充满烈焰的隧道在黑石山的阴影下依靠强制劳役维持运作。入侵者不仅要面对敌对的矮人监工，还要提防在底层游荡的贪婪燃火龙。",kw={"大熔炉","黑铁矮人","燃火龙","灼热峡谷","熔渣之池","奴隶贩子","奴隶","工头"},ang={["profession:Mining"]="熔渣之池的深井直插灼热峡谷富含矿产的核心地带，使其成为一处利润丰厚——但也极其危险——的高品位矿石产地。",["race:Dwarf"]="对于铁炉堡的矮人来说，目睹熔渣之池中黑铁奴隶贩子的残暴行径，是对各矮人氏族之间深刻分歧的一次严酷提醒。"},sec={{t="地下苦役",b="熔渣之池开凿在大熔炉深处，是黑铁矮人在灼热峡谷残酷工业机器的缩影。日夜不停地，被奴役的劳工在残暴的监工和工头的鞭笞下，被迫挖掘丰富的矿石和矿物。这里的环境恶劣而令人窒息，充斥着灼热的温度、呛人的尘土和铁镐的撞击声。黑铁矮人对他们的矿坑实行残酷的纪律，并暴力击退任何干扰他们通往黑石深渊补给线的外部势力。"},{t="矿坑深处",b="除了奴隶贩子的残暴，这些隧道本身对工人和入侵者而言也是致命的威胁。在矿坑的底层，大地裂开，形成了一座座酷热的洞穴，栖息着燃火龙——这是一种原产于地下火海的凶猛爬行兽。尽管时刻面临着被这些地下掠食者吞噬的危险，黑铁矮人大师们依然驱使劳工深入岩石，对过程中丧生的生命毫不在意。"}},faq={{q="熔渣之池在哪里？",a="熔渣之池位于大熔炉的深处，那是一个占据了灼热峡谷中心位置的巨大挖掘坑。其隧道直接从地表的采矿作业区下方延伸开来。",al={"熔渣之池位置","熔渣之池在哪","如何前往熔渣之池"}},{q="谁控制着熔渣之池？",a="这座矿坑完全由黑铁氏族掌控。黑铁奴隶贩子和工头在矿井中巡逻，执行残酷的纪律，并驱使俘虏们全天候不停地挖掘。",al={"谁管理熔渣之池","熔渣之池所属势力","黑铁矮人熔渣之池"}},{q="为什么奴隶工会攻击入侵者？",a="虽然被奴役的劳工对外界并不具有天生的攻击性，但他们对黑铁大师的恐惧根深蒂固。如果有奴隶贩子或工头在附近遇袭，惊慌失措的劳工为了避免严厉的惩罚，会冲上去保护他们的监工。",al={"为什么奴隶会攻击","敌对的奴隶","奴隶劳工仇恨"}},{q="熔渣之池里住着什么生物？",a="除了黑铁矮人和他们的奴隶之外，矿坑的最深处还滋生着燃火龙——一种具有攻击性、覆盖着火焰鳞片的爬行掠食者，潜伏在地下隧道中。",al={"熔渣之池怪物","燃火龙","熔渣之池野兽"}}},fp="8,370,17.539.0,17.505.0,30.181.0,26.185.0,42.256.0,36.197.0"}
P.entries["subzone:slaughter-hollow"] = {n="屠杀谷",s="屠杀谷是一处与世隔绝的食人魔土丘，隐匿在奥特兰克山脉白雪皑皑的高处。这里被野蛮的碎颅氏族所控制，更像是一个粗陋的营地，而非熙熙攘攘的定居点。除非是去猎杀食人魔或探索冰封的山隘，否则旅行者很少有理由踏足此地。",h="屠杀谷是一处与世隔绝的食人魔土丘，隐匿在奥特兰克山脉白雪皑皑的高处。这里被野蛮的碎颅氏族所控制，更像是一个粗陋的营地，而非熙熙攘攘的定居点。除非是去猎杀食人魔或探索冰封的山隘，否则旅行者很少有理由踏足此地。",kw={"奥特兰克","碎颅氏族","希尔斯布莱德","食人魔土丘","里兹·螺栓","屠杀谷"},ang={["race:Gnome"]="里兹·螺栓被碎颅氏族不幸俘获，给那些毫无准备就在奥特兰克山隘徘徊的技工和斥候敲响了警钟。"},sec={{t="食人魔巢穴",b="屠杀谷隐藏在希尔斯布莱德与奥特兰克交界的崇山峻岭之中，是当地碎颅氏族食人魔的营地。正如散布在高地上的许多食人魔土丘一样，这里到处都是临时搭建的篝火、丢弃的尸骨和简陋的住所。虽然山中的其他食人魔巢穴经常因领土争端或被盗的补给品而爆发冲突，但屠杀谷大体上还算安静，并未卷入主要的军事行动之中。"},{t="俘虏与旅行者",b="由于其位置偏僻，该土丘偶尔会被当作关押沿山路被俘的不幸之人的地方。旅行者中流传着一个关于名为里兹·螺栓的不幸侏儒的消息，他发现自己被关在这里一个简陋的笼子里，试图与任何经过的人进行交易。这些不幸的俘虏在面对碎颅氏族那贪婪的胃口时，往往结局凄惨。"}},faq={{q="什么是屠杀谷？",a="屠杀谷是奥特兰克山脉中一个由碎颅氏族居住的食人魔营地。这里有高地食人魔定居点典型的原始土丘住宅和篝火。",al={"屠杀谷背景故事","这里是什么地方","希尔斯布莱德的屠杀谷"}},{q="谁住在屠杀谷？",a="屠杀谷完全由碎颅氏族食人魔居住，该氏族同样占据着附近的奥特兰克废墟以及周围的各个哨所。",al={"谁在这里","屠杀谷怪物","谁控制了屠杀谷"}},{q="这里有任务吗？",a="没有直接将冒险者引向屠杀谷的正式任务。它大体上是一个在探索山区地形时偶然发现的偏远巢穴。",al={"屠杀谷任务","屠杀谷有任务吗","为什么要来这里"}},{q="被关在这里的侏儒是谁？",a="一个名叫里兹·螺栓的侏儒被囚禁在谷内的一个笼子里，向任何发现他的人兜售商品。",al={"里兹·螺栓","笼子里的侏儒","屠杀谷商人"}}},fx={["446b3423"]={q="屠杀谷危险吗？",a="是的，屠杀谷极其危险。它深藏在奥特兰克山脉的雪山隘口中，是一处遍布敌对碎脊食人魔的食人魔营地。毫无准备地闯入他们的营地，很快就会招来多个魁梧暴徒的怒火。",al={"屠杀谷安全吗","屠杀谷的危险","屠杀谷有多危险"}}},fp="16,307,14.439.0,22.381.0,25.183.0,30.145.0,26.151.0,29.112.0"}
P.entries["subzone:slaughtered-lamb"] = {n="Slaughtered Lamb",s="Slaughtered Lamb藏在暴风城的Mage Quarter里，表面上不过是一间安静又破旧的酒馆。然而，在它的地板之下，错综复杂的地下墓穴隐藏着联盟非法术士的密室和训练场。",h="Slaughtered Lamb藏在暴风城的Mage Quarter里，表面上不过是一间安静又破旧的酒馆。然而，在它的地板之下，错综复杂的地下墓穴隐藏着联盟非法术士的密室和训练场。",kw={"地下墓穴","jarel moor","mage quarter","slaughtered lamb","暴风城","术士","维沙克","加尔德斯"},ang={["class:Warlock"]="下方的地下墓穴是你身处暴风城时的主要避难所，这里提供职业训练师、恶魔奴役仪式，以及掌握黑暗技艺所必需的任务。",["faction:Alliance"]="虽然联盟崇尚圣光与秩序，但Slaughtered Lamb揭示了这个王国在阴影中容忍黑暗魔法的默许态度。"},sec={{t="拙劣的伪装",b="表面上，Slaughtered Lamb只有阴暗的角落和稀少的顾客，由酒保Jarel Moor照看。他会告诫随意的访客远离阴影，这句警告并非虚言。穿过后方的通道向下走，会发现一个由地下墓穴和召唤法阵组成的地下建筑群。在这里，人类术士和来自卡兹莫丹的施法者们公开研究着邪能奥术，免受圣光教会和肯瑞托那充满非议的目光的注视。"},{t="贵族的酒账",b="在王都中心经营一个邪能集会点总是伴随着持续的危险。当鲍雷斯·维沙克公爵发现潜伏在地窖里的术士时，他威胁要召集贵族议会并请求王座进行全面调查。实际上，这位贵族只是想赖掉一笔巨额酒账。在这一骚动引发真正的审查之前，黑爪加尔德斯安排维沙克喝下了一杯致命的混合物，永远地让这个多管闲事的人闭了嘴，守护住了这里的秘密。"}},faq={{q="Slaughtered Lamb下面究竟在进行什么活动？",a="酒馆下方的地下墓穴是暴风城术士的秘密密室。恶魔学识和暗影魔法的修行者们聚集在那里教导学徒、进行召唤仪式，并练习在上方街道中被禁止的邪能技艺。",al={"slaughtered lamb下面有什么","slaughtered lamb地下室","slaughtered lamb里有什么人"}},{q="暴风城守卫知道术士的存在吗？",a="这间酒馆在摇摇欲坠的“合理推诿”掩盖下运作。圣光教会和法师学院对邪能魔法抱有深深的不信任，迫使这个集会组织必须秘密运作，并积极地让任何威胁要向王室当局告发他们的人永远闭嘴。",al={"守卫知道术士吗","为什么术士没有被捕","slaughtered lamb是非法的吗"}},{q="维沙克公爵是谁，他发生了什么事？",a="鲍雷斯·维沙克公爵是一位贵族，也是酒馆的常客，他发现了躲在下面的术士。他在贵族议会中引起了骚动，并游说进行全面调查，希望请求国王关闭这家店。",al={"鲍雷斯·维沙克","维沙克公爵的下场","维沙克是谁"}},{q="侏儒术士为什么来这里？",a="在诺莫瑞根沦陷后，其术士大师拉戈·黑钳将新手送到Slaughtered Lamb的黑暗缚灵者加科因那里接受训练。",al={"暴风城的侏儒术士","卡兹莫丹术士"}}},fx={["28eb4e6b"]={q="什么是 Slaughtered Lamb？",a="表面上看，Slaughtered Lamb 是一家安静而阴暗的酒馆，藏在暴风城的 Mage Quarter。地面上的酒馆看起来几乎无人打理，空荡荡的酒吧间只有酒保 Jarel Moor 在照看。然而，地板之下却延伸着庞大的地下墓穴和陵寝网络。这些幽暗深处是暴风城术士的秘密圣所，为他们遮掩禁忌的邪能仪式和召唤，不让城卫队和贵族议会那不赞同的目光窥见。",al={"slaughtered lamb 是什么","slaughtered lamb 酒馆","slaughtered lamb"}},f1944543={q="Slaughtered Lamb 发生过什么事？",a="当鲍雷斯·维沙克公爵发现术士藏身于酒馆地下室时，这里的秘密差点暴露。他在贵族议会掀起风波，并游说展开全面调查，希望请求国王下令关闭这家店。",al={"slaughtered lamb 的历史","slaughtered lamb 发生过什么事","slaughtered lamb 背景"}},["531ea530"]={q="谁在经营 Slaughtered Lamb？",a="楼上的酒吧间由酒保 Jarel Moor 看管，他会悄悄提醒好奇的顾客远离那些阴暗角落。地下的隐秘据点里住着神秘的术士导师和召唤师，其中包括黑爪加尔德斯。他们教导人类学徒以及从侏儒处转来的学徒，行事低调，好让生意和黑暗魔法不受打扰地进行。",al={"谁在经营 slaughtered lamb","slaughtered lamb 的酒保","slaughtered lamb 里有哪些人"}},ecc63b24={q="Slaughtered Lamb 危险吗？",a="藏身于此的术士会严密守护他们的秘密，绝不容许任何人揭露他们的地下集会。",al={"slaughtered lamb 危险吗","slaughtered lamb 的危险","slaughtered lamb 里安全吗"}}},fp="16,244,15.486.0,15.511.1,49.240.0,54.287.0,47.236.1,32.209.0"}
P.entries["subzone:slither-rock"] = {n="滑石",s="滑石是一个隐蔽的洞穴，位于燃烧平原遥远的东北部悬崖中，穿过危险的龙翼小径即可到达。它是塞勒斯·萨雷芬图斯唯一的避难所，这只口舌尖酸的黑龙人怀揣着自己不可告人的目的。",h="滑石是一个隐蔽的洞穴，位于燃烧平原遥远的东北部悬崖中，穿过危险的龙翼小径即可到达。它是塞勒斯·萨雷芬图斯唯一的避难所，这只口舌尖酸的黑龙人怀揣着自己不可告人的目的。",kw={"黑龙人","燃烧平原","塞勒斯·萨雷芬图斯","滑石","龙翼小径"},sec={{t="一处隐蔽的洞穴",b="滑石隐藏在龙翼小径尽头的焦黑岩壁之中，在燃烧平原那火热的荒野里很容易被忽略。这个偏远的洞穴远离黑石塔那轰鸣的熔炉和行军的兽人战团，它是孤独的黑龙人塞勒斯·萨雷芬图斯的居所。尽管龙人通常是黑龙军团中极其忠诚的士兵，但塞勒斯却在此保持着一种古怪而暴躁的独立性。比起见面就大开杀戒，他更愿意与凡人旅者交谈——尽管交谈时总少不了一连串的谩骂。"}},faq={{q="滑石位于哪里？",a="滑石位于燃烧平原遥远的东北角。旅行者必须穿过巡逻在龙翼小径上的黑龙人，才能到达那里。",al={"滑石位置","滑石在哪里","找到滑石"}},{q="谁住在滑石里？",a="这个洞穴住着塞勒斯·萨雷芬图斯，一只孤独的黑龙人。与他那些一见到凡人就发动攻击的同类不同，塞勒斯愿意与外人交谈，尽管他依然脾气暴躁且出言不逊。",al={"滑石里的人","滑石怪物","滑石npc"}},{q="冒险者为什么要寻找这个洞穴？",a="冒险者们冒着危险穿过龙翼小径，去寻求塞勒斯·萨雷芬图斯的建议和帮助。尽管态度恶劣，但这只龙人还是会帮助他们战胜共同的敌人，不过他一定会伴随着大量的粗鲁和嘲讽言论。",al={"为什么要去滑石","滑石任务","塞勒斯的目的"}}},fp="12,249,17.566.0,30.173.0,26.212.0,43.251.0"}
P.entries["subzone:slithering-scar"] = {n="巨痕谷",s="巨痕谷是一座庞大的其拉虫巢，坐落在安戈洛环形山的南侧悬崖上。这里是极具侵略性的戈里希虫群的家园，它们挖掘的隧道和有机尖塔代表了一种危险的昆虫入侵，正在蚕食这片原始盆地。",h="巨痕谷是一座庞大的其拉虫巢，坐落在安戈洛环形山的南侧悬崖上。这里是极具侵略性的戈里希虫群的家园，它们挖掘的隧道和有机尖塔代表了一种危险的昆虫入侵，正在蚕食这片原始盆地。",kw={"扎瓦斯主母","巨像","戈里希","虫巢","其拉虫","巨痕谷","安戈洛"},ang={["class:Druid"]="戈里希虫巢的侵略性扩张威胁着环形山脆弱而原始的活力，需要人们时刻警惕这种不自然的虫群滋生。"},sec={{t="戈里希虫巢",b="巨痕谷深陷在安戈洛南部的红土和岩石之中，如同在繁茂的史前景观中植入的外来异物。这座虫巢由戈里希其拉虫控制，这是一个组织严密的昆虫种群，它们在悬崖中开凿了无数潮湿的洞穴和孵化室。在这些地下巢穴中，工虫和钻地虫在照料着大量的虫卵、幼虫以及高耸的黄蜂巢穴。更令人担忧的是，虫群还在培育初生的其拉巨像，这些庞然大物旨在为它们在环形山的生态系统中开辟一条畅通无阻的道路。虫巢内镶嵌的奇异水晶结构散发着不自然的共鸣，成为了虫群阴暗且协调一致的意志焦点。"},{t="缺失的守卫",b="经常穿行在安戈洛边缘的学者和探险家们，注意到了这个虫巢位置的一个令人不安的异常之处。虽然古老的水晶塔矗立在盆地的北部、东部和西部边缘作为守护，但南部区域却没有这样的柱子。正是在这个毫无保护的缺口处，戈里希其拉虫从邻近的沙漠中向内掘进。究竟是其拉虫有意破坏了一处被遗忘的南部守卫，还是它们仅仅入侵了环形山原始防护最为薄弱的地方，这对那些关注它们迅速扩张的人来说，仍然是一个令人不安的谜团。"}},faq={{q="什么是巨痕谷？",a="它是一座开凿在安戈洛环形山南侧悬崖上的其拉虫巢建筑群，戈里希虫群栖息于此。",al={"这是什么地方","巨痕谷概览","安戈洛虫巢"}},{q="其拉虫在这里做什么？",a="戈里希虫群正在挖掘庞大的地下隧道，照料装满幼虫和虫卵的育婴室，并培育巨大的其拉巨像，以建立对环形山的统治。",al={"为什么虫子在这里","其拉虫在安戈洛的目的","戈里希目标"}},{q="为什么南部没有像其他地区那样的水晶塔？",a="虽然安戈洛的北部、东部和西部边缘都有古老的水晶塔作为标记，但南部的悬崖却没有。巨痕谷正是出现在这个防御边界缺失的地方。",al={"缺失的南部水晶塔","为什么没有南部的塔","南部的水晶塔在哪里"}},{q="有哪些危险的生物栖息在虫巢中？",a="除了成群的工虫、掠夺者和刺虫外，虫巢中还有正在发育的巨像，以及像扎瓦斯主母这样声名狼藉、凶猛异常的巢穴首领。",al={"虫巢首领","著名的虫子","扎瓦斯主母"}}},fp="15,247,16.730.0,14.602.0,28.117.0,33.181.0,58.205.0,42.159.0"}
P.entries["subzone:sludge-fen"] = {n="淤泥沼泽",s="淤泥沼泽是荆棘谷地精在贫瘠之地东北部运营的一处有毒工业油田。这片湿地曾经是一汪纯净清澈的碧蓝水潭，但在地精竖起钻井平台和机械装置后，便沦为了一片油污泥潭。该行动由卢格维兹主管监督，并持续引来棘齿城竞争对手的工业间谍破坏活动。",h="淤泥沼泽是荆棘谷地精在贫瘠之地东北部运营的一处有毒工业油田。这片湿地曾经是一汪纯净清澈的碧蓝水潭，但在地精竖起钻井平台和机械装置后，便沦为了一片油污泥潭。该行动由卢格维兹主管监督，并持续引来棘齿城竞争对手的工业间谍破坏活...",kw={"石油钻井","伐木机","淤泥沼泽","斯布特瓦夫","卢格维兹主管","贫瘠之地","荆棘谷地精","维兹尔克兰"},ang={["class:Druid"]="淤泥沼泽是反自然剥削的罪恶见证。部落德鲁伊在进行海狮试炼时，会潜入这片油腻的深渊取回水兽敏捷坠饰。",["profession:Engineering"]="荆棘谷地精在此处运作着尖端的伐木机和机械装置，这使得该地点成为了蓝图、特殊零件以及棘齿城精心策划的商业盗窃行动的诱人目标。"},sec={{t="工业破坏",b="在荆棘谷地精到来之前，淤泥沼泽原本是由贫瘠之地的天然泉水补给的纯净清澈的水潭。出于对利润的无止境追求，荆棘谷地精在盆地上兴建了大规模的石油钻探工程，将这片湿地糟蹋成了一个覆盖着厚重工业废料的污泥水库。在卢格维兹主管的监管下，地精钻探工、工程师和监工昼夜不停地抽取原油，对环境的破坏置若罔闻。如今水域中充斥着径流和有毒副产品，本地的水生生物都在油垢的重压下窒息而亡。"},{t="企业竞争与间谍活动",b="沼泽里的机械装置和伐木机创新技术使其成为了工业窃取的首要目标。在附近的棘齿城，工匠联合会的工程师斯布特瓦夫面临着巨大的压力，急需匹配荆棘谷地精尖端的伐木和挖掘技术。斯布特瓦夫并没有研发自己的设计，而是派出了一个名叫维兹尔克兰的特工，打算直接从淤泥沼泽抢走一台荆棘谷地精的伐木机。由于维兹尔克兰愚蠢地在没有拿到打火钥匙的情况下就劫持了机器，雇佣兵们经常被卷入泥潭，设法从卢格维兹手中夺取钥匙，并护送这台被窃的战争机器穿过愤怒的荆棘谷地精员工的重重包围。"}},faq={{q="荆棘谷地精到来之前的淤泥沼泽是什么样的？",a="淤泥沼泽原本是一汪纯净的碧蓝色水潭。荆棘谷地精在上面直接建造了钻井和炼油设施，毁掉了这片天然绿洲，将周围的湿地淹没在原油和化学废料之中。",al={"淤泥沼泽的过去","淤泥沼泽一直是被污染的吗","淤泥沼泽历史"}},{q="谁在负责淤泥沼泽的运营？",a="这片油田由卢格维兹主管代表荆棘谷地精进行管理。他监管着一支由监工、钻探工和工程师组成的劳动力队伍，手下还有像格利比监工和格里尔斯工头这样的副手。",al={"淤泥沼泽首领","谁领导淤泥沼泽","卢格维兹主管"}},{q="为什么沼泽中间停着一台被劫持的伐木机？",a="地精维兹尔克兰受棘齿城的斯布特瓦夫派遣，前来窃取荆棘谷地精的高级伐木机设计。然而，他跳进驾驶舱时却忘了先拿到打火钥匙，结果被困在原地，被敌对的荆棘谷地精员工团团包围。",al={"维兹尔克兰的伐木机","淤泥沼泽伐木机里的地精","为什么伐木机动不了"}},{q="德鲁伊为什么要潜入这些被污染的水域？",a="进行海狮试炼的部落德鲁伊会被指引前往受污染水潭的底部，从一个淹没在水下的锁盒中取回水兽敏捷坠饰，以此在恶劣的环境中考验他们的耐力。",al={"淤泥沼泽德鲁伊任务","水兽敏捷坠饰","水栖形态试炼"}}},fx={["8087f29c"]={q="为什么叫淤泥沼泽？",a="这里因荆棘谷地精的钻探作业倾倒了大量有毒废水和工业废料而得名。曾经清澈的天然水池如今已被彻底污染，变成一片污浊、泛着油光的黑色淤泥沼泽。",al={"淤泥沼泽为何得名","淤泥沼泽名称含义","淤泥沼泽名称由来"}},["35534ec0"]={q="什么是淤泥沼泽？",a="淤泥沼泽是位于贫瘠之地东北部、由荆棘谷地精经营的石油钻探场。这里的核心是一座直接建在泥沼中的工业钻井平台，整片设施用于开采资源和测试机械，周围遍布有毒废水、运转的碎木机和公司的雇员。",al={"淤泥沼泽是什么","介绍淤泥沼泽","淤泥沼泽概况"}},["537e9a89"]={q="淤泥沼泽危险吗？",a="是的。荆棘谷地精雇用了具有攻击性的监工、工头和工程师，他们用碎木机和重型工具积极守卫作业区，一发现闯入者便会发动攻击。此外，这里的水域充斥着有毒工业废料，以及污染造成的异常淤泥。",al={"淤泥沼泽危险吗","淤泥沼泽的危险","淤泥沼泽面临的威胁"}}},fp="10,379,22.621.0,31.676.1,60.247.0,37.207.0,65.258.0,46.226.0"}
P.entries["subzone:solliden-farmstead"] = {n="索利丹农场",s="索利丹农场是位于提瑞斯法林地西部的一座仍在耕作的人类南瓜农场，就在丧钟镇的北面。它是洛丹伦北部罕见的异常存在：这些幸存下来的本土农夫在亡灵瘟疫中存活了下来，并在血色十字军的庇护下坚守着他们的土地。",h="索利丹农场是位于提瑞斯法林地西部的一座仍在耕作的人类南瓜农场，就在丧钟镇的北面。它是洛丹伦北部罕见的异常存在：这些幸存下来的本土农夫在亡灵瘟疫中存活了下来，并在血色十字军的庇护下坚守着他们的土地。",kw={"亡灵卫兵希米尔","丧钟镇","悲伤之田","南瓜","索利丹","索利丹农场","提瑞斯法林地"},ang={["faction:Alliance"]="看到活人耕种洛丹伦的土地带来了一丝希望，但残酷的现实是，这些孤立的幸存者对暴风城的公民抱有同样的排外仇恨，就像他们仇视亡灵一样。",["race:Undead"]="对于新崛起的被遗忘者来说，索利丹农场是现实政治的第一课：这些洛丹伦活人蔑视你们所变成的样子，既是药剂师毒素的原材料，也是一个潜在的南部桥头堡。"},sec={{t="反抗的遗民",b="尽管洛丹伦的大部分地区已沦为废墟和腐烂之地，索利丹农场的田地里依然出产着健康的作物。如今，这些幸存的人类农夫生活在附近一座塔楼中巡逻的血色十字军的庇护之下。他们饱受创伤且封闭排外，以毫不妥协的敌意保卫着他们的家园，攻击任何靠近的陌生人——无论是部落还是联盟。"},{t="幽暗城的注视",b="对于刚从丧钟镇走出来的被遗忘者来说，索利丹既是一种威胁，也是一种资源。皇家药剂师学会看中了农场里那些完好的南瓜，将其视为酿造新瘟疫的绝佳有机实验材料。与此同时，像亡灵卫兵希米尔这样的被遗忘者军官会派遣新兵突袭田地，为布瑞尔的药剂师乔汉偷走那些南瓜，并给这些活人一点教训。"}},faq={{q="为什么提瑞斯法林地会有活人农夫？",a="索利丹的农夫是洛丹伦的本土人类，他们在第三次战争中奇迹般地躲过了感染。在附近塔楼中巡逻的血色十字军的保护下，他们固执地继续耕种土地，而不是逃离他们的祖居之地。",al={"为什么他们还活着","这些农夫是谁","提瑞斯法的活人"}},{q="为什么索利丹的农夫会对联盟玩家保持敌意？",a="经历了洛丹伦的沦陷后，这些农夫变得多疑、痛苦，并且完全不信任圈子以外的任何人。在狂热的血色十字军的保护下，他们将所有闯入者视为潜在的威胁或受感染的拾荒者，无差别地攻击联盟和部落的旅行者。",al={"为什么农夫攻击联盟","他们是联盟吗","为什么对联盟是红色敌对"}},{q="为什么被遗忘者想要索利丹农场的南瓜？",a="服务于皇家药剂师学会的药剂师需要新鲜、未受污染的有机物质来测试和提炼他们的新瘟疫。索利丹土壤中生长的饱满、未受污染的南瓜，是开发毒素菌株的理想活体宿主。",al={"为什么要偷南瓜","悲伤之田南瓜任务","皇家药剂师学会南瓜"}},{q="亡灵卫兵希米尔是谁，为什么他要针对这个农场？",a="亡灵卫兵希米尔是一名驻扎在丧钟镇附近的被遗忘者军官。他派遣被遗忘者新兵去突袭农场，为布瑞尔的药剂师乔汉偷走十个南瓜，并给这些人类和保护他们血色十字军一点教训。",al={"为什么要杀死农夫","亡灵卫兵希米尔任务","收割收割者"}}},fx={cf3d4bd1={q="索利丹农场是什么地方？",a="索利丹农场是一座仍在经营的南瓜农场，位于提瑞斯法林地西部，就在丧钟镇以北不远处。令人惊讶的是，它是洛丹伦北部为数不多的地方之一，当地原生人类幸存者在亡灵瘟疫中完全未受腐化，并在附近血色十字军的阴影下顽强守着自己的土地。",al={"索利丹农场是什么","索利丹农场","索利丹农场介绍"}},["45cdb17a"]={q="索利丹农场有着怎样的历史？",a="关于农场早期历史的记载寥寥无几。已知的是，尽管处境艰难，它仍是一处活跃的农庄，直到第三次战争期间都是如此；农民在血色十字军的保护下熬过了亡灵瘟疫。",al={"索利丹农场历史","谁建立了索利丹农场","索利丹农场发生过什么"}},["7c9ed8e2"]={q="索利丹农场危险吗？",a="是的，如果你靠得太近。幸存的农民在被恐怖之物包围的环境中活下来后，变得极度多疑且富有攻击性。他们不会欢迎外来者，而是会一见面就攻击部落和联盟的旅人。此外，农场离附近哨所的血色十字军防御工事很近，周边地区因此危机四伏。",al={"索利丹农场危险吗","索利丹农场的农民危险吗","索利丹农场的威胁"}}},fp="18,295,17.378.0,21.395.0,55.257.0,57.315.0,58.243.0,58.238.0"}
P.entries["subzone:sorrow-hill"] = {n="悔恨岭",s="悔恨岭是西瘟疫之地安多哈尔以南的一片广阔墓地。它曾是平民、士兵和贵族的安息之所，但受到附近瘟疫锅的腐蚀，如今已变成亡灵四处游荡的恐怖之地。",h="悔恨岭是西瘟疫之地安多哈尔以南的一片广阔墓地。它曾是平民、士兵和贵族的安息之所，但受到附近瘟疫锅的腐蚀，如今已变成亡灵四处游荡的恐怖之地。",kw={"安多哈尔墓地","达尔加","约瑟夫·雷德帕斯","骷髅剥皮者","悔恨岭","乌瑟尔之墓","西瘟疫之地"},ang={["class:Paladin"]="对于圣骑士来说，悔恨岭是一个充满哀思与敬畏之地，他们前来乌瑟尔之墓瞻仰，同时还要击退那些亵渎导师安息之地的亡灵。",["faction:Alliance"]="这片墓地紧邻寒风营地，既是通往安多哈尔的战略要塞，也是洛丹伦阵亡捍卫者们神圣的安息之地。"},sec={{t="坟冢的重担",b="在第三次战争之前，悔恨岭是安多哈尔及其周边城镇的主要埋葬地。当天灾军团散布亡灵瘟疫时，掘墓人根本无法处理堆积如山的尸体。整齐的墓穴很快被浅浅的、标记简陋的土坑所包围。最终，惊恐的幸存者完全停止了传统的安葬方式，为了防止尸体复活，他们不得不将亲人的遗体运往南边的集体火堆烧毁。在城镇彻底沦陷前，幸存的居民将光明使者乌瑟尔安葬在墓地的高地上，从此赋予了这座山丘这个悲剧性的名字。"},{t="复活的死者",b="天灾军团在该地区散布的邪恶瘟疫锅早已腐蚀了悔恨岭。原本埋葬于此的士兵和市民如今已变成骷髅剥皮者和贪婪的食尸鬼，在迷雾缭绕的墓碑间游荡，而骷髅法师和一名当地的天灾指挥官则盘踞在东南部的墓穴中。由于这片墓地正位于寒风营地和安多哈尔之间的道路上，联盟和银色黎明经常派遣巡逻队清理此地的亡灵，以维持在该地区的重要立足点。"}},faq={{q="为什么这片墓地被称为悔恨岭？",a="这个名字源于洛丹伦沦陷期间，当时安多哈尔的幸存者在天灾军团的攻击下遭受了毁灭性的损失。他们在逃离前的最后一次集体行动，就是将他们倒下的领袖——光明使者乌瑟尔安葬在山顶的一座宏伟陵墓中。",al={"悔恨岭名字含义","为什么叫悔恨岭"}},{q="这里为什么有这么多浅坟？",a="当亡灵瘟疫袭击安多哈尔时，死亡人数激增，市民们根本来不及建造像样的陵墓。他们仓促地挖掘了一些标记简陋的土坑，直到瘟疫的攻势变得无法抵挡，他们便放弃了安葬，转而选择集体火葬。",al={"悔恨岭的浅坟","为什么墓碑标记简陋"}},{q="谁被埋葬在悔恨岭？",a="除了成千上万阵亡的士兵和安多哈尔市民外，这片墓地还安置着光明使者乌瑟尔的宏伟陵墓。这里还安息着炮手达尔加，并立有一座纪念约瑟夫·雷德帕斯的纪念碑，但他本人的遗体已被摧毁。",al={"悔恨岭的著名墓葬","这里埋葬的名人"}},{q="如今悔恨岭构成了什么样的威胁？",a="在巫妖王的瘟疫锅腐蚀下，墓地里的死者已经复活，化身为骷髅剥皮者、流着口水的食尸鬼和骷髅法师。在盘踞于东南部墓穴的天灾指挥官带领下，这些亡灵威胁着通往安多哈尔的南向道路。",al={"悔恨岭的天灾军团","谁控制着悔恨岭"}}},fp="11,257,18.667.0,20.521.0,41.275.0,42.265.0,29.248.0,40.260.0"}
P.entries["subzone:sorrowmurk"] = {n="忧伤湿地",s="忧伤湿地是悲伤沼泽中，位于泪水之池正东方的一片险恶湿地区域。长期以来，这里一直被负责守卫沉没的神庙入口的绿龙族巡逻队所占据，它是东部沼泽中最危险的地区之一。",h="忧伤湿地是悲伤沼泽中，位于泪水之池正东方的一片险恶湿地区域。长期以来，这里一直被负责守卫沉没的神庙入口的绿龙族巡逻队所占据，它是东部沼泽中最危险的地区之一。",kw={"阿塔哈卡","龙人","绿龙军团","绿幼龙","泪水之池","忧伤湿地","悲伤沼泽"},ang={["class:Druid"]="这些湿地中沾染了悲伤腐化的翡翠梦境守护者，对于任何自然仆从来说，这里的绿龙族都是令人悲痛的景象。"},sec={{t="危险的边界",b="忧伤湿地沿泪水之池的东侧延伸，是一片与禁忌之海接壤的茂密而阴暗的泥沼。多年来，这里的沼泽和纠结的枝桠间一直爬满了凶猛的绿龙人与高大的幼龙，它们是负责看守阿塔哈卡神庙遗迹的龙群遗部。它们的存在使得只有经验丰富的旅行者才敢涉足这片潮湿的土地。"}},faq={{q="忧伤湿地在哪里？",a="忧伤湿地位于悲伤沼泽的最东端，就在泪水之池和阿塔哈卡神庙的沉没遗迹之外，紧邻海岸。",al={"忧伤湿地位置","忧伤湿地在哪里","忧伤湿地地图"}},{q="忧伤湿地里有什么生物？",a="该地区以绿龙族而闻名，包括好斗的龙人以及在该神庙水域周围严密巡逻的大型幼龙。",al={"忧伤湿地怪物","忧伤湿地里有什么","忧伤湿地敌人"}},{q="为什么忧伤湿地里会有绿龙？",a="绿龙军团受伊瑟拉之托，负责监视泪水之池，并确保阿塔哈卡神庙中沉没的邪恶被封印。",al={"为什么这里有龙","悲伤沼泽绿龙军团","神庙巨龙"}}},fp="10,272,17.411.0,32.173.0,38.151.0,46.159.0"}
P.entries["subzone:south-gate-outpost"] = {n="南门哨岗",s="南门哨岗是一座坚固的矮人山地哨所，位于丹莫罗与洛克莫丹之间的南门小径沿途。这里的守山人驻守着这条积雪的南方道路，守护着在铁炉堡的寒冷高地与洛克湖温带山谷之间往来的旅客，保障交通顺畅。",h="南门哨岗是一座坚固的矮人山地哨所，位于丹莫罗与洛克莫丹之间的南门小径沿途。这里的守山人驻守着这条积雪的南方道路，守护着在铁炉堡的寒冷高地与洛克湖温带山谷之间往来的旅客，保障交通顺畅。",kw={"丹莫罗","矮人","铁炉堡之路","洛克莫丹","守山人","南门哨岗","南门小径","塞尔萨玛"},ang={["faction:Alliance"]="这座哨所是卡兹莫丹主要国内补给线上一处可靠的军事庇护所，确保了首都与东部定居点之间的通道畅通。",["race:Dwarf"]="对于第一次离开寒脊山谷和丹莫罗的矮人来说，南门哨岗是进入洛克莫丹那充满活力、阳光明媚的土地之前，最后的一处寒冷地标。"},sec={{t="南方道路的守望者",b="南门哨岗坐落于南门小径高山峡谷的中途，标志着丹莫罗积雪山坡与洛克莫丹葱郁盆地之间的边界。驻扎在这里的铁炉堡守山人负责巡逻崎岖的之字形山路，并将危险的野生生物挡在主干道外。与北门哨岗处境艰难的同僚相比，这里的守军在很大程度上已经肃清了他们负责的路段，使得前往塞尔萨玛的旅客、朝圣者和商队能够相对安全地通行。"}},faq={{q="南门哨岗的作用是什么？",a="它作为南门小径上的坚固边境检查站和驻军点发挥作用。驻扎于此的守山人负责清理积雪覆盖的交通要道，防止山中野兽和敌对入侵者在丹莫罗与洛克莫丹之间往来。",al={"为什么这里有南门哨岗","南门哨岗的用途","南门哨岗是什么"}},{q="为什么这里比北门哨岗平静得多？",a="南门哨岗的驻军成功清理了道路周边极具侵略性的野生生物。相比之下，北门哨岗面临着更严重的入侵和更狂野的山地地形，这使得南面的小径相对平静。",al={"北门与南门有何区别","南门安全吗","南门与北门对比"}},{q="通过南门哨岗的路通往哪里？",a="向西沿小径上行可进入丹莫罗的积雪高地，前往铁炉堡。向东下行则直接通往洛克莫丹的温带山谷，道路蜿蜒直达塞尔萨玛定居点。",al={"这条路通向哪里","南门道路目的地","南门小径路线"}}},fx={["3c6e6693"]={q="南门哨岗是什么地方？",a="南门哨岗是一处设防的矮人山间驿站，坐落在丹莫罗东部的南门小径沿线。它正位于连接丹莫罗与更广阔山谷的积雪高山隘口上，接待向东前往塞尔萨玛的旅人和信使。",al={"南门哨岗是什么","南门哨岗信息","南门小径哨岗"}},["790564b9"]={q="谁住在南门哨岗，或负责管理那里？",a="铁炉堡的山地矮人驻守着这座偏远的边境哨站。他们监视穿越山隘的旅人、管理补给，并与当地巡逻人员密切协作，确保丹莫罗和洛克莫丹之间的山道通行安全。",al={"谁控制南门哨岗","谁管理南门哨岗","谁住在南门哨岗"}},["94f233ba"]={q="南门哨岗危险吗？",a="哨岗本身相当安全。驻守的山地矮人勤勉地清除了山隘沿线大部分逼近的山地野兽，使这座哨站免遭北门哨岗所面临的猛烈生物袭击和严峻威胁。",al={"南门安全吗","南门哨岗危险吗","南门哨岗的危险"}},["09ad7c8c"]={q="为什么叫南门哨岗？",a="它得名于南门小径。南门小径是穿过丹莫罗与洛克莫丹之间峭壁的南部山口，与北门哨岗守卫的北部通道相对应。",al={"南门哨岗为何得名","南门哨岗名称由来","为何叫南门"}}},fp="18,291,29.544.0,42.228.0,57.255.0,52.251.0"}
P.entries["subzone:south-gate-pass"] = {n="南门小径",s="南门小径是连接丹莫罗的雪域高地与洛克莫丹山谷盆地的主要山道。它由矮人隧道和哨岗环绕，是往返于铁炉堡和塞尔萨玛定居点之间最直接的路线。",h="南门小径是连接丹莫罗的雪域高地与洛克莫丹山谷盆地的主要山道。它由矮人隧道和哨岗环绕，是往返于铁炉堡和塞尔萨玛定居点之间最直接的路线。",kw={"丹莫罗","洛克莫丹","登山者","南门哨岗","南门小径","塞尔萨玛","隧道"},ang={["faction:Alliance"]="该关口是连接铁炉堡与东部联盟领土的重要内部动脉，由国王的登山者进行维护和保卫。",["race:Dwarf"]="对于离开丹莫罗的矮人来说，南门小径是冰冷的空气逐渐转变为洛克莫丹开阔谷地与采石场的一道门槛。"},sec={{t="通往东方之路",b="南门小径径直穿过卡兹莫丹山脉，连接着西侧丹莫罗的高山与东侧洛克莫丹起伏的谷地。离开寒冷山坡的旅行者穿过石拱门，便会进入气候更为温和的矮人腹地。由于这条路直通塞尔萨玛，因此常有登山者、信使和从首都出发的受训冒险者往来。"},{t="受守护的关口",b="南门哨岗驻扎着时刻保持警惕的矮人登山者，他们负责保卫关口，抵御野兽和徘徊的穴居人。虽然此处通常比深谷中的荒野更安全，但仍建议旅行者留在道路上，因为敌对的野生生物和游荡的威胁经常试探性地袭击关口周边。"}},faq={{q="南门小径通向哪里？",a="向西穿过隧道即可进入丹莫罗的雪域高地，那是通往铁炉堡的道路。向东行进则会下到洛克莫丹盆地，直达塞尔萨玛定居点。",al={"南门小径通往哪里","南门小径目的地","南门之路"}},{q="南门小径旅行安全吗？",a="由于南门哨岗驻扎有矮人卫兵，道路本身相对安全，但隧道口外周边的岩脊和山坡上有熊、蜘蛛和不断入侵的穴居人出没。",al={"南门小径危险吗","南门小径威胁"}},{q="为什么这条路比北门小径使用得更频繁？",a="南门小径提供了丹莫罗与塞尔萨玛之间最直接、最便捷的陆路连接，因此成为当地贸易、补给商队和前往洛克莫丹中心地带的旅行者的首选路线。",al={"南门与北门对比","为什么要走南门"}}},fx={ae3b1570={q="南门小径是什么地方？",a="南门小径是一条重要的山间通道，穿过西侧白雪覆盖的丹莫罗与东侧洛克莫丹山谷之间的峭壁。由于它的出口就在塞尔萨玛镇附近，这里成为山地矮人、信使和旅人往返铁炉堡故土与洛克湖之间的主要路线。",al={"南门小径信息","南门小径是什么","南门小径背景"}},d7b0d8f2={q="谁负责守卫南门小径？",a="驻扎在南门哨岗的铁炉堡山地矮人负责守卫和维护这条山径。这些矮人哨兵监视着穿过隧道的往来人员，抵御周边山丘上潜伏的野兽和敌对威胁，确保贸易路线畅通。",al={"谁控制南门小径","南门小径守卫","南门哨岗"}},["487bb631"]={q="为什么叫南门小径？",a="这条小径根据其相对于分隔丹莫罗和洛克莫丹的山脉的位置而得名。它是穿越山脉的南部门户，北面与之相对应的是北门小径。",al={"南门小径名称含义","为何叫南门小径","为何叫南门"}}},fp="15,259,13.416.0,19.325.0,32.214.0,34.211.0,48.220.0"}
P.entries["subzone:south-seas"] = {n="南海",s="南海涵盖了分隔卡利姆多南部地区和东部王国的广阔阳光普照的水域。这些热带海域拍打着塔纳利斯和荆棘谷的海岸，以有利可图的贸易路线、危险的礁石和肆无忌惮的海盗船队而闻名。",h="南海涵盖了分隔卡利姆多南部地区和东部王国的广阔阳光普照的水域。这些热带海域拍打着塔纳利斯和荆棘谷的海岸，以有利可图的贸易路线、危险的礁石和肆无忌惮的海盗船队而闻名。",kw={"血帆","海盗","南海","热砂","荆棘谷","塔纳利斯","泰拉比姆","赞达拉"},ang={["class:Rogue"]="无法无天的南海是海盗财团和私掠者的生命线，为那些擅长接舷战、走私违禁品以及游走于残酷港口政治中的恶棍提供了无穷的机会。",["profession:Cooking"]="南海奇异的水域和沿岸海滩出产珍贵的海洋鱼类、巨型乌贼，以及从泰拉比姆等孤立岛屿运出的著名甜香蕉。"},sec={{t="剑客的边疆",b="南海向南延伸，位于无尽之海和大漩涡下方，冲刷着塔纳利斯的沙漠和荆棘谷郁郁葱葱的丛林。自一万年前大分裂将原始大陆撕裂以来，这片海洋孕育了偏远的热带岛屿、独特的海洋生物和独立的商贸网络。地精航运财团在热砂港和藏宝海湾等避风港运作，维持着穿过海浪的脆弱航线。然而，这片水域依然以无法无天而著称，到处都是海盗、血帆海盗以及掠食性的海洋生物，它们捕食任何胆敢远离海岸的船只。"},{t="隐藏的深渊与遥远的群岛",b="在沿海贸易航线之外，散布着一系列传奇岛屿和沉没的危险。南海中散布着著名的土地，包括古老的巨魔岛屿赞达拉和物产丰富的泰拉比姆海岸。然而，商船水手必须面对的远不止强盗；更深的水域潜藏着巨大的巨型乌贼、原始海龟以及守护着被波涛吞没的古代遗迹的潜伏娜迦。航行在这片水域需要经验丰富的船长、可靠的海图和强大的火力。"}},faq={{q="哪些地区与南海接壤？",a="在卡利姆多南部，南海构成了塔纳利斯的海岸线，靠近奥丹姆的封印大门。穿过东部的大洋，它们冲刷着荆棘谷及其哈圭罗岛和尤亚姆巴岛等外围岛屿的海岸。",al={"南海在哪里","南海边界","南海海岸"}},{q="谁控制着南海的航运？",a="没有任何单一势力统治南海。热砂财团控制着热砂港和藏宝海湾之间的主要商船交通，但他们不断与血帆海盗和南海自由海盗等敌对海盗组织争夺这些水域。",al={"谁统治南海","南海贸易","南海港口"}},{q="有哪些危险生物生活在这些水域？",a="开阔的海面上充满了危险，从贪婪的巨型乌贼和沿海礁鲨到披甲的巨型海龟，应有尽有。在第二次战争中，部落的暴风掠夺者氏族甚至捕获了这些水域原生的巨型海龟，将它们改装成海军潜水艇。该地区的岛屿还潜伏着食肉的血翼蝙蝠和出没的娜迦巡逻队。",al={"南海怪物","塔纳利斯海怪","南海生物"}},{q="南海里有哪些著名的岛屿？",a="深海中著名的岛屿包括物产丰富的泰拉比姆岛和巨魔帝国历史悠久的国度赞达拉。靠近海岸的地方则是一些较小的地标，如尤亚姆巴岛和哈圭罗岛。",al={"南海岛屿","科赞 赞达拉 南海","南海岛屿列表"}}},fx={b58adc59={q="南海是什么地方？",a="南海是无尽之海南部辽阔的海域，将卡利姆多和东部王国的南部区域分隔开来。这片温暖的热带海域位于狂暴的巨浪之下，拍打着塔纳利斯和荆棘谷的海岸，散布着偏远的群岛、海盗据点和未经探索的岛屿。",al={"南海是什么","南海概况","南海在哪里"}},["89d72661"]={q="南海的历史上发生过什么？",a="一万年前，大分裂撕碎了陆地，当时整个艾泽拉斯还是一块完整的大陆。上古之战期间，永恒之井爆炸，海水涌入裂隙，将大陆撕裂，并形成了巨浪和周边海域。散布在南海中的岛屿，都是那个远古世界的残余。",al={"南海历史","南海如何形成","南海的起源"}},["68566e28"]={q="在南海航行危险吗？",a="这片海域以险恶著称。除了变幻莫测的天气和危险的暗礁，南海还遍布凶猛的掠食者，包括巨型乌贼，以及在热带岛屿筑巢、吞食血肉的巨大血翼蝙蝠。更糟的是，血帆海盗等凶残的海盗集团在航道上游荡，袭击商船和胆敢前来的旅人。",al={"南海危险吗","南海的险情","南海的威胁"}},["7fe84177"]={q="为什么叫南海？",a="这个地区的名称直接源自其地理位置：它是无尽之海南部的一片海域，覆盖中央巨浪以南、毗邻两块主要大陆南岸的水域。",al={"南海名称由来","南海名称是怎么来的"}}},fp="10,284,25.656.0,31.514.0,33.241.0,40.273.0,46.341.0,47.214.0"}
P.entries["subzone:south-tide-s-run"] = {n="南流海岸",s="南流海岸是银松森林孤寂的西南海岸线，沿着无尽之海冰冷的水域延伸。这些潮湿的沙滩与海浪位于森林内陆的侧翼，与北流海岸互为南部对应。",h="南流海岸是银松森林孤寂的西南海岸线，沿着无尽之海冰冷的水域延伸。这些潮湿的沙滩与海浪位于森林内陆的侧翼，与北流海岸互为南部对应。",kw={"无尽之海","银松海岸","银松森林","南流海岸"},ang={["race:Undead"]="这片狂野的西南海岸远离瑟伯切尔的庇护，使其成为一片很少有被遗忘者踏足的空旷边境。"},sec={{t="西海岸",b="南流海岸沿着银松森林的西南边缘延伸，在树林与无尽之海之间形成了一道荒凉的边界。与通往格雷迈恩之墙、受到保护的东部道路不同，这条开阔的海岸直接承受着西部潮汐的冲击，成为了一片荒凉的沿海荒野，基本未受内陆定居点的影响。"}},faq={{q="南流海岸位于哪里？",a="南流海岸占据了银松森林的西南海岸线，与无尽之海的广阔水域接壤。",al={"南流海岸在哪里","南流海岸位置","南流海岸地图"}},{q="南流海岸与北流海岸有什么不同？",a="两者都是构成银松森林西部海岸线的长滩，但南流海岸覆盖了海岸的南部，而北流海岸则沿着西北方向靠近提瑞斯法林地边界的地方延伸。",al={"北流海岸与南流海岸的区别","流海岸之间的差异"}},{q="南流海岸沿线有任何定居点吗？",a="海滩本身没有任何主要城镇或哨所。大多数被遗忘者的活动仍集中在主要交通要道附近的内陆地区，使得这条海岸线处于与世隔绝的状态。",al={"南流海岸的城镇","谁居住在南流海岸"}}},fx={c53efa4c={q="南流海岸是什么地方？",a="南流海岸是银松森林西南部的一段海岸，沿着无尽之海延伸。与北面的北流海岸一道，它构成了该地区的西部海岸线。",al={"南流海岸是什么","南流海岸信息","南流海岸"}},d867ddea={q="为什么叫南流海岸？",a="它因位于银松森林海岸线的南段而得名，与无尽之海沿岸的北流海岸相对应。",al={"南流海岸为何得名","南流海岸名称含义","南流海岸名称"}}},fp="16,238,17.353.0,34.119.0,55.234.0,49.159.0"}
P.entries["subzone:southern-gold-road"] = {n="南黄金之路",s="南黄金之路是穿越贫瘠之地南半部的一条重要沙漠通衢，连接了中部平原与升降梯。它是区域贸易不可或缺的动脉，往来于卡利姆多远方的商队、物资和旅客都经由此地。",h="南黄金之路是穿越贫瘠之地南半部的一条重要沙漠通衢，连接了中部平原与升降梯。它是区域贸易不可或缺的动脉，往来于卡利姆多远方的商队、物资和旅客都经由此地。",kw={"贫瘠之地","商队","黄金之路","升降梯","南黄金之路","千针石林"},ang={["faction:Horde"]="这条路是贫瘠之地中心十字路口与临近千针石林的南部哨所之间部落补给线的中枢。"},sec={{t="南方的动脉",b="Officially beginning at the stone bridge dividing the northern and southern halves of the Barrens, the Southern Gold Road runs directly south until it meets the Great Lift leading down into the Thousand Needles. Like the northern portion simply named the Gold Road, this dusty highway derives its moniker from the endless stream of lucrative merchant caravans that trek along its length. Despite constant harassment from local quilboar tribes and predators prowling the savannah, it remains one of the busiest long-distance paths on the continent, ferrying goods between remote outposts and bustling ports."},{t="遥远之地的十字路口",b="这条道路上的往来不仅限于部落的交通。远道而来的冒险者和坚韧的商人——他们来自塔纳利斯南部沙漠的加基森、黑海岸多雾的海岸边，或是月光林地神圣的永夜港——都会踏上这片被太阳炙烤的土地。对于那些步行穿越卡利姆多内陆的旅行者来说，活着走完南黄金之路是一场艰苦的成人礼。"}},faq={{q="南黄金之路的起点和终点在哪里？",a="这条路正式起始于分割贫瘠之地南北半部的桥梁，向南延伸，直到到达升降梯处的千针石林边缘。",al={"南黄金之路路径","南黄金之路路线","南黄金之路在哪里"}},{q="为什么叫它黄金之路？",a="这条通衢因常年往来的高价值贸易商队而得名，商队运送着宝贵的货物、矿石和钱币，横跨卡利姆多的中心地带。",al={"为什么叫黄金之路","黄金之路名称由来","黄金之路含义"}},{q="黄金之路和南黄金之路有什么区别？",a="分界线是穿过贫瘠之地中心地带的桥梁。桥梁以北被称为黄金之路，而通往南侧升降梯的路段则被划定为南黄金之路。",al={"黄金之路与南黄金之路","两条黄金之路"}},{q="谁会走这段路？",a="除了当地的部落信使和巡逻队外，商人和探险家也会利用这条路线在遥远的领地之间往来，将远南的加基森与远北的黑海岸和月光林地连接起来。",al={"谁使用南黄金之路","南黄金之路商队"}}},fp="18,301,19.606.0,29.443.0,48.191.0,31.158.0,72.228.0,39.226.0"}
P.entries["subzone:southern-savage-coast"] = {n="南野人海岸",s="南野人海岸包含了紧贴荆棘谷西南部的漫长海滩和潮汐水域。这些海岸不仅面临着南海深处潜藏的危险，还是野生猛兽、敌对娜迦以及时刻威胁着过往船只的沿海掠夺者的巢穴。",h="南野人海岸包含了紧贴荆棘谷西南部的漫长海滩和潮汐水域。这些海岸不仅面临着南海深处潜藏的危险，还是野生猛兽、敌对娜迦以及时刻威胁着过往船只的沿海掠夺者的巢穴。",kw={"藏宝海湾","加尼罗哨站","野人海岸","南海","南野人海岸","荆棘谷","暗礁海"},ang={["class:Hunter"]="宽阔开阔的海滩是两栖猎物、海岸猫科动物和蜥蜴的理想追踪地，这里的视野远比丛林内部幽闭的灌木丛要好得多。"},sec={{t="危险的海岸线",b="南野人海岸沿着南部丛林的西侧边缘延伸，标志着大陆与南海温暖洋流交汇的地带。它与北部的野人海岸被暗礁海的水下遗迹和重重危机隔开。这条海岸线穿过古拉巴什竞技场和纳克迈尼圣泉附近的小海湾，一路延伸，经过藏宝海湾和加尼罗哨站后逐渐变窄。尽管这里的海滩相比令人窒息的丛林内部视野开阔，但旅行者仍需应对凶猛的爬行类捕食者、在浅滩猎食的娜迦，以及四处搜寻猎物的海盗。"}},faq={{q="南野人海岸从哪里开始，到哪里结束？",a="它覆盖了荆棘谷的西南海岸线，起始于暗礁海下方，向南沿着海岸延伸，经过藏宝海湾和加尼罗哨站，最终过渡到蛮荒海岸。",al={"南野人海岸位置","南野人海岸在哪里","野人海岸边界"}},{q="它与北部的野人海岸有什么不同？",a="这两段海岸线被暗礁海分隔开。北部的野人海岸沿着北荆棘谷的大海海域延伸，而南野人海岸则位于南角，毗邻南海。",al={"野人海岸与南野人海岸的区别","为什么有两个野人海岸","暗礁海边界"}},{q="旅行者在海滩上会遇到什么威胁？",a="开阔的沙滩上遍布着凶恶的蜥蜴、鳄鱼、从浅滩爬出的敌对娜迦以及巡逻的领地海盗。",al={"南野人海岸危险吗","南野人海岸怪物","海岸沿线的威胁"}},{q="藏宝海湾控制着这条海岸线吗？",a="不。黑水强盗和热砂港仅对藏宝海湾的港口及其直接航道保持控制。南北两侧的荒野海滩依然是无法无天的蛮荒之地。",al={"藏宝海湾拥有这片海滩吗","热砂港对海岸的控制","地精领土"}}},fp="21,281,23.616.0,51.203.0,51.226.0,50.167.0,38.205.0"}
P.entries["subzone:southfury-river"] = {n="怒水河",s="怒水河是卡利姆多中部最主要的水道之一，它从海加尔山的高处发源，一路向南，冲刷出宽阔湍急的河道。这条河流形成了艾萨拉与灰谷，以及杜隆塔尔与贫瘠之地之间的天然边界，最终在棘齿城附近汇入无尽之海。",h="怒水河是卡利姆多中部最主要的水道之一，它从海加尔山的高处发源，一路向南，冲刷出宽阔湍急的河道。这条河流形成了艾萨拉与灰谷，以及杜隆塔尔与贫瘠之地之间的天然边界，最终在棘齿城附近汇入无尽之海。",kw={"灰谷","艾萨拉","贫瘠之地","杜隆塔尔","海加尔山","奥格瑞玛","棘齿城","怒水河"},ang={["faction:Horde"]="怒水河充当了杜隆塔尔的西部防御边界，也是连接主城与贫瘠之地核心地带的天然交通干线。"},sec={{t="重要的天然分界线",b="怒水河发源于海加尔山的高处，奔腾而下形成壮观的瀑布，随后流经卡利姆多中部。奔腾的河水成为了明确的地理分界，将灰谷的圣洁森林与古老的艾萨拉隔开，也将杜隆塔尔的干旱丘陵与贫瘠之地的草原分开。只有少数几座战略桥梁敢于横跨这湍急的水流，其中最著名的是守卫着奥格瑞玛后门的重型桥梁，以及连接杜隆塔尔与贫瘠之地的渡口。河流最终在棘齿城中立港口东北方的一处瀑布汇入无尽之海。"},{t="战略重要性",b="对于部落来说，怒水河既是一道盾牌，也是一条至关重要的天然补给线。它保护着杜隆塔尔和奥格瑞玛的西部免受地面部队的直接突袭，同时也为这片焦灼干旱的土地提供了新鲜的山泉径流。就在通往奥格瑞玛的西部渡口以北，存在一个独特的地理枢纽，四个主要区域在此交汇：灰谷、艾萨拉、杜隆塔尔和贫瘠之地。控制这条奔腾的水道可以确保奥格瑞玛与部落边远定居点之间的补给线畅通无阻。"}},faq={{q="怒水河从哪里发源，又在哪里汇入大海？",a="怒水河发源于海加尔山的高山地带，奔流而下形成壮观的瀑布，流经低地。它向南流经灰谷、艾萨拉、杜隆塔尔和贫瘠之地，最后在棘齿城东北方的一处瀑布汇入无尽之海。",al={"怒水河源头","怒水河流向","怒水河入海口"}},{q="这条河流沿途与哪些地区接壤？",a="这条河流在北部将灰谷与艾萨拉隔开，在南部将贫瘠之地与杜隆塔尔隔开。值得注意的是，在奥格瑞玛西侧桥梁以北，四个区域沿河岸交汇于一点。",al={"怒水河流经区域","怒水河边界"}},{q="旅行者可以在哪里跨越怒水河？",a="主要有三座桥梁横跨怒水河：一座连接艾萨拉和灰谷，一座通往奥格瑞玛的后门，还有一座连接杜隆塔尔与贫瘠之地的重要桥梁。",al={"怒水河桥梁","如何横跨怒水河","怒水河上的桥"}},{q="为什么这条河流对奥格瑞玛很重要？",a="这条河流构成了捍卫奥格瑞玛和杜隆塔尔西侧防线的天然屏障。此外，它新鲜的山泉水是这片干旱地区不可或缺的生命线。",al={"怒水河与奥格瑞玛","部落为何重视怒水河"}}},fx={dbc3f3f2={q="怒水河是什么地方？",a="怒水河是卡利姆多中部最显著的水道。河水从海加尔山高处向南奔流，在灰谷的森林与艾萨拉的废墟之间冲出天然边界，随后又向下流去，将杜隆塔尔与贫瘠之地分隔开来。它最终从棘齿城东北方的一处层叠瀑布注入无尽之海。",al={"怒水河是什么","怒水河概况","怒水河背景"}},["4c95fcc0"]={q="怒水河危险吗？",a="怒水河水流湍急，从海加尔山奔流而下并注入大海之处还有险峻的瀑布。除了危险的急流，两岸土地也遍布冲突和徘徊的野兽，因此不经引导贸然渡河，远比走设防的桥梁危险得多。",al={"怒水河危险吗","怒水河的威胁","怒水河的危险"}}},fp="15,301,22.606.0,20.552.0,45.251.0,34.213.0,46.196.0,40.208.0"}
P.entries["subzone:southmoon-ruins"] = {n="南月废墟",s="南月废墟是位于塔纳利斯南部、守卫之谷正北方的古代石质遗迹。这些残垣断壁长期被残暴的沙槌食人魔占据，遗迹中保留着在沙漠将其吞没之前统治此地的古代巨魔文明的遗迹。",h="南月废墟是位于塔纳利斯南部、守卫之谷正北方的古代石质遗迹。这些残垣断壁长期被残暴的沙槌食人魔占据，遗迹中保留着在沙漠将其吞没之前统治此地的古代巨魔文明的遗迹。",kw={"沙槌食人魔","遗迹","南月","南月废墟","塔纳利斯","守卫之谷"},ang={["race:Dwarf"]="穿越南部塔纳利斯的矮人旅行者在南月废墟除了饱经风霜的巨魔石雕和驻扎在其中的沙槌食人魔之外，几乎一无所获。",["race:Troll"]="对于暗矛巨魔来说，这些断壁残垣是一次令人清醒的审视，让他们看到了远房巨魔亲戚曾经的辉煌如今已沦落至在烈日下的一片荒凉。"},sec={{t="流沙之中的石块",b="南月废墟矗立在塔纳利斯南部酷热的荒原上，作为曾经统治卡利姆多南部疆域的古代巨魔帝国的风蚀见证而存在。就像附近的东月废墟和日影废墟一样，这里的石柱和祭坛历经了数千年的风蚀和沙砾磨砺。此地经常成为沙槌食人魔的肮脏营地，他们对过去的工艺毫无敬意，仅仅将这些古老的建筑用作遮风避雨和占据领地的场所。"},{t="瓦砾之下的秘密",b="这些建筑遗迹带有明显的巨魔风格，但关于是谁建造了南月废墟，以及他们为何遗弃这里，几乎没有记载留存。无论他们留下了什么，都已经埋葬在流动的黄沙之下，而那些在石柱间盘踞的食人魔对此毫无兴趣。"}},faq={{q="南月废墟最初是谁建造的？",a="南月废墟是古代巨魔的遗迹，是曾经占据如今塔纳利斯沙漠南部疆域的巨魔文明的残存遗迹。",al={"南月废墟建造者","南月历史","这是巨魔遗迹吗"}},{q="目前是谁居住在这些废墟中？",a="这些废墟传统上一直由沙槌食人魔占据，他们游荡到塔纳利斯，将各种破败的古代哨所作为营地，并赶走了其他拾荒者。",al={"谁住在这里","南月废墟怪物","南月废墟的沙槌食人魔"}},{q="南月废墟位于哪里？",a="它们位于塔纳利斯的南半部，地处守卫之谷的西北方，中部沙漠荒原的南侧。",al={"南月废墟位置","南月废墟在哪里","如何找到南月废墟"}}},fp="15,295,28.499.0,26.276.0,41.160.0,33.195.0,38.130.0"}
P.entries["subzone:southpoint-tower"] = {n="南点哨塔",s="南点哨塔是一座位于希尔斯布莱德丘陵西侧边界的洛丹伦废弃侦查塔，俯瞰着通往银松森林的道路。这座曾经的人类哨所如今已是残垣断壁，被遗忘者侦察兵用来监视该地区的联盟动向。",h="南点哨塔是一座位于希尔斯布莱德丘陵西侧边界的洛丹伦废弃侦查塔，俯瞰着通往银松森林的道路。这座曾经的人类哨所如今已是残垣断壁，被遗忘者侦察兵用来监视该地区的联盟动向。",kw={"亡灵哨兵莱什","希尔斯布莱德农场","希尔斯布莱德丘陵","侦察塔","银松森林","南点哨塔"},ang={["faction:Alliance"]="这座废弃的塔楼窝藏着监视通往银松森林道路的敌方间谍，这使它成为保护希尔斯布莱德人类定居点的侦察兵们的天然打击目标。",["race:Undead"]="对于被遗忘者而言，这座塔楼在银松森林边界提供了一个不可或缺的侦察高地，用于监测从希尔斯布莱德出发的人类部队调动。"},sec={{t="废墟哨兵",b="南点哨塔耸立在连接银松森林和希尔斯布莱德丘陵的公路南侧，最初由洛丹伦王国建造，旨在守卫东部农田与西部森林之间的交通往来。第三次战争及天灾军团摧毁王国后，石砌建筑便化为废墟。如今，它屋顶尽失，砖石剥落，成为这片破碎领土上人类统治的一座孤立遗迹。"},{t="高地之眼",b="尽管已成废墟，但这处制高点仍具有重要的战术价值。遗忘者在此维持着一个前哨站，并派遣亡灵哨兵莱什等特工驻守于此，窥探当地的联盟巡逻队、附近的希尔斯布莱德农场人类定居点以及沿主路经过的旅行者。由于其孤立的位置紧邻敌对领土，这座塔楼频繁成为小规模冲突的爆发点。"}},faq={{q="南点哨塔位于何处？",a="南点哨塔位于希尔斯布莱德丘陵的西缘，就在通往银松森林的道路正南方，希尔斯布莱德农场以西。",al={"南点哨塔位置","南点哨塔在哪里","寻找南点哨塔"}},{q="目前是谁控制着南点哨塔？",a="该塔楼由遗忘者控制。一名名叫亡灵哨兵莱什的特工驻扎在其残破的墙壁内，观察着道路并监视附近的联盟部队。",al={"谁在南点哨塔","南点哨塔归谁所有","南点哨塔阵营"}},{q="为什么塔楼会变成废墟？",a="在洛丹伦陷落、天灾军团蹂躏该地区时，这座塔楼遭到破坏并被废弃。它从未被修复，只剩下破碎的石墙。",al={"为什么南点哨塔是破损的","谁摧毁了南点哨塔"}},{q="为什么联盟玩家会攻击这个前哨站？",a="该哨所驻有一名正在监视人类领土的被遗忘者侦察兵。其紧邻边界的孤立位置使其成为往返南海镇与西部道路的联盟旅行者眼中一个容易且诱人的目标。",al={"为什么要击杀亡灵哨兵莱什","联盟攻击南点哨塔"}}},fx={dd4aae73={q="南点哨塔是什么地方？",a="南点哨塔是一座摇摇欲坠的人类瞭望塔，位于希尔斯布莱德丘陵西缘，俯瞰通往银松森林的道路。它曾是人类守军的防御工事，如今大部分已成废墟，暴露在外，充当前沿战术监视哨。",al={"南点哨塔是什么","南点哨塔的用途","南点哨塔介绍"}},f07dd792={q="谁居住或驻守在南点哨塔？",a="这座哨塔并非永久定居点，但目前有被遗忘者的特工亡灵哨兵莱什驻守。她藏身于破碎的石墙之间，利用高处监视南海镇与西部边境之间的联盟动向。",al={"南点哨塔有什么人","南点哨塔的驻守者","谁住在南点哨塔"}},["0d7406b8"]={q="南点哨塔危险吗？",a="危险与否取决于你的阵营。亡灵哨兵莱什会毫不犹豫地袭击沿路前往银松森林的联盟旅人；联盟斥候和冒险者也常常袭击她孤立的据点，以破坏被遗忘者的情报活动。",al={"南点哨塔危险吗","南点哨塔有多危险","南点哨塔的威胁"}}},fp="16,286,17.431.0,17.407.0,34.162.0,40.173.0,26.163.0,44.214.0"}
P.entries["subzone:southridge-beach"] = {n="南山海滩",s="南山海滩沿着艾萨拉中部风暴海湾的南岸延展开来。这里曾是古老的卡多雷城市艾萨拉的一处宏伟区划，如今却只剩下破碎的废墟，被敌对的纳迦、鱼人和高大的海巨人所占据。",h="南山海滩沿着艾萨拉中部风暴海湾的南岸延展开来。这里曾是古老的卡多雷城市艾萨拉的一处宏伟区划，如今却只剩下破碎的废墟，被敌对的纳迦、鱼人和高大的海巨人所占据。",kw={"艾萨拉","风暴海湾","甲壳生物","鱼人","纳迦","海巨人","南山海滩"},ang={["race:NightElf"]="南山海滩上的破败建筑无声地诉说着大分裂前高等精灵文明的辉煌与悲惨陨落，令人唏嘘不已。"},sec={{t="沉没的海岸线",b="南山海滩构成了风暴海湾汹涌水域的南边界。数千年前，这片海岸曾是高等精灵城市艾萨拉辉煌的一部分，但大分裂撕裂了大地，将其大部分宫殿沉入海底。如今，风化的大理石柱和饱经风霜的石质亭阁散布在沙滩上。这里早已不再有学者和贵族的身影，取而代之的是好战的毒鞭纳迦、潜行的甲壳生物、凶残的多头蛇以及四处拾荒的鱼人部落。即便是巨大的海巨人也会偶尔从深海游荡到岸上。"}},faq={{q="南山海滩位于何处？",a="南山海滩位于艾萨拉中部，坐落在风暴海湾的南缘，紧邻内陆悬崖下方。",al={"南山海滩位置","南山海滩在哪里","艾萨拉南山海滩"}},{q="海滩上散布着什么遗迹？",a="沙滩上的石柱和拱门是艾萨拉的外围残骸，这是一座曾经伟大的高等精灵城市，在一万年前的大分裂中被摧毁并淹没。",al={"南山海滩遗迹","艾萨拉遗迹海滩","这里的遗迹是什么"}},{q="南山海滩上生活着什么生物？",a="海岸线上布满了纳迦，此外还有原始的鱼人、披甲的甲壳生物、危险的多头蛇，以及偶尔游荡的海巨人。",al={"南山海滩怪物","南山海滩敌人","这里生活着什么"}},{q="为什么这里有这么多纳迦？",a="纳迦从深海涌出，试图收复它们在艾萨拉的前文明遗迹，并在风暴海湾沿岸建立了稳固的军事据点。",al={"为什么海滩上有纳迦","纳迦南山海滩","艾萨拉纳迦"}}},fp="16,244,19.560.0,34.128.0,41.199.0,40.148.0,32.186.0"}
P.entries["subzone:southshore"] = {n="南海镇",s="南海镇是希尔斯布莱德丘陵的一座人类沿海港口，也是洛丹伦沦陷后联盟仅存的几个据点之一。它曾经是一个宁静的渔村，如今却成了一座饱经战火的堡垒，时刻面临着塔伦米尔的被遗忘者驻军、辛迪加不法暴徒以及海岸怪物的威胁。",h="南海镇是希尔斯布莱德丘陵的一座人类沿海港口，也是洛丹伦沦陷后联盟仅存的几个据点之一。它曾经是一个宁静的渔村，如今却成了一座饱经战火的堡垒，时刻面临着塔伦米尔的被遗忘者驻军、辛迪加不法暴徒以及海岸怪物的威胁。",kw={"希尔斯布莱德","jessen","洛丹伦","马雷布","雷德帕斯","南海镇","辛迪加","塔伦米尔"},ang={["faction:Alliance"]="南海镇是你作为联盟成员在北洛丹伦的主要避难所、任务中心和军事堡垒，为你对抗被遗忘者和辛迪加提供必要的支持。",["faction:Horde"]="对于部落——尤其是附近塔伦米尔的被遗忘者来说——南海镇是一个顽固的联盟飞地，侵占了属于亡者的土地。"},sec={{t="洛丹伦的灯塔",b="南海镇在第一次战争期间首次崭露头角，当时载着暴风城王国沦陷后的幸存者的难民船在它的海滩上登陆。尽管在第二次战争期间曾被争夺和占领，但它后来得到了重建，并熬过了第三次战争的恐怖。今天，当洛丹伦的其他地区陷入废墟或处于被遗忘者的统治之下时，南海镇依然坚定地效忠于大联盟。它为流离失所的人类幸存者、白银之手的资深圣骑士以及肯瑞托的学者们提供了避难所。"},{t="四面受敌",b="尽管这里有美丽的码头，米奈希尔港和奥伯丁之间的船只也会在此停靠，而且这里还有著名的海龟浓汤，但南海镇的生活依然充满危险。在赫尼·马雷布镇长和治安官雷德帕斯的领导下，该镇在巨大的压力下艰难求生。在北方，塔伦米尔的被遗忘者为了争夺对希尔斯布莱德的统治权，发动了激烈的边界冲突。在内陆，辛迪加的贵族亡命徒袭击补给线并暗杀当地领导人，同时食人魔、鱼人和娜迦也不断骚扰城镇的边界。"}},faq={{q="既然洛丹伦已经沦陷，为什么南海镇依然站在联盟这一边？",a="南海镇在天灾军团的入侵中幸免于难，未被彻底摧毁。其幸存的人类民众重申了他们对大联盟的历史誓言，并获得了来自暴风城的军事和后勤支持，从而在北方保留了一个立足点。",al={"为什么南海镇属于联盟","谁控制了南海镇","南海镇 联盟 洛丹伦"}},{q="为什么南海镇和塔伦米尔之间会有如此激烈的战斗？",a="塔伦米尔由被遗忘者控制，而南海镇则是该地区主要的联盟堡垒。双方都声称拥有对希尔斯布莱德丘陵的合法统治权，导致了几乎不断的边界冲突、突袭和破坏活动。",al={"南海镇与塔伦米尔的战争","为什么南海镇和塔伦米尔会战斗","希尔斯布莱德冲突"}},{q="谁在领导南海镇？",a="民政事务由赫尼·马雷布镇长处理，他在前任镇长被辛迪加暗杀后接管了职位。军事防御和城镇安全则由治安官雷德帕斯指挥。",al={"南海镇领导人","谁管理南海镇","马雷布镇长"}},{q="除了被遗忘者，南海镇还面临哪些威胁？",a="除了被遗忘者，南海镇还必须抵御海岸上的鱼人和娜迦、从奥特兰克山脉南下的碎颅食人魔，以及盘踞在敦霍尔德城堡的辛迪加犯罪组织。",al={"南海镇的敌人","南海镇面临的威胁"}}},fx={f6e4321c={q="南海镇是什么地方？",a="南海镇是希尔斯布莱德丘陵南岸一座繁忙的港口城镇。在天灾军团摧毁首都后，这里成为洛丹伦仅存的人类文明据点和联盟权力中心之一。尽管周围遍布敌对势力，南海镇仍维持着正常运作的港口、地方政务和坚定的驻军。",al={"南海镇是什么地方","南海镇","南海镇简介"}},b35b5b82={q="南海镇历史上发生过什么？",a="南海镇最初只是一个普通的渔村，第一次战争后接纳了逃离暴风城的难民。第二次战争期间，它因近海石油而成为各方觊觎的战略港口，曾被部落攻陷，战后又被收复并重建。",al={"南海镇历史","南海镇背景","南海镇的历史"}},["856a6b32"]={q="南海镇危险吗？",a="对联盟而言，南海镇有严密守卫，是一处安全的避难所，但周边乡野危机四伏。与塔伦米尔的被遗忘者之间的冲突常常蔓延至丘陵各处，沿海的鱼人和娜迦也威胁着港口。此外，辛迪加盗贼、破碎岭食人魔和徘徊的亡灵都潜伏在城镇外围。",al={"南海镇有多危险","南海镇安全吗","南海镇的威胁"}}},fp="10,321,21.528.0,22.516.0,70.248.0,70.235.0,33.201.0,58.183.0"}
P.entries["subzone:southshore-town-hall"] = {n="Southshore Town Hall",s="南海镇市政厅是希尔斯布莱德丘陵南海岸的行政中心，也是洛丹伦尚存的民政权力机构之一。赫尼·马雷布镇长在厅内协调当地的防御工作，并管理着镇上的幸存居民。这座市政厅是联盟在饱受瘟疫蹂躏的北方苦苦维持立足点时的重要枢纽。",h="南海镇市政厅是希尔斯布莱德丘陵南海岸的行政中心，也是洛丹伦尚存的民政权力机构之一。赫尼·马雷布镇长在厅内协调当地的防御工作，并管理着镇上的幸存居民。这座市政厅是联盟在饱受瘟疫蹂躏的北方苦苦维持立足点时的重要枢纽。",kw={"赫尼·马雷布","希尔斯布莱德","昆德瑞克·赞登","洛丹伦","镇长","南海镇","市政厅"},ang={["faction:Alliance"]="对于抵达北方的联盟勇士来说，南海镇市政厅是提供区域行政授权和发布对抗周边威胁的重要任务的主要民政哨所。",["race:Human"]="人类旅行者将这座市政厅视为洛丹伦失落荣耀的辛酸见证，在这里，一位行使职权的镇长依然在飘扬着破碎王国的旗帜。"},sec={{t="民政统治的堡垒",b="尽管大部分洛丹伦地区都在天灾军团的腐化和被遗忘者的扩张下支离破碎，南海镇的市政厅依然维持着人类政府尚存的样貌。赫尼·马雷布镇长在此处办公，监督日常政务，并与昆德瑞克·赞登等官员协作，保障资源供给并维护民政秩序。在一片被凶残的不死族、辛迪加盗贼和希尔斯布莱德激烈的边境冲突所包围的区域，这座市政厅是指挥城镇在持续不断的威胁中求生的神经中枢。"}},faq={{q="是谁在南海镇市政厅领导着这座城镇？",a="赫尼·马雷布镇长是南海镇的主要行政领导人，他在市政厅内处理镇务，指挥这座人类定居点的防御和行政事务。",al={"这里由谁负责","南海镇镇长","谁管理南海镇"}},{q="南海镇市政厅具有怎样的战略重要性？",a="它代表了洛丹伦在北方最后合法的民政领导机构之一。联盟成员寻求市政厅的指引、赏金任务，以及对抗步步紧逼的被遗忘者和辛迪加匪徒的协同作战。",al={"市政厅为什么重要","南海镇的重要性"}},{q="还有谁在市政厅里工作？",a="除了赫尼·马雷布镇长，还有像昆德瑞克·赞登这样的公务员驻守在市政厅内，协助管理当地事务并支持城镇的运作。",al={"谁在南海镇市政厅里","昆德瑞克·赞登","市政厅npc"}},{q="市政厅是如何与更广阔的联盟保持联系的？",a="虽然历史上南海镇属于洛丹伦王国，但现在它及其领导层极度依赖联盟，通过联盟获得的增援和补给来保卫这一孤立的沿海堡垒，对抗周遭的敌对势力。",al={"南海镇属于联盟吗","与暴风城的联系"}}},fx={ccaa2d22={q="Southshore Town Hall 是什么地方？",a="这座坚固的石制建筑是南海镇的行政中心，也是洛丹伦幸存者的重要治理中枢。地方官员在此协调聚落防务、维持公共秩序，并处理这座被敌对势力包围的避难所日常所需。",al={"southshore town hall","southshore town hall 是什么地方","南海镇这是什么建筑"}},eda35516={q="Southshore Town Hall 发生过什么？",a="第三次战争期间，洛丹伦沦陷于天灾军团之手后，南海镇成为王国幸存者最后几处主要避难所之一。市政厅由此成为地方政权的主要驻地，赫尼·马雷布镇长及其议员在此承担起重任，努力在南部海岸维系合法的人类社会。",al={"southshore town hall 的历史","这里的市政厅发生过什么"}},["49b6de22"]={q="Southshore Town Hall 危险吗？",a="对联盟勇士而言，市政厅有城镇卫兵严密把守，是安全而坚固的庇护所。然而，对部落成员来说，进入这座建筑十分危险；城镇官员和附近的哨兵会立即攻击任何闯入城镇范围的入侵者。",al={"southshore town hall 安全吗","southshore town hall 里危险吗"}}},fp="20,389,23.520.0,49.201.0,57.228.0,36.174.0,61.231.0"}
P.entries["subzone:southwind-village"] = {n="南风村",s="南风村是希利苏斯黄沙中一座暗夜精灵前哨站的闹鬼废墟。在流沙之战中被其拉虫人彻底摧毁，如今村庄的街道上游荡着阵亡守卫者们不安的灵魂，以及四处潜行的其拉虫群。",h="南风村是希利苏斯黄沙中一座暗夜精灵前哨站的闹鬼废墟。在流沙之战中被其拉虫人彻底摧毁，如今村庄的街道上游荡着阵亡守卫者们不安的灵魂，以及四处潜行的其拉虫群。",kw={"范达尔·鹿盔","其拉虫人","拉贾克斯将军","琥珀月之影","希利苏斯","南风村","瓦斯坦·鹿盔","流沙之战"},ang={["class:Druid"]="南风村残破的林地建筑和那些受折磨的古代德鲁伊灵魂，沉重地提醒着人们大自然在面对虫族大军时所遭受的惨痛损失。",["race:NightElf"]="对于暗夜精灵来说，南风村是他们历史上最痛苦的失败之一，而徘徊在残垣断壁间的那些受折磨的幽灵，正是等待着安宁的卡多雷同胞。"},sec={{t="黄沙中的悲剧",b="一千年前的流沙之战期间，南风村曾是暗夜精灵的主要据点。当其拉虫人大军突破防御防线时，大德鲁伊范达尔·鹿盔之子瓦斯坦·鹿盔率领一支小分队驻守该村。这场防御战以彻底的灾难告终：暗夜精灵守卫者们被压倒性的兵力屠戮殆尽，瓦斯坦本人也被拉贾克斯将军拖走并俘虏。村庄被夷为平地，昔日的建筑在烈日下分崩离析。"},{t="受折磨的亡者",b="在毁灭后的千年里，南风村一直是沙漠中未愈合的伤口。那场袭击带来的创伤是如此彻底，以至于阵亡的暗夜精灵哨兵和德鲁伊们的灵魂无法安息。由于无法摆脱生命最后时刻的恐怖，这些不安的幻影在琥珀月之影的带领下，无止境地徘徊在坍塌的石墙间，袭击任何闯入者，而贪婪的其拉虫群则在周围的沙丘中蜂拥肆虐。"}},faq={{q="南风村发生了什么？",a="南风村在一千年前的流沙之战中被摧毁。贪婪的其拉虫人军队蜂拥而至，袭击了暗夜精灵的驻军，无情地屠杀了守卫者并将这座前哨站夷为平地。",al={"为什么南风村是废墟","南风村背景故事","什么摧毁了南风村"}},{q="瓦斯坦·鹿盔是谁？",a="瓦斯坦·鹿盔是大德鲁伊范达尔·鹿盔挚爱的儿子。他领导了针对入侵虫族的南风村防御战，但他的部队伤亡殆尽，他本人也被其拉指挥官拉贾克斯将军俘虏。",al={"瓦斯坦·鹿盔南风村","范达尔·鹿盔之子","谁防守了南风村"}},{q="为什么这里有暗夜精灵的鬼魂？",a="守卫者们突如其来的残酷屠杀将他们的灵魂困在了废墟之中。阵亡的德鲁伊和哨兵的灵魂陷入了他们生命最后时刻那场恐怖战斗的永恒循环中，并在琥珀月之影的徘徊注视下不得解脱。",al={"南风村亡魂","为什么南风村有鬼魂","琥珀月之影"}},{q="虫子与摧毁村庄的原因有关吗？",a="是的。在废墟周围蜂拥而至的其拉虫群是其拉虫人虫族灾难的一部分，正是这股势力在几个世纪前入侵了希利苏斯并摧毁了这座前哨站。",al={"其拉虫群南风村","虫子和南风村有关系吗"}}},fp="17,249,22.540.0,18.438.0,35.214.0,26.242.0,36.239.0,51.183.0"}
P.entries["subzone:spirit-rise"] = {n="灵魂高地",s="灵魂高地是雷霆崖西北部的台地，是这座牛头人主城中进行精神和萨满修行的首要圣地。这里由追天者部族等精神向导管理，上方设有神圣的训练大厅，并向下延伸至洞穴般的预见之池。",h="灵魂高地是雷霆崖西北部的台地，是这座牛头人主城中进行精神和萨满修行的首要圣地。这里由追天者部族等精神向导管理，上方设有神圣的训练大厅，并向下延伸至洞穴般的预见之池。",kw={"灵魂大厅","莫高雷","预见之池","萨满","追天者","灵魂高地","雷霆崖"},ang={["class:Shaman"]="对于部落的萨满来说，灵魂高地是一个重要的聚集地，可以咨询训练师、进行元素仪式并与祖先之灵沟通。",["race:Tauren"]="这座高地体现了你们人民深厚的精神根源，在预见之池神秘的水域旁，让你从世俗的职责中获得慰藉。"},sec={{t="灵魂的圣所",b="灵魂高地高踞在俯瞰莫高雷平原的峭壁之上，致力于与元素和祖先之灵沟通。通过绳桥与中心台地相连，这里设有灵魂大厅和心灵治疗馆，年轻的和资深的萨满在此聚集，加深他们与大地、空气、火焰和水的联系。追天者部族在整个高地上保持着强大的影响力，指引寻求者遵循古老的传统。"},{t="洞穴与通道",b="在微风吹拂的小屋和露天图腾神龛之下，有一个深入台地本身的入口：热气腾腾的预见之池，这是一个神圣的地下洞穴，先知们在此凝视被灵魂触碰的水面。"}},faq={{q="灵魂高地以什么闻名？",a="灵魂高地是雷霆崖的精神中心，主要用于萨满修行、治疗，以及与自然之灵和祖先沟通。它也是通往预见之池的入口。",al={"灵魂高地是什么","灵魂高地的目的","为什么要访问灵魂高地"}},{q="哪个牛头人部族领导灵魂高地的活动？",a="追天者部族在此拥有显著的影响力，培养着定义了这座高地的精神传统、占卜仪式和萨满训练。",al={"谁管理灵魂高地","灵魂高地的部族","追天者部族"}},{q="我能在灵魂高地下方找到什么？",a="从高地向下走便可进入预见之池，这是一个潮湿的地下洞穴，充满了冒着热气的水，先知和精神修行者们在此冥想并寻求幻象。",al={"灵魂高地的洞穴","灵魂高地下方","预见之池入口"}}},fx={a67a2478={q="灵魂高地是什么地方？",a="灵魂高地是雷霆崖的一座高耸台地，位于中央崖顶的西北方。这里是城市的精神中心，主要用于萨满教研究、与灵魂沟通以及寻求祖先指引。灵魂高地以绳桥与城市其他部分相连，坐落着灵魂大厅，下方则是名为预见之池的地下洞穴。",al={"灵魂高地是什么地方","灵魂高地简介","雷霆崖灵魂高地"}},["6e710860"]={q="灵魂高地危险吗？",a="一点也不危险。灵魂高地是牛头人主权首都内的一处圣所。这里有萨满、灵疗者和来访的旅人，而非敌对野兽或入侵者。唯一真正的危险，是你在台地边缘或悬索桥附近失足时，可能会坠下悬崖。",al={"灵魂高地安全吗","灵魂高地的危险","灵魂高地的敌人"}}},fp="11,286,26.464.0,19.201.0,30.207.0,51.151.0,39.181.0"}
P.entries["subzone:spirit-rock"] = {n="灵魂石地",s="灵魂石地是位于杜隆塔尔试炼谷上方嶙峋峭壁上的一处神圣岩架。通过一条名为秘道的蜿蜒小径即可到达，它是一处隐秘的圣地，新兵们在此直接与大地的元素力量进行沟通。",h="灵魂石地是位于杜隆塔尔试炼谷上方嶙峋峭壁上的一处神圣岩架。通过一条名为秘道的蜿蜒小径即可到达，它是一处隐秘的圣地，新兵们在此直接与大地的元素力量进行沟通。",kw={"call of earth","杜隆塔尔","大地之灵","秘道","萨普塔","萨满","灵魂石地","试炼谷"},ang={["class:Shaman"]="灵魂石地对于年轻的兽人和巨魔萨满来说是一次至关重要的成年礼，他们踏上秘道去饮用大地萨普塔，并建立起他们与岩石和土地之灵的最初羁绊。"},sec={{t="元素圣所",b="它俯瞰着年轻的部落战士和斥候开始受训的红色峡谷，灵魂石地是一座沟通的祭坛。它与试炼谷的喧嚣隔绝，只能通过蜿蜒在岩石脊线上的秘道到达。有抱负的萨满祭司会前往这处荒凉的露头进行朝圣，饮下传统的萨普塔，穿透物质世界的面纱，倾听大地本身的轰鸣与低语。"}},faq={{q="灵魂石地的用途是什么？",a="灵魂石地是一处主要供部落萨满学徒使用的神圣场所。通过在这块岩石上饮用一种被称为大地萨普塔的特殊药剂，新手们可以获得与大地之灵直接沟通所需的灵视。",al={"灵魂石地用途","灵魂石地发生了什么","灵魂石地使用"}},{q="如何前往灵魂石地？",a="灵魂石地坐落在杜隆塔尔西南部试炼谷上方的悬崖高处。可以通过攀登秘道到达，这是一条狭窄且没有标记的小径，从峡谷底部蜿蜒延伸至崎岖的山丘中。",al={"如何到达灵魂石地","通往灵魂石地的道路","灵魂石地位置"}},{q="什么是萨普塔？",a="萨普塔是一种由萨满训练师调制的仪式性元素药剂。饮用它可以改变寻求者的感知，使他们能够察觉到普通感官无法看到的元素显现。",al={"大地萨普塔","什么是萨普塔","萨普塔饮料"}}},fx={["5b9df982"]={q="灵魂石地是什么地方？",a="灵魂石地是一处隐秘的圣地，坐落在俯瞰杜隆塔尔试炼谷的高耸岩壁上。沿着蜿蜒隐蔽的山路即可抵达，这里是有志成为萨满的人与世界之灵沟通的神圣聚集地。",al={"灵魂石地是什么地方","杜隆塔尔灵魂石地","灵魂石地简介"}},["383a79b2"]={q="灵魂石地危险吗？",a="灵魂石地本身是庄严的静思之地，并非怪物巢穴。不过，通往嶙峋山岩的道路紧邻杜隆塔尔的荒野，而毫无准备地直接与元素之灵沟通，也会带来种种考验。",al={"灵魂石地的危险","灵魂石地安全吗","灵魂石地的敌人"}},["57276d06"]={q="为什么叫灵魂石地？",a="这里是一处受祝圣的天然圣地，物质世界与元素之灵之间的帷幕在此十分稀薄，因此得名。萨满会在这里饮用特制的萨普塔，以感知并与大地之灵交谈。",al={"为什么叫灵魂石地","灵魂石地名称由来"}}},fp="11,255,27.445.0,29.236.0,29.217.0,16.204.0"}
P.entries["subzone:splinterspear-junction"] = {n="断矛路口",s="断矛路口是蜿蜒穿过悲伤沼泽腹地的主干道上一个战略性的分叉点。这里矗立着一座粗犷的兽人瞭望塔，部落哨兵会定期在此巡逻，它将通往北部避难地和南部前哨的路径分离开来。",h="断矛路口是蜿蜒穿过悲伤沼泽腹地的主干道上一个战略性的分叉点。这里矗立着一座粗犷的兽人瞭望塔，部落哨兵会定期在此巡逻，它将通往北部避难地和南部前哨的路径分离开来。",kw={"避难营","断矛路口","斯通纳德","悲伤沼泽","瞭望塔"},ang={["faction:Alliance"]="在路口附近行走时要小心；兽人瞭望塔有大量部落哨兵把守，他们渴望斩杀任何从夜色镇流落至此的入侵者。",["faction:Horde"]="路口的瞭望塔为往返于斯通纳德与沼泽北部目的地之间的旅客提供了重要的路径点和安全检查站。"},sec={{t="冲突的十字路口",b="断矛路口坐落在悲伤沼泽的中心附近，将旅客分流到两条道路：一条是通往失落者避难所——避难营和农田避难所的北部小径，另一条是直接经过斯通纳德要塞并通往诅咒之地的南部公路。一座古老的兽人瞭望塔俯瞰着这个分岔路口，由现役的部落军队驻守和巡逻。对于部落成员来说，这是在险恶沼泽中一个安全的地标；而对于联盟旅客而言，它是这条本就无情的道路上一个致命的伏击点。"}},faq={{q="断矛路口的道路通向何处？",a="这条路分为两条截然不同的路线。北方的岔路经过德莱尼人的避难所避难营，通向农田避难所；而南方的支路引导旅客向南前往斯通纳德，并继续进入诅咒之地的干旱荒野。",al={"道路去向","断矛路口路径","断矛路口往哪走"}},{q="断矛路口对联盟旅客安全吗？",a="不安全。该路口由部落控制，他们在此处维持着一座防御坚固的瞭望塔，并在交叉路口周围进行定期巡逻。这些守卫对联盟公开敌对，一旦发现路过的冒险者就会发起攻击。",al={"断矛路口对联盟是否安全","守卫是否敌对","断矛路口pvp"}}},fp="22,259,24.575.0,50.256.0,54.222.0"}
P.entries["subzone:splintertree-post"] = {n="碎木岗哨",s="碎木岗哨是灰谷东部主要的部落要塞，位于冥火岭的西北方。它由格罗玛什·地狱咆哮和战歌氏族在第三次战争期间建立，是抵御暗夜精灵的坚固堡垒，也是领土扩张的据点。",h="碎木岗哨是灰谷东部主要的部落要塞，位于冥火岭的西北方。它由格罗玛什·地狱咆哮和战歌氏族在第三次战争期间建立，是抵御暗夜精灵的坚固堡垒，也是领土扩张的据点。",kw={"灰谷","阿斯特兰纳","冥火岭","格罗玛什·地狱咆哮","碎木岗哨","vhulgra","战歌氏族"},ang={["faction:Horde"]="碎木岗哨是冒险者穿越灰谷时的重要中央基地，提供维修、休憩之所，以及横跨卡利姆多的关键飞行航线。",["race:NightElf"]="对暗夜精灵而言，这座要塞是灰谷上的一道苦涩伤疤，它由那位击倒了塞纳留斯的督军所建，并由那些屠戮他们古老树木的入侵者所延续。"},sec={{t="边境据点",b="碎木岗哨直接从古老的林地中开辟而成，是部落在灰谷东部的主要军事和后勤枢纽。最初由格罗玛什·地狱咆哮和战歌氏族在第三次战争期间兽人首次进入森林时建立，如今它仍是一个重兵把守的飞地，主要由兽人和牛头人侦察兵及战士进行防御。这里设有飞行管理员、旅店，并拥有通往奥格瑞玛的稳定补给线，是部落在树冠之下维持抗争的基石。"},{t="持续的报复威胁",b="碎木岗哨时刻处于戒备状态。暗夜精灵既没有忘记也没有原谅格罗玛什在战争期间的暴行，更无法容忍兽人持续进行的伐木活动以及对阿斯特兰纳的突袭。因此，这个定居点时刻面临着藏身于周围林木中的哨兵所发动的报复性打击和游击战，这无时无刻不在考验着驻军守卫。"}},faq={{q="谁建立了碎木岗哨？",a="它由格罗玛什·地狱咆哮和战歌氏族在第三次战争期间建立，当时兽人首次进入灰谷以采集木材并建立立足点。",al={"谁建造了碎木岗哨","碎木岗哨建立者","格罗玛什 碎木岗哨"}},{q="为什么暗夜精灵频繁攻击这个基地？",a="暗夜精灵将碎木岗哨视为对祖先领地的非法亵渎与入侵。格罗玛什在第三次战争中的残暴战役留下的敌意至今未散，而部落持续的伐木活动以及针对附近精灵据点阿斯特兰纳的冲突，更加剧了这种敌意。",al={"为什么精灵要攻击","碎木岗哨哨兵袭击","暗夜精灵突袭碎木岗哨"}},{q="这里提供哪些设施和旅行选择？",a="碎木岗哨提供旅店、马厩管理员、邮箱、护甲维修服务，以及通往奥格瑞玛、十字路口和卡利姆多各地其他部落前哨站的双足飞龙飞行管理员。",al={"碎木岗哨飞行路线","碎木岗哨服务","碎木岗哨旅店"}},{q="碎木岗哨目前的驻军由谁组成？",a="该定居点主要由兽人和牛头人居住，他们作为经验丰富的侦察兵、哨兵和前线军官，负责驻守边境。",al={"碎木岗哨守卫","谁住在碎木岗哨","碎木岗哨种族"}}},fx={["1c750cca"]={q="碎木岗哨是什么地方？",a="碎木岗哨是部落在灰谷东部的一处坚固据点，坐落在冥火岭西北方。它主要作为军事基地和集结地，巩固部落沿森林道路的势力。在木制栅墙内，斥候、战士和补给人员聚集于此，巩固部落的领土据点；在这片充满敌意、争夺激烈的林地中，它也为疲惫的旅人提供温暖、修理服务和双足飞龙运输，是一处重要的避难所。",al={"碎木岗哨是什么地方","碎木岗哨的用途","碎木岗哨营地"}},["1352f983"]={q="碎木岗哨有何历史？",a="第三次战争期间，格罗玛什·地狱咆哮和战歌氏族为采伐大量木材，最初在荒野中开辟了碎木岗哨，兽人也由此首次踏入灰谷。战争结束后的数年间，这座营地从简陋的战地营盘发展成部落的永久前哨，并持续与暗夜精灵守卫发生激烈冲突；他们对兽人入侵神圣森林深感愤怒。",al={"碎木岗哨历史","碎木岗哨过往","碎木岗哨发生过什么"}},e71555e8={q="碎木岗哨危险吗？",a="对部落勇士而言，坚固的木制路障后方是一处安全的避难所。然而，周围的森林危机四伏。暗夜精灵哨兵为报复附近的冲突，频繁对前哨发动致命突袭；而徘徊在冥火岭附近的堕落野兽和恶魔残余，也让木栅墙外始终危机四伏。",al={"碎木岗哨安全吗","碎木岗哨的危险","碎木岗哨面临的威胁"}}},fp="17,296,21.505.0,34.402.0,30.168.0,51.264.0,53.198.0,52.156.0"}
P.entries["subzone:splithoof-crag"] = {n="裂蹄峭壁",s="裂蹄峭壁是加拉克半人马的一处堡垒式定居点，坐落在千针石林北侧的悬崖边。它是该部族除了高耸的台地之外的主要据点之一，守卫着通往裂蹄堡的入口。穿行于峡谷底部的旅行者必须应对在峭壁附近游荡的、极具攻击性的加拉克巡逻队。",h="裂蹄峭壁是加拉克半人马的一处堡垒式定居点，坐落在千针石林北侧的悬崖边。它是该部族除了高耸的台地之外的主要据点之一，守卫着通往裂蹄堡的入口。穿行于峡谷底部的旅行者必须应对在峭壁附近游荡的、极具攻击性的加拉克巡逻队。",kw={"半人马","裂开的蹄子","黑云峰","加拉克","裂蹄峭壁","裂蹄堡","千针石林"},ang={["faction:Horde"]="控制峭壁下方的通道对于确保南贫瘠之地、乱风岗和闪光平原之间的通行安全至关重要。",["race:Tauren"]="牛头人与半人马之间长期的敌对状态，使得裂蹄峭壁成为部落侦察兵监控千针石林各地敌对活动时的重点关注对象。"},sec={{t="加拉克要塞",b="裂蹄峭壁依傍着千针石林北侧的险峻岩壁而建，位于巍峨的黑云峰正东方。这是一处成熟的加拉克半人马飞地，有着粗陋的帐篷营地和穿过峭壁的土路。在村庄中心，背靠悬崖的地方坐落着裂蹄堡，这是一处地下洞穴，里面供奉着裂蹄之蹄——一件由圣火盆守护的古老半人马圣物。"},{t="守卫洞穴",b="加拉克部族在峡谷的这一隅进行着激烈的争夺，与任何经过此地、在峭壁下徘徊的旅行者、部落远征队或牛头人侦察小队发生冲突。虽然恐怖图腾部族占据着附近高耸的山峰，但半人马牢牢控制着这处峡谷沟壑以及深埋于岩石之下的洞穴。"}},faq={{q="谁住在裂蹄峭壁？",a="这处定居点属于加拉克半人马部族，他们是与敌对的恐怖图腾牛头人并列，在千针石林中居住的主要氏族之一。",al={"裂蹄峭壁里有什么人","裂蹄峭壁怪物","裂蹄峭壁的半人马"}},{q="裂蹄峭壁位于哪里？",a="它位于千针石林的北侧峡谷壁上，坐落在黑云峰的正东方。",al={"裂蹄峭壁在哪里","裂蹄峭壁位置"}},{q="裂蹄堡里有什么？",a="裂蹄堡是该村庄的核心洞穴。在深处的密室中，加拉克人守护着“裂蹄之蹄”，这是一件被古老火盆中燃烧的圣火所保护的远古部族神器。",al={"什么是裂蹄堡","裂蹄峭壁的洞穴"}},{q="这里的半人马与附近的恐怖图腾有盟约吗？",a="没有。没有任何迹象表明他们之间存在结盟：加拉克人固守着他们的峡谷村庄和洞穴，而恐怖图腾则占据着黑云峰的高地。",al={"恐怖图腾与加拉克","半人马与牛头人的关系"}}},fx={fc440e32={q="裂蹄峭壁是什么地方？",a="裂蹄峭壁是千针石林北部岩壁上的一处坚固聚落，位于黑云峰以东不远处。这里是当地加拉克半人马的重要据点，峡谷底部散布着成群的营地，内部还有一处名为裂蹄堡的洞穴。",al={"这是什么地方","裂蹄峭壁简介","裂蹄峭壁介绍"}},["76cca678"]={q="裂蹄峭壁危险吗？",a="对外来者来说，这里极其危险。加拉克半人马凶悍好斗，领地意识极强，会一见入侵者便发动攻击。此外，聚落内部的圣所裂蹄堡也防守严密，用以保护他们的圣物。",al={"这里安全吗","裂蹄峭壁的危险","裂蹄峭壁的威胁"}}},fp="14,336,18.447.0,21.318.0,28.145.0,32.105.0,30.196.0,54.166.0"}
P.entries["subzone:splithoof-hold"] = {n="裂蹄堡",s="裂蹄堡是千针石林中一座深藏于裂蹄峭壁岩石内部的洞穴要塞。该洞穴由加拉克半人马部族占据，作为一座防御森严的巢穴，并供奉着古老火盆，其中燃烧着永不熄灭的神圣火焰。",h="裂蹄堡是千针石林中一座深藏于裂蹄峭壁岩石内部的洞穴要塞。该洞穴由加拉克半人马部族占据，作为一座防御森严的巢穴，并供奉着古老火盆，其中燃烧着永不熄灭的神圣火焰。",kw={"古老火盆","加拉克半人马","神圣之火","裂蹄峭壁","裂蹄堡","千针石林"},ang={["class:Shaman"]="在黑暗的石洞深处存在着一团永恒之火，这吸引了所有感应元素之火原始奥秘的灵性修行者的注意。",["race:Tauren"]="加拉克半人马依然是牛头人的血仇死敌，这使得他们在千针石林中保持的任何据点，都对乱风岗的安宁构成了直接威胁。"},sec={{t="半人马堡垒",b="裂蹄堡隐藏在裂蹄峭壁之内，是加拉克半人马的防御据点。与狂风呼啸的峡谷底部不同，这座封闭的洞穴为他们提供了遮蔽、易守难攻的关隘，以及躲避敌对部族和穿行在千针石林的旅人的安全避难所。"},{t="神圣之火",b="要塞幽暗的深处安放着一座古老火盆，其中孕育着神圣之火。这团神秘的火焰经久不息，既是半人马力量与仪式崇拜的焦点，也是峡谷中那些追寻灵性的流浪者们深感好奇的对象。"}},faq={{q="裂蹄堡在哪里？",a="裂蹄堡坐落在千针石林北侧崖壁上的裂蹄峭壁之中。入口位于半人马主要定居点内的一个洞穴开口处。",al={"裂蹄堡位置","裂蹄堡在哪里","如何找到裂蹄堡"}},{q="谁控制着裂蹄堡？",a="该洞穴由加拉克半人马部族所占据，他们积极防御着洞穴，抵御外来者、野兽入侵以及附近乱风岗的牛头人。",al={"谁住在裂蹄堡","裂蹄堡怪物","谁拥有裂蹄堡"}},{q="要塞里有什么？",a="除了充满敌意的加拉克半人马守卫，洞穴内还供奉着古老火盆，这是一件让神秘的神圣之火在岩石深处永恒燃烧的神器。",al={"裂蹄堡里有什么","古老火盆位置","裂蹄堡神圣之火"}}},fx={["9edfe937"]={q="裂蹄堡是什么地方？",a="裂蹄堡是千针石林裂蹄峭壁岩层中的一处洞穴据点。凶悍的加拉克半人马部族占据了天然洞穴，并将其改造成峡谷中的坚固基地，将圣物和氏族的炉火安置在其中。",al={"裂蹄堡是什么地方","裂蹄堡背景","裂蹄堡简介"}},["8bfe11a3"]={q="裂蹄堡危险吗？",a="裂蹄堡对外来者来说极其危险。这里是好战的加拉克半人马的重要据点，他们严密守卫着自己的洞穴、战团，以及深藏其中的永恒圣焰，不容任何人擅闯。",al={"裂蹄堡危险吗","裂蹄堡的危险","裂蹄堡的威胁"}}},fp="14,255,17.285.0,16.278.0,32.203.0,28.156.0,24.174.0"}
P.entries["subzone:stagalbog"] = {n="雄鹿沼泽",s="雄鹿沼泽是一片茂密、积水的沼泽地，横跨悲伤沼泽的南部区域。它毗邻泪水之池下方的南部山脉，是一片未开化的荒野。",h="雄鹿沼泽是一片茂密、积水的沼泽地，横跨悲伤沼泽的南部区域。它毗邻泪水之池下方的南部山脉，是一片未开化的荒野。",kw={"沼泽","泪水之池","雄鹿沼泽","雄鹿沼泽洞穴","悲伤沼泽"},ang={["class:Hunter"]="沼泽水域和山崖之间安静的区域使雄鹿沼泽成为了本地沼泽野兽绝佳的潜行狩猎场。",["profession:Herbalism"]="雄鹿沼泽潮湿且缺乏阳光的根系为那些远离人迹的沼泽植物提供了绝佳的生长条件。"},sec={{t="南部泥沼",b="雄鹿沼泽延伸在南部山崖的阴影之下，具有悲伤沼泽的典型特征：死水、低垂的芦苇和纠结的植被。它位于阿塔哈卡神庙沉没遗迹的正南方，夹在受污染的湖泊和该地区的岩石边界之间。除了粗野的野生动物外，这里没有文明的立足之地。"},{t="神庙之影",b="因为与泪水之池接壤，雄鹿沼泽经常受到从沉没的神庙中渗透出来的阴影或腐化的影响。"}},faq={{q="雄鹿沼泽位于哪里？",a="雄鹿沼泽位于悲伤沼泽的南部，直接坐落在泪水之池的南面，沿着南部山脉的基部延伸。",al={"雄鹿沼泽位置","雄鹿沼泽在哪里","如何找到雄鹿沼泽"}},{q="在沼泽中漫游着什么威胁？",a="沼泽中栖息着当地的沼泽野兽和掠食性生物。",al={"雄鹿沼泽怪物","雄鹿沼泽里的怪物"}}},fp="9,206,17.378.0,20.131.0,31.174.0,44.72.0"}
P.entries["subzone:stagalbog-cave"] = {n="雄鹿沼泽洞穴",s="雄鹿沼泽洞穴是一个潮湿的地下洞穴，坐落于悲伤沼泽东部的雄鹿沼泽内。它不仅是沼泽鱼人的据点，也是他们邪恶的精神领袖——沼泽语者的巢穴。",h="雄鹿沼泽洞穴是一个潮湿的地下洞穴，坐落于悲伤沼泽东部的雄鹿沼泽内。它不仅是沼泽鱼人的据点，也是他们邪恶的精神领袖——沼泽语者的巢穴。",kw={"沼泽鱼人","鱼人巢穴","雄鹿沼泽","雄鹿沼泽洞穴","悲伤沼泽","沼泽语者"},sec={{t="沼泽部族的巢穴",b="雄鹿沼泽洞穴隐藏在悲伤沼泽阴暗的东部湿地中，为当地的鱼人提供了躲避沼泽连绵阴雨的庇护所。这些被称为“沼泽部族”的两栖生物，与他们的首席秘术师——沼泽语者一道，凶猛地守卫着蜿蜒的洞穴深处。冒险者在靠近雄鹿沼泽那片沉陷的泥沼时，经常能听到鱼人咕噜咕噜的叫声在长满青苔的河岸间回荡，以此警告外来者远离他们的筑巢地。"}},faq={{q="雄鹿沼泽洞穴是什么？",a="雄鹿沼泽洞穴是一个位于悲伤沼泽东部雄鹿沼泽内的天然洞穴。这里主要被一群凶残的沼泽鱼人占据。",al={"雄鹿沼泽洞穴在哪里","雄鹿沼泽洞穴里有什么"}},{q="谁统治着这个洞穴？",a="这个洞穴由沼泽部族及其领袖沼泽语者所统治，沼泽语者是一位极具影响力的鱼人秘术师，负责监督该部族在潮湿洞穴内部的仪式与防御。",al={"雄鹿沼泽首领","沼泽语者","谁在这里领导鱼人"}},{q="附近有友好的定居点吗？",a="洞穴周围全是狂野而充满敌意的沼泽地。距离最近的友好定居点（至少对部落而言）是位于西部的斯通纳德前哨站。",al={"最近的城镇","雄鹿沼泽附近的商人"}}},fp="14,228,22.480.0,23.177.0,19.179.0,38.147.0"}
P.entries["subzone:staghelm-point"] = {n="鹿盔岗哨",s="鹿盔岗哨是一座古老的暗夜精灵瞭望塔，坐落在希利苏斯东北部的一座崎岖山峰之巅。这座塔俯瞰着不断逼近的沙丘和附近的暮光小径洞穴，作为一道守望防线，警惕着徘徊在沙漠中的古老威胁。",h="鹿盔岗哨是一座古老的暗夜精灵瞭望塔，坐落在希利苏斯东北部的一座崎岖山峰之巅。这座塔俯瞰着不断逼近的沙丘和附近的暮光小径洞穴，作为一道守望防线，警惕着徘徊在沙漠中的古老威胁。",kw={"青铜龙","范达尔·鹿盔","拉洛珊","希利苏斯","鹿盔岗哨","暮光小径","瞭望塔"},ang={["class:Druid"]="这座塔冠以鹿盔之名，提供了一个沉思的视角，俯瞰着这片破坏自然平衡、荒凉腐化的荒野。",["race:NightElf"]="鹿盔岗哨唤起了关于流沙之战的庄严历史，作为卡多雷为阻挡希利苏斯地下的恐怖而付出沉重牺牲的鲜明提醒，屹立不倒。"},sec={{t="沙海之上的静默守望",b="鹿盔岗哨高耸于希利苏斯东北部的干旱平原之上，塔顶是一座孤零零的暗夜精灵塔楼。这个哨所像是一个孤独的卫兵，守护着这片荒原，并监视着潜伏在附近洞穴（如暮光小径）中的邪教徒。永恒守望者拉洛珊镇守于此，头顶还有一只青铜龙盘旋巡逻。这座塔承载着鹿盔家族那引以为傲却又充满悲剧色彩的名字——这是为了纪念卡多雷在古代流沙之战中所做出的巨大牺牲。"}},faq={{q="谁居住在鹿盔岗哨？",a="这座孤塔由永恒守望者拉洛珊守护，而一只来自诺兹多姆的子嗣的雄伟青铜龙则在塔顶上空进行永恒的巡逻。",al={"谁在鹿盔岗哨","鹿盔岗哨npc","拉洛珊"}},{q="附近有什么威胁？",a="沿着蜿蜒小路从山峰而下，就是暮光小径，那里的洞穴和周围营地里爬满了暮光之锤教派的狂热信徒。",al={"鹿盔岗哨危险","附近的敌人","暮光小径"}}},fp="14,257,30.531.0,28.165.0,24.154.0"}
P.entries["subzone:stagnant-oasis"] = {n="死水绿洲",s="死水绿洲是坐落在贫瘠之地干旱中心的一片珍贵水域，位于黄金之路和商旅海岸之间。这里环绕着茂密的棕榈树，并有科卡尔半人马在此争夺，其浑浊的水域和周边的海岸支撑着独特的当地野生生物，包括鳄鱼和游荡的科多兽。",h="死水绿洲是坐落在贫瘠之地干旱中心的一片珍贵水域，位于黄金之路和商旅海岸之间。这里环绕着茂密的棕榈树，并有科卡尔半人马在此争夺，其浑浊的水域和周边的海岸支撑着独特的当地野生生物，包括鳄鱼和游荡的科多兽。",kw={"贫瘠之地","半人马","变异鱼","黄金之路","科多兽","科卡尔","鳄鱼","死水绿洲"},ang={["faction:Horde"]="对于往返于十字路口和陶拉祖之间的部落信使和侦察兵来说，绿洲上的半人马营地对黄金之路的补给运输构成了持续的威胁。",["profession:Cooking"]="死水绿洲的水域盛产稀有的变异鱼，这是烹制美味风蛇的重要配料。"},sec={{t="干旱中的浑浊避风港",b="死水绿洲隐藏在黄金之路以东、商旅海岸的内陆地带，在贫瘠之地尘土飞扬的灌木丛中提供了一片宝贵的绿色。和邻近的水域一样，这片水塘支撑着茂密的植被和好斗的鳄鱼，而虚弱的贫瘠之地科多兽经常远离巨人旷野庞大的兽群，徘徊到这里。然而，旅行者必须小心谨慎：科卡尔半人马在岸边设有营地，他们凶猛地守卫着水源，对抗任何闯入其领地的外来者。"},{t="奇异的水域",b="尽管外观上看来死气沉沉，但这片水塘中却充满了不同寻常的水生生物，包括像变异鱼这样奇异的变异物种。学者和萨满祭司一直密切关注着贫瘠之地的绿洲，研究那些影响当地泉源以及饮用泉水的野生生物的奇特力量。"}},faq={{q="死水绿洲位于哪里？",a="死水绿洲位于贫瘠之地的中南部地带，处于黄金之路以东，商旅海岸沿线的悬崖以西。",al={"死水绿洲位置","死水绿洲在哪里","如何找到死水绿洲"}},{q="谁控制着死水绿洲？",a="游牧的科卡尔半人马在水塘周边建立了营地。除了半人马，还有诸如绿洲鳄鱼和落单、游荡的科多兽等危险野兽在周围的绿地中徘徊。",al={"谁住在死水绿洲","死水绿洲半人马","死水绿洲的敌人"}},{q="为什么这里的科多兽更容易狩猎？",a="与在南面巨人旷野发现的庞大、协作的兽群不同，死水绿洲附近的科多兽通常是落单的，而且往往身体虚弱或迷失了方向，这使它们成了猎人和旅行者眼中更容易捕捉的猎物。",al={"迷失的贫瘠之地科多兽","死水绿洲科多兽","狩猎贫瘠之地科多兽"}},{q="在这片水塘里能钓到什么样的鱼？",a="垂钓者可以从这片浑浊的水塘中钓到变异鱼，这是一种独特的渔获，可以烹制成在整个卡利姆多都备受推崇的美味佳肴。",al={"死水绿洲垂钓","死水绿洲变异鱼","在死水绿洲钓鱼"}},{q="萨尔在长征期间曾造访过这座绿洲吗？",a="没有记录能证实这一点。死水绿洲可能是萨尔和新抵达的部落在与凯恩·血蹄一起穿越贫瘠之地时所占领的三处水源之一。",al={"萨尔死水绿洲","长征绿洲","魔兽争霸3绿洲"}}},fx={["9f5a622c"]={q="死水绿洲是什么地方？",a="死水绿洲是贫瘠之地干旱广袤的土地上点缀着的一处葱郁水源，位于黄金之路与商旅海岸之间。这里有淡水池、参天棕榈和本土植被，是周边草原野生动物的重要避难所，不过其中也潜藏着危险。",al={"死水绿洲是什么","死水绿洲信息","关于死水绿洲"}},f4d964bf={q="死水绿洲危险吗？",a="危险，旅人必须小心行事。凶悍的科卡尔半人马在绿洲周边扎营，暴力地将珍贵的水源据为己有。除了敌对的掠袭者，凶猛的绿洲钳嘴龟也在泥泞的岸边徘徊，对那些想躲避烈日、毫无防备地前来歇脚的旅人构成致命威胁。",al={"死水绿洲安全吗","死水绿洲危险","死水绿洲的威胁"}}},fp="14,329,28.530.0,14.291.0,36.151.0,32.208.0,38.221.0,44.135.0,50.197.0"}
P.entries["subzone:starbreeze-village"] = {n="星风村",s="星风村是位于泰达希尔，多兰纳尔以东的一处被遗弃的暗夜精灵定居点。这里曾经是一片宁静的林地村落，但最近却沦陷在陷入疯狂的Gnarlpine部族熊怪手中。这座废弃的定居点现在已成为正在渗透进世界之树根部的腐蚀力量的鲜明象征。",h="星风村是位于泰达希尔，多兰纳尔以东的一处被遗弃的暗夜精灵定居点。这里曾经是一片宁静的林地村落，但最近却沦陷在陷入疯狂的Gnarlpine部族熊怪手中。这座废弃的定居点现在已成为正在渗透进世界之树根部的腐蚀力量的鲜明象征。",kw={"多兰纳尔","ferocitas","熊怪","gnarlpine","星风村","泰达希尔","uruson","村庄"},ang={["class:Druid"]="Gnarlpine熊怪所遭受的疯狂以及星风村的遭践踏，直接挑战了塞纳里奥议会恢复泰达希尔野生动植物平衡的职责。",["race:NightElf"]="看到一个距离多兰纳尔如此之近的精灵定居点沦为废墟，痛苦地提醒着人们泰达希尔岌岌可危的状态以及正在啃噬世界之树的腐蚀力量。"},sec={{t="沦陷的村落",b="星风村位于幽影谷东南方，距离多兰纳尔不远，这里曾是居住在泰达希尔枝叶下的暗夜精灵家庭的安宁家园。如今，村庄已是一片废墟，木质建筑被极具攻击性的Gnarlpine熊怪占领。这些野兽般的生物受到折磨世界之树枝叶的邪恶腐蚀力量的影响而变得狂暴，它们驱逐了精灵居民，现在正凶猛地守卫着这片废墟。"},{t="Ferocitas的威胁",b="Gnarlpine部族在村中的存在不仅仅是一次普通的领地掠夺。徘徊在定居点边缘的是梦境吞噬者Ferocitas，一个神秘的、堕落的实体，它的存在表明某种黑暗而邪恶的魔法正在积极地驱使熊怪走向疯狂。连同像Uruson这样在道路上潜行的庞大野兽，这些入侵者使星风村成为了泰达希尔东部旅行者的一个重大威胁。"}},faq={{q="星风村为什么会被废弃？",a="当Gnarlpine熊怪成为泰达希尔内部蔓延的腐蚀力量的牺牲品时，村庄便沦陷了。陷入疯狂和暴力的熊怪袭击了这里的暗夜精灵居民，迫使他们逃离并放弃了家园。",al={"星风村发生了什么","为什么星风村是一片废墟","星风村是空的吗"}},{q="现在谁居住在星风村？",a="充满敌意的Gnarlpine熊怪现在占据了村庄。其中比较突出的人物包括游荡的巡逻者Uruson以及被称为梦境吞噬者Ferocitas的堕落者。",al={"谁在星风村","星风村的怪物","谁占领了星风村"}},{q="星风村在哪里？",a="星风村位于泰达希尔东部，在幽影谷的东南方，多兰纳尔的东方。",al={"星风村在哪里","星风村地图位置","如何找到星风村"}},{q="梦境吞噬者Ferocitas是谁？",a="Ferocitas是一个危险的堕落生物，出现在星风村边缘，与驱使当地Gnarlpine部族陷入疯狂的黑暗力量有关。",al={"ferocitas背景故事","ferocitas是谁","ferocitas 星风村"}}},fx={["3682bebf"]={q="星风村是什么地方？",a="星风村是泰达希尔枝叶间的一处暗夜精灵旧居，位于多兰纳尔以东、幽影谷东南方。这里曾是由一座座精灵小屋组成的宁静聚落，如今已沦为废墟，成为腐化正在世界之树蔓延的可怕见证。",al={"星风村是什么","星风村概况","星风村背景"}},["71f9207c"]={q="星风村发生了什么？",a="不久以前，星风村还是一处宁静的暗夜精灵社区。然而，当地的瘤背熊怪部族逐渐受到腐化侵蚀，变得野蛮而狂暴。卡多雷居民猝不及防，遭到袭击后被驱逐或屠杀，熊怪则完全控制了这处聚落。",al={"星风村历史","星风村发生了什么","星风村如何沦陷"}},["678e5f4f"]={q="星风村危险吗？",a="危险，毫无准备地进入这里十分危险。废墟里挤满了充满敌意、已遭腐化的瘤背熊怪，它们一看到外来者就会发动攻击。体型魁梧的熊怪乌鲁森在村中巡逻，而瘤背熊怪首领噬梦者菲罗克提斯则潜伏在聚落外围。",al={"星风村安全吗","星风村危险","星风村的危险"}}},fp="18,322,15.444.0,23.426.1,36.225.0,36.174.0,36.104.0,33.169.0"}
P.entries["subzone:starfall-village"] = {n="坠星村",s="坠星村是一处坐落在冬泉谷雪路旁的宁静暗夜精灵避难所。作为这片冰封山谷中唯一的联盟前哨站，它为在严寒中跋涉的旅行者提供了庇护与补给。它也时刻守护着附近的一处兽穴。",h="坠星村是一处坐落在冬泉谷雪路旁的宁静暗夜精灵避难所。作为这片冰封山谷中唯一的联盟前哨站，它为在严寒中跋涉的旅行者提供了庇护与补给。它也时刻守护着附近的一处兽穴。",kw={"联盟","暗夜精灵","坠星","坠星村","冬泉谷"},ang={["faction:Alliance"]="作为冬泉谷内唯一的联盟定居点，坠星村在这一荒凉险峻的高地中提供了必要的休憩、贸易物资和指路服务。",["race:NightElf"]="对于暗夜精灵而言，坠星村是一处重要的北方前哨站，矗立在一处安静、空置的兽穴旁。"},sec={{t="冰雪中的联盟避难所",b="坠星村位于地精贸易站永望镇的西北方、霜刀石的南面，是冬泉谷中联盟文明的唯一堡垒。该定居点由传统的暗夜精灵木屋组成，为过路人提供了一个休憩之所，在恶劣的山区环境中提供关键补给和温暖的炉火。尽管外观平静，但该村庄始终保持警惕，其位置毗邻着一处安静且无人居住的兽穴。"}},faq={{q="坠星村是什么地方？",a="坠星村是冬泉谷内的一处暗夜精灵飞地。它作为联盟在山谷中的主要避难所和补给营地，为前往霜刀石或调查附近兽穴的侦察兵提供食宿、贸易和指引。",al={"坠星","坠星镇","这里是什么地方"}},{q="部落玩家可以使用坠星村的设施吗？",a="不能。坠星村严格效忠于暗夜精灵和联盟。误闯此地的部落旅行者将会遭到当地守卫的敌对攻击。",al={"坠星村对部落友好吗","部落可以使用坠星村吗","坠星村部落"}},{q="村庄旁边的兽穴是什么？",a="村庄正后方的洞穴是一处空置的兽穴。此类圣所通常供德鲁伊在精神漫游翡翠梦境时栖身，但目前并没有德鲁伊在此沉睡。",al={"坠星兽穴","坠星旁的洞穴"}},{q="坠星村位于何处？",a="村庄坐落在穿越冬泉谷的主干雪道旁，位于地精定居点永望镇的西北方，霜刀石的南面。",al={"坠星位置","如何前往坠星","坠星在哪里"}}},fp="16,277,30.476.0,25.269.0,56.168.0,43.185.0,34.157.0"}
P.entries["subzone:steamwheedle-port"] = {n="热砂港",s="热砂港是位于塔纳利斯东海岸的一个繁忙的沿海前哨站，直接与加基森相连。它由中立的热砂港运作，是跨越南海的重要海上枢纽，同时时刻防范着不断侵扰的南海海盗。",h="热砂港是位于塔纳利斯东海岸的一个繁忙的沿海前哨站，直接与加基森相连。它由中立的热砂港运作，是跨越南海的重要海上枢纽，同时时刻防范着不断侵扰的南海海盗。",kw={"加基森港口","落帆海湾","南海海盗","热砂港","塔纳利斯码头","叶基亚"},ang={["class:Rogue"]="地精商人和附近的南海海盗之间不断的摩擦，为扒手、侦察兵和回收契约创造了有利可图的机会。",["profession:Engineering"]="该港口是一个宝贵的仓库，存放着从南海各地进口的零件和补给品，使其成为了修补匠们打听八卦和获取蓝图的天然中心。"},sec={{t="流沙之上的门户",b="热砂港坐落在南海沿岸的沙丘旁，为内陆沙漠城市加基森提供了通往海上贸易的直接生命线。这座定居点由热砂港管理，码头工人、商人和不畏艰险的海上船长往来其中，热闹非凡。补给船定期往返于此地和遥远的地精贸易站之间，将贵重的机械零件、奢侈品和原材料运往南卡利姆多。"},{t="海盗与古怪的学者",b="港口的生活绝非平静。沿着海岸向南走便是落帆海湾，那里盘踞着猖獗的南海自由海盗，他们经常洗劫地精货船、窃取货物并争夺海岸线的控制权。除了讨价还价的码头工人和试图追回失窃货物的多疑商人，港口还接待着一些不寻常的游客，比如神秘的巨魔叶基亚，他正在远离窥视的目光，研究着世界上古老而又不祥的灵魂。"}},faq={{q="谁控制着热砂港？",a="该定居点由热砂港建造并管理，这是中立地精的主要贸易集团。只要你与加基森和该财团保持良好的声望，联盟和部落的旅行者都会受到自由欢迎。",al={"谁经营热砂港","热砂港阵营","热砂港是否友好"}},{q="从这个港口出发的船只前往哪里？",a="该港口是热砂港跨越南海的海上联络点，将其与遥远的地精贸易中心相连，一艘客船会从这里的码头出发，横渡大海前往河林的爆破引线港。",al={"热砂港的船去哪","热砂港渡船"}},{q="为什么附近有这么多海盗？",a="南海自由海盗在南面的落帆海湾建立了基地。他们经常劫持进港货物、抢劫码头补给并袭击海岸线上的掉队者，这使他们成为当地地精贸易的主要威胁。",al={"落帆海湾海盗","塔纳利斯南海海盗"}},{q="叶基亚是谁？",a="叶基亚是一位在港口歇息的古怪巨魔学者。他招募勇敢的冒险者前往远方，捕捉诸如来自菲拉斯的尖啸者之类的灵魂精华，以研究被遗忘的原始仪式。",al={"叶基亚的目的","热砂港的巨魔"}}},fp="17,274,31.453.0,28.464.0,31.238.0,41.210.0,37.237.0,17.212.0"}
P.entries["subzone:steelgrill-s-depot"] = {n="钢架补给站",s="钢架补给站是一座繁忙的工程车间与维修站，坐落于丹莫罗卡拉诺斯的正东方。在贝尔丁·钢架及其工匠团队的监管下，它成为了车辆维护、修理补给运输和回收工作的最前线枢纽。",h="钢架补给站是一座繁忙的工程车间与维修站，坐落于丹莫罗卡拉诺斯的正东方。在贝尔丁·钢架及其工匠团队的监管下，它成为了车辆维护、修理补给运输和回收工作的最前线枢纽。",kw={"贝尔丁·钢架","丹莫罗","工程学","卡拉诺斯","钢架","钢架补给站","车间"},ang={["profession:Engineering"]="补给站是一个露天实验室，周围环绕着蒸汽机械和修理用品，这使得它成为了途经丹莫罗的有志工程师们天然的休憩站点。",["race:Gnome"]="流亡的侏儒修理工与他们的矮人东道主紧密合作，经常使用补给站的熔炉和备用零件来维持他们回收的装置正常运转。"},sec={{t="蒸汽与钢铁的堡垒",b="钢架补给站坐落在卡拉诺斯东侧雪路旁，这里终日回荡着金属碰撞的叮当声、蒸汽喷口的嘶嘶声以及实验性引擎的轰鸣声。矮人矿工与古怪的侏儒工程师聚集在此，周围是重型机械、机械步行装置以及从附近矿场运出的成堆矿石。面对丹莫罗持续不断的穴居人骚乱和机械补给短缺，贝尔丁·钢架和他的团队维持着联盟机械的正常运转，成为旅行者在严寒中寻求备件或技术指导不可或缺的落脚点。"}},faq={{q="钢架补给站是什么地方？",a="钢架补给站是位于丹莫罗的一座工程车间和前哨站，就在卡拉诺斯以东的道路旁。它主要服务于矿工、修理工以及负责维护重型机械的现场技术人员。",al={"钢架补给站","这是什么地方"}},{q="谁在管理这个补给站？",a="该补给站由钢架家族管理，主要是贝尔丁·钢架，并与负责维护周边机械和监督采矿作业的矮人及侏儒工匠们共同协作。",al={"谁领导钢架补给站","谁运营钢架补给站","贝尔丁·钢架"}},{q="这里提供什么服务？",a="补给站内设有贸易供应商、维修服务，以及为希望在外出时磨练工程学和采集技能的工匠准备的训练师。",al={"钢架补给站的训练师","我能在这里做什么","钢架补给站的服务"}}},fx={["01d49f70"]={q="钢架补给站危险吗？",a="直接来说并不危险。钢架补给站是一处安全的矮人工作营地和贸易站，坐落在卡拉诺斯以东的雪路旁。周围的峭壁和山丘上虽有野兽、游荡的穴居人，以及逃离诺莫瑞根陷落的麻风侏儒出没，但补给站本身仍牢牢掌握在联盟手中，由坚毅的矿工、工匠和附近的山地巡逻兵守卫。",al={"钢架补给站危险吗","钢架补给站的危险","钢架补给站安全吗"}},["14c76990"]={q="为什么叫钢架补给站？",a="这处哨站以负责监督此地事务的大工程师兼企业家贝尔丁·钢架命名。贝尔丁和其他工匠在卡拉诺斯这处繁忙聚落外建立了这个路边营地，用来维修、组装和测试矮人及侏儒的机械奇观、攻城器械与采矿装备。",al={"为什么叫钢架补给站","钢架是谁","钢架名称由来"}}},fp="18,272,28.601.0,27.200.0,19.189.0,33.150.0"}
P.entries["subzone:stendel-s-pond"] = {n="斯特登的池塘",s="斯特登的池塘是一处位于西部荒野哨兵岭西南方，且可能受到污染的小型水域。它被游荡的豺狼人所环绕，并有附近的坟墓作为标记，尽管存在险恶的隐患，但它仍是这片干旱土地上为数不多的几个淡水垂钓点之一。",h="斯特登的池塘是一处位于西部荒野哨兵岭西南方，且可能受到污染的小型水域。它被游荡的豺狼人所环绕，并有附近的坟墓作为标记，尽管存在险恶的隐患，但它仍是这片干旱土地上为数不多的几个淡水垂钓点之一。",kw={"豺狼人","坟墓","池塘","鼠尾鱼","哨兵岭","斯特登","西部荒野"},ang={["faction:Alliance"]="由于豺狼人营地的存在，这座靠近哨兵岭的池塘成为了民兵组织南部防线上一个不受控制的威胁。",["profession:Cooking"]="从这些浑浊水域中捕获的鼠尾鱼因可用于制作鱼类菜肴而受到厨师们的重视。"},sec={{t="危险的饮水处",b="斯特登的池塘位于哨兵岭西南方一隅，为西部荒野尘土飞扬的平原提供了一处宁静的休憩之所，尽管危险从未远离。豺狼人在泥泞的岸边徘徊，而散落的骸骨和两座孤坟暗示着，无论是池水还是周遭的野兽，对于粗心的旅人来说都是致命的。垂钓者们依然会冒险前往，以获取鼠尾鱼群。"}},faq={{q="斯特登的池塘位于哪里？",a="它位于西部荒野中心地带，哨兵岭的西南方，就在通往南部地区的尘土小径旁。",al={"斯特登的池塘位置","斯特登的池塘在哪里","寻找斯特登的池塘"}},{q="池塘周围潜伏着什么生物？",a="池塘泥泞的岸边有领地意识极强的河爪豺狼人游荡，它们会攻击任何靠近水域的流浪者。",al={"谁住在这里","斯特登的池塘的怪物","斯特登的池塘豺狼人"}},{q="为什么岸边会有骸骨和坟墓？",a="这些骸骨和两座无名坟墓指出了该地区的致命危险。旅人们究竟是沦为了豺狼人的猎物，还是被污浊的池水毒害，至今仍是一个不祥的谜团。",al={"这些坟墓是谁的","为什么有骸骨","池塘边的坟墓"}}},fx={a33fcb3a={q="斯特登的池塘是什么地方？",a="斯特登的池塘是一处宁静的小水塘，坐落在西部荒野中部平原的哨兵岭西南方。远看这里一片平静，但池塘岸边却诉说着这片尘土飞扬之地的艰难故事。",al={"斯特登的池塘是什么","斯特登的池塘概况","关于斯特登的池塘"}},["9e1e18fd"]={q="斯特登的池塘危险吗？",a="危险，独自旅行绝不安全。凶猛的豺狼人徘徊在水边，让任何靠近的举动都充满危险。此外，岸边排列着骸骨和孤坟，似乎说明当地野生动物致命，或者池塘里的死水已经变质，无法饮用。",al={"斯特登的池塘安全吗","斯特登的池塘有什么危险","斯特登的池塘有多危险"}}},fp="14,267,25.355.0,32.117.0,36.116.0,48.177.0"}
P.entries["subzone:stillwater-pond"] = {n="静水池",s="静水池是一片宁静、死气沉沉的水域，位于提瑞斯法林地布瑞尔的西侧。它曾是洛丹伦的活人孩子钟爱的野餐和游泳地点，如今已沦为一片浑浊的池塘，栖息着骷髅鱼，并有危险的食腐生物徘徊。",h="静水池是一片宁静、死气沉沉的水域，位于提瑞斯法林地布瑞尔的西侧。它曾是洛丹伦的活人孩子钟爱的野餐和游泳地点，如今已沦为一片浑浊的池塘，栖息着骷髅鱼，并有危险的食腐生物徘徊。",kw={"贝恩","澈水湖","布瑞尔","暗犬","骷髅鱼","静水池","提瑞斯法林地"},ang={["class:Hunter"]="池塘周围受到瘟疫感染的野生生物，包括像贝恩这样的狂暴暗犬，使该区域成为了布瑞尔外围巡逻侦察兵的危险狩猎场。",["race:Undead"]="对于那些保留着洛丹伦生活记忆的被遗忘者来说，静水池是一个残酷的提醒，勾起了他们曾在其曾经清澈的岸边野餐和游泳的逝去童年时光。"},sec={{t="荒废的休憩之所",b="在第三次战争和亡灵瘟疫的浩劫之前，静水池曾是提瑞斯法林地居民的一处宁静休憩地。附近村庄的家庭常聚集在它绿草如茵的岸边享用午后野餐，而那些年幼到无法挑战澈水湖危险深度的孩子们，则会在它的浅滩学习游泳。如今，那曾经田园诗般的水域已变得毫无生机，死气沉沉。活人早已绝迹，只留下骷髅鱼在水面下穿梭，漫无目的的亡灵在周围的树林中游荡。"},{t="迷雾中的潜行者",b="尽管与提瑞斯法那些饱受战火的道路和争夺中的农场相比，静水池较为安静，但这里依然暗藏危机。这片浑浊的水域只为林地里受瘟疫感染的野兽提供水源，其中最引人注目的莫过于一只名叫贝恩的凶猛暗犬，它常在岸边潜行。前往布瑞尔途中穿过西部草甸的旅人必须小心谨慎，因为掠食野兽和漫无目的的僵尸经常在水边徘徊。"}},faq={{q="瘟疫爆发前的静水池是什么样的？",a="在人类统治洛丹伦时期，静水池是一处风景优美且深受当地人喜爱的野餐地点。因为它比广阔的澈水湖更浅、更平静，家庭常带年幼的孩子来这里安全地游泳。",al={"静水池历史","静水池用途","提瑞斯法游泳点"}},{q="现在水里还有活物吗？",a="正常的海洋生物并未能在提瑞斯法受到的瘟疫侵蚀中存活下来。在这灰暗的水面下唯一游动的，是天灾军团的腐蚀所留下的被复活的鱼类骷髅残骸。",al={"静水池鱼类","静水池里有什么","静水池生物"}},{q="哪些危险生物在池塘附近游荡？",a="除了在林地游荡的无脑亡灵外，岸边最臭名昭著的威胁是贝恩，这是一只异常强大且好斗的暗犬，它常以粗心大意的旅人为食。",al={"静水池怪物","贝恩是谁","布瑞尔附近的暗犬"}},{q="静水池位于哪里？",a="静水池位于提瑞斯法林地中部，正处于布瑞尔镇的西侧，澈水湖的西南方。",al={"静水池位置","静水池地理位置","如何找到静水池"}}},fx={fa6e3aa4={q="静水池是什么地方？",a="静水池是一片幽静阴暗的湖泊，位于布瑞尔镇以西不远处。它曾是洛丹伦平民家庭钟爱的休闲胜地，如今却冷寂、灰暗而沉静，映照着笼罩提瑞斯法林地的荒凉景象。",al={"静水池是什么","静水池背景","介绍一下静水池"}},["7a8eb54a"]={q="静水池为什么荒废了？",a="第三次战争期间，天灾军团将亡灵瘟疫散布到提瑞斯法，静水池也随着王国的其他地方一同走向荒废。席卷洛丹伦的枯萎腐化夺去了池塘周围生者的性命，把宜人的野餐地变成了荒凉的旷野，野兽与游荡的亡者在此出没。",al={"静水池为何被遗弃","是什么毁了静水池","静水池为何死寂"}}},fp="15,272,16.533.0,20.437.0,48.231.0,42.196.0,46.178.0,33.129.0"}
P.entries["subzone:stonard"] = {n="斯通纳德",s="斯通纳德是部落在悲伤沼泽南部湿地建立的一座防御性前哨站。它始建于第一次战争期间，如今已成为现代部落在东部王国南部的重要立足点，也是监视诅咒之地的观察哨所。",h="斯通纳德是部落在悲伤沼泽南部湿地建立的一座防御性前哨站。它始建于第一次战争期间，如今已成为现代部落在东部王国南部的重要立足点，也是监视诅咒之地的观察哨所。",kw={"黑色沼泽","诅咒之地","大厅","兽人","罗卡德","斯通纳德","悲伤沼泽"},ang={["class:Shaman"]="斯通纳德作为东部王国南部的主要据点而闻名，部落萨满可以在此找到远离卡利姆多的指引与训练。",["faction:Horde"]="斯通纳德是部落在北部的荒芜之地和西部的荆棘谷之间，唯一的防御性锚点。"},sec={{t="第一次战争的遗迹",b="斯通纳德是艾泽拉斯最古老的兽人定居点之一。它是旧部落穿过黑暗之门进入曾经的黑色沼泽时建立的，斯通纳德及其姊妹哨站罗卡德共同构成了入侵者的防线支点。尽管在第二次战争结束后一度荒废并遭到破坏，但萨尔率领的新部落重建了斯通纳德并在此驻军。在传统的兽人大厅和防御工事的拱卫下，这座哨站如今已成为在这片未开化且充满危险的沼泽中，象征部落权威的一座坚实堡垒。"},{t="边境哨站",b="现代斯通纳德既是探险营地，也是集结地。制图师和侦察兵们分散在周围的泥沼中，勘测未知的沼泽地带，监视着当地的敌对野兽、迷失的德莱尼流浪者以及东部的沉没的神庙。至关重要的是，斯通纳德还为部落提供了一个位于破碎的诅咒之地北侧的后勤补给站，确保部落始终能密切关注那扇沉寂的黑暗之门。"}},faq={{q="为什么斯通纳德对部落很重要？",a="斯通纳德为部落在东部王国南部深处提供了一个坚固的军事和后勤枢纽。它使侦察兵能够勘测危险的悲伤沼泽，为进攻附近的沉没的神庙提供了行动基地，并保持着一支靠近诅咒之地的常备驻军。",al={"为什么斯通纳德在这里","斯通纳德的目的","斯通纳德是什么"}},{q="斯通纳德有多古老？",a="它可追溯到第一次战争时期，是艾泽拉斯最早建立的兽人定居点之一。它由旧部落在穿过黑暗之门后不久建立，在第二次战争后一度荒废，后来由萨尔领导的新部落进行了重建。",al={"斯通纳德历史","斯通纳德是何时建造的","谁建立了斯通纳德"}},{q="它的姊妹定居点罗卡德发生了什么事？",a="罗卡德与斯通纳德在第一次战争期间同时建立，这两座姊妹城镇是旧部落在沼泽防线的支点。与新部落重建的斯通纳德不同，自战争结束后，关于罗卡德的命运并无记录。",al={"罗卡德是什么","罗卡德历史","斯通纳德姊妹城镇"}},{q="我可以飞行或直接前往斯通纳德吗？",a="可以。斯通纳德拥有连通大陆的飞行点，连接着卡加斯、烈焰峰、格罗姆高营地、中立港口藏宝海湾，以及河林的洛格玛。",al={"斯通纳德飞行点","如何前往斯通纳德","斯通纳德传送门"}}},fp="7,270,24.519.0,16.452.0,38.289.0,19.260.0,48.229.0,42.178.0"}
P.entries["subzone:stone-cairn-lake"] = {n="石碑湖",s="石碑湖是一片位于艾尔文森林东北部的环形水域。湖中心坐落着一座小岛，上面矗立着英雄哨岗，这是为纪念第一次战争中阵亡者而建立的纪念碑。这里曾是一个平静的沉思之地，如今却因湖岸边充满敌意的鱼人和占据小岛的流亡法师而不再安宁。",h="石碑湖是一片位于艾尔文森林东北部的环形水域。湖中心坐落着一座小岛，上面矗立着英雄哨岗，这是为纪念第一次战争中阵亡者而建立的纪念碑。这里曾是一个平静的沉思之地，如今却因湖岸边充满敌意的鱼人和占据小岛的流亡法师而不再安宁。",kw={"铜矿","艾尔文森林","第一次战争","英雄哨岗","鱼人","流亡法师","石碑湖","纪念之石"},ang={["profession:Mining"]="环绕石碑湖的断崖和丘陵拥有艾尔文森林中最密集的铜矿矿脉之一，这使其成为渴望成为锻造师和工程师的人们的必经之地。",["race:Human"]="中心岛是暴风王国的一处意义深远的纪念地，旨在纪念第一次战争期间王国陷落时牺牲的人们。"},sec={{t="被围困的纪念碑",b="石碑湖的名字源于其中心大岛上耸立的显眼石制纪念碑。这座纪念碑被称为英雄哨岗，是为了纪念在与兽人部落进行的第一次战争中牺牲的大量人类生命而建立的。曾经，家庭和朝圣者可以安全地前往岛上缅怀先烈，凝望着平静水面上的庄严石碑。然而今天，危险的流亡法师直接在纪念碑旁建立了营地，将这个神圣的缅怀之地变成了一处充满敌意的堡垒。"},{t="湖岸",b="环绕着这片环形湖泊的风景优美的湖岸，如今对当地居民和旅行者来说已变得愈发危险。一群极具攻击性的鱼人占据了南岸，沿着水线建造了简陋的棚屋，骚扰着任何靠近的人。除了这些危险之外，环绕湖泊的丘陵和岩层中蕴藏着丰富的矿脉，使得这片区域成为了不惧当地威胁的勘探者和矿工们经常光顾的地方。"}},faq={{q="为什么这里叫石碑湖？",a="湖名取自英雄哨岗，这是一座建在中心岛屿上的石堆纪念碑，旨在纪念第一次战争中牺牲的暴风城士兵和平民。",al={"石碑湖命名","为什么叫石碑湖","地名来源"}},{q="现在是谁占据了中心岛？",a="这座岛屿被流亡法师和叛逆者占领，他们驱逐了普通的朝圣者，并在纪念碑周围建立了防御营地。",al={"岛上的人","岛上的法师","湖上的流亡法师"}},{q="为什么鱼人聚集在水边？",a="当地的一支鱼人部落在南岸的浅滩和河岸定居下来，建造了原始的棚屋，并将这片鱼产丰富的水域据为己有。",al={"石碑湖的鱼人","湖中鱼人","南岸棚屋"}},{q="岛上的纪念碑叫什么名字？",a="这座纪念碑被称为英雄哨岗，其主体是一座通常被称为纪念之石的石堆。",al={"岛上纪念碑名称","纪念碑名称","石碑湖圣坛"}}},fx={a25fa3d9={q="石碑湖是什么地方？",a="石碑湖是艾尔文森林东北部的一处环形湖泊。湖心岛上坐落着英雄哨岗，这是一座庄严的纪念碑，纪念在第一次战争中牺牲的人们。这里曾是旅人和哀悼者的宁静去处，如今却日渐荒芜，危机四伏。",al={"石碑湖是什么","石碑湖信息","介绍一下石碑湖"}},["9a875c99"]={q="石碑湖危险吗？",a="危险，四处游荡的旅人会面临重大威胁。流亡法师占据了湖心岛，并用奥术魔法凶狠地守卫营地。此外，敌对的鱼人已经占领浅滩，并在南岸建立了聚落，会攻击任何靠近的人。",al={"石碑湖安全吗","石碑湖的威胁","石碑湖危险"}},["92ff0cce"]={q="石碑湖为什么不再是朝圣之地？",a="石碑湖曾是宁静的朝圣之地，居民会来此缅怀第一次战争中阵亡的士兵。然而，随着动乱加剧，暴风城的卫兵已无力确保此地安全，流亡施法者趁机占据纪念碑所在的岛屿，凶残的鱼人也夺走了湖岸。",al={"石碑湖为何被遗弃","石碑湖为何荒废","石碑湖朝圣地"}}},fp="16,325,19.553.0,18.454.0,34.185.0,46.140.0,42.160.0,42.110.0"}
P.entries["subzone:stonebull-lake"] = {n="石牛湖",s="石牛湖是一片宁静的马蹄形水域，环绕着莫高雷中部的血蹄村。它由平原上纯净的自然径流汇聚而成，为在凯恩·血蹄指导下步入成年的牛头人后辈提供了至关重要的淡水、丰富的鱼类资源以及宁静的岸边休憩之所。",h="石牛湖是一片宁静的马蹄形水域，环绕着莫高雷中部的血蹄村。它由平原上纯净的自然径流汇聚而成，为在凯恩·血蹄指导下步入成年的牛头人后辈提供了至关重要的淡水、丰富的鱼类资源以及宁静的岸边休憩之所。",kw={"血蹄村","垂钓","湖泊","莫高雷","石牛湖","雷霆崖"},ang={["race:Tauren"]="对于在莫高雷各地建立家园的牛头人而言，石牛湖提供了温和的滋养，也是在大地母亲的恩赐下，靠近他们首都的一处寄托。"},sec={{t="平原之水",b="石牛湖三面环绕血蹄村，定义了莫高雷中部的地理格局。一座木桥横跨湖面最狭窄处，承载着连接该定居点与北面宏伟的雷霆崖高地之间的主干土路。湖水平静，鱼类繁多，其岸边是休憩的猎人、疲惫的旅者以及在广阔苍穹下学习捕鱼技艺的学徒们所青睐的地方。"}},faq={{q="石牛湖位于哪里？",a="石牛湖位于莫高雷中部。它呈马蹄形环绕着血蹄村，从三面包围着这个定居点。",al={"石牛湖位置","石牛湖在哪里","莫高雷湖泊"}},{q="横跨湖面的桥梁有什么用途？",a="这座桥横跨石牛湖最狭窄的部分，承载着连接血蹄村与北方雷霆崖的主要道路。",al={"石牛湖之桥","血蹄村附近的桥","跨越石牛湖的道路"}},{q="为什么石牛湖对牛头人很重要？",a="该湖泊是血蹄村居民不可或缺的淡水来源和重要的捕鱼点。对于在莫高雷中部进行训练的年轻牛头人勇士来说，它也是一处沉思与聚会的宁静之地。",al={"为什么石牛湖很重要","石牛湖的用途"}}},fx={b1753406={q="石牛湖是什么地方？",a="石牛湖是一片宽阔的马蹄形湖泊，环抱着莫高雷中部的血蹄村。湖水清凉甘甜，以鱼产丰富而闻名草原，既是重要的食物来源，也是牛头人常在岸边垂钓、享受宁静时光的好去处。一座坚固的木桥横跨湖面最窄处，供旅人沿着连接血蹄村与北方峭壁的主路通行。",al={"莫高雷石牛湖","石牛湖是什么","关于石牛湖"}},["641ee038"]={q="石牛湖危险吗？",a="石牛湖本身通常平静安宁，又有血蹄村和附近巡逻的牛头人勇士守护。莫高雷广阔的草原上虽有掠食者和四处游荡的野兽出没，但石牛湖水域仍是当地最安全的捕鱼和采集地点之一，近旁湖岸没有潜伏的水中怪物或敌对聚落。",al={"石牛湖危险吗","石牛湖的威胁","石牛湖危险"}}},fp="14,298,19.448.0,32.132.0,44.147.0,46.222.0"}
P.entries["subzone:stonefield-farm"] = {n="斯通菲尔德农场",s="斯通菲尔德农场是一处坐落在艾尔文森林南部的农庄。这里居住着斯通菲尔德家族，他们与邻居马科伦家族长期陷入激烈的世仇之中。",h="斯通菲尔德农场是一处坐落在艾尔文森林南部的农庄。这里居住着斯通菲尔德家族，他们与邻居马科伦家族长期陷入激烈的世仇之中。",kw={"艾尔文森林","米莱德·斯通菲尔德","马科伦","斯通菲尔德","斯通菲尔德农场","托米·乔"},ang={["race:Human"]="对于从北郡出发的人类新手来说，斯通菲尔德家族和马科伦家族之间的争吵，让人在土匪和豺狼人的威胁之外，得以轻松地一窥王国农村的生活。"},sec={{t="苦涩的家园",b="斯通菲尔德农场坐落在闪金镇以南的青葱丘陵之中，在为王国生产农作物的同时，也一直与附近的马科伦农场保持着长达数十年的深仇大恨。两家之间的积怨导致了琐碎的争吵、互相指责偷窃以及持续的紧张局势。然而，在这敌对的争执之下，年轻的托米·乔·斯通菲尔德却暗中爱上了梅贝尔·马科伦，这段安静的恋情要么能弥合两大家族之间的裂痕，要么会引发更激烈的愤怒。"}},faq={{q="斯通菲尔德家族和马科伦家族之间的世仇是什么？",a="斯通菲尔德家族和马科伦家族在艾尔文森林南部有着长期且顽固的竞争关系。他们不断指责对方擅自闯入、小偷小摸以及各种不当行为，甚至在简单的邻里事务上也拒绝合作。",al={"斯通菲尔德与马科伦的世仇","斯通菲尔德家族为何争斗","斯通菲尔德的竞争对手"}},{q="谁住在斯通菲尔德农场？",a="这座农场由斯通菲尔德家族经营，其中包括米莱德·斯通菲尔德、斯通菲尔德妈妈和年轻的托米·乔·斯通菲尔德。",al={"斯通菲尔德非玩家角色","谁在斯通菲尔德农场"}},{q="托米·乔·斯通菲尔德有什么秘密？",a="尽管两家之间存在着激烈的敌意，托米·乔·斯通菲尔德还是暗中爱上了梅贝尔·马科伦。这两位恋人依靠富有同情心的旅行者来传递信息和礼物，以免被家人发现。",al={"托米·乔的秘密","托米·乔的恋情","斯通菲尔德的爱情"}}},fx={["60255a1c"]={q="斯通菲尔德农场是什么地方？",al={"斯通菲尔德农场是什么","艾尔文森林斯通菲尔德农场","关于斯通菲尔德农场"}},["45c8f9cb"]={q="斯通菲尔德农场危险吗？",a="农场本身由家族经营，通常很安全，但周围的田野就另当别论了。和艾尔文森林南部的大部分地区一样，野兽会在边缘地带出没，当地的土匪和不断侵扰的害虫也常常威胁牲畜与庄稼。旅人进入牧场、沿着附近河岸和果园行走时，应当随时准备好武器。",al={"斯通菲尔德农场危险吗","斯通菲尔德农场的威胁","斯通菲尔德农场的敌人"}}},fp="15,190,18.517.0,58.248.0,29.124.0,38.239.0"}
P.entries["subzone:stonefire-tavern"] = {n="Stonefire Tavern",s="Stonefire Tavern是铁炉堡这座山中之城主要的旅店，为往来的旅人提供服务。它坐落在城市大门以北熙熙攘攘的平民区，提供温暖的炉火、烈性的矮人麦酒，以及让来自卡兹莫丹各地的冒险者休憩的场所。",h="Stonefire Tavern是铁炉堡这座山中之城主要的旅店，为往来的旅人提供服务。它坐落在城市大门以北熙熙攘攘的平民区，提供温暖的炉火、烈性的矮人麦酒，以及让来自卡兹莫丹各地的冒险者休憩的场所。",kw={"平民区","矮人旅店","gwenna firebrew","旅店老板洛雷·火酒","铁炉堡","卡兹莫丹","stonefire tavern"},ang={["faction:Alliance"]="作为距离铁炉堡正门最近的主要旅店，Stonefire往往是到访这座矮人首都的联盟旅行者的中心集结地。",["race:Dwarf"]="对于从卡兹莫丹各地远征归来的矮人们来说，Stonefire Tavern是他们在首都里喝上一品脱冰镇火酒并打听当地消息的首选之地。"},sec={{t="平民区中心",b="Stonefire Tavern位于平民区要塞大门的北侧，是铁炉堡首屈一指的酒馆。这里由旅店老板洛雷·火酒与其女儿Gwenna共同经营，为疲惫的旅人提供热腾腾的饭菜、当地酿造的酒水以及山底下的住处。无论你是为了躲避丹莫罗严酷的山区风雪，还是在深入城市之前寻找交换情报和补给的场所，来自联盟各地的旅行者都会聚集在这里的炉火旁。"}},faq={{q="Stonefire Tavern位于哪里？",a="这家旅店位于铁炉堡的平民区，穿过主城大门向北走一小段路即可到达。",al={"stonefire tavern位置","铁炉堡旅店位置","stonefire在哪里"}},{q="谁在经营Stonefire Tavern？",a="这家旅店由旅店老板洛雷·火酒在女儿Gwenna Firebrew的协助下共同管理。",al={"谁经营stonefire tavern","stonefire旅店老板","火酒旅店"}},{q="旅行者可以在这里绑定炉石吗？",a="是的。旅店老板洛雷·火酒欢迎那些想把Stonefire Tavern作为铁炉堡基地联盟旅行者。",al={"铁炉堡炉石绑定","铁炉堡旅店","stonefire炉石"}},{q="附近有什么设施？",a="旅店入口外就有一个城市邮箱，周围的平民区里也遍布银行、商人和贸易补给商。",al={"stonefire服务","stonefire附近的邮箱"}}},fx={a8df8501={q="Stonefire Tavern是什么地方？",a="Stonefire Tavern是铁炉堡主要的聚会场所和旅店之一。它坐落在城市大门以北、繁忙的公共区内，为疲惫的旅人、士兵和前来这座山中首都的访客提供温暖的炉火、醇厚的矮人啤酒和舒适的休息之处。",al={"stonefire tavern是什么","铁炉堡stonefire tavern","铁炉堡stonefire旅店"}},["3314a531"]={q="Stonefire Tavern危险吗？",a="一点也不危险。Stonefire Tavern是坐落在铁炉堡坚固核心深处的一处安全友善的避风港。这里有矮人巡逻队守卫，周围也都是联盟同胞；你可能遇到的唯一真正危险，就是多喝了几杯火酒家的烈性麦酒。",al={"stonefire tavern安全吗","stonefire tavern危险","stonefire tavern的威胁"}}},fp="16,284,20.513.0,38.120.0,34.97.0,43.122.0,26.136.0"}
P.entries["subzone:stonemaul-ruins"] = {n="石槌废墟",s="石槌废墟是石槌村破碎的残骸，这里曾是卡利姆多石槌食人魔引以为傲的定居点。在被黑龙军团驱逐后，该氏族向北逃亡，留下他们曾经的家园被火鬃龙人所占领。",h="石槌废墟是石槌村破碎的残骸，这里曾是卡利姆多石槌食人魔引以为傲的定居点。在被黑龙军团驱逐后，该氏族向北逃亡，留下他们曾经的家园被火鬃龙人所占领。",kw={"蕨墙","黑龙谷","火鬃","考戈尔","莫格穆洛克","石槌","石槌废墟","石槌村"},ang={["faction:Horde"]="石槌食人魔是坚定的盟友，他们曾与萨尔的部落并肩作战，与库尔提拉斯浴血奋战。帮助他们反击黑龙军团是对这份盟约的尊重。"},sec={{t="氏族家园的兴衰",b="石槌食人魔在迁徙到卡利姆多后，于尘泥沼泽阴暗的湿地中建立了他们的定居点。当兽王雷克萨勇闯氏族致命的试炼、击杀残暴的酋长考戈尔，并号召食人魔保卫新生的部落免受库尔提拉斯军队的侵害时，这座村庄声名大噪。战争结束后，雷克萨将指挥权留给了食人魔莫格穆洛克。在莫格穆洛克自私的统治下，村庄逐渐衰落，最终遭到黑龙军团的伏击并被摧毁。幸存的食人魔向北逃亡并建立了蕨墙村，而奥妮克希亚的后裔则完全占据了这些废墟。"},{t="收复家园的斗争",b="如今，这些废墟牢牢地坐落在黑龙谷内，到处爬满了照看附近巢穴的火鬃龙人。虽然莫格穆洛克大王变得胆小懦弱，满足于在蕨墙村苟延残喘，但像萨尔格和德拉兹辛比这样更年长、更自豪的氏族成员却拒绝放弃他们的家园。他们以蕨墙村为据点，敦促部落的勇士们屠杀占领此地的龙人并摧毁龙蛋，希望能有一天石槌食人魔能再次进军并收复他们祖先的村庄。"}},faq={{q="谁曾经住在石槌废墟？",a="石槌食人魔氏族在抵达卡利姆多后，建造并居住在这个被称为石槌村的定居点。",al={"谁曾住在这里","石槌废墟历史","谁建造了石槌村"}},{q="为什么村庄会被遗弃？",a="奥妮克希亚的黑龙军团袭击了该定居点并驱逐了食人魔，将村庄变成了火鬃龙人的巢穴哨站。",al={"为什么石槌被摧毁","石槌村发生了什么","谁袭击了石槌"}},{q="幸存的食人魔去了哪里？",a="幸存者在莫格穆洛克大王的带领下向北撤退到尘泥沼泽，并将蕨墙村作为他们临时的据点。",al={"食人魔现在在哪里","石槌食人魔所在地"}},{q="雷克萨与这个地方有什么联系？",a="雷克萨来到这里是为了招募食人魔对抗库尔提拉斯。他通过了他们的试炼，在战斗中击杀了暴君考戈尔，并曾短暂担任酋长，随后将领导权交给了莫格穆洛克。",al={"雷克萨与石槌","雷克萨与食人魔酋长"}},{q="食人魔计划夺回废墟吗？",a="是的。虽然莫格穆洛克不敢采取行动，但萨尔格和德拉兹辛比等其他石槌领袖积极招募部落的冒险者来清除火鬃龙人，为夺回家园做准备。",al={"食人魔会回去吗","收复石槌"}}},fp="15,257,30.654.0,28.522.0,36.124.0,30.146.0,33.144.0,43.201.0,38.196.0"}
P.entries["subzone:stonesplinter-valley"] = {n="碎石怪之谷",s="碎石怪之谷是位于洛克莫丹西南部的一处崎岖山谷，那里充斥着充满敌意的穴居人。它曾经是一片原始的高山空地，如今在穴居人首领格拉姆格的残暴统治下，已经变成了一座设防营地。",h="碎石怪之谷是位于洛克莫丹西南部的一处崎岖山谷，那里充斥着充满敌意的穴居人。它曾经是一片原始的高山空地，如今在穴居人首领格拉姆格的残暴统治下，已经变成了一座设防营地。",kw={"格拉姆格","洛克莫丹","碎石怪","碎石怪之谷","塞尔萨玛","穴居人"},ang={["faction:Alliance"]="清理碎石怪之谷可以确保穿过洛克莫丹的重要补给路线安全，在铁炉堡的兵力分散在各地的情况下，这些路线已经变得十分脆弱。",["race:Dwarf"]="这里的穴居人泛滥是对洛克莫丹安全的一种侮辱，塞尔萨玛的山地探险队员们指望着勇敢的矮人同胞能清除掉格拉姆格手下那些不断扩张的野蛮生物。"},sec={{t="嘶鸣的要塞",b="碎石怪之谷坐落在洛克莫丹西南部崎岖的山坡之间，曾经是一片宁静的高山空地。当成群结队的地下穴居人从卡兹莫丹各地挖掘通道来到地表时，这份宁静便荡然无存。碎石怪部族将这座山谷占为己有，迅速将岩石峡谷变成了粗陋的防御工事，挖掘洞穴、竖起路障，并猎杀任何靠近的生物。他们的人数使这座山谷成为了洛克莫丹南部道路上的一道伤疤，迫使塞尔萨玛的山地探险队员不得不雇佣愿意消灭这些穴居人并除掉他们那高大的军阀格拉姆格的冒险佣兵。"}},faq={{q="碎石怪之谷位于哪里？",a="它位于洛克莫丹西南角的群山之中，就在经过灰爪山的主干道南侧。",al={"碎石怪之谷位置","碎石怪之谷在哪里","洛克莫丹穴居人山谷"}},{q="谁统治着碎石怪之谷？",a="这座营地由一名残暴的穴居人首领格拉姆格所统治，他从山谷的最深处指挥该部族对当地的旅行者和巡逻队进行袭击。",al={"谁领导碎石怪穴居人","格拉姆格","洛克莫丹穴居人首领"}},{q="为什么穴居人会来到洛克莫丹？",a="穴居人是在矮人于卡兹莫丹其他地区进行挖掘时从地下深处被发掘出来的。在无脑攻击性的驱使下，不同的战帮迁移到了地表，而碎石怪部族选择了这片偏僻的山谷作为他们的主要集结地。",al={"为什么洛克莫丹有穴居人","穴居人从哪里来","洛克莫丹穴居人起源"}},{q="为什么矮人想要清理这座山谷？",a="山谷距离矮人的定居点、矿井和山路非常近，构成了严重的威胁。放任一支根深蒂固的碎石怪穴居人军队不管，不仅威胁着穿过洛克莫丹南部的旅行者的安全，也让本已捉襟见肘的山地探险队巡逻任务倍感压力。",al={"为什么要对抗碎石怪穴居人","塞尔萨玛穴居人问题"}}},fx={c84babb8={q="什么是碎石怪之谷？",a="碎石怪之谷是洛克莫丹西南部一处崎岖的山间谷地。这里曾是一片原始的高山景致，如今却被大批敌对穴居人彻底占据。他们将谷中的洞穴和山隘据为己有，建成自己的据点。",al={"碎石怪之谷概况","什么是碎石怪之谷","关于碎石怪之谷"}},["30aeaf73"]={q="碎石怪之谷发生了什么？",a="洛克湖山地盆地中这片原本宁静、未经扰动的角落，如今已变成穴居人的巢穴。碎石怪氏族在卡兹莫丹各地出现后，大举涌入山谷，蹂躏荒野，驱逐所有胆敢靠近的人。",al={"碎石怪之谷的历史","山谷发生了什么","碎石怪之谷的穴居人侵扰"}},["39c06fe2"]={q="碎石怪之谷危险吗？",a="这里极其危险。敌对的碎石怪穴居人密集地遍布山谷，凶狠地抵御外来者，守卫自己的领地。谷地深处潜伏着他们强大的酋长格拉姆格，任何深入谷中的行动都可能致命。",al={"碎石怪之谷有多危险","碎石怪之谷的威胁","碎石怪之谷安全吗"}},["27e6d962"]={q="为什么叫碎石怪之谷？",a="山谷的名字直接源自盘踞并控制此地的碎石怪穴居人部族。在周边矮人守军眼中，他们根深蒂固的存在彻底改变了这片区域的面貌。",al={"碎石怪之谷名称由来","为什么叫碎石怪之谷","碎石怪名称的由来"}}},fp="20,234,23.646.0,38.136.0,31.171.0,38.260.0,50.267.0"}
P.entries["subzone:stonetalon-peak"] = {n="石爪峰",s="石爪峰是一处隐匿在石爪山脉西北边缘青翠高山峡谷中的古老暗夜精灵圣所。这里是卡多雷的神圣之地，由当地的德鲁伊照看，也是联盟在这些崎岖高地上的主要堡垒。",h="石爪峰是一处隐匿在石爪山脉西北边缘青翠高山峡谷中的古老暗夜精灵圣所。这里是卡多雷的神圣之地，由当地的德鲁伊照看，也是联盟在这些崎岖高地上的主要堡垒。",kw={"jaina","卡多雷","暗夜精灵","神谕者","哨兵","石爪","石爪峰","鹰巢","萨尔"},ang={["class:Druid"]="这处圣所与塞纳里奥的历史以及神圣的鹰巢有着深厚的联系，使其成为了荒野守护者们朝圣和防御的关键场所。",["faction:Alliance"]="石爪峰是你在西部山脉中唯一的坚固立足点，在敌对区域内提供关键的休憩地、飞行路线和任务协助。"},sec={{t="神圣的山谷",b="石爪峰高耸于低海拔地区干旱的尘土之上，展开了一片郁郁葱葱、云雾缭绕的圣所。这里自古以来就被视为神圣之地，浸透着古老的魔法，山谷中保留着数千年前的遗迹，那时该地区还坐落着在大分裂之前供奉艾萨拉女王的神庙。在现代，卡多雷哨兵和德鲁伊在此恢复了有序且和平的治理，维护着这片宁静的避难所，这里不仅有一处林精巢穴，还有一个重要的联盟飞行点。"},{t="命运的十字路口",b="除了田园诗般的森林和古老的遗迹外，石爪峰还因第三次战争而具有历史意义。在麦迪文预言的指引下，Jaina Proudmoore的人类远征军和萨尔的部落都攀登上了这片危险的高地，寻找隐居在深山洞穴中的神谕者。那次决定性的相遇迫使宿敌放下了手中的利刃，为在海加尔山共同抵御燃烧军团的艰难契约奠定了基础。如今，这里依然牢牢掌握在哨兵手中，尽管低地部落的入侵让守卫们时刻保持警惕。"}},faq={{q="为什么石爪峰相比周围的山脉如此翠绿？",a="石爪峰坐落在一个受保护的高海拔盆地中，充满了古老的魔法。通过暗夜精灵和附近鹰巢德鲁伊的精心照料，这里得以保留了一片充满生机的森林圣所，茂密的植被与下方焦黑、嶙峋的悬崖形成了鲜明的对比。",al={"为什么石爪峰是绿色的","为什么石爪峰会有森林","石爪峰天气"}},{q="第三次战争期间这里发生了什么？",a="在先知麦迪文的预言警告引导下，Jaina Proudmoore和萨尔都来到了石爪峰，寻找山洞中的神谕者。他们在深山中的会面促使双方达成了历史性的休战，让联盟与部落联合起来对抗燃烧军团。",al={"石爪峰发生了什么魔兽争霸3","jaina和萨尔石爪","神谕者石爪"}},{q="现在是谁控制着石爪峰？",a="该山峰是一处联盟哨站，由暗夜精灵哨兵和德鲁伊保护和维护。它是联盟冒险者在石爪山脉活动时的主要避风港、任务中心和飞行管理员所在地。",al={"石爪峰是联盟还是部落","谁住在石爪峰","石爪峰阵营"}},{q="这里有哪些古老遗迹？",a="散布在峡谷中的断壁残垣和大理石建筑是古老暗夜精灵帝国的遗迹，在大分裂和艾萨拉女王堕落之前，这里曾是供奉她的神庙。",al={"石爪峰遗迹","古老神庙石爪","艾萨拉神庙石爪峰"}}},fx={["755df306"]={q="什么是石爪峰？",a="石爪峰是一处郁郁葱葱的山间谷地，也是暗夜精灵的聚居地，坐落在石爪山脉最西北端。这里对当地文化而言神圣无比，充盈着古老的魔法；这片繁茂的圣地与下方荒芜的峭壁形成鲜明对比。它是暗夜精灵及其联盟盟友在卡利姆多中部的重要北方堡垒。",al={"什么是石爪峰","石爪峰概况","关于石爪峰"}},d4bc90d5={q="石爪峰危险吗？",a="林地本身是联盟设防的庇护所，但周围的山峰危机四伏。凶猛的 harpies 在峭壁间筑巢，敌对的荆棘谷地精伐木工毁坏附近的森林，部落则争夺山间通道。攀登石爪峰的旅人必须时刻警惕狭窄山道上的伏击。",al={"石爪峰安全吗","石爪峰的威胁","石爪峰的危险"}}},fp="15,269,22.491.0,21.593.0,70.293.0,40.291.0,39.233.0,36.239.0"}
P.entries["subzone:stonewatch"] = {n="石堡",s="石堡是位于赤脊山中心的一座坚固堡垒，旨在保护周边人类土地免受北方入侵。这座堡垒曾由暴风城的士兵驻守，如今已沦陷并处于黑石兽人的残酷控制之下，对附近的湖畔镇构成了直接威胁。",h="石堡是位于赤脊山中心的一座坚固堡垒，旨在保护周边人类土地免受北方入侵。这座堡垒曾由暴风城的士兵驻守，如今已沦陷并处于黑石兽人的残酷控制之下，对附近的湖畔镇构成了直接威胁。",kw={"黑石兽人","加塞尔佐格","湖畔镇","摩根斯","赤脊山","石堡","石堡要塞","萨瑞尔祖恩"},ang={["faction:Alliance"]="石堡代表了敌对兽人对联盟核心领土最危险的前沿入侵之一，因此将其收复对于赤脊山的安全至关重要。",["race:Human"]="第12军刀军团的屠杀和要塞的陷落，痛苦地提醒着人们湖畔镇的脆弱和暴风城政治上的漠视。"},sec={{t="沦陷的堡垒",b="石堡坐落在石堡瀑布附近的悬崖之上，由一座坚固的塔楼和要塞组成，旨在守卫来自燃烧平原的通道。这座堡垒最初由湖畔镇的守军把守，后来因背叛者术士摩根斯与黑石氏族结盟而沦陷。在黑暗魔法的加持下，入侵的兽人击溃了当地的人类守军——第12军刀军团，并占领了这座堡垒。尽管摩根斯最终背叛了他的盟友，并带着一支暗皮豺狼人军队撤退到了附近的伊尔加拉之塔，但黑石兽人在督军加塞尔佐格和中尉萨瑞尔祖恩的指挥下，依然牢牢控制着这座要塞。"},{t="对湖畔镇的威胁",b="随着石堡被敌对的兽人牢牢占据，湖畔镇直接处于迫在眉睫的征服威胁之下。由于暴风城贵族议会的冷漠或无能，无法提供实质性的军事增援，所罗门镇长和治安官马瑞斯被迫雇佣佣兵和志愿者。铲除该堡垒的领导层——即同时针对萨瑞尔祖恩和加塞尔佐格——仍然是小镇解除该地区围困的孤注一掷的首要希望。"}},faq={{q="谁现在控制着石堡？",a="石堡目前被黑石氏族的兽人占据，指挥官是督军加塞尔佐格和他的副官萨瑞尔祖恩。他们驱逐了王国的驻军，现在将这座堡垒作为对整个赤脊山发动攻击的基地。",al={"石堡里有什么人","谁控制着石堡","石堡的敌人"}},{q="人类是如何失去石堡的？",a="这座要塞是在黑石氏族的一次协同入侵中陷落的，当时得到了叛变人类术士摩根斯的黑暗魔法支持。他们合力击溃了第12军刀军团的守卫者，占领了整个建筑群。",al={"石堡的陷落","石堡是如何陷落的","石堡背景故事"}},{q="为什么暴风城不派军队将其夺回？",a="暴风城拒绝向边境地区调拨足够的部队，导致所罗门镇长和治安官马瑞斯只能独自防守赤脊山。湖畔镇只能依靠路过的冒险者和雇佣兵来组织对石堡的反击。",al={"为什么没有暴风城的支援","湖畔镇增援"}},{q="石堡和伊尔加拉之塔有什么关系？",a="摩根斯最初协助黑石兽人夺取了石堡，但在胜利后不久，他就背叛了他的盟友。他在附近建造了伊尔加拉之塔，聚集了一群由魔法奴隶和暗皮豺狼人组成的随从，同时攻击兽人和人类。",al={"与伊尔加拉之塔的联系","摩根斯与石堡"}}},fx={["5eefcf97"]={q="什么是石堡？",a="石堡是一座设防的军事据点，位于赤脊山中部，建在飞流直下的石堡瀑布上方高处。湖畔镇的人类修建了这座要塞，作为抵御从燃烧平原侵袭而来的兽人的重要防线。它由坚固的石堡要塞和一座俯瞰周围山谷的装甲瞭望塔组成。",al={"什么是石堡","石堡要塞概况","介绍一下石堡"}},ae6d9597={q="石堡危险吗？",a="石堡是赤脊山最危险的区域之一。这里防御森严，盘踞着大批纪律严明的黑石兽人入侵者，是他们袭击周围山谷的主要集结地。闯入者将面对久经战阵的步兵、哨兵和术士；他们都效忠于军阀加塞尔佐格，因此任何进攻都凶险致命。",al={"石堡有多危险","石堡的威胁","石堡安全吗"}}},fp="10,295,17.689.0,23.484.0,34.240.0,35.228.0,52.247.0,69.264.0"}
P.entries["subzone:stonewatch-falls"] = {n="石堡瀑布",s="石堡瀑布是一处风景秀丽的瀑布和深山水潭，位于赤脊山的东部边缘，由止水湖流出的河水汇聚而成。瀑布从石堡高耸的山崖下倾泻而下，其与世隔绝的水域被一支充满敌意的鱼人部落占据。",h="石堡瀑布是一处风景秀丽的瀑布和深山水潭，位于赤脊山的东部边缘，由止水湖流出的河水汇聚而成。瀑布从石堡高耸的山崖下倾泻而下，其与世隔绝的水域被一支充满敌意的鱼人部落占据。",kw={"止水湖","鱼人","赤脊山","石堡","石堡瀑布","瀑布"},ang={["faction:Alliance"]="位于石堡瀑布的鱼人定居点是又一个危险的怪物据点，它们不断袭扰着本就动荡不安的赤脊山东部地区。"},sec={{t="危险的山中盆地",b="石堡瀑布源自止水湖东侧的河流，沿崎岖的地势奔流而下，直抵黑石兽人要塞石堡之下。倾泻的水流在山脚下冲刷出一个深邃的水潭。尽管这里自然风光绝美，但旅人们很少在此驻足观赏；一群凶残的鱼人盘踞在水潭边，搭建起粗陋的芦苇棚屋，猎杀任何胆敢靠近水边的愚蠢之徒。"}},faq={{q="石堡瀑布的水源来自哪里？",a="瀑布的源头是止水湖东侧流出的河流，河水沿山坡而下，汇入石堡悬崖下的幽静山间盆地。",al={"石堡瀑布从哪里开始","瀑布水源","石堡河流源头"}},{q="石堡瀑布周围生活着哪些生物？",a="一支当地的鱼人部落占据了瀑布的岸边。他们以深山水潭中的鱼类为食，并在河岸边搭建了简陋的窝棚和栖身之所。",al={"石堡瀑布有什么","石堡瀑布的鱼人","瀑布附近的怪物"}},{q="石堡瀑布与石堡要塞有联系吗？",a="瀑布位于石堡及其废弃要塞正下方的山脚处。虽然上方的高地堡垒由黑石兽人把守，但下方的水域盆地则被鱼人控制。",al={"瀑布与要塞的联系","石堡要塞在瀑布附近吗","石堡关系"}}},fx={ffdc928b={q="什么是石堡瀑布？",a="石堡瀑布是一处风景秀丽的瀑布，位于止水湖东侧河流的尽头。瀑布从石堡要塞正下方的山坡倾泻而下，汇入赤脊山东部岩石高地间一处幽深僻静的山湖。",al={"石堡瀑布传说","这是什么地方","石堡瀑布在哪里"}},["763cc7e3"]={q="石堡瀑布危险吗？",a="是的，旅人应小心行事。一个敌对的鱼人部族盘踞在水潭及其岸边，并沿岸搭建了简陋的棚屋。这些守土的水岸爬行者，以及上方石堡要塞中黑石兽人的威胁，都让这里的水域远称不上平静。",al={"石堡瀑布的危险","这里安全吗","石堡瀑布的威胁"}},["7a8101a7"]={q="为什么叫石堡瀑布？",a="瀑布的名字直接源自石堡要塞，那座坚固的堡垒高踞于瀑布上方。水流从要塞下方的山坡径直倾泻而下。",al={"石堡瀑布名称由来","为什么叫石堡瀑布"}}},fp="16,292,25.441.0,53.165.0,44.178.0,49.190.0"}
P.entries["subzone:stonewatch-keep"] = {n="石堡要塞",s="石堡要塞是一座耸立在赤脊山东部的坚固石制堡垒，曾由暴风城王国建造并驻守。它现已被一支入侵的黑石兽人军队攻陷，成为了他们的前线作战基地，这些兽人军阀正以此为据点威胁着湖畔镇。",h="石堡要塞是一座耸立在赤脊山东部的坚固石制堡垒，曾由暴风城王国建造并驻守。它现已被一支入侵的黑石兽人军队攻陷，成为了他们的前线作战基地，这些兽人军阀正以此为据点威胁着湖畔镇。",kw={"黑石氏族","加塞尔佐格","基沙恩","湖畔镇","莫甘斯","赤脊山","石堡要塞","萨瑞尔祖恩"},ang={["faction:Alliance"]="石堡要塞是暴风城边境防线紧张局势的痛苦缩影；清理其城墙上的敌军对于保护脆弱的湖畔镇居民至关重要。",["race:Human"]="人类守军曾为保卫这些城墙流尽鲜血，解放要塞有助于为那些阵亡的士兵和被黑石氏族俘虏的人们复仇。"},sec={{t="沦陷的壁垒",b="Stonewatch Keep originally defended the eastern ridges and guarded the settlers of Lakeshire against hostile incursions. That peace shattered when the renegade warlock Morganth struck an alliance with the Blackrock clan. Bolstered by dark magic, the orcs stormed the fortress with vicious ferocity, overwhelming the human defenders and taking the keep for themselves. Although Morganth later abandoned his allies to raise the nearby Tower of Ilgalar and subjugate local gnolls, the Blackrock invaders successfully consolidated their grip over Stonewatch, transforming a former bastion of the Alliance into a fortified staging ground for their assault on the valley."},{t="军阀的王座",b="要塞现已被大量的黑石兽人守军占据，由强大的兽人军阀加塞尔佐格和其残暴的副官萨瑞尔祖恩共同把守。这些指挥官站在石墙之上协调着对赤脊山的突袭，抓捕了包括暴风城的基沙恩下士在内的俘虏。由于王国的军队兵力不足，无法派遣整支军团来解放这座要塞，所罗门镇长和治安官马瑞斯被迫雇佣佣兵勇士潜入堡垒，在湖畔镇彻底沦陷之前铲除这些黑石氏族的领导层。"}},faq={{q="现在是谁占领了石堡要塞？",a="这座要塞目前由黑石氏族占领，由军阀加塞尔佐格及其副官萨瑞尔祖恩现场指挥。在被占领之前，它曾是保卫湖畔镇的联盟据点。",al={"谁控制着石堡要塞","谁住在石堡要塞","石堡要塞的敌人"}},{q="黑石兽人是如何攻占这座要塞的？",a="黑石氏族与背叛的人类术士莫甘斯结盟。在莫甘斯黑暗巫术的加持下，兽人发动了凶猛的突袭，击溃了驻守在石堡的人类守军。",al={"兽人是如何得到石堡的","石堡要塞的陷落","石堡为何陷落"}},{q="为什么暴风城军队不夺回石堡要塞？",a="由于内部政治问题和王国各地的兵力短缺，暴风城军队在很大程度上忽略了赤脊山。因此，湖畔镇的领导人们必须依赖独立的冒险者来应对威胁。",al={"为何没有暴风城军队","守卫在哪里","湖畔镇的军事援助"}},{q="莫甘斯与这座堡垒有什么关联？",a="莫甘斯曾帮助黑石氏族征服了石堡要塞，但在胜利后不久便背叛了他们。他搬去建造了自己的巢穴——伊尔加拉之塔，并利用受过魔法控制的影皮豺狼人而非兽人来为他效力。",al={"莫甘斯与石堡","莫甘斯在石堡要塞里吗"}}},fx={["2fd36daf"]={q="什么是石堡要塞？",a="石堡要塞是一座巨大的石砌堡垒，俯瞰赤脊山东北部。它最初由湖畔镇的人类修建并驻守，用来守卫山间通道，曾是王国东部防线的支柱。如今，这里成了入侵的黑石兽人的坚固据点；他们以黑暗巫术和残暴武力夺取了要塞。",al={"什么是石堡","石堡要塞概况","这是什么地方"}},["9c4dac94"]={q="石堡要塞危险吗？",a="它是赤脊山最危险的据点之一。要塞防御森严，盘踞着大批纪律严明的黑石兽人，由军阀加塞尔佐格及其亲信副官萨瑞尔祖恩统领。独自闯入庭院必死无疑；若要攻下这里，必须有经验丰富的冒险者准备迎战持续不断的残酷战斗。",al={"石堡有多危险","石堡要塞安全吗","石堡要塞的危险"}}},fp="15,277,16.665.0,18.585.0,35.214.0,44.202.0,54.219.0,47.240.0"}
P.entries["subzone:stonewatch-tower"] = {n="石堡高塔",s="石堡高塔是一座屹立在赤脊山东北部被占领的石堡要塞之中的石质岗哨。这座前哨站曾由湖畔镇的守军负责维护，后来被黑石氏族夺取，用以监视周边山脊并巩固他们的山中堡垒。",h="石堡高塔是一座屹立在赤脊山东北部被占领的石堡要塞之中的石质岗哨。这座前哨站曾由湖畔镇的守军负责维护，后来被黑石氏族夺取，用以监视周边山脊并巩固他们的山中堡垒。",kw={"黑石氏族","加塞尔佐格","湖畔镇","赤脊山","侦察塔","石堡","石堡高塔"},ang={["faction:Alliance"]="石堡高塔是一个冷酷的提醒，展示了在暴风城王国的中央军队缺席时，黑石氏族已经深入渗透到了何种程度。",["race:Human"]="对于湖畔镇的居民来说，看到兽人的旗帜在石堡的塔楼上飘扬，是他们生存所面临的持续威胁。"},sec={{t="陷落的岗哨",b="石堡高塔由暴风城王国建造，旨在守护止水湖上方的高海拔山口，是作为石堡要塞的前哨侦察点而存在的。从这座高处的制高点，哨兵可以轻易监视东部的山脊，并向湖畔镇预警任何从燃烧平原逼近的威胁。当加塞尔佐格督军麾下的黑石兽人从高处俯冲而下，击溃人类守军并将这座要塞据为己有时，那套早期预警网络便随之瓦解了。如今，这座塔楼里布满了黑石哨兵，确保没有任何联盟侦察兵能在不被发现的情况下接近要塞。"}},faq={{q="石堡高塔是什么？",a="它是一座位于赤脊山脉东北部，更大的石堡区域内的人类设防岗哨。它最初是为了保护该地区而建造的，目前被来自黑石氏族的入侵者所控制。",al={"石堡高塔背景故事","这座塔是什么","石堡了望台"}},{q="目前是谁控制着石堡高塔？",a="这座塔楼被加塞尔佐格督军麾下的黑石氏族兽人所占据，他们从当地赤脊山人类手中夺取了这座要塞。",al={"谁拥有石堡高塔","谁在石堡高塔里","石堡高塔的敌人"}},{q="为什么这座塔对黑石兽人很重要？",a="其高海拔的地势使黑石氏族能够侦察到逼近的联盟军队，并保护他们主要堡垒——石堡要塞的进出通道。",al={"兽人为什么想要石堡高塔","石堡高塔的战略重要性"}},{q="湖畔镇能收复这座塔吗？",a="湖畔镇缺乏足够的军事人力来独自夺回石堡，因此只能依靠流浪的冒险者来削减占据塔楼和要塞的黑石守军。",al={"湖畔镇会收复它吗","湖畔镇针对石堡高塔的计划"}}},fx={["84e56e26"]={q="石堡高塔发生了什么？",a="这座侦察塔最初由湖畔镇的人类修建，是石堡大要塞的一部分，曾守卫赤脊山东部地区。然而，黑石兽人推进到此地后，守军被击溃。在军阀加塞尔佐格的指挥下，兽人夺取了高塔和相邻的要塞，将湖畔镇昔日的瞭望据点变成了对付王国的前哨。",al={"石堡高塔的历史","石堡高塔发生了什么","兽人是如何夺取石堡高塔的"}},["7b29287c"]={q="石堡高塔危险吗？",a="极其危险。黑石氏族在高塔驻扎了大批兵力，将它作为前沿哨站，牢牢扼守在石堡要塞的阴影之下。任何没有强大援军便靠近的旅人，很快就会被奉加塞尔佐格之命行事的老练兽人战士包围。",al={"石堡高塔的危险","石堡高塔有多危险","石堡高塔安全吗"}}},fp="16,281,18.624.0,25.214.0,40.149.0,49.151.0,32.168.0"}
P.entries["subzone:stonewrought-dam"] = {n="巨石水坝",s="巨石水坝是一座巨大的矮人工程奇迹，矗立在洛克莫丹的北缘。它拦截了洛克湖的水流，形成了巨大的高地湖泊，同时也使下方的湿地排水，变成了适宜居住的沼泽。",h="巨石水坝是一座巨大的矮人工程奇迹，矗立在洛克莫丹的北缘。它拦截了洛克湖的水流，形成了巨大的高地湖泊，同时也使下方的湿地排水，变成了适宜居住的沼泽。",kw={"黑铁矮人","弗兰克罗恩·铸铁","辛德维尔","洛克莫丹","巨石水坝","洛克湖","湿地"},ang={["profession:Engineering"]="对于任何派系的工程师来说，这座水坝都是水力控制和巨石承重力学的经典之作，甚至可以媲美铁炉堡地下的伟大工程。",["race:Dwarf"]="这座水坝是古代矮人砖石建筑和建筑独创性的丰碑，尽管其黑铁传承在铁炉堡的历史学家中仍然是一个令人不快且备受争议的话题。"},sec={{t="矮人技艺的奇迹",b="巨石水坝横跨丹奥加兹以东的峡谷，被广泛认为是矮人文明最伟大的结构性成就之一。这座屏障由黑铁建筑大师弗兰克罗恩·铸铁设计，采用了他开创性的巨石构造技术建造而成。通过拦截山谷盆地的水流，这座水坝使洛克湖的表面积增加了一倍，同时稳步降低了北方的水位，使湿地的沼泽盆地从曾经完全被淹没的山谷中显现出来。"},{t="破坏与防御",b="尽管是在黑铁建筑师的指导下建造的，但这座水坝如今服务于铁炉堡——并且已经成为从南方山区活动的黑铁破坏者们的主要目标。近期的袭击和渗透企图迫使铁炉堡在主工程师辛德维尔七世的指挥下在此驻扎了一支卫戍部队。卫兵和工程师日夜巡逻着这些砖石建筑，因为他们知道，任何缺口都会导致洛克湖的水灾难性地流失，并对下方的湿地造成毁灭性的洪水。"}},faq={{q="是谁建造了巨石水坝？",a="它是由著名的黑铁建筑师弗兰克罗恩·铸铁设计并监造的，他发明了巨石构造技术。虽然是由黑铁大师建造，但它如今服务于铜须王国。",al={"谁建造了巨石水坝","水坝的创造者","水坝建筑师"}},{q="如果水坝决堤会发生什么？",a="坍塌将是灾难性的。洛克湖会迅速干涸，使洛克莫丹留下一片空荡荡的泥坑，而排出的水则会像一场无法控制的毁灭性洪水一样席卷下方的湿地。",al={"如果水坝决堤","水坝决堤会怎样","水坝被毁"}},{q="为什么黑铁矮人要攻击它？",a="黑铁氏族试图打击铁炉堡的重要基础设施并破坏该地区的稳定。毁坏水坝将瘫痪补给线，淹没北部湿地，并对铜须矮人的自尊心造成沉重打击。",al={"为什么要攻击水坝","黑铁矮人攻击水坝"}},{q="目前是谁负责水坝的防御？",a="主工程师辛德维尔七世负责管理水坝的日常运作和防御工事，并与铁炉堡的部队协调以清除破坏者。",al={"谁在管理水坝","水坝工程师"}}},fx={["721eb9b8"]={q="什么是巨石水坝？",a="巨石水坝是一项宏伟的矮人奇迹，坐落在洛克莫丹北缘，丹奥加兹山口以东。它拦住了巨大的湖泊，大幅扩展了湖面的面积，同时调节流向下方湿地的水道。它被誉为世界上最伟大的建筑奇观之一，是古代矮人工程技艺的不朽丰碑。",al={"什么是巨石水坝","关于巨石水坝","巨石水坝传说"}},b3d97da7={q="巨石水坝有着怎样的历史？",a="这座水坝由才华横溢的黑铁建筑师弗兰克罗恩·铸铁设计并监督建造。在黑铁氏族堕入黑暗之前，他开创了革命性的建造技艺。他的宏伟设计使洛克莫丹的蓄水量翻倍，并帮助排干湿地的沼泽盆地。水坝建于久远年代，当时各方尚且团结；如今，黑铁破坏者企图摧毁它，这里已成为激烈冲突的前线。",al={"巨石水坝的历史","水坝的历史","巨石水坝发生了什么"}},a124034a={q="巨石水坝危险吗？",a="水坝本身坚固牢靠，但周边危机四伏。黑铁矮人潜入者和破坏者在水坝侧翼及隧道中潜行，携带炸药和黑暗魔法，企图炸开坝墙。联盟部队和铁炉堡卫兵疲于应付不断发生的破坏行动，准备不足的旅人在坝顶周边行走会十分危险。",al={"巨石水坝危险吗","水坝安全吗","巨石水坝的威胁"}},e9d9cbd5={q="为什么叫巨石水坝？",a="水坝的名字源自“巨石砌筑”工法。这是一种先进的矮人石工与建筑技艺，由水坝的首席建造师弗兰克罗恩·铸铁发明。这种工法精确而坚韧，使巨大的坝墙历经世代仍能承受巨大的水压。",al={"为什么叫巨石水坝","巨石水坝名称的含义","巨石名称的由来"}}},fp="16,239,25.518.0,20.490.0,31.218.0,31.209.0,39.225.0,48.162.0"}
P.entries["subzone:stonewrought-pass"] = {n="石坝小径",s="石坝小径是一条直接穿过洛克莫丹南部群山，通往灼热峡谷荒芜之地的地下隧道。这条通道由著名建筑师弗兰克罗恩·铸铁精心设计，将国王谷与尘火谷直接相连。沉重的铁门封锁了两端，以保护和平的矮人领地免受南部火山恐怖生物的侵扰。",h="石坝小径是一条直接穿过洛克莫丹南部群山，通往灼热峡谷荒芜之地的地下隧道。这条通道由著名建筑师弗兰克罗恩·铸铁精心设计，将国王谷与尘火谷直接相连。沉重的铁门封锁了两端，以保护和平的矮人领地免受南部火山恐怖生物的侵扰。",kw={"尘火谷","弗兰克罗恩·铸铁","洛克莫丹","贝波蒂","灼热峡谷","石坝小径","国王谷"},ang={["faction:Alliance"]="在矮人巡山人的守卫下，这条封闭的通道保护着洛克莫丹脆弱的定居点，使其免受灼热峡谷中滋生的火山威胁。",["race:Dwarf"]="这条隧道是弗兰克罗恩·铸铁工程才华的证明，尽管它现在紧邻着你们那些误入歧途的黑铁矮人同胞所征服的阴森领土。"},sec={{t="石中雕琢的门户",b="石坝小径由传奇建筑大师弗兰克罗恩·铸铁（也因宏伟的巨石水坝而闻名）从基岩中雕琢而成，它是连接洛克莫丹田园美景与灼热峡谷焦土荒原的直接通道。它在洛克莫丹的巨大国王谷附近出现，径直穿过山脊，一直延伸到尘火谷。由于灼热峡谷中充斥着黑铁矮人和火元素生物，铁炉堡的巡山人将这条通道用沉重的铁门严密封锁，以防止危险蔓延至北方。"}},faq={{q="石坝小径通往哪里？",a="这条小径直接穿过山脉，将洛克莫丹南缘的国王谷与灼热峡谷北部的尘火谷连接起来。",al={"石坝小径通向何处","隧道连接","灼热峡谷至洛克莫丹"}},{q="是谁设计了这条隧道？",a="它由矮人建筑大师弗兰克罗恩·铸铁设计。这位传奇工匠因设计了巨石水坝和其他宏伟的石构建筑而在卡兹莫丹备受赞誉。",al={"谁建造了石坝小径","小径的设计师","弗兰克罗恩·铸铁隧道"}},{q="为什么要锁住大门？",a="大门两侧均有重兵把守，旨在阻止灼热峡谷中的火元素怪物和敌对的黑铁矮人入侵洛克莫丹的居住区。巡山人贝波蒂守卫着洛克莫丹的入口，需要获得授权后才会放行。",al={"锁闭的大门","为何小径会被锁住","如何开启大门"}}},fp="17,396,25.591.0,38.181.0,25.190.0,25.272.0"}
P.entries["subzone:stormrage-barrow-dens"] = {n="怒风兽穴",s="怒风兽穴是一处古老的地下圣所，开凿在月光林地那片神圣的山谷之下。此处以玛法里奥·怒风的名字命名，这些安静的土制墓穴是德鲁伊们的专属休憩地，他们在此进行漫长而恢复元气的沉睡，以此游历翡翠梦境。",h="怒风兽穴是一处古老的地下圣所，开凿在月光林地那片神圣的山谷之下。此处以玛法里奥·怒风的名字命名，这些安静的土制墓穴是德鲁伊们的专属休憩地，他们在此进行漫长而恢复元气的沉睡，以此游历翡翠梦境。",kw={"兽穴","塞纳里奥议会","clintar dreamwalker","翡翠梦境","玛法里奥","月光林地","怒风兽穴"},ang={["class:Druid"]="对于两个种族的德鲁伊来说，怒风兽穴代表了塞纳里奥传统的圣地核心，展示了资深修行者往返于艾泽拉斯和翡翠梦境之间的传统地下庇护所。",["race:NightElf"]="这个空洞对卡多雷来说具有深远的历史意义，它铭记了他们沉睡者长达数千年的守护，也铭记了泰兰德·语风为对抗燃烧军团而深入地底唤醒玛法里奥·怒风的危险旅程。"},sec={{t="沉睡者之室",b="兽穴是遍布暗夜精灵领地的神圣避难所，为德鲁伊们提供了一个安全的地下栖身之所。当他们沉浸在翡翠梦境中时，肉身可以不受打扰地在此安息。怒风兽穴在神圣的月光林地中尤受尊崇。为了纪念大德鲁伊玛法里奥·怒风，这里以其名字命名，这些蜿蜒的土制大厅不仅蕴含着古老的敬意，还静静地守护着这里。虽然像Clintar Dreamwalker这样的一些德鲁伊仍然安全地在壁龛中沉睡，但那位伟大大德鲁伊本人的缺席，在空洞的根须和宁静的荧光灯笼上投下了阴郁的阴影。"},{t="第三次战争的回响",b="在第三次战争那段绝望的日子里，这些兽穴濒临彻底毁灭。恐惧魔王提克迪奥斯和燃烧军团的势力试图在沉睡的德鲁伊们集结之前将他们铲除。大祭司泰兰德·语风一路奋战，杀穿了入侵的恶魔和充满敌意的腐化生物，深入这些土制隧道，吹响了塞纳留斯之角，及时唤醒了玛法里奥·怒风。自从阿克蒙德在海加尔山战败后，玛法里奥的灵魂再次飘入了翡翠梦境，留下他的同胞守护着这些神圣的地下深处。"}},faq={{q="怒风兽穴的作用是什么？",a="兽穴为暗夜精灵德鲁伊提供了受保护的、宁静的地下圣所。当他们的心智和灵魂漫游在翡翠梦境的广阔路径时，他们的肉身会在数月甚至数年内保持静止且毫无防备，因此需要一个安静而隐蔽的休憩处，以便在同胞的守护下安全地休息。",al={"兽穴的用途","为什么要再兽穴中睡觉","怒风兽穴的目的"}},{q="玛法里奥·怒风现在在这些兽穴里吗？",a="在第三次战争期间，玛法里奥·怒风曾在兽穴中休息，后来被泰兰德·语风唤醒。战后，他的灵魂一直迷失在翡翠梦境中，而塞纳里奥议会则在没有他的情况下继续运作。",al={"玛法里奥在哪里","玛法里奥在兽穴里吗","我能在这里找到玛法里奥吗"}},{q="现在有谁在这些兽穴中沉睡？",a="在兽穴中休息的德鲁伊包括Clintar Dreamwalker，他正躺在地下深处做着梦，而他的灵魂则穿梭在自然的空灵路径中。",al={"谁在这里睡觉","clintar dreamwalker","月光林地的沉睡德鲁伊"}},{q="在第三次战争期间这里发生了什么？",a="在第三次战争期间，恐惧魔王提克迪奥斯和燃烧军团的恶魔势力入侵了兽穴，企图屠杀沉睡的暗夜精灵德鲁伊。大祭司泰兰德·语风率领突击队深入地底，奋战穿过恶魔势力，吹响了塞纳留斯之角并唤醒了玛法里奥·怒风。",al={"第三次战争与兽穴","提克迪奥斯袭击月光林地","泰兰德唤醒怒风"}}},fp="21,283,26.620.0,23.589.0,49.330.0,51.218.0,44.189.0,49.326.0"}
P.entries["subzone:stormwind-city"] = {n="暴风城",s="暴风城是暴风王国的雄伟首都，也是联盟的军事与政治中心。它在第一次战争中被摧毁，随后在废墟上重建，如今已成为北方诸王国沦陷后，艾泽拉斯人类势力最强大的堡垒。",h="暴风城是暴风王国的雄伟首都，也是联盟的军事与政治中心。它在第一次战争中被摧毁，随后在废墟上重建，如今已成为北方诸王国沦陷后，艾泽拉斯人类势力最强大的堡垒。",kw={"联盟","安度因","伯瓦尔","艾尔文","第一次战争","石匠工会","暴风城","乌瑞恩"},ang={["faction:Alliance"]="暴风城是联盟在东部王国南部的首要军事、海军和精神集结地，迎接并包容着矮人、侏儒和暗夜精灵的使节。",["race:Human"]="对于全艾泽拉斯的人类而言，暴风城的白色城墙代表了坚韧、生存，以及在北方诸王国覆灭后，人类文明依然存续的荣耀。"},sec={{t="浴火重生的灯塔",b="一千多年前，阿拉索的后裔向南迁徙，建立了暴风城。它曾是一座充满活力的沿海都城，四周环绕着坚固的石墙，因湍急的河流推动的水磨坊而繁荣。然而，这种辉煌在第一次战争中戛然而止：兽人部落围攻了这座城市，攻破了防御，并将其付之一炬。安度因·洛萨爵士被迫率领幸存的难民渡过无尽之海，逃往洛丹伦。在联盟于第二次战争中获胜后，石匠工会承担了重建首都的艰巨任务，将其打造为如今坐落在艾尔文森林北部的这座闪耀的要塞。它由白色石材筑成，拥有错综复杂的运河网络和高耸入云的尖塔。"},{t="联盟的心脏",b="随着洛丹伦被天灾军团摧毁，达拉然也在第三次战争中受到重创，暴风城成为了人类主要的避难所和据点。暴风城卫兵在宽阔的街道和防御墙上巡逻，维持治安；而位于城中的Cathedral of Light的尖塔则在南方诸王国传播着信仰与奉献。然而，在这秩序井然的城区和庄严的城门之下，却暗流涌动：瓦里安·乌瑞恩国王离奇失踪，留下年幼的儿子安度因在摄政王伯瓦尔·弗塔根公爵的辅佐下登基，并受到皇家顾问女伯爵卡特拉娜·普瑞斯托的耳语教唆。"}},faq={{q="为什么暴风城在第一次战争后要重建？",a="暴风城在第一次战争期间被兽人部落攻陷并焚毁。在洛丹伦联盟于第二次战争击败兽人后，人类难民收复了他们祖先的王国。皇家法庭委托石匠工会，在原来的废墟之上建造了一座更宏伟的堡垒之城。",al={"谁重建了暴风城","暴风城的重建","为什么暴风城看起来很新"}},{q="目前谁在统治暴风城？",a="名义上，在父亲瓦里安·乌瑞恩国王突然且毫无预兆地失踪后，少年国王安度因·乌瑞恩登上了王位。由于安度因尚且年幼，真正的治理权力掌握在摄政王兼王国防御指挥官——伯瓦尔·弗塔根公爵手中。",al={"谁是暴风城国王","谁在管理暴风城","暴风城现任统治者"}},{q="为什么暴风城是主要的人类首都，而不是洛丹伦？",a="在第三次战争期间，北方的洛丹伦王国在亡灵瘟疫和天灾军团的内部侵蚀下彻底覆灭。随着洛丹伦的毁灭和其他北方人类王国的满目疮痍，暴风城成为了艾泽拉斯仅存的、最富庶、最完好且人口最稠密的人类王国。",al={"洛丹伦发生了什么","为什么不是洛丹伦作为首都","暴风城是最后的城市吗"}},{q="哪些军事力量保护着这座城市？",a="城区内和城墙上的治安由暴风城卫兵维护。更大范围的领土防御和皇室保护则由王国的骑士、Stormwind Keep的驻军以及隶属于圣光教会的圣骑士们负责。",al={"谁在守卫暴风城","暴风城军队","城市卫兵"}}},fx={["209accb7"]={q="什么是暴风城？",a="暴风城是暴风王国的首都，也是艾泽拉斯现存最强大的人类堡垒。它坐落在艾尔文森林以北的西海岸，是联盟的心脏。高耸的白石城墙和深邃的运河之内，坐落着繁荣的商业区、王权中心，以及圣光大教堂——一座为所有敬奉圣光者指引方向的信仰灯塔。",al={"什么是暴风城","暴风城概况","关于暴风城"}},["38604972"]={q="暴风城发生过什么？",a="一千多年前，阿拉希人的后裔建立了暴风城。此后，暴风城历经豺狼人战争和巨魔袭击，直到第一次战争中遭到彻底毁灭。兽人部落围攻这座都城，攻破防线并将其夷为平地，幸存者被迫渡海北逃。联盟在第二次战争中获胜后，石匠公会艰苦重建了这座城市，使其成为今日这座雄伟的要塞。",al={"暴风城历史","暴风城发生了什么","暴风城的陷落"}},["7f858f77"]={q="暴风城危险吗？",a="在城墙之内，暴风城是王国中最安全的聚居地之一，时刻有警惕的暴风城卫兵巡逻。不过，这里并非绝对太平。Old Town的小巷等阴暗角落潜藏着阴影，王室朝廷暗流涌动，王国周边的领土仍受到歹徒和不断逼近的怪物威胁。",al={"暴风城安全吗","暴风城危险吗","暴风城面临的威胁"}}},fp="14,298,16.651.0,21.636.0,46.327.0,35.292.0,61.301.0,38.284.0"}
P.entries["subzone:stormwind-gate"] = {n="Stormwind Gate",s="Stormwind Gate是连接艾尔文森林与暴风城之间宏伟的防御性入口。这道关口时刻都有皇家卫兵守卫，是宁静森林与宏大的英雄谷之间的主要界限。",h="Stormwind Gate是连接艾尔文森林与暴风城之间宏伟的防御性入口。这道关口时刻都有皇家卫兵守卫，是宁静森林与宏大的英雄谷之间的主要界限。",kw={"艾尔文森林","闪金镇","暴风城卫兵","stormwind gate","英雄谷"},ang={["faction:Alliance"]="这道大门象征着大联盟的安全与坚韧，是远征归来的士兵和年轻冒险者眼中展现威严的第一幕。",["race:Human"]="对于暴风城的民众来说，穿过这些石拱门意味着在穿越艾尔文森林及更远的地方经历漫长旅程后，终于回到了安全的家中。"},sec={{t="王国的门槛",b="Stormwind Gate高耸于艾尔文森林的南侧道路上，既是首都的防御工事，也是礼仪性的大门。暴风城卫兵的哨兵们时刻注视着这座石质门户，守卫着从森林通往城内的通道，同时正规巡逻队在外部拱门和英雄谷之间行进。尽管艾尔文森林各地仍有动荡，但这道巨大的铁石大门始终敞开，欢迎旅行者、商人和归来的守卫进入联盟的心脏。"}},faq={{q="Stormwind Gate通向哪里？",a="从艾尔文森林穿过大门，你将直接进入英雄谷，这是通往暴风城的宏伟入口，两旁矗立着第二次战争中英雄们的雕像。",al={"stormwind gate通向哪里","大门后面是什么","暴风城入口"}},{q="如果艾尔文森林很危险，为什么大门始终敞开？",a="暴风城的繁荣依赖于开放的贸易以及来自闪金镇和整个联盟的稳定通行。尽管周边森林中存在强盗和迪菲亚兄弟会的威胁，但暴风城选择派遣警惕的守卫驻守通道，而不是将自己的市民和商业拒之门外。",al={"为什么大门是开着的","stormwind gate是关闭的吗","为什么敞开"}},{q="是谁在守卫大门？",a="这个入口由暴风城卫兵驻守。两名哨兵在艾尔文森林外侧站岗，另外两名守卫着内侧通道，还有武装步兵在通往英雄谷的桥上巡逻。",al={"stormwind gate守卫","谁保卫大门"}},{q="大门处会举行特殊活动吗？",a="是的。Stormwind Gate周围的开阔地带经常举办联盟重大的城市节日和季节性聚会，作为拥挤街区之外的开放集会场所。",al={"stormwind gate的节日","大门处的活动"}}},fx={c23a16f5={q="Stormwind Gate危险吗？",a="对联盟成员来说并不危险。城门戒备森严，暴风城卫兵在门内外以及相邻的英雄谷巡逻。不过，敌方潜入者或部落旅客几乎不可能闯过这里，因为驻守的哨兵一旦发现王国的敌人，就会立即发起攻击。",al={"城门安全吗","暴风城城门危险吗","暴风城城门安全吗"}}},fp="14,246,28.536.0,35.176.0,56.267.0,21.226.0,42.193.0"}
P.entries["subzone:stormwind-keep"] = {n="Stormwind Keep",s="Stormwind Keep 巍然耸立于首都之上，是暴风王国的石制堡垒和权力中心。它在第一次战争中被毁后重建，目前是年幼的国王安度因·乌瑞恩和他的摄政王伯瓦尔·弗塔根公爵的皇室庭院所在地。",h="Stormwind Keep 巍然耸立于首都之上，是暴风王国的石制堡垒和权力中心。它在第一次战争中被毁后重建，目前是年幼的国王安度因·乌瑞恩和他的摄政王伯瓦尔·弗塔根公爵的皇室庭院所在地。",kw={"安度因·乌瑞恩国王","bolvar fordragon","暴风城城堡","卡特拉娜·普瑞斯托","royal library","stormwind keep","王座大厅","war room"},ang={["faction:Alliance"]="这座要塞是联盟东方军事指挥中心的心脏，伯瓦尔·弗塔根公爵和元帅们在此指挥防御，抵御来自艾尔文森林、西部荒野及更远地区的不断威胁。",["race:Human"]="这座堡垒在第一次战争的浩劫后从灰烬中重建，见证了暴风城人民的韧性和自豪。"},sec={{t="重建的要塞",b="Stormwind Keep 坐落于俯瞰整座城市的高原之上，既是宫殿也是军事堡垒。在第一次战争末期，莱恩国王被刺杀后，最初的要塞被旧部落烧成了平地。联盟收复王国后，这座要塞在旧地基上拔地而起，重建后的要塞不仅拥有宏伟的王座大厅和 War Room，还拥有宁静的庭院和广阔的 Royal Library。"},{t="分裂的宫廷",b="在这座要塞的旗帜和打磨光滑的石墙背后，隐藏着不安的和平。瓦里安·乌瑞恩国王在前往塞拉摩参加外交峰会的途中神秘失踪，治理国家的重任落在了十岁的安度因·乌瑞恩国王肩上。实际的统治权掌握在伯瓦尔·弗塔根公爵和贵族女伯爵卡特拉娜·普瑞斯托手中。虽然伯瓦尔负责防御和军事事务，但宫廷政治却因贵族内斗而陷入瘫痪，导致外围领土极其脆弱，王室也深陷混乱。"}},faq={{q="现在是谁在统治 Stormwind Keep？",a="安度因·乌瑞恩国王在名义上拥有王位，但由于他年仅十岁，因此由伯瓦尔·弗塔根公爵担任摄政王，并与作为皇家顾问的女伯爵卡特拉娜·普瑞斯托共同治理国家。",al={"谁在负责","谁领导暴风城","谁是国王"}},{q="瓦里安·乌瑞恩国王发生了什么事？",a="瓦里安国王在穿越海洋前往塞拉摩参加和平会议的途中神秘失踪。他突然失踪导致王位空缺，迫使伯瓦尔和宫廷为确保政治稳定而加冕年幼的安度因。",al={"瓦里安在哪里","瓦里安失踪","国王发生了什么"}},{q="这座要塞在第一次战争中被摧毁了吗？",a="是的。在迦罗娜谋杀莱恩·乌瑞恩国王后，旧部落压倒了城市并彻底夷平了这座要塞。目前的堡垒是在第二次战争中联盟取得胜利后，在古老的地基上重建的。",al={"兽人摧毁了要塞吗","第一次战争城堡破坏"}},{q="要塞内可以参观哪些主要区域？",a="该建筑群包含主王座大厅、其后方的 War Room、用于接见请愿者的 Petitioner's Chamber、开放式花园庭院、Royal Gallery 和 Royal Library。",al={"要塞房间","要塞里有什么","stormwind keep 的侧厅"}}},fx={["3e1bbfc4"]={q="Stormwind Keep是什么地方？",a="Stormwind Keep是人类王国暴风城的宏伟堡垒，也是权力中心。这座要塞俯瞰整座城市，既是王宫，也是王国政府的核心。走进坚固的石墙之内，可以看到王室朝廷、王座厅、供请愿者使用的接见厅、Royal Library、宁静的内庭花园，以及城堡精锐亲卫的营房。",al={"stormwind keep是什么","stormwind keep的用途","stormwind keep简介"}},a781e02c={q="Stormwind Keep危险吗？",a="对忠诚的臣民和联盟盟友而言，Stormwind Keep是世界上最安全的庇护所之一。这里驻扎着大批精锐王室卫兵和王冠守护者，时刻防范外部威胁。然而，平静的宫廷生活之下暗藏微妙的政治角力，贵族派系和王室顾问争相影响年轻的国王，而王国各地的动荡也日益加剧。",al={"stormwind keep危险吗","stormwind keep安全吗","要塞会敌对吗"}}},fp="14,269,19.466.0,15.482.1,38.178.0,35.249.0,40.232.0,48.194.0"}
P.entries["subzone:stormwind-stockade"] = {n="暴风城监狱",s="监狱隐藏在法师区北侧的运河下方，是暴风城戒备森严的惩戒所。这座地下堡垒原本用于关押杀人犯、政治异见者和外国敌对势力，但近期由于一场有组织的囚犯暴动，已经彻底陷入混乱之中。",h="监狱隐藏在法师区北侧的运河下方，是暴风城戒备森严的惩戒所。这座地下堡垒原本用于关押杀人犯、政治异见者和外国敌对势力，但近期由于一场有组织的囚犯暴动，已经彻底陷入混乱之中。",kw={"巴基尔·斯瑞德","运河","迪菲亚","迪克斯特·瓦德","卡姆·深怒","监狱","暴乱","暴风城","塔格尔","典狱官塞尔沃特"},ang={["class:Rogue"]="这场暴乱揭开了迪菲亚潜行者和巴基尔·斯瑞德的运作内幕，让人得以一窥这个犯罪黑社会在王权眼皮底下组织得有多么严密。",["faction:Alliance"]="监狱直接位于首都，因此平定监狱对民防至关重要；清理其大厅可以暴露迪菲亚潜行者渗透暴风城的程度有多深。"},sec={{t="围城中的监狱",b="监狱通常由典狱官塞尔沃特负责管理，王国会将最危险的囚犯关押于此，从亡命之徒和迪菲亚潜行者，到被俘获的黑石兽人和黑铁矮人，应有尽有。然而，狡诈的迪菲亚阴谋家巴基尔·斯瑞德策划了一场暴力起义，彻底取代了监狱看守。囚犯们现在在下层牢房中横行，将这里变成了一座暴乱的堡垒。塞尔沃特在勉强守住入口关卡后，只能指望独立冒险者们深入地下走廊，在暴乱蔓延到运河区之前平息这场叛乱。"},{t="官僚主义与幕后阴谋",b="监狱关押的不仅仅是普通的街头罪犯；长期以来，它一直是王国腐败的贵族议会手中的谈判筹码。那些在其他地方被判处死刑的杀人犯和高价值囚犯——例如来自暮色森林的盗墓贼迪克斯特·瓦德，或来自赤脊山的黑石行刑者可怕的塔格尔——由于贵族阶层的干预，他们的死刑被推迟执行，沦为政治傀儡。甚至邻近的铁炉堡也注意到了这一点，当人类官僚主义阻碍了正当的审判时，他们会秘密雇佣雇佣兵去处决像卡姆·深怒这样危险的囚犯。"}},faq={{q="监狱的入口在哪里？",a="入口位于暴风城的运河区，就在通往法师区的桥梁旁，隐藏在北侧的弯道处。一个有守卫把守的门口通往一条向下的石阶，直达地下牢房。",al={"监狱入口","如何进入监狱","监狱位置"}},{q="是谁引发了监狱里的暴乱？",a="这场叛乱是由关押在监狱中的迪菲亚潜行者高级头目巴基尔·斯瑞德策划并点燃的。在他的指挥下，囚犯们压制了守卫，夺取了武器，并完全控制了地下牢房区。",al={"巴基尔·斯瑞德是谁","谁领导了监狱暴乱","谁管理监狱"}},{q="为什么暴风城的监狱里会有兽人和黑铁矮人？",a="暴风城会从其有争议的领土上俘获高优先级敌对目标。值得注意的是，可怕的塔格尔是从赤脊山被抓捕的，而卡姆·深怒则代表了黑铁矮人的威胁。他们没有被迅速处决，而是作为战俘被带到这里，或者因贵族的法令而被保留性命以作为政治筹码。",al={"为什么监狱里有兽人","监狱里的黑铁囚犯"}},{q="为什么暮色森林和赤脊山的人要求人们在这里处决囚犯？",a="像夜色镇和湖畔镇这样的偏远定居点判处了迪克斯特·瓦德和可怕的塔格尔等罪犯死刑，却发现贵族议会中止了他们的处刑。由于对暴风城的官僚干预感到沮丧，地方领袖私下雇佣佣兵来绕过皇家的文书工作，完成任务。",al={"暮色森林监狱任务","罪与罚","因果报应"}}},fx={e9dc0ba3={q="暴风城监狱是什么地方？",a="监狱是位于暴风城运河下方的高戒备地下监牢，由典狱官塞尔沃特管理。这里原本用来关押王国最危险的罪犯，包括杀人犯、政治叛乱者、迪菲亚匪徒，以及等待审判的外国敌对分子。",al={"监狱是什么","暴风城监狱信息"}},d734f0f2={q="暴风城监狱发生过什么？",a="监狱内部爆发了一场由囚犯发动的暴力叛乱，幕后策划者是被捕的迪菲亚首脑巴基尔·斯瑞德。暴动的囚犯制服了狱卒，将卫兵彻底赶出牢房区，并夺取了监狱的控制权。城卫队目前对这场危机严加保密，同时招募佣兵夺回监狱。",al={"监狱里发生了什么","监狱历史","监狱为何发生暴乱"}},["10925a1c"]={q="暴风城监狱危险吗？",a="现在极其危险。囚犯在监狱各处自由活动，无人看管，并在迪菲亚势力的领导下武装起来、组织成队，此外还有亡命之徒、黑石兽人和黑铁潜入者。任何进入的人都必须在无法无天、充满敌意的走廊中一路战斗，卫兵已无法控制这里。",al={"监狱有多危险","监狱危险吗","监狱里的危险"}}},fp="18,322,20.626.0,32.587.1,46.230.0,39.264.0,61.332.0,67.307.0"}
P.entries["subzone:stormwind-stockade-classic"] = {n="Stormwind Stockade (Classic)",s="暴风城监狱是位于暴风城运河区下方的一座加固地下监狱。它最初用于关押轻罪罪犯、暴力雇佣兵和政治颠覆分子，但最近因为一场暴力的囚犯叛乱而陷入了混乱。",h="暴风城监狱是位于暴风城运河区下方的一座加固地下监狱。它最初用于关押轻罪罪犯、暴力雇佣兵和政治颠覆分子，但最近因为一场暴力的囚犯叛乱而陷入了混乱。",kw={"巴基尔·斯瑞德","迪菲亚","迪克斯特·瓦德","卡姆·深怒","监狱","暴风城监狱","可怕的塔格尔","起义","典狱官塞尔沃特"},ang={["faction:Alliance"]="发生在首都街道下方的这场暴动对伯瓦尔·弗塔根公爵的执政当局来说是一种严重的羞辱，暴露出在国王缺席的情况下，暴风城内部竟是如此脆弱。",["race:Human"]="对于边境城镇的人类居民来说，监狱的瘫痪证明了贵族议会更关心首都的法律繁文缛节，而不是保护边境定居点免受谋杀犯的侵害。"},sec={{t="暴动的监狱",b="暴风城监狱隐藏在旧城区和法师区之间的运河旁，是暴风王国的首要惩戒设施。在典狱官塞尔沃特的管理下，这座地下建筑关押着王国里最危险的恶徒：迪菲亚潜行者中的杀手、一名掠夺成性的黑石兽人、一名食人魔，甚至还有一个潜入进来的黑铁矮人。最近，狡猾的罪犯巴基尔·斯瑞德精心策划了一场监狱暴乱，击溃了守卫部队，将幸存的卫兵赶走，使囚犯们完全控制了内部大厅。"},{t="官僚主义与报应",b="监狱内的灾难暴露了暴风城治理中的严重裂痕。许多臭名昭著的囚犯，例如黑石恐怖分子可怕的塔格尔和倒卖尸体的盗墓贼迪克斯特·瓦德，早已被判处死刑，却因有影响力的贵族们不断拖延执行而苟活至今。由于对贵族们的推诿感到愤怒，湖畔镇和夜色镇等周边定居点，连同丹莫德的矮人驻军，完全绕过了王室渠道，直接招募外来的冒险者，趁着混乱潜入并处决关键的首领。"}},faq={{q="暴风城监狱在哪里？",a="暴风城监狱的入口位于暴风城北侧运河岸边，连接着旧城区与大教堂区和法师区之间的通道。",al={"监狱入口","如何前往监狱","监狱位置"}},{q="目前是谁在管理监狱？",a="虽然典狱官塞尔沃特是官方指定的典狱官，但他已在叛乱中被赶走。该设施目前实际上是由挑起暴动的囚犯巴基尔·斯瑞德及其迪菲亚潜行者盟友所控制。",al={"谁在管理监狱","监狱首领","巴基尔·斯瑞德"}},{q="为什么暴风城会关押兽人和黑铁矮人？",a="暴风城在此关押着高价值的战俘和破坏者。可怕的塔格尔是从附近山区抓获的黑石兽人掠夺者，而卡姆·深怒则是一名因进行反联盟颠覆活动而被监禁的敌对黑铁矮人。",al={"为什么监狱里有兽人","卡姆·深怒","可怕的塔格尔"}},{q="为什么那些被判死刑的谋杀犯没有被处决？",a="暴风城高级贵族的官僚主义和政治干预反复拖延了迪克斯特·瓦德和塔格尔等罪犯的处决，引发了赤脊山和暮色森林等外围领地的强烈不满。",al={"为什么他们没有被处决","暴风城贵族","迪克斯特·瓦德的处决"}}},fx={d4f3da71={q="暴风城监狱是什么地方？",a="监狱是建在暴风城运河区下方、戒备森严的高安全级别监牢。它由典狱官塞尔沃特管理，原本用来关押王国中最恶劣的罪犯，从街头小偷和盗墓贼，到政治叛乱者、迪菲亚阴谋分子和冷酷的杀人犯。",al={"监狱是什么","暴风城监狱","监狱介绍"}},["5c482541"]={q="暴风城监狱发生过什么？",a="不久前，监狱牢房内爆发了暴力叛乱，由狡猾的首脑巴基尔·斯瑞德带头策划。暴动的囚犯制服了卫兵，杀害看守，并把典狱官塞尔沃特赶进运河。城卫队被挡在外面后，囚犯夺取了整个监狱的控制权，将地下走廊变成了亡命之徒和阴谋分子的坚固藏身处。",al={"这里发生了什么","监狱暴乱故事","监狱历史"}},b72eefeb={q="暴风城监狱危险吗？",a="这里极其危险。狭窄的石质走廊里挤满了获释的杀人犯、迪菲亚佣兵、凶悍的黑石兽人和黑铁潜入者。囚犯被困在狭小的牢房中，一旦有人进入便会群起袭击；敌对势力冲出监狱、涌入城市运河的风险也仍然威胁着暴风城的安全。",al={"监狱有多危险","监狱安全吗","监狱危险"}}},fp="28,265,18.586.0,27.590.1,30.162.0,36.231.0,64.239.0,60.218.0"}
P.entries["subzone:stoutlager-inn"] = {n="烈酒旅店",s="烈酒旅店是塞尔萨玛热闹的核心，也是洛克湖旅行者的主要避风港。它坐落在洛克湖起伏的丘陵之下，提供温暖的炉火、烈性的矮人麦酒，是冒险者和当地居民熙熙攘攘的聚集地。",h="烈酒旅店是塞尔萨玛热闹的核心，也是洛克湖旅行者的主要避风港。它坐落在洛克湖起伏的丘陵之下，提供温暖的炉火、烈性的矮人麦酒，是冒险者和当地居民熙熙攘攘的聚集地。",kw={"矮人","炉石","旅店老板","洛克莫丹","烈酒旅店","酒馆","塞尔萨玛"},ang={["faction:Alliance"]="这家旅店是联盟冒险者前往北方湿地，或是在洛克湖周围饱受困扰的山谷巡逻时的重要补给站和避风港。",["race:Dwarf"]="对于铜须矮人来说，烈酒旅店体现了熟悉的家园温暖，以纯正的好客、新鲜的麦酒和远离铁炉堡后的可靠陪伴而闻名。"},sec={{t="丘陵中温馨的炉火",b="烈酒旅店位于塞尔萨玛定居点的正中央，是洛克湖西部社区生活的中心。往返于丹莫罗和湿地之间的矿工、登山者和旅行者都会在此驻足，交换传闻、投宿，并分享浓郁的矮人佳酿。虽然塞尔萨玛之外的荒野因穴居人和狗头人的活动而日益险恶，但烈酒旅店那厚实的石墙和熊熊燃烧的炉火提供了一个可靠的避难所。"}},faq={{q="在烈酒旅店可以获得哪些服务？",a="这家旅店提供传统的酒馆设施，包括绑定炉石的旅店老板、为疲惫的旅行者准备的床铺，以及为穿越洛克湖的旅程提供补给和饮品的当地商人。",al={"旅店服务","旅店里有什么","塞尔萨玛旅店老板"}},{q="烈酒旅店位于哪里？",a="它建在塞尔萨玛的中心，这是位于洛克湖西部主干道旁的主要联盟城镇。",al={"旅店位置","烈酒旅店在哪里","寻找烈酒旅店"}},{q="为什么这家旅店对塞尔萨玛如此重要？",a="除了提供食物和住宿外，烈酒旅店还是城镇广场和消息中心。当地的登山者在这里发布悬赏，旅行者则在这里规划前往周边丘陵的探险。",al={"它为什么受欢迎","塞尔萨玛酒馆背景故事"}}},fx={["621b2370"]={q="烈酒旅店是什么地方？",a="烈酒旅店是塞尔萨玛的中心，也是整个洛克莫丹最热闹的聚会场所之一。它为刚走下山路、疲惫不堪的旅人提供温暖亲切的歇脚处，有醇厚的矮人麦酒、热腾腾的食物和炉边舒适的床铺。当地的山地巡行者、矿工和来访的冒险者常聚集在粗壮的木梁之下，分享传闻、计划前往周边山丘的行程，享受远离荒野的融洽时光。",al={"烈酒旅店是什么","烈酒旅店背景","塞尔萨玛的旅店"}},["7e615305"]={q="烈酒旅店危险吗？",a="一点也不危险。烈酒旅店位于塞尔萨玛的中心，是一处安全的庇护所，由当地矮人卫兵和途经此地的山地巡行者严密守护。虽然穴居人、狗头人和凶猛的野兽在洛克莫丹的湖岸与山脊间出没，但旅店本身仍是一处安宁之地，你可以在此休息、喘口气，并将灵魂绑定在炉火旁，不必担心遭到袭击。",al={"烈酒旅店安全吗","烈酒旅店危险吗","塞尔萨玛旅店的威胁"}}},fp="14,255,31.482.0,50.207.0,36.126.0,41.193.0"}
P.entries["subzone:strahnbrad"] = {n="斯坦恩布莱德",s="斯坦恩布莱德是一座破败的人类定居点，坐落在奥特兰克山脉东北部的山地上，毗邻西瘟疫之地。这里曾因阿尔萨斯·米奈希尔王子早期防卫黑石兽人袭击的壮举而闻名，但如今这座城镇已衰败不堪，成为了辛迪加这个犯罪组织的一处坚固据点。",h="斯坦恩布莱德是一座破败的人类定居点，坐落在奥特兰克山脉东北部的山地上，毗邻西瘟疫之地。这里曾因阿尔萨斯·米奈希尔王子早期防卫黑石兽人袭击的壮举而闻名，但如今这座城镇已衰败不堪，成为了辛迪加这个犯罪组织的一处坚固据点。",kw={"奥特兰克","阿尔萨斯","黑石","戈尔迪尔","克鲁斯克","洛丹伦","斯坦恩布莱德","辛迪加"},ang={["class:Paladin"]="漫步在斯坦恩布莱德的鹅卵石路上，让人回想起阿尔萨斯·米奈希尔王子和光明使者乌瑟尔那段早期清白的时光，这苦涩地提醒着人们，洛丹伦的英雄们如今已沦落至何种境地。",["faction:Horde"]="辛迪加对兽人戈尔迪尔的奴役使得斯坦恩布莱德成为了部落勇士们的目标，他们迫切需要打击这些人类强盗并营救自己的同胞。"},sec={{t="悲剧之城",b="斯坦恩布莱德原本属于奥特兰克王国，第二次战争后被并入洛丹伦，其不幸始于第三次战争前夕。黑石氏族的兽人袭击了该定居点，意图将人类作为燃烧军团的祭品。阿尔萨斯·米奈希尔王子和白银之手骑士团骑马赶来支援。尽管阿尔萨斯击退了袭击者并斩杀了他们的奴隶主，但小镇还是血流成河。此后不久，随着洛丹伦在天灾军团的铁蹄下沦陷，斯坦恩布莱德也遭到遗弃，任由风雨侵蚀。"},{t="辛迪加的控制",b="今天，斯坦恩布莱德已成为辛迪加的关键行动中心。辛迪加是由流离失所的奥特兰克贵族和亡命之徒组成的组织，他们密谋夺回沦陷的王国。这里有盗贼和强盗巡逻，废弃的市政厅和铁匠铺成了他们的藏身处和集结地。辛迪加利用这座废墟城镇来存放补给和关押苦工，其中包括不幸的囚犯，比如兽人戈尔迪尔，来自塔伦米尔的部落侦察兵正积极设法营救他。"}},faq={{q="为什么斯坦恩布莱德在历史上很重要？",a="斯坦恩布莱德是阿尔萨斯·米奈希尔王子在第三次战争中的首场交锋地点。受光明使者乌瑟尔之命，阿尔萨斯保卫此定居点免受狂暴黑石兽人的侵扰，他在此完成了自己早期的成名之战，解救了城镇居民并斩杀了兽人袭击者。",al={"为什么斯坦恩布莱德很重要","阿尔萨斯 斯坦恩布莱德","斯坦恩布莱德历史"}},{q="谁现在控制着斯坦恩布莱德？",a="辛迪加控制着斯坦恩布莱德。这些效忠于奥特兰克没落贵族血脉的人类强盗，加固了破败的市政厅和铁匠铺，将其作为在山区扩张势力的主要集结地。",al={"谁占领了斯坦恩布莱德","斯坦恩布莱德怪物","谁住在斯坦恩布莱德"}},{q="斯坦恩布莱德最初属于哪个王国？",a="斯坦恩布莱德在第一次战争前最初属于奥特兰克王国。在奥特兰克于第二次战争期间背叛联盟后，该镇被并入洛丹伦王国的领土。",al={"斯坦恩布莱德属于奥特兰克还是洛丹伦","斯坦恩布莱德所属王国"}},{q="部落为何关注这座城镇？",a="辛迪加俘虏了一名叫做戈尔迪尔的兽人，强迫他在斯坦恩布莱德的废墟中从事残酷的奴隶劳动。来自塔伦米尔的部落特工在克鲁斯克的指挥下，派遣冒险者前往此地突破辛迪加的防线并救出戈尔迪尔。",al={"斯坦恩布莱德部落任务","克鲁斯克 斯坦恩布莱德","戈尔迪尔 斯坦恩布莱德"}}},fx={["8ef7b8bc"]={q="斯坦恩布莱德是什么地方？",a="斯坦恩布莱德是一处废墟，坐落在奥特兰克山脉东北麓，靠近通往西瘟疫之地的山口。它原本是一座人类城镇，先后归属奥特兰克王国和洛丹伦，如今已荒废，街道上不见无辜居民的踪影，只剩危险的歹徒盘踞。",al={"这是什么地方","斯坦恩布莱德概况","介绍一下斯坦恩布莱德"}},e385b772={q="斯坦恩布莱德为何沦为废墟并被遗弃？",a="第三次战争前不久，叛逃的黑石兽人袭击了斯坦恩布莱德，抓捕祭品献给燃烧军团，使这座城镇遭受残酷破坏。阿尔萨斯·米奈希尔王子虽赶来驱逐袭击者，仍有许多镇民丧生。洛丹伦沦陷于天灾军团后，幸存者四散或死去，废弃的建筑随后被强盗占据。",al={"斯坦恩布莱德为何被摧毁","谁摧毁了斯坦恩布莱德","斯坦恩布莱德为何成了鬼城"}},["37fa5a7f"]={q="前往斯坦恩布莱德危险吗？",a="是的，斯坦恩布莱德非常危险。废弃的城镇是辛迪加的活跃据点。辛迪加是由前奥特兰克贵族和歹徒组成的残酷犯罪组织。他们一发现闯入者就会发动袭击，甚至会抓人强迫劳役，因此任何独自在山间经过的旅人都可能遭遇危险。",al={"斯坦恩布莱德安全吗","斯坦恩布莱德有敌对势力吗","斯坦恩布莱德的危险"}}},fp="10,344,17.552.0,20.482.0,41.275.0,28.226.0,50.207.0,40.243.0"}
P.entries["subzone:stratholme"] = {n="斯坦索姆",s="斯坦索姆曾是东威尔的明珠，也是洛丹伦王国第二大城市。在第三次战争期间，这里成为了阿尔萨斯·米奈希尔王子臭名昭著的“净化”行动的现场，起因是城中居民食用了受到亡灵瘟疫污染的谷物。如今，这座废弃的大都市仍在燃烧，成为了天灾军团在洛丹伦北部的主要据点。",h="斯坦索姆曾是东威尔的明珠，也是洛丹伦王国第二大城市。在第三次战争期间，这里成为了阿尔萨斯·米奈希尔王子臭名昭著的“净化”行动的现场，起因是城中居民食用了受到亡灵瘟疫污染的谷物。如今，这座废弃的大都市仍在燃烧，成为了天灾军...",kw={"andorhal","阿尔萨斯","净化","东威尔","玛尔加尼斯","瘟疫之地","天灾军团","白银之手","斯坦索姆","乌瑟尔"},ang={["class:Paladin"]="对于圣骑士而言，斯坦索姆是一片化为悲剧的神圣土地；这里是白银之手骑士团诞生的圣地，也是阿尔萨斯通过下令屠杀无辜平民而粉碎了同一兄弟会的地方。",["faction:Alliance"]="这座废墟之城是洛丹伦陨落的一座令人难忘的纪念碑，提醒着联盟的旅行者们，当北方王国在瘟疫和背叛中崩溃时，他们付出了多么惨痛的代价。"},sec={{t="圣骑士与贸易的摇篮",b="在陷落之前，斯坦索姆曾是北方文明的基石。它于几个世纪前从阿拉希人向东威尔的扩张中兴起，并繁荣发展成为洛丹伦第二大定居点，以其神圣的神殿和能够抵御黑暗魔法的神圣水源而闻名。在第二次战争之前，阿隆苏斯·法奥大主教在城内的礼拜堂聚集了众人，创立了白银之手骑士团，并册封了如光明使者乌瑟尔这样的传奇人物。在整个战争期间，斯坦索姆作为洛丹伦联盟的重要港口、补给中心和北部炼油基地，在经历旧部落的袭击后，又在胜利中重建。"},{t="净化与永恒的废墟",b="当诅咒神教将从安多哈尔运来的一批批受感染谷物送入城内市场时，斯坦索姆的命运就被注定了。毫无察觉的数千名居民食用了这些受污染的面粉。当阿尔萨斯王子与乌瑟尔和吉安娜·普罗德摩尔一同抵达时，他发现瘟疫已经扩散到无法治愈的地步。阿尔萨斯认为屠杀是阻止玛尔加尼斯获得一支军队的唯一途径，于是下令肃清城内所有居民——这一暴行导致乌瑟尔和吉安娜离他而去，也开启了王子堕落入疯狂的序幕。城市随后被付之一炬，此后，天灾军团进驻了这片烟雾弥漫的废墟，将其改造成了他们的区域首府。"}},faq={{q="为什么斯坦索姆还在燃烧？",a="当阿尔萨斯王子在第三次战争期间肃清该城时，他的军队点燃了房屋和街道，以消灭受感染的民众并阻止亡灵瘟疫的蔓延。受瘟疫污染的非自然大火至今仍未熄灭，在黑暗通灵能量和猖獗的天灾军团侵蚀下持续燃烧。",al={"为什么斯坦索姆在燃烧","斯坦索姆的火焰","斯坦索姆的烟雾"}},{q="什么是斯坦索姆的净化？",a="“净化”是指阿尔萨斯·米奈希尔王子对斯坦索姆民众的大规模屠杀。在全城居民食用了受到亡灵瘟疫污染的谷物后，阿尔萨斯选择处决每一位居民——无论病患还是健康者——以防他们成为天灾军团的士兵。这一决定使他失去了盟友，也摧毁了他的道德底线。",al={"斯坦索姆的净化","阿尔萨斯的肃清","斯坦索姆肃清"}},{q="斯坦索姆对白银之手骑士团有着怎样的历史意义？",a="斯坦索姆是白银之手骑士团的诞生地。在城内的阿隆苏斯礼拜堂，阿隆苏斯·法奥大主教在第二次战争前创立了圣骑士组织，并受封了最初的五位成员，其中包括光明使者乌瑟尔、图拉扬和赛丹·达索汉。",al={"白银之手起源","阿隆苏斯礼拜堂","白银之手骑士团斯坦索姆"}},{q="提里奥·弗丁在这里遭遇了什么？",a="在第二次战争结束多年后，提里奥·弗丁勋爵在斯坦索姆的司法大厅因捍卫崇高的兽人隐士伊崔格而受审。在乌瑟尔和联盟领袖的裁决下，提里奥被剥夺了爵位并遭到流放。后来，在萨尔领导的城市袭击中，他释放了伊崔格。",al={"提里奥·弗丁审判","提里奥斯坦索姆审判","伊崔格审判"}}},fp="10,367,28.666.0,28.622.0,32.295.0,35.340.0,59.268.0,38.300.0"}
P.entries["subzone:stratholme-classic"] = {n="Stratholme (Classic)",s="斯坦索姆曾是洛丹伦北部最引以为傲的明珠，也是白银之手骑士团的诞生地，如今却沦为了一片燃烧的废墟，成为了天灾军团的区域首府。这座被诅咒的城市在狂热的血色十字军与瑞文戴尔男爵的亡灵军团之间被一分为二，陷入了永无止境的残酷战争之中。",h="斯坦索姆曾是洛丹伦北部最引以为傲的明珠，也是白银之手骑士团的诞生地，如今却沦为了一片燃烧的废墟，成为了天灾军团的区域首府。这座被诅咒的城市在狂热的血色十字军与瑞文戴尔男爵的亡灵军团之间被一分为二，陷入了永无止境的残酷战争...",kw={"阿尔萨斯","达索汉","瘟疫之地","清洗","瑞文戴尔","白银之手","屠宰场","斯坦索姆"},ang={["class:Paladin"]="斯坦索姆的亵渎对圣骑士来说是沉痛的打击；它既是白银之手神圣的诞生地，也是阿尔萨斯粉碎乌瑟尔教诲的墓地。",["faction:Alliance"]="对于联盟来说，斯坦索姆代表了洛丹伦灾难性的陨落，提醒着士兵和幸存者们第三次战争所付出的惨重代价。"},sec={{t="被诅咒的都城",b="在第三次战争之前，斯坦索姆是洛丹伦北部的权力中心，也是白银之手骑士团神圣的诞生地。当阿尔萨斯王子因为被感染的谷物将瘟疫带入城内，而对城内百姓进行屠杀并清洗城市时，斯坦索姆的命运便已注定。如今，斯坦索姆在烟火和废墟中被天灾军团所占据。在巫妖克尔苏加德的最高权威和瑞文戴尔男爵的现场指挥下，这座城市成为了亡灵在瘟疫之地力量的主要基地。"},{t="分裂的战线",b="斯坦索姆被两个陷入永恒血战的残酷阵营一分为二。在西侧，狂热的血色十字军在大十字军战士赛丹·达索汉的指挥下，加固了十字军广场和血色区。东侧则是天灾军团的屠宰场和死灵之城，由高耸的通灵塔和死亡骑士瑞文戴尔男爵防守。任何进入城市的人都必须在这磨人的交叉火力中穿行，四周环绕着燃烧的住宅区和躁动的灵魂。"}},faq={{q="为什么斯坦索姆还在燃烧？",a="阿尔萨斯王子在第三次战争中那场臭名昭著的清洗行动中放火烧城，以阻止亡灵瘟疫的蔓延。由于黑暗魔法、死灵术以及天灾军团与血色十字军之间无休止的城市巷战，火势从未真正熄灭，始终在燃烧。",al={"为什么斯坦索姆在燃烧","是谁烧毁了斯坦索姆","斯坦索姆燃烧"}},{q="现在是谁在控制斯坦索姆？",a="控制权被瓜分了。大十字军战士达索汉指挥着一支幸存的血色十字军，固守在西侧的堡垒中，而死亡骑士瑞文戴尔男爵则在克尔苏加德的统领下，为天灾军团统治着东侧的废墟。",al={"谁统治着斯坦索姆","谁在负责斯坦索姆","斯坦索姆的领袖"}},{q="这座城市对于圣骑士有何历史意义？",a="斯坦索姆是白银之手骑士团的诞生地，阿隆索斯·法奥大主教曾在此第一次为光明使者乌瑟尔和最初的圣骑士们举行了圣礼。它的沦陷是该骑士团历史上最沉痛的悲剧。",al={"白银之手斯坦索姆","圣骑士历史斯坦索姆"}},{q="如何进入这座城市中天灾军团控制的那一侧？",a="虽然冒险者可以从正门一路杀进去，但东侧的天灾区也可以通过后门直接进入。进入这个后门需要巴纳扎尔（或相关掉落）或巴瑟拉斯镇长持有的钥匙，不过技术高超的潜行者、强大的锻造骷髅钥匙或地精炸药也可以强行打开它。",al={"后门钥匙","斯坦索姆后门","如何进入亡灵一侧"}}},fp="20,296,18.522.0,18.475.0,32.278.0,34.232.0,60.223.0,57.327.0"}
P.entries["subzone:stratholme-main-gate"] = {n="Stratholme Main Gate",s="斯坦索姆正门矗立在东瘟疫之地西北部，是这座洛丹伦北部大都市宏伟却燃着烈火的入口。它提供了通往这座城市废墟大道，进而直达国王广场和内部血色十字军防御工事的直接通路。",h="斯坦索姆正门矗立在东瘟疫之地西北部，是这座洛丹伦北部大都市宏伟却燃着烈火的入口。它提供了通往这座城市废墟大道，进而直达国王广场和内部血色十字军防御工事的直接通路。",kw={"阿尔萨斯","东瘟疫之地","前门","国王广场","正门","血色堡垒","亡灵天灾","斯坦索姆"},ang={["class:Paladin"]="站在这些大门前会让圣骑士感到无比悲痛；阿尔萨斯在清洗斯坦索姆当天解散白银之手骑士团时，这个组织就是在此分崩离析的。",["race:Human"]="这座主拱门曾是洛丹伦第二大首府的宏伟门槛，如今已沦为一座灰烬弥漫的死灵之城。"},sec={{t="通往陨落明珠的门户",b="斯坦索姆曾是洛丹伦北部的骄傲，以白银之手骑士团的诞生地而闻名。如今，其巨大的拱形正门标记着一场永无止境的梦魇的开端。正是在这里，阿尔萨斯王子在第三次战争期间背叛了他的导师光明使者乌瑟尔，并在亡灵天灾夺走他们之前清洗了自己的国民。自那以后，这座城市一直在熊熊燃烧，成为了该地区主要的亡灵天灾据点。"},{t="血色之路",b="穿过正门可以直接进入国王广场和市场区的废墟，径直前往被称为血色堡垒的防御区。血色十字军的狂热者们冲破了这个入口试图收复城市并净化亡灵，在废墟中开辟了一处营地。然而，十字军发现自己陷入了铺天盖地的亡灵怪物的包围之中，正在进行一场他们注定无法在这股操控着斯坦索姆防御的黑暗力量面前获胜的消耗战。"}},faq={{q="这道门通往哪里？",a="正门是进入斯坦索姆的宏伟前入口，直接通往国王广场和市场区。它是前往血色堡垒——也就是血色十字军所争夺的那个区域——的主要路径。",al={"斯坦索姆正门通向哪里","什么是斯坦索姆正门","斯坦索姆前门"}},{q="为什么这道门后的城市仍在燃烧？",a="在第三次战争期间，阿尔萨斯王子清洗了这座城市并将其付之一炬，以阻止亡灵瘟疫的蔓延。黑暗的死灵魔法、邪恶的火焰和肆虐的亡灵天灾腐蚀使这座废墟城市自那以后一直阴燃并不断燃烧，从未停歇。",al={"为什么斯坦索姆在燃烧","谁烧毁了斯坦索姆","斯坦索姆的火焰"}},{q="这道门和后门有什么区别？",a="两个入口都通向同一座广阔的废墟城市，但分别位于城市两端。正门进入后靠近城市中存活者和血色十字军占据的区域，而后门则直接通向东部的街道，那里完全处于亡灵天灾的屠宰场和瑞文戴尔男爵的统治之下。",al={"正门与后门区别","斯坦索姆哪个入口","斯坦索姆大门"}},{q="谁控制着正门内的区域？",a="拱门后的起始街道上徘徊着蹒跚的僵尸、食尸鬼、骷髅怪物和游荡的阴影，而血色十字军在更深处的大道上维持着一座处于激战中的堡垒。",al={"正门内有什么人","斯坦索姆前门有什么怪物"}}},fp="20,259,25.472.0,20.494.0,26.214.0,49.258.0,66.289.0,55.203.0"}
P.entries["subzone:stratholme-service-entrance"] = {n="Stratholme Service Entrance",s="Stratholme Service Entrance 是位于东瘟疫之地北部东墙大门的一座防御森严的后门。它提供了直接、隐蔽的通道，可进入这座燃烧的城市中被天灾军团控制的东部区域，从而绕过宏伟的前门。",h="Stratholme Service Entrance 是位于东瘟疫之地北部东墙大门的一座防御森严的后门。它提供了直接、隐蔽的通道，可进入这座燃烧的城市中被天灾军团控制的东部区域，从而绕过宏伟的前门。",kw={"后门","瑞文戴尔男爵","东瘟疫之地","东墙大门","长者广场","天灾军团","服务入口","斯坦索姆"},ang={["class:Paladin"]="对于圣光的骑士来说，这道门槛直通天灾军团亵渎的死灵装置，为肃清瑞文戴尔男爵并重拾这座圣城失落的荣誉提供了一条直接的途径。",["class:Rogue"]="这道服务之门是经典的战术渗透体现，让冒险者能够绕过防御严密的战线，悄悄溜进城市的维修通道。"},sec={{t="被攻破的堡垒",b="虽然宏伟的 Stratholme Main Gate 通向国王广场，并提供了一条通往血色堡垒的路线，但 Stratholme Service Entrance 却在东墙大门处突破了城市的东部防御。如今，它直接通往这座大都市腐化堕落的中心：长者广场，以及通往瑞文戴尔男爵屠宰场的荒芜小径。"},{t="天灾军团的堡垒",b="穿过这道服务传送门可以更近地接近天灾军团的东部地区。周围的小巷里爬满了石像鬼、地穴恶魔和守卫着恐怖通灵塔的邪教徒。对于银色黎明和那些寻求直接打击统治此地的死亡骑士的勇敢冒险者来说，这道隐蔽的铁门是针对巫妖王麾下指挥官进行外科手术式打击的主要集结地。"}},faq={{q="Stratholme Service Entrance 位于何处？",a="该入口位于东瘟疫之地北部山脉沿线的东墙大门处，就在 斯坦索姆 主要废墟的东侧。它隐藏在防御墙沿线的一座石拱门中。",al={"服务入口位置","后门在哪里","斯坦索姆侧门地图","如何找到斯坦索姆后门"}},{q="这个入口与 Stratholme Main Gate 有什么不同？",a="Main Gate 通向国王广场，并提供了一条横穿城市前往血色堡垒的路线。而 Service Entrance 开在长者广场附近，能更近地接近亡灵控制的东部地区和屠宰广场。",al={"后门与前门的区别","服务入口的区别","斯坦索姆哪个入口"}},{q="为什么它被称为“服务入口”？",a="它是位于东墙大门的一处后门，可以绕过城市的前方入口。它最初的市政用途并未明确。",al={"为什么叫服务入口","服务之门背景故事"}},{q="城市的这一部分由谁控制？",a="门后的区域由天灾军团牢牢控制，由瑞文戴尔男爵和他的侍僧们监管，他们维护着在长者广场锚定其黑暗魔法的通灵塔。",al={"谁控制了后门","服务入口首领","亡灵区首领"}}},fp="27,253,18.359.0,19.413.0,49.202.0,60.236.0,38.124.0,35.182.0"}
P.entries["subzone:stromgarde-keep"] = {n="激流堡",s="激流堡是位于阿拉希高地、已覆灭的人类王国斯托姆加德那饱经战火且四分五裂的首都。这座要塞曾是人类文明引以为傲的摇篮，名为“激流城”，如今却被敌对的辛迪加盗贼、入侵的巨石食人魔，以及加林·托尔贝恩王子麾下拼死抵抗的皇家守军瓜分殆尽。",h="激流堡是位于阿拉希高地、已覆灭的人类王国斯托姆加德那饱经战火且四分五裂的首都。这座要塞曾是人类文明引以为傲的摇篮，名为“激流城”，如今却被敌对的辛迪加盗贼、入侵的巨石食人魔，以及加林·托尔贝恩王子麾下拼死抵抗的皇家守军瓜...",kw={"阿拉希","阿拉索","巨石氏族","加林","激流城","斯托姆加德","激流堡","辛迪加","索拉丁","托尔贝恩"},ang={["faction:Alliance"]="斯托姆加德是第二次战争期间洛丹伦联盟的创始成员。其陷入困境的守军代表了北方仅存的忠诚堡垒之一，正在进行殊死抵抗，以避免彻底覆灭。",["race:Human"]="斯托姆加德是你整个种族的古老心脏，最初的人类部落在索拉丁的领导下在此团结起来，并从高等精灵那里学习了奥术。看到它被罪犯和食人魔蹂躏，实在令人痛心。"},sec={{t="人类的摇篮",b="在拥有现在的名字之前，这座要塞在近三千年前就被建立，名为激流城，是索拉丁国王统治下的阿拉索统一帝国的第一座首都。它是人类对抗森林巨魔取得胜利的集结地，也是人类法术的诞生地，高等精灵法师曾在此教导了最初的一百位人类施法者。几个世纪以来，随着达拉然、洛丹伦和暴风城等年轻的姐妹王国崛起并繁荣起来，激流城的影响力逐渐衰退。留守此地的顽强的托尔贝恩王朝将其更名为斯托姆加德，在第二次战争期间，它始终是一座引以为傲的战士堡垒，是洛丹伦联盟抵御兽人部落的坚固支柱。"},{t="破碎的堡垒",b="在第三次战争的浩劫之后，斯托姆加德最终在日益严重的灾难和背叛中土崩瓦解。如今，这座宏伟的石砌城市被分割为三个交战区域。辛迪加的贵族叛徒占据了宏伟的内堡，而粗野的巨石食人魔则占领了法师区的前圣所。加林·托尔贝恩王子和饱经战火的斯托姆加德军队被困在剩下的城区中，在多条战线上进行着艰苦而血腥的战争，只为不让他们的祖居之地湮没在记忆中。"}},faq={{q="谁现在控制着激流堡？",a="这座废墟之城被划分为三个激烈争夺的区域。奸诈的辛迪加控制着中央内堡，入侵的巨石氏族食人魔占据了荒废的法师区，而加林·托尔贝恩王子则在剩下的城区带领着斯托姆加德军队的残部。",al={"激流堡的居民","激流堡的控制者","激流堡内的人员"}},{q="什么是阿拉索帝国？",a="阿拉索帝国是第一个统一的人类国家，由索拉丁国王在近三千年前建立。它的首都是激流城，坐落在今天激流堡所在的位置上。",al={"什么是激流城","第一个人类王国","阿拉索帝国"}},{q="为什么这座城市会变成废墟？",a="斯托姆加德在第二次战争期间曾是中坚力量，但在第三次战争混乱的余波中，该王国变得脆弱且孤立无援。内部背叛、犯罪组织辛迪加的投机攻击以及巨石食人魔的突袭，共同摧毁了这座城市的防御。",al={"斯托姆加德为何毁灭","斯托姆加德的遭遇"}},{q="加林·托尔贝恩是谁？",a="加林·托尔贝恩王子是斯托姆加德残存军队的皇室后裔和指挥官。他在堡垒内受到围攻的据点里，指挥着针对辛迪加和食人魔的绝望防御战。",al={"托尔贝恩王子","加林王子是谁"}}},fp="15,342,18.693.0,19.547.0,39.293.0,31.208.0,25.300.0,23.208.0"}
P.entries["subzone:sun-rock-retreat"] = {n="烈日石居",s="烈日石居是隐藏在石爪山脉中部高山之中的一座部落避难所，位于暗色湖以南。这里主要由牛头人和兽人力量驻守，是部落在该地区的主要集结地和补给站。除了战略用途之外，这处定居点还坐落在一片被牛头人长期尊崇的圣地上，因其深厚的精神共鸣而备受推崇。",h="烈日石居是隐藏在石爪山脉中部高山之中的一座部落避难所，位于暗色湖以南。这里主要由牛头人和兽人力量驻守，是部落在该地区的主要集结地和补给站。除了战略用途之外，这处定居点还坐落在一片被牛头人长期尊崇的圣地上，因其深厚的精神共...",kw={"安舍","暗色湖","石爪山脉","烈日石居","牛头人","荆棘谷地精"},ang={["faction:Horde"]="作为部落在石爪山脉的主要集结枢纽，烈日石居在这片饱受争夺的山峰中提供了一个重要的补给站和飞行枢纽。",["race:Tauren"]="对舒哈鲁而言，烈日石居不仅仅是一座前哨站；它是受到安舍祝福的神圣土地，数百年来萨满们一直在此漫步于灵界之中。"},sec={{t="高山之中的神圣避难所",b="烈日石居隐匿在暗色湖以南的山谷中，长期以来对牛头人而言具有重要的精神意义。根据古老的传说，太阳安舍曾亲吻过村庄所在的这座山峰。在部落到来之前的几代人里，牛头人萨满和朝圣者们都会来到这里举行仪式，沟通凡世与彼岸，从这片土地与灵界的紧密联系中汲取力量。"},{t="边境前哨",b="如今，烈日石居是部落在石爪山脉的主要行动基地。兽人和牛头人并肩作战，建立起稳固的立足点，以抵御敌对的鹰身人族群、当地的暗夜精灵哨兵以及荆棘谷地精的工业掠夺。作为连接雷霆崖、十字路口以及灰谷边界的贸易和飞行航线的枢纽，烈日石居为那些勇闯险峰的人们提供了庇护、补给和精神指引。"}},faq={{q="什么是烈日石居？",a="烈日石居是部落在石爪山脉的主要前哨站。这里主要居住着牛头人和兽人，是部落英雄在该地区开展工作的和平避难所、贸易站和指挥部。",al={"烈日石居是什么","烈日石居信息","谁在管理烈日石居"}},{q="为什么这个地方对牛头人来说是神圣的？",a="牛头人的传说认为，太阳安舍曾触碰过如今烈日石居所在的山峰。这片土地与灵界有着持久的联系，使其成为进行幻象试炼和与祖先沟通的古老朝圣地。",al={"为什么烈日石居是圣地","安舍 石爪山脉","牛头人烈日石居背景故事"}},{q="烈日石居面临着哪些威胁？",a="烈日石居需要应对好战且具有领地意识的鹰身人、守护神圣森林的敌对暗夜精灵，以及正在破坏自然景观的荆棘谷地精的破坏性采矿和伐木活动。",al={"烈日石居的威胁","谁在攻击烈日石居","石爪山脉的敌人"}},{q="当地的飞行管理员通向哪里？",a="烈日石居提供双足飞龙服务，可将旅客直接送往卡利姆多中部的多个主要地点，包括贫瘠之地的十字路口和牛头人的主城雷霆崖。",al={"烈日石居飞行路线","飞往烈日石居","烈日石居飞行管理员"}}},fx={ea57691e={q="烈日石居过去发生过什么？",al={"烈日石居历史","烈日石居的过往","烈日石居的历史"}},["399aba06"]={q="谁住在烈日石居？",a="烈日石居驻扎着一支尽职的部落部队，其中以牛头人和兽人为主。除了尊崇这片圣地的灵魂萨满和德鲁伊，战士与劳工也共同努力，修复石爪山脉被荆棘谷地精等肆意开发者留下的创伤。",al={"谁住在烈日石居","烈日石居的居民","谁管理烈日石居"}},["7401fa7d"]={q="烈日石居危险吗？",a="烈日石居本身是由警惕的部落守卫保护的安全庇护所，能为旅人和朝圣者提供保障。不过，周围的荒野危机四伏。凶猛的野兽、领地意识强烈的 harpy，以及荆棘谷地精派来的破坏性佣兵遍布附近的峭壁与峡谷，所以一离开营地边界就要保持警惕。",al={"烈日石居安全吗","烈日石居有多危险","烈日石居的危险"}},f56a5eae={q="为什么叫烈日石居？",a="这处聚居地的名字源自牛头人的古老神话。传说中，牛头人信仰里的太阳安舍曾俯身亲吻如今村庄所在的山峰，为岩石赐福，并赋予这片区域神圣的温暖与灵力。",al={"为何叫烈日石居","烈日石居名称由来","烈日石居名称的含义"}}},fp="16,391,27.428.0,16.496.0,25.221.0,39.234.0,35.212.0,43.192.0"}
P.entries["subzone:sundown-marsh"] = {n="日落沼泽",s="日落沼泽标志着湿地最深、最西端的区域，那里死水汇集，野兽横行。尽管有迅猛龙、软泥怪和豺狼人在此徘徊，但一对古怪的搭档仍在这片泥泞边缘的一处孤立宅邸中安了家。",h="日落沼泽标志着湿地最深、最西端的区域，那里死水汇集，野兽横行。尽管有迅猛龙、软泥怪和豺狼人在此徘徊，但一对古怪的搭档仍在这片泥泞边缘的一处孤立宅邸中安了家。",kw={"鳄鱼","弗拉德·迅齿","苔黑","软泥怪","日落沼泽","温娜·丝须","湿地"},ang={["race:Gnome"]="看到弗拉德·迅齿和温娜·丝须能够在危险的泥泞中经营他们的风车前哨站，这证明了侏儒的巧思可以在任何地方开辟出一片舒适的家园。"},sec={{t="狂野而昏暗的低地",b="日落沼泽位于湿地的西北角，以深水、厚重的淤泥和密集的掠食者种群而闻名。巨型鳄鱼、流动的软泥怪、游荡的迅猛龙以及领地意识极强的苔黑豺狼人在迷雾中自由穿行。危险的地形使得大多数过往旅客只能严格沿着连接米奈希尔港和铁炉堡的铺石主路行进，从而使得这片深处的角落基本处于未被开发的野蛮状态。"},{t="泥沼边缘的生活",b="在沼泽的重重危机之中，矗立着一座孤独的石屋，屋顶上有着一台不停转动的风车。在那里，侏儒弗拉德·迅齿和矮人温娜·丝须以在沼泽中拾荒为生，这对组合看起来十分不协调。他们将从泥沼中寻获的奇珍异宝和稀有配方兜售给那些勇敢到足以穿越这片充满敌意生物的沼泽的旅行者。"}},faq={{q="日落沼泽位于何处？",a="日落沼泽位于湿地的西北部。它代表了沼泽地势最低、最深的部分之一，偏离了主要皇家道路。",al={"日落沼泽位置","日落沼泽在哪里","湿地沼泽位置"}},{q="谁住在日落沼泽？",a="一对古怪的搭档，侏儒弗拉德·迅齿和矮人温娜·丝须住在这里，他们的住所是一座带有风车的小型石屋。他们在泥沼中搜寻奇珍，并向路过的旅行者出售稀有商品。",al={"谁住在这里","日落沼泽npc","迅齿小屋"}},{q="日落沼泽里有什么威胁？",a="这片沼泽中充满了危险的野生生物和怪物，包括巨型鳄鱼、污浊的软泥怪、沼泽兽、迅猛龙以及敌对的苔黑豺狼人，这些生物让普通的探险望而却步。",al={"日落沼泽的怪物","日落沼泽的危险","日落沼泽的敌人"}},{q="冒险者为什么要进入日落沼泽？",a="除了应对当地的野兽，旅行者们还会前往那座风车小屋，与弗拉德·迅齿和温娜·丝须进行贸易。他们提供在周围沼泽中发现的罕见配方和奇异珍品。",al={"为什么要访问日落沼泽","前往日落沼泽的理由","日落沼泽商人"}}},fx={a91ad050={q="什么是日落沼泽？",a="日落沼泽是湿地深处西北方的沼泽地带。这里遍布浑浊的水域和茂密的植被，这片偏僻的泥沼环绕着一座孤零零的石砌风车宅邸。尽管周遭危机四伏，仍有一对勇敢的商人设法在此谋生。",al={"日落沼泽是什么","日落沼泽简介","湿地日落沼泽"}},d0103c3e={q="日落沼泽危险吗？",a="对于没有做好应对野外环境准备的旅人来说，日落沼泽危机四伏。凶猛的鳄鱼潜伏在水中，迅猛龙和四处游荡的豺狼人徘徊于泥岸，危险的软泥怪和沼泽野兽则在泥沼中游荡，使任何偏离常规路线的旅程都险象环生。",al={"日落沼泽有多危险","日落沼泽的威胁","日落沼泽安全吗"}}},fp="13,240,25.423.0,28.341.0,31.193.0,27.205.0,43.181.0,50.216.0"}
P.entries["subzone:sunnyglade"] = {n="阳光林地",s="阳光林地曾是暴风城王国在第一次战争期间一个富庶繁荣的人类定居点。随着前线崩溃，这座城镇遭到破坏并最终被废弃，如今，这片废墟正饱受暮光之锤邪教的黑暗影响。",h="阳光林地曾是暴风城王国在第一次战争期间一个富庶繁荣的人类定居点。随着前线崩溃，这座城镇遭到破坏并最终被废弃，如今，这片废墟正饱受暮光之锤邪教的黑暗影响。",kw={"第一次战争","法师塔","旧部落","河林","暴风城","阳光林地","暮光之锤"},ang={["class:Mage"]="阳光林地那座孤零零的法师塔是早期人类咒法的一处诡异遗迹，当初旧部落将其留下，纯粹是为了剖析人类的奥术知识。",["race:Human"]="阳光林地杂草丛生的乱石是一座沉重的纪念碑，象征着在第一次战争期间暴风城被迫撤退时所抛弃的那些外围定居点。"},sec={{t="黄金小镇的陷落",b="在第一次战争将艾泽拉斯南部撕裂之前，阳光林地以其财富和安宁的繁荣而闻名。当旧部落入侵时，那份和平被暴力粉碎。兽人突袭队攻击了该镇并奴役了幸存的居民，只留下一座孤零零的法师塔，用于研究人类施法者的奥术。虽然暴风城的军队曾试图营救被俘的农民并重建定居点，但周边的河林地区正逐渐被不断推进的部落吞噬。在认定外围省份已失守后，暴风城的指挥官们最终撤回了资源以保卫家园，让阳光林地沦为废墟。"},{t="枯萎的避难所",b="如今，阳光林地位于暴风城重建后的安全边界之外。虽然那座标志性的石头法师塔奇迹般地挺过了第一次战争以及随后的多年荒废，但它周围曾经宁静的城镇已不复存在。取而代之的是，这片隐蔽的废墟已被暮光之锤邪教的狂热分子占据，他们正将这片曾经繁荣的谷地变为实现其邪恶计划的温床。"}},faq={{q="阳光林地发生了什么？",a="阳光林地在第一次战争期间遭到了旧部落的袭击和劫掠。尽管人类军队曾设法解救了被俘的农民并试图重建，但暴风城最终还是放弃了河林地区，转而专注于保卫其核心领土。",al={"阳光林地是什么","阳光林地的历史","阳光林地为何被摧毁"}},{q="谁现在控制着阳光林地？",a="阳光林地的废墟目前被暮光之锤邪教占据，他们在破败的房屋和古老的法师塔之间建立了营地。",al={"谁住在阳光林地","阳光林地的敌人","阳光林地暮光邪教"}},{q="为什么兽人在第一次战争期间留下了那座法师塔？",a="当旧部落劫掠阳光林地时，他们故意留下了镇上的奥术塔，以便他们的术士和指挥官研究人类魔法并参透其中的秘密。",al={"阳光林地的兽人与法师塔","阳光林地法师塔传说"}},{q="为什么暴风城在战争结束后没有收复该镇？",a="随着第一次战争的加剧，暴风城的领导层认为河林地区已是失地，并将所有军事力量转向保卫王国中心区域，从而放弃了阳光林地。",al={"为何被废弃","暴风城与阳光林地"}}},fp="10,277,21.665.0,17.396.0,28.256.0,28.151.0,68.168.0,52.193.0"}
P.entries["subzone:swamplight-manor"] = {n="水光庄园",s="水光庄园是一间名不副实的破旧木屋，坐落在尘泥沼泽女巫岭的深处。这里是“沼泽之眼”贾尔古怪的家和厨房，他是一位隐士，以其奇怪的烹饪癖好在整个沼泽地闻名。尽管庄园位置偏僻且阴森，但其周围的花园里隐藏着引人注目的秘密，塞拉摩和蕨墙村都对这里虎视眈眈。",h="水光庄园是一间名不副实的破旧木屋，坐落在尘泥沼泽女巫岭的深处。这里是“沼泽之眼”贾尔古怪的家和厨房，他是一位隐士，以其奇怪的烹饪癖好在整个沼泽地闻名。尽管庄园位置偏僻且阴森，但其周围的花园里隐藏着引人注目的秘密，塞拉摩和...",kw={"蕨墙村","尘泥沼泽","盖兰·维米斯","丢失的报告","沼泽之眼贾尔","水光庄园","女巫岭"},ang={["faction:Alliance"]="由盖兰·维米斯队长派遣的塞拉摩斥候密切关注着围绕庄园的传闻，特别是关于失踪的斥候和被截获的部落通信的消息。",["profession:Cooking"]="对于敢于闯荡沼泽地的烹饪爱好者来说，贾尔代表了沼泽觅食界的怪诞巅峰，他能用大多数厨师避之不及的生物制作出当地风味的美食。"},sec={{t="沼泽中的隐士休憩处",b="尽管名字听起来气派，水光庄园却远非什么贵族庄园。它不过是一间蜷缩在女巫岭闹鬼湿地中、破败不堪且歪歪斜斜的小屋。唯一的住户是一位名叫“沼泽之眼”贾尔的怪异隐士，他独自生活在雾气、污泥和不安分的沼泽鬼魂之中。贾尔终日钻研如何用当地的野生动物制作罕见的区域美味，并经常招募路过的冒险者去猎取沼泽蛙腿和生物眼睛之类的奇特食材，以满足他的烹饪需求。"},{t="花园中的秘密",b="虽然旅行者通常是为了寻求古怪的美食或躲避女巫岭的鬼魂而偶然发现这座庄园，但庄园的土地下却隐藏着更深层的边境冲突。在贾尔临时开辟的花园里，一堆松散的泥土下埋着一份被丢弃的兽人间谍报告，旁边还放着一颗断头。在盖兰·维米斯队长麾下的塞拉摩卫兵和蕨墙村的部落军队都对回收这些文件有着浓厚的兴趣，这使得隐士那片杂草丛生的土地成了区域冷战中意想不到的交火点。"}},faq={{q="为什么一间小棚屋会被称为“庄园”？",a="这个名字纯粹是讽刺。这座建筑不过是一间潮湿、破旧的木屋，其隐居的住户“沼泽之眼”贾尔为其取名时带有一种怪诞的幽默感，以此与女巫岭那阴沉的氛围形成对比。",al={"水光庄园名字由来","为什么叫庄园","水光庄园是真正的庄园吗"}},{q="谁住在水光庄园？",a="“沼泽之眼”贾尔独自住在这里。他是一位臭名昭著、半疯癫的隐士兼厨师，选择隐居在闹鬼的沼泽中，并雇佣路过的旅行者为他提供奇特的烹饪原料，同时协助他处理当地的鬼魂。",al={"谁是沼泽之眼贾尔","水光庄园住户","谁住在这里"}},{q="花园外埋着什么？",a="在贾尔院子里一堆被翻动的泥土中，藏着一份由兽人撰写的失落间谍报告，旁边还有一颗断头。塞拉摩的联盟当局和蕨墙村的部落斥候都急于获取这些情报。",al={"水光庄园土堆","水光庄园松动的泥土","兽人间谍报告"}},{q="联盟和部落的玩家都能拜访贾尔吗？",a="是的。贾尔远离文明社会，保持着中立，乐于接受联盟和部落旅行者的帮助并与其交换食谱。",al={"贾尔是中立的吗","部落可以和沼泽之眼贾尔交谈吗","水光庄园阵营"}}},fp="16,407,30.551.0,21.545.1,37.222.0,30.238.0,37.238.1,47.159.0"}
P.entries["subzone:swarming-pillar"] = {n="虫群之柱",s="虫群之柱是希利苏斯中心的一座高耸岩层，已被其拉虫人彻底侵蚀并改造。它位于塞纳里奥要塞的正南方，因其峰顶和地下入口处终日盘旋着无数带翼昆虫而得名。",h="虫群之柱是希利苏斯中心的一座高耸岩层，已被其拉虫人彻底侵蚀并改造。它位于塞纳里奥要塞的正南方，因其峰顶和地下入口处终日盘旋着无数带翼昆虫而得名。",kw={"塞纳里奥要塞","虫巢","昆虫","其拉虫人","希利苏斯","尖塔","虫群之柱"},ang={["class:Druid"]="由于紧邻塞纳里奥要塞，虫群之柱的虫巢不仅是对自然秩序的直接挑衅，也是对塞纳里奥议会守望工作的持续威胁。"},sec={{t="甲壳与沙砾之塔",b="虫群之柱突兀地耸立在希利苏斯中部的流沙之上，是其拉虫人无节制扩张的残酷纪念碑。这里原本是一处天然岩层，如今却被虫群的分泌物和巢穴雕琢、覆盖。它位于塞纳里奥要塞正南方，源源不断地孵化着带翼的工虫和兵虫，它们形成的乌云笼罩着干燥的沙漠，警告过往的旅人保持距离。"},{t="虫巢之心",b="尽管在地表上显得庞大且令人望而生畏，但虫群之柱仅仅是庞大地下网络在地面上的凸起部分。在其石质外壳之下，深藏着幽深的隧道和宽敞的育虫室，这里是该地区最大的虫巢之一。塞纳里奥议会对这座尖塔深感忧虑，因为其活跃的虫群直接威胁着德鲁伊的行动，也暗示了这种昆虫威胁背后存在着令人恐惧的组织性。"}},faq={{q="什么是虫群之柱？",a="虫群之柱是位于希利苏斯中部的一座大型岩层，已被其拉虫人占据并改造成了一个活跃的虫巢。其标志性特征是其峰顶终日盘旋着无穷无尽的飞行昆虫。",al={"虫群之柱","这是什么柱子","希利苏斯其拉虫人尖塔"}},{q="虫群之柱位于何处？",a="它位于沙漠中心，就在塞纳里奥要塞正南方的短距离处。",al={"虫群之柱在哪里","虫群之柱位置"}},{q="为什么它周围有那么多虫子在飞？",a="这座岩层是希利苏斯的主要虫巢之一，作为带翼其拉虫人的大型育婴场和中转站，它们巡视着周围的沙漠。",al={"为什么叫虫群","希利苏斯柱子的飞虫","飞行其拉虫人"}},{q="虫群之柱是否与沙下的虫巢相连？",a="是的。可见的尖塔只是深埋于希利苏斯基岩和沙土之下的庞大地下聚落的顶部投影。",al={"虫巢隧道","地下其拉虫人柱"}}},fp="15,288,26.462.0,17.444.0,28.213.0,37.99.0,44.172.0,63.146.0"}
P.entries["subzone:tabetha-s-farm"] = {n="Tabetha's Farm",s="在泥潭沼泽最阴暗的深处，坐落着Tabetha's Farm，这是一个与世隔绝的家园，中心是一座小木屋，配有一个朴素的庭院和一个私人码头。尽管周围的沼泽环境险恶，但这个避难所却是隐士法师塔贝萨的一处隐秘据点。",h="在泥潭沼泽最阴暗的深处，坐落着Tabetha's Farm，这是一个与世隔绝的家园，中心是一座小木屋，配有一个朴素的庭院和一个私人码头。尽管周围的沼泽环境险恶，但这个避难所却是隐士法师塔贝萨的一处隐秘据点。",kw={"尘泥沼泽","泥潭沼泽","塔贝萨","tabetha's farm","塔贝萨的小屋"},ang={["class:Mage"]="你在主城的训练师对塔贝萨的秘法知识评价很高，他们会派遣娴熟的施法者前往她的农场，去调查不稳定的法力涌动和古老的强大圣物。",["class:Warlock"]="尽管她像个安静的沼泽隐士一样生活，但塔贝萨是少数几个能协助你净化奥拉希尔之球所束缚的强大能量的施法者之一。"},sec={{t="隐士的避难所",b="Tabetha's Farm隐匿于尘泥沼泽西部的湿地之中，不畏恶劣的环境。这处家园由一座饱经风霜的小屋、几块菜地和一个用于在沼泽浑浊水道中穿行的码头组成，它提供了一个远离塞拉摩和蕨墙村政治纷争的宁静港湾。在这儿，隐居的人类女法师塔贝萨几乎与世隔绝，在不受达拉然或当地官方干扰的情况下，潜心钻研奥术和邪能的秘法。"},{t="奥术之力的航标",b="尽管位置偏远，但这里吸引了来自卡利姆多和东部王国各地的魔法实践者。寻求掌控原始奥术涌动力量的法师，以及寻求帮助以净化奥拉希尔之球等不稳定神器的术士，都会被指引到塔贝萨的家门口。"}},faq={{q="谁住在Tabetha's Farm？",a="这座农场是古怪法师塔贝萨的家，她在泥潭沼泽险恶的沼泽生物环伺中，打理着那片小花园、码头和家园。",al={"谁是塔贝萨","谁住在这里","tabetha's farm的居民"}},{q="为什么法师要大老远跑到这个农场来？",a="世界各地的法师训练师会将有前途的学生指引给塔贝萨，以进一步深化他们的奥术知识。她拥有关于不稳定的法力涌动、古代圣物和原始力量的深厚专业知识，这是常规城市学院很少教授的。",al={"为什么法师要拜访塔贝萨","尘泥沼泽法师任务","法师职业任务塔贝萨"}},{q="术士为什么要来这里？",a="术士们在努力净化和驯服危险的神器时，会寻求塔贝萨在驱魔和元素能量方面的专业知识，最显著的例子是在净化奥拉希尔之球所需的仪式期间。",al={"塔贝萨术士任务","净化奥拉希尔之球","术士塔贝萨"}},{q="Tabetha's Farm是属于部落还是联盟？",a="塔贝萨保持中立立场，无论旅行者有何政治派别，她都向他们提供智慧。她的农场既不从属于Jaina Proudmoore的塞拉摩，也不属于蕨墙村的部落势力。",al={"塔贝萨是联盟吗","塔贝萨是部落吗","塔贝萨是中立的吗"}}},fp="14,275,20.507.0,26.286.0,28.148.0,45.240.0,29.196.0,56.221.0"}
P.entries["subzone:tahonda-ruins"] = {n="塔霍达废墟",s="塔霍达废墟是曾经的牛头人定居点被闪光平原的盐碱与沙尘所吞没后，留下的被太阳晒得发白的残迹。人们对曾经生活在这里的村民知之甚少，而今，危险的盐石蛇怪在腐朽的帐篷支柱和破碎的皮革间徘徊。",h="塔霍达废墟是曾经的牛头人定居点被闪光平原的盐碱与沙尘所吞没后，留下的被太阳晒得发白的残迹。人们对曾经生活在这里的村民知之甚少，而今，危险的盐石蛇怪在腐朽的帐篷支柱和破碎的皮革间徘徊。",kw={"盐石蛇怪","闪光平原","塔霍达","塔霍达废墟","牛头人村庄","千针石林"},ang={["race:Tauren"]="在千针石林的盐碱地之下发现一处被遗忘的牛头人定居点，这令人痛心地提醒着人们，你们的游牧祖先在流浪卡利姆多时曾面临种种危险。"},sec={{t="沉没于盐碱之下",b="塔霍达废墟位于闪光平原南部，靠近通往塔纳利斯的山口，它如同一座阴郁的纪念碑，见证了已被遗弃的牛头人往昔。这座村庄早已没落，其风化的建筑逐渐被不断移动的白色盐壳所吞没。虽然有些人怀疑是当地的盐石蛇怪驱逐了居民，但残存的建筑物上留下了奇怪的线索。在这一处破败小屋的皮革上，留下了两组明显的三道平行抓痕，这表明在沙漠吞噬残骸之前，村庄可能遭到了强大捕食者或敌对入侵者的暴力袭击。"}},faq={{q="塔霍达废墟最初是什么地方？",a="塔霍达曾经是一个建立在闪光平原干涸广袤之地上的牛头人村庄。随着时间的推移，村庄变得荒废，并逐渐被流沙和盐壳所吞没。",al={"什么是塔霍达废墟","谁建造了塔霍达","塔霍达废墟历史"}},{q="村庄为何会被废弃？",a="没有任何文字记录保留了该村庄的确切命运。废墟目前被凶猛的盐石蛇怪占据，它们可能是驱逐定居者的元凶。然而，残存的皮革帐篷上留下的深深三爪抓痕表明，这里可能发生过突然且暴力的袭击。",al={"为什么塔霍达会变成废墟","什么摧毁了塔霍达","塔霍达发生了什么"}},{q="现在废墟里生活着什么生物？",a="这处村庄的残骸被充满敌意的盐石蛇怪彻底侵占，它们在腐烂的木杆和破烂的皮革庇护所之间享受着日光浴。",al={"塔霍达的怪物","塔霍达废墟里有什么","塔霍达的野兽"}}},fx={["601f2090"]={q="塔霍达废墟发生过什么？",a="关于塔霍达的过往，记载寥寥。这里曾是牛头人的古老聚居地，后来逐渐衰败，最终被闪光平原不断流动的沙土掩埋。盐石蜥蜴的逼近或许迫使村民离开，但风化的皮革居所上遍布的爪痕表明，这处聚居地可能在被时间遗忘之前，就已遭凶残野兽或敌对掠袭者袭击，惨遭毁灭。",al={"塔霍达废墟历史","塔霍达废墟发生过什么","塔霍达废墟的故事"}},d43cf6cc={q="塔霍达废墟危险吗？",a="危险。沉没的村庄遗迹已成为凶猛盐石蜥蜴的繁殖地。穿行于半埋在沙中的皮帐篷和倒塌的支柱之间，会让你暴露在这些能石化猎物的掠食者面前。对于途经此处前往塔纳利斯的粗心旅人来说，这片盐碱地的荒凉角落危机四伏。",al={"塔霍达废墟危险吗","塔霍达废墟的威胁","塔霍达废墟中的危险"}}},fp="13,290,23.605.0,39.186.0,30.272.0,37.163.0"}
P.entries["subzone:tainted-scar"] = {n="腐烂之痕",s="腐烂之痕是一道位于诅咒之地西南部的峡谷，这里不仅布满了恶魔，还充斥着来自附近黑暗之门的邪恶邪能魔法。目前，它是燃烧军团在艾泽拉斯残余势力的主要堡垒，由末日守卫卡扎克领主指挥。",h="腐烂之痕是一道位于诅咒之地西南部的峡谷，这里不仅布满了恶魔，还充斥着来自附近黑暗之门的邪恶邪能魔法。目前，它是燃烧军团在艾泽拉斯残余势力的主要堡垒，由末日守卫卡扎克领主指挥。",kw={"诅咒之地","燃烧军团","衰老的戴奥","艾瑞达","卡扎克","卡扎克领主","拉瑟莱克","腐烂之痕"},ang={["class:Warlock"]="腐烂之痕对资深术士而言极具吸引力，他们会前往衰老的戴奥所在的恶魔祭坛，学习如何奴役和指挥炙热的地狱火。",["faction:Alliance"]="联盟指挥官们密切监视着这道峡谷，唯恐卡扎克领主那盘踞于此的恶魔大军向北突袭进入悲伤沼泽或暴风城领土。"},sec={{t="军团的堡垒",b="这片荒凉的沟壑曾经是属于古老黑色沼泽的茂密湿地，但随着黑暗之门中泄漏出的混乱邪能，这里的一切生命都被彻底抽干，大地也变成了干涸血液般的颜色。在第三次战争中阿克蒙德于海加尔山战败后，燃烧军团的幸存部队在南方集结。巨大的艾瑞达恶魔卡扎克领主宣称腐烂之痕是他的据点，他将精锐恶魔驻扎在黑色的山脊上，并派遣像污染者拉瑟莱克这样可怕的副官来统治这片荒芜的红土地。"},{t="邪恶的居民",b="虽然大多数凡人为了避免遭受极端的痛苦而对腐烂之痕避之唯恐不及，但那些钻研黑暗艺术的施法者却发现这里饱和的邪能具有不可抗拒的吸引力。一位古怪的人类术士，衰老的戴奥，在俯瞰着恐怖景象的一座被毁坏的恶魔祭坛旁定居下来，利用这些肆虐的恶魔进行黑暗仪式，并指导有抱负的术士如何召唤和奴役恐惧的地狱火。"}},faq={{q="腐烂之痕是什么？",a="它是位于诅咒之地西南部的一道峡谷，受到了来自黑暗之门的恶魔魔法的严重腐蚀。这里曾经是黑色沼泽的一部分，但土地已经枯萎成为一片荒凉、血红色的废土，几乎完全由燃烧军团的高阶恶魔所占据。",al={"腐烂之痕是什么","腐烂之痕背景故事","为什么这里的地面是红色的"}},{q="谁统治着腐烂之痕？",a="卡扎克领主，一位统领着燃烧军团的高大末日守卫，负责监管聚集在此的恶魔。在军团于第三次战争中战败后，他将南方的幸存恶魔集结起来，在艾泽拉斯维持着一个致命的立足点。",al={"谁在这里领导恶魔","腐烂之痕首领","腐烂之痕卡扎克领主"}},{q="为什么会有一个年迈的人类住在这里的恶魔中间？",a="那个隐士就是衰老的戴奥，一位年迈的术士，他冒着生命危险来到腐烂之痕，是为了驾驭这里强大的邪能地脉能量。他并没有逃离恶魔，而是在这里的一座祭坛上进行黑暗仪式，并指导那些寻求掌握地狱火召唤术的资深术士。",al={"戴奥是谁","衰老的戴奥","腐烂之痕里的隐士"}},{q="腐烂之痕与黑暗之门有关联吗？",a="是的。当黑暗之门首次打破世界之间的界限时，混乱的虚空能量就泄漏到了周围的沼泽中。腐烂之痕吸收了大量的这种魔法尘埃，将地形永久地扭曲成了一个不适宜居住的恶魔堡垒。",al={"腐烂之痕与黑暗之门的联系","为什么这里会被腐蚀"}}},fp="12,280,23.561.0,18.385.0,25.273.0,27.232.0,49.263.0,49.266.0"}
P.entries["subzone:talonbranch-glade"] = {n="刺枝林地",s="刺枝林地是坐落在费伍德森林北部遭到腐蚀的丘陵中的一处宁静的暗夜精灵要塞。它位于木喉要塞正南，在充满腐化的荒野中提供了一处难得的纯净月光、庇护所和角鹰兽航线。",h="刺枝林地是坐落在费伍德森林北部遭到腐蚀的丘陵中的一处宁静的暗夜精灵要塞。它位于木喉要塞正南，在充满腐化的荒野中提供了一处难得的纯净月光、庇护所和角鹰兽航线。",kw={"费伍德森林","飞行点","林地","月井","哨兵","刺枝林地","木喉"},ang={["faction:Alliance"]="刺枝林地是你在费伍德森林最北端的行动据点，在木喉要塞附近提供重要的飞行连接、修理服务和庇护所。",["race:NightElf"]="这片林地中未受触碰的月井见证了艾露恩在扼杀古老森林的严重恶魔腐蚀中依然存在的恩泽。"},sec={{t="腐蚀中的灯塔",b="刺枝林地坐落于通往木喉要塞的隧道附近的高地上，是联盟在费伍德森林最北端的堡垒。该哨所围绕着一座受庇护的暗夜精灵小屋和一口运作正常的月井而建，为人们提供了逃离吞噬了周围森林的恶魔腐蚀的重要避难所。联盟侦察兵、哨兵和过往的冒险者利用这片林地进行休息、恢复体力，并规划他们深入受污染森林或是继续前往冬泉谷和月光林地的旅程。"},{t="北方的十字路口",b="除了其天然和精神层面的防御外，刺枝林地还是一个重要的后勤枢纽。驻扎在这里的角鹰兽连接着黑海岸的奥伯丁，以及木喉要塞之外雪原中的永望镇。它始终是一座孤独而警惕的哨所，抵御着暗影议会步步紧逼的阴影以及在受腐蚀的山谷中游荡的野兽群。"}},faq={{q="什么是刺枝林地？",a="这是位于费伍德森林北部的一处联盟营地，作为哨兵、德鲁伊和穿越这片受腐蚀森林的旅行者们的避难所、休憩站和飞行枢纽。",al={"刺枝林地","刺枝林地的作用","这是什么地方"}},{q="这里的飞行管理员可以飞往哪里？",a="刺枝林地的角鹰兽管理员直接连接着几个联盟和中立哨所，包括奥伯丁、永望镇和月光林地。",al={"刺枝林地的飞行航线","飞行点","我可以飞往哪里"}},{q="月井里的水可以安全饮用吗？",a="可以。与散布在整个费伍德森林中那些受污染的水潭和泉水不同，刺枝林地的月井依然受到艾露恩的祝福，没有受到恶魔污秽的玷污。",al={"刺枝林地的月井","水干净吗","月井受到腐蚀了吗"}},{q="这里距离木喉要塞有多近？",a="刺枝林地位于木喉要塞入口的正南方，是进入冬泉谷或月光林地的熊怪隧道之前的最后一处休憩点。",al={"木喉要塞在哪里","前往冬泉谷的道路"}}},fp="17,255,22.502.0,25.395.0,26.165.0,41.142.0,43.170.0,36.176.0"}
P.entries["subzone:talondeep-path"] = {n="石爪小径",s="石爪小径是一条蜿蜒的地底隧道，穿过了灰谷与石爪山脉之间的山脊。这里没有敌对生物或旅客，是一条宁静的天然地下通道，连接着密斯特拉湖与狂风峭壁。",h="石爪小径是一条蜿蜒的地底隧道，穿过了灰谷与石爪山脉之间的山脊。这里没有敌对生物或旅客，是一条宁静的天然地下通道，连接着密斯特拉湖与狂风峭壁。",kw={"灰谷","洞穴","密斯特拉湖","石爪","石爪深处","石爪小径","隧道","狂风峭壁"},ang={["profession:Mining"]="洞穴蜿蜒的岩石壁龛直接切穿了山脉深处的基岩，使其成为在矿产丰富的灰谷与石爪山脉之间航行时的天然地标。"},sec={{t="静谧的山间通道",b="隐藏在分隔灰谷与石爪山脉的崎岖山脊之下，坐落着石爪小径，一条静谧的地下通路。这条通道将密斯特拉湖以西的森林直接与狂风峭壁的西北部区域连接起来。与充满掠食者和交战势力的危险地表路径不同，隧道内部极其平静，没有敌对野兽或营地，尽管岩壁上布满了扭曲的侧穴、裂隙和天然壁龛。在地面上方，依然残留着一条古老地表道路的痕迹，暗示着在这个受庇护的洞穴成为穿过石山的常用路线之前，旅客们曾经翻越过这些高耸的山峰。"}},faq={{q="石爪小径通向哪里？",a="这条隧道连接了灰谷西南部与石爪山脉东北部。它的北入口位于密斯特拉湖以西，南出口则通向狂风峭壁的西北侧。",al={"石爪小径通向哪里","石爪小径连接点","石爪隧道出口"}},{q="隧道里有怪物或敌人吗？",a="没有。洞穴内部异常平静，完全没有敌对怪物、野兽或友方NPC，对于穿梭于山脉分界线的旅客来说是一条安全的通道。",al={"石爪小径安全吗","石爪小径怪物","石爪小径威胁"}},{q="洞穴上方的废墟是什么？",a="一条杂草丛生的地表道路残迹沿着洞穴正上方的山脊延伸。这表明在通过这片空洞内部的通道开辟之前，曾经有一条更古老、更危险的陆路穿过这些峭壁。",al={"石爪小径上方的道路","石爪山脉陆路"}},{q="石爪小径是联盟还是部落的隧道？",a="没有任何阵营控制这条隧道。这是一片完全未设防的中立荒野，允许任何阵营的旅客在饱受争议的森林与山脉之间安全穿行。",al={"谁控制石爪小径","石爪小径阵营"}}},fx={["3cd0cb65"]={q="什么是石爪小径？",a="石爪小径是一条蜿蜒的地下隧道，直接穿凿山峰而过，为灰谷郁郁葱葱的森林与石爪山脉崎岖的高地之间提供了一条重要捷径。从灰谷密斯特拉湖以西进入后，旅人会在石爪山脉狂风峭壁西北部附近走出隧道。洞穴内部岔出一些奇特的小洞和死路，却仍是卡利姆多最安静的山间通道之一。",al={"石爪小径是什么","石爪小径隧道","石爪小径简介"}}},fp="14,267,21.684.0,35.211.0,48.194.0,36.211.0,46.198.0"}
P.entries["subzone:talondeep-vale"] = {n="Talondeep Vale",s="Talondeep Vale是位于灰谷中南部的一处宁静的森林低地。它毗邻银风避难所、星尘废墟以及通往石爪山脉的关口，是旅行者穿越卡利姆多南部时的一片静谧林荫道。",h="Talondeep Vale是位于灰谷中南部的一处宁静的森林低地。它毗邻银风避难所、星尘废墟以及通往石爪山脉的关口，是旅行者穿越卡利姆多南部时的一片静谧林荫道。",kw={"灰谷","星尘废墟","银风避难所","talondeep pass","石爪小径","talondeep vale"},ang={["race:NightElf"]="这些山谷小径坐落在密斯特拉湖的神圣水域和星尘废墟附近，对于在灰谷南部巡逻的哨兵和守望者来说，这里是他们熟悉的土地。"},sec={{t="一处隐蔽的山谷",b="Talondeep Vale隐藏在灰谷中南部茂密的树冠之下，是连接多处地标的十字路口。它的东面是银风避难所，附近有令人心悸的星尘废墟，还有通往石爪山脉的崎岖高地。在古树的遮蔽下，这座山谷依然是一片未被驯服的林地，暗夜精灵守望者、哨兵和往来的旅人穿行其间，往返于森林中心与远方的高耸峭壁。"}},faq={{q="Talondeep Vale位于何处？",a="Talondeep Vale位于灰谷的中南部，坐落在银风避难所、古老的星尘废墟以及通往石爪山脉的南向山口之间。",al={"talondeep vale在哪里","talondeep vale位置","如何找到talondeep vale"}},{q="穿过山谷向南的小径通向哪里？",a="沿着这条穿过山谷的小径走，旅行者会来到Talondeep Path，这是一条穿过崎岖高地的上升路径，直接将灰谷的林地与石爪山脉干旱的山峰连接起来。",al={"talondeep vale向南路径","talondeep pass通向哪里","通往石爪山脉的道路"}},{q="旅行者应该留意附近的哪些地标？",a="该山谷东侧毗邻银风避难所，以及水气充沛的星尘废墟，古老的暗夜精灵遗迹依然矗立在树冠之下。",al={"talondeep vale附近的地标","talondeep vale附近有什么"}}},fx={["5eca3f30"]={q="什么是Talondeep Vale？",a="Talondeep Vale是灰谷南部一处宁静而林木繁茂的山谷。它坐落在银风避难所与古老的星尘废墟之间，是通往石爪小径的葱郁入口；这条隧道穿过南部山脉，通往石爪地区。",al={"talondeep vale是什么","talondeep vale资料","talondeep vale简介"}}},fp="14,256,18.502.0,32.183.0,54.208.0,49.174.0"}
P.entries["subzone:tarren-mill"] = {n="塔伦米尔",s="塔伦米尔是一处位于希尔斯布莱德丘陵北部，奥特兰克山脉脚下的被遗忘者据点，处境艰难。这里曾经是一个宁静的人类农耕村庄，如今已成为部落在希尔斯布莱德的主要堡垒，与南方的联盟城镇南海镇陷入了不断的冲突之中。",h="塔伦米尔是一处位于希尔斯布莱德丘陵北部，奥特兰克山脉脚下的被遗忘者据点，处境艰难。这里曾经是一个宁静的人类农耕村庄，如今已成为部落在希尔斯布莱德的主要堡垒，与南方的联盟城镇南海镇陷入了不断的冲突之中。",kw={"奥特兰克","被遗忘者","希尔斯布莱德","希尔斯布莱德丘陵","洛丹伦","南海镇","辛迪加","塔伦米尔"},ang={["faction:Horde"]="塔伦米尔是你希尔斯布莱德丘陵中唯一的重大避难所，提供蝙蝠管理员、补给，以及对抗从南海镇入侵的联盟军队的重要军事支持。",["race:Undead"]="占据塔伦米尔扩张了希尔瓦娜斯女王的南部边境，将一座曾经引以为傲的洛丹伦农耕城镇变成了对抗生者的战略据点。"},sec={{t="从谷物到坟墓",b="在第三次战争之前，塔伦米尔是效忠于洛丹伦王国的一处繁荣的农业城镇。第二次战争期间，联盟军队在这里解救了被俘的高等精灵弓箭手，确保了奎尔萨拉斯对洛丹伦联盟的全面支持，这让塔伦米尔声名大噪。然而今天，城镇最初的活人居民已经消失，取而代之的是被遗忘者。城镇的建筑风化腐朽，田地荒芜，古老的磨坊一片死寂，而新的亡灵居民则在这里加固防御，以抵御来自山中野兽、辛迪加不法之徒以及联盟散兵游勇的不断威胁。"},{t="希尔斯布莱德前线",b="塔伦米尔是部落在该地区至关重要的前线作战基地。作为联盟港口南海镇的直接对手，连接这两个定居点之间的道路已经变成了一个公开的战区。部落的旅行者利用塔伦米尔来反击占领希尔斯布莱德的人类农夫和士兵，协调对丹加洛克的矮人挖掘者的袭击，并确保通往奥特兰克山脉雪峰的险峻道路安全。"}},faq={{q="目前谁控制着塔伦米尔？",a="塔伦米尔完全由被遗忘者控制，是部落在希尔斯布莱德丘陵的主要任务中心和前哨站。",al={"塔伦米尔的拥有者","塔伦米尔是部落还是联盟","塔伦米尔阵营"}},{q="为什么塔伦米尔和南海镇在战斗？",a="塔伦米尔代表了被遗忘者和部落在洛丹伦的南部势力范围，而南海镇则是联盟在该地区最后的重大据点。它们距离极近，使得持续的领土战争不可避免，双方都在争夺希尔斯布莱德肥沃的土地和战略要道的控制权。",al={"南海镇与塔伦米尔","为什么要与南海镇开战","希尔斯布莱德战争"}},{q="瘟疫爆发前的塔伦米尔是什么样的？",a="它曾是洛丹伦王国一个宁静的人类农耕和磨坊定居点。第二次战争期间，联盟士兵在这里著名的解救了被俘的高等精灵弓箭手，确保了奎尔萨拉斯与洛丹伦联盟达成的军事协议。",al={"塔伦米尔历史","以前这里住着谁","塔伦米尔背景故事"}},{q="除了联盟之外，塔伦米尔周围还有什么威胁？",a="除了南海镇的军队，塔伦米尔还必须应对当地的辛迪加匪徒、从奥特兰克山峰上下来的高原雪人和食人魔，以及在丘陵间游荡的凶猛山地野生动物。",al={"塔伦米尔的敌人","希尔斯布莱德的地方危险"}}},fx={["51e1ff94"]={q="什么是塔伦米尔？",a="塔伦米尔是希尔斯布莱德丘陵北部的一处前哨和聚居地，位于奥特兰克山脉南麓。这里曾是洛丹伦王国一个规模不大的农业社区，如今则是被遗忘者在该地区的主要堡垒，也是部落的据点，与南海镇的联盟势力形成直接对峙。",al={"塔伦米尔概况","这座镇子是什么","塔伦米尔简介"}},["7a0e9758"]={q="过去塔伦米尔发生过什么？",a="第二次战争期间，部落部队在镇子附近伏击了银月城的精灵弓箭手。泰瑞纳斯国王于是下令联盟军队前往营救俘虏，并巩固精灵与洛丹伦的联盟。第三次战争蹂躏王国后，当地的人类居民消失，被遗忘者便将这座饱经风霜的聚居地据为己有，作为集结据点。",al={"塔伦米尔历史","塔伦米尔的过往","第二次战争中的塔伦米尔"}},["3dc25634"]={q="塔伦米尔为何如此破败？",a="这座镇子历经第三次战争的浩劫、随后天灾军团的袭击，以及原有人类居民的消失。如今占据此地的被遗忘者主要将塔伦米尔视为战略军事集结地，而非舒适的家园，因此镇上的旧建筑、教堂和枯萎的果园都任其荒废衰败。",al={"塔伦米尔为何沦为废墟","塔伦米尔为何看起来破败不堪","破败的塔伦米尔"}},["4eb188ad"]={q="塔伦米尔危险吗？",a="塔伦米尔极其危险。它位于希尔斯布莱德动荡的前线，南海镇的联盟士兵和英雄不断发动袭击与反攻。除了联盟势力，辛迪加匪徒潜伏在附近的废墟中，山地雪人出没于北面的山坡，而凶残的克鲁什之脊食人魔也不断威胁着外围。",al={"塔伦米尔安全吗","塔伦米尔的危险","塔伦米尔的威胁等级"}}},fp="11,317,19.631.0,23.462.0,35.138.0,44.306.0,44.250.0,59.201.0"}
P.entries["subzone:temple-gardens"] = {n="神殿花园",s="神殿花园是达纳苏斯宁静的水域中心，环绕着Temple of the Moon以北的小岛屿。该区域装饰着桥梁和原始植被，设有城市银行和通往泰达希尔底部的神秘树洞传送门。",h="神殿花园是达纳苏斯宁静的水域中心，环绕着Temple of the Moon以北的小岛屿。该区域装饰着桥梁和原始植被，设有城市银行和通往泰达希尔底部的神秘树洞传送门。",kw={"银行","达纳苏斯","传送门","鲁瑟兰","泰达希尔","神殿花园","temple of the moon"},ang={["faction:Alliance"]="任何从码头乘船抵达的游客，都必须穿过鲁瑟兰传送门进入这片宁静的水域，才能前往城市的其他地方。",["race:NightElf"]="花园代表了荒野与城市建筑的和谐交融，这正是达纳苏斯文化的定义，在日常行政生活中提供了一处平静的反思之地。"},sec={{t="精灵首都之心",b="神殿花园横跨达纳苏斯中心的水域，是暗夜精灵首都的交通枢纽。木桥将这些经过精心修整的小岛与北部的塞纳里奥区、东部繁华的平台区以及南部宏伟的Temple of the Moon圣殿连接起来。暗夜精灵精心塑造了该区域流动的河水和茂密的植被，营造出宁静的氛围，为游客和女祭司们提供休憩之所。"},{t="泰达希尔之门",b="除了在其主岛上设有城市的中央金库和银行外，神殿花园对于进出世界之树的旅行者来说也至关重要。在花园的西岸矗立着一座巨大的、闪烁着粉红色光芒的树洞传送门。这座魔法拱门提供了一条通往泰达希尔底部鲁瑟兰村的瞬时通道，将孤立的树冠与海岸码头及飞行路线连接起来。"}},faq={{q="花园里那个发光的粉色传送门是什么？",a="花园西侧那个发光的树洞传送门是泰达希尔树冠与其底部之间的主要交通方式。穿过它，旅行者可以瞬间传送到鲁瑟兰村，在那里，船只和角鹰兽将暗夜精灵与黑海岸以及更广阔的世界连接起来。",al={"达纳苏斯树洞传送门","粉色树洞传送门","达纳苏斯传送门"}},{q="达纳苏斯的银行在哪里？",a="该市的主银行就位于神殿花园内，坐落在该区最大的中央岛屿上的一座开放式精灵凉亭中。",al={"达纳苏斯银行位置","银行在哪里","达纳苏斯银行职员"}},{q="为什么这里被称为神殿花园？",a="该区的名字来源于宏伟的Temple of the Moon，它就在花园的南侧边缘，与之毗邻。",al={"神殿花园名称由来","为什么叫神殿花园"}},{q="哪些区域与神殿花园相连？",a="从花园延伸出的桥梁横跨水面，连接着几乎每一个街区：北部的塞纳里奥区，东部的工匠区、战士区和商旅区，以及南部的Temple of the Moon。",al={"神殿花园通向哪里","神殿花园的桥梁"}}},fx={["15ee89a5"]={q="什么是神殿花园？",a="神殿花园是达纳苏斯葱郁而宁静的中心地带。这片风景优美的城区环绕着一座中央湖泊，拥有郁郁葱葱的小岛、蜿蜒的木桥，以及由暗夜精灵自然魔法滋养的精心修整的植物。城区的中央岛上设有城市银行，也是连接首都周边各层台地与月神殿的天然交通枢纽。",al={"达纳苏斯神殿花园","神殿花园是什么","神殿花园的传说"}},a5d2a9ad={q="神殿花园发生过什么？",a="第三次战争后，神殿花园与达纳苏斯其他区域一同建造在泰达希尔的枝干之上，成为一处供人欣赏美景、宁静沉思的场所。暗夜精灵看护者悉心引导水流、培育娇嫩的植物，营造出一片宁静的圣地，供祭司、领袖和访客沉思冥想。",al={"神殿花园的历史","神殿花园历史","神殿花园发生过什么"}},["6a127887"]={q="神殿花园危险吗？",a="完全不危险。花园位于达纳苏斯内部，受到哨兵守卫和首都防御设施的保护。这是城中最宁静、往来人数最多的城区之一，没有野兽或敌对威胁。",al={"神殿花园安全吗","神殿花园的危险","神殿花园危险吗"}}},fp="14,273,26.462.0,21.431.0,47.289.0,36.136.0,39.141.0,46.219.0"}
P.entries["subzone:temple-of-arkkoran"] = {n="亚考兰神殿",s="亚考兰神殿是一处古老的暗夜精灵遗迹，坐落在艾萨拉东北部的悬崖上，俯瞰着破碎海岸。这座建筑最初是为了供奉艾露恩而建，如今已残破不堪，被高大的海巨人亚考罗克和他麾下的水生奴仆所占据。",h="亚考兰神殿是一处古老的暗夜精灵遗迹，坐落在艾萨拉东北部的悬崖上，俯瞰着破碎海岸。这座建筑最初是为了供奉艾露恩而建，如今已残破不堪，被高大的海巨人亚考罗克和他麾下的水生奴仆所占据。",kw={"亚考罗克","艾萨拉","艾露恩","纳迦","鱼人","海巨人","破碎海岸","亚考兰神殿"},ang={["class:Priest"]="虽然风化的岩石间仍残留着古老的艾露恩符号，但这些饱受海浪侵蚀的遗迹中已不再有神圣的灵性。",["race:NightElf"]="看到一座艾露恩的神圣殿堂沦为纳迦和海巨人的巢穴，不禁让人痛心地想起一万年前失去的辉煌。"},sec={{t="被海洋占据的神圣遗迹",b="和散布在艾萨拉海岸上的许多宏伟遗迹一样，在天崩地裂摧毁了古老的暗夜精灵帝国之前，亚考兰神殿曾是供奉月神艾露恩的圣所。今天，它那风化的大理石台阶和破碎的柱廊已被潮汐怪物所侵占。海巨人亚考罗克坐镇神殿的最高层，周围簇拥着忠诚的纳迦和凶猛的鱼人，他们暴力地驱逐着任何胆敢靠近这片海岸的陆地入侵者。"}},faq={{q="亚考兰神殿最初的用途是什么？",a="在被称为现在的名字之前，这座建筑是一座供奉艾露恩的暗夜精灵神殿。它在大分裂中与周围其他的沿海文明一同化为了废墟。",al={"亚考兰神殿历史","谁建造了亚考兰神殿","这是什么神殿"}},{q="亚考罗克是谁？",a="亚考罗克是一位强大的海巨人，他将这座曾经的暗夜精灵神殿作为了自己的家。他居住在遗迹的最高平台上，统领着周围的海岸以及栖息在那里的海洋生物。",al={"亚考罗克是谁","海巨人亚考罗克","谁统治亚考兰"}},{q="哪些生物守卫着神殿区域？",a="神殿及其周围的梯田由好斗的纳迦和鱼人巡逻，包括亚考兰钳蟹、钳虫和泥沼居住者。破碎海岸的周边海滩也是多头蛇和其他海巨人的栖息地。",al={"亚考兰神殿的怪物","亚考兰神殿里居住着什么","亚考兰神殿的敌人"}}},fp="18,270,37.478.0,53.228.0,16.208.0,40.238.0"}
P.entries["subzone:temple-of-atal-hakkar"] = {n="阿塔哈卡神庙",s="阿塔哈卡神庙，通常被称为沉没的神庙，是一座由被流放的巨魔祭司建造的被淹没的堡垒，旨在供奉鲜血之神哈卡。数百年前，这座神庙被绿龙军团沉入沼泽之下，其淹没的大厅至今仍是禁忌仪式和黑暗腐化的温床。",h="阿塔哈卡神庙，通常被称为沉没的神庙，是一座由被流放的巨魔祭司建造的被淹没的堡垒，旨在供奉鲜血之神哈卡。数百年前，这座神庙被绿龙军团沉入沼泽之下，其淹没的大厅至今仍是禁忌仪式和黑暗腐化的温床。",kw={"阿塔莱","阿塔哈卡","伊兰尼库斯","哈卡","预言者迦玛兰","泪水之池","沉没的神庙","悲伤沼泽","伊瑟拉"},ang={["class:Druid"]="神庙深处伊瑟拉绿龙卫士的腐化直击翡翠梦境的核心，需要迅速展开调查。",["race:Troll"]="对于暗矛巨魔来说，这些废墟是对毁灭了古老古拉巴什帝国的血腥疯狂以及夺灵者哈卡永恒威胁的残酷提醒。"},sec={{t="绿龙军团的愤怒",b="一千多年前，阿塔莱祭司试图召唤夺灵者哈卡，这场灾难性的内战摧毁了古拉巴什帝国。幸存的狂热分子被流放到北方，在悲伤沼泽中建造了一座巨大的石质神庙，试图完成他们的黑暗使命。绿龙女王伊瑟拉得知了他们的阴谋，将这座金字塔建筑砸入泥潭深处，使其房间被淹没在泪水之池下。绿龙卫士们被留下来看守这片淹没的废墟，确保哈卡的回归被永远阻止。"},{t="沉睡变为梦魇",b="神庙的沉没并没有埋葬这个邪教，反而让阿塔莱人获得了隔离的空间，得以不受干扰地继续进行他们令人毛骨悚然的献祭。几个世纪以来，腐化开始从内部侵蚀守护者们；龙族哨兵陷入疯狂，而由预言者迦玛兰指引的阿塔莱人，正在为哈卡的化身铺平道路。如今，部落和联盟都在密切关注着这座淹没的金字塔，沼泽深处不断传出神秘的流言。"}},faq={{q="为什么神庙会在水下？",a="绿龙军团的守护巨龙伊瑟拉亲自将神庙压入沼泽的水下，以阻止阿塔莱巨魔将鲜血之神哈卡召唤到艾泽拉斯。",al={"为什么是沉没的神庙","谁沉没了神庙","神庙是如何沉没的"}},{q="谁是阿塔莱？",a="阿塔莱是一个狂热的巨魔祭司教派，因修习血魔法并试图将夺灵者哈卡召唤到物质位面而从南方的古拉巴什帝国被流放。",al={"阿塔莱背景故事","谁建造了沉没的神庙","阿塔莱祭司"}},{q="为什么这里会有绿龙？",a="伊瑟拉指派了一群绿龙来看守这片沉没的废墟，并将闯入者拒之门外，确保哈卡永远无法被召唤。不幸的是，许多守护者已经沦为疯狂和黑暗腐化的牺牲品。",al={"为什么沼泽里有龙","绿龙军团沉没的神庙"}},{q="如何进入神庙内部？",a="你必须从泪水之池游入被淹没的废墟，穿过Broken Hall里淹没的通道，然后沿着像Hall of Masks这样的石廊向上前行。",al={"如何进入沉没的神庙","沉没的神庙入口","如何进入阿塔哈卡"}}},fp="21,301,25.529.0,26.462.0,29.183.0,20.188.0,33.223.0,33.178.0"}
P.entries["subzone:temple-of-the-moon"] = {n="Temple of the Moon",s="Temple of the Moon坐落在达纳苏斯，是暗夜精灵人民的精神中心，也是泰达希尔的政府所在地。这座圣殿由大祭司泰兰德·语风主持，是The Sisterhood of Elune的总部。它高耸的大理石阶梯内供奉着一口神圣的月亮井，井中受过祝福的井水能带来治疗，并让人与月亮女神沟通。",h="Temple of the Moon坐落在达纳苏斯，是暗夜精灵人民的精神中心，也是泰达希尔的政府所在地。这座圣殿由大祭司泰兰德·语风主持，是The Sisterhood of...",kw={"达纳苏斯","海德恩","月亮井","the sisterhood of elune","泰达希尔","艾露恩神殿","temple of the moon","泰兰德·语风"},ang={["class:Priest"]="对于联盟牧师——特别是暗夜精灵——来说，这座神殿代表着艾露恩神圣旨意的最高源泉，也是他们最高导师的所在地。",["race:NightElf"]="这座神殿是现代卡多雷文化、精神和市政生活的核心，将The Sisterhood of Elune和泰达希尔的治理统一于一个屋檐之下。"},sec={{t="月亮女神圣殿",b="Temple of the Moon在第三次战争后暗夜精灵定居泰达希尔时不久建成，是现代卡多雷亲手建造的规模最大的石质建筑之一。它的大部分大理石开采自卡利姆多大陆，并通过魔法手段跨海运输而来。在其内部中心处坐落着一口广阔的月亮井，上方伫立着海德恩的雕像，神圣的井水散发着静谧的力量。除了作为朝圣者的礼拜和静思之所，该神殿还是达纳苏斯的政治核心，大祭司泰兰德·语风在此坐镇，引导她的人民走过这个充满不确定性的新时代之初。"},{t="姐妹会的堡垒",b="在神殿宁静的露台上，The Sisterhood of Elune的祭司们在精神和战术层面上执行着女神的意志。由此出发，使者和派遣的姐妹们被派往卡利姆多北部各地，以调查威胁或向当地哨兵提供援助，例如温尼斯·布莱葛祭司在黑海岸沿线的调查工作。新手和资深祭司们聚集在星光穹顶下，研修神圣的法术，照料伤员，并守卫密室免受外界腐化的侵扰。"}},faq={{q="谁领导着Temple of the Moon？",a="大祭司泰兰德·语风主持着这座神殿。作为The Sisterhood of Elune的领袖和卡多雷政府的事实首脑，她在高层阶梯上举行朝会，指导着达纳苏斯的精神和军事事务。",al={"temple of the moon领袖","神殿里有哪些人","泰兰德位置"}},{q="神殿在泰达希尔上是如何建造的？",a="虽然泰达希尔是从跨海而来的大树枝上生长出来的，但神殿本身是达纳苏斯为数不多的几座大型石质建筑之一。它的大理石和砖石开采自卡利姆多大陆，并利用魔法运输手段移至世界之树的顶端。",al={"temple of the moon如何建造","达纳苏斯石质神殿起源"}},{q="神殿中央的水池是什么？",a="中央水池是一口神圣的月亮井，由海德恩的雕像守护。其井水深受圣化，并被尊为艾露恩的直接祝福，The Sisterhood of Elune利用它进行净化仪式、冥想和强大的恢复魔法。",al={"神殿月亮井","temple of the moon中的水"}},{q="玩家可以在这里找到什么服务？",a="该神殿是达纳苏斯牧师训练的主要中心。冒险者也会来到这里向大祭司泰兰德·语风报告，并接受由The Sisterhood of Elune派发的指导或任务。",al={"艾露恩神殿里有什么","达纳苏斯神殿训练师"}}},fx={["18c3233a"]={q="什么是Temple of the Moon？",a="Temple of the Moon是供奉艾露恩的宏伟圣所，也是暗夜精灵的精神中心。它是泰达希尔上规模最大的石制建筑之一，既是艾露恩姐妹会的圣地，也是达纳苏斯实际上的执政中心，泰兰德·语风大祭司便居于此处。",al={"达纳苏斯temple of the moon","这座神殿是什么","达纳苏斯艾露恩神殿"}},fde18cfb={q="Temple of the Moon发生过什么？",a="月神殿在第三次战争后与达纳苏斯一同建造，建筑所用的石料由魔法从大陆运来。自建成以来，这里一直是指挥中心，泰兰德·语风大祭司与艾露恩姐妹会在此处理事务，并为卡多雷提供精神指引。",al={"temple of the moon历史","这里发生过什么","艾露恩神殿历史"}},["7506a07b"]={q="Temple of the Moon危险吗？",a="对于暗夜精灵的盟友而言，这里完全不危险。它是整个泰达希尔最安全、最宁静的圣所之一，由经验丰富的女祭司、哨兵和大祭司亲自守护。然而，胆敢将敌意或腐化带入艾露恩圣所的人，必将遭到迅速而致命的惩罚。",al={"temple of the moon危险吗","这里安全吗","艾露恩神殿的危险"}},["7361c49d"]={q="为什么叫Temple of the Moon？",a="这座圣所供奉着艾露恩，她是卡多雷所敬仰的月亮女神。暗夜精灵视她为族人的母亲和神圣之光的源泉，因此以她璀璨的圣辉为名，命名了他们最宏伟的殿堂与圣所。",al={"为何叫temple of the moon","神殿名称的由来","为何命名为temple of the moon"}}},fp="18,378,29.664.0,24.544.0,33.245.0,39.261.0,45.247.0,36.220.0"}
P.entries["subzone:temple-of-zin-malor"] = {n="辛玛洛神殿",s="辛玛洛神殿是一座位于艾萨拉埃达拉斯废墟中的古老暗夜精灵圣所。这座日渐崩塌的建筑最初是为月亮女神艾露恩而建，如今则被毒蛇纳迦占据，由督军克雷里安直接指挥。",h="辛玛洛神殿是一座位于艾萨拉埃达拉斯废墟中的古老暗夜精灵圣所。这座日渐崩塌的建筑最初是为月亮女神艾露恩而建，如今则被毒蛇纳迦占据，由督军克雷里安直接指挥。",kw={"亚考兰","艾萨拉","辛玛洛水晶","埃达拉斯","克雷里安","毒蛇纳迦","辛玛洛"},ang={["class:Priest"]="尊崇艾露恩的祭司传统深深烙印在这些石头中，它们展现的神殿布局与现代达纳苏斯姐妹会所保留的布局如出一辙。",["race:NightElf"]="走在辛玛洛的废墟中，让人痛苦地回想起上层精灵的时代，以及纳迦那悲剧性的堕落，他们现在亵渎了曾经供奉艾露恩的神圣土地。"},sec={{t="月影回响",b="在大分裂之前，辛玛洛神殿曾是一座宏伟的礼拜堂，供奉着艾露恩。其建筑风格与附近的亚考兰神殿以及达纳苏斯现代的Temple of the Moon如出一辙，拥有大分裂前暗夜精灵文明标志性的优雅、流线型石雕。然而今天，它那沐浴月光的云石早已风化破碎，被蛇身的毒蛇纳迦所占据。这些入侵者占领了这片神圣的土地，将原本宁静的沉思之地变成了军事堡垒。"},{t="被窃的水晶",b="这座神殿曾存放着著名的辛玛洛水晶，那是一件强大的神器，很久以前就被带到了冬泉谷的凯尔希里尔。"}},faq={{q="现在是谁控制着辛玛洛神殿？",a="神殿现被毒蛇纳迦部族占据。他们在该地区的领袖督军克雷里安就居住在神殿建筑内部。",al={"谁在辛玛洛神殿","谁住在辛玛洛神殿","辛玛洛神殿的首领是谁"}},{q="这座神殿最初是做什么用的？",a="它最初是由古代暗夜精灵在大分裂之前建造的，是崇敬月亮女神艾露恩的圣地。",al={"谁建造了辛玛洛神殿","辛玛洛神殿原本是什么"}},{q="为什么它看起来和达纳苏斯的那座神殿那么像？",a="辛玛洛神殿与亚考兰神殿有着共同的经典暗夜精灵建筑根源，两者的设计都与达纳苏斯现代的Temple of the Moon非常相似。",al={"与达纳苏斯神殿的相似之处","辛玛洛神殿的建筑"}},{q="辛玛洛水晶是什么？",a="它是一件古老的魔法遗物，最初存放在神殿内。很久以前，它被位于冬泉谷冰封大地深处的凯尔希里尔的居民偷走了。",al={"辛玛洛水晶在哪里","辛玛洛水晶"}}},fp="19,260,18.553.0,18.137.0,43.141.0,40.140.0,54.183.0,33.176.0"}
P.entries["subzone:terrace-of-repose"] = {n="休息区",s="休息区是一处位于提瑞斯法林地血色修道院入口外的纯净庭院花园。该区域由血色十字军维护，它是洛丹伦北部极少数完全未受亡灵瘟疫侵蚀的地方之一，拥有绿色的树篱和洁净的水源。",h="休息区是一处位于提瑞斯法林地血色修道院入口外的纯净庭院花园。该区域由血色十字军维护，它是洛丹伦北部极少数完全未受亡灵瘟疫侵蚀的地方之一，拥有绿色的树篱和洁净的水源。",kw={"喷泉","树篱","亡灵瘟疫","血色十字军","血色修道院","休息区","提瑞斯法林地","未受腐蚀"},ang={["class:Paladin"]="在提瑞斯法林地看到生机勃勃的植物和未受污染的水源，这强有力地证明了这片土地拥有治愈的潜力，即使它目前是由顽固的狂热分子所照料的。",["race:Undead"]="对于被遗忘者来说，露台那纯净的绿色是那个排斥他们的生者世界鲜明而苦涩的提醒，而维护这一切的正是那些只想将他们这类存在从洛丹伦彻底清除的凡人敌人。"},sec={{t="枯萎之地的一片绿洲",b="休息区位于血色修道院宏伟入口的正北方，它与提瑞斯法林地腐烂的森林形成了超现实的鲜明对比。当洛丹伦的其他地方在灰色迷雾、腐败土壤和停滞的沼泽下窒息时，这片露台却拥有郁郁葱葱、修剪整齐的树篱，以及由清新、未受污染的水源供应的喷泉。对于血色十字军的狂热信徒来说，这座花园是他们神圣的正义与纯洁的实证，是一座神圣的堡垒，证明了虔诚的信仰可以抵御天灾军团的腐化。"}},faq={{q="为什么在提瑞斯法林地已经死寂的情况下，这里的草地和水源依然洁净？",a="休息区并未受到亡灵瘟疫的侵染。通过时刻的警惕，或许还有他们对圣光的坚定信仰，血色十字军保护了这里的土壤，种植了茂盛的树篱，并维持着不受周围腐烂影响的清澈、新鲜的水源供应。",al={"为什么这里是绿色的","血色修道院 洁净水源","休息区 未受腐蚀"}},{q="休息区的具体位置在哪里？",a="它位于提瑞斯法林地东北部的丘陵地带，就在血色修道院建筑群的入口处。",al={"休息区在哪里","休息区位置","修道院花园入口"}},{q="十字军用这个露台做什么？",a="除了作为他们防御森严的修道院的前厅外，它还提供了一处未受腐蚀的宁静避难所，十字军可以在此休息、反思，并瞻仰第三次战争前洛丹伦王国的理想化景象。",al={"血色十字军花园用途","休息区的目的"}}},fx={f618a338={q="什么是休息区？",a="休息区是一处宁静的庭院，位于血色修道院正门以北。这里由血色十字军严密看守，是洛丹伦北部少数仍然完好的地方之一，拥有修剪整齐的绿篱和清澈流淌的泉水，未受天灾军团的腐化侵蚀。",al={"休息区是什么","血色修道院休息区","休息区简介"}},["310f02b5"]={q="谁控制着休息区？",a="休息区由血色十字军维护并控制。它紧邻这支军团庞大的修道院据点，是一处由十字军哨兵和神职人员看管的户外休憩地兼防御花园。他们决心保留洛丹伦沦陷前的景象，让这片土地成为一隅旧日风貌的留存之地。",al={"谁住在休息区","谁控制休息区","休息区所属阵营"}},["538b338a"]={q="休息区危险吗？",a="对于血色十字军以外的人来说，这里极其危险。十字军狂热地在此巡逻，会当场攻击任何入侵者，无论对方是被遗忘者、部落成员，还是不隶属于任何阵营、冒险接近修道院大门的旅人。",al={"休息区危险吗","休息区的威胁","我能去休息区吗"}}},fp="17,314,22.565.0,60.300.0,47.135.0,42.239.0"}
P.entries["subzone:terror-run"] = {n="恐惧小道",s="恐惧小道是位于安戈洛环形山西南部的一片险恶土地，位于巨痕谷虫群巢穴的正西方。正如其令人胆寒的名字一样，这片区域到处都是掠食野兽，从巨大的魔暴龙到贪婪的异龙，还有俯冲的翼龙，应有尽有。",h="恐惧小道是位于安戈洛环形山西南部的一片险恶土地，位于巨痕谷虫群巢穴的正西方。正如其令人胆寒的名字一样，这片区域到处都是掠食野兽，从巨大的魔暴龙到贪婪的异龙，还有俯冲的翼龙，应有尽有。",kw={"魔暴龙","异龙","马绍尔探险队","翼龙","红色能量水晶","巨痕谷","恐惧小道","安戈洛"},ang={["class:Hunter"]="恐惧小道广阔的平原是一处致命的试炼场，拥有卡利姆多最凶猛的一些野兽——从迅猛的迅猛龙和野蛮的翼龙，到高耸的魔暴龙。"},sec={{t="开阔地带的狩猎",b="恐惧小道横跨安戈洛环形山西南部的台地，名副其实地充满了令人不安的传闻。凶猛的翼龙在潮湿的空中盘旋，而巨大的异龙、剑龙和顶级的魔暴龙则在下方的低矮灌木丛中游荡。该区域位于环形山边缘的阴影之下，紧邻巨痕谷那些发出吱吱声的异形土堆，地理位置十分尴尬。在这片平原的东侧边缘，散落着威利德·马绍尔探险队遗留下的营地废墟，这令人清醒地提醒着人们，当环形山的原始掠食者逼近时，那些措手不及的研究人员遭遇了怎样的下场。"},{t="红色水晶与远古掠食者",b="除了聚集着大量饥饿的动物群之外，恐惧小道还因其独特的地质特征而吸引着博物学家和冒险者：它是环形山中唯一能从肥沃土壤中挖掘出奇异的红色能量水晶的主要区域。这些深红色的结晶散发着原始的能量，与盆地其他地方发现的蓝色、绿色和黄色水晶类似。然而，想要活得足够久去收集它们，就意味着要与平原上的统治级猎手进行抗衡——包括那些绝不允许深南部出现任何闯入者的筑巢魔暴龙。"}},faq={{q="为什么这个区域叫作恐惧小道？",a="这个名字反映了潜伏在这条开阔走廊上的致命顶级掠食者。面对巨大的魔暴龙、领地意识极强的异龙，以及头顶上虎视眈眈的翼龙，任何步行穿越这片平原的人，都极有可能不得不拼命奔逃以求活命。",al={"恐惧小道名字含义","为什么叫恐惧小道","谁为恐惧小道命名"}},{q="除了危险的野兽，这里还能找到什么？",a="恐惧小道是安戈洛环形山中唯一可以从大地上采集到红色能量水晶的区域。你还能在它的东侧边缘找到一个废弃的研究营地，那是威利德·马绍尔的探险队在对环形山进行危险的勘测时丢下的。",al={"恐惧小道里有什么","恐惧小道水晶","恐惧小道资源"}},{q="东侧边缘的废弃营地是什么？",a="那个废弃的营地属于威利德·马绍尔探险队的成员。当当地的野生动物冲垮他们的阵地时，科学家和探险家们被迫放弃了他们的研究设备并仓皇逃离。",al={"马绍尔营地恐惧小道","废弃研究营地","失踪的探险队营地"}},{q="恐惧小道相对于其他地标的位置在哪里？",a="它跨越了安戈洛环形山的西南部，位于被虫群侵扰的巨痕谷蜂巢正西方，以及中心火山火羽山的南面。",al={"恐惧小道位置","恐惧小道在哪里"}}},fp="10,310,18.617.0,34.534.0,35.276.0,48.257.0,47.214.0,57.172.0"}
P.entries["subzone:terror-wing-path"] = {n="龙翼小径",s="龙翼小径是一条蜿蜒穿过燃烧平原东部的岩石峡谷。这里遍布着黑龙军团的幼龙和龙人，是前往平原东北部偏远角落的一条危险通道。",h="龙翼小径是一条蜿蜒穿过燃烧平原东部的岩石峡谷。这里遍布着黑龙军团的幼龙和龙人，是前往平原东北部偏远角落的一条危险通道。",kw={"黑龙军团","燃烧平原","龙人","赤脊山山口","龙翼小径","幼龙"},ang={["class:Hunter"]="陡峭的地形和飞行的幼龙使龙翼小径成为了狙击手们在烟雾和峡谷风中追踪龙类野兽的试炼场。"},sec={{t="龙人栖息地",b="龙翼小径开凿在燃烧平原东部布满灰烬的崎岖山脚下，因其出没的空中掠食者和龙兽而得名。黑龙军团的族群在这些峡谷中徘徊，凶猛地守卫着龙蛋，并捕猎任何愚蠢到闯入它们阴影下的生物。灰烬和煤烟覆盖着石质小径，使得峡谷绝壁下的每一次跋涉都险象环生。"},{t="危险的通道",b="黑龙在峡谷中巡逻，偶尔还能看到罕见的熔岩巨人沃尔查恩在此徘徊。只有经验最丰富的冒险者才敢踏上这段旅程，而且很少独自行动，但这却是前往平原东北尽头隐藏的滑石洞穴的唯一途径。"}},faq={{q="龙翼小径里生活着哪些生物？",a="这条小径里到处都是黑龙军团的幼龙、龙崽和体型更大的龙人。它们在山坡上积极巡逻，并在东部的山口捕猎地面上的猎物。",al={"龙翼小径怪物","这里有什么","龙翼小径龙人"}},{q="龙翼小径通向哪里？",a="它蜿蜒穿过燃烧平原的东侧，一直通往该地区东北部的偏远角落，滑石洞穴就隐藏在那里。",al={"龙翼小径通向何处","龙翼小径路线","龙翼小径指引"}},{q="为什么黑龙军团在这个峡谷里活动？",a="黑龙军团在黑石山下的燃烧平原保持着强大的控制力。龙翼小径为它们提供了筑巢地、狩猎场，以及保卫黑石山侧翼的东部防线。",al={"为什么巨龙在这里","龙翼小径黑龙军团","龙军团势力"}}},fp="16,239,17.411.0,18.300.0,40.173.0,33.156.0,52.214.0"}
P.entries["subzone:terrordale"] = {n="恐惧谷",s="恐惧谷是一座荒废且闹鬼的定居点，坐落在东瘟疫之地的西北边缘。这座废弃的城镇毗邻受腐蚀的病木林和恶蛛隧道，到处都是天灾军团和不安的死者。",h="恐惧谷是一座荒废且闹鬼的定居点，坐落在东瘟疫之地的西北边缘。这座废弃的城镇毗邻受腐蚀的病木林和恶蛛隧道，到处都是天灾军团和不安的死者。",kw={"受创的奥古斯都","战马","东瘟疫之地","伊根","格雷森·沙东布瑞克公爵","病木林","恐惧谷","恶蛛隧道"},ang={["class:Paladin"]="恐惧谷是资深圣骑士的关键试炼场；格雷森·沙东布瑞克公爵要求获得战马资格的候选人冒险进入这座废墟小村，去驱除那里哭泣的灵魂。",["race:Human"]="恐惧谷破败的房屋无声地提醒着洛丹伦北部的沦陷，普通平民的灵魂至今仍被困在死亡之中，徘徊在他们曾经的家门前。"},sec={{t="林边的一处闹鬼避难所",b="恐惧谷曾是洛丹伦北部一处宁静的定居点，但在王国沦陷时，它也随之落入了天灾军团手中。如今，这座村庄在恶蛛隧道的入口附近已沦为凄凉的废墟。街道上充斥着不安的幽灵和游荡的亡灵，而周围病木林的树木正不断侵蚀着村庄腐朽的木梁。在这片荒凉之地，只有少数古怪的居民敢于留下——比如那名奇特的商人奥古斯都，以及正试图解救被困在两界之间的受苦灵魂的幽灵猎人伊根。"},{t="灵异扰动与驱魔",b="恐惧谷毁灭时的痛苦如此深重，以至于物理世界在灵界的折磨下都显得有些扭曲。恐惧谷的灵魂因其悲惨的结局而被束缚在尘世，陷入永恒的痛苦之中。由于这种集中的精神腐化，在白银之手和格雷森·沙东布瑞克公爵的指导下，经验丰富的圣骑士被派往此处执行审判与牺牲的仪式，将这些折磨作为圣光的神圣试炼来消除。"}},faq={{q="恐惧谷是什么地方？",a="恐惧谷是东瘟疫之地西北部一座荒废的废墟小村。它位于病木林以西，恶蛛隧道以南，完全被天灾军团的恐怖生物和备受折磨的幽灵所占据。",al={"恐惧谷在哪里","这是什么城镇","恐惧谷背景故事"}},{q="还有谁待在这座城镇里？",a="两名古怪的人物徘徊在废墟之中：伊根，一位试图安抚并解救被困灵魂的勇敢幽灵猎人；以及“受创的”奥古斯都，一位半疯的亡灵隐士兼商人，执着于找回他旧时的账本和财物。",al={"伊根是谁","奥古斯都是谁","恐惧谷中的npc"}},{q="这座城镇与圣骑士试炼有什么联系？",a="格雷森·沙东布瑞克公爵会将那些寻求获得神圣战马的圣骑士送往恐惧谷。圣骑士必须使用驱魔香炉来驱逐此处的受折磨灵魂，以展现身为圣光精英骑士所需的精神决心、审判与牺牲精神。",al={"恐惧谷圣骑士战马","驱除恐惧谷","格雷森·沙东布瑞克公爵"}}},fp="10,252,34.553.0,34.478.0,19.219.0,37.245.0,46.283.0"}
P.entries["subzone:terrorweb-tunnel"] = {n="恶蛛隧道",s="恶蛛隧道是一条开凿在恐惧谷和索多里尔河之间的地下通道，穿过山脉。这里盘踞着天灾军团的不死尼鲁布穴居恶魔，构成了东瘟疫之地西界的一条危险的地下捷径。",h="恶蛛隧道是一条开凿在恐惧谷和索多里尔河之间的地下通道，穿过山脉。这里盘踞着天灾军团的不死尼鲁布穴居恶魔，构成了东瘟疫之地西界的一条危险的地下捷径。",kw={"穴居恶魔","尼鲁布人","尼鲁布监工","恐惧谷","恶蛛隧道","索多里尔河","提里奥·弗丁"},ang={["class:Paladin"]="隧道的南出口距离被流放的圣骑士提里奥·弗丁仅有几步之遥，他驻扎在这个腐烂的巢穴附近，独自监视着天灾军团的蔓延。"},sec={{t="地下虫患",b="恶蛛隧道笔直地穿过了索多里尔河两岸的山脉，将受污染的恐惧谷村庄与南面的河岸连接起来。与常见的食尸鬼或骷髅哨兵不同，这条黑暗的地下通道完全被穴居恶魔占据——这些木乃伊化的尼鲁布蜘蛛是被巫妖王复活并强行奴役的。穿过这条通道可以省去绕行山坡的长路，但需要穿越厚厚的蛛网，并避开巡逻在黑暗中的高大尼鲁布监工。"}},faq={{q="恶蛛隧道通向哪里？",a="隧道直接穿过了恐惧谷西北部的山脉。它的北入口通往恐惧谷，而南出口则通向索多里尔河畔的岩石河岸。",al={"恶蛛隧道路径","恶蛛隧道去哪","恶蛛隧道连接"}},{q="隧道里栖息着什么生物？",a="隧道里挤满了穴居恶魔，这些来自古老诺森德的不死尼鲁布蛛魔被复活并编入了天灾军团。在它们之中，强大的尼鲁布监工偶尔会在隧道内徘徊，使得通行变得极其危险。",al={"恶蛛隧道怪物","谁住在恶蛛隧道","恶蛛隧道生物"}},{q="隧道外附近有什么人？",a="被流放的圣骑士提里奥·弗丁在索多里尔河边维持着一个小营地，就在隧道南出口附近。",al={"恶蛛隧道外面是谁","恶蛛隧道附近的提里奥","恶蛛隧道附近的npc"}},{q="为什么瘟疫之地会有尼鲁布人？",a="在巫妖王征服了诺森德的地下王国艾卓-尼鲁布后，他将阵亡的尼鲁布人复活为穴居恶魔。当天灾军团入侵洛丹伦时，这些蛛魔突击部队被部署到南方，以巩固The Cult of the Damned对该地区的控制。",al={"为什么这里有穴居恶魔","瘟疫之地的尼鲁布人"}}},fp="16,272,26.538.0,33.207.0,34.240.0,33.134.0,37.271.0"}
P.entries["subzone:thalanaar"] = {n="萨兰纳尔",s="萨兰纳尔是一个隐蔽的暗夜精灵前哨站，坐落在菲拉斯葱郁的荒野与千针石林干旱的峡谷之间的边界上。作为联盟进入菲拉斯的主要东部门户，它为疲惫的旅人提供了一个至关重要的角鹰兽栖息处，以及树冠下的庇护所。尽管规模不大，但它是卡利姆多大陆与偏远的羽月要塞之间关键的连接点。",h="萨兰纳尔是一个隐蔽的暗夜精灵前哨站，坐落在菲拉斯葱郁的荒野与千针石林干旱的峡谷之间的边界上。作为联盟进入菲拉斯的主要东部门户，它为疲惫的旅人提供了一个至关重要的角鹰兽栖息处，以及树冠下的庇护所。尽管规模不大，但它是卡利姆...",kw={"卡莉丝·月猎","羽月","菲拉斯","飞行管理员","哨兵","萨兰纳尔","千针石林","部落制皮"},ang={["faction:Alliance"]="当你从千针石林危险的台地向西挺进，进入菲拉斯未驯化的丛林时，萨兰纳尔为你提供了第一个安全港湾和可靠的飞行枢纽。",["race:NightElf"]="该前哨站作为一个哨岗，时刻监视着边界，欢迎族人回归到菲拉斯古老树冠下的祖辈阴影之中。"},sec={{t="被遗忘荒野的门户",b="萨兰纳尔矗立在自然的咽喉要道上，千针石林被烤焦的砂岩在这里让位于菲拉斯茂密而多雾的树冠，它是东来旅人所见到的第一个暗夜精灵据点。它不过是一个设有几座坚固亭台和岗哨的堡垒化林地，但其地理位置却至关重要。该前哨站为深入未驯化森林的联盟侦察兵、信使和工匠提供了庇护，是抵御南部卡利姆多游荡的野兽、食人魔和部落军队的坚实阵地。"},{t="重要的空中枢纽",b="由于穿越南部卡利姆多的陆路旅行充满危险，萨兰纳尔的主要功能是后勤保障。它的角鹰兽管理员将偏远的菲拉斯荒野与尘泥沼泽的塞拉摩岛、塔纳利斯的加基森以及西部的羽月要塞直接相连。工匠们也会前来此处朝圣，寻求那些在林荫下传授古老野生皮革加工技艺的制皮大师的教导。"}},faq={{q="什么是萨兰纳尔？",a="萨兰纳尔是一个小型暗夜精灵边境营地，位于菲拉斯的东部入口，正处于该地区与千针石林的交界处。它作为一个联盟前哨站，提供庇护、基本补给和飞行运输服务。",al={"萨兰纳尔概览","这是什么地方","萨兰纳尔营地"}},{q="飞行管理员能把我送到哪里？",a="萨兰纳尔的角鹰兽栖息处连接着菲拉斯西海岸外的羽月要塞、尘泥沼泽的塞拉摩岛，以及塔纳利斯的中立地精港口加基森。",al={"萨兰纳尔飞行点","我能飞到哪里","萨兰纳尔飞行管理员"}},{q="工匠为什么要前往萨兰纳尔？",a="该前哨站是卡莉丝·月猎的所在地，她是致力于部落制皮这一隐秘传统的导师，吸引着来自卡利姆多各地的熟练工匠。",al={"萨兰纳尔导师","萨兰纳尔制皮","卡莉丝·月猎"}},{q="萨兰纳尔对部落冒险者安全吗？",a="不安全。萨兰纳尔是一个坚定的联盟定居点，由暗夜精灵哨兵守卫，她们会攻击任何见到的部落成员。",al={"萨兰纳尔对部落友好吗","萨兰纳尔的部落"}}},fp="9,422,35.537.0,19.455.0,18.223.0,36.186.0,38.172.0,40.128.0"}
P.entries["subzone:thalassian-base-camp"] = {n="萨拉斯营地",s="萨拉斯营地坐落在艾萨拉北部的一处高脊之上，这里是血精灵远征队挖掘古代奥术遗物的据点。虽然最初是在与部落达成协议的情况下获得资助的，但营地的领导者在挖掘工作开始后很快就背弃了诺言。现在，在红色的帐篷和被粉碎的魔法制品中，一些更黑暗的召唤仪式暗示了他们真正的目标。",h="萨拉斯营地坐落在艾萨拉北部的一处高脊之上，这里是血精灵远征队挖掘古代奥术遗物的据点。虽然最初是在与部落达成协议的情况下获得资助的，但营地的领导者在挖掘工作开始后很快就背弃了诺言。现在，在红色的帐篷和被粉碎的魔法制品中，一...",kw={"艾萨拉","背叛","闪光尘埃","霍克海姆","魔导师霍克海姆","大法师雷姆托里","雷姆托里","萨拉斯营地","乌索兰"},ang={["class:Mage"]="血精灵将遗物精炼成闪光尘埃的独特方式提供了一个罕见且危险的视角，让人们得以一窥即使是大法师克希雷姆也感兴趣的萨拉斯技术。",["faction:Horde"]="部落不会轻视背信弃义的行为；大法师雷姆托里拿走了你们的钱却只回报以背叛，这使得该营地成为了报复的直接目标。"},sec={{t="破碎的盟约",b="位于乌索兰以东的血精灵远征队本不应与来自奥格瑞玛的旅行者为敌。他们的领袖，大法师雷姆托里，与部落达成了一项正式协议：作为交换，她将获得补给线、资金以及穿越艾萨拉险恶荒野的武装护送，而她的研究人员则会分享他们发现的任何魔法珍宝。然而，当营地刚建成，第一批遗物从精灵废墟中被挖掘出来时，雷姆托里便彻底背信弃义，驱逐了部落的使者。现在，雷姆托里带着武装卫队在更远的地区进行搜寻，而魔导师霍克海姆则留守山脊，负责保卫营地，防止报复。"},{t="尘埃与恶魔学",b="血精灵来到这里不仅仅是为了记录历史。他们掌握着一种不同寻常的技术，能将回收的魔法奇物粉碎成闪光尘埃——这是一种与普通附魔残渣截然不同的精炼粉末，它已经引起了大法师克希雷姆的好奇。更令人担忧的是，在营地的山脊高处放着一本卡多雷召唤之书。这远非对上层精灵遗物的学术研究，这本古籍揭示了他们渴望冲破帷幕，将恶魔直接召唤到艾萨拉废墟中的险恶用心。"}},faq={{q="为什么血精灵会出现在艾萨拉？",a="他们是大法师雷姆托里领导的奥术挖掘队的一部分。他们穿越卡利姆多，意图开发卡利姆多古代遗迹中的强大魔法遗物，寻找在太阳之井被摧毁后可供采集和汲取的能量。",al={"为什么血精灵在艾萨拉","萨拉斯营地的目的","谁住在这里"}},{q="为什么部落对这个营地怀有敌意？",a="大法师雷姆托里在承诺分享探险发现的前提下接受了部落的资金和资源。当她的部队在艾萨拉北部稳固阵脚后，她撕毁了协议，拒绝上交任何贡品，这也让部落开始寻求报复。",al={"为什么部落攻击萨拉斯营地","大法师雷姆托里的背叛","背叛任务背景"}},{q="谁领导着萨拉斯营地？",a="远征队的最高领导者是大法师雷姆托里，尽管她经常带着贴身保镖在艾萨拉各地穿行。在她不在时，营地的日常指挥权由魔导师霍克海姆负责。",al={"谁负责","营地首领","魔导师霍克海姆"}},{q="什么是闪光尘埃？",a="这是一种通过血精灵专门研磨附魔遗物的方法所产生的奥术残渣。与传统附魔分解出的尘埃不同，它独特的性质吸引了古怪的大法师克希雷姆的浓厚兴趣。",al={"魔法尘埃克希雷姆","闪光尘埃背景","为什么要粉碎魔法物品"}},{q="山脊上的那本卡多雷召唤之书是什么？",a="这本放置在俯瞰营地的山脊上的古籍，可以被用来召唤恶魔来到该区域。它的存在表明雷姆托里的远征队正在进行比简单的历史恢复黑暗得多的研究。",al={"山上的书","卡多雷召唤之书","艾萨拉的恶魔之书"}}},fp="20,415,18.654.0,19.532.1,36.238.0,38.249.0,35.211.0,24.271.0,52.221.0"}
P.entries["subzone:thandol-span"] = {n="萨多尔大桥",s="萨多尔大桥是一座宏伟的矮人双重石桥，连接着卡兹莫丹的湿地与洛丹伦南部的阿拉希高地。它曾长期作为一项工程奇迹和连接南北王国的生命动脉而闻名，但在遭到黑铁部族的潜入者蓄意破坏后，如今已陷入灾难性的状态。",h="萨多尔大桥是一座宏伟的矮人双重石桥，连接着卡兹莫丹的湿地与洛丹伦南部的阿拉希高地。它曾长期作为一项工程奇迹和连接南北王国的生命动脉而闻名，但在遭到黑铁部族的潜入者蓄意破坏后，如今已陷入灾难性的状态。",kw={"阿拉希高地","巴尔加斯","黑铁部族","丹莫德","铁炉堡","卡姆·深怒","萨多尔大桥","湿地"},ang={["faction:Alliance"]="萨多尔大桥是连接卡兹莫丹与洛丹伦北部受困前哨站的唯一直接陆路联系，因此它的防守对战争进程至关重要。",["race:Dwarf"]="对于铁炉堡的矮人来说，萨多尔大桥既是他们石匠大师的杰作，也是一个痛苦的战场，他们的黑铁同族已将战火烧到了家门口。"},sec={{t="跨海之战",b="幸存的桥梁依然是争夺的焦点，且防守严密。来自铁炉堡的登山者们在拼死保卫残存的桥面，击退黑铁工兵的同时也付出了惨痛的代价。如果大桥失守，北方的贸易和军事行动将几乎完全依赖海上航线，这会切断驻扎在阿拉希高地的联盟部队的直接支援。"},{t="被切断的生命线",b="萨多尔大桥建造于三锤之战后，旨在连接铁炉堡与鹰巢山的蛮锤部族，是矮人历史上最伟大的石造工程之一。它能够支撑整支行军的军队，在整个第二次战争期间，它一直是连接洛丹伦和卡兹莫丹的关键陆路走廊，安度因·洛萨爵士的反攻正是从这里向南推进的。如今，这座跨海大桥伤痕累累。由邪恶的巴尔加斯和卡姆·深怒领导的黑铁破坏者从附近的丹莫德发起了毁灭性的袭击，用炸药彻底摧毁了其中一段桥梁，并威胁要完全切断盟友国度之间的陆路交通。"}},faq={{q="什么是萨多尔大桥？",a="这是一座巨大的矮人双拱石桥，跨越了连接北卡兹莫丹湿地与南洛丹伦阿拉希高地之间的深谷。",al={"萨多尔大桥概述","这座桥是什么","萨多尔桥"}},{q="为什么其中一座桥梁断裂了？",a="黑铁矮人从被占领的丹莫德前哨站发起袭击，使用高爆炸药摧毁了两座桥梁中的一座，试图切断联盟的补给线。",al={"是谁炸毁了桥","萨多尔大桥被毁","萨多尔大桥为何断裂"}},{q="萨多尔大桥最初是为何而建？",a="铁炉堡矮人在三锤之战后建造了这座桥，以促进贸易、外交，并加强他们与居住在峡谷北侧的蛮锤表亲之间的长期联系。",al={"是谁建造了萨多尔大桥","萨多尔历史","它为何而建"}},{q="在第二次战争期间，军队是否经过这里？",a="是的。尽管旧部落通过横渡海洋绕过了大桥入侵洛丹伦，但后来安度因·洛萨爵士带领联盟反攻部队穿过了大桥，将兽人赶回了卡兹莫丹。",al={"第二次战争中的萨多尔大桥","萨多尔大桥的兽人","洛萨与萨多尔大桥"}}},fx={["6e9af8e2"]={q="萨多尔大桥由谁控制？",a="萨多尔大桥由铁炉堡的矮人占据并守卫。尽管来自附近丹莫德的黑铁渗透者发动了残酷袭击和破坏，铁炉堡的山地巡逻兵仍继续守卫尚存的桥梁，维系卡兹莫丹与北方王国之间至关重要的通道。",al={"谁控制萨多尔大桥","谁管理萨多尔大桥","萨多尔大桥的守卫"}},a33b8b45={q="萨多尔大桥危险吗？",a="是的，穿越大桥十分危险。黑铁破坏者最近潜入峡谷并引爆炸药，彻底炸断了两座并列拱桥中的一座，使剩下的桥段也岌岌可危。敌对的黑铁矮人仍在北部湿地和丹莫德附近徘徊，积极谋划进一步袭击过往旅人和坚守阵线的铁炉堡守军。",al={"萨多尔大桥安全吗","萨多尔大桥的危险","萨多尔大桥面临的威胁"}}},fp="12,349,26.422.0,18.687.1,25.167.0,33.175.0,42.182.0,44.204.0"}
P.entries["subzone:the-den"] = {n="大兽穴",s="大兽穴是位于杜隆塔尔西南部试炼谷中心地带的一处隐蔽洞穴。它是年轻兽人和巨魔冒险者的主要行动基地，为他们在走向更广阔的世界之前提供武艺和魔法训练。",h="大兽穴是位于杜隆塔尔西南部试炼谷中心地带的一处隐蔽洞穴。它是年轻兽人和巨魔冒险者的主要行动基地，为他们在走向更广阔的世界之前提供武艺和魔法训练。",kw={"杜隆塔尔","高内克","起始洞穴","大兽穴","训练师","试炼谷","祖雷萨"},ang={["race:Orc"]="每一位年轻的兽人都是在大兽穴开启他们的旅程，摒弃拘留营的安逸与血之狂热，通过纪律与劳作来赢取他们的一席之地。",["race:Troll"]="在暗矛群岛遭到破坏后，年轻的暗矛巨魔在大兽穴与他们的兽人盟友并肩受训，在部落的旗帜下证明他们的勇气。"},sec={{t="部落的摇篮",b="大兽穴坐落在试炼谷的红色峡谷峭壁之中，是一处朴素的试炼场。在其开凿出的阴影内部，新手战士、施法者和猎人们向高内克和祖雷萨这样的老兵报到。正是从这里，雏鹰们接受基础的战斗指导、物资供给和最初的成人礼，在杜隆塔尔严酷的现实和新部落所面临的更宏大的斗争中磨练自己。"},{t="警觉的前哨站",b="除了容纳职业训练师和提供补给之外，大兽穴还充当了一处活跃的战地堡垒。在派遣新兵去清理当地野兽和好斗的野猪人之间，监工们始终对山谷保持着严密而警惕的监视。"}},faq={{q="大兽穴的用途是什么？",a="大兽穴是试炼谷内的中央指挥所和训练圣地。在这里，新手兽人和暗矛巨魔聚集在一起学习基本的职业技能，购买补给，并接受那些能够证明他们对部落的忠诚和战斗准备的任务。",al={"什么是大兽穴","大兽穴为何在此","大兽穴的用途"}},{q="谁在大兽穴负责管理？",a="该营地由高内克和工头塔兹利尔这样的资深监工监督，辅以祖雷萨和坎纳甘·地鸣这样的精神和魔法导师，他们通力合作，指导新一代的战士和神秘修行者。",al={"谁领导大兽穴","谁负责管理","大兽穴监工"}},{q="在这里可以学习主要专业吗？",a="不能。大兽穴只提供基础的职业训练师和普通装备商人。新的冒险者必须向北前往剃刀岭，或者继续前往奥格瑞玛，才能学习锻造、制皮或采矿等主要专业技能。",al={"大兽穴专业训练师","我能在这里学锻造吗","在大兽穴训练采矿"}}},fx={e0991dfb={q="大兽穴是什么地方？",a="大兽穴是位于杜隆塔尔西南角、试炼谷中的大型洞窟基地。它是年轻兽人新兵的主要集结营地，他们希望证明自己配得上部落。在洞内，训练师教授各种技艺的基础，商人出售必需品，当地首领则安排试炼，考验即将入伍的新兵，然后他们才会踏入更广阔的世界。",al={"大兽穴是什么","杜隆塔尔的大兽穴","关于大兽穴"}},ac46dd9b={q="大兽穴危险吗？",a="大兽穴本身戒备森严，对部落成员来说相当安全，有大兽穴步兵和经验丰富的监督者守卫。真正的危险在外面，野兽和野猪人游荡在试炼谷中。",al={"大兽穴危险吗","大兽穴里安全吗","大兽穴的威胁"}}},fp="7,253,19.447.0,18.240.0,31.278.0,31.254.0,39.223.0"}
P.entries["subzone:the-loch"] = {n="洛克湖",s="洛克湖是占据了洛克莫丹山谷的巨大淡水湖。它被宏伟的巨石水坝所拦截，是卡兹莫丹最大的水体，也是周边矮人定居点的生命之源。",h="洛克湖是占据了洛克莫丹山谷的巨大淡水湖。它被宏伟的巨石水坝所拦截，是卡兹莫丹最大的水体，也是周边矮人定居点的生命之源。",kw={"卡兹莫丹","湖泊","洛克莫丹","巨石水坝","洛克湖","塞尔萨玛","刺喉鱼","湿地"},ang={["faction:Alliance"]="洛克湖平静的湖水为铁炉堡中心山谷与周边前哨站之间提供了至关重要的淡水和贸易航线。",["race:Dwarf"]="洛克湖是铁炉堡引以为傲的核心景观，展现了矮人的石匠工艺以及巨石水坝如何驯服自然，从而供养如塞尔萨玛这样的定居点。"},sec={{t="山谷之心",b="洛克湖横跨洛克莫丹中心地带，是已知世界中最大的内陆湖之一，仅次于北方的洛丹米尔湖和达隆米尔湖。湖水养育了当地的渔民，并为塞尔萨玛镇和附近的猎人营地提供了一片宁静的背景。然而，在平静的水面下，游荡着充满攻击性的刺喉鱼和淡水野兽，使得横渡湖泊成为一项危险的壮举。"},{t="巨石屏障",b="得益于矮人大师级的工程杰作，洛克湖得以保持现状。北端矗立着巨大的巨石水坝，这座建筑奇迹横跨山谷裂口，防止湖水涌入下方的湿地。维护这座巨大的建筑对于保护山谷的生态系统和确保卡兹莫丹的安全至关重要。"}},faq={{q="什么是洛克湖？",a="洛克湖是填满了卡兹莫丹洛克莫丹山谷中心的巨大高山湖泊。它是世界上规模最大的淡水水体之一，决定了当地矮人的地理环境和生计。",al={"洛克湖背景故事","什么是洛克湖","洛克莫丹湖"}},{q="湖水是如何保持满盈的？",a="湖泊北端由巨石水坝拦截，这是一座高耸的矮人建筑。大坝拦住了数不尽的湖水，否则这些水就会顺着山口倾泻到地势低洼的湿地中去。",al={"为什么洛克湖不会干涸","是什么阻挡了洛克湖","巨石水坝的作用"}},{q="在洛克湖游泳安全吗？",a="并不完全安全。虽然湖岸和码头上随处可见当地的渔民，但深水区栖息着掠食性的刺喉鱼和咬人怪兽，它们经常会攻击那些离岸太远的粗心旅客。",al={"洛克湖怪物","洛克湖游泳","洛克湖生物"}},{q="洛克湖与其他湖泊相比有多大？",a="它是卡兹莫丹大陆上最大的水体，也是东部王国已知的第三大湖泊，仅次于洛丹伦的洛丹米尔湖和达隆米尔湖。",al={"最大的湖","洛克湖大小比较","洛克湖有多大"}}},fp="8,227,19.414.0,24.373.0,17.221.0,28.225.0,31.194.0,46.181.0"}
P.entries["subzone:thelgen-rock"] = {n="瑟根石",s="瑟根石是位于湿地南部山壁上的一处庞大洞穴系统。这里遍布着剧毒蜘蛛，并以蕴藏着稀有的不稳定的火岩矿石而闻名。",h="瑟根石是位于湿地南部山壁上的一处庞大洞穴系统。这里遍布着剧毒蜘蛛，并以蕴藏着稀有的不稳定的火岩矿石而闻名。",kw={"洞穴","火岩矿石","蜘蛛洞","蜘蛛","瑟根石","湿地"},ang={["profession:Mining"]="瑟根石深邃的隧道中藏有稀有的火岩矿石矿床，吸引着勘探者们深入山底，面对危险。"},sec={{t="蛛网密布的洞穴",b="瑟根石坐落在将湿地与洛克莫丹隔开的南部山脉边缘，是一个深邃的地下洞穴网络，被极具攻击性的节肢动物所占据。洞穴通道内蛛网丛生，爬满了有毒的蜘蛛，这使得过往的旅人进入其中变得极其危险。尽管虫患严重，矿工和冒险者们依然勇闯其深处，只为开采镶嵌在岩石隧道中的珍贵火岩矿石矿脉。"}},faq={{q="瑟根石的危险之处是什么？",a="瑟根石的洞穴中栖息着大量有毒的蜘蛛。贸然进入曲折隧道的旅人很容易在蛛网中被包围，并被毒咬所伤。",al={"瑟根石的危险","瑟根石为什么危险","瑟根石的蜘蛛"}},{q="为什么勘探者和矿工要来这里？",a="这个洞穴系统蕴藏着丰富的火岩矿石矿脉，这是一种矮人勘探者和工程师们趋之若鹜的炽热且不稳定的矿物。尽管这里蜘蛛泛滥，大胆的矿工们还是会进入其中，从岩壁上开采样本。",al={"为什么去瑟根石","瑟根石的矿石","火岩矿石"}},{q="瑟根石位于哪里？",a="瑟根石位于湿地的南侧山脊沿线，在连接米奈希尔港和丹奥加兹山口的主干道以南。",al={"瑟根石位置","瑟根石在哪里"}}},fx={["10e18c06"]={q="瑟根石是什么地方？",a="瑟根石是一个广阔的洞穴系统，深深凿入湿地南部的群山之中。矿工们都知道这里蕴藏着丰富的火岩矿石，但要在此采集任何东西，都必须冒险面对遍布洞内每一处阴影和隧道的毒蜘蛛群。",al={"瑟根石是什么","瑟根石是什么地方","瑟根石洞穴"}},ba9bab1c={q="瑟根石危险吗？",a="是的，这里极其危险。洞穴里盘踞着凶猛的毒蜘蛛，任何勘探行动都可能因此成为致命之旅。探索者和矿工若想寻找洞中的稀有矿脉，就必须时刻警惕黑暗洞穴，以免被毒液和蛛网吞没。",al={"瑟根石有多危险","瑟根石的危险","瑟根石安全吗"}}},fp="12,197,19.443.0,34.212.0,40.227.0,30.153.0"}
P.entries["subzone:thelsamar"] = {n="塞尔萨玛",s="塞尔萨玛是洛克莫丹主要的矮人定居点，坐落在俯瞰大湖的西侧悬崖上。它位于丹莫罗和湿地之间的主干道旁，是贸易、住宿和防御周围穴居人和食人魔入侵的繁忙中心。",h="塞尔萨玛是洛克莫丹主要的矮人定居点，坐落在俯瞰大湖的西侧悬崖上。它位于丹莫罗和湿地之间的主干道旁，是贸易、住宿和防御周围穴居人和食人魔入侵的繁忙中心。",kw={"血肠","灰爪山","洛克莫丹","山地巡逻队员","碎石怪","烈酒旅店","塞尔萨玛"},ang={["profession:Cooking"]="烹饪旅行者经常在烈酒旅店停留，学习制作这种丰盛血肠的区域食谱，这种血肠是用当地熊、蜘蛛和野猪的肉制成的。",["race:Dwarf"]="对于离开寒冷丹莫罗的矮人来说，塞尔萨玛是他们品尝到的第一个温暖低地的滋味，这里有美味的麦芽酒、坚固的石制炉火，还有为山地巡逻卫队提供的积极服务。"},sec={{t="洛克莫丹的心脏",b="塞尔萨玛是该山谷中矮人平民生活的核心堡垒。它采用了传统的卡兹莫丹石木建筑风格，拥有热闹的烈酒旅店、专门的狮鹫管理员、制造台以及各种补给商人。由于它直接坐落在连接南门小径通往丹莫罗的通道，以及通往湿地的奥加兹大门的交通要道上，该地区几乎所有的旅行者都会经过其温暖的炉火和坚固的屋檐。"},{t="边境的麻烦",b="尽管这里舒适安逸，塞尔萨玛却处于持续的危险之中。在南方，从碎石怪之谷涌出的穴居人威胁着城镇的周边地区，而灰爪山则有熊和捕食野兽出没。由于铁炉堡的常规军事力量在王国各地捉襟见肘，当地治安官和山地巡逻队员非常依赖旅行中的冒险者和雇佣兵来巡逻贸易道路，并击退入侵的敌对势力。"}},faq={{q="塞尔萨玛提供哪些服务？",a="塞尔萨玛提供全套的边境服务设施，包括用于住宿和餐饮的烈酒旅店、一个拥有通往卡兹莫丹中部航线的飞行管理员、贸易商贩以及一个露天锻造台。这里还设有几位专业技能训练师和战斗训练师，以协助正在成长的冒险者。",al={"塞尔萨玛商人","塞尔萨玛有什么","塞尔萨玛的训练师"}},{q="穿过塞尔萨玛的道路通向哪里？",a="城镇西侧的南北向道路向南穿过隧道连接至丹莫罗，直通铁炉堡。沿着这条路向北走，旅行者可以穿过奥加兹大门进入沼泽密布的湿地。",al={"塞尔萨玛道路","路径通往何处","从塞尔萨玛出发"}},{q="为什么这个城镇雇佣了这么多雇佣兵？",a="当地的山地巡逻队员正被多种新出现的威胁弄得焦头烂额。好战的碎石怪穴居人已经占领了南方的挖掘场，野生猛兽在定居点边缘徘徊，而有组织的食人魔也开始施压，迫使城镇领导层向独立的战士提供赏金。",al={"为什么塞尔萨玛有任务","谁在攻击塞尔萨玛"}},{q="这里有什么著名的当地特产？",a="该镇因“塞尔萨玛血肠”而受到猎人和旅行者的青睐。这是一种浓郁的矮人菜肴，由烈酒旅店的维德拉·壁炉使用当地野生动物的内脏和肉制作而成。",al={"塞尔萨玛食物","洛克莫丹血肠"}}},fx={["19f21b39"]={q="塞尔萨玛是什么地方？",a="塞尔萨玛是洛克莫丹的主要矮人聚居地，坐落在俯瞰洛克湖的西侧峭壁上。小镇紧邻连接丹莫罗与湿地的南北大道，是山地旅人、商人和守卫山谷的山地巡逻兵的重要枢纽。",al={"塞尔萨玛小镇","这座小镇是什么地方","介绍一下塞尔萨玛"}},a244cff7={q="谁住在塞尔萨玛，或由谁管理？",al={"谁领导塞尔萨玛","谁负责管理塞尔萨玛","塞尔萨玛的领袖"}},c5fc67c9={q="塞尔萨玛危险吗？",a="小镇本身安全，山地巡逻兵守卫严密，但周边荒野危机四伏。碎石怪之谷的穴居人不断侵扰附近农场，熊在南面出没，莫格罗什要塞的食人魔也步步逼近，因此小镇不得不依靠路过的冒险者守住外围。",al={"塞尔萨玛安全吗","塞尔萨玛面临的威胁","塞尔萨玛的危险"}}},fp="9,303,19.471.0,23.430.0,41.290.0,43.220.0,43.293.0,40.198.0"}
P.entries["subzone:theramore-isle"] = {n="塞拉摩岛",s="塞拉摩岛是一座戒备森严的人类港口要塞，位于尘泥沼泽的东海岸。它是吉安娜·普罗德摩尔女士为逃离洛丹伦沦陷的难民所建立，是联盟在卡利姆多南部的主要据点。",h="塞拉摩岛是一座戒备森严的人类港口要塞，位于尘泥沼泽的东海岸。它是吉安娜·普罗德摩尔女士为逃离洛丹伦沦陷的难民所建立，是联盟在卡利姆多南部的主要据点。",kw={"联盟","戴林·普罗德摩尔","尘泥沼泽","jaina proudmoore","库尔提拉斯","洛丹伦难民","塞拉摩"},ang={["class:Mage"]="作为大法师吉安娜·普罗德摩尔的私人领地，塞拉摩拥有强大的奥术导管，是肯瑞托传统和西半球传送枢纽的重要节点。",["faction:Alliance"]="塞拉摩岛是联盟在卡利姆多中部的主要权力中心，提供安全保障、重要的渡轮连接，以及一座被敌对荒野包围、防御严密的港口。"},sec={{t="西方的避难所",b="在第三次战争期间，随着达拉然和洛丹伦被天灾军团摧毁，吉安娜·普罗德摩尔女士率领一支幸存者舰队跨越无尽之海，抵达了卡利姆多的海岸。在与兽人和暗夜精灵并肩作战击败海加尔山之巅的燃烧军团后，她所领导的人类、矮人和高等精灵联军撤退到了尘泥沼泽多雾的边缘地带。在近海的一座崎岖岛屿上，他们建造了塞拉摩岛——一座繁荣的港口城市，以高耸的石墙和吉安娜的私人城堡为依托，旨在守护北方王国仅存的火种。"},{t="不安的和平",b="塞拉摩的历史始终伴随着与杜隆塔尔萨尔所领导的部落之间的紧张关系。当戴林·普罗德摩尔海军上将带着库尔提拉斯舰队抵达时，他接管了这座岛屿，并发动了一场未经挑衅的战役，试图消灭兽人。吉安娜拒绝让仇恨摧毁卡利姆多来之不易的生存局面，她选择了退让，允许部落在塞拉摩的城墙内击杀她的父亲，以维持和平。如今，这座城市与杜隆塔尔维持着脆弱的休战协议，尽管老兵们心中积压的怨恨随时可能撕碎这份脆弱的契约。"}},faq={{q="谁统治着塞拉摩岛？",a="吉安娜·普罗德摩尔女士统治着塞拉摩岛。她是一位来自达拉然和库尔提拉斯的大法师，在第三次战争期间率领洛丹伦的幸存者来到卡利姆多，并统管着该城的军事防御和外交关系。",al={"谁领导塞拉摩","塞拉摩统治者","吉安娜 塞拉摩"}},{q="为什么人类要在沼泽中建立城市？",a="海加尔山之战后，幸存的人类远征队需要一个易守难攻的沿海据点来庇护人民并维持海军。尘泥沼泽外的岩石岛屿提供了深水锚地，且与大陆威胁保持了天然的隔绝，这使其成为一个理想的堡垒，尽管周围环境泥泞不堪。",al={"为什么选择尘泥沼泽","为什么塞拉摩在沼泽里","为什么在这里建造"}},{q="塞拉摩对部落敌对吗？",a="塞拉摩是联盟的堡垒，其卫兵会对部落旅行者表现出敌意。然而，在官方层面上，吉安娜·普罗德摩尔女士和大酋长萨尔维持着不安的外交和平，尽管双方公民之间仍存有积怨，但双方都尊重彼此的领土边界。",al={"部落可以访问塞拉摩吗","塞拉摩与部落的关系","塞拉摩的人类是否在交战"}},{q="戴林·普罗德摩尔海军上将在塞拉摩发生了什么事？",a="戴林·普罗德摩尔海军上将从他女儿吉安娜手中夺取了塞拉摩的控制权，以发动针对新生的部落的战争。吉安娜认识到他的行动将导致所有人毁灭，因此她选择了退让，允许萨尔和雷克萨突袭岛上要塞，并在战斗中击杀了海军上将。",al={"戴林之死","吉安娜的父亲发生了什么","戴林·普罗德摩尔 塞拉摩"}}},fp="14,243,18.596.0,15.563.1,25.247.0,39.330.0,34.284.0,54.262.0"}
P.entries["subzone:thistlefur-hold"] = {n="Thistlefur Hold",s="Thistlefur Hold 是位于灰谷中西部蓟皮村北端的一个洞穴。这里曾经是森林中宁静的熊怪部落，但现在居住在此的蓟皮熊怪已经受到腐蚀，对任何靠近的外来者都充满敌意。",h="Thistlefur Hold 是位于灰谷中西部蓟皮村北端的一个洞穴。这里曾经是森林中宁静的熊怪部落，但现在居住在此的蓟皮熊怪已经受到腐蚀，对任何靠近的外来者都充满敌意。",kw={"灰谷","熊怪","remulos","鲁尔·雪蹄","thistlefur hold","蓟皮村","巨魔咒符"},ang={["class:Druid"]="目睹蓟皮熊怪陷入腐蚀和疯狂，让人悲哀地意识到，在灰谷，自然的守护者竟如此容易受到腐蚀。",["faction:Horde"]="对于部落来说，这个洞穴既是一次救援任务，也是一次抢救行动，要求战士们深入巢穴营救鲁尔·雪蹄并取回被偷走的巨魔咒符。"},sec={{t="被腐蚀的巢穴",b="Thistlefur Hold 坐落在蓟皮村的最北端，是蓟皮部落领地的中心。这里的熊怪因腐蚀而陷入疯狂，处于一种野蛮的敌对状态，这对旅行者和邻居来说都非常危险。在蜿蜒曲折的洞穴深处，部落囤积着搜刮来的遗物，其中包括暗矛巨魔感兴趣的巨魔咒符，还把俘虏关在木笼子里，比如被囚禁的牛头人勇士鲁尔·雪蹄。"}},faq={{q="Thistlefur Hold 是什么地方？",a="Thistlefur Hold 是位于灰谷中西部蓟皮村北端的地下洞穴群，这里居住着大量敌对的蓟皮熊怪。",al={"thistlefur hold 信息","这是什么洞穴","蓟皮洞穴"}},{q="为什么 Thistlefur Hold 的熊怪会敌对？",a="蓟皮熊怪已经受到了腐蚀。邪恶的影响扭曲了它们的心智，驱使它们攻击所有外来者。",al={"为什么蓟皮熊怪会发疯","蓟皮腐蚀","为什么熊怪会攻击"}},{q="谁被困在洞穴里了？",a="牛头人勇士鲁尔·雪蹄被蓟皮部落俘虏，正被关在洞穴深处的木笼子里，等待部落勇士的营救。",al={"蓟皮俘虏","thistlefur hold 中的牛头人","鲁尔·雪蹄是谁"}},{q="为什么部落对 Thistlefur Hold 感兴趣？",a="部落试图解救被俘的牛头人鲁尔·雪蹄，并夺回熊怪在洞穴深处囤积的珍贵巨魔咒符。",al={"蓟皮部落任务","蓟皮巨魔咒符"}}},fx={["6573f817"]={q="Thistlefur Hold发生了什么？",a="Thistlefur Hold曾是灰谷深处一处宁静的熊怪聚居地，但腐化侵蚀了居民，使他们陷入疯狂。他们温和的天性荡然无存，转而盲目攻击任何靠近巢穴的外来者，并将家园变成了敌意满满的堡垒。",al={"thistlefur hold的历史","thistlefur hold发生了什么","蓟皮熊怪的历史"}},["36b0fa4f"]={q="Thistlefur Hold里住着谁？",a="这座洞窟据点容纳着蓟皮熊怪部族的大部分族人。过去他们曾和睦地生活在灰谷古老的森林中，如今这些遭到腐化的熊怪却凶狠地守卫着地下巢穴，敌视暗夜精灵、部落旅人以及任何踏入其领地的人。",al={"谁住在thistlefur hold","thistlefur hold的居民","thistlefur hold里有谁"}},["77184072"]={q="Thistlefur Hold危险吗？",a="进入其中极其危险。洞穴里挤满了愤怒的蓟皮熊怪，它们受腐化驱使而陷入狂暴，一见人就会发动攻击。任何试图穿过狭窄通道的人，都会遭到敌对的萨满和战士围攻，他们正守卫着这座遭腐化的据点。",al={"thistlefur hold有多危险","蓟皮熊怪危险吗","thistlefur hold面临的威胁"}}},fp="15,256,15.498.0,24.193.0,48.141.0,31.160.0,47.153.0"}
P.entries["subzone:thistlefur-village"] = {n="蓟皮村",s="蓟皮村是一处蔓延的定居点，坐落在灰谷中西部阿斯特兰纳以北的森林中。这里是蓟皮熊怪部族的主要家园，该部族已深受黑暗腐蚀，并会暴力攻击任何靠近其巢穴的外来者。",h="蓟皮村是一处蔓延的定居点，坐落在灰谷中西部阿斯特兰纳以北的森林中。这里是蓟皮熊怪部族的主要家园，该部族已深受黑暗腐蚀，并会暴力攻击任何靠近其巢穴的外来者。",kw={"灰谷","阿斯特兰纳","腐蚀","达尔·血爪","熊怪","罗吉什·下颌","蓟皮","村庄"},ang={["class:Druid"]="蓟皮部族的堕落状态是对困扰着灰谷的灵魂与野生生物的长期污秽的严酷提醒，需要塞纳里奥议会进行警惕的净化。",["race:NightElf"]="几个世纪以来，暗夜精灵一直与当地的熊怪部族和谐相处。看到蓟皮部族在距离阿斯特兰纳如此之近的地方陷入暴力腐蚀，对哨兵来说既令人心碎，也是一场严峻的安全危机。"},sec={{t="堕落的巢穴",b="蓟皮村位于暗夜精灵避难所阿斯特兰纳以北，曾是灰谷本土宁静林地社区的一部分。然而，渗入古老森林的恶性腐蚀已经完全侵蚀了蓟皮部族。如今，这些熊怪已经彻底疯狂且充满敌意，极其凶狠地守卫着蜿蜒穿过其定居点的小径。该部族听命于两位异常凶猛的酋长：达尔·血爪和罗吉什·下颌，他们毫不妥协的侵略性对旅行者和附近的定居点构成了持续威胁。"}},faq={{q="蓟皮村在哪里？",a="蓟皮村位于灰谷的中西部，坐落在暗夜精灵城镇阿斯特兰纳正北方的林地丘陵深处。",al={"蓟皮村位置","蓟皮在哪里","蓟皮地图"}},{q="为什么这里的熊怪会攻击旅行者？",a="蓟皮熊怪已被蔓延在灰谷森林中的黑暗腐蚀所控制。在这些邪恶影响的驱使下，他们陷入疯狂，将所有外来者视为即刻的敌人，并攻击任何靠近其领地的人。",al={"为什么蓟皮怀有敌意","蓟皮腐化的熊怪","为何攻击"}},{q="谁领导着蓟皮熊怪？",a="该部族由两位特别凶猛且残暴的战士酋长领导，分别是达尔·血爪和罗吉什·下颌，他们对村庄及其附近的巢穴保持着残暴的统治。",al={"蓟皮首领","蓟皮领导者","谁领导蓟皮"}},{q="蓟皮村对阿斯特兰纳构成危险吗？",a="是的。由于蓟皮村就在阿斯特兰纳的正北方，这些堕落熊怪具有攻击性且不稳定的本质，使他们对驻扎在中央道路沿线的暗夜精灵斥候、补给线和哨兵构成了持续的威胁。",al={"蓟皮对阿斯特兰纳的威胁","对阿斯特兰纳的危险"}}},fx={["840d1e44"]={q="蓟皮村是什么地方？",a="蓟皮村是灰谷中西部的一处熊怪聚居地，位于阿斯特兰纳正北方。它是蓟皮部族的主要家园和据点；这个熊怪部族已沦为森林中蔓延的黑暗腐化的牺牲品。",al={"蓟皮村信息","什么是蓟皮熊怪","蓟皮村背景"}},["7a812bcb"]={q="蓟皮村危险吗？",a="蓟皮村对任何旅人来说都极其危险。村里的熊怪因腐化而陷入疯狂，领地意识极强，会猛烈袭击任何靠近边界的人。这里由强悍的战士和萨满严密守卫，他们听命于残暴的达尔·血爪和洛吉什·唇角。",al={"蓟皮村有多危险","蓟皮村安全吗","蓟皮村的危险"}},fc97bd16={q="蓟皮村里住着谁？",a="村里住的全是蓟皮熊怪部族的成员。他们曾是和平的森林居民，如今却受两位凶暴的酋长人物——达尔·血爪和洛吉什·唇角——残酷统治，由他们组织防御和袭击。",al={"谁住在蓟皮村","蓟皮熊怪居民","蓟皮村住着谁"}}},fp="18,279,15.565.0,36.158.0,46.239.0,34.180.0,51.243.0"}
P.entries["subzone:thistlefuzz-arcanery"] = {n="Thistlefuzz Arcanery",s="Thistlefuzz Arcanery 是一间坐落于铁炉堡 Great Forge 东侧的著名工坊与魔法艺术学院。它主要由侏儒从业者运营，是这座首都内附魔师和学者们将魔法编织进金属与羊皮纸的首选避风港。其繁忙的室内不仅回荡着奥术能量的嗡嗡声，还伴随着矮人工业咆哮的火光。",h="Thistlefuzz Arcanery 是一间坐落于铁炉堡 Great Forge...",kw={"奥术","附魔师","附魔","侏儒","great forge","铁炉堡","thistlefuzz arcanery"},ang={["class:Mage"]="到访的法师们可以在这座以军事和武器为中心的矮人首都大厅中，找到熟悉的试剂、安静的理论角落，以及志同道合的法术使用者。",["race:Gnome"]="对于居住在铁炉堡的侏儒来说，Thistlefuzz Arcanery 是一个舒适的提醒，让他们在这座被沉重矮人钢铁所主宰的城市中，依然能感受到对奥术理论、技术研究和精细实验的热爱。"},sec={{t="山中的奥术工艺",b="Thistlefuzz Arcanery 坐落在轰鸣的 Great Forge 正东方，与矮人铁匠铺内叮当作响的铁砧形成了鲜明对比。在其两层楼的建筑内，学者、从业者和学徒们汇聚一堂，钻研附魔与魔法研究的精妙学科。虽然铁炉堡的矮人们更倾向于通过力量与烈火重塑钢铁，但 Arcanery 的侏儒们展示了原始的奥术能量是如何直接被束缚进武器、护甲和各种奇特工具之中的。它是这座山中堡垒内法术使用者们不可或缺的避难所。"}},faq={{q="Thistlefuzz Arcanery 位于哪里？",a="Thistlefuzz Arcanery 位于铁炉堡中心地带 Great Forge 的东环区域，门口陈列的奥术设备和附魔补给品让它极易辨认。",al={"奥术工坊位置","thistlefuzz 在哪里","铁炉堡附魔商店"}},{q="Arcanery 内部提供哪些服务？",a="这家商店专为魔法工艺的从业者服务。附魔训练师、法术工艺供应商和学者们聚集于此，教导学徒、交易稀有试剂，并在远离锻造厂煤烟的地方进行实验。",al={"thistlefuzz arcanery 里有什么","thistlefuzz 的训练师"}},{q="为什么奥术工坊会建在紧邻 Great Forge 的地方？",a="将附魔工坊安置在紧邻 Great Forge 的地方非常实用。矮人铁匠们新锻造的刀剑、护甲片和机械组件可以被立即运往东侧，注入保护性附魔和元素力量。",al={"为什么它靠近锻炉","奥术工坊与 great forge 的联系"}}},fx={b65c06f3={q="Thistlefuzz Arcanery是什么地方？",a="Thistlefuzz Arcanery是一家奥术工坊兼商店，坐落在铁炉堡中心地带的Great Forge以东。周围的城市回荡着铁砧敲击和熔铁翻涌之声，而这家宁静的店铺则服务于奥术技艺的修习者，为有志成为附魔师的人提供训练和补给。",al={"thistlefuzz arcanery","thistlefuzz arcanery是什么","铁炉堡的奥术工坊"}},ddf479e1={q="Thistlefuzz Arcanery危险吗？",a="只要你受到铁炉堡欢迎，这里一点也不危险。Thistlefuzz Arcanery是一家平和的商店，由城镇卫兵和铁炉堡当局保护。只要你不敌视联盟，就可以安心浏览货架，并与店里的从业者交谈。",al={"thistlefuzz危险吗","thistlefuzz arcanery的危险"}}},fp="20,374,28.565.0,38.185.0,46.231.0,63.264.0"}
P.entries["subzone:thistleshrub-valley"] = {n="灌木谷",s="灌木谷隐藏在塔纳利斯的西南边缘，是在无尽沙丘中一处充满多刺植物的奇特绿洲。这座峡谷以其奇怪的巨型仙人掌丛林和充满敌意的活化灌木怪而闻名，任何踏入它们那荆棘密布的领地的生物都会遭到攻击。",h="灌木谷隐藏在塔纳利斯的西南边缘，是在无尽沙丘中一处充满多刺植物的奇特绿洲。这座峡谷以其奇怪的巨型仙人掌丛林和充满敌意的活化灌木怪而闻名，任何踏入它们那荆棘密布的领地的生物都会遭到攻击。",kw={"仙人掌","沙漠","塔纳利斯","灌木怪","荆棘","奥丹姆","山谷"},ang={["class:Druid"]="德鲁伊们可能会觉得这些凶猛的活化灌木怪非常迷人，并思考究竟是什么原始或元素力量让它们在荒凉的沙漠中得以繁衍生息。",["profession:Herbalism"]="对于穿行于塔纳利斯的草药师来说，这座山谷是一个反常之地，在茂密的荆棘丛中生长着奇特而顽强的沙漠植物。"},sec={{t="荆棘之林",b="虽然塔纳利斯大部分地区都是寸草不生的荒凉废土，但灌木谷却生机盎然，令人称奇。高大的仙人掌耸立在峡谷底部，与周围的沙海形成了鲜明的对比。然而，这里并非宁静的避难所。这座山谷得名于潜伏在灌木丛中的敌对活体植物生物。这些灌木怪会向任何靠近的旅行者挥舞锋利的尖刺，使得那些试图穿过悬崖前往神秘南部大门的旅者举步维艰。"},{t="沙漠的哨兵",b="在如此干旱的气候下存在着活化的植物，长期以来一直困扰着流浪者和沙漠生存专家。无论是被被遗忘的元素能量所唤醒，还是对塔纳利斯恶劣气候的顽强适应，这些灌木怪始终保持着极强的领地意识。穿行于峡谷的旅行者不仅要面对这些狂暴的荆棘与根须，还要提防筑巢于高耸仙人掌间的沙漠掠食者和剧毒蛇类。"}},faq={{q="灌木谷位于哪里？",a="灌木谷坐落在塔纳利斯的西南角，夹在南部山脊旁，靠近奥丹姆那神秘的封闭大门。",al={"灌木谷位置","灌木怪在哪里","寻找灌木谷"}},{q="为什么塔纳利斯的这个地区有如此茂盛的植物？",a="与贫瘠沙漠的其他地方不同，山谷中存在着一种微气候，以高耸的仙人掌和活化植物为主。这些不同寻常的灌木怪如何在干旱的沙漠沙地中如此旺盛地生长，至今仍是南部沙丘的一个未解之谜。",al={"为什么这里有巨型仙人掌","为什么这里有植物生长"}},{q="灌木谷里生活着什么生物？",a="山谷中充斥着充满敌意的步行灌木怪、具有攻击性的沙漠花朵，以及潜伏在多刺植被下的各种毒性爬行动物。",al={"灌木谷怪物","灌木谷的怪物"}},{q="山谷附近那座巨大的石制结构是什么？",a="在山谷外不远处坐落着一座巨大的、被封印的泰坦建筑，通常被称为通往奥丹姆的大门，对于沙漠流浪者来说，它依然处于封闭且神秘的状态。",al={"灌木谷附近的大门","塔纳利斯泰坦大门"}}},fp="19,294,17.559.0,23.453.0,37.153.0,56.254.0,43.162.0,52.160.0"}
P.entries["subzone:thondroril-river"] = {n="索多里尔河",s="索多里尔河是一条至关重要的自然分界线，将西瘟疫之地和东瘟疫之地分隔开来。它发源于北洛丹伦靠近恶蛛隧道的山脉，其受到瘟疫污染的河水向南流向达隆米尔湖。这条曾经是陨落王国繁荣的贸易与交通航道，如今却被可怕的天灾野兽所包围，只有一位传奇隐士在此处简陋地避难。",h="索多里尔河是一条至关重要的自然分界线，将西瘟疫之地和东瘟疫之地分隔开来。它发源于北洛丹伦靠近恶蛛隧道的山脉，其受到瘟疫污染的河水向南流向达隆米尔湖。这条曾经是陨落王国繁荣的贸易与交通航道，如今却被可怕的天灾野兽所包围，只...",kw={"达隆米尔湖","东瘟疫之地","洛丹伦","恶蛛隧道","索多里尔河","提里奥·弗丁","西瘟疫之地"},ang={["class:Paladin"]="索多里尔河的东岸庇护着提里奥·弗丁，这位白银之手的创始人尽管身处流放，但其遗泽依然回响不绝。",["profession:Herbalism"]="潮湿腐烂的河床滋养着顽强的瘟疫植物，如太阳草、阿尔萨斯之泪和瘟疫花，它们生长在浑浊的河岸附近。"},sec={{t="被毁灭切断的河流",b="在洛丹伦陷落之前，索多里尔河是连接北部据点通往斯坦索姆，以及南向达隆米尔湖的重要航道。如今，这条河流标志着西瘟疫之地和东瘟疫之地之间危险的分界线。河水携带了瘟疫的毒素，河岸上充斥着巨型蛆虫、瘟疫蝙蝠、患病的熊以及掠食性的鳄鱼，将曾经风景优美的河床变成了旅行者致命的穿越点。"},{t="河岸的守望者",b="虽然索多里尔河沿岸的荒野严酷且无情，但并非完全没有希望。在东岸的一座不起眼、杂草丛生的农舍中，住着被流放的圣骑士提里奥·弗丁。这位前领主多年前被剥夺了头衔并被迫隐居，他从远处注视着腐烂的河流和家园的废墟，考验着那些有胆量穿过这片受瘟疫侵蚀的边境的冒险者的勇气和良知。"}},faq={{q="索多里尔河起于何处，又终于何处？",a="这条河发源于北洛丹伦的高地，靠近恶蛛隧道的入口，然后向南穿过瘟疫之地，直到直接注入达隆米尔湖。流过湖泊后，这条水道继续向南延伸，被称为达隆米尔河。",al={"索多里尔河路径","索多里尔河走向","索多里尔河源头"}},{q="河岸边生活着哪些危险生物？",a="瘟疫已经将当地的野生动物突变成了致命的怪物。旅行者在两岸经常会遇到吞噬蛆虫、患病的瘟疫熊、巨大的吸血蝙蝠、地穴蜘蛛和河鳄。",al={"河岸怪物","索多里尔河生物","河流威胁"}},{q="住在东岸的老人是谁？",a="东岸那座破旧农舍里的孤独身影是提里奥·弗丁，白银之手骑士团的创始成员之一。他在第三次战争前多年就被联盟流放，过着安静的隐居生活，观察着天灾军团。",al={"河边的人是谁","索多里尔河隐士","索多里尔河任务发布者"}},{q="为什么这条河是两片瘟疫之地的分界线？",a="索多里尔河在洛丹伦中部切割出了一道宽阔的自然峡谷。当王国沦陷为天灾军团的领地后，地图绘制者和幸存者便开始将这条河视为分隔西瘟疫之地和东瘟疫之地的明确界线。",al={"西瘟疫之地与东瘟疫之地边界","瘟疫之地界线"}}},fp="16,386,19.461.0,20.446.1,46.248.0,51.217.0,47.240.0,46.241.0"}
P.entries["subzone:thoradin-s-wall"] = {n="索拉丁之墙",s="索拉丁之墙是一座宏伟但已然残破的石墙，将阿拉希高地与希尔斯布莱德丘陵隔开。它由索拉丁国王在数千年前的阿拉索帝国黎明时期下令修建，旨在保护早期人类免受阿曼尼巨魔的猛烈入侵。",h="索拉丁之墙是一座宏伟但已然残破的石墙，将阿拉希高地与希尔斯布莱德丘陵隔开。它由索拉丁国王在数千年前的阿拉索帝国黎明时期下令修建，旨在保护早期人类免受阿曼尼巨魔的猛烈入侵。",kw={"阿曼尼","阿拉希","阿拉索","希尔斯布莱德","斯托姆","索拉丁","索拉丁之墙","墙"},ang={["race:Human"]="伫立在墙前，仿佛肃穆地触碰到了人类的远古历史，展示着索拉丁国王那持久的砖石建筑工艺，正是他首次统一了散乱的人类部落。",["race:Troll"]="这座破败的防御工事鲜明地提醒着人们那场古老的领土战争，在那场战争中，人类成功阻止了森林巨魔的扩张。"},sec={{t="古代阿拉索的壁垒",b="索拉丁之墙建于近三千年前，是古代斯托姆的西部边境，也是第一个人类统一帝国的核心。索拉丁国王意识到人类刚刚起步的定居点在阿曼尼森林巨魔的掠夺性突袭面前极其脆弱。通过在山谷通道上竖起这道巨大的石墙，阿拉索保卫了其腹地，并锻造出一座可供防御的堡垒，使得人类得以生存，并最终在北方与巨魔的霸权抗衡。"},{t="数个世纪的衰败",b="如今，这座古代屏障已破败不堪。巨大的缺口撕裂了石墙，城垛在数千年的风吹雨打、战火洗礼和无人维护下早已风化。随着阿拉索分裂成相互敌对的王国，以及邻近的洛丹伦最终亡于天灾军团之手，再无中央政权来维护这些砖石结构。现在，旅行者和流浪的强盗可以自由地穿过破损的拱门，往返于希尔斯布莱德和荒野阿拉希高地之间。"}},faq={{q="谁建造了索拉丁之墙？",a="它是由索拉丁国王下令修建的，他是统一人类部落并于近三千年前建立阿拉索帝国的创始人和军阀。",al={"谁建造了索拉丁之墙","索拉丁之墙的建造者","索拉丁之墙的起源"}},{q="这道墙最初为何而建？",a="索拉丁国王下令建造它是为了保护人类的早期首都斯托姆及其初生的定居点，抵御邻近阿曼尼巨魔帝国的猛烈突袭。",al={"索拉丁之墙的用途","为何修建这道墙","索拉丁之墙的作用"}},{q="为什么这座墙在今天破败得如此严重？",a="这座墙经历了数千年的自然风化、冲突和忽视。在阿拉索帝国分裂为独立的人类国家后，这座宏伟的边境防御工事失去了战略重要性，逐渐走向了衰败。",al={"索拉丁之墙为何破损","谁摧毁了索拉丁之墙","为何荒废"}},{q="索拉丁之墙分隔了哪些区域？",a="这道墙构成了天然的陆路边界，将西侧郁郁葱葱的希尔斯布莱德丘陵与东侧崎岖的阿拉希高地隔开。",al={"索拉丁之墙在哪里","这道墙分隔了什么","索拉丁之墙的边界"}}},fx={b3263746={q="索拉丁之墙是什么地方？",a="索拉丁之墙是一道古老而宏伟的石墙，横跨阿拉希高地与希尔斯布莱德丘陵的边界。它在数千年前阿拉索帝国鼎盛时期建成，曾是人类宏伟的防御屏障，用来保护斯托姆周围的腹地免受阿曼尼巨魔的猛烈侵袭。如今，这道墙虽饱经风霜、残破不堪，高耸的拱门和崩塌的石块仍矗立在贸易大道旁。",al={"索拉丁之墙是什么","索拉丁之墙信息","关于索拉丁之墙"}},a3fa6dab={q="索拉丁之墙发生过什么？",a="数代以来，这道墙抵御了祖阿曼森林巨魔无数次袭击，守护着人类的发祥地。此后的数百年间，疏于维护、战争和岁月侵蚀使它的防御逐渐衰败，最终只剩下如今的废墟。",al={"索拉丁之墙的历史","索拉丁之墙的战斗","这里发生了什么"}},bb7d6206={q="为什么叫索拉丁之墙？",a="这道墙以索拉丁大帝之名命名，以纪念这位传奇统帅。他曾首次统一彼此交战的人类部族，建立辉煌的阿拉索帝国。在建立帝国并创建宏伟首都斯托姆后不久，索拉丁便下令修建这座庞大的防御工事，以抵御险恶荒野中的威胁，确保人类得以生存，也让他的名字永远铭刻在这片边境的石墙上。",al={"为什么叫索拉丁之墙","索拉丁之墙以谁命名","索拉丁之墙名称"}}},fp="15,288,28.497.0,18.490.0,26.154.0,42.172.0,37.241.0,43.140.0"}
P.entries["subzone:thorium-point"] = {n="瑟银哨塔",s="瑟银哨塔矗立在灼热峡谷北侧的峭壁之上，是瑟银兄弟会的主要据点。在这个中立前哨站，这些离群的黑铁矮人招募过往的冒险者，并向深入火山荒地的残暴同族发起反击。",h="瑟银哨塔矗立在灼热峡谷北侧的峭壁之上，是瑟银兄弟会的主要据点。在这个中立前哨站，这些离群的黑铁矮人招募过往的冒险者，并向深入火山荒地的残暴同族发起反击。",kw={"锻造","黑铁","观火岭","飞行点","灼热峡谷","瑟银兄弟会","瑟银哨塔"},ang={["profession:Blacksmithing"]="这里的黑铁矮人铁匠掌握着被全世界金属加工者垂涎的贸易秘密，他们会向提供火山矿石和零件的工匠出售稀有的锻造图纸。",["race:Dwarf"]="见到那些不会立刻试图谋杀你的黑铁矮人是很罕见的，但铜须旅行者知道，这些流放者纯粹是出于对技艺和生存的追求，而不是因为对铁炉堡的热爱。"},sec={{t="灰烬之上的立足点",b="瑟银哨塔俯瞰着灼热峡谷中焦黑的矿渣堆，是一座因局势所迫而建的简朴山间营地。它由瑟银兄弟会控制，这是一个与暗炉城内受奴役的同族断绝关系的黑铁矮人叛军派系。这些流放者不愿向火焰之王或达格兰·索瑞森大帝低头，他们在观火岭东北方维持着一座露天熔炉、一个繁忙的飞行管理员哨位，以及严密防守的警戒区。由于生存斗争的残酷以及对大师级锻造的追求，兄弟会向联盟和部落双方开放营地，欢迎任何愿意从灰烬中挖掘矿石或敲碎黑铁矮人头骨的人。"},{t="旅行者的中转站",b="Beyond being a staging ground for the Brotherhood's war against their brethren, Thorium Point is an indispensable crossroads in the heart of the Redridge mountain chain. Perched safely above the ravenous spiders and fire elementals that prowl the volcanic basin, the outpost offers direct flight links to Ironforge, as well as forward camps across the Badlands and the Burning Steppes. For wandering mercenaries, prospectors, and crafters looking to earn the secretive favor of master dwarf smiths, this smoky cliffside is the safest hearth to be found in the Gorge."}},faq={{q="谁控制着瑟银哨塔？",a="该前哨站由瑟银兄弟会控制，这是一群脱离了黑铁矮人阵营的组织，他们拒绝火元素皇帝的统治，寻求锻造属于自己的命运，摆脱元素的奴役。",al={"谁在经营瑟银哨塔","瑟银哨塔的主人","谁住在瑟银哨塔"}},{q="为什么瑟银哨塔对联盟和部落保持中立？",a="瑟银兄弟会的人数远少于敌对的黑铁矮人同族和灼热峡谷中的野兽。他们承担不起与过往冒险者为敌的后果，因此他们进行自由贸易，并雇佣不分阵营的雇佣兵。",al={"为什么部落可以使用瑟银哨塔","瑟银哨塔是中立的吗","联盟部落瑟银哨塔"}},{q="瑟银哨塔提供什么服务？",a="该营地设有连接铁炉堡、荒芜之地和燃烧平原的飞行管理员，此外还有基础的贸易商人、可使用的熔炉和铁砧，以及针对黑铁矮人的当地工作订单。",al={"瑟银哨塔飞行点","瑟银哨塔有什么","瑟银哨塔商人"}},{q="瑟银哨塔在灼热峡谷的什么位置？",a="它坐落在灼热峡谷北侧的岩壁上，位于观火岭东北方的高处，可以俯瞰火山口底部。",al={"如何找到瑟银哨塔","瑟银哨塔位置","瑟银哨塔在哪里"}}},fp="13,297,24.703.0,26.566.0,27.202.0,60.250.0,45.205.0,48.134.0"}
P.entries["subzone:thorn-hill"] = {n="荆棘岭",s="荆棘岭是坐落于贫瘠之地十字路口东侧高岭之上的一处防御森严的钢鬃野猪人聚居地。该定居点是野猪人战团袭击往来于杜隆塔尔和内陆稀树草原之间的部落补给线的作战前哨。",h="荆棘岭是坐落于贫瘠之地十字路口东侧高岭之上的一处防御森严的钢鬃野猪人聚居地。该定居点是野猪人战团袭击往来于杜隆塔尔和内陆稀树草原之间的部落补给线的作战前哨。",kw={"贫瘠之地","十字路口","野猪人","钢鬃","刺鼻","荆棘岭"},ang={["faction:Horde"]="保障十字路口和杜隆塔尔之间的道路安全对新生部落至关重要，这使得荆棘岭中那些侵略成性的袭击者成为了新晋战士亟待解决的目标。"},sec={{t="部落的眼中钉",b="荆棘岭位于杜隆塔尔和十字路口之间崎岖山脉的北坡，占据了监视贫瘠之地主要贸易走廊的有利位置。该定居点盘踞着一群危险的钢鬃部族野猪人，其中包括猎手、驯养的座狼以及能够塑地的大地塑师。在老地卜师刺鼻等秘术师的指引下，这里的野猪人不断加剧对过往部落补给商队的袭击。由于这个山地营地紧邻重要的运输路线，十字路口的卫兵将荆棘岭视为中部稀树草原最紧迫的军事威胁之一。"}},faq={{q="什么是荆棘岭？",a="荆棘岭是位于贫瘠之地北部山坡上的一处钢鬃野猪人大型营地，正处于十字路口与杜隆塔尔边界之间。",al={"荆棘岭位置","荆棘岭在哪里","这个营地是什么"}},{q="谁领导着荆棘岭的野猪人？",a="这里野猪人中最著名的人物是老地卜师刺鼻，这是一位指导该部族战团的钢鬃秘术师。",al={"荆棘岭首领","谁统治荆棘岭"}},{q="为什么部落要在这里与野猪人作战？",a="以荆棘岭为基地的钢鬃战团经常伏击从杜隆塔尔跨越边界前往十字路口的部落补给商队，迫使当地的部落当局派遣战士前往肃清这些山岭。",al={"为何攻击荆棘岭","部落商队遇袭","十字路口野猪人"}},{q="荆棘岭里有哪些种类的敌人？",a="该营地由钢鬃大地塑师、猎手、驯养的座狼和凶猛的狂暴者守护。",al={"荆棘岭怪物","荆棘岭野猪人类型"}}},fx={e0126d7b={q="荆棘岭危险吗？",a="荆棘岭对往来于杜隆塔尔和十字路口之间的旅人构成严重威胁。山坡上的聚居地防守森严，驻有敌对的剃刀沼泽地卜师、猎手和受训的狼，并由长者秘法师剃须领导的秘法师等人指挥。这些野猪人会主动袭击途经的部落商队，因此毫无防备的旅人一踏入他们设防的领地，就会立即遭到攻击。",al={"荆棘岭危险吗","荆棘岭的危险","荆棘岭有多危险"}}},fp="10,259,27.622.0,19.169.0,37.129.0,44.217.0,41.102.0"}
P.entries["subzone:three-corners"] = {n="三角路口",s="三角路口是一个坐落在赤脊山西部边界内的重要十字路口。它向三个邻近的城镇——闪金镇、湖畔镇和夜色镇分岔延伸，标志着王国中心地带与赤脊山险恶荒野之间的分界线。一座暴风城卫兵的瞭望塔矗立在这个交叉路口上方，守卫着防线，抵御着不断入侵的豺狼人族群。",h="三角路口是一个坐落在赤脊山西部边界内的重要十字路口。它向三个邻近的城镇——闪金镇、湖畔镇和夜色镇分岔延伸，标志着王国中心地带与赤脊山险恶荒野之间的分界线。一座暴风城卫兵的瞭望塔矗立在这个交叉路口上方，守卫着防线，抵御着不...",kw={"十字路口","夜色镇","豺狼人","闪金镇","湖畔镇","赤脊山","三角路口","瞭望塔"},ang={["faction:Alliance"]="对于离开相对安全的艾尔文森林的联盟旅行者来说，三角路口是第一个设防的前哨站，也是一个严酷的提醒：暴风城对边境地区的控制力已捉襟见肘。",["race:Human"]="这座瞭望塔连接着南部人类中心地带，是往来于艾尔文、暮色森林和赤脊山之间的信使和贸易的关键枢纽。"},sec={{t="三个地区的十字路口",b="三角路口位于赤脊山西缘，连接着三个重要的联盟定居点：西面的艾尔文森林中的闪金镇、东北面的湖畔镇，以及南面暮色森林中的夜色镇。由于这一战略枢纽的重要性，暴风城在路口中心建立了瞭望塔。驻守在这里的当地卫兵和侦察兵试图清理道路，抵御来自赤脊山好战的豺狼人，这些豺狼人不断威胁着穿行于这些地区之间的旅行者和补给马车。"}},faq={{q="这个地方为什么叫三角路口？",a="这个交叉路口分成了三条通往暴风城南部“三个地区”的独特道路：艾尔文森林的闪金镇、赤脊山的湖畔镇以及暮色森林的夜色镇。",al={"三角路口命名含义","为什么叫三角路口","三角路口历史"}},{q="谁在镇守三角路口的塔楼？",a="这个被称为瞭望塔的前哨站由暴风城卫兵驻守。他们作为预警哨点和防御壁垒，抵御着从赤脊山山峰向下进发并试图靠近艾尔文边界的豺狼人。",al={"谁控制三角路口","瞭望塔卫兵","塔里驻守的是谁"}},{q="三角路口周围有哪些活跃的威胁？",a="来自周围山丘的豺狼人不断在道路上游荡，伏击旅行者和信使。驻扎在这里的卫兵经常请求路过的冒险者清除豺狼人族群，以保持道路畅通。",al={"三角路口的怪物","三角路口的危险","三角路口的豺狼人"}}},fx={["36588b3d"]={q="什么是三角路口？",a="三角路口是一处重要的交通枢纽，位于赤脊山西南边境内侧。三条大道从这个中心路口分出，分别通往三个地区重镇：艾尔文森林的闪金镇、赤脊山的湖畔镇，以及暮色森林深处的夜色镇。暴风城卫兵驻守的瞭望塔是这处重要路口的中心防御据点。",al={"这是什么地方","三角路口在哪里","三角路口概况"}},["4545d69d"]={q="三角路口危险吗？",a="瞭望塔驻扎的暴风城哨兵会守护路口本身，但附近的山丘和小径危机四伏。当地的豺狼人群不断在灌木丛间游荡，沿路伏击毫无防备的旅人。强烈建议途经此地的人留在驻军瞭望塔附近，不要独自深入荒野灌木丛。",al={"三角路口安全吗","三角路口的危险","三角路口的威胁"}}},fp="13,386,28.513.0,39.182.0,38.217.0,45.216.0"}
P.entries["subzone:thunder-axe-fortress"] = {n="雷斧堡垒",s="雷斧堡垒是位于凄凉之地西北部的一处防御工事，也是恶魔化的火刃氏族的大本营。在石制的兵营、瞭望塔和阴暗的洞穴中，邪教徒们进行着黑暗仪式，召唤恶魔实体并储藏偷来的强大神器。对于任何穿越这片荒凉废土的人来说，这个邪教仍然是一个活跃的威胁。",h="雷斧堡垒是位于凄凉之地西北部的一处防御工事，也是恶魔化的火刃氏族的大本营。在石制的兵营、瞭望塔和阴暗的洞穴中，邪教徒们进行着黑暗仪式，召唤恶魔实体并储藏偷来的强大神器。对于任何穿越这片荒凉废土的人来说，这个邪教仍然是一个...",kw={"火刃氏族","凄凉之地","伊鲁克斯之手","科霍尔","光明权杖","雷斧堡垒","泰拉尼斯·马莱姆"},ang={["class:Warlock"]="火刃氏族在堡垒中的实验展示了恶魔学肆无忌惮的界限，从束缚次级恶魔到强行开启通往更强大实体的位面裂隙。",["faction:Alliance"]="调查雷斧堡垒符合银色黎明的努力，即在邪能崇拜者利用它们对抗整个大陆之前，确保像光明权杖这样危险的神器处于安全状态。"},sec={{t="火刃氏族的堡垒",b="雷斧堡垒坐落在凄凉之地西北部，是火刃氏族严加防守的堡垒。它由石制兵营、防御瞭望塔和深邃的洞穴组成，使该邪教能够在远离卡利姆多各大城市视野的地方维持一个坚固的立足点。在这里，邪教徒们聚集邪能，召唤次级恶魔，并策划将更危险的实体带入这个世界。"},{t="被盗圣物与黑暗召唤",b="该邪教将伊鲁克斯之手储存在这座堡垒中，这是一件与玛诺洛克集会所的恶魔传送门有关的圣物。一名火刃氏族先知也在其中一座瞭望塔顶端研究被盗的光明权杖。阿佐尔·奥达蒙特请求旅行者取回这把权杖，据传它是从娜迦手中夺走的。"}},faq={{q="谁控制着雷斧堡垒？",a="这座堡垒由火刃氏族控制，这是一个致力于恶魔力量和影子议会残党的组织。在地面上，这座堡垒及其行动由泰拉尼斯·马莱姆等术士监督。",al={"谁管理雷斧堡垒","谁在雷斧堡垒","雷斧堡垒首领"}},{q="什么是光明权杖？",a="光明权杖是一件古老的神器，据说能够将整座城市沉入海底。阿佐尔·奥达蒙特请求旅行者从一名在堡垒瞭望塔顶端研究它的火刃氏族先知手中夺回它。",al={"光明权杖","被盗的娜迦神器"}},{q="这座堡垒与玛诺洛克集会所有什么联系？",a="雷斧堡垒的邪教徒持有一件被称为伊鲁克斯之手的神器。这件圣物直接连接着凄凉之地南部的玛诺洛克集会所中活跃的恶魔传送门，将他们在该地区的恶魔行径联系在一起。",al={"与玛诺洛克集会的联系","伊鲁克斯之手"}}},fp="20,359,30.415.0,33.304.1,34.223.1,29.221.1,49.232.0"}
P.entries["subzone:thunder-bluff"] = {n="雷霆崖",s="雷霆崖是牛头人高耸的都城，从莫高雷的草海平原上拔地而起，高出地面数百英尺。它由凯恩·血蹄在第三次战争后建立，作为一个统一的庇护所和文化中心，服务于那些世代游牧的民族。",h="雷霆崖是牛头人高耸的都城，从莫高雷的草海平原上拔地而起，高出地面数百英尺。它由凯恩·血蹄在第三次战争后建立，作为一个统一的庇护所和文化中心，服务于那些世代游牧的民族。",kw={"凯恩·血蹄","大地母亲","野性图腾","台地","莫高雷","预见之池","牛头人","雷霆崖"},ang={["faction:Horde"]="雷霆崖为部落提供了卡利姆多南部的一个重要据点，与兽人的奥格瑞玛一道，成为了智慧与资源的坚实锚点。",["race:Tauren"]="对于牛头人来说，雷霆崖代表着他们世代漂泊后的第一个真正永久的家园，这里保存着他们神圣的图腾、灵魂小屋和最伟大的酋长们。"},sec={{t="高台之上的避难所",b="在无数个世代里，牛头人作为游牧民族在卡利姆多中部四处漂泊，不断遭到野蛮的半人马掠夺者的侵扰。那段逃亡的岁月在第三次战争期间画上了句号，当时凯恩·血蹄与大酋长萨尔以及新部落建立了荣誉盟约。他们齐心协力击退了半人马的威胁，夺回了肥沃的莫高雷大草原。凯恩召集了分散的部落，在一系列平坦的天然石制台地上建立了雷霆崖。今天，这座城市通过令人目眩的绳索吊桥连接，并由巧妙的木制升降梯提供出入，既提供了绝对的防御，又成为了一个繁忙的贸易与精神聚集中心。"},{t="团结与汇聚之雾",b="虽然雷霆崖是一座和谐的灯塔，但其高耸的地势容纳了不同的派系。大多数部落尊崇凯恩·血蹄的智慧，然而在长者高地的玛加萨·野性图腾及其族人等传统派别中，分歧正悄然酝酿。在城市地表深处是地下的预见之池，灵魂行者和萨满祭司在此洞察祖先的意志。尽管存在潜在的部落竞争，雷霆崖依然是卡利姆多部落真正的精神支柱，欢迎从贫瘠之地归来的猎人、旅行的工匠以及与大地母亲沟通的德鲁伊。"}},faq={{q="旅行者如何前往雷霆崖？",a="旅行者可以通过位于西南和东北悬崖上的巨型木制绳索与滑轮升降梯进入城市，也可以直接飞往位于中央台地顶部的风骑士之巢。",al={"雷霆崖升降梯","如何前往雷霆崖","进入雷霆崖"}},{q="为什么牛头人要将城市建在悬崖上？",a="在忍受了几个世纪在开阔地带遭受的无休止的半人马突袭后，凯恩·血蹄选择了高耸的石制台地，为他那游牧的族人提供了一处坚不可摧的避难所，并可俯瞰莫高雷的神圣牧场。",al={"为什么要用台地","为何建在高耸的悬崖上","雷霆崖防御"}},{q="谁统治着雷霆崖？",a="大酋长凯恩·血蹄领导着雷霆崖。他团结了分散的部落并确保了莫高雷的和平，在各高地部落领袖和长者的建议下进行统治。",al={"雷霆崖的领袖","谁是酋长","凯恩 雷霆崖"}},{q="所有的牛头人部落都效忠于凯恩吗？",a="虽然绝大多数人尊崇凯恩的智慧，但一些群体——最著名的是由老妪玛加萨领导的野性图腾部族——对部落联盟持有怀疑态度，并寻求牛头人自己的发展道路。",al={"野性图腾 雷霆崖","雷霆崖的部落","牛头人政治对手"}}},fx={f3581e0f={q="什么是雷霆崖？",a="雷霆崖是牛头人的首都，坐落于莫高雷北部一片高耸而多风的台地群之上。城中以绳桥和高耸的升降梯相连，长屋、帐篷和灵魂小屋鳞次栉比，构成一处繁忙的庇护所。这是牛头人在数个世纪的游牧生活后，建立并据有的第一个永久家园。",al={"什么是雷霆崖","介绍雷霆崖","雷霆崖的背景故事"}},d7d48e60={q="雷霆崖是如何建立的？",a="数代以来，牛头人以游牧部族的形式生活，时常遭到四处劫掠的半人马追猎。第三次战争期间，酋长凯恩·血蹄与萨尔和新部落结盟。他们一同击退半人马，守住了莫高雷这片富饶的平原。凯恩在高耸的崖地上建立了这座城市，作为安全的避难所，将四散的牛头人部族团结起来。",al={"雷霆崖的历史","谁建立了雷霆崖","雷霆崖的起源"}},["4fba0646"]={q="雷霆崖安全吗？",a="这座城市本身是部落防守严密的庇护所，不过若在边缘附近失足，陡峭的悬崖足以致命。除了地势险峻，和平之下也潜藏着政治上的紧张局势：一些敌对势力，例如恐怖图腾部族，仍未完全融入凯恩统一的部族联盟。",al={"雷霆崖安全吗","雷霆崖的危险","雷霆崖的威胁"}}},fp="13,279,23.664.0,25.602.0,41.205.0,46.220.0,24.188.0,38.215.0"}
P.entries["subzone:thunder-falls"] = {n="雷霆瀑布",s="雷霆瀑布是隐藏在艾尔文森林西北高地上的一处偏僻山谷。它坐落在陡峭的悬崖之间，咆哮的瀑布为其注入水源，这里有一座安静的河畔小屋，现已被当地强盗占据。",h="雷霆瀑布是隐藏在艾尔文森林西北高地上的一处偏僻山谷。它坐落在陡峭的悬崖之间，咆哮的瀑布为其注入水源，这里有一座安静的河畔小屋，现已被当地强盗占据。",kw={"强盗","小屋","艾尔文森林","明镜湖","雷霆瀑布","瀑布"},sec={{t="隐藏的山中空地",b="雷霆瀑布隐藏在明镜湖上方的锯齿状山脊中，是一处不同寻常的地理裂隙。这条峡谷由湍急的山间溪流冲刷而成，溪流经由一处无法接近的北部瀑布进入，随后在两侧形成壮观的瀑布倾泻而下。一侧向下汇入明镜湖，而下游则向西流向西部荒野崎岖的边界。尽管水声轰鸣，岸边仍坐落着一座小屋、一个码头和一个户外铁砧，不过强盗们现在已经将这片宁静的空地据为己有。"}},faq={{q="如何前往雷霆瀑布？",a="你可以前往艾尔文森林明镜湖的北侧来抵达雷霆瀑布。一条陡峭狭窄的小径沿着明镜湖瀑布的右侧蜿蜒向上，直通这处偏僻的峡谷。",al={"如何前往雷霆瀑布","雷霆瀑布位置","雷霆瀑布在哪里"}},{q="谁住在雷霆瀑布的小屋里？",a="这座偏僻的小屋似乎曾属于一位孤独的渔夫或边疆拓荒者，配有码头、划艇和户外铁砧。然而如今，它已成为在艾尔文森林荒野中活动的强盗们的隐秘据点。",al={"小屋里有什么人","雷霆瀑布房屋","小屋强盗"}},{q="雷霆瀑布的河流流向哪里？",a="溪流从上方的山间瀑布流出，穿过狭窄的山口。在下游，它蜿蜒经过小屋，随后从另一处陡峭的瀑布倾泻而下，汇入靠近西部荒野东部边界的地方。",al={"水流向哪里","雷霆瀑布河流"}}},fx={["1050bd39"]={q="什么是雷霆瀑布？",a="雷霆瀑布是一处隐秘的山间峡谷，藏在艾尔文森林西北部的高地之中。河水源自北方高崖上一处难以抵达的瀑布，穿过两道瀑布之间的狭窄峡谷，一侧向下流入明镜湖，另一侧则向西奔流至西部荒野边界。这里远离尘嚣，藏着一间僻静的乡间小屋和一座小码头，山泉冰冷清冽。",al={"什么是雷霆瀑布","雷霆瀑布的背景故事","介绍雷霆瀑布"}},db2700a0={q="雷霆瀑布危险吗？",a="这里看似宁静，行走时仍须格外小心。亡命之徒和迪菲亚相关的匪徒在那间偏僻的小屋周围扎营，利用瀑布上方隐蔽且易守难攻的地势。此外，陡峭的悬崖和轰鸣的瀑布也难以应付，稍有不慎便可能跌入下方的急流。",al={"雷霆瀑布安全吗","雷霆瀑布的匪徒","雷霆瀑布的威胁"}}},fp="13,246,24.529.0,31.232.0,42.247.0,43.207.0"}
P.entries["subzone:thunder-ridge"] = {n="雷霆山",s="雷霆山是杜隆塔尔西部的一处崎岖峡谷，位于奥格瑞玛西南方，怒水河畔。这里曾经是一片古木参天的葱郁树林，是雷霆蜥蜴群的栖息地。由于人类的伐木作业和黑暗巫术，峡谷遭受了严重的森林砍伐。如今，狂暴的野兽和残留的邪教徒对附近的定居点构成了持续威胁。",h="雷霆山是杜隆塔尔西部的一处崎岖峡谷，位于奥格瑞玛西南方，怒水河畔。这里曾经是一片古木参天的葱郁树林，是雷霆蜥蜴群的栖息地。由于人类的伐木作业和黑暗巫术，峡谷遭受了严重的森林砍伐。如今，狂暴的野兽和残留的邪教徒对附近的定居...",kw={"火刃氏族","杜隆塔尔","菲兹尔·暗爪","奥戈尼尔·魂痕","雷克萨","怒水河","雷霆蜥蜴","雷霆山","犹塞克"},ang={["class:Warrior"]="像犹塞克这样的战士导师会派他们的学员进入雷霆山，以测试他们对抗野生雷霆蜥蜴纯粹的物理力量和闪电冲击时的防御能力。",["faction:Horde"]="这座山脊坐落在奥格瑞玛西侧的峭壁外，必须清除像菲兹尔·暗爪这样的火刃氏族特工，以防止在首都门口发生恶魔颠覆活动。"},sec={{t="伤痕累累的庇护所",b="不久之前，雷霆山还是干旱的杜隆塔尔中难得的一片绿色天堂，依靠古树维持着生态。第三次战争结束后不久，来自库尔提拉斯的人类入侵者开始砍伐此地的树木，这种平静便被打破了，随之而来的还有雷霆蜥蜴的暴动。后来，火刃氏族施展的邪能巫术彻底摧毁了这里，剥去了树冠，留下一片荒芜而裸露的峡谷，愤怒的雷霆蜥蜴现在在这里横行无忌。"},{t="邪教徒与力量的试炼",b="奥格瑞玛的居民时刻警惕着这座山脊。火刃氏族在术士菲兹尔·暗爪（Fizzle Darkclaw）的带领下在此盘踞，利用恶魔魔法在杜隆塔尔散播混乱。像奥戈尼尔·魂痕这样的部落老兵指派侦察兵去清剿这些邪教党羽，而像犹塞克这样的战士训练师则会将渴望成为勇士的新兵送入山谷，以测试他们面对暴怒的雷霆蜥蜴时的韧性。"}},faq={{q="雷霆山的树木发生了什么？",a="雷霆山曾经是一片茂密的林地，但经历了两次毁灭性的打击。首先，在杜隆塔尔建立后不久，库尔提拉斯的伐木部队为了利益大肆砍伐这里的古树。后来，火刃氏族利用黑暗的恶魔魔法摧毁了幸存的树林，彻底抹去了这片森林。",al={"为什么雷霆山寸草不生","雷霆山森林","雷霆山森林砍伐"}},{q="为什么这里的雷霆蜥蜴如此狂暴？",a="雷霆蜥蜴原本平静地生活在山脊的古树之间，直到外来者的入侵破坏了它们的栖息地。人类伐木带来的噪音和破坏，再加上火刃氏族邪教徒残留的邪能腐化，使蜥蜴群陷入了焦躁的疯狂，从而攻击任何冒险进入峡谷的人。",al={"雷霆山狂暴的蜥蜴","杜隆塔尔的雷霆蜥蜴"}},{q="谁是菲兹尔·暗爪？",a="菲兹尔·暗爪是火刃氏族的一名领袖，他在雷霆山内建立了一个营地。以此为据点，他和他的追随者指挥黑暗仪式以破坏该地区的稳定，这促使奥戈尼尔·魂痕等部落领导人悬赏取他首级。",al={"菲兹尔·暗爪背景故事","暗爪是谁","雷霆山的火刃氏族"}},{q="雷克萨在雷霆山战斗过吗？",a="是的。在杜隆塔尔建立后不久，部落勇士雷克萨曾来到这里，为先知德雷克塔尔采集闪光草。在峡谷中，雷克萨发现了人类的伐木营地，正是这些家伙让蜥蜴变得狂暴，这迫使他不得不猎杀狂暴的野兽并回收它们的蛋，以便让德雷克塔尔进行研究。",al={"雷克萨雷霆山","德雷克塔尔雷霆山"}}},fx={d8d2e909={q="什么是雷霆山？",a="雷霆山是杜隆塔尔西北部一处深邃而林木尽失的峡谷，位于奥格瑞玛西南方不远处。这里曾是一片繁茂的古老森林，也是成群雷霆蜥蜴的传统栖息地。如今，茂密的树冠已不复存在，只剩下荒凉的峭壁、游荡的野兽，以及步步逼近的黑暗教徒。",al={"什么是雷霆山","杜隆塔尔的雷霆山","雷霆山在哪里"}},["675c5d12"]={q="雷霆山发生过什么？",a="杜隆塔尔建立后不久，来自库尔提拉斯的人类在此非法伐木，砍伐古树，激怒了雷霆蜥蜴，直到雷克萨和德雷克塔尔出面干预。后来，火刃氏族教派施展恶魔力量，砍倒了残存的树木，将山谷夷为荒地，也让当地野兽陷入狂暴。",al={"雷霆山的历史","雷霆山的背景故事","雷霆山发生过什么"}},ea9b6430={q="谁住在雷霆山？",a="山脊内没有和平的聚居地。除了成群躁动的雷霆蜥蜴和闪电蜥蜴外，由术士菲兹尔·暗爪率领的一伙火刃氏族教徒也在峡谷中扎下营地，利用黑暗魔法在杜隆塔尔四处制造混乱。",al={"谁住在雷霆山","雷霆山的居民","雷霆山的势力"}},e9504f5d={q="雷霆山危险吗？",a="危险。雷霆蜥蜴天生具有领地意识，最近的黑暗势力干预又让它们变得狂暴而难以预测，甚至会用闪电攻击入侵者。此外，潜伏在峡谷中的火刃氏族教徒会毫不犹豫地杀死任何调查他们仪式地点的人。",al={"雷霆山有多危险","雷霆山的危险","雷霆山安全吗"}}},fp="13,391,19.466.0,30.418.1,44.317.0,47.331.0,23.279.0,34.309.0"}
P.entries["subzone:thunderbrew-distillery"] = {n="雷酒酿制厂",s="雷酒酿制厂是丹莫罗卡拉诺斯熙熙攘攘的旅店和核心聚会场所。它以其烈性麦芽酒而闻名遐迩，既是一家活跃的酿酒厂，也是过往旅客在雪山山口停留的关键休息站。在室内，顾客可以找到温暖的壁炉、冰凉的扎啤，以及众多的职业导师和当地商人。",h="雷酒酿制厂是丹莫罗卡拉诺斯熙熙攘攘的旅店和核心聚会场所。它以其烈性麦芽酒而闻名遐迩，既是一家活跃的酿酒厂，也是过往旅客在雪山山口停留的关键休息站。在室内，顾客可以找到温暖的壁炉、冰凉的扎啤，以及众多的职业导师和当地商人。",kw={"丹莫罗","矮人麦芽酒","旅店老板贝尔姆","卡拉诺斯","拉格纳·雷酒","雷酒酿制厂"},ang={["profession:Cooking"]="酿酒厂内的厨房提供烹饪训练和补给品，使其成为希望学习如何制作丰盛山区补给的厨师们的关键停靠点。",["race:Dwarf"]="对于离开寒脊山谷的矮人来说，酿酒厂是一个受人喜爱的家，提供熟悉的黑啤酒、靠近炽热壁炉的座位，以及值得信赖的钢铁与信仰导师。"},sec={{t="卡拉诺斯的温暖壁炉",b="雷酒酿制厂坐落在卡拉诺斯的中心，是丹莫罗南部市民生活的核心。它由雷酒氏族创建——由Arkilus Thunderbrew建立并由其族人维护——该酿酒厂以酿造能够抵御刺骨山寒的强劲、温暖的麦芽酒而闻名于Khaz Modan。它作为当地旅店运营，由Innkeeper Belm在楼面管理，为疲惫的登山者提供旺盛的炉火、丰盛的食物和躲避户外暴风雪的床铺。"},{t="知识与技艺的十字路口",b="除了供应著名的烈性黑啤酒外，酿酒厂还是培养冒险者的重要中心。因为卡拉诺斯是旅客离开寒脊山谷后到达的第一个主要定居点，所以雷酒旅店接待着各式各样的训练师。武术、神圣仪式、奥术研究和盗贼技巧的导师们聚集在坚固的木椽下，还有烹饪和急救的指导员，使这个喧闹的酒馆变成了不可或缺的准备站。"}},faq={{q="谁拥有并经营雷酒酿制厂？",a="该机构属于雷酒家族，由Arkilus Thunderbrew创立。他的儿子Ragnar Thunderbrew积极打理家族的酿酒传统，而Innkeeper Belm则负责在卡拉诺斯休息的旅客的接待和住宿工作。",al={"酿酒厂所有者","谁经营雷酒","雷酒家族"}},{q="酿酒厂内提供哪些服务？",a="该酿酒厂是卡拉诺的主要旅店。在室内，旅客可以找Innkeeper Belm绑定炉石，从商人处购买饮料和补给品，并向战士、圣骑士、牧师、法师、潜行者、烹饪和急救的训练师寻求指导。",al={"雷酒酿制厂里有什么","酿酒厂训练师","卡拉诺旅店服务"}},{q="为什么酿酒厂如此出名？",a="该酿酒厂在整个东部王国因酿造异常强劲的矮人麦芽酒（特别是雷酒麦芽酒）而受到赞誉。众所周知，它的啤酒能增强旅客对抗丹莫罗山峰严酷冰冻温度的能力。",al={"为什么雷酒麦芽酒出名","雷酒麦芽酒声誉"}}},fx={["1fa2ba89"]={q="什么是雷酒酿制厂？",a="雷酒酿制厂是卡拉诺斯中心一间热闹的矮人酒馆兼旅店。这里不仅提供温暖的床铺、炉石和醇厚的饮品，也是社区主要的聚集地，登山者、工匠、职业导师和旅人都会在此歇脚，分享来自丹莫罗各地的消息。",al={"什么是雷酒酿制厂","雷酒酒馆","卡拉诺斯的酿酒厂"}},["6c9338b8"]={q="雷酒酿制厂有什么历史？",a="这间酿酒厂由矮人酿酒师阿基鲁斯·雷酒创立，数代以来一直是丹莫罗最出色的酿酒厂之一。如今，它仍由家族经营，由他的儿子拉格纳接手，并继续酿造闻名遐迩的麦酒。",al={"酿酒厂的历史","雷酒酿制厂的历史","谁创立了雷酒酿制厂"}},ec3a2fd6={q="雷酒酿制厂危险吗？",a="完全不危险。酿酒厂是旅人和联盟守卫的安全之所，有登山者和城镇卫兵守护，使其免受卡拉诺斯周边雪山中穴居人、霜鬃巨魔和饥饿野兽的侵扰。",al={"雷酒酿制厂危险吗","酿酒厂安全吗","这里安全吗"}},["1194a384"]={q="为什么叫雷酒酿制厂？",a="酿酒厂的名字来自雷酒家族，他们世代创办并经营着这门生意；这里的地窖也酿造着浓烈的矮人麦酒。",al={"为什么叫雷酒酿制厂","雷酒之名的由来","雷酒酿制厂的名称"}}},fp="22,378,27.500.0,35.495.0,49.249.0,50.270.0,32.244.0"}
P.entries["subzone:thunderhorn-water-well"] = {n="雷角水井",s="雷角水井是位于莫高雷中部草海平原的一处重要水源，坐落在血蹄村和雷霆崖之间的小路上。就像山谷中所有的水井一样，它为游荡在草原上的部落和兽群提供了必要的滋养。保持井水清洁并加以守卫，对于维持牛头人家园的生命至关重要。",h="雷角水井是位于莫高雷中部草海平原的一处重要水源，坐落在血蹄村和雷霆崖之间的小路上。就像山谷中所有的水井一样，它为游荡在草原上的部落和兽群提供了必要的滋养。保持井水清洁并加以守卫，对于维持牛头人家园的生命至关重要。",kw={"血蹄","莫高雷","雷霆崖","雷角","荆棘谷地精","水","水井"},ang={["class:Shaman"]="萨满祭司深切地尊崇莫高雷的纯净泉水，视保护水元素和地下暗流为神圣职责。",["race:Tauren"]="对于牛头人来说，像雷角水井这样的水井是大地母亲赐予的至关重要的生命线，需要不断地守卫，以抵御外来的污染者和贪婪的闯入者。"},sec={{t="生命之源",b="雷角水井坐落在莫高雷中部广袤的草原中，直接连接着滋养整个山谷的纯净含水层。对于游牧的牛头人及其新建的村庄来说，这些公共水井代表着生命、养分和大地母亲的馈赠。由于水在阳光普照的平原上十分珍贵，控制水井就意味着控制这片土地本身。像荆棘谷地精这样的入侵者屡次觊觎这些水源，试图将其用于工业开发，并破坏部落努力维护的脆弱平衡。"}},faq={{q="雷角水井位于何处？",a="该水井位于莫高雷中部，坐落在连接血蹄村与雷霆崖峭壁的南北向道路旁。",al={"雷角水井位置","雷角水井在哪里","雷角水井地图"}},{q="为什么这口水井对牛头人很重要？",a="莫高雷的水井汲取了山谷中纯净的地下水，供养着兽群、朝圣者和定居点。对牛头人而言，水是大地母亲赐予的神圣礼物，必须守护好它，使其免受外界腐化和贪婪的侵害。",al={"为什么雷角水井很重要","牛头人水井的含义","为什么要保护水井"}},{q="谁威胁过这口水井？",a="荆棘谷地精试图夺取水井的控制权，想垄断山谷的水源供应以供其附近的采矿和伐木事业，但当地牛头人进行了反击，收复并净化了水井。",al={"谁攻击了水井","荆棘谷地精水井","雷角水井的敌人"}}},fx={["4280b7a1"]={q="什么是雷角水井？",al={"什么是雷角水井","雷角水井信息","关于雷角水井"}},["254832a1"]={q="雷角水井发生过什么？",a="荆棘谷地精为控制平原上稀缺的水源，派遣武装工人占据了水井。牛头人意识到这对家园构成了严重威胁，于是团结起来驱逐入侵者，为族人夺回清澈的水源。",al={"雷角水井的历史","雷角水井发生过什么","荆棘谷地精与雷角水井"}},b5bd5549={q="雷角水井危险吗？",a="水井属于牛头人，但周围的草原上常有掠食性野兽出没，也有不断侵入、企图掠夺土地资源的荆棘谷地精成员。沿着血蹄村与雷霆崖之间的道路行走时，旅人应保持警惕。",al={"雷角水井危险吗","雷角水井的威胁","雷角安全吗"}}},fp="22,373,20.585.0,44.142.0,47.252.0,28.210.1"}
P.entries["subzone:tidefury-cove"] = {n="狂潮湾",s="狂潮湾是位于尘泥沼泽东南海岸、塞拉摩岛以南的一片险恶水域和岩石浅滩。这里以危险的暗礁和失事船只而闻名，是游荡的迈克罗和孤独垂钓者的隐蔽避风港。",h="狂潮湾是位于尘泥沼泽东南海岸、塞拉摩岛以南的一片险恶水域和岩石浅滩。这里以危险的暗礁和失事船只而闻名，是游荡的迈克罗和孤独垂钓者的隐蔽避风港。",kw={"海湾","尘泥","迈克罗","帕格","普罗德摩尔","暗礁","沉船","塞拉摩","狂潮"},ang={["faction:Horde"]="对于部落而言，这条海岸线是最终反攻的发起地，这场反攻粉碎了海军上将普罗德摩尔的海上侵略，并确保了这个年轻国家的生存。",["profession:Cooking"]="丰富的近海浅滩和邻近垂钓大师纳特·帕格的地理位置，使尘泥沼泽的这一带成为了寻求珍稀渔获的钓鱼者的首选目的地。"},sec={{t="沉船与暗礁的墓地",b="狂潮湾坐落在尘泥海湾的尽头，夹在塞拉摩岛和巨龙沼泽之间，是过往船员眼中臭名昭著的航行险地。多年来，参差不齐的暗礁和移动的浅滩导致多艘船只在此沉没，腐烂的木制船体在潮汐线中半沉半浮。如今，废弃的船只上爬满了投机的迈克罗，使这片海湾变成了一处危险且孤立的海岸线，只有坚韧的拾荒者或希望远离塞拉摩繁忙码头的隐士才会到访这里。"},{t="历史性的立足点",b="在杜隆塔尔入侵期间，狂潮湾的海岸成为了关键的战略战场。戴林·普罗德摩尔上将的库尔提拉斯远征军在海岸上筑起了雄伟的海岸堡垒和岗哨塔，以控制通往塞拉摩的路径。为了打破普罗德摩尔的封锁，萨尔集结了年轻部落的联合力量——联合了兽人、暗矛巨魔和牛头人，并在雷克萨和石槌食人魔的协助下——强行登陆海岸，摧毁了库尔提拉斯的滩头阵地，随后直接向岛上的堡垒挺进。"}},faq={{q="狂潮湾位于何处？",a="狂潮湾位于尘泥沼泽的东南边缘，就在塞拉摩岛以南，与尘泥海湾南端的巨龙沼泽海岸接壤。",al={"狂潮湾位置","狂潮湾在哪里","狂潮湾地图"}},{q="为什么狂潮湾有这么多沉船？",a="海湾里到处是浅沙洲和隐藏的岩礁，使得航行变得极其危险。偏离航线太靠近海岸的船只经常会搁浅，随后海浪和拾荒者很快就会将它们变成残破的船壳。",al={"狂潮湾沉船","狂潮湾的破损船只","尘泥海湾沉船"}},{q="如今谁居住在狂潮湾？",a="除了具有攻击性的海岸迈克罗之外，该海湾最著名的居民是著名的垂钓者纳特·帕格，他在外围的一座小岛上维持着一个被称为Nat's Landing的营地。",al={"谁在狂潮湾","狂潮湾居民","纳特·帕格位置"}},{q="过去这里发生过什么战斗？",a="在戴林·普罗德摩尔上将针对新部落的战役期间，库尔提拉斯军队在此建造了一座防御森严的海岸据点。萨尔的部落在牛头人和食人魔盟友的支援下，发起进攻并摧毁了该基地，从而扫清了前往塞拉摩岛的道路。",al={"狂潮湾之战","魔兽争霸3狂潮湾","杜隆塔尔入侵狂潮湾"}}},fp="13,267,30.529.0,21.548.0,31.167.0,42.233.0,33.183.0,40.256.0"}
P.entries["subzone:tidus-stair"] = {n="提度斯阶梯",s="提度斯阶梯是一处天然岩层，由宽阔的阶梯状石台组成，坐落在棘齿城东南方的商旅海岸之上。这里毗邻无尽之海，是两位牛头人萨满祭司与潮汐和水之灵沟通的幽静休憩之所。",h="提度斯阶梯是一处天然岩层，由宽阔的阶梯状石台组成，坐落在棘齿城东南方的商旅海岸之上。这里毗邻无尽之海，是两位牛头人萨满祭司与潮汐和水之灵沟通的幽静休憩之所。",kw={"贫瘠之地","水之先知伊斯伦","马伦·天视","商旅海岸","棘齿城","提度斯阶梯","水之图腾"},ang={["class:Shaman"]="每一位部落萨满祭司最终都会沿着这些海岸阶梯走下来，在绑定水之图腾的试炼过程中寻找水之先知伊斯伦。",["race:Tauren"]="水之先知伊斯伦和马伦·天视的静默守护表明，牛头人先知即使在莫高雷的边界之外，依然保持着精神上的守望。"},sec={{t="通往海洋的阶梯",b="沿着棘齿城东南方蜿蜒而下，提度斯阶梯看起来就像是一套直接开凿在海岸峭壁上的巨大石阶。虽然周围的贫瘠之地干燥、尘土飞扬且常有冲突，但这段俯瞰商旅海岸的静谧地带却只剩下汹涌的海浪声。台地上坐落着一座简陋的小屋，牛头人水之先知伊斯伦和马伦·天视居住于此。远离地精繁忙的贸易码头，他们日复一日地在此垂钓、凝望地平线，并向海岸的水之灵寻求启迪。"}},faq={{q="提度斯阶梯位于何处？",a="提度斯阶梯位于贫瘠之地的东海岸，就在地精港口棘齿城的正东南方。它俯瞰着商旅海岸的水域。",al={"提度斯阶梯位置","提度斯阶梯在哪里","如何前往提度斯阶梯"}},{q="谁住在提度斯阶梯？",a="有两位牛头人以此为家：水之先知伊斯伦和马伦·天视。他们住在台地上的一座简朴海边小屋里，终日垂钓并与自然沟通。",al={"提度斯阶梯有什么人","提度斯阶梯npc","谁住在这里"}},{q="为什么提度斯阶梯对萨满祭司很重要？",a="寻求掌握水元素的部落萨满祭司会得到指引，穿越卡利姆多前往提度斯阶梯寻找水之先知伊斯伦。在这里，面对着广阔的海洋，初学者们学习与潮汐沟通，并寻找纯净之水来绑定他们的水之图腾。",al={"萨满 提度斯阶梯","水之图腾 提度斯阶梯","为什么萨满祭司来这里"}},{q="提度斯阶梯是属于部落还是中立的？",a="居住于此的牛头人效忠于部落并指导部落萨满祭司，尽管这些偏远的台地处于任何正式的军事边界之外。",al={"提度斯阶梯是部落的吗","提度斯阶梯阵营"}}},fx={["95879c45"]={q="什么是提度斯阶梯？",a="提度斯阶梯是商旅海岸上一处引人注目的天然地貌，位于棘齿城东南方。几层宽阔的岩石阶地如同巨大的石阶，向无尽之海延伸而下。阶地上有一处简朴的海边庇护所，静静俯瞰海浪，为这片繁忙而干燥的贫瘠之地海岸带来一处宁静的栖身之所。",al={"什么是提度斯阶梯","提度斯阶梯概况","提度斯阶梯的背景故事"}},["4cc68021"]={q="提度斯阶梯危险吗？",a="阶梯本身是一处宁静的避风港，远离开阔平原上的直接威胁。然而，周围的商旅海岸常有沿岸野生动物和附近南海据点的危险海盗出没，因此旅人沿海岸向南行进时应保持警惕。",al={"提度斯阶梯安全吗","提度斯阶梯的危险","提度斯阶梯的威胁"}}},fp="11,254,16.579.0,29.153.0,25.174.0,42.242.0,49.135.0"}
P.entries["subzone:timbermaw-hold"] = {n="木喉要塞",s="木喉要塞是一个设防的地下隧道网络，连接着费伍德森林、月光林地和冬泉谷。它是木喉熊怪的堡垒，也是抵抗在卡利姆多北部肆虐的恶魔腐蚀的最后几个部落之一。",h="木喉要塞是一个设防的地下隧道网络，连接着费伍德森林、月光林地和冬泉谷。它是木喉熊怪的堡垒，也是抵抗在卡利姆多北部肆虐的恶魔腐蚀的最后几个部落之一。",kw={"费伍德森林","熊怪","月光林地","木喉","木喉要塞","隧道","冬泉谷"},ang={["class:Druid"]="这座要塞是连接你在月光林地的神圣避难所和费伍德森林伤痕累累的荒野之间的一条重要山道，在森林里，熊怪的灵魂急需净化。",["class:Shaman"]="尽管洞穴大门外邪能腐蚀不断恶化，但木喉熊怪依然坚定地维护着他们未受腐蚀的灵性传统和治疗仪式。"},sec={{t="腐朽中的避难所",b="木喉要塞深凿于费伍德森林、月光林地和冬泉谷之间的山根之中，是一座被拼死守卫的堡垒。虽然邻近的熊怪部落在第三次战争期间屈服于燃烧军团的邪恶腐蚀，但木喉部族在这些石砌通道内熬过了这场梦魇。尽管身处地底十分安全，但他们只能眼睁睁看着自己深爱的森林扭曲成腐烂的怪物。这些熊怪极具防御性且对外来者充满猜疑，他们凶狠地守卫着每一个隧道入口，时刻准备应对任何从被感染的树林中游荡而来的威胁。"},{t="北方十字路口",b="除了作为部落的避难所外，木喉要塞还是连接费伍德森林被污染的低地、月光林地神圣的避难所以及冬泉谷冰封原野的唯一一条直接山路。外来者若想通过而不被部落哨兵撕碎，就必须证明自己的善意。那些证明自己反对该地区腐化的熊怪部族的人，会发现木喉熊怪是坚定的盟友，愿意分享他们古老的萨满知识和制皮传统。"}},faq={{q="为什么木喉要塞的熊怪会攻击访客？",a="木喉部族在目睹邻近同胞屈服于燃烧军团的腐蚀后，天生对外来者充满不信任。由于担心陌生人将他们与那些陷入疯狂、被恶魔腐蚀的熊怪混为一谈，或者担心外来者将腐蚀带入他们的家园，他们在访客证明自己并无恶意之前，会攻击任何靠近隧道的生物。",al={"为什么木喉熊怪充满敌意","木喉熊怪攻击我","如何提升木喉熊怪声望"}},{q="木喉要塞连接哪些地区？",a="主洞穴分支出三个主要出口：西南方向的费伍德森林北部、北方向宁静的月光林地，以及东方向冰霜覆盖的冬泉谷。在艾萨拉北部还有一扇封闭的大门。",al={"木喉要塞隧道终点","木喉要塞通向哪里","木喉要塞出口"}},{q="木喉熊怪是如何在军团的腐蚀下幸存的？",a="当费伍德森林在恶魔邪能的侵蚀下枯萎时，木喉部族退避到了深山洞穴中。通过在恶魔入侵最猖獗时将要塞封死，他们在邻近部族陷入疯狂时，得以保全了理智和神圣的萨满之道。",al={"为什么木喉熊怪没有被腐蚀","木喉熊怪未受腐蚀"}},{q="要塞内那扇封闭的木门是什么？",a="在隧道更深处，有一道圆形的木制屏障阻挡着一个侧洞。其确切用途尚不明确，但旅行者推测它封锁了通往深渊之巢或其他海加尔山下古老地下室的旧隧道群。",al={"木喉要塞中被封锁的门","木喉要塞锁住的大门"}}},fp="14,250,24.597.0,23.517.0,54.342.0,40.232.0,49.316.0,47.257.0"}
P.entries["subzone:timbermaw-post"] = {n="木喉岗哨",s="木喉岗哨是一个小型的熊怪营地，位于白雪皑皑的冬泉谷，坐落在冰火温泉和凯斯利尔湖之间。尽管这里有着未受污染的木喉部族之名，但该营地实际上已经落入了深受腐蚀的冬泉熊怪的魔爪之中。",h="木喉岗哨是一个小型的熊怪营地，位于白雪皑皑的冬泉谷，坐落在冰火温泉和凯斯利尔湖之间。尽管这里有着未受污染的木喉部族之名，但该营地实际上已经落入了深受腐蚀的冬泉熊怪的魔爪之中。",kw={"冰火温泉","熊怪","凯斯利尔湖","木喉","木喉岗哨","冬泉","冬泉谷"},ang={["class:Druid"]="对于那些将熊怪视为自然古老守护者的德鲁伊来说，看到营地被受疯狂驱使的冬泉熊怪所占据，正是燃烧军团余毒的鲜明写照。"},sec={{t="一座被取代的哨站",b="木喉岗哨位于冰火温泉东南侧的道路对面，凯斯利尔湖以西，是冬泉谷内熊怪部族内斗的苦涩见证。尽管名为“木喉”，但接近营地的旅行者却不会受到任何欢迎。该哨站被充满敌意的冬泉部族所控制，他们因恶魔的腐蚀而陷入疯狂与暴力。如今，营地里挤满了野蛮的冬泉熊怪，成为了一处侵占中央道路的侵略性据点。"}},faq={{q="为什么冬泉熊怪住在这里，它却被称为木喉岗哨？",a="尽管名字如此，该营地实际上是由受到腐蚀的冬泉部族控制的。其建立的历史尚不为人知。",al={"为什么叫木喉岗哨","谁控制了木喉岗哨","木喉岗哨的熊怪"}},{q="木喉岗哨位于哪里？",a="它位于冬泉谷中部，坐落在冰火温泉东南侧的道路对面，正西邻凯斯利尔湖。",al={"木喉岗哨位置","木喉岗哨在哪里","木喉岗哨地图"}},{q="木喉岗哨的熊怪有敌意吗？",a="是的。即使你已经赢得了真正的木喉部族的友谊，居住在这个哨站的熊怪也属于充满敌意的冬泉部族，他们会对入侵者发起攻击。",al={"这里的熊怪有敌意吗","木喉岗哨友好度","能和木喉岗哨对话吗"}}},fp="14,295,19.525.0,65.110.0,32.137.0,43.188.0"}
P.entries["subzone:tinker-town"] = {n="Tinker Town",s="Tinker Town是坐落在矮人地下城市铁炉堡中的繁华侏儒区。该地区建立的初衷是为了安置诺莫瑞根悲剧陷落后的难民，如今它是大工匠Gelbin Mekkatorque流亡政府的所在地，也是矿道地铁的主要终点站。",h="Tinker Town是坐落在矮人地下城市铁炉堡中的繁华侏儒区。该地区建立的初衷是为了安置诺莫瑞根悲剧陷落后的难民，如今它是大工匠Gelbin Mekkatorque流亡政府的所在地，也是矿道地铁的主要终点站。",kw={"矿道地铁","工程学","诺莫瑞根","铁炉堡","mekkatorque","tinker town"},ang={["profession:Engineering"]="对于工程师来说，Tinker Town是铁炉堡不可或缺的一站，这里除了矿道地铁之外，还提供专业的训练师、装置供应商和零部件。",["race:Gnome"]="Tinker Town是你流亡人民的心脏。在这里，被叮当作响的原型机和幸存同胞所环绕，大工匠Mekkatorque正在指挥收复诺莫瑞根的持续行动。"},sec={{t="流亡之家",b="当地下穴居人占领了高科技城市诺莫瑞根时，铁炉堡的矮人向幸存者们敞开了大门。为了安置突然涌入的难民，一个原本居住着矮人居民且作为矿道地铁入口的巨大洞穴被划拨给了他们。在大工匠Gelbin Mekkatorque及其议会的注视下，Tinker Town迅速变成了一个充满了齿轮转动声、实验炼金术和各种精巧装置的活力中心。尽管作为客人居住在拥挤的石城中，侏儒们围绕着一个巨大的球形装置重建了他们的文明，并决心收复他们地下的家园。"},{t="地铁与秘密",b="除了容纳侏儒领导层之外，Tinker Town还是大陆上最具战略意义的交通枢纽之一。该地区拥有矿道地铁的铁炉堡入口，这是一项将矮人首都与暴风城迅速连接起来的工程奇迹。"}},faq={{q="为什么侏儒住在铁炉堡而不是他们自己的城市？",a="诺莫瑞根在遭受穴居人的突然毁灭性入侵后陷落。为了不给第三次战争期间的联盟增添负担，侏儒们选择孤军奋战，最终被迫撤离。国王麦格尼·铜须提供了铁炉堡作为避难所，使大工匠Mekkatorque得以建立这个地区作为他们临时的流亡首都。",al={"为什么侏儒在这里","为什么侏儒住在铁炉堡","侏儒难民铁炉堡"}},{q="为什么矿道地铁入口会在这里？",a="矿道地铁是侏儒和矮人合作打造的工程奇迹，旨在将铁炉堡直接与暴风城连接起来。矿道地铁的铁炉堡终点站就开在Tinker Town，为两个联盟首都之间提供了高速交通。",al={"地铁通往哪里","tinker town里的地铁","tinker town传送门"}}},fx={d4e07867={q="什么是Tinker Town？",a="Tinker Town是铁炉堡的侏儒区，围绕矿道地铁的宏伟入口开凿而成。诺莫瑞根陷落后，铁炉堡的矮人接纳了流离失所的盟友进入山中，并将这片区域划给他们，让他们重建社区、工坊和工程实验室。",al={"什么是tinker town","tinker town信息","铁炉堡的侏儒区"}},["37905e65"]={q="谁统治着Tinker Town？",a="Tinker Town是侏儒流亡政府的所在地，由大工匠Gelbin Mekkatorque及其资深顾问团领导。在他的领导下，这片区域挤满了流离失所的侏儒、大师级工程师、炼金师和发明家，他们正努力开创崭新的未来。",al={"谁领导tinker town","tinker town的领袖","谁负责管理tinker town"}},["70a740c2"]={q="Tinker Town危险吗？",a="Tinker Town深处铁炉堡戒备森严的核心地带，完全不受外敌威胁。不过，拥挤的工坊里堆满了不稳定的炼金混合物、飞转的齿轮和实验性炸药，因此机械故障和火灾意外始终有可能发生。",al={"tinker town安全吗","tinker town是否安全","tinker town的威胁"}},["3f3e824e"]={q="为什么叫Tinker Town？",a="这片区域的名称源自侏儒对修修补补、发明创造和机械改造的热衷，也源自他们选举出的领袖大工匠Gelbin Mekkatorque的头衔。这里是矮人首都中工匠、工程师和发明家忙碌工作的中心。",al={"为什么叫tinker town","tinker town名称由来","tinker town得名由来"}}},fp="11,310,15.671.0,18.264.0,61.345.0,45.264.0"}
P.entries["subzone:tinkers-court"] = {n="Tinkers' Court",s="Tinkers' Court是诺莫瑞根中心的大型议事厅。这里曾是大工匠和他的统治议会繁忙的驻地，如今却已变成叛徒麦克尼尔·瑟玛普拉格冷酷的据点。",h="Tinkers' Court是诺莫瑞根中心的大型议事厅。这里曾是大工匠和他的统治议会繁忙的驻地，如今却已变成叛徒麦克尼尔·瑟玛普拉格冷酷的据点。",kw={"议会","诺莫瑞根","大工匠","gelbin mekkatorque","tinkmaster overspark","麦克尼尔·瑟玛普拉格","tinkers court"},ang={["profession:Engineering"]="这个大厅是一场腐化工程的惊人展示，里面充满了致命的炸弹投放系统和由瑟玛普拉格驾驶的致命攻城机甲。",["race:Gnome"]="伫立在Tinkers' Court中是一次关于背叛的痛苦提醒；在麦克尼尔·瑟玛普拉格于辐射废墟中夺取它之前，这里曾是侏儒领袖们集会的地方。"},sec={{t="侏儒议会驻地",b="在导致诺莫瑞根毁灭的灾难发生前，Tinkers' Court曾是这个国家的公民和政治中心。大工匠Gelbin Mekkatorque就是在这里与顾问和发明大师们（包括Tinkmaster Overspark）齐聚一堂，商讨技术进步、管理市政事务并指引侏儒社会。该议事厅位于Engineering Labs和Launch Bay的工业设施之外，是侏儒创造力和治理能力的象征。"},{t="瑟玛普拉格的王座室",b="在导致侏儒流亡的灾难性辐射泄漏事件后，麦克尼尔·瑟玛普拉格占据了这个大厅。这位疯狂的发明家自封为诺莫瑞根之王，如今坐在Tinkers' Court中，周围环绕着扭曲的装置、忠诚的麻风侏儒和炸弹投放器。从这个被玷污的议事厅里，他指挥着残余的部队，使得这里成为了任何试图终结他统治的突袭小队所要面对的最后，也是最危险的关口。"}},faq={{q="Tinkers' Court最初的用途是什么？",a="在历史上，Tinkers' Court曾是民选的大工匠和诺莫瑞根统治议会的会面地点和市政厅。Gelbin Mekkatorque和高级顾问（如Tinkmaster Overspark）曾在这里讨论城市管理和前沿发明。",al={"tinkers court历史","什么是tinkers court","议事厅的最初用途"}},{q="现在是谁在控制Tinkers' Court？",a="麦克尼尔·瑟玛普拉格目前占据着该议事厅。他自称诺莫瑞根之王，利用他的防御机械和受辐射的爪牙把守着这里。",al={"谁在tinkers court","tinkers court的首领","瑟玛普拉格房间"}},{q="Tinkers' Court在诺莫瑞根的什么位置？",a="Tinkers' Court位于诺莫瑞根的最深处，穿过连接Launch Bay和Engineering Labs的黑暗隧道与下层区域即可到达。",al={"tinkers court在哪里","如何前往tinkers court","寻找tinkers court"}},{q="为什么抵达Tinkers' Court对联盟如此重要？",a="抵达该议事厅是收复这座城市的终极目标，因为麦克尼尔·瑟玛普拉格就在里面指挥他那受辐射的爪牙。将其推翻是诺莫瑞根获得解放的关键第一步。",al={"为什么要前往tinkers court","为什么要杀瑟玛普拉格","tinkers court的重要性"}}},fx={d2a5bbc9={q="什么是Tinkers' Court？",a="Tinkers' Court是诺莫瑞根最深处的行政核心。在和平年代，这里是宏伟的议事厅，由选举产生的大工匠和执政议会聚集于此，领导侏儒族群、探讨工程奇迹并管理民政事务。如今，这里成了叛徒占据的戒备森严的内殿。",al={"什么是tinkers' court","诺莫瑞根的tinkers' court","关于tinkers' court"}},["66d32e28"]={q="诺莫瑞根陷落期间，Tinkers' Court发生了什么？",a="穴居人入侵时，大工匠Gelbin Mekkatorque及其顾问在这座大厅里主持政务。麦克尼尔·瑟玛普拉格提出灾难性的建议，要将辐射排放到全城以消灭野兽，随后法院被有毒的辐射尘埃吞没。Mekkatorque和幸存者被迫逃离，将大厅留在了疯狂叛徒手中。",al={"tinkers' court发生了什么","tinkers' court的历史","tinkers' court的陷落"}},fddc0bd4={q="Tinkers' Court为何被废弃并沦为废墟？",a="诺莫瑞根遭受毁灭性辐射时，这座议事厅被废弃了。致命的放射性蒸气笼罩着下层区域，令侏儒无法正常生活；留在那里的侏儒变异成疯狂的麻风侏儒，宏伟的政府中枢也变成了一座遭污染的机械堡垒。",al={"tinkers' court为何沦为废墟","tinkers' court被废弃","为何沦为废墟"}},["19b28a1e"]={q="Tinkers' Court有多危险？",a="这是整座废墟城市中防御最严密、最危险的大厅。麦克尼尔·瑟玛普拉格身边有致命的机器人守卫、机械陆行鸟和狂热的麻风侏儒仆从。进入此地，就意味着要面对碾压机械、有毒辐射，以及这位疯狂工匠最致命的战斗发明。",al={"tinkers' court危险吗","tinkers' court的威胁","tinkers' court有多危险"}},a5ad6256={q="为什么命名为Tinkers' Court？",a="侏儒社会并非由世袭君主统治，而是由称为大工匠、经选举产生的远见发明家，与大师级工匠和学者组成的议会共同治理。这座大厅以执政团体命名，也是工匠们聚集并领导族群的真正议事厅。",al={"为何叫tinkers' court","tinkers' court名称含义","tinkers' court名称由来"}}},fp="14,205,27.487.0,24.464.1,48.292.0,32.170.0,45.157.0,61.209.0"}
P.entries["subzone:tiragarde-keep"] = {n="提拉加德城堡",s="提拉加德城堡是一座位于杜隆塔尔流亡海岸的坚固人类据点，位于剃刀岭以南。这座城堡最初是在海军上将戴林·普罗德摩尔入侵时建造的，如今这里仍由贝内迪克特中尉指挥的敌对库尔提拉斯海军陆战队驻守，成为部落家门口一根顽固且永久的刺。",h="提拉加德城堡是一座位于杜隆塔尔流亡海岸的坚固人类据点，位于剃刀岭以南。这座城堡最初是在海军上将戴林·普罗德摩尔入侵时建造的，如今这里仍由贝内迪克特中尉指挥的敌对库尔提拉斯海军陆战队驻守，成为部落家门口一根顽固且永久的刺。",kw={"戴林·普罗德摩尔","杜隆塔尔","库尔提拉斯","贝内迪克特中尉","剃刀岭","流亡海岸","提拉加德城堡"},ang={["faction:Horde"]="提拉加德城堡是联盟在杜隆塔尔家门口赤裸裸的入侵基地；突袭其城垛并消灭贝内迪克特中尉是剃刀岭年轻士兵的一项成人礼。",["race:Human"]="这支驻军代表了库尔提拉斯和普罗德摩尔上将不屈不挠、充满复仇意味的遗产，他们无视吉安娜·普罗德摩尔的外交努力，进行着顽固的游击战。"},sec={{t="普罗德摩尔堡垒",b="提拉加德城堡始建于海军上将戴林·普罗德摩尔试图铲除萨尔刚刚建立的王国的那场战役中，它为库尔提拉斯舰队在杜隆塔尔红色的海岸线上提供了一个稳固的滩头堡。尽管部落最终在塞拉摩岛打破了围攻并击杀了普罗德摩尔，但这座城堡从未被彻底遗弃。在贝内迪克特中尉的带领下，补给部队收复了这座残破的石墙要塞，他们遵循这位已故上将的遗命，对兽人发动永不妥协的战争，完全拒绝吉安娜·普罗德摩尔所达成的和平。"},{t="杜隆塔尔侧翼的一根刺",b="如今，城堡闪耀的白色城垛与杜隆塔尔的深红悬崖形成了鲜明的对比。训练有素的库尔提拉斯水兵和海军陆战队员在城墙上巡逻，并不时对剃刀岭附近的补给线发动突袭。对于部落来说，提拉加德城堡是一个持续的安全危机，也是一个活生生的练兵场。兽人和巨魔指挥官不断派遣年轻战士去突袭这座堡垒并消灭贝内迪克特的士兵，试图在人类发动更深层的内陆攻势之前将其困在驻地内。"}},faq={{q="为什么杜隆塔尔会有这些人类？",a="这些人是库尔提拉斯的水兵和海军陆战队，他们随海军上将戴林·普罗德摩尔在第三次战争后的入侵行动中抵达。他们拒绝与部落和平共处，并一直维持着这个驻地来骚扰兽人。",al={"联盟为什么在这里","提拉加德的人类是谁","杜隆塔尔人类士兵"}},{q="这些人是塞拉摩的吉安娜部队的一部分吗？",a="不是。虽然吉安娜·普罗德摩尔统治着塞拉摩岛并与萨尔保持着脆弱的休战，但这些士兵追随的是她已故的父亲——海军上将戴林·普罗德摩尔的意志。他们认为与兽人的任何和平都是不可接受的背叛。",al={"提拉加德是塞拉摩吗","他们是吉安娜·普罗德摩尔的人吗","这里的塞拉摩士兵"}},{q="谁在指挥提拉加德城堡？",a="这座据点由库尔提拉斯军官贝内迪克特中尉指挥，他执行的是普罗德摩尔上将留下的死后入侵命令，旨在守住海岸并攻击部落。",al={"提拉加德首领","谁领导提拉加德城堡","贝内迪克特中尉"}},{q="为什么部落没有简单地将其铲除？",a="这座城堡防御严密，由训练有素、装备精良的库尔提拉斯部队守卫。虽然来自剃刀岭的守军经常与该驻地发生小规模冲突，并将其作为新兵的练兵场，但发动全面围攻会造成严重伤亡，并分散保卫杜隆塔尔其他地区的重要资源。",al={"为什么不摧毁提拉加德","为什么城堡还在"}}},fx={["975f81a6"]={q="什么是提拉加德城堡？",a="提拉加德城堡是联盟的一处海岸防御工事，位于杜隆塔尔东南部的流亡海岸。它由浅色石料建成，与周围的红色峡谷形成鲜明反差，是敌视部落的人类部队在海滩上的据点。即使城堡已破败不堪，仍为库尔提拉斯士兵提供了一处坚固基地，让他们能够骚扰剃刀岭等附近定居点。",al={"提拉加德城堡是什么","这座城堡是什么","介绍一下提拉加德城堡"}},["6c9a5200"]={q="提拉加德城堡发生过什么？",a="大舰队司令戴林·普라우德摩尔在入侵杜隆塔尔、向初建的部落开战时，匆忙修建了这座城堡。部落发动反击，猛攻并重创堡垒，最终将其攻陷。普라우德摩尔后来虽被杀，贝尼迪克特中尉率领的预备部队仍奉命夺回废墟城堡，继续阵亡司令的征战。",al={"提拉加德城堡的历史","这里发生了什么","提拉加德城堡之战"}},["79c67834"]={q="提拉加德城堡为何成了废墟？",a="大舰队司令普라우德摩尔最初入侵杜隆塔尔时，部落攻入并摧毁了这座堡垒，因此它沦为废墟。贝尼迪克特中尉和库尔提拉斯援军虽成功重新占据此地，却只能将它当作一处摇摇欲坠、修修补补的据点，而非完好的城堡；附近的兽人哨站不断施压，城堡也始终处于围攻之中。",al={"提拉加德城堡为何被摧毁","城堡为何受损","谁摧毁了提拉加德城堡"}},["246e91e1"]={q="提拉加德城堡危险吗？",a="是的，对部落成员来说尤其危险。城堡由训练有素的库尔提拉斯海军陆战队员和水手占据，他们对兽人怀有深仇大恨，会袭击沿海旅人。他们向剃刀岭方向发动突袭，并严密守卫城垛，抵御任何奉命驱逐他们的部落勇士。",al={"提拉加德城堡安全吗","提拉加德城堡的危险","提拉加德城堡里的人类危险吗"}}},fp="14,360,20.550.0,26.519.0,32.220.0,53.232.0,28.177.0,43.324.0"}
P.entries["subzone:tkashi-ruins"] = {n="伽什废墟",s="伽什废墟是位于荆棘谷北部奈辛瓦里远征队营地西南方的一处古代石砌遗迹。这里已被敌对的血顶巨魔所占据，如今是该部落的据点。",h="伽什废墟是位于荆棘谷北部奈辛瓦里远征队营地西南方的一处古代石砌遗迹。这里已被敌对的血顶巨魔所占据，如今是该部落的据点。",kw={"血顶","奈辛瓦里","荆棘谷","伽什","伽什废墟","巨魔废墟"},ang={["race:Troll"]="对于暗矛巨魔来说，像伽什这样的遗迹是他们敌对的古拉巴什族人留下的古代部落废墟的阴森提醒，如今这些地方被凶残的血顶残留势力死死守卫着。"},sec={{t="血顶之石",b="伽什废墟耸立在赫米特·奈辛瓦里狩猎营地的西南方，其坍塌的石砌建筑标志着荆棘谷丛林巨魔古老的领地。如今，这里被血顶部落重兵把守，他们在此充满藤蔓和残垣断壁的地方积极防御着领土，并进行着他们的萨满仪式。虽然赫米特·奈辛瓦里在他的狩猎回忆录中记录曾安然无恙地穿过这些废墟，但现代的旅行者会发现这些巨魔并不那么友好，他们守护着埋藏在瓦砾中珍贵的部落遗物。"}},faq={{q="谁住在伽什废墟？",a="这些废墟被血顶部落占据，这是一个敌对的丛林巨魔派系，他们积极防御着这座摇摇欲坠的建筑，以对抗外来者和敌对部落。",al={"这里是谁","伽什废墟的怪物","伽什的巨魔"}},{q="伽什废墟位于哪里？",a="它们位于荆棘谷北部，就在奈辛瓦里远征队营地附近的河流渡口西南方。",al={"伽什位置","伽什在哪里","寻找伽什废墟"}},{q="赫米特·奈辛瓦里的著作中提到了伽什吗？",a="在他回忆录《荆棘谷的青山》的第三章（具体在第21页）中，奈辛瓦里记录了他和他的狩猎队在丛林探索初期曾平安无事地穿过了伽什废墟。",al={"奈辛瓦里伽什","荆棘谷的青山伽什"}}},fp="12,203,24.548.0,30.167.0,35.107.0,62.230.0"}
P.entries["subzone:tor-kren-farm"] = {n="托克雷农场",s="托克雷农场是位于杜隆塔尔西北部的一处安静但经营艰难的养猪场，靠近雷霆山和怒水河。米莎·托克伦独自打理着家园，焦急地等待着她儿子克鲁恩的消息，他去打猎至今未归。",h="托克雷农场是位于杜隆塔尔西北部的一处安静但经营艰难的养猪场，靠近雷霆山和怒水河。米莎·托克伦独自打理着家园，焦急地等待着她儿子克鲁恩的消息，他去打猎至今未归。",kw={"杜隆塔尔","克鲁恩","米莎·托克伦","养猪场","怒水河","雷霆山","托克雷农场"},ang={["class:Hunter"]="米莎关于怒水河鳄鱼的警告提醒着年轻的猎人们，杜隆塔尔的河岸有多么危险。",["faction:Horde"]="托克雷农场的安静悲剧揭示了为了驯服杜隆塔尔这片狂野边疆，普通的部落定居者所做出的日常牺牲。"},sec={{t="孤独的家园",b="在杜隆塔尔贫瘠且严酷的红土地上谋生从来都不容易，但托克雷农场比大多数地方都要艰难。这座农场位于雷霆山东南部，在饲料和水源匮乏的严酷气候下以养猪为生。与部落那些熙熙攘攘的贸易站或防御森严的兵营不同，这里孤立而宁静，在附近悬崖的阴影下勉强维持着微薄的产出。"},{t="母亲的担忧",b="米莎·托克伦的儿子克鲁恩几天前去怒水河边猎杀鳄鱼，至今没有回来。她曾警告过他那些凶猛的掠食者，但他愤怒地离开了。现在，她恳求过往的冒险者去寻找他，或者带回他命运的线索。她担心最坏的情况发生，但在不知道发生了什么之前，她无法开始哀悼。"},{t="母亲的哀恸",b="当有冒险者从河里的鳄鱼身上带回克鲁恩的护身符时，米莎认出了它，并表示她现在知道儿子已经遇难了。得知他的结局，她终于可以开始哀悼。"}},faq={{q="托克雷农场在哪里？",a="托克雷农场位于杜隆塔尔西北部，坐落在雷霆山东南部，怒水河以东。",al={"托克雷农场位置","托克雷农场在哪里","找到托克雷农场"}},{q="谁住在托克雷农场？",a="米莎·托克伦经营着这家养猪场。她的儿子克鲁恩在前往怒水河狩猎后失踪了。",al={"谁在经营托克雷农场","托克雷农场的npc","米莎·托克伦是谁"}},{q="米莎的儿子发生了什么事？",a="克鲁恩几天前去怒水河猎杀鳄鱼，至今未归。米莎请求旅行者去寻找他或带回他命运的线索。",al={"米莎的儿子","克鲁恩·托克伦的死亡","克鲁恩是谁"}},{q="托克雷农场出产什么？",a="它是一家养猪场，但恶劣的地形和地理位置的偏僻使得其收益比杜隆塔尔的其他畜牧业点要微薄得多。",al={"托克雷农场生意","托克雷是什么样的农场","托克雷的猪"}}},fx={["13fe9b16"]={q="什么是托克雷农场？",a="托克雷农场是一处朴素的家园，位于杜隆塔尔西北部，坐落在雷霆山与怒水河之间。这里经营着一个养猪场，但始终难以像该地区的其他定居点那样兴旺获利。在酷烈的沙漠阳光下维持生计的农场，体现了普通兽人在杜隆塔尔严酷边境开辟生路的日常艰辛。",al={"什么是托克雷农场","托克雷农场的故事","关于托克雷农场"}},["11f4c018"]={q="托克雷农场危险吗？",al={"托克雷农场安全吗","托克雷农场的威胁","托克雷农场的危险"}},["65c8d3ec"]={q="为什么叫托克雷农场？",a="农场以建造并经营它的托克雷家族命名。米莎·托克伦定居于此，与儿子克隆一同养猪，于是这个小小却经久不衰的农田便冠以家族之名。",al={"为什么叫托克雷农场","托克雷农场名称由来","托克雷是谁"}}},fp="13,240,18.429.0,16.352.0,15.183.1,31.128.0,27.113.0,29.152.0,32.135.0"}
P.entries["subzone:tower-of-althalaxx"] = {n="奥萨拉克斯之塔",s="奥萨拉克斯之塔是一座古老的上层精灵尖塔，矗立在黑海岸北部靠近海岸的地方。在大分裂之前，它曾是法师阿萨里克·纳拉辛的一处隐居所，但如今已被练习黑暗魔法的恶魔信徒和术士所盘踞。",h="奥萨拉克斯之塔是一座古老的上层精灵尖塔，矗立在黑海岸北部靠近海岸的地方。在大分裂之前，它曾是法师阿萨里克·纳拉辛的一处隐居所，但如今已被练习黑暗魔法的恶魔信徒和术士所盘踞。",kw={"奥萨拉克斯","亚米萨兰","阿萨里克·纳拉辛","巴莎兰","黑暗之滩","黑海岸","上层精灵","萨特","暗影议会"},ang={["class:Warlock"]="黑暗之滩教派所进行的黑暗仪式展示了暗影议会在卡利姆多深远的影响力和挥之不去的阴影。",["race:NightElf"]="这座塔是上层精灵腐化和恶魔愚行在祖先土地上残留的严酷提醒，亟需达纳苏斯采取迅速干预。"},sec={{t="一处上层精灵的隐居所",b="一万年前，艾萨拉女王将她宠信的上层精灵仆从安置在亚米萨兰和巴莎兰的沿海城镇，并委派强大的法师阿萨里克·纳拉辛管理他们。由于逐渐疏远了政务，阿萨里克选择隐居在附近的奥萨拉克斯之塔中。当大分裂摧毁了古老的卡利姆多时，这座高塔在黑海岸荒凉的海岸线上幸存了下来，成为了被遗忘的精灵魔法的沉寂废墟。"},{t="黑暗之滩",b="在现代，这座塔中又涌动起了邪恶的魔法。在阿萨里克·纳拉辛本人的领导下，术士、自称“黑暗之滩教派”的黑暗信徒以及盟友萨特都聚集在废墟中。他们的仪式引导着恶魔魔法，折磨着古代死者徘徊的灵魂，为直接与暗影议会勾结的邪恶计划服务。"}},faq={{q="什么是奥萨拉克斯之塔？",a="这是一座古老的精灵法师塔，由艾萨拉女王统治时期在黑海岸北部建成，现在被黑暗术士和邪教徒所占据。",al={"奥萨拉克斯之塔","什么是奥萨拉克斯"}},{q="最初是谁建造并居住在这座塔里的？",a="阿萨里克·纳拉辛，一位由艾萨拉女王任命来监管附近亚米萨兰和巴莎兰定居点的强大上层精灵法师，他在厌倦了职责后隐居于此。",al={"谁住在这里","阿萨里克·纳拉辛","谁建造了这座塔"}},{q="现在占据这座塔的邪教徒是谁？",a="他们属于黑暗之滩教派，这是一个在废墟塔内进行黑暗仪式的术士、邪教徒和萨特教派。",al={"邪教徒是谁","黑暗之滩教派","奥萨拉克斯的敌人"}},{q="为什么这里会有鬼魂和受折磨的灵魂？",a="邪教徒们进行黑暗仪式和灵魂绑定魔法，将古老黑海岸长期死亡的精灵灵魂置于痛苦的折磨中，以完成他们的法术。",al={"为什么会有鬼魂","奥萨拉克斯受折磨的灵魂"}}},fx={["1aaea03f"]={q="奥萨拉克斯之塔危险吗？",a="这座塔极其危险。塔内挤满了黑暗海岸教派的狂热术士和邪教徒，他们在暗影议会的指挥下侍奉恶魔主宰。除了这些黑暗施法者及其萨特盟友，塔内庭院还游荡着受折磨的灵魂和受邪恶法术束缚的幽魂。",al={"奥萨拉克斯之塔安全吗","奥萨拉克斯之塔的危险","奥萨拉克斯之塔的威胁"}}},fp="18,265,19.473.0,15.397.1,31.141.0,44.189.0,45.131.0,47.156.0"}
P.entries["subzone:tower-of-arathor"] = {n="阿拉索之塔",s="阿拉索之塔是一座破败的法师塔，坐落于激流堡西南隅的前法师区。它曾是大法师特雷莱恩的工作室，在激流堡陷落时被攻占，目前被石拳食人魔占据。",h="阿拉索之塔是一座破败的法师塔，坐落于激流堡西南隅的前法师区。它曾是大法师特雷莱恩的工作室，在激流堡陷落时被攻占，目前被石拳食人魔占据。",kw={"阿拉希","石拳","马林","鲁尔·石拳","斯奎尔图","激流堡","阿拉索之塔","特雷莱恩"},ang={["class:Mage"]="这座塔是激流堡奥术飞地遭遇变故的沉痛提醒，同时也展示了大法师特雷莱恩对防御性元素构件的高超掌控。",["faction:Alliance"]="激流堡是争夺中的领土；协助大法师马林的特工回收特雷莱恩失落的文物，可以阻止侵略成性的石拳氏族获取强大的魔法圣物。"},sec={{t="沦陷的堡垒",b="这座尖塔矗立在激流堡法师区的中心，因古老的阿拉索帝国而得名，曾长期作为该国法师们的研习之所。它最著名的住户，大法师特雷莱恩，曾设计了一套以附魔宝石为核心的魔法防御阵列，以保护密室。然而，当辛迪加和石拳食人魔氏族在第三次战争后袭击激流堡时，王国分崩离析。尽管特雷莱恩拼死尝试用奥术结界守住这座塔，但食人魔野蛮的暴力终究还是压倒了他。大法师被迫弃城逃亡，留下了他最珍贵的奥术文物，让这座尖塔落入了石拳食人魔鲁尔·石拳及其追随者的手中。"},{t="收回遗失的圣物",b="即使流亡在外，特雷莱恩也不愿放弃毕生的心血。他在昔日学徒，肯瑞托的大法师马林的帮助下，组织了一支探险队，前往废墟中寻回他的命匣、宝珠和余烬玛瑙。马林的特工们以避难谷地为据点，发现食人魔掠夺了启动防御塔自动防御系统所需的宝石。通过制作一颗替代用的附魔玛瑙并将其放置在塔门两侧的基座上，探险者们可以唤醒被召唤的水元素来清洗食人魔占领者，从而夺回这位大法师的传家宝。"}},faq={{q="什么是阿拉索之塔？",a="这是一座位于激流堡西南废墟中的法师塔。为了纪念古老的人类帝国阿拉索而得名，在它落入入侵的食人魔手中之前，曾是该王国法师们的研究中心。",al={"阿拉索之塔","激流堡法师塔","阿拉希之塔"}},{q="现在是谁住在塔里？",a="这座塔和周围的法师区目前被石拳食人魔占据。尖塔内部居住着食人魔巫师鲁尔·石拳及其卫兵，他们搜刮并守卫着前任主人留下的圣物。",al={"阿拉索之塔里有什么人","阿拉索之塔怪物","阿拉索之塔首领"}},{q="大法师特雷莱恩是谁？",a="大法师特雷莱恩是激流堡的一位著名法师，曾在塔内生活和研究。他创造了塔内以宝石驱动的结界系统，在未能守住密室抵御石拳氏族的攻击后被迫流亡。",al={"大法师特雷莱恩","谁拥有这座塔","特雷莱恩"}},{q="塔的防御系统是如何运作的？",a="特雷莱恩将防御系统与塔门两侧的基座联动，当附魔玛瑙被放置在基座上时即会激活。一旦激活，奥术矩阵会召唤敌对的水元素，与占据入口的任何入侵者战斗。",al={"如何激活防御塔","特雷莱恩的防御","塔门基座"}}},fp="16,262,17.725.0,26.615.1,29.215.0,27.230.0,25.226.0,33.232.0"}
P.entries["subzone:tower-of-azora"] = {n="阿祖拉之塔",s="阿祖拉之塔是一座高耸于艾尔文森林东部，坐落在布莱克威尔南瓜田以北的细长法师塔。该据点由人类大法师塞欧克瑞图斯主持，作为一处学术前哨站，与邻近赤脊山内的一座敌对高塔进行着一场无声的魔法对抗。",h="阿祖拉之塔是一座高耸于艾尔文森林东部，坐落在布莱克威尔南瓜田以北的细长法师塔。该据点由人类大法师塞欧克瑞图斯主持，作为一处学术前哨站，与邻近赤脊山内的一座敌对高塔进行着一场无声的魔法对抗。",kw={"阿祖拉","艾尔文","附魔","伊尔加拉","莫甘斯","侦测","高塔","塞欧克瑞图斯"},ang={["class:Mage"]="对于那些远行至暴风城之外的法师来说，这座高塔提供了一处隐秘的学习避风港，拥有奥术训练师，并能让人身临其境地体验远程占卜这种危险艺术。",["race:Gnome"]="在人类领地看到一座由大法师塞欧克瑞图斯领导、侏儒驻守的奥术高塔，正是你们种族对神秘艺术精通程度的骄傲展示。"},sec={{t="奥术警惕之塔",b="阿祖拉之塔矗立在通往赤脊山的东侧道路旁，是一处几乎完全由侏儒施法者组成的奥术庇护所。在大法师塞欧克瑞图斯的管理下，这些学者们潜心研究各种奇特的奥秘，并为游历的施法者提供魔法指导。高塔周围狂野的魔法气息有时会扭曲附近的野生生物，使得侏儒仆从们不得不对付那些被附魔的家居用品以及潜入门口的变异昆虫。"},{t="与伊尔加拉的宿怨",b="在平静的学术表象之下，这座高塔正深陷于一场旷日持久的侦测与破坏战争中。向东望去，在赤脊山的峭壁之上，坐落着邪恶的伊尔加拉之塔，由叛变巫师莫甘斯统治。塞欧克瑞图斯与莫甘斯不断利用奥术手段相互监视，并雇用大胆的冒险者去安放如阿祖拉之眼之类的侦测遗物，以穿透伊尔加拉的防御结界，监视莫甘斯的黑暗阴谋。"}},faq={{q="谁在统治阿祖拉之塔？",a="这座高塔由大法师塞欧克瑞图斯主持，他是一位造诣深厚的人类法师。他负责指挥塔内的仆从，并协调他们对抗敌对巫师的魔法防御。",al={"谁领导阿祖拉之塔","谁在这里负责","阿祖拉之塔首领"}},{q="为什么这里有这么多侏儒？",a="阿祖拉的仆从主要是侏儒研究员和侍僧，他们协助大法师塞欧克瑞图斯进行研究、奥术实验，并处理各种魔法事故带来的家务琐事。",al={"为什么艾尔文森林的塔里有侏儒","阿祖拉的仆从"}},{q="这座塔在与谁战斗？",a="这座塔正与位于赤脊山的伊尔加拉之塔进行着魔法竞争，后者是邪恶巫师莫甘斯的巢穴。两座高塔都在利用侦测神器互相监视，并争夺彼此的影响力。",al={"阿祖拉的敌人","高塔宿怨","阿祖拉在监视谁"}},{q="顶楼的阿祖拉之眼是什么？",a="阿祖拉之眼是一个被放置在顶层密室桌上的附魔侦测焦点。触碰它，观察者便能跨越魔法距离，监视伊尔加拉之塔的周边情况。",al={"顶楼的宝珠","阿祖拉之眼","阿祖拉水晶球"}}},fx={e823b8a2={q="什么是阿祖拉之塔？",a="阿祖拉之塔是一座引人注目的法师高塔，位于艾尔文森林中部、闪金镇以东。它由阿祖拉大法师塞欧克瑞图斯领导，是一处供奥术施法者使用的魔法圣所和研究场所，工作人员主要是侏儒仆从和附魔师。",al={"阿祖拉之塔","这座塔是什么","关于阿祖拉之塔"}},["7c8bc76d"]={q="阿祖拉之塔危险吗？",a="这座塔是联盟旅人的安全庇护所，提供住所和附魔训练。不过，从尖塔散发出的强大魔法气息会扭曲靠得太近的日常物品和野生动物，迫使塔内仆从处理各种奇异现象，比如会动的水桶和变异蝴蝶。",al={"阿祖拉之塔危险吗","阿祖拉之塔的危险","阿祖拉之塔的威胁"}}},fp="14,299,27.497.0,21.444.1,29.185.0,34.181.0,34.218.0,42.200.0"}
P.entries["subzone:tower-of-eldara"] = {n="埃达拉之塔",s="埃达拉之塔是一座古老且封闭的暗夜精灵尖塔，坐落在艾萨拉风暴海湾东北方向的一处远端岬角上。虽然它早已被遗弃，但其坚固的石质建筑在天崩地裂后依然屹立不倒，静静地矗立在充斥着好斗海岸野兽的海岸线上。",h="埃达拉之塔是一座古老且封闭的暗夜精灵尖塔，坐落在艾萨拉风暴海湾东北方向的一处远端岬角上。虽然它早已被遗弃，但其坚固的石质建筑在天崩地裂后依然屹立不倒，静静地矗立在充斥着好斗海岸野兽的海岸线上。",kw={"艾萨拉","风暴海湾","埃达拉","上层精灵","卡多雷","废墟","埃达拉之塔"},ang={["class:Mage"]="和艾萨拉各地许多上层精灵建筑一样，这座被封印的塔楼在被锁起来防止凡人染指之前，很可能曾因奥术研究而嗡嗡作响。",["race:NightElf"]="埃达拉之塔是一个令人感伤的提醒，它见证了在艾萨拉女王和上层精灵摧毁古代世界之前，你们的祖先所统治的伟大帝国。"},sec={{t="古代艾萨拉的遗迹",b="埃达拉之塔高耸在风暴海湾东北侧偏远的悬崖边缘，作为曾经统治这片海岸线的广阔卡多雷帝国的遗迹，默默地见证着历史。与艾萨拉大部分破败的建筑一样，它在数千年前的大分裂之后便不再使用。如今，塔门依然紧闭，阻挡着外界，让人无法窥探其中究竟封存着何种遗迹或密室。塔楼周围的海岸充满了危险，徘徊的鱼人、挥舞着利爪的穴居人（马克鲁拉）以及掠食性的多头蛇在此游荡，让除了最勇敢的旅行者之外的所有人都望而却步。"}},faq={{q="埃达拉之塔是什么？",a="这是一座古老的暗夜精灵塔楼，位于艾萨拉东北部的悬崖边缘，俯瞰着风暴海湾。它始建于大分裂之前，是曾经横跨该地区的庞大卡多雷帝国的一部分。",al={"埃达拉之塔背景故事","这座塔是什么","埃达拉之塔"}},{q="你能进入埃达拉之塔吗？",a="不能。这座塔的大门紧闭，对外来者严密封锁。无论塔内保留着怎样的密室或宝库，它们都拒绝现代探险者的进入。",al={"我可以进入埃达拉之塔吗","如何打开埃达拉之塔","这座塔开放吗"}},{q="塔楼周围有哪些威胁？",a="岬角周围的岩石峭壁和邻近的沙滩上遍布着敌对的鱼人、披甲的穴居人（马克鲁拉）以及海岸多头蛇。",al={"埃达拉之塔附近的怪物","埃达拉周围的敌人","风暴海湾的生物"}},{q="塔楼具体在哪里？",a="你可以找到它，它位于伸入无尽之海的最东端陆地上，就在艾萨拉风暴海湾东北方向的水域对面。",al={"埃达拉之塔位置","埃达拉之塔在哪里","如何找到埃达拉"}}},fp="15,292,26.615.0,28.229.0,34.147.0,37.147.0,35.140.0"}
P.entries["subzone:tower-of-ilgalar"] = {n="伊尔加拉之塔",s="伊尔加拉之塔是一座孤零零的尖塔，高耸在赤脊山东部的峭壁之上。这里曾是一位法师的隐居之所，如今却陷入了阴影，成为了Morganth的藏身处。Morganth曾是被放逐出暴风城的术士，现在他统领着该地区的野生豺狼人，并在此钻研黑暗魔法。",h="伊尔加拉之塔是一座孤零零的尖塔，高耸在赤脊山东部的峭壁之上。这里曾是一位法师的隐居之所，如今却陷入了阴影，成为了Morganth的藏身处。Morganth曾是被放逐出暴风城的术士，现在他统领着该地区的野生豺狼人，并在此钻...",kw={"阿祖拉","暗犬","伊尔加拉","湖畔镇","morganth","赤脊山","shadowhide","塞欧克瑞图斯","伊尔加拉之塔"},ang={["class:Mage"]="这座塔是一个严厉的警示，说明当奥术研究深入禁忌的黑暗魔法时会发生什么，这也吸引了像塞欧克瑞图斯这样的肯瑞托老兵警惕的目光。",["class:Warlock"]="Morganth对召唤暗犬和暗影妖术的依赖反映了恶魔技艺，使他的山中隐居处成为了城市秘法会之外堕落法术的一个引人注目的例子。"},sec={{t="黑暗巫术的堡垒",b="伊尔加拉之塔俯瞰着赤脊山东部，是Morganth的私人圣所。他因涉足禁忌魔法而被驱逐出暴风城的Mage Quarter，这位堕落的术士退居到这些崎岖的高地，以便在不受帝国干扰的情况下深入钻研黑暗技艺。Morganth并没有过着隐居生活，而是统治了当地的Shadowhide豺狼人氏族，并将他们作为野蛮的哨兵部署在塔基周围。塔内爬满了召唤出来的恶魔犬，并闪烁着暗影能量，对下方的湖畔镇构成了持续而沉重的威胁。"},{t="与阿祖拉的竞争",b="学者们常将伊尔加拉之塔与艾尔文森林的阿祖拉之塔相提并论。尽管伊尔加拉的真实身份仍然笼罩在谜团之中，但这两座塔处于一种静默的魔法对立状态。在艾尔文森林，大法师塞欧克瑞图斯通过诸如阿祖拉之眼这样的附魔窥探装置，密切监视着伊尔加拉，以此监控Morganth的邪恶实验，并策划在腐化蔓延至整个王国之前铲除这个叛徒。"}},faq={{q="谁住在伊尔加拉之塔？",a="这座塔由Morganth把守，他是一位被暴风城放逐的叛逃人类术士，放逐原因是练习禁忌的黑暗魔法。他现在统治着这座塔，身旁有召唤出来的恶魔暗犬，并统领着当地的Shadowhide豺狼人。",al={"谁在伊尔加拉之塔","伊尔加拉之塔首领","谁控制着这座塔"}},{q="为什么Morganth逃到了赤脊山？",a="Morganth在钻研黑暗技艺后被赶出了暴风城的Mage Quarter。他退避到赤脊山偏远的峭壁上，远离王国当局和肯瑞托的监视，进行他的禁忌实验。",al={"morganth为什么在这里","morganth背景故事","morganth为何被流放"}},{q="这座塔与阿祖拉之塔有什么联系？",a="两座塔都是暴风城南部显眼的魔法尖塔，其用途似乎互为镜像。在艾尔文森林的阿祖拉之塔中，法师塞欧克瑞图斯利用阿祖拉之眼积极窥探着伊尔加拉的上层圣所，以监视Morganth的黑暗仪式。",al={"阿祖拉之塔联系","伊尔加拉与阿祖拉","赤脊山阿祖拉之眼"}},{q="为什么有豺狼人守卫着这座塔？",a="Morganth利用他的魔法影响力征服了当地的Shadowhide豺狼人氏族。他们充当外围哨兵和打手，阻止入侵者、侦察兵和湖畔镇的民兵攀登悬崖进入他的圣所。",al={"为什么这里有豺狼人","shadowhide豺狼人之塔","塔周围的豺狼人"}}},fx={d387a688={q="伊尔加拉之塔是什么？",a="伊尔加拉之塔是一座神秘的法师塔，矗立在赤脊山东部高地。它高踞止水湖上方，外形与艾尔文森林的阿祖拉之塔相似，却已沦为禁忌巫术的堡垒，而非研习正统奥术的场所。",al={"伊尔加拉之塔是什么","伊尔加拉之塔背景","赤脊山法师塔"}},["30aed8f6"]={q="伊尔加拉之塔危险吗？",a="这里极其危险。塔楼周围盘踞着敌对的暗皮豺狼人，它们听命于塔中的术士；黑色猎犬的魔仆也在塔内巡逻。沿着螺旋楼梯向上攀登，你就会直面摩根斯本人——一名遭到放逐、掌握着毁灭性黑暗魔法的术士。",al={"伊尔加拉之塔危险吗","伊尔加拉之塔的危险","伊尔加拉之塔有多危险"}}},fp="16,285,25.620.0,22.485.0,34.231.0,34.239.0,65.273.0,40.217.0"}
P.entries["subzone:trade-district"] = {n="Trade District",s="Trade District 是暴风城熙熙攘攘的商业中心，位于大门和英雄谷之后。这里是冒险者和市民的主要聚集地，城内的中央银行、拍卖行、公会注册处和各种商铺都坐落于此。",h="Trade District 是暴风城熙熙攘攘的商业中心，位于大门和英雄谷之后。这里是冒险者和市民的主要聚集地，城内的中央银行、拍卖行、公会注册处和各种商铺都坐落于此。",kw={"拍卖行","市集","财务中心","金玫瑰旅店","gryphon roost","暴风城","trade district","游客中心"},ang={["faction:Alliance"]="对于联盟的勇士来说，Trade District 是进行银行业务、在拍卖行交易、组织公会以及飞往东部王国各地的核心枢纽。"},sec={{t="商业的十字路口",b="穿过英雄谷的石拱门，旅行者便会直接进入 Trade District。这个充满活力的开放广场是暴风城的主要市场和物流枢纽。其中心矗立着拍卖行，附近则是暴风城财务中心（城内的主要银行）以及广受欢迎的旅店——金玫瑰旅店。该区直接连接了 Old Town 的军事区、宁静的 Cathedral Square 以及 Mage Quarter 的奥术大道，确保钱币、原材料和冒险补给能迅速流通于整个王国。"},{t="市集与公会大厅",b="沿着铺设好的街道和两侧的运河，可以买到所有必需的商品。Weller's Arsenal 和 Lionheart Armory 的武器匠提供刀剑和锁甲，The Empty Quiver 的制箭师出售弓箭，而工匠摊位则提供从鲜花到 Gallina Winery 陈年佳酿的各种商品。就在大门内侧，暴风城游客中心负责协调新注册的公会章程和战袍设计，而东侧的一座高架坡道则通向 Gryphon Roost，将首都的商业生活与联盟领地的其他部分连接起来。"}},faq={{q="Trade District 位于何处？",a="Trade District 位于城市正门和英雄谷之后。它直接通向西北方的 Cathedral Square、东方的 Old Town，以及西南方跨过运河的 Mage Quarter。",al={"trade district 位置","trade district 在哪","如何前往 trade district"}},{q="我在哪里可以找到银行和旅店？",a="暴风城财务中心（主要城市银行）和金玫瑰旅店位于 Trade District 的西南边缘，就在主要道路旁，十分方便。",al={"trade district 银行","金玫瑰旅店位置","暴风城银行 trade district"}},{q="在暴风城哪里可以注册公会或设计战袍？",a="暴风城游客中心位于从城门进入 Trade District 后的左侧，那里有公会会长和战袍设计服务。",al={"暴风城公会会长","公会注册处","创建公会"}},{q="在 Trade District 哪里可以乘坐狮鹫飞行？",a="Trade District 东侧的一座石坡道直接通往 Gryphon Roost，飞行管理员在那里派遣狮鹫前往王国各地及更远的地方。",al={"暴风城飞行管理员","暴风城狮鹫栖息地","飞行管理员在哪"}}},fx={["747b4250"]={q="Trade District是什么地方？",a="Trade District是暴风城的繁华商业中心，位于主城门内、英雄谷之后。它是王国的主要贸易、银行和交通枢纽。旅人来到这里买卖货物、在热闹的商店购买补给、寄送邮件，也可以前往暴风城钱庄。这里还设有城内主要的狮鹫栖木，可搭乘狮鹫飞往东部王国各地。",al={"trade district概况","这是什么地方","暴风城trade district"}},d6628855={q="为什么叫Trade District？",a="这个区域因其作为暴风城主要商业市场的职能而得名，有时也被称为集市区。商人、店主和行脚贸易者聚集于此，出售种类繁多的商品，从护甲、武器和奥术试剂，到新鲜奶酪、鲜花和佳酿，应有尽有。这里以贸易为中心，既有城中的银行金库，也有繁忙的商行。",al={"为何叫trade district","trade district名称由来","集市区"}},["7971c440"]={q="Trade District危险吗？",a="通常情况下，Trade District极其安全。暴风城守卫在此巡逻，这里又位于宏伟城门内侧，因此免受外部威胁。首都的阴影中或许潜伏着窃贼或政治暗流，但诚实的居民和来访的冒险者可以安心交易、存取钱财、办理事务，不必担心荒野中的危险。",al={"trade district安全吗","trade district危险吗","trade district有什么威胁"}}},fp="14,293,26.599.0,23.612.0,36.228.0,38.188.0,60.170.0,58.169.0"}
P.entries["subzone:trade-quarter"] = {n="Trade Quarter",s="贸易区是幽暗城的核心地带，位于洛丹伦废墟下方的升降梯正下方。它是被遗忘者经济跳动的中心，安置着他们的主要银行金库、拍卖行以及基本的民用设施。从这个同心圆枢纽出发，拱形走廊向四周延伸至各个区域。",h="贸易区是幽暗城的核心地带，位于洛丹伦废墟下方的升降梯正下方。它是被遗忘者经济跳动的中心，安置着他们的主要银行金库、拍卖行以及基本的民用设施。从这个同心圆枢纽出发，拱形走廊向四周延伸至各个区域。",kw={"拍卖行","银行","蝙蝠管理员","棺材","旅店","杰雷米亚·佩森","trade quarter","幽暗城"},ang={["faction:Horde"]="对于抵达提瑞斯法林地的兽人、牛头人或巨魔特使来说，贸易区是他们北方盟友那充满异域风情且阴森的市场中心。",["race:Undead"]="贸易区代表了被遗忘者迅速重建文明秩序的成果，他们将地下的地牢转变成了致力于为他们的生存提供资金的繁荣市场。"},sec={{t="墓穴之心",b="从破碎的洛丹伦地表降下，旅行者走下升降梯，便踏入了贸易区回荡着石音的广阔空间。它围绕着环形分层的布局设计，中央平台存放着城市金库和中央银行，周围有横跨污浊排水渠的桥梁。环绕的露台人声鼎沸，商贩、公会注册员和拍卖师在诡异的阴暗中讨价还价。即便是最基础的住宿设施也体现了被遗忘者的实用主义：当地旅店提供的是未衬里的木棺，而不是柔软的床铺。从这个中心枢纽，石拱门通向城内各专门区域，使这里成为了所有在首都进行商业活动的必经之路。"}},faq={{q="贸易区位于哪里？",a="贸易区占据了幽暗城的正中心。当通过洛丹伦废墟下方的地面升降梯进入首都时，你会直接步入该区域的上环。",al={"贸易区位置","如何找到贸易区","贸易区在哪里"}},{q="贸易区有哪些服务？",a="该区域设有幽暗城中央银行、位于外环的拍卖行、主旅店、用于空中旅行的蝙蝠管理员、公会注册员，以及包括城市烹饪导师在内的各种商业训练师。",al={"贸易区服务","贸易区里有什么","幽暗城银行位置"}},{q="为什么旅店里有棺材？",a="被遗忘者的生理构造不需要真正的睡眠，许多人保留着适合他们亡灵状态的习惯。旅店提供的是简陋的、没有内衬的木棺，而不是传统的寝具——对于亡者来说这是一种例行的舒适，尽管对于活着的访客来说这令人深感不安。",al={"幽暗城旅店棺材","为什么旅店里有棺材","幽暗城床铺"}},{q="潜伏在桥下的是什么商贩？",a="杰雷米亚·佩森在通往银行的中央桥梁下谋生。当标准的商人在上方兜售武器和贸易货物时，佩森则向好奇的路人兜售活蟑螂宠物。",al={"杰雷米亚·佩森","幽暗城蟑螂人","谁卖蟑螂"}}},fx={d7706923={q="Trade Quarter是什么地方？",a="Trade Quarter是幽暗城的中心枢纽与核心地带。它紧邻从上方旧洛丹伦废墟通往地下的电梯，呈多层环形结构，并通过蜿蜒的运河与其他区域直接相连。这里是王国繁忙的商业中心，设有大型银行金库、杂货商、工会服务设施和城中的主要集会场所。",al={"trade quarter是什么地方","幽暗城trade quarter","幽暗城中心"}},b95b8a75={q="Trade Quarter是如何形成的？",a="这些地下大厅最初开凿于洛丹伦王宫和首都之下，曾经设有地牢、墓穴和下水道。洛丹伦在天灾军团和阿尔萨斯王子的进攻下沦陷后，希尔瓦娜斯·风行者女士率领被遗忘者收复了这片领土。他们扩建并改造了地下中央区域，将其建成设防的城市中心，以便开展贸易并治理新建立的主权领地。",al={"trade quarter历史","trade quarter是如何建成的","trade quarter的历史"}},["5eb4f186"]={q="Trade Quarter危险吗？",a="对于部落成员和黑暗女士的盟友而言，Trade Quarter是王国中最安全的地方之一，有高大的憎恶和王室卫兵严密把守。然而，对于联盟成员或未经允许闯入的人来说，这里是致命之地：他们刚从上方废墟下来，就会立即遭到击杀。",al={"trade quarter安全吗","trade quarter危险吗","trade quarter的威胁"}},["49015933"]={q="为什么叫Trade Quarter？",a="它因作为被遗忘者首都最重要的商业区而得名。中央金库设有城市宝库和银行，周围各层则分布着商贩摊位、拍卖师、工艺品供应商和工会联络员，为整个王国的各类重要商业交易提供便利。",al={"为什么叫trade quarter","trade quarter名称","为何叫trade quarter"}}},fp="13,354,19.694.0,35.206.0,45.214.0,33.269.0,46.212.0"}
P.entries["subzone:tradesmen-s-terrace"] = {n="贸易区",kw={"拍卖行","达纳苏斯","卡多雷","商人","商店","泰达希尔","贸易区","商贩"},ang={["faction:Alliance"]="贸易区为通过鲁瑟兰村来到这里的联盟旅行者提供了银行、拍卖师和必要的贸易补给，方便他们继续深入卡利姆多。",["race:NightElf"]="对于暗夜精灵而言，贸易区是一个难得的密集城市商业中心，它经过调整以保护达纳苏斯宁静的树冠，且没有其他种族那种破坏性的工业。"},sec={{t="达纳苏斯的商业中心",b="贸易区占据了达纳苏斯的南部，承载着这座首都的商业生活。虽然城市的大部分区域专注于宁静的沉思、荒野圣地和精神职责，但这个区域汇集了为当地卡多雷和来自广大联盟的旅行者服务的店主、手艺人和商人。这里设有达纳苏斯的中央拍卖行、杂货店和制作补给品商店，使其成为前往荒野探险的重要补给站。宽阔的小径向北直接连接战士区，向西连接神殿花园宁静的水域和宏伟的Temple of the Moon。"},{t="工匠与商人",b="卡多雷手工艺品优先考虑与自然的和谐，这里的商店反映了这种微妙的平衡。即使在日常商业活动中，这个区域的运作也没有矮人或人类作坊中那种轰鸣的熔炉或烟雾，而是偏好安静的石头、精心挑选的木材和编织品。对于寻求贸易合同、修理服务或从泰达希尔茂密枝叶中采集的材料的到访冒险者来说，这里是卡利姆多北部的主要商业中心。"}},faq={{q="什么是贸易区？",a="贸易区是达纳苏斯的南部市场区。它是暗夜精灵首都的商业中心，汇集了城中大部分的商人、工匠和中央拍卖行。",al={"这是什么地方","贸易区信息","达纳苏斯贸易区"}},{q="达纳苏斯的拍卖行在哪里？",a="达纳苏斯的拍卖行就位于贸易区。它为旅行者、商人和当地居民提供了参与全市及联盟贸易的途径。",al={"达纳苏斯拍卖行","达纳苏斯拍卖行位置","拍卖行在哪里"}},{q="我该如何从这里前往其他区域？",a="从贸易区出发，向北可以进入战士区，向西可以前往神殿花园和高耸的Temple of the Moon。",al={"贸易区的出口","这个区域通向哪里","如何离开贸易区"}},{q="这个区域有哪些类型的商贩？",a="该区域有各种各样的杂货商、贸易补给商和工匠，满足日常需求、修理服务以及泰达希尔各地生产的商品供应。",al={"贸易区的商贩","这里可以买到什么","贸易区商店"}}},fx={f0c60839={q="贸易区危险吗？",a="一点也不危险。贸易区是达纳苏斯最安全、人口最密集的区域之一。作为暗夜精灵首都繁华的商业中心，这里有城市哨兵持续巡逻，也有商人、工匠和联盟旅人往来，和平地处理各种事务。",al={"贸易区安全吗","贸易区的危险"}},a7d49f79={q="为什么叫贸易区？",a="这个区域的名称直接源于它作为达纳苏斯主要贸易和工艺中心的职能。它是首都指定的商业区，聚集了城中的工会工匠、店主、杂货供应商和中央拍卖行。",al={"为何叫贸易区","贸易区名称","为什么取名为贸易区"}}},fp="19,370,31.671.0,20.467.0,28.216.0,40.158.0,45.140.0,49.169.0"}
P.entries["subzone:train-depot"] = {n="Train Depot",s="Train Depot位于丹莫罗诺莫瑞根地表入口的正下方，是一处地下交通枢纽。它曾是侏儒交通繁忙的中心，现在却充斥着敌对的麻风侏儒和入侵的穴居人。",h="Train Depot位于丹莫罗诺莫瑞根地表入口的正下方，是一处地下交通枢纽。它曾是侏儒交通繁忙的中心，现在却充斥着敌对的麻风侏儒和入侵的穴居人。",kw={"clockwerk run","丹莫罗","诺莫瑞根","麻风侏儒","loading room","namdo bizzfizzle","train depot","穴居人"},ang={["profession:Engineering"]="寻找稀有图纸的工程师经常会搜寻车站的下层站台，像Namdo Bizzfizzle这样幸存下来的侏儒商人仍在残骸中经营着他们的生意。",["race:Gnome"]="对于流亡的侏儒来说，这座废弃的车站是一个悲剧的象征，展示了曾经连接他们地下大都市的先进交通系统的毁灭。"},sec={{t="废弃的交通枢纽",b="Train Depot位于从丹莫罗通往地下的巨大升降梯底部，曾是横跨诺莫瑞根地下奇迹的铁路运输枢纽。如今，站台和铁轨已是一片狼藉。导致城市辐射的灾难将幸存的工人们变成了疯狂的麻风侏儒，而地下的穴居人则占领了轨道。进入这座废弃城市的探险者必须穿过这个集结地，才能到达Clockwerk Run、Loading Room和内部工程设施等更深层的区域。"}},faq={{q="Train Depot在哪里？",a="Train Depot位于丹莫罗地表入口升降梯的正下方，是进入诺莫瑞根核心区之前的外围门槛区域之一。",al={"train depot位置","如何到达train depot","train depot入口"}},{q="现在有哪些生物居住在Train Depot？",a="这个车站被从深地挖掘上来的凶猛穴居人和在放射性灾难中丧失理智的卑劣麻风侏儒所占据。",al={"train depot敌人","train depot怪物","谁在train depot"}},{q="从Train Depot出发的路通向哪里？",a="通道向西通往Clockwerk Run和Loading Room，而北部的车间区域则有一个通往上层Engineering Labs的后门。",al={"train depot出口","train depot通往哪里","train depot连接区域"}},{q="谁躲在Train Depot里？",a="工程学供应商Namdo Bizzfizzle成功在车站下层主站台北侧的隐蔽处生存了下来。",al={"namdo bizzfizzle","train depot npc","train depot商人"}}},fx={["08edd791"]={q="Train Depot是什么地方？",a="Train Depot是一个宽阔的交通区域，位于诺莫瑞根入口电梯的正下方。在城市陷落之前，这里曾是繁忙的交通枢纽，连接上层区域与更深处的工坊和中央设施。",al={"train depot是什么地方","诺莫瑞根train depot","train depot简介"}},["34ec9e38"]={q="Train Depot发生了什么？",a="穴居人入侵以及随后的辐射污染席卷诺莫瑞根时，城中的铁路和交通系统彻底瘫痪。正常的侏儒很快便弃置了这座车站，它就此荒废，与这座地下废墟都市的其他部分一同腐朽。",al={"train depot历史","train depot发生了什么","train depot的陷落"}},b2726984={q="Train Depot为什么成了废墟？",a="诺莫瑞根各处爆发的放射性污染彻底摧毁了正常运作。幸存的工人变成了失心疯的麻疯侏儒，或是逃离了这里，基础设施也随之崩溃，车站的机器和走廊渐渐失修，并被敌对生物占据。",al={"train depot为何被遗弃","train depot为何被摧毁","train depot成了废墟"}},ab6b6be9={q="Train Depot有多危险？",a="对于毫无准备的旅人来说，这里极其危险。凶残的地下穴居人和受到辐射、充满敌意的麻疯侏儒在站台和走廊中徘徊，会毫不犹豫地攻击任何从丹莫罗下来的人。",al={"train depot危险吗","train depot的威胁","train depot里的危险"}},["9f84ab0b"]={q="为什么叫Train Depot？",a="它因最初的设计用途而得名：这里是中央铁路车站和装卸终点站，曾供复杂的机械铁路网使用，将货物和乘客运送到诺莫瑞根各处。",al={"为何叫train depot","train depot名称含义","这里有火车吗"}}},fp="11,222,20.566.0,33.171.0,43.153.0,45.154.0,33.145.0"}
P.entries["subzone:tranquil-gardens-cemetery"] = {n="静谧花园墓场",s="静谧花园墓场位于暮色森林中夜色镇的东南方。尽管名字听起来很安宁，但这里如今已充斥着蹒跚的骷髅和食尸鬼，使得这片曾经的安息之地变成了邻近城镇的一大威胁。",h="静谧花园墓场位于暮色森林中夜色镇的东南方。尽管名字听起来很安宁，但这里如今已充斥着蹒跚的骷髅和食尸鬼，使得这片曾经的安息之地变成了邻近城镇的一大威胁。",kw={"墓场","夜色镇","暮色森林","花园","疯狂的食尸鬼","骷髅","静谧"},ang={["class:Paladin"]="静谧花园墓场的亵渎是对圣光的冒犯，这使其成为了圣骑士们为暮色森林中不得安息的亡灵祈求安宁的紧急试炼场。",["faction:Alliance"]="对于抵达夜色镇的联盟勇士来说，保卫这座邻近的墓地对于维护城镇外围安全、防止亡灵入侵至关重要。"},sec={{t="不安之地",b="静谧花园墓场曾经是大地精小镇逝者安息的宁静场所，但如今这里早已不再平静。随着黑暗诅咒笼罩暮色森林，埋葬于此的死者开始从坟墓中爬出。虽然在这些墓碑间徘徊的骷髅战士、骷髅法师和游荡的亡灵，比起森林深处潜藏的恐怖怪物而言相对脆弱，但由于它们极其靠近夜色镇，对镇民构成了持续不断的威胁。"},{t="城镇的门槛",b="由于墓场紧邻夜色镇的边缘，这里成为了当地民兵的前线阵地。守夜人经常派遣新兵和刚抵达的冒险者来此，在这些复苏的亡灵冲破防线进入城镇之前将其清除。在倾倒的墓碑和废弃的礼拜堂之间，潜伏着更加危险的威胁，例如疯狂的食尸鬼。"}},faq={{q="既然这里到处都是亡灵，为什么还叫静谧花园？",a="这座墓场建立时，夜色镇还被称为大地精小镇，是当时阳光明媚的森林中一处宁静的定居点。它原本是为当地家庭准备的一处安宁、庄重的安息之所。当诅咒降临这片土地，死者开始从坟墓中复苏，这个名字便成了一种残酷的讽刺。",al={"为什么叫静谧","静谧花园的名字起源","为什么被称为静谧"}},{q="墓场周围游荡着什么威胁？",a="这片土地上遍布着相对脆弱的亡灵，包括蹒跚的骷髅、骷髅战士和骷髅法师。在那座废弃的礼拜堂里或墓碑间，还能发现一只格外凶残的疯狂的食尸鬼。",al={"静谧花园的敌人","这里有什么怪物","墓场怪物"}},{q="守夜人为什么要派新兵到这里来？",a="由于墓场紧邻夜色镇东南方，任何未受遏制的亡灵数量激增都有可能直接威胁到城镇。守夜人利用此地磨练新的保卫者，让他们在对付较弱的亡灵之后，再去应对森林深处更危险的敌人。",al={"守夜人墓场任务","为什么要清理静谧花园","谁在守护墓场"}},{q="谁住在墓场北边？",a="在静谧花园墓场北边坐落着一间与世隔绝的小屋，居住着名为盲眼玛丽的灵魂，她徘徊在那片被腐蚀的墓地附近。",al={"静谧花园附近的房子","墓场北边的幽灵","盲眼玛丽的屋子"}}},fx={["86a6efa8"]={q="静谧花园墓场是什么地方？",a="静谧花园墓场是一处古老的墓地，位于暮色森林夜色镇的东南方。这里曾是宁静的安息之地，如今笼罩整个地区的黑暗诅咒却使死者从坟墓中复苏。墓场里杂草丛生，礼拜堂也已成为废墟，如今到处都是游荡的骷髅和食尸鬼。",al={"静谧花园是什么","静谧花园墓场背景","介绍一下静谧花园"}},["77d44972"]={q="静谧花园墓场为何沦为废墟？",a="暮色森林的许多地方都在黑暗和异常疫病侵袭后逐渐衰败，静谧花园也不例外。墓地的教堂毁坏殆尽，死者从受祝圣的土地中爬出，迫使活着的看守者彻底弃守墓园。",al={"静谧花园为何沦为废墟","静谧花园墓场成了废墟","礼拜堂为何毁坏"}}},fp="25,244,16.462.0,23.348.0,58.312.0,40.231.0,44.274.0,37.150.0"}
P.entries["subzone:tundrid-hills"] = {n="冻土岭",s="冻土岭是一片崎岖、被积雪覆盖的高地，位于丹莫罗中南部，就在古博拉采掘场的西侧。这里栖息着危险的山地野生动物，崎岖的山路鲜有普通旅人踏足。",h="冻土岭是一片崎岖、被积雪覆盖的高地，位于丹莫罗中南部，就在古博拉采掘场的西侧。这里栖息着危险的山地野生动物，崎岖的山路鲜有普通旅人踏足。",kw={"寒脊山谷","丹莫罗","霜鬃巨魔","古博拉采掘场","铁炉堡","卡拉诺斯","冻土岭"},ang={["class:Hunter"]="风蚀的峭壁提供了崎岖的追踪场地，这里充斥着适应了丹莫罗严酷山地寒冷的坚韧野兽。",["race:Dwarf"]="对于铁炉堡的登山者来说，这些高地时刻提醒着他们，荒野和敌对的霜鬃巨魔正紧紧逼近丹莫罗的核心地带。"},sec={{t="危险的荒野",b="冻土岭横跨寒脊山谷和丹莫罗东部低地，为那些想要避开卡拉诺斯主干道的旅人提供了一条崎岖的越野路线。然而，便利的代价是高昂的。锯齿状的雪坡上潜伏着凶猛的掠食者，对于那些不带武器就偏离既定道路的粗心旅人来说，这片领土充满了危险。"}},faq={{q="冻土岭位于哪里？",a="冻土岭横跨丹莫罗的中南部，位于古博拉采掘场以西，构成了连接卡拉诺斯与东方领地的主干道南侧的一道天然高地边界。",al={"冻土岭位置","冻土岭在哪里","冻土岭地图"}},{q="为什么有人会穿越冻土岭？",a="探险者有时会穿过这些严酷的山脊，作为连接寒脊山谷和丹莫罗东部的一条陆路捷径，从而避开既定的定居点路线，尽管这比沿着有巡逻队的道路行走要危险得多。",al={"为什么要去冻土岭","冻土岭捷径"}},{q="在冻土岭会遇到什么威胁？",a="这些山丘是适应了寒冷高地的凶猛原生野生动物的家园，很少有人会在不携带武器的情况下到这里旅行。",al={"这里有什么生物","冻土岭敌人","冻土岭怪物"}}},fx={["6d54f98b"]={q="穿越冻土岭危险吗？",a="是的，穿行于这些雪山丘陵，比沿着有巡逻守卫的道路前进危险得多。高地上栖息着凶猛的掠食性野兽，也没有矮人卫兵定期巡逻或提供庇护。这里虽然是连接寒脊山谷与丹莫罗东部的捷径，但很少有旅人会在没有备好武器、保持警惕的情况下偏离常走的道路。",al={"冻土岭危险吗","冻土岭的危险","冻土岭安全吗"}}},fp="13,232,24.401.0,36.205.0,50.237.0,47.126.0"}
P.entries["subzone:twilight-base-camp"] = {n="暮光营地",s="暮光营地是暮光之锤教派在希利苏斯荒芜大地上设立的一处防御据点。这里是教徒们聚集、与元素力量沟通并策划其世界末日阴谋的活跃仪式地点。营地内布满了诡异的风石，并由全副武装的狂热教徒把守。",h="暮光营地是暮光之锤教派在希利苏斯荒芜大地上设立的一处防御据点。这里是教徒们聚集、与元素力量沟通并策划其世界末日阴谋的活跃仪式地点。营地内布满了诡异的风石，并由全副武装的狂热教徒把守。",kw={"希利苏斯","暮光复仇者","暮光营地","暮光地领主","暮光守护者哈文斯","暮光领主埃沃伦","暮光之锤","风石"},ang={["class:Paladin"]="教徒们所进行的黑暗、末日仪式代表了对和平的直接威胁，需要圣光的正义审判。",["class:Shaman"]="在营地的风石处对元素之灵进行的公然扭曲和奴役，是对任何致力于维护精神和谐的萨满的冒犯。"},sec={{t="末日堡垒",b="暮光营地坐落在希利苏斯荒凉的沙地中，是暮光之锤教派建立的多个据点之一。营地里挤满了狂热者、地卜师和唤石者，他们致力于召唤毁灭性的元素力量。营地周围环绕着嶙峋的仪式石，是像暮光守护者哈文斯和暮光领主埃沃伦这样的领袖指挥行动、加速艾泽拉斯毁灭的集结地，他们公然对抗着试图恢复该地区平衡的塞纳里奥要塞部队。"},{t="风石",b="在据点各处散布着被称为风石的神秘纪念碑，其力量从次级导管到大型巨石不等。通过晦涩的咒语和教派法器，暮光之锤利用这些焦点将混乱的元素之灵直接拉入物质位面。对于希望阻止教派影响力在卡利姆多扩散的旅行者和侦察兵来说，打断这些仪式仍然是首要任务。"}},faq={{q="暮光营地是什么？",a="这是一个由毁灭性的暮光之锤教派在希利苏斯沙漠中建立的武装据点，用于进行黑暗仪式并召唤强大的元素生物。",al={"暮光营地 希利苏斯","暮光营地是什么","希利苏斯教徒营地"}},{q="谁控制着这个营地？",a="该据点由暮光之锤的狂热者把守，在暮光守护者哈文斯和罕见的领袖暮光领主埃沃伦等监工的指挥下运作。",al={"谁领导暮光营地","暮光营地领袖","谁在负责"}},{q="营地里的那些奇怪石头是什么？",a="这些结构是风石——一种大小不一的神秘聚焦导管，教徒们用它来穿透位面壁垒并将元素生物束缚在他们的麾下。",al={"风石","次级风石","希利苏斯大型风石"}},{q="暮光之锤为什么会在希利苏斯？",a="该教派被希利苏斯沙土之下徘徊的古老而混乱的能量所吸引，试图唤醒黑暗力量并召唤元素，从而带来世界的毁灭。",al={"为什么暮光之锤在希利苏斯","暮光教派希利苏斯目标"}}},fp="18,330,17.529.0,15.444.0,31.173.0,23.164.0,40.165.0,42.188.0"}
P.entries["subzone:twilight-grove"] = {n="黎明森林",s="黎明森林坐落在暮色森林的中心，这片令人惊叹的飞地植被葱郁，充满卡利姆多的气息，与周围阴森、被枯萎病侵蚀的森林形成了鲜明的对比。在其高耸的巨树和古老的暗夜精灵建筑之下，坐落着一口月亮井和一座直接连通翡翠梦境的巨大翡翠传送门。",h="黎明森林坐落在暮色森林的中心，这片令人惊叹的飞地植被葱郁，充满卡利姆多的气息，与周围阴森、被枯萎病侵蚀的森林形成了鲜明的对比。在其高耸的巨树和古老的暗夜精灵建筑之下，坐落着一口月亮井和一座直接连通翡翠梦境的巨大翡翠传送门...",kw={"暮色森林","翡翠梦境","巨树","绿龙军团","月亮井","传送门","黎明森林"},ang={["class:Druid"]="对于探索东部王国的德鲁伊来说，这片森林是一处罕见的家园绿洲，拥有一口活跃的月亮井和一条通往祖先梦境之路的直接通道。",["race:NightElf"]="在远离卡利姆多的地方发现一口隐秘的月亮井和传统的凉亭，这令人心酸地提醒着你的族人：你们有治愈艾泽拉斯伤口的古老职责。"},sec={{t="一处翠绿的避难所",b="黎明森林隐藏在暮色森林中心陡峭的环形山脊后，对于东部王国而言，这里显得格格不入。古老的暗夜精灵凉亭、充满活力的绿色草地和宁静的月亮井环绕着一棵无名的巨树，它高耸于阴郁的树冠之上。这棵树是自然的导管，将翡翠梦境的原始活力过滤到清醒的世界中，使这个环形山即使在暮色森林永恒的阴霾之下也能繁茂生长。"},{t="翡翠传送门",b="在巨树的底部耸立着一座巨大的石制传送门，这是艾泽拉斯已知的四座直接连接物质位面与翡翠梦境的传送门之一。虽然传统上由伊瑟拉的绿龙军团守护，但黑暗的低语声称，邪恶势力已经开始扭曲彼端那宁静的国度。这座传送门目前大多处于静默状态，但它那翡翠色的漩涡是一个严峻的提醒：宇宙的腐蚀可能通过比天灾军团或当地狼人更深邃的路径，从这儿蔓延到暮色森林中。"}},faq={{q="为什么暮色森林会有暗夜精灵建筑？",a="这些凉亭和月亮井均为暗夜精灵所造，围绕着森林的巨树及其通往翡翠梦境的传送门而建。它们何时以及如何出现在距离卡利姆多如此遥远的地方，目前尚不为人知。",al={"暮色森林精灵遗迹","为什么这里有暗夜精灵建筑","暮色森林月亮井"}},{q="那座巨大的绿色发光传送门是什么？",a="这是一座通往翡翠梦境的巨树传送门，翡翠梦境是受绿龙军团监管的艾泽拉斯原始蓝图。在灰谷、菲拉斯和辛特兰也存在三座类似的传送门。",al={"暮色森林绿色传送门","暮色森林翡翠梦境传送门","黎明森林的石拱门"}},{q="如今是谁在守护这片森林？",a="历史上，伊瑟拉的绿龙军团的副官们守护着这处避难所。虽然对于过往的旅人来说，这里通常空无一人，但翡翠梦境内部日益增长的动荡威胁着要将腐化的守护者通过传送门带入凡间。",al={"谁在守护黎明森林","黎明森林的绿龙"}},{q="为什么黎明森林看起来不像暮色森林其他地方那样死气沉沉？",a="这棵巨树充当了通往翡翠梦境的导管，辐射出纯净、原始的生命能量。这种源源不断的自然生命力保护着内盆地，使其免受扼杀周围森林的超自然诅咒和枯萎病的侵袭。",al={"为什么黎明森林是绿色的","为什么暮色森林里有生机"}}},fx={["4ad09d10"]={q="黎明森林发生过什么？",a="关于这片林地的起源，几乎没有记载。林中的巨树是通往翡翠梦境的通道，周围的暗夜精灵凉亭和月亮井表明，卡多雷曾经守护这里。如今，梦境中日益蔓延的腐化正威胁着守望传送门的绿龙。",al={"黎明森林历史","黎明森林的历史","黎明森林是如何形成的"}},["69043853"]={q="黎明森林危险吗？",a="与暮色森林中游荡的亡灵恐怖相比，这片林地看似宁静；然而，它的传送门通往正遭受梦魇腐化侵蚀的翡翠梦境。奉命守护这些枝桠的绿龙有陷入疯狂的危险，使这处静谧的幽谷成为潜伏着巨大危险的沉眠之地。",al={"黎明森林安全吗","黎明森林危险","黎明森林的危险"}},a63f3ab3={q="黎明森林是什么地方？",a="黎明森林是一片隐秘而葱郁的盆地，藏在暮色森林中央。这里以一棵没有名字的大树、一座宁静的月亮井和精灵建筑为中心，有一道巨大的漩涡状传送门，直接连接艾泽拉斯与翡翠梦境。与黑暗而闹鬼的森林其他区域不同，这里的自然依然生机盎然。",al={"黎明森林是什么地方","暮色森林的黎明森林","黎明森林背景"}}},fp="14,305,19.445.0,19.517.0,48.198.0,39.210.0,33.253.0,67.227.0"}
P.entries["subzone:twilight-outpost"] = {n="暮光前哨站",s="暮光前哨站是暮光之锤教派的一处防御营地，坐落在希利苏斯西南部的沙地中。它位于古老的甲虫之墙西北侧，是教徒们进行黑暗仪式以与元素恐怖沟通并召唤它们的集结地。",h="暮光前哨站是暮光之锤教派的一处防御营地，坐落在希利苏斯西南部的沙地中。它位于古老的甲虫之墙西北侧，是教徒们进行黑暗仪式以与元素恐怖沟通并召唤它们的集结地。",kw={"铜须营地","甲虫之墙","希利苏斯","暮光守卫埃克塞特","暮光领主埃弗伦","暮光前哨站","暮光之锤","风石"},ang={["class:Paladin"]="暮光之锤那虚无主义的狂热是对圣光的公然亵渎，必须施以神圣的愤怒，将他们那邪恶的召唤仪式从这片沙漠中彻底清除。",["class:Shaman"]="暮光之锤通过他们的风石腐化并操控着元素之灵，这违背了萨满们竭力维护的元素自然平衡。"},sec={{t="低语堡垒",b="暮光前哨站深藏在希利苏斯的西南部，是点缀着这片荒漠的几处主要教派据点之一。它坐落在巨大的甲虫之墙阴影下，位于铜须营地以西，营地里挤满了狂热的暮光复仇者、地卜师和唤石者。在暮光守卫埃克塞特和稀有精英暮光领主埃弗伦等首领的指挥下，这些狂热分子为了侍奉他们那疯狂的天启主人而不知疲倦地劳作。"},{t="风石",b="营地各处散布着神秘的风石，从次级到强效，规格不一。通过使用附魔的教派法衣和邪恶的咒语，教派利用这些巨石撕裂元素位面，强行将深渊指挥官和元素领主拖入凡世。对于那些敢于潜入他们队伍的冒险者来说，打断这些召唤仪式仍然是对抗教派在这片沙漠中影响力的主要手段之一。"}},faq={{q="暮光前哨站位于哪里？",a="暮光前哨站位于希利苏斯的最西南角。它坐落在古老的甲虫之墙西北方，就在矮人的铜须营地正西方。",al={"暮光前哨站位置","暮光前哨站在哪","寻找暮光前哨站"}},{q="谁占据了暮光前哨站？",a="该营地被暮光之锤教派所占据。其成员包括各种凡人狂热者，例如暮光复仇者、地卜师、唤石者和暮光大师，并由暮光守卫埃克塞特和暮光领主埃弗伦等首领监管。",al={"暮光前哨站里有什么人","暮光前哨站的敌人","希利苏斯的教徒"}},{q="营地里的风石是什么？",a="风石——从次级到强效——是教派用来打破元素位面屏障的神秘焦点。教徒们通过这些石头引导黑暗能量，将强大的元素领主和深渊指挥官召唤到艾泽拉斯。",al={"什么是风石","希利苏斯强效风石","希利苏斯次级风石"}},{q="为什么暮光之锤聚集在甲虫之墙附近？",a="该教派被希利苏斯地下沉睡的强大古老黑暗能量所吸引。在甲虫之墙附近建立营地，使他们能够进行元素召唤，并驾驭在那封印之门后涌动的混乱力量。",al={"为什么教徒在希利苏斯","暮光之锤在希利苏的目的"}}},fp="16,286,21.497.0,15.480.0,38.178.0,34.248.0,43.239.0,59.241.0"}
P.entries["subzone:twilight-post"] = {n="暮光岗哨",s="暮光岗哨是暮光之锤教派在希利苏斯西北部建立的一处防御森严的营地。它坐落于塞纳里奥要塞的遥远西侧，暮光营地的西北方，是该教派进行元素召唤仪式的关键地点。冒险者们来到这里，将会面对狂热的教徒以及他们用来与异界力量沟通的风石。",h="暮光岗哨是暮光之锤教派在希利苏斯西北部建立的一处防御森严的营地。它坐落于塞纳里奥要塞的遥远西侧，暮光营地的西北方，是该教派进行元素召唤仪式的关键地点。冒险者们来到这里，将会面对狂热的教徒以及他们用来与异界力量沟通的风石。",kw={"地质领主","希利苏斯","石语者","暮光守护者玛娜","暮光领主埃沃伦","暮光岗哨","暮光之锤","风石"},ang={["class:Druid"]="塞纳里奥议会密切注视着该教派前哨站的崛起，因为教徒们黑暗的元素仪式威胁到了希利苏斯脆弱且伤痕累累的平衡。",["class:Shaman"]="暮光之锤扭曲了神圣的元素共融，通过在像这样的前哨站中发现的风石，强行召唤并束缚元素灵魂。"},sec={{t="元素狂热的堡垒",b="暮光岗哨隐藏在希利苏斯西北部的沙漠沙丘之中，是暮光之锤教派的一处前哨站。营地中驻扎着装备精良的守卫和施法者，包括暮光复仇者、地质领主和石语者，在暮光守护者玛娜和稀有狂热分子暮光领主埃沃伦的领导下。正如散布在荒原上的其他营地一样，这座岗哨的核心是古老的召唤导管——次级风石、普通风石和大型风石。通过黑暗仪式和元素沟通，教徒们利用这些石头来恳求并束缚来自异界的元素恐怖生物，威胁着塞纳里奥议会在该地区维持的脆弱和平。"}},faq={{q="暮光岗哨位于哪里？",a="暮光岗哨位于希利苏斯遥远的西北部，坐落在塞纳里奥要塞以西以及大型暮光营地的西北方。",al={"暮光岗哨位置","暮光岗哨在哪里","暮光岗哨希利苏斯地图"}},{q="谁占据了暮光岗哨？",a="该岗哨由暮光之锤教派把守。驻扎在这里的重要人物包括暮光守护者玛娜和暮光领主埃沃伦，他们由成群的暮光复仇者、地质领主和石语者保护。",al={"谁在暮光岗哨","暮光岗哨怪物","暮光岗哨敌人"}},{q="营地里的风石是什么？",a="风石——包括次级风石、普通风石和大型风石——是暮光之锤用来召唤并将元素生物束缚为他们所用的奥术导管。",al={"风石是什么","风石希利苏斯","次级风石暮光岗哨"}},{q="为什么暮光之锤在希利苏斯活动？",a="暮光之锤涌入希利苏斯的荒凉沙漠，是为了唤醒并与沉睡在沙地之下的古老黑暗力量沟通，通过元素召唤来壮大他们的队伍。",al={"为什么教徒在希利苏斯","暮光之锤希利苏斯目标"}}},fp="13,369,31.701.0,31.167.0,31.203.0,43.193.0,51.197.0"}
P.entries["subzone:twilight-s-run"] = {n="暮光小径",s="暮光小径是一处隐蔽的地下洞穴，位于希利苏斯北部山脉，鹿盔岗哨之下。它被狂热的暮光之锤教派占据，作为一处远离沙漠严酷风沙的隐秘避难所和仪式堡垒。",h="暮光小径是一处隐蔽的地下洞穴，位于希利苏斯北部山脉，鹿盔岗哨之下。它被狂热的暮光之锤教派占据，作为一处远离沙漠严酷风沙的隐秘避难所和仪式堡垒。",kw={"希利苏斯","鹿盔岗哨","暮光教派","暮光之锤","暮光小径","邪恶的维拉尔"},ang={["class:Paladin"]="暮光小径那与世隔绝的深处藏着狂热的虚无主义者，他们对黑暗力量的侍奉是对圣光神圣教义的亵渎。"},sec={{t="一处地下堡垒",b="暮光小径隐藏在鹿盔岗哨下方的北侧悬崖中，为暮光之锤的教徒们在希利苏斯狂风肆虐的危险环境中提供了一处天然的堡垒。教徒们没有选择忍受沙尘暴，也没有直接与地表沙丘上游荡的其拉虫群巢穴对抗，而是退入这些阴暗的隧道中，与黑暗力量交流、守卫仪式材料并集结他们的兵力。在邪恶的维拉尔等监工的指挥下，洞穴内的教派成员保持着警惕和敌对状态，随时准备击杀任何靠近他们地下营地的好奇旅行者或侦察兵。"}},faq={{q="暮光小径位于何处？",a="暮光小径是一个位于希利苏斯北部山脉的洞穴，就在鹿盔岗哨下方的岩石基座处。",al={"暮光小径在哪里","暮光小径位置","如何找到暮光小径"}},{q="谁占据了暮光小径？",a="该洞穴完全由暮光之锤的成员控制，包括邪恶的维拉尔、暮光霸主和暮光烈焰掠夺者等人物。",al={"暮光小径里有什么人","暮光小径怪物","谁住在暮光小径"}},{q="教派在洞穴里做什么？",a="教派将该洞穴用作在希利苏斯的隐蔽堡垒和作战前哨，以躲避沙漠恶劣的天气，同时推进他们的末日计划。",al={"暮光教派希利苏斯洞穴目的","为什么教徒在暮光小径"}}},fp="14,256,22.649.0,32.120.0,28.159.0,41.158.0"}
P.entries["subzone:twilight-shore-darkshore"] = {n="暮光海岸 (黑海岸)",s="暮光海岸是黑海岸南部一片崎岖的海岸线，从长桥码头一直向南延伸至灰谷的边界。它那阴暗、雾气弥漫的沙滩被突出的海崖、近海小岛和险恶的浪潮所阻隔。该地区充斥着好斗的鱼人部落和像掘泥蟹这样贪婪的水生掠食者。",h="暮光海岸是黑海岸南部一片崎岖的海岸线，从长桥码头一直向南延伸至灰谷的边界。它那阴暗、雾气弥漫的沙滩被突出的海崖、近海小岛和险恶的浪潮所阻隔。该地区充斥着好斗的鱼人部落和像掘泥蟹这样贪婪的水生掠食者。",kw={"灰谷","海岸","黑海岸","长桥码头","鱼人","掘泥蟹","暮光海岸"},ang={["race:NightElf"]="暮光海岸是黑海岸闹鬼遗迹与灰谷神圣祖先森林之间那片孤独而迷雾笼罩的界限。"},sec={{t="险恶的海岸线",b="暮光海岸从长桥码头以南延伸，经过亚米萨兰遗迹，一直通向灰谷，是黑海岸最崎岖、最荒凉的海岸线之一。灰色的沙滩逐渐过渡为尖锐的、受海浪拍打的悬崖和散布的岩石岛屿。这里的海域以危险著称；在海岸游泳会招致领地意识极强的掘泥蟹和海爬虫的攻击，而海滩本身则被繁茂且好斗的鱼人营地所占据。"}},faq={{q="暮光海岸在哪里？",a="它涵盖了黑海岸最南端的沿海地带，从长桥码头以南（大致在古老的亚米萨兰遗迹以西）开始，一直向南延伸，直到到达灰谷的岩石边界。",al={"暮光海岸位置","暮光海岸在哪里","暮光海岸地图"}},{q="暮光海岸有什么威胁？",a="海岸线上聚居着大量好斗的鱼人部落，而周围寒冷的海浪中则栖息着领地意识强的掘泥蟹、潜伏者和巨型螃蟹，它们会袭击毫无防备的旅行者。",al={"暮光海岸怪物","暮光海岸的危险","暮光海岸有什么"}},{q="为什么这里的地形如此崎岖？",a="与更北边平坦宽阔的沙滩不同，暮光海岸被尖锐的海崖、岩石浅滩和受遮蔽之海无情拍打而形成的小型近海岛屿所割裂。",al={"为什么有悬崖","暮光海岸地理"}}},fx={["4cda5a2c"]={q="什么是暮光海岸？",a="暮光海岸是黑海岸南部一段崎岖的海岸线，从长桥码头边缘一直延伸至灰谷边界附近。与更北面平坦的沙滩不同，这里的海岸嶙峋险峻，遍布突出的海崖、岩石小岛和雾气弥漫的灰色海滩，常受冰冷海水冲刷。",al={"暮光海岸传说","什么是暮光海岸","关于暮光海岸"}},["2a509b88"]={q="暮光海岸危险吗？",a="是的，这是该地区最危险的海岸线之一。成群的好斗鱼人盘踞在岩岸和突出的礁石上，饥饿的刺喉龙则在浪涛间出没，伺机袭击游泳者。在翻涌的海浪附近行进，或攀爬偏僻的海岬，都可能遭到来自陆地和海上的伏击。",al={"暮光海岸安全吗","暮光海岸有多危险","暮光海岸的危险"}}},fp="26,345,23.464.0,36.214.0,51.187.0,34.200.0"}
P.entries["subzone:twilight-vale"] = {n="暮光谷",s="暮光谷涵盖了黑海岸南部茂密阴暗的林地，一直延伸至灰谷的边界。在其阴影笼罩下，受到腐蚀的熊怪、狂犬般的野熊和凶猛的夜刃豹在灌木丛中游荡，使得越野通行变得危机四伏。它是黑海岸污浊的海岸与南部神圣林冠之间的一道严峻关口。",h="暮光谷涵盖了黑海岸南部茂密阴暗的林地，一直延伸至灰谷的边界。在其阴影笼罩下，受到腐蚀的熊怪、狂犬般的野熊和凶猛的夜刃豹在灌木丛中游荡，使得越野通行变得危机四伏。它是黑海岸污浊的海岸与南部神圣林冠之间的一道严峻关口。",kw={"亚米萨兰","灰谷","黑海岸","熊怪","夜刃豹","狂犬般的野熊","暮光谷"},ang={["class:Druid"]="穿梭于黑海岸和灰谷之间的德鲁伊亲眼目睹了山谷生物所遭受的病痛，这强调了净化这片土地的紧迫需求。",["race:NightElf"]="南部森林的退化让暗夜精灵们倍感沉重，他们哀悼着本土野兽的腐化，也为在灰谷门槛附近堕落的熊怪邻居感到悲伤。"},sec={{t="危险的关口",b="从古老的亚米萨兰遗迹南端一直延伸到灰谷的边界，暮光谷让黑海岸的南部区域终年笼罩在昏暗之中。侵蚀着北卡利姆多的腐化力量深深地影响了这里的野生生物。狂犬般的野熊与凶残的夜刃豹并肩游荡，充满敌意的熊怪部落在黑暗的丛林中潜行。哨兵和旅行者都建议一定要严格走在主路上，因为哪怕稍微偏离几步进入树林，都会引来迅速且致命的伏击。"}},faq={{q="暮光谷位于哪里？",a="暮光谷构成了黑海岸的南部。它始于亚米萨兰的上层精灵遗迹以南，一直延伸到进入灰谷的边界山口。",al={"暮光谷位置","暮光谷在哪里","暮光谷地图"}},{q="这片森林里徘徊着什么威胁？",a="山谷中到处都是受折磨的野生生物和敌对部落。旅行者会遇到狂犬般的野熊、极具攻击性的夜刃豹，以及会攻击任何侵入其领地的受腐蚀熊怪。",al={"暮光谷怪物","暮光谷里有什么","暮光谷危险"}},{q="穿过山谷旅行安全吗？",a="黑海岸的荒野没有绝对安全的地方，但坚持走修好的土路要比穿过灌木丛安全得多。偏离主路会让你直接暴露在野兽的攻击路径上。",al={"暮光谷安全吗","从黑海岸到灰谷的安全路径"}},{q="为什么山谷里的野生生物会受到腐蚀？",a="自第三次战争以及北卡利姆多各地残留的破碎魔法以来，黑海岸遭受了沉重的打击。受污染的水源和黑暗的魔法残留物使当地的野生生物变得疯狂，并让原本平静的熊怪变得暴力。",al={"为什么黑海岸的熊会得狂犬病","暮光谷熊怪腐化"}}},fp="13,357,20.517.0,35.178.0,32.199.0,38.220.0,42.220.0"}
P.entries["subzone:twin-colossals"] = {n="双塔山",s="双塔山是一对高耸入云、峭壁陡峭的平顶山，位于菲拉斯的西北部天际线。它们高耸于林冠之上，两座绝壁之间的狭窄通道形成了连接菲拉斯与北部荒凉的凄凉之地之间的主要陆路通道。",h="双塔山是一对高耸入云、峭壁陡峭的平顶山，位于菲拉斯的西北部天际线。它们高耸于林冠之上，两座绝壁之间的狭窄通道形成了连接菲拉斯与北部荒凉的凄凉之地之间的主要陆路通道。",kw={"凄凉之地","钻石首领","菲拉斯","卡林·风翼","马克鲁拉","玛里","双塔山"},ang={["race:NightElf"]="该子区域的险峻高度和附近被腐蚀的月亮井，冷峻地提醒着人们菲拉斯古老的历史，以及那些潜入荒野的挥之不去的阴影。"},sec={{t="雨林之柱",b="双塔山耸立在菲拉斯的西部，是该地区最高的陆地地貌。它们垂直的岩壁在天空中勾勒出引人注目的剪影，成为从凄凉之地向南探险的旅行者们不可错过的地标。虽然山坡下部与茂密的丛林和向被遗忘的海岸延伸的土地融为一体，但山顶却是高出森林地面许多的孤立高原。"},{t="登顶",b="徒步攀登这些垂直的悬崖是不可能的，但这山顶并非完全荒无人烟。一位名叫玛里的勇敢暗夜精灵会协助那些寻求前往东侧山峰的旅行者。登上顶峰的人会发现石桌山上坐落着一处宁静的池塘——尽管这里栖息着一只异常巨大的马克鲁拉，名叫钻石首领。为了帮助冒险者重返地面，卡林·风翼会提供结实的降落伞，让人们滑翔回下方的丛林树冠中。"}},faq={{q="双塔山位于何处？",a="双塔山位于菲拉斯西北部，构成了向北通往凄凉之地的主干道两侧。周边子区域向西延伸至被遗忘的海岸。",al={"双塔山位置","双塔山在哪里","双塔山地图"}},{q="如何到达双塔山的顶部？",a="陡峭的岩壁无法通过常规方式攀爬。旅行者需要依靠暗夜精灵玛里，她能提供通往东侧山峰的魔法通道。",al={"如何攀爬双塔山","到达双塔山顶部","登顶任务"}},{q="东侧山顶上住着谁？",a="在东侧山峰的顶部，你会找到出售安全降落伞的卡林·风翼，以及一处栖息着巨大的马克鲁拉——钻石首领的深水池。",al={"双塔山顶的npc","平顶山上的人","菲拉斯钻石首领"}},{q="如何从山顶安全撤离？",a="卡林·风翼在东侧山顶出售特制的巨型降落伞，允许旅行者从悬崖上跳下，并安然滑翔至下方的菲拉斯丛林中。",al={"离开双塔山","跳下双塔山","巨型降落伞"}}},fp="14,286,25.426.0,20.464.0,37.172.0,47.153.0,32.181.0,40.173.0"}
P.entries["subzone:tyr-s-hand"] = {n="提尔之手",s="提尔之手是位于东瘟疫之地东南群山中的一座防守严密的人类要塞。长期以来，它被圣光教会视为一座古老的圣地，而如今，这座城市已成为狂热的血色十字军在当地主要的堡垒和补给中心。",h="提尔之手是位于东瘟疫之地东南群山中的一座防守严密的人类要塞。长期以来，它被圣光教会视为一座古老的圣地，而如今，这座城市已成为狂热的血色十字军在当地主要的堡垒和补给中心。",kw={"阿比迪斯","黛米提雅","东威尔德","圣光","血色十字军教堂","血色十字军","提尔之手","瓦德玛尔"},ang={["class:Paladin"]="对于神圣战士来说，看到这个白银之手的古老摇篮被扭曲成一个充满疯狂、坚不可摧的血色狂热堡垒，是一个严酷的警告，提醒人们当信仰失去了怜悯的调节后会变成什么样。",["class:Priest"]="修道院和血色十字军教堂作为早期圣光教会的建筑奇迹，依然气势宏伟，尽管里面的神职人员已经将牧灵疗愈换成了盲目的十字军征讨。"},sec={{t="教堂之城",b="提尔之手险要地矗立在曾经属于洛丹伦的绿色东威尔德，是人类最古老的圣地之一。由于其地面上耸立着众多的神龛和神圣建筑，该定居点被称为“教堂之城”。与瘟疫之地其他地方那些被腐蚀的废墟不同，提尔之手凭借坚固的砖石、厚重的城墙以及巍峨的血色十字军教堂的剪影，依然得到了完好的保存。"},{t="血色十字军的堡垒",b="当第三次战争期间天灾军团横扫洛丹伦时，瓦德玛尔领主凭借纯粹的军事警惕和信仰守住了这座城市。在白银之手骑士团分裂成敌对派系后，提尔之手坚定地与血色十字军的赤色黎明站在了一起。如今，它已成为由大将军布丽奇特·阿比迪斯和瓦德玛尔领导的坚不可摧的行动基地。精英十字军在修道院内训练，严密守卫的信使负责维持与驻守斯坦索姆的血色部队之间的联系，而这座城市则无情地击退了所有接近其大门的陌生人。"}},faq={{q="为什么这座城市被称为提尔之手？",a="这个名字非常古老，洛丹伦幸存的记录中很少提及提尔是谁。这座城市本身被认为是旧东威尔德圣光教会最古老、最受尊崇的圣地之一。",al={"提尔是谁","提尔之手名字含义","提尔之手起源"}},{q="为什么天灾军团没有攻陷提尔之手？",a="提尔之手占据了一个天然的山区咽喉要地，并有坚固的石制防御工事、军营和一座修道院作为屏障。除了防御性的地理位置外，血色十字军还拥有一支精锐且装备精良的常备守军，他们的尚武狂热和耀眼的神圣魔法成功击退了天灾军团一波又一波的猛烈攻势。",al={"提尔之手为什么幸存","提尔之手为什么不是亡灵","提尔之手如何坚守"}},{q="游客和冒险者在提尔之手受欢迎吗？",a="不。血色十字军已经陷入了排外的偏执，他们视任何非其成员的人为潜在的亡灵瘟疫携带者或天灾军团的秘密特工。联盟和部落的局外人一旦被发现就会遭到攻击。",al={"我能访问提尔之手吗","提尔之手友好吗","这里的血色十字军友好吗"}},{q="这座城市在第二次战争中扮演了什么角色？",a="在第二次战争期间，奥特兰克的煽动者曾在提尔之手秘密挑起了一场农民起义，以此掩护附近的一个兽人采矿据点。在联盟和白银之手平定骚乱后，部落的食人魔术士对该城进行了猛烈的轰炸，并洗劫了邻近的海湾，以切断奎尔萨拉斯的补给线。",al={"第二次战争提尔之手","提尔之手农民起义"}}},fp="10,284,18.444.0,31.592.0,34.209.0,42.334.0,52.244.0,50.301.0"}
P.entries["subzone:tyr-s-hand-abbey"] = {n="Tyr's Hand Abbey",s="Tyr's Hand Abbey是一座维护良好的圣所，坐落在东瘟疫之地东南部的提尔之手防御堡垒内。它由血色十字军的狂热者所控制，作为除宏伟的血色十字军教堂之外的辅助礼拜与学习场所。",h="Tyr's Hand Abbey是一座维护良好的圣所，坐落在东瘟疫之地东南部的提尔之手防御堡垒内。它由血色十字军的狂热者所控制，作为除宏伟的血色十字军教堂之外的辅助礼拜与学习场所。",kw={"东瘟疫之地","hall of arms","图书馆侧厅","血色十字军教堂","血色十字军","tyr's hand abbey","提尔之手"},ang={["class:Paladin"]="对于圣战者来说，这座修道院代表了白银之手遗产的悲剧性腐化：一个曾经神圣的祈祷之地，如今已变成狂热与嗜血的堡垒。",["class:Priest"]="图书馆侧厅保留着古典圣光教义的残余，尽管这些教义是通过血色十字军扭曲且偏执的视角所保存下来的。"},sec={{t="狂热者的圣所",b="虽然宏伟的血色十字军教堂在提尔之手的天际线上占据主导地位，但这座修道院为血色十字军提供了一个更为安静、实用的奉献与武学教义中心。其建筑风格与艾尔文森林的北郡修道院等传统的圣光教派基础建筑非常相似，设有一个中央大厅，两侧分别是Hall of Arms和一个专门的图书馆侧厅。尽管瘟疫之地恐怖无情，但十字军仍以极其细致的态度维护着这座修道院，并不惜一切代价保卫其回廊，拒绝任何外人进入。"}},faq={{q="Tyr's Hand Abbey有什么用途？",a="它是血色十字军在提尔之手的次要宗教与后勤设施。虽然宏伟的血色十字军教堂负责举办大型仪式，但该修道院通过其Hall of Arms和图书馆侧厅，提供了生活、训练和学习的场所。",al={"这座建筑是什么","tyrs hand abbey的目的","修道院里发生什么"}},{q="为什么它看起来像北郡修道院？",a="这两座建筑都是遵循洛丹伦和暴风城的圣光教会修道院标准建筑设计建造的，将建筑划分为一个主集会厅、一个武术训练侧厅和一个圣典档案馆。",al={"北郡修道院的仿制品","为什么它看起来像北郡修道院","修道院布局"}},{q="现在谁控制着这座修道院？",a="该修道院完全由血色十字军控制。就像防御严密的提尔之手城其余部分一样，它由十字军战士、牧师和圣骑士严密防守，他们会攻击任何没有身着其制服的人。",al={"谁拥有tyrs hand abbey","血色十字军在这里吗"}}},fp="16,280,24.533.0,34.242.0,39.246.0,33.231.0"}
P.entries["subzone:uldaman"] = {n="奥达曼",s="奥达曼位于荒芜之地北部山脉的深处，是一座古老的泰坦金库，其历史可以追溯到世界重塑时期。最近，矮人挖掘者开启了这座遗迹，其大厅中不仅埋藏着矮人种族的起源，还有凶残的穴居人和警觉的石像守卫。",h="奥达曼位于荒芜之地北部山脉的深处，是一座古老的泰坦金库，其历史可以追溯到世界重塑时期。最近，矮人挖掘者开启了这座遗迹，其大厅中不仅埋藏着矮人种族的起源，还有凶残的穴居人和警觉的石像守卫。",kw={"阿扎达斯","荒芜之地","诺甘农圆盘","土灵","探险者协会","艾隆亚","泰坦","穴居人","奥达曼"},ang={["profession:Mining"]="这些由泰坦打造的大厅中有着数千年来未曾开采的稀土和金属矿脉，但想要开采它们，就意味着要面对穴居人的伏击和苏醒的石像守卫。",["race:Dwarf"]="奥达曼代表着通向你们最早传承的门户。几代人以来，铁炉堡的氏族一直想知道他们是如何诞生的；答案就刻在这些埋藏在穴居人横行的地底大厅之下的石盘上。"},sec={{t="最初创造物的金库",b="奥达曼是由泰坦守护者建造的一座地下要塞和研究设施。当早期的塑造活体岩石实验制造出了畸形的穴居人后，泰坦们将这些失败的造物封存在金库的静滞舱中，并重新开始实验，最终创造出了拥有岩石皮肤的土灵。奥达曼最深处的密室中保存着至关重要的档案，包括传说中的诺甘农圆盘，由石像守望者阿扎达斯和巨人艾隆亚守护。矮人的传说认为，拥有岩石皮肤的土灵最终演化成了矮人种族，而他们的摇篮就埋藏在这些山丘之下，已被世人遗忘。"},{t="发掘与动荡",b="当铁炉堡的勘探者们冲破奥达曼的外部大门时，他们的鹤嘴锄无意间凿开了静滞舱。大群苏醒的穴居人冲出了上层隧道，击退了矮人小队并切断了早期的挖掘现场。混乱之中，黑铁矮人也闯入遗迹，试图为他们火焰的主人拉格纳罗斯搜寻拥有强大力量的神器。如今，深处的矿井已成为各方势力——包括相互竞争的挖掘小队、嗜血的穴居人，以及为了粉碎任何闯入者而苏醒的泰坦构装体——之间的战场，无论入侵者属于哪个部落或有何目的。"}},faq={{q="什么是奥达曼？",a="奥达曼是一座巨大的地下泰坦设施，位于荒芜之地的北部边界。它建于世界黎明时期，用于隔离失败的泰坦实验并存放大量的历史记录，其中最著名的是诺甘农圆盘。",al={"奥达曼背景故事","这是什么地方","关于奥达曼"}},{q="为什么奥达曼对矮人很重要？",a="矮人传说认为他们的祖先，即拥有岩石皮肤的土灵，是在像奥达曼这样的泰坦设施中被创造出来的。找到并破译埋藏在遗迹核心处的诺甘农圆盘，或许能揭开矮人起源的终极真相。",al={"矮人为何在意奥达曼","矮人起源","诺甘农圆盘"}},{q="为什么穴居人会盘踞在遗迹中？",a="穴居人是泰坦最早试图制造的岩石仆从。当实验出错后，泰坦将他们锁在了奥达曼的静滞金库中。铁炉堡的矿工意外地破坏了这些囚笼，导致穴居人涌入了走廊和周围的山脉。",al={"穴居人从哪里来","为什么穴居人在这里","穴居人起源"}},{q="黑铁矮人在那里做什么？",a="黑铁矮人的入侵者正在搜寻古代泰坦神器，希望能发掘出像诺甘农圆盘这样强大的遗物，来效忠他们元素的主人——炎魔之王拉格纳罗斯。",al={"奥达曼的黑铁矮人","黑铁矮人为何在这里"}},{q="谁在守护最底层的密室？",a="最深处的金库由阿扎达斯守护，这是一位巨大的石像守望者，其职责是与一支活体岩石构装体和魔像军团一起，守护这座综合设施及其知识。",al={"阿扎达斯","奥达曼的头目是谁","奥达曼守护者"}}},fp="7,287,32.613.0,22.547.1,16.243.0,40.249.0,35.280.0,42.181.0,31.187.0"}
P.entries["subzone:uldum"] = {n="奥丹姆",s="奥丹姆是一处巨大的、被封印的泰坦研究设施，隐藏在塔纳利斯最南端悬崖后的巨大石门之内。长期以来，它一直被古老的结界和早已被人遗忘的机械所掩盖，现代的探险家根本无法进入。",h="奥丹姆是一处巨大的、被封印的泰坦研究设施，隐藏在塔纳利斯最南端悬崖后的巨大石门之内。长期以来，它一直被古老的结界和早已被人遗忘的机械所掩盖，现代的探险家根本无法进入。",kw={"探险者协会","奥丹姆之门","奥丹姆圆盘","塔纳利斯","泰坦","奥丹姆"},ang={["faction:Alliance"]="联盟学者们希望能在任何敌对势力之前，抢先获取隐藏在南部山脉中的泰坦秘密。",["race:Dwarf"]="对于那些通过探险者协会追寻泰坦遗产的矮人来说，奥丹姆的宏伟之门代表了卡利姆多大陆上最令人费解的谜团之一。"},sec={{t="造物者之门",b="通往奥丹姆的巨大门户矗立在塔纳利斯沙漠边缘崎岖的南部山脉之中，寂静且不可逾越。它建造于远古卡利姆多的秩序建立时期，是一座先进的泰坦设施，与泰坦塑造和监视星球生物圈的神秘工作息息相关。泰坦守护者和防御构装体曾经负责维护这里的外围防线，留给现代凡人的只有宏伟的石刻拱门和深埋的秘密，这些秘密抵御了一切凡世的入侵尝试。"},{t="被封印的秘密",b="该遗址上无可辨驳的泰坦工艺吸引了矮人学者的好奇心，但至今尚未发现任何能够开启这座古老建筑的机关或钥匙。传说声称，要真正洞悉深锁其中的秘密，需要用到失落的“奥丹姆圆盘”，这使得矮人学者们只能透过门锁的缝隙，窥视着一个他们至今无法攻破的帝国。"}},faq={{q="你能打开奥丹姆的大门吗？",a="不能。通往山隘的巨大石门被完全封死，隔绝了任何凡人的入侵。周围的沙漠中不存在任何可以解锁它们的机关或钥匙。",al={"如何进入奥丹姆","打开奥丹姆之门","进入奥丹姆"}},{q="奥丹姆里有什么？",a="根据古老的记录和泰坦传说，奥丹姆是一座宏大的研究设施，由泰坦建造，用于研究和改善艾泽拉斯的生物圈。然而，具体的细节仍然被泰坦的安全措施锁在门后。",al={"奥丹姆是什么","奥丹姆的目的","奥丹姆内部"}},{q="什么是奥丹姆圆盘？",a="奥丹姆圆盘是泰坦创造的古代数据圆盘。根据远古石像守卫保存的传说，关于奥丹姆内部工作和设施的具体知识只能通过这些神圣的圆盘来获取。",al={"奥丹姆圆盘","奥丹姆数据盘","奥丹姆石板"}}},fp="5,236,23.511.0,18.354.0,32.193.0,21.225.0,29.235.0"}
P.entries["subzone:undercity"] = {n="幽暗城",s="幽暗城在洛丹伦都城的破碎宫殿之下开凿而成，是遗忘者庞大的地下堡垒。这里原本是复杂的皇家墓穴、地牢和下水道网络，后来被天灾军团扩建。希尔瓦娜斯·风行者夺取了此地，并将其打造成了一座为她的自由亡灵提供重重保护的首都。",h="幽暗城在洛丹伦都城的破碎宫殿之下开凿而成，是遗忘者庞大的地下堡垒。这里原本是复杂的皇家墓穴、地牢和下水道网络，后来被天灾军团扩建。希尔瓦娜斯·风行者夺取了此地，并将其打造成了一座为她的自由亡灵提供重重保护的首都。",kw={"阿尔萨斯","都城","墓穴","地下墓穴","遗忘者","洛丹伦","希尔瓦娜斯","幽暗城"},ang={["faction:Horde"]="这座地下城市是部落在东部王国的主要军事据点，尽管其昏暗且充斥着药剂气味的通道对于来自卡利姆多的访客来说并不舒适。",["race:Undead"]="幽暗城是遗忘者文明跳动的心脏——它是由你们过去生活的废墟和墓穴建造的避难所，在这里，你们得以免受天灾军团和生者的侵扰。"},sec={{t="从皇家墓穴到天灾军团的堡垒",b="在第三次战争前，都城之下的深处拥有一个庞大的下水道、皇家陵墓和地牢网络。在洛丹伦沦陷期间，阿尔萨斯·米奈希尔王子下令他的天灾军团开始将这些深处地带扩建为权力中心。当巫妖王召唤阿尔萨斯前往诺森德时，这位死亡骑士留下了尚未完工的建筑。"},{t="遗忘者的首都",b="在瘟疫之地的内战中，希尔瓦娜斯·风行者集结了那些从巫妖王的控制中挣脱出来的亡灵。在推翻恐惧魔王并赶走敌对势力后，新生的遗忘者占据了这个地下建筑群。他们完成了天灾军团未竟的扭曲墓穴迷宫，将其加固为一座隐匿在他们曾经王国静谧废墟之下的坚不可摧的堡垒。今天，黑暗女王就在其充满毒气的大厅中统治着她的人民。"}},faq={{q="在亡灵接管之前，幽暗城一直就在这里吗？",a="是的，尽管规模要小得多。在洛丹伦王国时期，宫殿之下的区域有着古老的皇家墓穴、地牢和城市的下水道系统。",al={"幽暗城的起源","幽暗城一直存在吗","幽暗城的历史"}},{q="究竟是谁建造了现代的幽暗城？",a="最初的扩建工程是由阿尔萨斯·米奈希尔王子发起的，他意图将其作为天灾军团在洛丹伦的权力中心。当阿尔萨斯被召回诺森德时，希尔瓦娜斯·风行者和她的遗忘者夺取了这些未完成的隧道，并花费数年时间进行挖掘和加固，将其变成了今天所见的这座堡垒城市。",al={"谁制造了幽暗城","谁建造了幽暗城","幽暗城的建设"}},{q="为什么要住在地下而不是重建地上的城市？",a="都城的地面废墟容易受到血色十字军、天灾余孽和联盟的攻击。地下墓穴具有天然的防御性，隐蔽在视野之外，且非常适合亡灵的需求，因为他们不需要阳光、温暖或露天空气。",al={"为什么要住在地下","为什么不重建洛丹伦","为什么选择幽暗城"}},{q="谁统治着幽暗城？",a="这座城市由女妖之王、遗忘者的领袖希尔瓦娜斯·风行者女王统治，她在建筑群深处的皇家区进行管辖。",al={"幽暗城的领袖是谁","幽暗城领袖","谁统治幽暗城"}}},fx={f1849a51={q="什么是幽暗城？",a="幽暗城是被遗忘者的地下首都，规模庞大，位于破碎的洛丹伦王城废墟正下方。它最初由古老的皇家墓穴、地牢和下水道组成，后来扩建成迷宫般的堡垒。如今，这里是希尔瓦娜斯·风行者女王领地的核心，既是坚固的避难所和政治中心，也是部落中拥有自由意志的亡灵进行研究的据点。",al={"什么是幽暗城","幽暗城概览","幽暗城传说"}},["88d828cf"]={q="幽暗城发生过什么？",a="洛丹伦沦陷后，阿尔萨斯王子开始在首都地下开辟据点，供天灾军团使用。巫妖王的力量减弱、阿尔萨斯逃往诺森德后，希尔瓦娜斯·风行者率领获得自由的亡灵起义。在瘟疫之地的内战期间，她的部队击败了敌对的恐惧魔王和联盟残部，夺取了这片地下网络，并将其建成新成立的被遗忘者的据点。",al={"幽暗城的历史","幽暗城历史","这里发生了什么"}},["9e3a5d6b"]={q="谁住在幽暗城？",a="城中居民以被遗忘者为主——他们是挣脱巫妖王铁腕控制的亡灵。在各个城区，你会遇见调制致命药剂的皇家药剂师协会、行踪诡秘的盗贼、黑暗施法者，以及守卫外围的亡灵卫兵。来自部落的兽人、牛头人和暗矛巨魔也会有使节与战士到访，尽管他们很少能自在地穿行于城中。",al={"谁住在幽暗城","幽暗城居民","幽暗城人口"}},a78ac513={q="幽暗城危险吗？",a="对外来者和粗心的访客而言，这里极其危险。擅闯的联盟成员会迅速死在警惕的亡灵卫兵手中。即使是宣誓效忠部落的盟友，在城中也会遭遇危险：巨大的竖井、有毒的炼金污泥池、阴森的通灵师和心怀算计的药剂师，都可能因一个失足而致人丧命。",al={"幽暗城危险吗","幽暗城有多危险","幽暗城的危险"}},["4cec4aa1"]={q="为什么叫幽暗城？",a="这个名字描述了它的位置：一座位于洛丹伦王城废墟下方的城市。它由曾经位于王宫之下的皇家墓穴、地牢和下水道发展而来：阿尔萨斯麾下的天灾军团开始扩建这些地下区域，被遗忘者则完成了这项工程，并将这片庞大的地下迷宫作为家园。",al={"幽暗城名称由来","幽暗城名称的起源","为什么叫幽暗城"}}},fp="9,323,36.360.0,20.498.0,54.161.0,40.314.0,58.283.0,24.141.0"}
P.entries["subzone:undercroft"] = {n="墓室",s="墓室是一座古老的地下墓穴，坐落在东瘟疫之地的西南丘陵中。它曾是洛丹伦的一座庄严陵墓，如今却被扎尔达拉和他的流亡亡灵巨魔爪牙所亵渎。在这片被玷污的墓穴之中，掩埋着一座久远前挖掘的假墓，那是为了掩盖流放圣骑士提里奥·弗丁的假死而设。",h="墓室是一座古老的地下墓穴，坐落在东瘟疫之地的西南丘陵中。它曾是洛丹伦的一座庄严陵墓，如今却被扎尔达拉和他的流亡亡灵巨魔爪牙所亵渎。在这片被玷污的墓穴之中，掩埋着一座久远前挖掘的假墓，那是为了掩盖流放圣骑士提里奥·弗丁的假...",kw={"墓穴","恐魔","东瘟疫之地","坟墓","圣光之愿","流亡者","提里奥·弗丁","墓室","扎尔达拉"},ang={["class:Paladin"]="对于圣战者而言，进入墓室意味着目睹一段悲剧——流放英雄提里奥·弗丁的虚假葬礼，以及扎尔达拉卑劣的族群对神圣墓穴的污蔑。",["race:Troll"]="巨魔旅人会将“流亡者”扎尔达拉和他的亡灵同类视为对巨魔传统以及向已故祖先履行神圣仪式的严酷而扭曲的嘲弄。"},sec={{t="被亵渎的坟冢",b="墓室开凿在考林路口西南方的崎岖峭壁中，最初是作为洛丹伦尊贵逝者的安息之所而建。王国的陨落剥夺了它的神圣，如今这里已被一群野蛮的亡灵巨魔所占据。在庞大的怪物“流亡者”扎尔达拉的率领下，这些食尸鬼般的掠夺者将地下大厅用作盘踞点，以此在瘟疫之地四处徘徊，甚至胆敢突袭圣光之愿礼拜堂的墓穴，搜刮尸体以供他们进行邪恶的勾当。"},{t="伪装者的陵墓",b="除了这些鸠占鹊巢的怪物外，墓室还隐藏着一个关乎第二次战争时期的辛酸秘密：一座刻有提里奥·弗丁名字的假墓。在弗丁因叛国罪受审并被流放后，他的盟友们在此安排了一场象征性的葬礼，以便让他的家族能够保住地位，同时让这位落魄的圣骑士销声匿迹。在这片泥土掩盖的谎言中，安放着一件来自提里奥过去的个人遗物，藏在只有知晓真相的人才敢寻找的地方。"}},faq={{q="墓室是什么？",a="墓室是坐落在东瘟疫之地西南部的一座墓穴。最初的建造目的是为了安葬洛丹伦当地的贵族和阵亡士兵，但如今它已沦为废墟，并被亡灵怪物所占据。",al={"墓室在哪里","这是什么墓穴","墓室 东瘟疫之地"}},{q="现在是谁占据了墓穴？",a="墓穴被一群亡灵巨魔所占据，首领是一只被称为“流亡者”扎尔达拉的巨大亡灵恐魔。他们将这些隧道作为在地区内搜刮掠夺时的巢穴。",al={"墓室里有什么人","墓室怪物","墓室中的巨魔"}},{q="为什么东瘟疫之地会有亡灵巨魔？",a="虽然天灾军团主要是在洛丹伦北部复活人类和精灵，但苔藓剥皮者和枯木巨魔等部落也居住在附近。像扎尔达拉和他的复生爪牙这样的亡灵巨魔游荡在峭壁间，洗劫墓地并捕食毫无防备的旅人。",al={"为什么这里有巨魔","扎尔达拉背景故事","东瘟疫之地 亡灵巨魔"}},{q="为什么提里奥·弗丁的名字会出现在这里的墓碑上？",a="那座墓是一个替代品，也就是假墓。在提里奥被洛丹伦联盟剥夺军衔并流放后，盟友在墓室安排了一场虚假的葬礼，这样他的家人就可以维护名誉并声称他已死亡，而他本人则秘密地隐居了起来。",al={"提里奥之墓","提里奥死了吗","弗丁的坟墓"}},{q="墓室的巨魔为什么要突袭圣光之愿礼拜堂？",a="“流亡者”扎尔达拉偶尔会带领部下对圣光之愿礼拜堂外的墓坑发动夜间突袭。他的目的是挖掘并偷走新下葬的尸体，以扩充自己的队伍或满足他们病态的食欲。",al={"扎尔达拉突袭","突袭墓坑","圣光之愿的巨魔"}}},fp="10,351,22.536.0,18.491.1,23.240.0,27.189.0,55.269.0,46.268.0,54.222.0"}
P.entries["subzone:uplands"] = {n="高地",s="高地是奥特兰克山脉东北部一片起伏的高地，曾是覆灭的奥特兰克王国的农业腹地。在王国覆灭后，这些肥沃的丘陵完全落入了辛迪加的控制之下。如今，这个犯罪组织在此维持着其最强大的权力基地，并在各处山坡上加固了多个营地。",h="高地是奥特兰克山脉东北部一片起伏的高地，曾是覆灭的奥特兰克王国的农业腹地。在王国覆灭后，这些肥沃的丘陵完全落入了辛迪加的控制之下。如今，这个犯罪组织在此维持着其最强大的权力基地，并在各处山坡上加固了多个营地。",kw={"奥特兰克","巴隆·瓦杜斯","粮仓","达伦德农场","山脉","辛迪加","高地"},ang={["class:Rogue"]="高地是辛迪加的主要权力所在地，这使得它成为了研究流离失所的贵族如何将整个区域性的强盗网络转变为一个有组织的致命卡特尔的关键案例。",["race:Human"]="这些丘陵是奥特兰克覆灭的冷酷提醒；曾经是人类繁荣的农业粮仓的地方，现在挤满了亡命之徒和破碎的野心。"},sec={{t="从粮仓到强盗据点",b="在第二次战争摧毁奥特兰克之前，高地曾被誉为王国的粮仓，为山中堡垒提供谷物和牲畜。当王国的核心陷入废墟和声名狼藉的境地时，诚实的民众放弃了这些农庄。取而代之的是辛迪加，由失势的奥特兰克贵族和亡命之徒领导，他们决心通过武力夺回被窃取的遗产。高地现在是辛迪加在该地区势力最集中的领地，遍布着营地、巡逻队和哨所，例如其西部边界上的达伦德农场。"},{t="阴影据点",b="由于辛迪加在这些丘陵地区拥有强大的控制力，高级阴谋家经常在高地指挥行动。诸如巴隆·瓦杜斯之类的人物与引导奥特兰克贵族残余势力的幕后黑手结盟，协调强盗的行动、对邻近山谷的突袭以及针对联盟和部落的抵抗。穿越东北山脊的旅行者会立即遭到根深蒂固的劫匪的敌视，他们视整个山脉为自己的领土。"}},faq={{q="高地最初的用途是什么？",a="高地在历史上曾是奥特兰克王国主要的农业区。在战争和背叛导致国家覆灭之前，其起伏的丘陵曾是王国的粮仓。",al={"高地历史","这里过去是什么","高地的用途"}},{q="现在是谁控制着高地？",a="高地由辛迪加控制。奥特兰克的前贵族及其强盗网络在这些丘陵中建立了多个营地，使其成为他们势力最强的地区。",al={"谁居住在高地","谁控制着高地","高地的阵营"}},{q="高地位于何处？",a="高地横跨奥特兰克山脉的东北部高地，西部边缘与达伦德农场接壤。",al={"高地的位置","高地在哪里","如何找到高地"}},{q="巴隆·瓦杜斯是谁？",a="巴隆·瓦杜斯是辛迪加内部的一位有影响力的贵族和领袖，他负责监督高地的行动，指挥那些试图夺回奥特兰克的强盗和阴谋家。",al={"巴隆·瓦杜斯背景故事","瓦杜斯是谁","高地男爵"}}},fx={["35db727f"]={q="高地为何沦为废墟并被遗弃？",a="高地曾是奥特兰克王国的粮仓，遍布肥沃的田地和农庄。第二次战争期间，奥特兰克背叛盟军，王国随之覆灭，其腹地也遭到重创。失去王国庇护后，这片地区的农业核心逐渐衰败，又被罪犯占据，达伦德农场等遗迹由此留存下来。",al={"高地为何沦为废墟","高地的农场发生了什么","高地为何被遗弃"}},["4211f63f"]={q="高地危险吗？",a="这里极其危险。高地是辛迪加的主要据点，聚集着山脉中数量最多的辛迪加战士。四处游荡的强盗、亡命之徒和叛变贵族在山间巡逻，凶狠地守卫营地，不让任何外人侵入他们的地盘。",al={"高地危险吗","高地危险","高地有多危险"}}},fp="7,390,32.608.0,17.495.0,41.202.0,29.202.0,29.119.0,20.175.0"}
P.entries["subzone:ursolan"] = {n="乌索兰",s="乌索兰是位于艾萨拉西部的一处庞大的木喉熊怪定居点，就在木喉要塞的东侧。营地被一条深邃的峡谷一分为二，它纪念着熊之半神乌索尔，是未受腐蚀的熊怪守卫领土抵御外敌的重要堡垒。",h="乌索兰是位于艾萨拉西部的一处庞大的木喉熊怪定居点，就在木喉要塞的东侧。营地被一条深邃的峡谷一分为二，它纪念着熊之半神乌索尔，是未受腐蚀的熊怪守卫领土抵御外敌的重要堡垒。",kw={"艾萨拉","熊怪","深谷","泰兰迪斯","木喉","乌索尔","乌索兰"},ang={["class:Druid"]="德鲁伊对乌索兰的守护者怀有深切的敬意，因为双子熊半神乌索尔和乌索克是自然崇拜和熊形态掌握的核心人物。",["race:NightElf"]="虽然暗夜精灵也崇拜熊之半神，但双方在实地却存在紧张关系，这从泰兰迪斯的研究人员在熊怪警惕的注视下考察峡谷这一点上就可见一斑。"},sec={{t="熊之壁垒",b="乌索兰坐落在艾萨拉西部的崎岖悬崖上，构成了木喉部族领地的东部支脉，通过木喉要塞直接与南部的熊头相连。该营地以受人敬仰的熊之半神乌索尔命名，是卡利姆多熊怪群体中罕见的理智避难所，毕竟大多数熊怪都已沦为恶魔腐蚀的牺牲品。村庄横跨一道巨大的地壳裂缝两侧，木喉熊怪在这里警惕地守卫着边界，抵御入侵者，包括来自泰兰迪斯暗夜精灵营地的那些闯入者。"}},faq={{q="谁住在乌索兰？",a="乌索兰居住着木喉熊怪，他们是少数几支成功抵御了肆虐卡利姆多的恶魔腐蚀的熊怪部族之一。",al={"乌索兰里有什么人","乌索兰的居民","乌索兰的熊怪"}},{q="为什么这个区域叫乌索兰？",a="该定居点是以乌索尔的名字命名的，乌索尔是深受熊怪种族崇拜的两位熊之半神之一。",al={"乌索兰的命名由来","乌索兰是以谁的名字命名的","乌索兰的含义"}},{q="穿过营地的那道深谷是什么？",a="乌索兰被大地上的一道深痕所分割。在峡谷深处，经常可以看到来自附近暗夜精灵营地泰兰迪斯的生物学家们在进行实地考察。",al={"乌索兰的峡谷","乌索兰的深谷","乌索兰的地裂"}},{q="乌索兰如何与木喉领地的其他部分连接？",a="乌索兰位于木喉要塞艾萨拉入口的正东方，通过山间隧道将他们北部的驻地与南部的熊头连接起来。",al={"乌索兰的连接","如何从乌索兰前往木喉要塞"}}},fp="7,290,19.587.0,21.161.0,32.110.0,48.175.0,64.164.0"}
P.entries["subzone:uther-s-tomb"] = {n="乌瑟尔之墓",s="乌瑟尔之墓是光明使者乌瑟尔神圣的安息之所，位于西瘟疫之地的悔恨岭顶端。这座纪念碑由他在安多哈尔战败后的幸存追随者们所建，是在这片饱受瘟疫侵扰、鬼魂出没的地区中，为数不多的圣光堡垒之一。",h="乌瑟尔之墓是光明使者乌瑟尔神圣的安息之所，位于西瘟疫之地的悔恨岭顶端。这座纪念碑由他在安多哈尔战败后的幸存追随者们所建，是在这片饱受瘟疫侵扰、鬼魂出没的地区中，为数不多的圣光堡垒之一。",kw={"andorhal","阿尔萨斯","光明使者","白银之手","悔恨岭","thel'danis","乌瑟尔"},ang={["class:Paladin"]="站在乌瑟尔的雕像前，对任何圣骑士来说都是一次意义深远的朝圣，他们在此向这位骑士团之父致敬，他的牺牲体现了白银之手的崇高美德。",["faction:Alliance"]="这座陵墓是洛丹伦陨落遗产的永恒见证，也是联盟旅行者在饱受瘟疫之地恐怖袭击时进行安静反思的地方。"},sec={{t="瘟疫中的堡垒",b="乌瑟尔之墓坐落在安多哈尔废墟以南的悔恨岭上，标志着这位创立了白银之手骑士团的传奇圣骑士的最终安息地。洛丹伦陷落后，乌瑟尔在安多哈尔进行了最后的抵抗，守卫着存放泰瑞纳斯·米奈希尔二世国王骨灰的皇家骨灰瓮，抵御阿尔萨斯·米奈希尔王子和天灾军团的进攻。阿尔萨斯击倒了他昔日的导师，并亵渎了骨灰瓮，用来装载克尔苏加德的遗骸。幸存的士兵们收敛了乌瑟尔的遗体，将其安葬在一座石砌圣所中。尽管周围的土地被无情的腐蚀所笼罩，但陵墓却奇迹般地未受侵蚀，在大祭司Thel'danis的坚定守护下保持完好。"},{t="光明使者的遗产",b="沿着乌瑟尔之路前行，纪念碑的中心是一座宏伟的石像，描绘了这位圣骑士一手拿着圣光之书，另一手握着战锤的形象。跋涉过这些险恶道路的朝圣者经常会来到陵墓前，向这位定义了首批圣骑士忠诚信仰的先驱致敬、祈祷或进行反思。"}},faq={{q="谁葬在这座陵墓里？",a="光明使者乌瑟尔安葬于此。他是白银之手骑士团的最高指挥官和创始人，这是人类历史上第一个圣骑士组织，在洛丹伦陷落于天灾军团之前，他曾担任阿尔萨斯·米奈希尔王子的导师。",al={"谁是乌瑟尔","谁葬在这里","光明使者乌瑟尔"}},{q="乌瑟尔是怎么死的？",a="乌瑟尔在安多哈尔被他昔日的学生阿尔萨斯·米奈希尔杀害，后者作为死亡骑士从诺森德归来。乌瑟尔在拼死守卫存放着阿尔萨斯之父，泰瑞纳斯·米奈希尔二世国王骨灰的骨灰瓮时牺牲。",al={"谁杀了乌瑟尔","乌瑟尔是怎么死的","阿尔萨斯杀死乌瑟尔"}},{q="大祭司Thel'danis是谁？",a="大祭司Thel'danis是这座纪念碑的忠诚看护者。他默默地在乌瑟尔的安息之所进行神圣的守夜，冒着周围亡灵的威胁，确保这座圣殿始终是圣光的避难所。",al={"thel'danis","乌瑟尔之墓的祭司","谁在守护陵墓"}},{q="为什么陵墓没有受到瘟疫的腐蚀？",a="乌瑟尔的记忆中永恒的神圣感和圣光的不朽力量净化了这片土地。虽然悔恨岭周围的森林已经枯萎腐烂，但这座圣殿本身仍然是抵御瘟疫的一片净土。",al={"为什么乌瑟尔之墓是干净的","为什么陵墓没有瘟疫"}}},fp="12,311,23.713.0,25.330.0,27.242.0,18.229.0,30.213.0,43.252.0"}
P.entries["subzone:valgan-s-field"] = {n="瓦尔甘牧场",s="瓦尔甘牧场是坐落于银松森林北部的一处废弃麦田，俯瞰着洛丹米尔湖。这里曾经是一片风景如画的家园，如今却荒凉破败，被大法师阿鲁高释放出的月怒狼人所占据。",h="瓦尔甘牧场是坐落于银松森林北部的一处废弃麦田，俯瞰着洛丹米尔湖。这里曾经是一片风景如画的家园，如今却荒凉破败，被大法师阿鲁高释放出的月怒狼人所占据。",kw={"阿鲁高","月怒","闪光湖岸","银松森林","瓦尔甘","瓦尔甘牧场","狼人"},ang={["class:Mage"]="阿鲁高在农场留下的废弃研究，为不受限制的召唤术和位面魔法所带来的灾难性危险提供了一个严肃的警示。",["race:Undead"]="对于被遗忘者来说，清理瓦尔甘牧场对于确保银松森林道路的安全，以及在阿鲁高的怪物宠物进一步向北蔓延之前回收他的笔记至关重要。"},sec={{t="一处废弃的家园",b="瓦尔甘牧场位于闪光湖岸以西，附近河流的北侧。它曾经是一座繁荣的麦田，可以欣赏到洛丹米尔湖的迷人景色。当天灾军团席卷洛丹伦时，这份宁静的生活随之消失，农场主瓦尔甘被迫逃离或是死于非命。无人照料的农场陷入了废墟，并落入从影牙城堡游荡而来的凶猛月怒狼人之爪。在第三次战争之前，法师阿鲁高曾在此居住，留下了一些奥术研究的遗迹，如今这些遗迹吸引了被遗忘者的注意。"}},faq={{q="瓦尔甘是谁？",a="瓦尔甘是一位人类农夫，在第三次战争之前拥有并耕种着这座家园。当天灾军团横扫洛丹伦北部时，瓦尔甘要么已经死去，要么逃亡在外，留下了这座逐渐荒废的农场。",al={"瓦尔甘","瓦尔甘是谁","瓦尔甘牧场历史"}},{q="为什么狼人会在瓦尔甘牧场游荡？",a="盘踞在农场的凶猛月怒狼人种群是由大法师阿鲁高召唤到银松森林的。阿鲁高释放这些野兽来对抗天灾军团，但随着它们在森林中蔓延，他很快失去了控制，而愧疚感让他陷入了疯狂。",al={"为什么这里有狼人","月怒狼人 瓦尔甘","谁带来了狼人"}},{q="为什么被遗忘者对这个农场感兴趣？",a="大法师阿鲁高在战争前曾居住在这个农场，并留下了珍贵的法术书。被遗忘者们在寻求了解并对抗阿鲁高那可怕魔法的行动中，正在搜寻这些失落的文献。",al={"瓦尔甘牧场任务","为什么被遗忘者关心瓦尔甘牧场","阿鲁高 农场 法术书"}},{q="农场附近会出现什么稀有威胁吗？",a="月怒狼人种群是农场的主要威胁，目前还没有其他值得注意的威胁被发现在这些田野中游荡。",al={"夜斩","瓦尔甘牧场 稀有刷新","瓦尔甘的怪物"}}},fx={["5ca486da"]={q="什么是瓦尔甘牧场？",a="瓦尔甘牧场是位于银松森林北部的一处荒凉废弃的小麦农场，紧邻闪光湖岸以西，主路以东。瘟疫席卷洛丹伦之前，这里曾是一处宁静的农庄，可以俯瞰洛丹米尔湖。如今，它和森林中的许多地方一样，杂草丛生、无人打理，还盘踞着致命的掠食者。",al={"什么是瓦尔甘牧场","瓦尔甘农场","银松森林的瓦尔甘牧场"}},["1c9d9eee"]={q="瓦尔甘牧场发生过什么？",a="第三次战争之前，大法师阿鲁高曾在此逗留，留下了奥术研究的遗迹。天灾军团席卷银松森林时，农庄的主人被迫逃离或遭到屠戮，农庄也随之化为废墟。后来，阿鲁高从影牙城堡释放狼人肆虐当地，凶暴的月怒狼人占据了田地，把破败的农场当成自己的领地。",al={"瓦尔甘牧场历史","瓦尔甘农场发生了什么"}},d73dae69={q="瓦尔甘牧场为何沦为废墟？",a="天灾军团横扫洛丹伦北部时，摧毁了乡村聚落，农场因此被遗弃。阿鲁高召唤出异界狼人后，月怒狼群又侵占了田地，使人类再也无法在此居住，任何收复这片土地的希望也随之破灭。",al={"瓦尔甘牧场为何被遗弃","瓦尔甘农场为何沦为废墟","瓦尔甘牧场的废墟"}},["93e0efce"]={q="瓦尔甘牧场危险吗？",a="独自旅行的人在这里会面临极大危险。废弃的农庄有凶残的月怒狼人出没，它们由阿鲁高的黑暗魔法所造。贪婪的狼群会袭击任何误入田地的人。",al={"瓦尔甘牧场有多危险","瓦尔甘牧场的威胁"}}},fp="14,230,18.546.0,15.210.0,38.231.0,45.200.0,39.108.0"}
P.entries["subzone:valley-of-bones"] = {n="白骨之谷",s="白骨之谷是一处沿着辛德拉峭壁的荒凉峡谷，这里尘土飞扬，遍布古老的遗骸，充斥着不安的亡灵。玛格拉姆半人马氏族的残魂在此徘徊，黑暗的死灵法师在此巡逻。峡谷中耸立着被称为“死亡歌利亚”的神秘远古巨兽的巨大肋骨，令人望而生畏。",h="白骨之谷是一处沿着辛德拉峭壁的荒凉峡谷，这里尘土飞扬，遍布古老的遗骸，充斥着不安的亡灵。玛格拉姆半人马氏族的残魂在此徘徊，黑暗的死灵法师在此巡逻。峡谷中耸立着被称为“死亡歌利亚”的神秘远古巨兽的巨大肋骨，令人望而生畏。",kw={"半人马","死亡歌利亚","玛格拉姆","死灵法师","辛德拉","骷髅","白骨之谷"},ang={["class:Priest"]="峡谷中对灵魂的亵渎十分严重，黑暗的施法者们通过束缚玛格拉姆的灵魂并唤醒扭曲的骷髅仆从，篡改了死亡的自然规律。"},sec={{t="The Restless Dead之峡谷",b="白骨之谷隐匿在凄凉之地的南部区域，正如其名，这里是一片阴森之地。骸骨怪物在尘土飞扬的峡谷中游荡，它们是由借助黑暗魔法的半人马死灵法师所唤醒并束缚的。已故玛格拉姆半人马的灵魂也伴随着它们在荒野中徘徊，在暴毙多年之后依然被禁锢在这片贫瘠的土地上。让这座峡谷显得更加不祥的是“死亡歌利亚”——两具倚靠在岩壁上的巨大骨架，对于学者和流浪者来说，它们的真正起源至今仍是一个谜。"}},faq={{q="什么是死亡歌利亚？",a="死亡歌利亚是两具倚靠在峡谷岩壁上的巨大、身份不明的生物遗骸。关于它们属于什么物种或何时死亡，我们知之甚少，但其巨大的体型表明它们属于一个古老而被人遗忘的时代。",al={"巨骨","凄凉之地巨大骷髅","死亡歌利亚背景"}},{q="为什么这里会有半人马的幽灵？",a="这些灵魂属于玛格拉姆氏族，这是这片干旱平原上土生土长的凶残半人马部落之一。在无休止的氏族战争和半人马死灵法师亵渎死者的双重影响下，这些灵魂无法安息，化作徘徊的幻影在这座峡谷中游荡。",al={"玛格拉姆幽灵","为什么有半人马灵魂","亡灵半人马"}},{q="谁在控制峡谷里的骷髅？",a="半人马死灵法师在峡谷中进行黑暗仪式，唤醒并指挥骷髅爪牙，以此守护这些峭壁并在死者之中维持他们的立足之地。",al={"谁指挥骷髅","白骨之谷死灵法师"}}},fp="15,323,29.534.0,27.259.0,34.289.0,41.162.0"}
P.entries["subzone:valley-of-fangs"] = {n="巨牙谷",s="巨牙谷是一条崎岖狭窄的通道，位于荒芜之地中部，在耸立的岩石柱之间开辟而成。这里以潜伏在尘土飞扬的地面上的凶猛掠食者而闻名，同时也庇护着一小群与世隔绝的流浪工匠和流放者营地。",h="巨牙谷是一条崎岖狭窄的通道，位于荒芜之地中部，在耸立的岩石柱之间开辟而成。这里以潜伏在尘土飞扬的地面上的凶猛掠食者而闻名，同时也庇护着一小群与世隔绝的流浪工匠和流放者营地。",kw={"荒芜之地","美洲狮","jazzrik","martek the exiled","里格弗兹","巨牙谷","狼"},ang={["class:Hunter"]="大量强壮的美洲狮和狼群使得这个山谷成为了追踪猎物和驯服荒芜之地野兽的绝佳狩猎场。",["profession:Engineering"]="驻扎在巨牙谷的地精工匠吸引了那些在干旱荒原中寻求非传统技术的充满好奇心的工程师。"},sec={{t="危险的通道",b="巨牙谷坐落在荒芜之地中心地带两座雄伟的石层之间，其得名于周围悬崖的尖锐轮廓，以及出没于谷底的危险野兽。野生的峭壁土狼、徘徊的美洲狮和凶恶的狼群潜伏在布满尘土的走廊中，使得独自旅行变得险象环生。尽管野生动物充满敌意，但仍有一些特立独行的人物——包括被放逐的兽人Martek the Exiled，以及他的地精伙伴里格弗兹（Rigglefuzz）和Jazzrik——在这里搭建了一个非正式的营地，远离地区的哨站，在僻静中潜心钻研工艺。"}},faq={{q="巨牙谷位于哪里？",a="巨牙谷位于荒芜之地中部，夹在北部主要山脊线以南的两座巨大天然岩层之间。",al={"巨牙谷位置","巨牙谷在哪里","巨牙谷地图"}},{q="谁住在巨牙谷？",a="这里有一个小小的路边营地，是孤独的兽人Martek the Exiled和他喜欢钻研的地精伙伴里格弗兹和Jazzrik的家。",al={"巨牙谷里有什么人","巨牙谷营地","巨牙谷npc"}},{q="为什么穿越这个山谷很危险？",a="谷底栖息着大量荒芜之地本土的攻击性野生动物，特别是掠食性的美洲狮、狼和土狼，它们会在狭窄的地形中伏击路人。",al={"巨牙谷危险性","巨牙谷怪物","巨牙谷有什么会攻击你"}},{q="Martek和地精们为什么在这里安营扎寨？",a="Martek the Exiled被放逐后在荒野中流浪，他在岩壁之间找到了一个安静且易于防守的角落，与愿意交易和钻研工艺的地精伙伴们一起，远离主要势力的窥探。",al={"为什么martek在这里","为什么要驻扎在巨牙谷","martek the exiled"}}},fp="15,247,18.594.0,37.138.0,33.139.0,46.176.0,43.208.0"}
P.entries["subzone:valley-of-heroes"] = {n="英雄谷",s="英雄谷是暴风城宏伟的南入口，承载着来往的旅人跨越护城河上的石桥。道路两旁矗立着纪念联盟远征德拉诺的领袖们的巨大雕像，这里既是令人敬畏的欢迎之地，也是戒备森严的检查站。",h="英雄谷是暴风城宏伟的南入口，承载着来往的旅人跨越护城河上的石桥。道路两旁矗立着纪念联盟远征德拉诺的领袖们的巨大雕像，这里既是令人敬畏的欢迎之地，也是戒备森严的检查站。",kw={"奥蕾莉亚","达纳斯","卡德加","库德兰","马库斯·乔纳森","stormwind gate","图拉扬","英雄谷"},ang={["class:Paladin"]="图拉扬将军的雕像令圣骑士们深感鼓舞，它让这位白银之手骑士团的创始勇士之一永垂不朽。",["faction:Alliance"]="大联盟的每一位公民都将英雄谷视为种族间通力合作的庄严见证，向人类、高等精灵和矮人的殉难者致敬。"},sec={{t="迷失者的纪念碑",b="这些矗立在栈道旁的雕像修建于第二次战争后暴风城的重建时期，旨在纪念联盟远征军的指挥官们。这些勇士穿过黑暗之门，踏入了兽人的家园德拉诺，永远地封印了裂隙，并为艾泽拉斯的生存献出了生命。向北前往贸易区的访客会从大法师卡德加、库德兰·蛮锤、游侠将军奥蕾莉亚·风行者、部队指挥官达纳斯·托尔贝恩和图拉扬大将军的雕像下经过。"},{t="城市壁垒",b="除了仪式性的作用外，英雄谷还是守卫暴风城免遭陆路入侵的主要防御咽喉。城卫军指挥官马库斯·乔纳森将军负责监管此处的动向，他骑着坐骑监视着所有通过大门进出的交通。包括玛丁雷少校和斯托布里奇元帅在内的随行指挥官，正与成排的老练卫兵保持警惕，确保首都免受外部威胁。"}},faq={{q="路边的雕像是什么人？",a="这五座巨大的纪念碑描绘了洛萨之子传说中的指挥官，他们曾领导联盟远征军前往德拉诺：图拉扬大将军、游侠将军奥蕾莉亚·风行者、大法师卡德加、库德兰·蛮锤以及部队指挥官达纳斯·托尔贝恩。",al={"暴风城的雕像","英雄是谁","英雄谷雕像","雕像上的名字"}},{q="为什么要把这些纪念碑安放在城门口？",a="这些雕像修建于第二次战争后城市的重建时期，作为对在德拉诺毁灭中被认为已经失踪的英雄们的不朽致敬。它们提醒着每一位进入城市的人，为了保卫王国所付出的沉重代价。",al={"为什么在这里建造雕像","英雄谷的目的"}},{q="谁负责指挥驻守在入口处的卫兵？",a="暴风城卫军的总指挥官马库斯·乔纳森将军，在玛丁雷少校和斯托布里奇元帅等军官的协助下，直接在前线监督英雄谷的安保工作。",al={"卫兵队长","骑马的人是谁","谁负责指挥暴风城防御"}},{q="英雄谷通向哪里？",a="向北过桥可以直接进入暴风城繁华的贸易区，而向南走出大门则通往艾尔文森林的田园地带。",al={"桥通向哪里","暴风城门方向"}}},fx={f5acfed9={q="什么是英雄谷？",a="英雄谷是一片宏伟葱郁的入口区域，位于暴风城主城门前方。一座宽阔的石桥横跨艾尔文森林与城门之间的护城河，两侧矗立着纪念传奇英雄的高大雕像。对于从南方步行而来的人来说，这里是通往人类王国首都的宏伟门庭。",al={"什么是英雄谷","暴风城英雄谷","关于英雄谷"}},["5176beb8"]={q="英雄谷发生过什么？",a="第二次战争结束后，暴风城开始重建，这片山谷也被改造成一座永恒的纪念地。五座巨型雕像拔地而起，以纪念穿过黑暗之门、前往支离破碎的德拉诺世界封闭空间裂隙的联盟远征军。人们以为这五位指挥官永远留在了彼方，于是将他们雕刻成石像，永远铭记他们的牺牲。",al={"英雄谷历史","英雄谷传说","这里发生了什么"}},["7507c845"]={q="英雄谷危险吗？",a="不危险。英雄谷防守严密，是联盟首都的主要入口。这里由马库斯·乔纳森将军等高级军官看守，并有城市卫兵不断巡逻，是艾泽拉斯最安全的地方之一，联盟旅客可以放心通行。",al={"英雄谷安全吗","英雄谷危险吗","英雄谷的危险"}},["6b62f2c8"]={q="为什么叫英雄谷？",a="山谷的名字源于沿途矗立的巨大石像。每座雕像都刻画了一位前往德拉诺的联盟远征军领袖——图拉扬、奥蕾莉亚·风行者、卡德加、达纳斯·托尔贝恩和库德兰·蛮锤。他们为保护艾泽拉斯免受黑暗之门另一端的恶魔威胁，付出了一切。",al={"为什么叫英雄谷","英雄谷名称的起源","为何称为英雄谷"}}},fp="16,306,22.531.0,16.488.0,36.259.0,49.242.0,50.219.0,37.175.0"}
P.entries["subzone:valley-of-honor"] = {n="Valley of Honor",s="Valley of Honor是奥格瑞玛的武力核心和战士区，坐落在首都东北部的峡谷中。这里设有城市的兵营、战士和猎人公会，以及负责指挥艾泽拉斯各地部落军队的战场军官。这里有活跃的熔炉、训练场和静谧的水域，是部落磨砺力量、铭记尚武传统的地方。",h="Valley of...",kw={"兵营","战场军官","锻造","hall of the brave","诺格","奥格瑞玛","valley of honor"},ang={["class:Hunter"]="猎人大厅和野兽驯养场使这个山谷成为补充弹药、磨练射击技巧和安顿宠物同伴的必经之地。",["class:Warrior"]="Valley of Honor是你在奥格瑞玛的精神家园，这里不仅有Hall of the Brave、资深战斗教官，还有为部落前线锻造装备的护甲匠。"},sec={{t="部落力量的核心",b="Valley of Honor坐落于高耸的峡谷脊线之后，是奥格瑞玛主要的军事区。练习武器的碰撞声和铁匠铺铁砧的敲击声构成了这里日常生活的基调。Hall of the Brave坐落在山谷中，是经验丰富的战士和协调诸如奥特兰克山谷和战歌峡谷等前线战事的战场军官的聚集地。该区域两侧设有野兽控制者和猎人的训练设施，完全致力于装备、操练和动员部落的前线保卫者。"},{t="工艺、贸易与休憩",b="除了武器和演练场，该山谷还支持战争的后勤工作。炽热铁砧和红峡谷矿业供应护甲和粗铁，而工程师们则在附近的诺格的机器商店里忙碌。在履行职责的间隙，兽人和前来拜访的冒险者会向山谷中那片令人惊讶的静谧水池抛下鱼线，在远离Valley of Strength尘土飞扬的喧嚣中享受片刻的宁静。"}},faq={{q="Valley of Honor的用途是什么？",a="它是奥格瑞玛的军事和武力中心。这里有城市的兵营、战士和猎人训练师、武器匠，以及负责派遣士兵前往各大战场的战场军官。",al={"valley of honor用途","这里有什么","valley of honor里有什么"}},{q="我在奥格瑞玛哪里可以找到战场军官？",a="部落的战场军官驻扎在Valley of Honor的Hall of the Brave内。从那里，士兵们被征召并派往艾泽拉斯各地的冲突前线。",al={"战场军官位置","奥格瑞玛pvp","奥格瑞玛战场排队"}},{q="在Valley of Honor可以学习哪些专业？",a="山谷内有锻造、采矿和钓鱼的训练师及补给商人，还有在诺格的机器商店运营的地精工程学专家。",al={"valley of honor专业技能","这里的训练师","奥格瑞玛锻造"}}},fx={cbe73428={q="什么是荣誉谷？",a="荣誉谷是奥格瑞玛引以为傲的军事核心。它隐于城市东北部的峡谷之中，是一片崎岖的城区，设有城市兵营、勇士大厅和猎手大厅。战士与猎人会在此磨炼致命技艺，战场军官则召集勇士，前往艾泽拉斯各地的遥远战场一决高下。",al={"valley of honor","什么是荣誉谷","奥格瑞玛荣誉谷"}},["167ed7f9"]={q="荣誉谷里住着哪些人？",a="这里主要是部落的军事力量及为他们提供装备的工匠们的驻地。老兵、步兵新兵、猎人和驯兽师聚集在各处大厅与营房中。铁匠、矿工和工程师也在此工作，为部落的战争机器供应锋利的刀刃、坚固的板甲和弹药。",al={"荣誉谷住着谁","荣誉谷居民","谁管理荣誉谷"}},["6cb8ac9d"]={q="荣誉谷危险吗？",a="对于忠于部落的成员来说，荣誉谷是一座安全的堡垒，由城中最强大的勇士和士兵守卫。切磋大厅里战斗激烈，令人热血沸腾，但暴力严格限于训练和有组织的武艺试炼。可对于任何擅闯的酋长敌人而言，这里却是杜隆塔尔最致命的地方之一。",al={"荣誉谷危险吗","荣誉谷的危险","荣誉谷有什么危险"}}},fp="15,383,26.559.0,25.391.0,43.206.0,44.187.0,52.169.0"}
P.entries["subzone:valley-of-kings"] = {n="国王谷",s="国王谷是一座坐落在洛克莫丹西南角的郁郁葱葱的峡谷，位于通往丹莫罗的通道正南方。它是通往炽热的灼热峡谷的一处严加看守的关口，两侧耸立着为纪念三锤之战而雕刻的巨大石像。来到这里的旅行者在古老的矮人历史印记下穿行，同时也要面对黑石兽人和穴居人带来的直接威胁。",h="国王谷是一座坐落在洛克莫丹西南角的郁郁葱葱的峡谷，位于通往丹莫罗的通道正南方。它是通往炽热的灼热峡谷的一处严加看守的关口，两侧耸立着为纪念三锤之战而雕刻的巨大石像。来到这里的旅行者在古老的矮人历史印记下穿行，同时也要面对...",kw={"卡德罗斯·蛮锤","洛克莫丹","茉德拉·铜须","贝波蒂","灼热峡谷大门","国王谷","三锤之战"},ang={["faction:Alliance"]="峡谷是抵御南部荒地日益增长的威胁的北部屏障，阻止了灼热峡谷的阴燃危机蔓延到宁静的卡兹莫丹。",["race:Dwarf"]="对于铁炉堡的矮人来说，国王谷是神圣的土地，展示了铜须和蛮锤部族为对抗黑铁部族的背叛而铸就的牢不可破的纽带。"},sec={{t="南方隘口的守护者",b="峡谷中最引人注目的景观是那对高大的雕像，描绘的是茉德拉·铜须国王和蛮锤大领主卡德罗斯。在他们去世后，他们的儿子们联合下令雕刻了这些石像，这些石像俯瞰着通往南方焦土的隘口。它们作为三锤之战联盟胜利的永恒纪念碑，也是对黑铁部族的恒久警告，提醒所有向南望去的人，拉格纳罗斯的召唤给南部地区带来了怎样的浩劫。"},{t="通往灼热峡谷的大门",b="除了作为南门小径和碎石怪之谷之间的通道外，国王谷还设有一道通往灼热峡谷的重型铁门。由于另一侧潜伏着充满敌意的黑石兽人、黑铁矮人以及火山险境，这道大门一直处于严密封锁状态，并由铁炉堡巡山人守卫。巡山人贝波蒂在门槛处把守，拒绝除最强悍的冒险者以外的所有人，只有证明自己有能力在烈焰中生存下来的人才能通行。"}},faq={{q="这两座巨大的雕像代表了谁？",a="这两座巨大的雕像描绘的是铁炉堡的茉德拉·铜须国王和蛮锤大领主卡德罗斯。在他们去世后，他们的儿子们联合委托建造了这些纪念碑，以庆祝在三锤之战中取得胜利的联盟。",al={"国王谷雕像","洛克莫丹矮人雕像","雕像是谁"}},{q="为什么雕像要朝南建造？",a="它们被竖立在这里，直视着被黑铁部族召唤拉格纳罗斯所摧毁的南部领土。这两位国王像一道保护盾，同时也向黑铁部族以及任何试图入侵北方矮人领地的敌对势力发出了永恒的警告。",al={"雕像为何朝南","雕像的用途","面向灼热峡谷的雕像"}},{q="我该如何通过南端那道锁住的大门？",a="为了旅行者的安全，通往灼热峡谷的大门一直保持锁闭。你必须与守在大门处的巡山人贝波蒂交谈，并向她证明你的能力，完成她交代的任务后，她才会给你通过大门的钥匙。",al={"如何打开灼热峡谷之门","巡山人贝波蒂的钥匙","国王谷大门锁闭"}},{q="这座峡谷通向哪里？",a="这座峡谷连接着通往丹莫罗的南门小径、东面穴居人出没的碎石怪之谷，以及通过戒备森严的南门通往灼热峡谷的炽热荒地。",al={"国王谷的连接区域","峡谷通向哪里"}}},fx={["7c2b9610"]={q="国王谷是什么地方？",a="国王谷是一处郁郁葱葱的山间隘道，坐落在洛克莫丹西南角，就在碎石怪之谷以西。它是一条至关重要的通道，连接着经由南门小径往返于丹莫罗的旅人，以及南方灼热峡谷危机四伏、遍布火山的土地。",al={"洛克莫丹国王谷","国王谷是什么地方","国王谷介绍"}},["0960ad5d"]={q="国王谷发生过什么？",a="三锤之战造成毁灭性破坏，高王麦迪文·铜须与卡德罗斯·蛮锤也不幸身亡。此后，他们的儿子共同下令建造了谷中的两座巨大纪念碑。雕像凿刻在俯瞰南方隘道的峭壁上，永远纪念他们联手战胜巫师萨满索瑞森，以及他留下的焦土。",al={"国王谷的历史","这里为什么有雕像","国王谷背景故事"}},f059810f={q="谁控制着国王谷？",a="国王谷处于铁炉堡的主权管辖之下，由矮人巡山人巡逻。在通往南方灼热峡谷的南门，巡山人贝波蒂负责把守，确保只有证明过自己实力的老练冒险者才能开启沉重的大门，前往焦土。",al={"谁控制国王谷","谁管理国王谷","铁炉堡守卫国王谷"}},["960bcb2e"]={q="国王谷危险吗？",al={"国王谷的危险","这里安全吗","国王谷的威胁"}},["04615939"]={q="为什么叫国王谷？",a="这个名字源自两座凿刻在山壁上的巨大雕像，雕像描绘的是铁炉堡的高王麦迪文·铜须和格瑞姆巴托的国王卡德罗斯·蛮锤。他们的儿子共同竖起这两座高耸的雕像，以纪念父亲们在三锤之战中的领导功绩。",al={"为什么叫国王谷","国王谷名称由来","谁给国王谷命名"}}},fp="15,419,30.510.0,29.508.0,39.257.0,40.286.0,57.257.0,28.206.0"}
P.entries["subzone:valley-of-spears"] = {n="长矛谷",s="长矛谷是坐落于凄凉之地西部的一处崎岖峡谷，它是玛洛迪半人马氏族的大本营。峡谷四面环绕着陡峭的悬崖，并由多处隘口把守，直接通往半人马一族的神圣祖坟——玛拉顿。",h="长矛谷是坐落于凄凉之地西部的一处崎岖峡谷，它是玛洛迪半人马氏族的大本营。峡谷四面环绕着陡峭的悬崖，并由多处隘口把守，直接通往半人马一族的神圣祖坟——玛拉顿。",kw={"半人马","凄凉之地","玛洛迪","玛拉顿","梅丽萨","长矛谷"},ang={["faction:Alliance"]="联盟一直对该地区保持着警惕，尤其是在像侏儒梅丽萨这样的探险旅行者被敌对的玛洛迪氏族俘虏之后。",["race:Tauren"]="半人马的残暴世世代代困扰着卡利姆多的部落；在这个大本营中穿行，会让牛头人直面那种古老仇恨的核心。"},sec={{t="玛洛迪的大本营",b="长矛谷位于凄凉之地西部的崎岖高地之中，是玛洛迪氏族的大本营。该峡谷四面封闭，仅能通过南部和东部狭窄且易守难攻的山隘徒步进入，这为半人马提供了一道天然的堡垒。穿过这些岩石关隘的旅行者将会面临敌对游牧民族的重兵营地，他们守护着通往其最受尊崇的圣地的道路。"},{t="玛拉顿的入口",b="位于峡谷西南尽头的是玛拉顿的入口，那是一座神圣的洞穴，安葬着半人马之父Zaetar，也是Theradras公主居住的地方。正因为靠近这里，玛洛迪氏族对峡谷的防守极其狂热，无论是敌对氏族还是外来的闯入者，都会遭到他们的猛烈攻击。任何愚蠢到在毫无察觉的情况下闯入峡谷的人——比如粗心的侏儒制图师或侦察兵——通常都会被俘虏或杀害。"}},faq={{q="谁控制着长矛谷？",a="该峡谷是玛洛迪氏族的主要领地，他们是在凄凉之地争夺统治权的半人马派系之一。",al={"这里住着谁","长矛谷半人马氏族","玛洛迪据点"}},{q="长矛谷通向哪里？",a="在峡谷的西南尽头，就是玛拉顿的入口，那是半人马一族神圣的祖先洞穴和陵墓。",al={"如何前往玛拉顿","玛拉顿入口","长矛谷尽头有什么"}},{q="如何进入该峡谷？",a="峡谷被陡峭的山脊所环绕，只能通过东部和南部的狭窄山隘徒步进入。",al={"长矛谷入口","如何进入","通往长矛谷的隘口"}},{q="有人被困在峡谷里吗？",a="是的，一位名叫梅丽萨的倒霉侏儒被玛洛迪半人马俘虏，目前被关押在他们的营地里。",al={"梅丽萨","长矛谷中的俘虏","侏儒俘虏"}}},fp="16,264,27.419.0,25.457.0,34.130.0,37.139.0,28.136.0,32.131.0"}
P.entries["subzone:valley-of-spirits"] = {n="Valley of Spirits",s="Valley of Spirits依傍着奥格瑞玛的西侧峭壁，是暗矛巨魔在部落主城内长久以来的驻地。这里布满了茅草屋、提基图腾和宁静的水池，与周围岩石嶙峋、钢铁坚硬的兽人建筑风格形成了鲜明的对比。",h="Valley of Spirits依傍着奥格瑞玛的西侧峭壁，是暗矛巨魔在部落主城内长久以来的驻地。这里布满了茅草屋、提基图腾和宁静的水池，与周围岩石嶙峋、钢铁坚硬的兽人建筑风格形成了鲜明的对比。",kw={"darkbriar lodge","暗矛","奥格瑞玛","spirit lodge","talon gate","巨魔","valley of spirits"},ang={["profession:Herbalism"]="山谷中宁静的水道和专业的小屋使其成为城中向当地草药大师寻求智慧的主要中心。",["race:Troll"]="对于暗矛部族来说，这片宁静的飞地在兽人主城高耸的红色峡谷中，为他们提供了一处至关重要的家园和文化归属感。"},sec={{t="暗矛部族的家园",b="Valley of Spirits从繁忙的Valley of Strength向西延伸，是一块专门为暗矛巨魔开辟的郁郁葱葱且安静的飞地。当该部族随萨尔的兽人定居在杜隆塔尔时，这处岩石间的宁静之地便成了他们的城市聚居区。巨魔工匠、灵魂行者和施法者们聚集在木桥和蜿蜒的水道旁，在这里研习技艺，远离了主干道上的干热。"},{t="技艺的守护者",b="除了住宅和宁静的水池外，山谷中还汇聚了魔法和荒野技艺的修行者。巫医、草药师和施法者聚集在Spirit Lodge和Darkbriar Lodge等小屋中。靠后方的是Talon Gate，它直接通往贫瘠之地广阔的平原，为漫游者、猎人和游历于峡谷之外的旅行者提供了快捷的通道。"}},faq={{q="谁居住在Valley of Spirits？",a="这个山谷主要是随兽人定居在杜隆塔尔的暗矛巨魔的家园。你可以在此找到他们的工匠、精神领袖、草药师和猎人，他们生活在具有鲜明巨魔风格的小屋和雕刻精美的提基图腾之间。",al={"这里住着谁","valley of spirits居民","奥格瑞玛的巨魔"}},{q="Talon Gate通向哪里？",a="Talon Gate位于Valley of Spirits的后方，是奥格瑞玛的西出口。穿过它可直达怒水河流域和贫瘠之地的平原。",al={"talon gate出口","奥格瑞玛后门","valley of spirits大门"}},{q="这里有哪些服务和训练师？",a="Valley of Spirits设有草药学、烹饪以及各种荒野和魔法学科的训练师和商人，他们分布在Spirit Lodge和Darkbriar Lodge等著名建筑中。",al={"valley of spirits的训练师","valley of spirits有什么"}}},fx={cef16464={q="灵魂谷是什么地方？",a="灵魂谷是奥格瑞玛内一处狭长的区域，从中央的力量谷一直延伸到城市后方的猛禽之门。这里以热带风格的建筑、图腾和浅浅的水道为特色，是暗矛巨魔的文化中心与居住地，他们与兽人盟友一同生活在部落的首都中。",al={"灵魂谷是什么地方","奥格瑞玛灵魂谷","巨魔区域"}},["8d1b898f"]={q="灵魂谷有怎样的历史？",a="第三次战争结束后，奥格瑞玛建立之际，这片山谷被划给暗矛部族居住，他们当时加入了萨尔新建的部落。自首都建成以来，这里一直是巨魔萨满教、巫毒仪式和日常社区生活的中心，受到城市红色岩壁的庇护。",al={"灵魂谷的历史","灵魂谷发生过什么","灵魂谷背景故事"}},["210fd1e6"]={q="灵魂谷危险吗？",a="不，部落成员和中立访客在这里都十分安全。山谷由奥格瑞玛的哨兵和暗矛战士守卫，是一处居民区，提供庇护、贸易和精神指引，而非带来人身威胁。",al={"灵魂谷安全吗","灵魂谷的危险","灵魂谷的敌人"}}},fp="17,303,24.453.0,20.401.0,35.238.0,31.199.0,42.204.0"}
P.entries["subzone:valley-of-strength"] = {n="Valley of Strength",s="Valley of Strength是奥格瑞玛繁华的中心区域，迎接所有穿过这座城市高耸正门的人。这里设有城市银行、中央拍卖行和破碎獠牙旅店，是部落首都名副其实的商业和行政中心。",h="Valley of Strength是奥格瑞玛繁华的中心区域，迎接所有穿过这座城市高耸正门的人。这里设有城市银行、中央拍卖行和破碎獠牙旅店，是部落首都名副其实的商业和行政中心。",kw={"拍卖行","银行","破碎獠牙","杜隆塔尔","grommash hold","部落","奥格瑞玛","萨尔","valley of strength"},ang={["faction:Horde"]="作为奥格瑞玛大门内的主要广场，Valley of Strength是部落旅行者会面进行贸易和招募远征队的第一站。"},sec={{t="城市大门",b="穿过奥格瑞玛坚固的木制大门，你就进入了Valley of Strength。这座峡谷深深嵌入杜隆塔尔的红色岩石之中，是部落的前广场。来自各个盟友种族的冒险者、商人和战士们在这个尘土飞扬的广场上汇聚，在破碎獠牙旅店里一边畅饮一边交换战事传闻，或者在中央银行和拍卖行处理重要的贸易事宜。这里是兽人为在新家园中建立的力量与团结的繁荣见证。"},{t="贸易与指挥枢纽",b="除了防御意义外，该峡谷还是首都最重要的集市。诸如Soran's Leather and Steel Armory之类的商店出售护甲，而各种商贩则提供横穿贫瘠之地的长途跋涉所需的物资。步兵们在每个角落警惕地守卫着，为新来者指引方向，并确保在萨尔旗帜下寻求庇护的各族人民之间维持秩序。"}},faq={{q="什么是Valley of Strength？",a="它是奥格瑞玛的主要入口和中心峡谷，位于城市正门内侧。这里包含银行、拍卖行、杂货商和破碎獠牙旅店等基本的城市服务设施。",al={"valley of strength 概览","这是什么地方","奥格瑞玛入口区域"}},{q="Grommash Hold相对于这个峡谷位于何处？",a="Grommash Hold不在Valley of Strength内；它位于北部的智慧谷，是萨尔大酋长和部落高级指挥部的所在地。",al={"萨尔在哪里","grommash hold 位置","大酋长驻地"}},{q="我可以在这里找到什么服务？",a="该峡谷设有城市的主要银行、拍卖行、贸易物资、Soran's Leather and Steel Armory的护甲商、破碎獠牙旅店的住宿以及一般贸易商品。",al={"valley of strength 便利设施","valley of strength 商贩","这里有什么"}},{q="谁在守卫Valley of Strength？",a="峡谷由奥格瑞玛步兵严密巡逻，这些经验丰富的兽人战士维持着和平，保护进城的商队，并引导旅行者穿过这座迷宫般的峡谷城市。",al={"奥格瑞玛步兵","valley of strength 卫兵","城市防御"}}},fx={da94a7d4={q="力量谷危险吗？",a="对部落成员来说并不危险。作为奥格瑞玛繁忙的门户和商业中心，这里全天都有步兵和城市守卫严密巡查。这里真正的危险只有联盟大举进攻、攻破主城大门，或潜行者试图刺杀部落领袖。",al={"力量谷危险吗","力量谷的危险","力量谷安全吗"}},["007f5841"]={q="力量谷里住着谁？由谁管理？",a="力量谷是奥格瑞玛的公共中心，由酋长萨尔及其守卫管辖。旅人、银行职员和商贩在开放的街道上来来往往，而萨尔则在智慧谷的Grommash Hold处理政务。",al={"谁管理力量谷","力量谷居民","谁控制力量谷"}}},fp="18,289,21.508.0,24.385.0,31.222.0,55.164.0,30.183.0,34.180.0"}
P.entries["subzone:valley-of-the-watchers"] = {n="守卫之谷",s="守卫之谷坐落在塔纳利斯沙漠的遥远南部边缘，这是一座被烈日灼烧的峡谷，以其宏伟的石雕建筑而闻名。峡谷的尽头矗立着一座巨大的封闭石门，通往神秘的奥丹姆建筑群，由迟缓的巨人和古老的石质哨兵守护着。",h="守卫之谷坐落在塔纳利斯沙漠的遥远南部边缘，这是一座被烈日灼烧的峡谷，以其宏伟的石雕建筑而闻名。峡谷的尽头矗立着一座巨大的封闭石门，通往神秘的奥丹姆建筑群，由迟缓的巨人和古老的石质哨兵守护着。",kw={"沙尘粉碎者","卡利姆多","塔纳利斯","泰坦之门","泰坦","奥丹姆","守卫之谷"},ang={["race:Dwarf"]="对于矮人探险家和探险者协会的成员来说，这座巨大的石门代表了他们在寻找泰坦造物主的过程中，又一块令人垂涎的拼图。"},sec={{t="封闭的门槛",b="守卫之谷标志着塔纳利斯的流沙与大陆南部山区边缘交界的南端边界。峡谷中最为显眼的是一扇由古老石材打造的巨门，它紧紧关闭，将外界隔绝。人们相信这扇封闭的传送门守护着通往奥丹姆的入口，这是一个由神秘的泰坦建造的地下设施。巨大的沙尘粉碎者山岭巨人在布满尘土的入口附近徘徊，确保无论是旅行者、盗墓贼还是学者，都无法打扰深埋在沙土之下的秘密。"}},faq={{q="那扇巨大的石门后面是什么？",a="这座宏伟的门扉是通往奥丹姆的入口，这是一座古老的地下设施，由泰坦在凡人历史记录之前很久就已建造完成。目前，这里的机制依然完全封闭，使其真实的内容和目的成为了一个未解之谜。",al={"奥丹姆之门","奥丹姆是什么","门后有什么"}},{q="通往奥丹姆的大门能打开吗？",a="不能。那座巨大的石门完全无法通行。目前卡利姆多已知的任何凡人钥匙、咒语或力量，都无法绕过锁定该设施的泰坦防御机制。",al={"能打开奥丹姆之门吗","打开奥丹姆大门","如何进入奥丹姆"}},{q="为什么山谷里有巨人游荡？",a="被称为沙尘粉碎者的巨大山岭巨人在峡谷底部徘徊。它们被该地区强大的大地能量所吸引，凶猛地守护着入口，碾碎任何靠南部悬崖太近的冒险者。",al={"为什么会有沙尘粉碎者","山谷巨人","塔纳利斯山岭巨人"}},{q="这个山谷位于塔纳利斯的什么地方？",a="该山谷位于塔纳利斯的最南端，在灌木谷和南海断崖的巨大深渊以南，直接凿刻在高耸的南部山墙之中。",al={"守卫之谷位置","如何找到守卫之谷","大门在哪里"}}},fp="22,298,20.543.0,40.246.0,32.171.0,42.217.0,40.191.0"}
P.entries["subzone:valley-of-trials"] = {n="试炼谷",s="试炼谷隐藏在杜隆塔尔南部崎岖的红色悬崖之后，是部落新兵的试炼之地。年轻的兽人和他们的暗矛巨魔盟友来到这里，证明自己的实力，争取在卡利姆多的战士中赢得一席之地。那些在山谷严酷的野生动物和隐藏威胁中幸存下来的人，将准备好去保卫他们的新生家园。",h="试炼谷隐藏在杜隆塔尔南部崎岖的红色悬崖之后，是部落新兵的试炼之地。年轻的兽人和他们的暗矛巨魔盟友来到这里，证明自己的实力，争取在卡利姆多的战士中赢得一席之地。那些在山谷严酷的野生动物和隐藏威胁中幸存下来的人，将准备好去保...",kw={"火刃集会所","杜隆塔尔","高内克","兽人","苦工","萨科斯","大兽穴","试炼谷"},ang={["race:Orc"]="对于每一位寻求荣耀的年轻兽人来说，这座山谷象征着成人礼，在重建的家园中回响着德拉诺的战士传统。",["race:Troll"]="暗矛巨魔在回音群岛的家园被扎拉赞占领后，便在这个峡谷中与他们的兽人盟友并肩训练，以争取在部落中赢得一席之地。"},sec={{t="沙石的熔炉",b="试炼谷旨在将弱者淘汰出局，让他们甚至无法踏足杜隆塔尔的更广阔区域。年轻的战士们被派往烈日灼烧的峡谷中，在被称为大兽穴的崖壁避难所中，由酋长和训练师监督，他们需要猎杀蝎虫、捕杀具有攻击性的野猪，并督促那些采集稀缺木材的懒惰苦工。试炼是毫不妥协的：证明自己实力的人有权作为部落的真正士兵出发，而失败者则只能留在沙漠的烈日下暴尸荒野。"},{t="北方的阴影",b="这里曾经是一个与世隔绝的训练场，但最近却笼罩上了一层更加阴险的色彩。在北侧悬崖的天然洞穴中，火刃氏族的邪教徒已经扎下根来，将低阶恶魔仆从召唤到了山谷中。虽然训练师们将这些入侵者视为新兵的实战练习对象，但奥格瑞玛门前出现邪能魔法，这引发了黑暗的传言，称暗影议会正积极试图将魔爪重新伸向兽人。"}},faq={{q="试炼谷的目的是什么？",a="这是部落新兵（主要是年轻的兽人和暗矛巨魔）传统的试炼场。在新兵们被允许前往杜隆塔尔的其他地方之前，他们会在这些受到庇护的峡谷中完成严格的任务，以展示他们的战斗技巧、生存本能和忠诚。",al={"兽人为什么在这里","这里是什么地方","试炼谷的目的"}},{q="什么是大兽穴？",a="大兽穴是山谷中心地带凿刻在悬崖上的一个洞穴。这里有职业训练师、商人和像高内克这样的监工，他们负责指导新兵、为他们装备武器，并监督他们初步试炼的进度。",al={"大兽穴","试炼谷的洞穴","大兽穴里有什么人"}},{q="为什么新手训练场里会有恶魔？",a="属于火刃氏族的邪教徒在北部的洞穴中建立了一个秘密巢穴。虽然训练师们利用他们弱小的仆从去测试新兵，但邪教的存在表明，暗影议会等阴暗势力正在寻求在杜隆塔尔的家门口站稳脚跟。",al={"为什么试炼谷里有恶魔","杜隆塔尔的火刃氏族","北部洞穴的恶魔"}},{q="萨科斯是谁？",a="萨科斯是一只体型异常庞大且剧毒的蝎虫，居住在山谷岩石嶙峋的高处。由于它极具攻击性和致命性，导师们会指派有前途的新兵去猎杀它，以测试他们的勇气，并带回它那残缺的爪子作为证明。",al={"萨科斯背景故事","巨型蝎虫","萨科斯任务"}}},fx={["7f52c0d9"]={q="试炼谷是什么地方？",a="试炼谷是杜隆塔尔南部一处粗犷的峡谷试炼场。四周被高耸的红色峭壁环绕，这里是年轻兽人和暗矛巨魔证明自己、赢得在部落中一席之地的重要场所。新兵们在这里顶着烈日、身处崎岖的岩地，接受战斗、生存和纪律试炼，然后才会走出山谷，踏入更广阔的世界。",al={"我在哪里","这里是什么地方","试炼谷背景故事"}},["341e719f"]={q="为什么叫试炼谷？",a="这个名字源自山谷中严苛的成年礼。每个有志成为新兵的人，都必须通过与当地野兽和威胁交锋的危险试炼，证明自己的力量、决心以及对部落的忠诚。证明自己配得上资格的人会获准离开山谷，进入杜隆塔尔；那些未能通过、在尝试中倒下的人，则只能被遗弃在灼热的沙漠烈日之下。",al={"为什么叫试炼谷","试炼谷名称含义","试炼谷为什么这样命名"}},["5bae7ae4"]={q="试炼谷属于杜隆塔尔吗？",a="是的，它位于杜隆塔尔南部。杜隆塔尔本身是卡利姆多东海岸一片干燥多岩的土地，由萨尔建立，并以纪念他的父亲杜隆坦而命名。试炼谷是一处受保护的集结地，新兵们会在这里做好准备，再进入这片广阔疆域中更为严酷的荒野。",al={"这里属于杜隆塔尔吗","试炼谷属于杜隆塔尔吗","杜隆塔尔试炼谷"}},["9914b36c"]={q="这里由谁负责？",a="山谷中的试炼与训练由部落的老兵训练师和职业训练师负责。任务主管高内克指挥新来者并评估他们的进展，确保每个新手都向新部落证明自己的价值，之后才能前往杜隆塔尔更深处。",al={"谁领导试炼谷","谁管理试炼谷","这里谁说了算"}},aa4d1f31={q="高内克是谁？",a="高内克是一名兽人任务主管，驻扎在试炼谷的大兽穴正前方。他从新兵报到时起便负责监督他们，布置基础试炼来检验他们的实力、清剿野兽，并指引通过考验的战士和施法者前往各自的训练师处。",al={"高内克","高内克是谁","高内克负责什么"}},["4fde55c9"]={q="新部落是什么？",a="新部落是一个由不同文化组成的联盟，由酋长萨尔建立，奉行生存、荣誉与自由的原则。在危机四伏的世界中，各族凭借相互保护的盟约团结一心；兽人是其核心，暗矛巨魔和牛头人等盟友也加入其中，共同致力于创造一个摆脱恶魔腐化的未来。",al={"新部落","部落是什么","萨尔的部落"}},["3a67b133"]={q="兽人为什么如今住在沙漠里？",a="萨尔带领兽人逃离东部王国的人类囚禁，横渡无尽之海，来到卡利姆多，为他们开辟自己的家园。杜隆塔尔龟裂的红土、崎岖的峡谷和干旱酷热让兽人想起故乡德拉诺，也为他们提供了一片严酷而壮美、能让他们坚韧生存的土地。",al={"为什么是杜隆塔尔","兽人为什么在沙漠里","兽人为什么定居杜隆塔尔"}},e4c91867={q="为什么我的巨魔会从兽人营地开始？",a="暗矛部族能存活下来，全靠萨尔的帮助；在他们为前往卡利姆多而离开故土时，萨尔曾协助营救他们。出于感激与友谊，年轻的暗矛巨魔与兽人新兵在试炼谷并肩训练，以证明他们同心效忠部落。",al={"巨魔为什么从试炼谷开始","巨魔起始区域","巨魔为什么和兽人在一起"}},["3629ab9f"]={q="暗矛部族发生了什么？",a="暗矛部族在与鱼人和一名海巫战斗后，被迫离开无尽之海上的祖居群岛。随后，暗矛部族追随萨尔来到卡利姆多，并在杜隆塔尔海岸外的回音群岛定居。然而，巫医扎拉赞的背叛以及人类势力的袭击将他们赶出了群岛，迫使他们迁至杜隆塔尔大陆上的森金村。",al={"暗矛部族历史","暗矛部族发生了什么","暗矛部族与回音群岛"}},["9ca718af"]={q="火刃氏族是什么人？",a="火刃氏族是一个与恶魔腐化以及背信弃义的暗影议会低语有关的黑暗教派。他们的术士和追随者不寻求在萨尔的部落中以荣誉立足，而是勾结邪能，图谋危害杜隆塔尔的安宁。",al={"火刃氏族","火刃氏族是什么人","火刃教派"}},d2b83034={q="火刃氏族为何会出现在山谷中？",a="该教派的成员秘密迁入山谷北侧峭壁沿线的天然洞穴群，如今那里被称为火刃集会所。在术士亚罗格·暗影灾星的带领下，他们的存在使恶魔小鬼涌入训练场，考验着那些必须在离开前铲除腐化的新兵。",al={"火刃氏族为何在这里","试炼谷的火刃氏族","他们为何在集会所"}},["3ff6b15f"]={q="森金村是什么地方？我为什么要被派去那里？",a="森金村是暗矛巨魔在杜隆塔尔南岸暗矛海滩建立的聚居地。扎拉赞夺取回音群岛后，沃金在此建立了村庄。这里是部族的集结据点；而当你证明自己有资格离开试炼谷后，这里自然就是你的目的地。",al={"森金村","为何去森金村","森金村是什么地方"}},b9026890={q="我是怎么来到试炼谷的？",a="你来到这里，是为了接受考验。试炼谷隐于杜隆塔尔南部的峭壁之间，是部落新兵的试炼场。无论你是出于责任感、部族传统，还是为族人而战的强烈愿望，凡是想要效力于萨尔领地的人，都必须先勇闯这条干旱的峡谷。你徒步来到此地，向大兽穴的招募者和工头报到，开始自己的成年礼。",al={"我是怎么来到这里的","我是怎么到这里的","我为什么在这里醒来"}},f72f3f76={q="我在试炼谷应该做些什么？",a="你来此是为了证明自己的力量，赢得在部落中的一席之地。在烈日炙烤下，工头高内克和山谷中的导师要求你通过猎杀当地野兽、收集重要物资以及磨练战斗技艺来锤炼自己。最后，你必须面对北方洞穴中日益滋长的腐化。待导师们认定你有能力在杜隆塔尔的险境中生存下来，你便获准穿过北门，深入前方的荒野。",al={"我在这里该做什么","我在这里做什么","我为什么在这里"}},["5263efa6"]={q="为什么新来的兽人会从试炼谷开始？",a="对兽人而言，来到试炼谷是成年礼中不可或缺的一环。在萨尔以尘土开辟、并以其父亲杜隆坦之名命名的新家园里，古老传统以新的形式延续着。每一位有志成为战士的兽人都必须接受这些考验，证明自己拥有荣誉、纪律和战斗准备，然后才能加入守卫奥格瑞玛的步兵，或在边境巡行。你被派到这里，是为了证明自己拥有保卫新部落所需的精神。",al={"兽人为何从这里开始","兽人为何在山谷中","兽人为何从试炼谷开始"}},["576a24aa"]={q="为什么新来的巨魔会从试炼谷开始？",a="你的族人暗矛部族最近遭受了沉重的背叛。你们被叛徒扎拉赞及其被诅咒的爪牙赶出回音群岛的家园，幸存者聚集在森金村一带的海岸上。由于没有自己的合适试炼场，你们的酋长沃金依靠与萨尔的盟约，将满怀热忱的暗矛青年派到杜隆塔尔的山谷，与兽人一同接受考验。在这条严酷的峡谷中证明自己的力量，能让你为部落效力，并最终帮助夺回家园。",al={"巨魔为何从这里开始","巨魔为何在兽人营地","我作为巨魔为何在这里"}}},fp="16,385,28.558.0,23.490.1,44.300.0,16.231.0,53.276.1,15.251.0"}
P.entries["subzone:valor-s-rest"] = {n="勇士之墓",s="勇士之墓是位于希利苏斯东部边缘的一处小型前哨站和墓地。这里由塞纳里奥议会的成员守卫，是旅者从安戈洛环形山进入这片风沙肆虐的荒原时所能见到的第一处避难所。",h="勇士之墓是位于希利苏斯东部边缘的一处小型前哨站和墓地。这里由塞纳里奥议会的成员守卫，是旅者从安戈洛环形山进入这片风沙肆虐的荒原时所能见到的第一处避难所。",kw={"营地","塞纳里奥议会","墓地","希利苏斯","安戈洛环形山","勇士之墓"},ang={["class:Druid"]="作为一个由塞纳里奥议会维持的前哨站，勇士之墓代表了你们组织对南方沙漠中邪恶动向的警惕守望。",["faction:Alliance"]="虽然规模不大，并且在塞纳里奥的中立原则下与部落共享，但勇士之墓在从安戈洛的荒野中走出时，提供了一个受欢迎的首个避难所。"},sec={{t="沙丘之门",b="勇士之墓坐落在希利苏斯的东部边界，沿着从安戈洛环形山下来的坡道，它是通往这片荒凉边境的门户。作为由塞纳里奥议会维持的中立据点，该营地接待了那些敢于闯入这片干旱荒原的联盟和部落成员。其显眼的墓地时刻提醒着人们沙漠中潜伏的危险，那里昆虫般的恐怖生物和古老的威胁考验着即使是最坚韧的探险队。"}},faq={{q="勇士之墓位于何处？",a="勇士之墓坐落于希利苏斯的东部入口处。当你沿着从安戈洛环形山西北角通往沙漠的道路向上行走时，它是你所遇到的第一个定居点。",al={"勇士之墓位置","如何找到勇士之墓","勇士之墓在哪里"}},{q="谁控制着勇士之墓？",a="该前哨站由塞纳里奥议会维持。作为研究并守卫该地区的中立看守者，他们允许联盟和部落的旅行者使用这个营地。",al={"谁管理勇士之墓","勇士之墓阵营","希利苏斯的塞纳里奥议会营地"}},{q="这个营地有什么显著特征？",a="勇士之墓最显著的特征就是它的墓地，这里安葬着那些被无情的沙漠及其不断侵蚀的昆虫类居民所夺去生命的人。",al={"勇士之墓的墓地","勇士之墓有什么"}},{q="勇士之墓周围的野生动物安全吗？",a="虽然它作为前哨站运作，但营地周围的区域仍会受到常见的昆虫侵扰，这也是希利苏斯深处潜伏着虫群的早期预警。",al={"勇士之墓安全吗","勇士之墓是否受到攻击"}}},fp="12,240,20.489.0,30.203.0,26.171.0,41.165.0,51.188.0"}
P.entries["subzone:valormok"] = {n="瓦罗莫克",s="瓦罗莫克是部落建立在艾萨拉崎岖西北部的一个偏远哨站。它位于哈达尔营地以北，这个饱受风霜的定居点是侦察兵和冒险者勇闯沿海被诅咒的古老遗迹时的补给站。",h="瓦罗莫克是部落建立在艾萨拉崎岖西北部的一个偏远哨站。它位于哈达尔营地以北，这个饱受风霜的定居点是侦察兵和冒险者勇闯沿海被诅咒的古老遗迹时的补给站。",kw={"ag'tor bloodfist","艾萨拉","贝尔戈洛姆·石槌","飞行管理员","jediga","大法师雷姆托里","瓦罗莫克"},ang={["faction:Horde"]="瓦罗莫克是部落冒险者在艾萨拉危险遗迹中穿行时的主要庇护所，提供飞行管理员和复仇任务。",["race:Orc"]="对于远离奥格瑞玛的驻守兽人来说，这座哨站不仅是对耐力的严酷考验，更是他们因荣誉而必须为背叛的族人复仇的见证。"},sec={{t="危险的立足点",b="瓦罗莫克坐落在艾萨拉秋意盎然的树林中，代表了部落对这片充满敌意且几乎被遗弃的土地所持有的试探性关注。这里的生活凄凉且危机四伏；营地防御薄弱，时刻暴露在附近的萨特、纳迦和徘徊的野兽威胁之下。尽管困难重重，驻守在此的战士们依然坚守阵地，作为连接奥格瑞玛与卡利姆多北部荒野的关键飞行枢纽和前哨堡垒。"},{t="背叛与报复",b="这个营地最近遭遇了一场毁灭性的背叛。贝尔戈洛姆·石槌最初派遣部落战士协同一位名叫大法师雷姆托里的血精灵前往遗迹，搜寻古代宝藏和强大的神器。雷姆托里却对护卫反戈相向，屠杀了战士们以将神器据为己有。在Ag'tor Bloodfist的带领下，瓦罗莫克的幸存者们正密谋向雷姆托里及其盘踞在附近萨拉斯营地的党羽复仇。"}},faq={{q="瓦罗莫克是什么？",a="瓦罗莫克是位于艾萨拉西北部的一个孤立的部落定居点。它提供了关键的飞行点连接，并作为部落旅行者探索古老沿海荒野的行动基地。",al={"瓦罗莫克 艾萨拉","这个营地是什么","艾萨拉的部落基地"}},{q="谁在领导这个营地？",a="该哨站由Ag'tor Bloodfist负责，这位兽人战士的任务是维持部落的立足点，并为他牺牲的战友复仇。",al={"谁是负责人","瓦罗莫克领导者","ag'tor bloodfist"}},{q="为什么这么多部落战士在这里丧生？",a="贝尔戈洛姆·石槌曾派遣战士护送血精灵大法师雷姆托里搜寻神器。雷姆托里背叛并屠杀了她的护卫，试图将艾萨拉的力量和财富据为己有，导致驻军严重减员。",al={"卫兵发生了什么事","瓦罗莫克大屠杀","雷姆托里背叛"}},{q="这里的飞行管理员可以通往哪里？",a="瓦罗莫克的双足飞龙管理员提供横跨卡利姆多的直飞航线，包括前往奥格瑞玛、雷霆崖、十字路口、碎木岗哨、血毒岗哨和永望镇的路线。",al={"瓦罗莫克飞行路线","从瓦罗莫克可以飞往哪里"}}},fp="8,262,21.473.0,25.457.1,17.213.0,25.151.0,44.241.0,40.190.0"}
P.entries["subzone:vault-of-ironforge"] = {n="Vault of Ironforge",s="Vault of Ironforge是这座矮人首府的主要银行和金库。它坐落在熙熙攘攘的平民区，正对着拍卖行，是联盟各地的市民和旅行者安全存放财富的核心枢纽。该金库由Dinita和受人尊敬的Stonemantle家族共同管理。",h="Vault of...",kw={"dinita","铁炉堡","铁炉堡银行","stonemantle","平民区","vault of ironforge"},ang={["faction:Alliance"]="金库位于城市拍卖行的正对面，是联盟贸易的基石，让冒险者们能够有充足的资金和补给。",["race:Dwarf"]="对于矮人来说，这座金库关乎山丘的尊严，象征着坚不可摧的安全性以及守护矮人财富的持久声誉。"},sec={{t="矮人商业的核心",b="Vault of Ironforge深深嵌入平民区的山岩之中，是矮人财政安全和精湛工艺的象征。随着城市贸易的兴旺，游客、士兵和商人们每天都会聚集于此，在城市卫兵和柜员的严密注视下存入钱币、遗物和物资。该机构由Dinita和值得信赖的Stonemantle家族负责，为联盟的顾客提供了绝对的安心保障。"}},faq={{q="Vault of Ironforge有什么用？",a="该金库是铁炉堡市的中央银行和保险库。市民和联盟的旅行者都依靠它将金币、装备和珍贵财物安全地保存在这厚重的山岩石墙之内。",al={"金库用途","铁炉堡银行","这是什么地方"}},{q="谁在经营这家银行？",a="该设施由Dinita和Stonemantle家族的成员共同维护，他们负责为来访者管理存款、交易和存储事宜。",al={"银行职员","谁经营金库","stonemantle家族"}},{q="金库位于哪里？",a="你可以在铁炉堡的平民区找到它，它就坐落在繁华的城市拍卖行广场对面。",al={"金库位置","铁炉堡银行在哪里","如何找到金库"}}},fx={["84f84a05"]={q="铁炉堡金库是什么地方？",al={"铁炉堡金库是什么地方","铁炉堡银行背景","vault of ironforge"}},["45fc2a88"]={q="铁炉堡金库危险吗？",a="对联盟的旅行者而言，一点也不危险。金库位于城市公共区的中心地带，守卫森严，并受到铁炉堡全体城防卫兵的保护。除非敌对的部落势力胆敢突袭山腹，否则这里仍是王国中最安全的场所之一。",al={"铁炉堡金库安全吗","铁炉堡银行有危险吗","金库安全吗"}},ef86fb6b={q="为什么叫铁炉堡金库？",a="它的名字源自其用途和堡垒般的结构。这座宏伟的城市宝库建成后，便成为一处宽敞的大厅，并经过加固，在山体坚实的岩石之下守护财富与圣物，因此它是矮人王国名副其实的金库。",al={"为何称作金库","铁炉堡金库名称由来","铁炉堡金库名称"}}},fp="18,358,25.425.0,40.231.0,22.142.0,27.130.0"}
P.entries["subzone:venomweb-vale"] = {n="毒蛛峡谷",s="毒蛛峡谷是位于提瑞斯法林地东部的一处阴暗山谷，坐落在血色修道院的正南方。这里曾经是一片猎物众多的茂密林地，但如今已沦为被极具攻击性的剧毒蛛形生物所占据的枯萎巢穴。",h="毒蛛峡谷是位于提瑞斯法林地东部的一处阴暗山谷，坐落在血色修道院的正南方。这里曾经是一片猎物众多的茂密林地，但如今已沦为被极具攻击性的剧毒蛛形生物所占据的枯萎巢穴。",kw={"桑德斯中尉","血色营地","斯瑞斯库克","提瑞斯法林地","毒蛛峡谷"},ang={["race:Undead"]="前往血色修道院的被遗忘者旅人必须同时应对斯瑞斯库克蛛群的致命毒素，以及北部桑德斯中尉麾下十字军的警惕巡逻。"},sec={{t="一处被腐蚀的避难所",b="在瘟疫吞噬洛丹伦之前，这座山谷曾是一片长满青草和葱郁树木的宁静之地，深受当地猎人青睐，常有猎人在此追踪鹿和兔子。如今，腐朽和蔓延的阴霾笼罩着这片土地。巨大的毒蛛在树木和洼地间成群结队，由可怕的蛛形生物斯瑞斯库克所统领。山谷的北缘与血色十字军的领地接壤，在桑德斯中尉的驻地——血色营地附近，经常有黑暗猎犬徘徊。"}},faq={{q="为什么毒蛛峡谷里有这么多蜘蛛？",a="这座山谷曾经是猎捕鹿和兔子的天堂，但现在却变成了一个被致命蜘蛛占据的受污染之地，由可怕的斯瑞斯库克领导。它们致命的蛛网和毒液是这座山谷得名的由来。",al={"毒蛛峡谷蜘蛛起源","为什么有这么多蜘蛛","谁制造了这些蜘蛛"}},{q="谁统领着山谷里的蛛形生物？",a="蜘蛛群由一只巨大而致命的蛛形生物斯瑞斯库克所领导，它潜伏在山谷枯萎的树冠下，在阴暗的洼地中游荡。",al={"毒蛛峡谷蜘蛛首领","斯瑞斯库克","提瑞斯法蜘蛛领袖"}}},fx={c3248b05={q="毒蛛峡谷是什么地方？",a="毒蛛峡谷是提瑞斯法林地东部一片广阔的荒芜山谷，就在血色修道院以南。这里曾是鹿兔成群的茂密林地，如今已衰败成一片阴暗有毒的洼地，盘踞着凶猛的蜘蛛和四处游荡的野兽；附近还有戒备森严的血色十字军巡逻队。",al={"毒蛛峡谷是什么地方","毒蛛峡谷信息","介绍毒蛛峡谷"}},a3685aae={q="毒蛛峡谷过去发生过什么？",a="在瘟疫污染洛丹伦之前，这片山谷曾是树木葱郁、绿草如茵的宁静乐土，深受追踪鹿与兔的猎人喜爱。王国覆灭后，这里成了受污染之地，遍布毒蜘蛛，而它们由斯瑞斯库尔统领，山谷也因此得到了如今的名字。",al={"毒蛛峡谷历史","毒蛛峡谷发生了什么","毒蛛峡谷的历史"}},["266d3ee0"]={q="谁生活在毒蛛峡谷？",a="没有文明种族居住在山谷深处。这里完全被毒蜘蛛占据，它们听命于蛛后斯瑞斯库尔，此外还有游荡的黑暗犬。在山谷北缘，血色十字军在桑德斯中尉的指挥下驻守着一处武装据点，名为血色营地。",al={"谁住在毒蛛峡谷","毒蛛峡谷的居民","谁控制毒蛛峡谷"}},f69dc1ca={q="毒蛛峡谷为何变成了废墟？",a="洛丹伦覆灭时，荒芜之力蔓延至林地，树木枯萎，草地凋零。斯瑞斯库尔率领的可怕毒蜘蛛席卷了山谷，再无人能够制止它们，如今蛛群已将这片曾经绿意盎然的乐土吞噬殆尽。",al={"毒蛛峡谷为何荒废","是什么毁了毒蛛峡谷","毒蛛峡谷的腐化"}},f71a1b3a={q="毒蛛峡谷危险吗？",a="是的，对粗心的旅行者而言，这里极其危险。致命的毒蜘蛛在山谷荒芜的树林中筑巢，在斯瑞斯库尔的阴影下伏击猎物。此外，凶猛的黑暗犬在北部边界游荡，而血色十字军的狂热分子会袭击任何接近营地的人。",al={"毒蛛峡谷危险吗","毒蛛峡谷的危险","毒蛛峡谷中的威胁"}},["7b7f7008"]={q="为什么叫毒蛛峡谷？",a="这片山谷得名于遍布其间的巨型蜘蛛，它们在树木间结下浓密的毒网。这片林地曾是一处无名的乐土；在致命的蜘蛛占据整个盆地后，旅行者和当地人便开始称它为毒蛛峡谷。",al={"为何叫毒蛛峡谷","毒蛛峡谷名称含义","毒蛛峡谷如何得名"}}},fp="13,233,17.469.0,47.217.0,36.143.0"}
P.entries["subzone:venture-co-base-camp"] = {n="风险投资公司营地",s="风险投资公司营地隐藏在北荆棘谷茂密的丛林中，是这个臭名昭著、贪婪成性的地精集团的前哨基地。在这里，受雇的监工和劳工们对这片葱郁的荒野进行着掠夺，他们致力于伐木、猎杀当地野生动物，并从附近的水道中开采珍贵的翻滚晶体。",h="风险投资公司营地隐藏在北荆棘谷茂密的丛林中，是这个臭名昭著、贪婪成性的地精集团的前哨基地。在这里，受雇的监工和劳工们对这片葱郁的荒野进行着掠夺，他们致力于伐木、猎杀当地野生动物，并从附近的水道中开采珍贵的翻滚晶体。",kw={"地精木材","工作中心","荆棘谷","翻滚晶体","风险投资公司营地","荆棘谷地精"},ang={["class:Druid"]="荆棘谷地精代表着肆无忌惮的工业破坏，为了粗糙的机械企业而撕裂原始的丛林栖息地，扰乱了当地的自然平衡。",["profession:Mining"]="该营地是丛林勘探的工业枢纽，公司勘探员在此搜寻原材料和稀有的翻滚晶体。"},sec={{t="工业扩张",b="荆棘谷地精在艾泽拉斯臭名昭著，以冷酷无情的牟利手段和对自然世界的彻底蔑视而闻名。在这个丛林营地里，蒸汽动力设备和地精临时搭建的棚屋正在啃噬着古老的树冠。营地由武装雇佣兵、工头和现场工人守卫，负责协调整个周边山谷的资源开采，并特别关注附近发现的珍贵翻滚晶体，同时铲平阻挡他们去路的任何丛林。"}},faq={{q="荆棘谷地精在荆棘谷做什么？",a="荆棘谷地精是一个投机取巧的采矿、伐木和工程集团。在北荆棘谷，他们设立了营地，旨在砍伐茂密的丛林，建立重型作业设施，并开采宝贵的矿藏——其中最主要的就是在当地水道附近发现的翻滚晶体。",al={"地精为什么在这里","风险投资公司目的","荆棘谷地精荆棘谷"}},{q="这里的地精与藏宝海湾的热砂港有关联吗？",a="没有。荆棘谷地精是一个独立的掠夺性企业，与大财主里维加兹和热砂港完全不同。与藏宝海湾那些培养互利贸易关系的商业亲王不同，荆棘谷地精依靠冷酷的剥削，并且对任何干涉他们利益的人都表现出敌意。",al={"风险投资公司是藏宝海湾的吗","他们对藏宝海湾友好吗","风险投资公司热砂港"}},{q="营地外还有什么？",a="营地旁边是风险投资公司工作中心，这是一个根基更深的前哨站，容纳了重型伐木设备、木材补给，以及指挥区域性皆伐工作的公司高级经理。",al={"这个营地通向哪里","营地附近有什么","风险投资公司工作中心"}}},fp="21,365,23.487.0,56.301.0,74.338.0,31.230.0"}
P.entries["subzone:venture-co-mine"] = {n="风险投资公司矿洞",s="风险投资公司矿洞位于莫高雷的东部悬崖中，是由贪婪的荆棘谷地精非法开采的工业矿坑。尽管遭到了牛头人的拒绝，荆棘谷地精还是强行挖掘了山丘，威胁到了平原的自然平衡。",h="风险投资公司矿洞位于莫高雷的东部悬崖中，是由贪婪的荆棘谷地精非法开采的工业矿坑。尽管遭到了牛头人的拒绝，荆棘谷地精还是强行挖掘了山丘，威胁到了平原的自然平衡。",kw={"费兹斯普罗基特","地精","莫高雷","被破坏的货车","拉兹敦","伐木机","石牛湖","风险投资公司矿洞"},ang={["profession:Engineering"]="穿过矿洞并越过较高的伐木空地，潜伏着修补匠特维兹威克·齿轮研磨器，他愿意在避开公司窥探目光的情况下分享机械制作的秘密。",["race:Tauren"]="这座矿洞是对大地之母的深深侮辱，给部落誓死守护的祖传山谷带来了煤烟、噪音和鲁莽的创伤。"},sec={{t="不请自来的工业",b="当荆棘谷地精试图寻求开采莫高雷矿产的权利时，牛头人断然拒绝了他们。这个企业集团无视了他们的反对，在工头费兹斯普罗基特的指挥下，依然在东部的山墙上开凿出了深邃的隧道。他们庞大的综合设施有三个入口——一个由雇佣兵把守的地面隧道、一个陡峭的悬崖观景点，以及一条通往小型伐木营地的上层通道。不断扩张的机器、烟雾和矿渣堆，是对这片圣地的公然亵渎。"},{t="扩张的野心",b="采矿只是该集团的开局。内部文件显示，莫古尔·拉兹敦和荆棘谷地精董事会鼓励费兹斯普罗基特进一步扩大规模，开展全面的木材采伐，并承诺提供先进的“地精伐木机”来清理连绵的山丘。虽然牛头人斥候突袭并烧毁了石牛湖附近的一支企业补给车队以阻挠他们的扩张，但打捞队立刻被派去回收货物。为了阻止这种破坏，部落已经转而直接针对矿坑的监工进行报复。"}},faq={{q="为什么地精要在莫高雷采矿？",a="荆棘谷地精曾试图请求在莫高雷开采矿产，但遭到了牛头人的拒绝。由于不愿尊重当地的领土主张或环境平衡，该集团在未经许可的情况下，将工人和机械潜入东部悬崖，大肆掠夺这些山丘。",al={"为什么这里会有地精","风险投资公司莫高雷原因","谁经营着矿洞"}},{q="谁负责这个采矿点？",a="工头费兹斯普罗基特在主入口内的岗位上监督着荆棘谷地精在莫高雷的所有行动。他直接听命于公司的执行董事会和莫古尔·拉兹敦。",al={"矿洞老板","谁领导着矿洞","工头费兹斯普罗基特"}},{q="湖边的补给车队发生了什么事？",a="牛头人斥候在石牛湖的北岸附近伏击并放火烧毁了一支荆棘谷地精的补给车队，以阻止机械进入矿洞。地精们迅速派出了打捞队，在烧焦的残骸中搜寻并回收他们的货物。",al={"被破坏的货车故事","石牛湖货车","谁烧了货车"}},{q="地精还打算在这里建造什么？",a="除了为了矿石而掏空悬崖外，内部通讯还揭露了他们计划建造一座伐木场，并部署伐木机来砍伐莫高雷的树木，以获取额外的企业利润。",al={"荆棘谷地精计划","莫高雷地精伐木机","伐木营地计划"}}},fx={["082f8142"]={q="风险投资公司矿洞是什么地方？",a="这是一处深入莫高雷东部峭壁的大型矿坑。风险投资公司未经许可便在此开采，在牛头人的家园内建立了非法的工业据点。矿区设有由地精主管看守的主入口、沿峭壁延伸的通道，以及一处通往小型伐木场的上层出口。",al={"风险投资公司矿洞","风险投资公司矿洞是什么","莫高雷矿洞"}},["55edfc51"]={q="风险投资公司矿洞发生过什么？",a="牛头人断然拒绝授予风险投资公司在莫高雷的采矿权后，这个财团无视他们的决定，执意开挖。牛头人斥候随后反击，在石牛湖附近袭击并焚毁了一支重要的补给车队。血蹄村的长老们因神圣的祖地遭到破坏而愤怒不已，已组织多次突袭矿洞，准备将入侵者赶出去。",al={"风险投资公司矿洞历史","这里发生了什么","风险投资公司矿洞背景"}},a93a58cf={q="风险投资公司矿洞危险吗？",a="是的。矿道里挤满了全副武装的地精打手、劳工和工程师，他们会拼命保护自己的非法矿权。风险投资公司的守卫发现入侵者后会立即开枪；而穿行于曲折、多层的矿道中，意味着你将直接暴露在这群冷酷无情的工人火力之下。",al={"风险投资公司矿洞危险吗","风险投资公司矿洞的危险","风险投资公司矿洞的威胁"}},caf6f18d={q="为什么叫风险投资公司矿洞？",a="它的名称直接源自经营此地的臭名昭著的地精团伙：荆棘谷地精。在莫古尔·拉兹敦的远程指挥下，这家冷酷无情的企业对当地的主权和环境保护毫不在意，还以公司名号为其非法挖掘活动招牌。",al={"风险投资公司矿洞为何得名","风险投资公司矿洞名称含义","荆棘谷地精名称"}}},fp="16,280,17.506.0,19.546.1,34.290.0,37.192.0,48.266.0,44.184.0"}
P.entries["subzone:vice"] = {n="罪恶谷",s="罪恶谷是逆风小径上一片崎岖荒凉的区域，坐落于通往卡拉赞的道路旁。这里是逆风食人魔的领地，他们在严酷孤寂的土地上维持着粗陋的土墩和零星的营地。过往的旅人必须同时应对他们野蛮的暴力和令人惊讶的暗影魔法造诣。",h="罪恶谷是逆风小径上一片崎岖荒凉的区域，坐落于通往卡拉赞的道路旁。这里是逆风食人魔的领地，他们在严酷孤寂的土地上维持着粗陋的土墩和零星的营地。过往的旅人必须同时应对他们野蛮的暴力和令人惊讶的暗影魔法造诣。",kw={"逆风食人魔","逆风小径","逆风术士","卡拉赞","食人魔土墩","罪恶谷"},ang={["class:Mage"]="食人魔驻扎在通往卡拉赞的直接道路上，这让肯瑞托不禁怀疑，麦迪文之塔的残留能量是否正在影响当地的野兽和部族。",["class:Warlock"]="居住在罪恶谷的逆风食人魔展现出了对黑暗魔法出人意料的精通，这表明即使是与世隔绝的野蛮氏族也能接触到腐蚀性的邪能。"},sec={{t="一座荒凉的据点",b="罪恶谷延伸在逆风小径的南部，遍布贫瘠的土地、嶙峋的岩壁，以及逆风食人魔氏族筑起的粗陋土墩。虽然周围的峡谷大多被复仇的幽灵和食腐秃鹫占据，但这些食人魔在通往卡拉赞的主路旁强行开辟出了一处据点。他们为何选择这样一片凄凉且充满魔法伤痕的废土，至今仍是个未解之谜，但任何往来于暮色森林和悲伤沼泽的旅人都很快会发现，他们会以凶猛的领地意识捍卫自己的营地。"},{t="蛮力与黑暗技艺",b="与一般的拦路强盗不同，居住在罪恶谷的食人魔不仅拥有强大的武力，还掌握着危险的奥术天赋。在魁梧的打手身边，逆风术士们在土墩间练习着粗陋却致命的邪能法术。他们出现在麦迪文的废弃宅邸附近，似乎暗示着他们对残留魔法力量的渴望，这使得峡谷成为了流浪学者和独行斥候的致命关卡。"}},faq={{q="什么是罪恶谷？",a="罪恶谷是逆风小径南部的一个崎岖子区域，其特征是完全由逆风食人魔控制的土墩、零星的篝火和岩石峡谷。",al={"罪恶谷 逆风小径","什么是罪恶谷","罪恶谷 区域 逆风小径"}},{q="为什么食人魔住在这里？",a="没有人确切知道食人魔为何选择定居在这片环境恶劣、闹鬼的峡谷中。他们的术士可能是被附近卡拉赞散发出的残留奥术余波所吸引，又或许只是利用这条偏僻的山路来捕猎过往的旅人。",al={"为什么食人魔在逆风小径","逆风食人魔动机","为什么食人魔在罪恶谷"}},{q="穿过罪恶谷的道路通向哪里？",a="穿过罪恶谷的小径蜿蜒深入逆风小径南部的岩峰，直通守护者麦迪文的废弃之塔——卡拉赞那阴森的大门。",al={"罪恶谷 道路终点","道路通向哪里","穿过罪恶谷的小径"}},{q="旅人在罪恶谷会遇到什么危险？",a="旅人会遇到在路上巡逻并捍卫其土墩的侵略性逆风食人魔。除了体格魁梧的打手外，该氏族还包括使用诅咒和暗影魔法的危险术士。",al={"罪恶谷 威胁","罪恶谷中的敌人","罪恶谷中什么会攻击你"}}},fp="4,362,21.584.0,25.419.0,17.170.0,30.270.0,42.183.0,49.215.0"}
P.entries["subzone:vile-reef"] = {n="暗礁海",s="暗礁海是一片位于荆棘谷西海岸外，靠近格罗姆高营地的被淹没的生机勃勃的珊瑚礁。在海水之下，好战的鱼人在古老的巨魔遗迹、巨型蛤蜊和沿海沉船之间安了家。",h="暗礁海是一片位于荆棘谷西海岸外，靠近格罗姆高营地的被淹没的生机勃勃的珊瑚礁。在海水之下，好战的鱼人在古老的巨魔遗迹、巨型蛤蜊和沿海沉船之间安了家。",kw={"潮汐祭坛","蓝珍珠","巨型蛤蜊","格罗姆高","鱼人","荆棘谷","暗礁海"},ang={["faction:Horde"]="这片珊瑚礁紧邻格罗姆高营地，对荆棘谷的部落补给船和海岸巡逻队构成了持续的海上威胁。",["race:Troll"]="沉没的石雕和古老的潮汐祭坛作为一个阴郁的提醒，诉说着丛林巨魔曾经统治过的失落已久的沿海领土。"},sec={{t="沉没的岩石与珊瑚床",b="暗礁海延伸于格罗姆高营地近海的无尽之海波涛之下，以其色彩鲜艳的海洋生物和危险的居民而闻名。海底散布着被淹没的巨魔遗迹的风化石雕，以及神秘的潮汐祭坛。成群结队的领地鱼人潜伏在珊瑚礁和过往船只的残骸之间，凶猛地保卫着浅水区，捕食着任何为了寻找巨型蛤蜊和稀有蓝珍珠而敢于潜入深海的潜水者。"}},faq={{q="暗礁海位于何处？",a="暗礁海位于荆棘谷西海岸外的无尽之海中，就在格罗姆高营地的西北方。",al={"暗礁海位置","暗礁海在哪里","如何找到暗礁海"}},{q="什么生物栖息在暗礁海？",a="这片珊瑚礁遍布着敌对的鱼人，它们在珊瑚和沉没的建筑物之间游动，还有散落在海底的巨型蛤蜊。",al={"暗礁海怪物","暗礁海中的怪物","谁住在暗礁海"}},{q="这里水下有什么遗迹？",a="海底包含着古老的巨魔遗迹的残骸和潮汐祭坛，这些是早已被大海吞噬的巨魔文明的遗迹。",al={"暗礁海遗迹","荆棘谷沉没的遗迹","潮汐祭坛位置"}},{q="为什么冒险者要潜入暗礁海？",a="潜水者冒着被鱼人出没的危险潜入水中，探索沿海沉船，调查潮汐祭坛，并采集有时隐藏着珍贵蓝珍珠的巨型蛤蜊。",al={"为什么要前往暗礁海","暗礁海宝藏","荆棘谷蓝珍珠"}}},fp="9,250,28.513.0,31.132.0,37.150.0,37.158.0,43.178.0"}
P.entries["subzone:vul-gol-ogre-mound"] = {n="沃古尔食人魔山",s="沃古尔食人魔山是暮色森林南部的一个低洼盆地，被碎拳食人魔部落占领，并由凶暴的扎尔库沃统治。这里曾经是一片人类宅地，如今废弃的农舍和地下洞穴中到处都是该部落留下的尸体和劫掠来的财物。",h="沃古尔食人魔山是暮色森林南部的一个低洼盆地，被碎拳食人魔部落占领，并由凶暴的扎尔库沃统治。这里曾经是一片人类宅地，如今废弃的农舍和地下洞穴中到处都是该部落留下的尸体和劫掠来的财物。",kw={"亚伯克隆比","暮色森林","守夜人","食人魔","碎拳氏族","沃古尔","扎尔库沃"},ang={["faction:Alliance"]="对于那些走南部小路前往荆棘谷的联盟旅行者来说，将碎拳氏族遏制在沃古尔对于维护这条穿过危险森林的补给线至关重要。",["race:Human"]="盆地中破碎的农舍残骸是一个苦涩的提醒，让人意识到在过去的一代人中，暴风城王国在暮色森林失去了多少领土。"},sec={{t="被蹂躏的宅地",b="沃古尔食人魔山坐落在通往荆棘谷的三岔路口西南方的阴影中，是碎拳氏族在暮色森林的大本营。这个盆地曾经是宁静的农田，但人类居民早已逃离或丧生，只留下了破败的木屋，现在这些木屋已被笨重的食人魔占据，成了它们简陋的避难所。土丘下的洞穴里堆满了被屠宰的黑熊尸体，证明了该氏族那贪婪的胃口。他们的酋长扎尔库沃统治着这个营地，除了搜集普通的破烂装备外，还囤积着各种奇怪的饰品。"},{t="南部边境的威胁",b="由于疲于奔命的守夜人必须分散有限的兵力来保护夜色镇免受狂暴的狼人和亡灵的侵害，指挥官阿尔泰娅·埃伯洛克和她的民兵只能依靠外来的雇佣兵在碎拳氏族北进之前削减其数量。然而，这些食人魔惹上的敌人远不止镇上的卫兵。他们袭击了隐居者亚伯克隆比，偷走了他的一箱炼金工具，并引来了那些寻求传说中扎尔库沃酋长所拥有的奥术透镜的好奇法师们的注意。"}},faq={{q="谁住在沃古尔食人魔山？",a="沃古尔食人魔山被碎拳氏族食人魔占据，由魁梧的酋长扎尔库沃领导。它们居住在破败的人类小屋中以及深处的土洞里。",al={"谁在沃古尔","沃古尔的敌人","暮色森林的食人魔"}},{q="为什么守夜人没有清理掉这些食人魔？",a="守夜人缺乏足够的兵力对南部盆地进行武力征讨。由于夜色镇四面受敌，面临亡灵、狼人和腐草农场的恐怖威胁，民兵组织选择雇佣旅行的冒险者去削减碎拳氏族的数量，而不是让城镇卫兵冒险。",al={"守夜人与食人魔","为什么夜色镇不进攻沃古尔"}},{q="在食人魔到来之前，谁住在这里？",a="在暮色森林南部这片肥沃的区域还处于宁静时期时，这里曾经居住着耕作的人类农户。当诅咒降临这片土地时，农场陷入荒废，入侵的食人魔便占领了这些废弃的建筑。",al={"沃古尔的废墟","沃古尔的历史"}},{q="隐居者亚伯克隆比为什么让我去那里？",a="碎拳食人魔伏击了隐居者亚伯克隆比，抢走了一个装有他草药和防腐工具的箱子。亚伯克隆比无法亲自去战斗，便指引旅行者前往食人魔山夺回他被盗的物品。",al={"亚伯克隆比的食人魔","亚伯克隆比的箱子"}},{q="沃古尔食人魔山在哪里？",a="沃古尔位于暮色森林的最南端，就在那条向南通往荆棘谷边境的道路分叉口的西南方。",al={"沃古尔的位置","如何前往沃古尔"}}},fx={["40dc9221"]={q="什么是沃古尔食人魔山？",a="沃古尔食人魔山是暮色森林南部的一处洼地，位于通往荆棘谷的道路分岔处西南方。这里曾是人类农民的家园，如今这片低地已被粗暴的碎掌食人魔占据，并改造成简陋的据点，遍布泥泞的土丘，还有一座洞穴，里面堆满了他们残忍杀戮的猎物。",al={"什么是沃古尔食人魔山","沃古尔山丘介绍","这个地方是什么"}},["7dda38fd"]={q="沃古尔的农庄遭遇了什么？",a="暮色森林陷入阴影、堕落野兽逼近之前，人类拓荒者曾在这片肥沃的低地耕作。碎掌食人魔入侵后，定居者或被杀害，或被赶走，农舍也沦为废墟。如今，这片低地已彻底沦为食人魔据点，遍地都是熊的尸体和骨骸，不见庄稼。",al={"沃古尔的历史","沃古尔发生过什么","沃古尔食人魔山的往事"}},["60de4358"]={q="沃古尔食人魔山危险吗？",a="这里极其危险。整片洼地遍布凶暴的碎掌食人魔及其打手，他们一见旅人便会发动攻击，还会掠夺附近的游荡者。此外，他们洞穴深处还住着狡猾的首领扎尔克·沃古尔。夜色镇卫队认为，以他们稀少的人手清剿这片洼地代价过高，因此只能依靠经验丰富的雇佣兵来削弱这股威胁。",al={"沃古尔有多危险","沃古尔危险吗","沃古尔山丘危险程度"}}},fp="18,272,20.578.0,31.517.0,36.171.0,49.266.0,32.228.0,44.227.0,27.151.0"}
P.entries["subzone:wailing-caverns"] = {n="哀嚎洞穴",s="哀嚎洞穴坐落于贫瘠之地甜水绿洲上方的悬崖之中，是一个庞大的地下泉水和洞穴网络。最初，暗夜精灵德鲁伊纳拉雷克斯对这里进行了探索，希望为这片干旱的平原恢复生机，但这个地下建筑却变成了一个充满诡异突变、焦躁野兽和非自然危险的扭曲避难所，其真正的源头仍然是一个令人不安的谜团。",h="哀嚎洞穴坐落于贫瘠之地甜水绿洲上方的悬崖之中，是一个庞大的地下泉水和洞穴网络。最初，暗夜精灵德鲁伊纳拉雷克斯对这里进行了探索，希望为这片干旱的平原恢复生机，但这个地下建筑却变成了一个充满诡异突变、焦躁野兽和非自然危险的扭...",kw={"贫瘠之地","cavern of mists","变异者","尖牙德鲁伊","翡翠梦魇","甜水绿洲","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="对于德鲁伊来说，这座洞穴是一个因翡翠梦魇而导致好意被腐蚀的悲剧性警世故事，因此必须唤醒纳拉雷克斯，或者铲除他那些扭曲的弟子。",["faction:Horde"]="扭曲的水源威胁着贫瘠之地赖以生存和通行的一系列脆弱的绿洲，因此，为了附近定居点的安全，清理这些洞穴已迫在眉睫。"},sec={{t="尖牙德鲁伊",b="随着纳拉雷克斯的沉睡陷入疯狂，他最亲近的弟子们被入侵的梦魇逼疯了。他们摒弃了古老的传统，在安娜科德拉等领袖的带领下组成了尖牙德鲁伊，信奉毒蛇之灵，并守卫着沉睡的导师，抵御任何试图打破其恍惚状态的人。这些地下水道现在威胁着贫瘠之地各处的绿洲，引起了雷霆崖的塞纳里奥议会盟友和棘齿城投机地精们的关注。"},{t="梦境的腐化",b="这座洞穴得名于当天然的地下喷泉喷出蒸汽时，岩石裂缝中会传出凄惨的哀嚎声。暗夜精灵德鲁伊纳拉雷克斯带着他忠诚的追随者深入这些地下水道，希望能利用这个地下网络并引导翡翠梦境的力量，让这片贫瘠的草原焕发生机。然而，纳拉雷克斯的意识却被困在了翡翠梦魇之中。溃烂的腐化力量透过沉睡的德鲁伊向外扩散，扭曲了泉水，并将当地的野兽变成了非自然的变异怪物。"}},faq={{q="为什么这里被称为哀嚎洞穴？",a="这座洞穴得名于当底下的蒸汽喷口冲破岩石天花板上的狭窄裂缝时所产生的萦绕耳畔的哀嚎声，这些声音在巨大的石室中回荡，宛如痛苦的呻吟。",al={"为什么叫哀嚎","哀嚎洞穴名字含义","为什么会哀嚎"}},{q="纳拉雷克斯是谁，他为什么在这里沉睡？",a="纳拉雷克斯是一位暗夜精灵德鲁伊，他曾试图通过将地下泉水连接到翡翠梦境来将贫瘠之地变成茂密的林地。然而，他在恍惚状态中被翡翠梦魇吞噬，成为了腐化力量的不知情导火索。",al={"纳拉雷克斯是谁","沉睡的德鲁伊","为什么纳拉雷克斯在沉睡"}},{q="什么是尖牙德鲁伊？",a="他们是纳拉雷克斯昔日的弟子，在导师沉睡期间被翡翠梦魇逼疯。他们信奉蛇之灵，积极地守卫着被腐化的洞穴，并试图将他们扭曲的自然观传播到这片土地上。",al={"尖牙德鲁伊背景故事","尖牙德鲁伊是谁","蛇德鲁伊"}},{q="为什么洞穴里的野兽被称为“变异者”？",a="从纳拉雷克斯体内泄漏出的梦魇能量污染了泉水，将普通的迅猛龙、鳄鱼和毒蛇突变为异常的变异形态，其特征是颜色怪异、攻击性增强，以及有着异样的鳞片和皮毛。",al={"变异野兽","什么是变异者","为什么变异"}}},fx={["0897dbe4"]={q="什么是哀嚎洞穴？",a="哀嚎洞穴是贫瘠之地甜水绿洲中的地下水道与洞窟网络。洞穴中的地下河滋养着地面上散布于干旱平原的绿洲。它曾是雾气缭绕、地下水流奔涌的自然奇观，如今却成了迅速蔓延的腐化之源，侵蚀着这片大草原的腹地。",al={"什么是哀嚎洞穴","哀嚎洞穴概况","哀嚎洞穴介绍"}},["2a1640a8"]={q="哀嚎洞穴发生过什么？",a="暗夜精灵德鲁伊纳拉雷克斯曾带领追随者进入这些洞穴，怀着宏大的目标：汲取地下水并引导翡翠梦境的力量，让贫瘠之地恢复丰饶。然而，他的沉睡被翡翠梦魇缠住。黑暗腐化从他的梦境中渗入地下泉水，扭曲了当地的野生生物，也令他的追随者发狂。",al={"哀嚎洞穴的历史","哀嚎洞穴里发生过什么","哀嚎洞穴传说"}},fdd3771a={q="哀嚎洞穴危险吗？",a="这里极其危险。洞穴中的水域遍布变异且凶猛的野兽，包括有毒的变异蛇、变异迅猛龙和贪婪的鳄鱼。野兽之外，还有尖牙德鲁伊潜伏其中，他们会攻击所有擅闯者，并引导梦魇般的能量，保护那位受困沉睡的主人；正是他的梦境滋生了腐化。",al={"哀嚎洞穴有多危险","哀嚎洞穴安全吗","哀嚎洞穴中的威胁"}}},fp="15,408,22.526.1,17.558.1,37.203.0,43.254.1,32.256.1,43.234.1"}
P.entries["subzone:war-quarter"] = {n="War Quarter",s="War Quarter是幽暗城的西北区，也是被遗忘者的指挥所和军事训练场。在它那回音阵阵的石室中，洛丹伦的士兵、牧师和工匠们磨练着武器和暗影魔法，以保卫他们初生的王国。这里既有战士和牧师的训练大厅，也设有武器大师和重工业设施。",h="War...",kw={"黑暗祭坛","军营","锻造","被遗忘者","牧师训练师","幽暗城","war quarter","战士训练师"},ang={["class:Warrior"]="War Quarter是你前往幽暗城的主要避风港，这里提供武器大师、高级战斗教官和重型军械库，让你为洛丹伦残酷的前线战斗做好准备。",["profession:Blacksmithing"]="War Quarter既有训练大师，也有高温铁砧，是铁匠们为被遗忘者的战争努力敲打弹药和板甲的中心枢纽。"},sec={{t="被遗忘者驻军",b="War Quarter占据了这座地下都市的西北区，是被遗忘者武装力量的堡垒。在阴沉的石拱下，普通卫兵和精英勇士们聚集在此进行武装战斗演练。与传统活人王国的军营不同，这个军事中心将残酷的钢铁战争与冷酷的暗影仪式结合在一起，这里有一座阴森的黑暗祭坛，将精神修行与军事雄心融合在一起。"},{t="锻造与钢铁",b="除了容纳战士和牧师公会外，该区还是幽暗城战时生产的核心。刀剑和盔甲的撞击声在石壁间持续回荡，这得益于该区的铁匠、冶炼工和武器大师。在这里，深埋地下的铁矿被锻造成型，为保卫洛丹伦废墟免受天灾军团和血色十字军侵扰的部队提供装备。"}},faq={{q="War Quarter的目的是什么？",a="War Quarter是幽暗城的军事总部。它拥有供战士和牧师使用的军事训练场，以及至关重要的铁匠和采矿生产中心，以保证被遗忘者军队拥有充足的武器和护甲。",al={"什么是war quarter","war quarter的作用","为什么要访问war quarter"}},{q="为什么牧师位于War Quarter？",a="被遗忘者牧师主要专注于暗影的修行，将其视为一种强大的武器，而不是维护田园牧歌式的圣所。他们出现在军事力量和黑暗祭坛附近，反映了信仰与战争在被遗忘者的防御中交织得有多深。",al={"亡灵牧师位置","为什么牧师在war quarter","幽暗城牧师训练师"}},{q="什么是黑暗祭坛？",a="黑暗祭坛是位于War Quarter内的一处黑暗精神力量汇聚点。它与被遗忘者的黑暗仪式和训练息息相关，为牧师和勇士们所使用的暗影魔法提供根基。",al={"幽暗城黑暗祭坛","war quarter里的祭坛"}},{q="War Quarter在幽暗城的什么位置？",a="War Quarter位于幽暗城环形布局的西北象限，在中央的Trade Quarter西北方，介于东侧的Magic Quarter和南侧的Apothecarium之间。",al={"war quarter在哪里","war quarter位置","war quarter方位"}}},fx={["89f17781"]={q="什么是War Quarter？",a="War Quarter是幽暗城西北部的区域，也是被遗忘者军队的主要堡垒和训练场。它深藏在洛丹伦废墟之下，宽阔的大厅里回荡着刀剑交击声与黑暗的吟唱，设有战士营房、武术教官驻地，以及研习暗影之术的被遗忘者牧师驻地。",al={"什么是war quarter","幽暗城war quarter","幽暗城的war quarter"}},e554fcad={q="为什么叫War Quarter？",a="这里是希尔瓦娜斯女士领地的军事核心，因此得名。被遗忘者在此组织常备军、操练士兵、磨砺刀剑，并制定对抗天灾军团、血色十字军以及其他威胁其主权之敌的战术。",al={"为何称为war quarter","war quarter名称","为何叫war quarter"}},d58a257c={q="War Quarter危险吗？",a="对部落勇士而言，这片区域安全无虞，有精锐的被遗忘者部队和亡灵卫兵严密把守。然而，对外来者、联盟成员或天灾军团的爪牙来说，踏入War Quarter就意味着要面对随时准备毫不犹豫地击倒闯入者的武装驻军。",al={"war quarter危险吗","war quarter的危险","war quarter安全吗"}}},fp="11,390,21.477.0,15.390.0,39.237.0,43.313.0,30.216.0,50.196.0"}
P.entries["subzone:war-room"] = {n="War Room",s="War Room坐落在Stormwind Keep的最深处，是联盟军队的战略枢纽。这里环绕着武器装备、战争史书和战术图表，将军和战略家们在此监控遥远的前线，并协调王国的防御事务。",h="War Room坐落在Stormwind Keep的最深处，是联盟军队的战略枢纽。这里环绕着武器装备、战争史书和战术图表，将军和战略家们在此监控遥远的前线，并协调王国的防御事务。",kw={"黑暗之门","格瑞姆巴托","地图室","stormwind keep","战略桌","war room"},ang={["class:Warrior"]="在重型弹药和战略地图的环绕下，武将们会赞赏要塞内保持的周密军事组织。",["faction:Alliance"]="对于联盟士兵和勇士来说，War Room代表了王国防御东部王国及更远地区挥之不去的威胁的战略大脑。"},sec={{t="要塞的神经中枢",b="War Room从Stormwind Keep的宏伟厅室中分出，专门用于军事后勤和高级战役规划。它的石墙上装饰着一排排的武器装备，包括剑、火枪，甚至重型火炮。军事论著和历史编年史堆叠在附近的桌子上。房间的中心是一张巨大的战术地图桌，指挥官们可以借此评估联盟在艾泽拉斯各地的部署，而皇室成员则在几步之遥处理国家大事。"}},faq={{q="War Room在哪里？",a="War Room位于Stormwind Keep内，坐落在皇家堡垒的中央走廊之后。它以其厚重的防御工事、武器架和大型战术战略桌而闻名。",al={"war room位置","如何找到war room","地图室在哪里"}},{q="这个房间有什么用？",a="它是联盟军队在暴风城的战略规划总部。高级指挥官们聚集于此审查情报、协调部队调动，并研究历史和正在进行的冲突。",al={"war room有什么用","war room目的","为什么要塞会有war room"}},{q="这里有什么历史传说？",a="房间的桌子上堆满了关于军事战略的书籍和王国过去战争的编年史，方便那些规划联盟战役的指挥官随时查阅。",al={"war room书籍","stormwind keep里的书籍","war room历史典籍"}}},fx={bec1bb93={q="什么是War Room？",a="War Room是暴风城要塞内的一间军事战略室，位于主王座大厅走廊旁。它是高级指挥中心，供指挥官、战略家和联盟领袖聚集，统筹正在进行的军事行动。室内摆满地图、武器、战略典籍和火炮，专用于保卫暴风城及其盟友，并调度战略部署。",al={"什么是war room","war room介绍","暴风城war room"}},["2eaea60b"]={q="谁负责War Room？",al={"war room里有哪些人","谁负责war room","war room指挥官"}},["3751c6cd"]={q="War Room危险吗？",a="对联盟成员而言并不危险。它位于暴风城要塞深处，周围有精锐皇家卫队和高级军官把守。然而，对闯入者或部落爪牙来说，潜入这座戒备森严的战略要地无异于自寻死路。",al={"war room安全吗","war room中的威胁"}},["6b32db00"]={q="为什么叫War Room？",a="这间屋子的名字源于它专门承担的职责：它是统筹王国军事行动的中枢。室内陈列着火枪、利剑、火炮和战术地图，所有布置都服务于策划和发动联盟的军事行动。",al={"war room名称含义","为何叫war room"}}},fp="8,279,24.541.0,30.209.0,33.216.0,39.180.0"}
P.entries["subzone:warpwood-quarter"] = {n="Warpwood Quarter",s="Warpwood Quarter 位于毁坏的上层精灵城市艾德雷萨（即现在的厄运之槌）的东区。这里曾是精灵培育自然和郁郁葱葱花园的中心，如今却沦为一片扭曲的、被恶魔玷污的废墟，充斥着狂暴的植物和堕落的萨特。",h="Warpwood Quarter 位于毁坏的上层精灵城市艾德雷萨（即现在的厄运之槌）的东区。这里曾是精灵培育自然和郁郁葱葱花园的中心，如今却沦为一片扭曲的、被恶魔玷污的废墟，充斥着狂暴的植物和堕落的萨特。",kw={"荒野变形者奥兹恩","厄运之槌东区","艾德雷萨","魔藤","生育之果","拉瑞斯小亭","普希林","warpwood quarter"},ang={["class:Druid"]="Warpwood 古树扭曲的命运以及生育之果被腐蚀成肮脏的魔藤，是对塞纳里奥教义的悲剧性侮辱，促使月光林地的德鲁伊们寻求净化该区域。",["race:NightElf"]="看到艾德雷萨宏伟的温室变成萨特的巢穴，令人清醒地意识到正是这种腐蚀导致了古老的上层精灵帝国的覆灭。"},sec={{t="被腐蚀的花园",b="Warpwood Quarter 曾经以宏伟的植物奇观而闻名，现在却变成了一片由扭曲的上古树精和致命鞭笞者组成的窒息森林。该地区落入了萨特“荒野变形者”奥兹恩的控制之下，他利用黑暗魔法亵渎了古老的“生育之果”。在他的邪恶影响下，这里的植物变得怪诞且具有掠夺性，空气中弥漫着邪恶的魔藤碎片，并将恶魔、叛逆的小鬼和恶魔奴仆吸引到了这些废墟大厅之中。"},{t="穿越杂草丛生的路径",b="虽然探险者通常从厄运之槌中央的破烂广场进入该地区，但在东边的拉瑞斯小亭下方还隐藏着一条杂草丛生的地下后门。想要在这一地区穿行，不仅要对抗奥兹恩扭曲的守护者，还要应付像淘气的小鬼普希林这样难以捉摸的居民，他会通过盗窃诱导追捕者深入废墟的危险地带。"}},faq={{q="什么是 Warpwood Quarter？",a="Warpwood Quarter 是厄运之槌的东翼，也就是古老的上层精灵城市艾德雷萨。它最初是围绕着宏伟的温室而建，现已被恶魔能量过度生长和改变。",al={"什么是 warpwood quarter","warpwood 区","厄运之槌东区背景故事"}},{q="谁统治着这个地区？",a="萨特“荒野变形者”奥兹恩统治着这个区域。他利用邪能腐蚀了当地的植被和传奇的生育之果，将该地区的植物守护者变成了邪恶的扭曲古树。",al={"谁控制了 warpwood","荒野变形者奥兹恩","warpwood 首领"}},{q="如何进入 Warpwood Quarter？",a="主入口位于厄运之槌内部的破烂广场。第二个隐蔽的后门位于菲拉斯东部的拉瑞斯小亭下方，需要一把月牙钥匙才能解锁。",al={"warpwood 入口","如何前往厄运之槌东区","拉瑞斯小亭入口"}},{q="小鬼普希林为什么要在废墟里跑来跑去？",a="普希林是一个潜伏在区域入口附近的盗窃小鬼。当有入侵者对峙时，他会嘲弄他们并逃往废墟深处，一路嘲笑着冒险者，直到隐秘之地。",al={"普希林","普希林是谁","厄运之槌里跑动的小鬼"}}},fp="16,281,18.474.0,31.427.0,29.199.0,24.234.0,38.206.0,50.210.0"}
P.entries["subzone:warrior-s-terrace"] = {n="战士区",s="战士区是达纳苏斯的东部区域，既是武技训练中心，也是这座首都的防御要塞。它俯瞰着通往泰达希尔更深处的道路，汇集了城中的战场军官、战士训练师以及哨兵巡逻队。",h="战士区是达纳苏斯的东部区域，既是武技训练中心，也是这座首都的防御要塞。它俯瞰着通往泰达希尔更深处的道路，汇集了城中的战场军官、战士训练师以及哨兵巡逻队。",kw={"战场军官","达纳苏斯","决斗场","东门","正义大厅","哨兵","泰达希尔","战士区"},ang={["class:Warrior"]="对于在暗夜精灵首都进行训练的战士来说，这个区域就是你们的行动基地，提供武技指导、决斗场地以及战场军官。",["profession:Blacksmithing"]="该露台设有城中的锻造训练师和熔炉设施，除了驻军外，还负责护甲和武器的制作。"},sec={{t="达纳苏斯之盾",b="战士区位于达纳苏斯的东部入口，有时也被称为正义大厅，是抵御来自泰达希尔荒野入侵的主要防御壁垒。全副武装并骑着夜刃豹的哨兵守卫着高耸的拱门，对来往的旅人保持着警惕。在露天的广场上，有抱负的战士们在广阔的决斗场和靶场中与经验丰富的老兵一同操练。该区域还承担着实际的军事需求，驻扎着武器锻造师、护甲商，以及负责协调世界各地暗夜精灵部队的战场军官。"}},faq={{q="战士区的作用是什么？",a="战士区是达纳苏斯的军事核心和主要防御门户。这里设有城中的武技训练师、战场军官、决斗场和靶场，而驻扎的哨兵则守卫着通往泰达希尔广袤大地的东门。",al={"什么是战士区","战士区的作用","为什么要有战士区"}},{q="穿过东门的道路通向哪里？",a="战士区东边缘的宏伟城门直接通往达纳苏斯之外，连接到泰达希尔更广阔的森林小径，将这座与世隔绝的首都与下方的多兰纳尔和鲁瑟兰村等定居点枢纽连接起来。",al={"城门通向何处","战士区城门","达纳苏斯东门"}},{q="谁守卫着这个区域？",a="该区域及其周边城门主要由哨兵，即暗夜精灵的精锐常备军来守卫。许多哨兵骑着披甲的夜刃豹在露台和门口巡逻。",al={"谁保护战士区","战士区的哨兵","达纳苏斯卫兵"}},{q="还有哪些区域与战士区相连？",a="桥梁和步道将战士区直接与北面的工匠区、南面的贸易区，以及向西通往城市中心的葱郁的神殿花园连接在一起。",al={"战士区的连接","如何前往战士区","与战士区相连的地方"}}},fx={["162de6c0"]={q="什么是战士区？",a="战士区是达纳苏斯最东侧的区域，守卫着通往泰达希尔荒野的大门。它是暗夜精灵首都的主要军事中心，设有决斗场、射击场和兵营，哨兵、战士训练师与战斗大师在此集结操练，守卫国土。",al={"什么是战士区","战士区介绍","战士区概况"}},["4e3ffca6"]={q="为什么叫战士区？",a="战士区因其作为达纳苏斯军事核心而得名。这里是暗夜精灵战士、哨兵和战斗大师磨练战斗技艺的集结与训练场，也是一旦有人进犯城门时，城市的第一道防线。",al={"为什么叫战士区","战士区名称含义","为何称为战士区"}},d3913307={q="战士区危险吗？",a="对联盟访客而言，这里完全安全。战士区是达纳苏斯守卫最森严的据点，由警惕的哨兵昼夜骑乘夜刃豹巡逻守护。只要不在决斗场挑起较量，也不作为卡多雷的敌人闯入城中，这里就没有危险。",al={"战士区危险吗","战士区安全吗","战士区中的威胁"}}},fp="17,256,19.626.0,45.284.0,50.225.0,24.191.0,55.206.0"}
P.entries["subzone:warsong-labor-camp"] = {n="战歌劳工营地",s="战歌劳工营地是一个位于灰谷东南部隐蔽处的部落木材采集前哨。该营地由战歌伐木工运营，并由兽人哨兵防守。为了支持杜隆塔尔的发展，这里的工人们不顾周边森林的敌意，在此砍伐木材。",h="战歌劳工营地是一个位于灰谷东南部隐蔽处的部落木材采集前哨。该营地由战歌伐木工运营，并由兽人哨兵防守。为了支持杜隆塔尔的发展，这里的工人们不顾周边森林的敌意，在此砍伐木材。",kw={"灰谷","朵丹尼尔","坠星湖","劳工营地","伐木工","木材","战歌"},ang={["faction:Horde"]="这些伐木工采集的木材对于建设和维护奥格瑞玛至关重要，使得这个偏远的作业站成为了在这片争议领土上的一个重要经济生命线。",["race:NightElf"]="该营地对灰谷生机勃勃的森林来说是一道持续的伤口，它通过砍伐先祖林地来维持杜隆塔尔的战争机器。"},sec={{t="部落的木材",b="战歌劳工营地位于坠星湖以东、朵丹尼尔兽穴的西南方，其存在只有一个至关重要的目的：采集灰谷茂密的木材。杜隆塔尔干旱的平原无法提供足够的优质木材来建设奥格瑞玛这样的城市，因此战歌氏族被迫深入这片充满争议的丛林。该营地由刻苦的伐木工和兽人卫兵组成，在相对孤立的环境中运作，尽管随时面临暗夜精灵侦察兵和路过的联盟战争小队的威胁，依然不断地砍伐着古老的树木。"},{t="易受攻击的前哨",b="由于它地处偏远，远离主路和碎木岗哨这样的坚固基地，该营地极其脆弱。联盟突袭者经常袭击在此工作的苦工和守卫，因为他们知道援军无法迅速赶到。对暗夜精灵来说，每一棵被砍伐的树木都是一种亵渎，这使得这个平凡的伐木营地成为了该地区战争中一个长期的冲突点。"}},faq={{q="战歌劳工营地位于哪里？",a="劳工营地位于灰谷东南部，在坠星湖以东、朵丹尼尔兽穴的西南方。",al={"战歌劳工营地位置","战歌劳工营地在哪里","寻找劳工营地"}},{q="这个营地的目的是什么？",a="该前哨是一个木材采集点。兽人伐木工在此砍伐并加工灰谷的古老木材，为奥格瑞玛和杜隆塔尔的其他定居点提供建筑材料。",al={"兽人为什么在这里","他们在这里做什么","战歌伐木营地目的"}},{q="为什么营地经常受到攻击？",a="营地孤立无援，远离部落的主要防御工事。暗夜精灵极其痛恨这种对他们神圣森林的采伐行为，而且联盟勇士经常突袭该前哨，因为其偏远的位置使得附近的守卫无法提供及时的支援。",al={"联盟攻击劳工营地","为什么它成为目标","营地安全吗"}},{q="这是格罗玛什·地狱咆哮建立的营地吗？",a="大酋长萨尔最初在第三次战争期间派遣格罗玛什·地狱咆哮和战歌氏族进入灰谷，目的正是为了采集木材。劳工营地正是对那些最初伐木工作的持续延续。",al={"是格罗姆建立的吗","格罗玛什·地狱咆哮劳工营地","营地历史"}}},fx={["1e0e0990"]={q="为什么叫战歌劳工营地？",a="这座前哨以战歌氏族命名。这个强悍的兽人氏族受大酋长萨尔委派，在灰谷各处伐木。这里专用于伐木作业，并非宏伟的要塞，因此被称为他们的劳工营地。",al={"为什么叫战歌劳工营地","战歌劳工营地名称含义","战歌劳工营地的由来"}},f9ba0d17={q="什么是战歌劳工营地？",a="战歌劳工营地是部落仍在运作的伐木前哨，位于灰谷东南部，坠星湖以东、朵丹尼尔兽穴西南。这里是前线木材作业点，劳工和机械伐木机砍伐森林中的古树，为部落扩张提供木材，并持续戒备当地威胁。",al={"什么是战歌劳工营地","战歌劳工营地介绍","介绍一下战歌劳工营地"}},b37a2225={q="谁住在战歌劳工营地，又由谁管理？",a="营地由战歌氏族成员驻守，主要包括兽人伐木工、负责操作地精制造的切割机和伐木机的工人，以及驻扎在周边警戒、保护木材收获的坚毅卫兵。",al={"谁管理战歌劳工营地","战歌劳工营地的居民","谁在战歌劳工营地"}},f04818dc={q="战歌劳工营地危险吗？",a="这里相当危险。营地位于灰谷深处，位置相对孤立，因此容易遭到联盟部队和当地哨兵突袭；他们试图在部落较大据点的援军赶到前消灭伐木队。",al={"战歌劳工营地危险吗","战歌劳工营地的危险","战歌劳工营地有多危险"}}},fp="18,280,20.518.0,20.390.0,40.113.0,33.189.0,36.258.0,40.223.0"}
P.entries["subzone:warsong-lumber-camp"] = {n="战歌伐木营地",s="战歌伐木营地是深藏在灰谷的一处坚固的兽人伐木作业点，由战歌氏族运营，旨在为部落采集木材。以坚固的卡加希亚要塞为依托，它既是附近部落定居点的经济命脉，也是对暗夜精灵不休的挑衅。地精制造的伐木机啃噬古树枝干发出的持续轰鸣，使这片林中空地成为了森林战争的主要焦点。",h="战歌伐木营地是深藏在灰谷的一处坚固的兽人伐木作业点，由战歌氏族运营，旨在为部落采集木材。以坚固的卡加希亚要塞为依托，它既是附近部落定居点的经济命脉，也是对暗夜精灵不休的挑衅。地精制造的伐木机啃噬古树枝干发出的持续轰鸣，使...",kw={"灰谷","卡加希亚要塞","伐木机","碎木岗哨","木材","战歌氏族","战歌伐木营地"},ang={["faction:Horde"]="这里采集的木材为碎木岗哨提供了建筑材料，以及保卫部落在卡利姆多未来的防御工事。",["race:NightElf"]="营地中伐木机发出的尖啸声和倒下的树木，代表了对灰谷神圣平衡的直接而残酷的侵犯，而哨兵们誓要消除这种侵犯。"},sec={{t="伐木之心",b="战歌伐木营地直接从灰谷东部茂密的树冠层中开辟出来，是推动部落在卡利姆多扩张的工业引擎。兽人苦工和受雇的地精工程师利用飞速旋转的伐木机剥开森林，将参天巨木加工成木材，用于加固像附近的碎木岗哨这样的哨所城墙，并建立起杜隆塔尔这个新兴的国度。营地防御森严，以抵御暗夜精灵不断的反击，其核心是卡加希亚要塞的围栏，以及氏族凶猛战狼的犬舍。对于战歌氏族来说，每一棵伐下的树木都意味着生存与力量；而对于当地的哨兵来说，每一片锯刃都亵渎神圣。"},{t="战争的遗产",b="战歌氏族在这片森林中的存在可以追溯到第三次战争，当时格罗姆·地狱咆哮首次率领他的战士进入圣林，为部落索取木材。最初的砍伐点燃了半神塞纳留斯的怒火，并引来了暗夜精灵古老的愤怒。尽管现在的营地是在萨尔的部落旗帜下运作，但旧日的仇恨依然燃烧得同样炽热。在被荒野的树木、敌对的精灵以及邻近冥火岭周围残留的恶魔腐化所包围的情况下，营地的守卫者全天候保持武装，手持斧头采集木材，随时准备丢下木料去击退下一次伏击。"}},faq={{q="部落为什么要在灰谷伐木？",a="部落定居的土地——特别是杜隆塔尔和贫瘠之地——干旱而稀疏，缺乏建造建筑、栅栏和战争机器所需的茂密木材。灰谷提供了大量几乎无穷无尽的优质木材，这对像碎木岗哨这样的兽人哨所以及奥格瑞玛主城的生存和扩张至关重要。",al={"为什么要伐木","战歌伐木原因","部落为何需要木材"}},{q="卡加希亚要塞是什么？",a="卡加希亚要塞是锚定战歌伐木营地的坚固堡垒。它提供了军营、战略指挥部以及一个加固的据点，当哨兵或当地野生生物袭击伐木周边区域时，苦工和监工可以撤退至此并抵御暗夜精灵的伏击。",al={"卡加希亚要塞的用途","伐木营地中的堡垒","战歌在灰谷的要塞"}},{q="为什么暗夜精灵对这个营地如此敌视？",a="对暗夜精灵来说，灰谷是受自然之灵和远古守护者保护的神圣祖居之地。用嘈杂、喷吐黑烟的地精机械砍伐古树被视为肆意的破坏和彻底的亵渎，这引发了不断的游击袭击，试图将战歌兽人逐出森林。",al={"暗夜精灵的反应","为什么精灵要袭击伐木营地","哨兵袭击"}},{q="地精在营地中扮演什么角色？",a="地精雇佣兵和技术人员提供了推动伐木作业的专业技术，其中最著名的是蒸汽动力伐木机。这些机器使战歌氏族能够以传统手斧无法企及的速度采集和剥离巨大的古树。",al={"战歌营地里的地精","伐木机为什么在这里","灰谷的地精机械"}}},fx={["4dce9068"]={q="什么是战歌伐木营地？",a="战歌伐木营地是战歌氏族在灰谷中部建立的一座规模庞大的防御型伐木前哨。营地以坚固的卡加希亚要塞为核心，还设有狼舍，是部落在这片古老森林中的主要木材生产基地。营地持续将木材和补给运往卡利姆多各地，支援奥格瑞玛等年轻的兽人定居点。",al={"战歌伐木营地","这是什么地方","战歌伐木营地简介"}},ae82815c={q="为什么叫战歌伐木营地？",a="营地以战歌氏族命名。第三次战争期间，这个强悍的兽人氏族在酋长格罗姆·地狱咆哮的率领下，率先进入灰谷的古老森林。尽管他们的领袖为使兽人摆脱恶魔腐化而牺牲，但氏族仍永久盘踞于此，不顾荒野的猛烈反抗，执意推进部落的伐木行动。",al={"为什么叫战歌伐木营地","战歌伐木营地名称由来"}},["4eda0a15"]={q="谁在管理战歌伐木营地？",a="营地由战歌氏族的兽人驻守和运营，同时有受荆棘谷地精训练的地精雇佣兵、工程师和机械操作员协助。战歌步兵和兽栏管理员守卫卡加希亚要塞及营地外围，而地精监工则负责操纵那些轰鸣着、喷吐燃料的伐木机，将灰谷的古树砍倒。",al={"谁领导战歌伐木营地","这里由谁负责","战歌伐木营地指挥官"}},["7474287b"]={q="战歌伐木营地危险吗？",a="这里极其危险。战歌氏族在灰谷无休止地砍伐树木，激怒了暗夜精灵和森林之灵。哨兵和复仇的树妖经常从树冠间发动伏击，摧毁伐木机并夺回圣林。此外，靠近营地外围的联盟旅人会发现卡加希亚要塞戒备森严，凶悍的战歌守卫随时准备击倒任何擅闯者。",al={"战歌伐木营地危险吗","伐木营地有多危险"}}},fp="19,433,20.678.0,15.661.0,38.357.0,23.276.0,48.307.0,38.272.0"}
P.entries["subzone:waterspring-field"] = {n="清泉平原",s="清泉平原是塔纳利斯北部的一项至关重要的抽水作业，由加基森的地精建造，旨在开发地下蓄水层。但这片平原并没有供应给这座繁荣的城镇，反而被冷酷的废土强盗所占据，他们现在囤积着这片沙漠中最珍贵的资源。",h="清泉平原是塔纳利斯北部的一项至关重要的抽水作业，由加基森的地精建造，旨在开发地下蓄水层。但这片平原并没有供应给这座繁荣的城镇，反而被冷酷的废土强盗所占据，他们现在囤积着这片沙漠中最珍贵的资源。",kw={"加基森","水泵","塔纳利斯","废土强盗","水囊","水塔","清泉平原"},ang={["profession:Engineering"]="这些地精建造的机械抽水塔代表了令人印象深刻的沙漠水力工程。",["race:Human"]="占据这些塔楼的废土强盗主要是人类亡命之徒，他们背弃了北方的王国，在烈日沙漠中过着残暴的生活。"},sec={{t="被窃的绿洲",b="在塔纳利斯灼热的荒野中，没有什么比淡水更珍贵了。为了支持其不断扩张的贸易枢纽，加基森的热砂财团地精在清泉平原上竖起了一排工业抽水塔，用以汲取地下储备水源。但当废土强盗——一群由人类亡命之徒和沙漠掠夺者组成的庞大团伙——夺取了整个平原后，他们的计划便破产了。强盗们现在誓死守卫着被劫持的抽水机，迫使加基森必须寻找愿意收复水源的雇佣兵。"}},faq={{q="是谁在这里建造了水塔？",a="这些水塔是由加基森的地精建造的。他们打算从深层的地下储备中抽取淡水，以维持他们的沙漠定居点和工业运营。",al={"谁建造了这个","地精水泵","清泉平原之塔"}},{q="为什么强盗会盘踞在清泉平原？",a="废土游牧民入侵了这片平原，并将机器据为己有。控制了塔纳利斯北部的主要淡水来源，使他们能够完全支配周围的旅行者和商人。",al={"强盗是谁","清泉平原的废土强盗","为什么废土强盗在这里"}},{q="为什么加基森不直接夺回平原？",a="加基森雇佣冒险者来击退废土强盗并找回他们的水囊。至于为何没有派遣他们的打手前往平原，原因尚不得而知。",al={"为什么加基森不战斗","守护清泉平原的地精"}}},fp="17,294,14.538.0,32.178.0,53.215.0,51.162.0"}
P.entries["subzone:wavestrider-beach"] = {n="破浪海滩",s="破浪海滩是塔纳利斯东部边缘那条被烈日炙烤的海岸线。它延伸在热砂港和海盗据点落帆海湾之间，沙滩上不仅有富有侵略性的甲壳类野生生物，还可以远眺海面上持续不断的海上冲突。",h="破浪海滩是塔纳利斯东部边缘那条被烈日炙烤的海岸线。它延伸在热砂港和海盗据点落帆海湾之间，沙滩上不仅有富有侵略性的甲壳类野生生物，还可以远眺海面上持续不断的海上冲突。",kw={"海岸","沙漠爬行蟹","落帆海湾","南海","热砂港","钢颚钳嘴龟","塔纳利斯","破浪海滩"},sec={{t="危险的海岸线",b="Running along the ocean border of eastern Tanaris, Wavestrider Beach connects the goblin settlement of Steamwheedle Port in the north to the cliffs guarding Lost Rigger Cove to the south. Rather than a gentle resort, the shoreline is plagued by vicious Steeljaw Snappers and Desert Crawlers scuttling across the baking sand. Out in the deep water just offshore, burning vessels remain locked in a perpetual naval clash, serving as a grim warning of the piratical violence that dominates these coastal waters."}},faq={{q="破浪海滩在哪里？",a="破浪海滩位于塔纳利斯的东海岸，直接连接着北部的热砂港码头和南部的落帆海湾入口。",al={"破浪海滩位置","破浪海滩在哪里","塔纳利斯 破浪海滩"}},{q="这里沙滩上有什么生物出没？",a="海滩上主要被富有侵略性的海洋食腐动物所占据，包括原生的沙漠爬行蟹和在浪花中潜行的重甲钢颚钳嘴龟。",al={"破浪海滩怪物","破浪海滩螃蟹"}},{q="近海那些燃烧的船只是什么？",a="从沙滩望向大海，旅行者可以看到两艘正在交战的燃烧船只。它们反映了肆虐在南海海盗藏身处周围海域的猖獗海盗活动。",al={"塔纳利斯 燃烧的船","破浪海滩起火船只"}},{q="破浪海滩可以安全通行吗？",a="这里相对危险。不仅水边有富有侵略性的钳嘴龟和螃蟹，而且靠近南海海盗的领地，粗心的探险者很容易陷入重围。",al={"破浪海滩危险吗","破浪海滩安全"}}},fp="17,279,23.508.0,35.182.0,37.153.0,44.213.0,44.204.0"}
P.entries["subzone:weathered-nook"] = {n="老屋",s="老屋隐藏在千针石林的北侧峭壁间，是一处位于峡谷底部上方高处的隐蔽裂隙与避难所。它俯瞰着广袤的石柱之海，作为那些寻求远离喧嚣定居点、安宁沉思的牛头人隐居者的简朴家园与静修处。",h="老屋隐藏在千针石林的北侧峭壁间，是一处位于峡谷底部上方高处的隐蔽裂隙与避难所。它俯瞰着广袤的石柱之海，作为那些寻求远离喧嚣定居点、安宁沉思的牛头人隐居者的简朴家园与静修处。",kw={"洞穴","峭壁","多恩·平原行者","乱风岗","普拉特·白云","千针石林","老屋"},ang={["faction:Horde"]="探索峡谷高处峭壁的部落流浪者会在这里发现栖身于北侧岩壁的友善同胞。",["race:Tauren"]="对于牛头人旅行者来说，老屋代表着自力更生的宁静精神，它提供了一处俯瞰峡谷的平和视野，让人可以远离乱风岗繁忙的桥梁，与元素进行交流。"},sec={{t="峭壁之上的避风港",b="老屋开凿在乱风岗北侧的陡峭砂岩壁上，从下方峡谷盆地经过的旅人很容易错过它。一条天然坡道盘旋而上，通往一处避风的岩架和洞穴。这里并没有设立军事哨所或大型定居点，而是作为多恩·平原行者和普拉特·白云等孤独流浪者的简朴居所，提供了一处安全、静谧的落脚点，并能一览这片风蚀针岩高原的壮丽景色。"}},faq={{q="老屋在哪里？",a="老屋坐落在千针石林的北侧峭壁沿线。从乱风岗出发，向北行进直至抵达高耸的岩壁，然后沿着峭壁向东走，你就会发现一条蜿蜒向上通往台地岩壁的坡道。",al={"如何找到老屋","老屋位置","老屋在哪里"}},{q="谁住在老屋？",a="这里居住着多恩·平原行者和普拉特·白云，他们是选择栖居于这处峡谷上方偏远岩架的孤独牛头人，而不是住在乱风岗拥挤的高塔之上。",al={"这里有什么人","老屋的居民","老屋里的npc"}},{q="老屋隶属于部落吗？",a="虽然居住者是牛头人，且与他们的同胞有着天然的认同感，但老屋并非正式的部落驻军点。它只是隐匿在荒野中的简朴个人营地与居所。",al={"这是部落营地吗","部落与老屋"}}},fx={["3c15de53"]={q="什么是老屋？",a="老屋是一处小巧而僻静的避身处，开凿在俯瞰千针石林峡谷的北部峭壁上。它远离乱风岗和闪光平原的繁忙道路，这处安静的岩隙为旅人提供了简陋的营地，让他们得以躲避恶劣环境和峡谷底部游荡的野兽。",al={"老屋是什么","什么是老屋","老屋介绍"}},["4c65fc70"]={q="老屋危险吗？",a="与周围的峡谷底部相比，老屋本身相对平静，是居住者的避难所。不过，沿着高耸崖壁的道路十分险峻；附近的岩石高地和隘道上也有徘徊的狮鹫、双足飞龙以及半人马劫掠者等凶猛野兽。",al={"老屋危险吗","老屋安全吗","老屋附近的威胁"}}},fp="14,319,19.505.0,36.227.0,32.191.0,48.189.0"}
P.entries["subzone:weazel-s-crater"] = {n="维吉尔之坑",s="维吉尔之坑是位于闪光平原北部坚硬盐地上一处深邃的凹坑。它的起源至今仍是个谜，而且现在有盐石蛇妖栖息在这片洼地中。",h="维吉尔之坑是位于闪光平原北部坚硬盐地上一处深邃的凹坑。它的起源至今仍是个谜，而且现在有盐石蛇妖栖息在这片洼地中。",kw={"侏儒工程学","地精赛道","盐石蛇妖","闪光平原","千针石林","维吉尔之坑"},ang={["profession:Engineering"]="这处深坑坐落在闪光平原的实验赛车和碎片残骸之间。造访赛道的工程师们有充分的理由去研究这片危险的地形。"},sec={{t="不稳定的遗产",b="在闪光平原那刺眼的白色旷野上，地精和侏儒的实验性火箭车不断挑战着机械工程的极限。碎片、焦土和撞击留下的坑洞遍布平原，但维吉尔之坑因其巨大的规模和深度而尤为显眼。这个坑的起源尚不为人所知。如今，机械残骸大多已被清理，这片洼地已成为好斗的盐石蛇妖们晒太阳的巢穴。"}},faq={{q="是什么导致了维吉尔之坑的形成？",a="这个坑的起源尚不为人所知。目前尚未确定其成因。",al={"维吉尔之坑是如何形成的","维吉尔之坑的起源","为什么这里有个坑"}},{q="现在坑里有什么生物居住？",a="这处洼地目前居住着危险的盐石蛇妖，它们潜伏在坑洞的岩石边缘和底部。",al={"维吉尔之坑的怪物","坑里有什么"}}},fx={["76b07605"]={q="什么是维吉尔之坑？",a="维吉尔之坑是千针石林闪光平原北部的一处宽阔而深陷的洼地。它看起来像一处撞击坑，却正好位于地精和侏儒测试易爆火箭赛车的道路旁，因此成为盐碱荒漠中醒目而危险的地标。",al={"维吉尔之坑","这个坑是什么","闪光平原的维吉尔之坑"}},["4a4cb038"]={q="维吉尔之坑危险吗？",a="是的。除了鲁莽的火箭赛车在平原上横冲直撞带来的风险外，坑中还成了凶猛的盐石蜥蜴的巢穴。任何人若踏入坑底，都可能被石化，或遭潜伏在其中的领地性野兽撕咬。",al={"维吉尔之坑危险吗","维吉尔之坑的威胁","维吉尔之坑的危险"}}},fp="15,163,17.446.0,28.58.0,29.127.0"}
P.entries["subzone:webwinder-path"] = {n="蛛网小径",s="蛛网小径是一条位于石爪山脉的蜿蜒山路，连接着玛拉卡金巨魔前哨站与暗色湖。它穿过崎岖的岩壁和茂密的高地树林，那里栖息着极具攻击性的蛛形纲生物和原生野兽。",h="蛛网小径是一条位于石爪山脉的蜿蜒山路，连接着玛拉卡金巨魔前哨站与暗色湖。它穿过崎岖的岩壁和茂密的高地树林，那里栖息着极具攻击性的蛛形纲生物和原生野兽。",kw={"玛拉卡金","暗色湖","道路","蜘蛛","石爪山脉","蛛网","蛛网小径"},ang={["class:Hunter"]="这条小径是强壮的雷蜥、健硕的高地公羊和有毒的织网蛛的家园，是侦察和驯服石爪山脉野兽的绝佳路径。",["faction:Horde"]="这条小径是位于玛拉卡金门前的一条重要陆路动脉，将你的斥候与石爪山脉更深处的山谷连接起来。"},sec={{t="一条危险的要道",b="蛛网小径从部落定居点玛拉卡金延伸至暗色湖，是穿过石爪山脉下部的主要道路之一。名副其实，这条路线以其高悬于树冠和锯齿状悬崖间的浓密蛛网而闻名。在这条蜿蜒的道路上旅行时，旅者必须时刻留意脚下，因为他们会与徘徊的山地蜘蛛、充满攻击性的雷蜥以及领地意识极强的公羊共用这条小径。"}},faq={{q="蛛网小径通向哪里？",a="蛛网小径在南部的暗矛巨魔前哨站玛拉卡金和北部山上的暗色湖之间延伸。",al={"蛛网小径位置","蛛网小径在哪里","蛛网小径连接哪里"}},{q="为什么它被称为蛛网小径？",a="这条路因该地区栖息着大量蛛形纲生物而得名。蜘蛛在树木高处和道路两侧的岩架上编织出了巨大的闪亮丝绸迷宫。",al={"为什么叫蛛网","为什么叫蛛网小径"}},{q="什么生物会在小径上游荡？",a="除了在道路上方织网的毒蜘蛛外，旅行者还经常会遇到游荡的雷蜥、高地公羊以及普通的高山生物。",al={"这里住着什么生物","蛛网小径野兽","蛛网小径怪物"}},{q="蛛网小径安全吗？",a="它远称不上安全。当地的掠食者凶猛且领地意识极强，而且这条路直接经过玛拉卡金部落营地，对于从贫瘠之地深入此地的联盟旅人来说十分危险。",al={"蛛网小径危险吗","联盟可以走蛛网小径吗"}}},fx={["4490b183"]={q="什么是蛛网小径？",a="蛛网小径是石爪山脉中的一条蜿蜒山路，构成从巨魔前哨玛拉卡金通往暗色湖的重要路线。它穿过嶙峋山峰和布满蛛网的树冠，是旅人深入山脉的重要通道，沿途尽是崎岖荒野和凶猛的本地野兽。",al={"什么是蛛网小径","蛛网小径的背景","石爪山脉蛛网小径"}}},fp="14,242,26.465.0,31.145.0,32.195.0,31.166.0,33.205.0"}
P.entries["subzone:weeping-cave"] = {n="哭泣之洞",s="哭泣之洞是一个污秽的地下洞穴，隐匿在西瘟疫之地东北部的山丘中，就在索多里尔河以西。它曾经是一个天然的洞穴系统，如今却渗满了有毒的瘟疫，并滋生着畸形的真菌怪兽和软泥怪。",h="哭泣之洞是一个污秽的地下洞穴，隐匿在西瘟疫之地东北部的山丘中，就在索多里尔河以西。它曾经是一个天然的洞穴系统，如今却渗满了有毒的瘟疫，并滋生着畸形的真菌怪兽和软泥怪。",kw={"腐烂的恐惧怪","软泥怪","腐朽的巨兽","躯壳","索多里尔河","哭泣之洞","西瘟疫之地"},ang={["class:Druid"]="哭泣之洞代表了自然界的一种怪诞扭曲，那里的地下植物群和元素能量已经被亡灵瘟疫彻底腐化，变成了暴力的怪兽。"},sec={{t="腐烂之穴",b="哭泣之洞开凿在索多里尔河上方的崎岖峭壁中，因其岩石天花板上不断滴落的水滴而得名——这些水早已变得恶臭且腐败。天灾军团的瘟疫彻底渗透了上方的土壤，将致命的污秽排入黑暗之中。洞穴内，腐烂的恐惧怪、腐朽的巨兽和腐蚀性的软泥怪在潮湿的隧道中游荡，还有一种神秘的被腐化的元素生物，人们简单地称它为“躯壳”。"}},faq={{q="哭泣之洞位于哪里？",a="哭泣之洞位于西瘟疫之地的东北角，坐落在索多里尔河以西、靠近东瘟疫之地边界的岩石山脊中。",al={"哭泣之洞位置","哭泣之洞在哪里","寻找哭泣之洞"}},{q="洞穴里住着什么生物？",a="洞穴中充斥着蹒跚而行的植物状憎恶体——例如腐朽的巨兽和腐烂的恐惧怪——以及有毒的爬行软泥怪，还有稀有的、受折磨的元素生物，被称为“躯壳”。",al={"哭泣之洞怪物","哭泣之洞里有什么","哭泣之洞生物"}},{q="为什么它被称为哭泣之洞？",a="洞穴的天花板不断滴落水分，看起来就像岩石在哭泣。然而，在瘟疫过后，这些径流变成了恶臭、腐败的渗出物，滋生了致命的真菌生长。",al={"为什么叫哭泣之洞","哭泣之洞名字含义"}},{q="“躯壳”是谁？",a="“躯壳”是一种稀有的被腐化的元素生物，栖息在哭泣之洞的深处，它被感染了周围土地和水源的残留炼金瘟疫所扭曲。",al={"躯壳","哭泣之洞的躯壳","稀有怪躯壳"}}},fp="12,256,12.485.0,34.189.0,37.198.0,34.226.0,16.188.0"}
P.entries["subzone:wellspring-lake"] = {n="涌泉湖",s="涌泉湖是位于泰达希尔枝干高处的一片宁静淡水湖，坐落在达纳苏斯东北方向。它由世界之树深处涌出的天然泉水补给，湖水流入蜿蜒的涌泉河。这里曾是暗夜精灵渔民的宁静隐居之所，但如今，湖岸已深受泰达希尔日益严重的腐蚀影响，野生动物也变得躁动不安。",h="涌泉湖是位于泰达希尔枝干高处的一片宁静淡水湖，坐落在达纳苏斯东北方向。它由世界之树深处涌出的天然泉水补给，湖水流入蜿蜒的涌泉河。这里曾是暗夜精灵渔民的宁静隐居之所，但如今，湖岸已深受泰达希尔日益严重的腐蚀影响，野生动物也...",kw={"达纳苏斯","卡多雷","夜刃豹","神谕林地","泰达希尔","树精","涌泉湖","涌泉河"},ang={["class:Druid"]="德鲁伊们研究涌泉湖附近的焦躁树精和野兽，以探寻在泰达希尔水域和土壤中蔓延的不自然疾病的根源。",["race:NightElf"]="对于卡多雷来说，像涌泉湖这样宁静的树林退化成危险的怪物巢穴，是一个痛苦的提醒，表明他们年轻的世界之树出了大问题。"},sec={{t="被玷污的避难所",b="Nestled beneath the canopy between Darnassus and the Oracle Glade, Wellspring Lake was long cherished by the Kaldorei as a quiet haven for fishing and contemplation. Its clear waters originate from subterranean springs running through the colossal boughs of the World Tree, which then drain northward through the Wellspring River. In recent times, however, an insidious blight has begun to seize the surrounding wilds. Aggressive spiders, prowling nightsabers, and agitated timberlings now roam the banks, making what was once an idyllic pond a treacherous place for unwary travelers."}},faq={{q="涌泉湖位于何处？",a="涌泉湖位于泰达希尔北部，达纳苏斯主城东北方向，神谕林地东南方向。",al={"涌泉湖在哪里","涌泉湖位置","如何前往涌泉湖"}},{q="湖水从何而来，又流向何处？",a="该湖由源自泰达希尔根部和木材深处的天然泉水补给。多余的湖水流入涌泉河，并向北流向树木的边缘。",al={"涌泉湖的排水去向","涌泉河源头","涌泉湖水源"}},{q="为什么涌泉湖周边地区很危险？",a="虽然这里曾是受卡多雷垂钓者青睐的宁静之地，但蔓延在世界之树各处的腐蚀已使当地野兽陷入疯狂。潜行的夜刃豹、巨型蛛网蜘蛛和被腐蚀的树精正在湖岸边徘徊。",al={"涌泉湖的生物","涌泉湖怪物","为什么涌泉湖充满敌意"}},{q="过去是谁聚集在涌泉湖？",a="在近来的枯萎病激怒野生动物并使湖岸变得危险之前，当地的暗夜精灵渔民经常造访该湖，进行静思和垂钓。",al={"涌泉湖历史","暗夜精灵渔民的湖泊"}}},fx={f7f79729={q="什么是涌泉湖？",a="涌泉湖是泰达希尔枝杈间的一片小湖，位于达纳苏斯东北方、神谕林地东南方。湖水由埋藏在世界之树深处的天然泉眼补给，继而流入涌泉河，滋养周围的林地。",al={"什么是涌泉湖","泰达希尔涌泉湖","涌泉湖简介"}},ce819020={q="涌泉湖为什么被遗弃了？",a="暗夜精灵渔民曾偏爱湖边宁静的岸畔，但世界之树各处日益加剧的腐化迫使他们离开。腐化的木灵如今栖居在湖水中，凶猛的夜刃豹和蜘蛛则在周边荒野游荡，让人无法再安宁地来此。",al={"涌泉湖为什么被遗弃","涌泉湖渔民","渔民为什么离开涌泉湖"}},["0645470a"]={q="涌泉湖危险吗？",a="是的。湖泊曾是宁静的垂钓胜地，如今却被敌对的腐化木灵占据。周边地带也不安全，灌木丛中遍布捕食性的夜刃豹和林木蜘蛛。",al={"涌泉湖危险吗","涌泉湖安全吗","涌泉湖的危险"}},["4ed9a160"]={q="为什么叫涌泉湖？",a="湖泊的名字源自它的水源：一处由泰达希尔根部和土壤深处涌出的天然泉眼。它也是涌泉河的源头，为枝杈间的中央水道带去生机。",al={"为什么叫涌泉湖","涌泉湖名称由来","涌泉湖名称含义"}}},fp="15,384,16.584.0,33.127.0,45.193.0,49.252.0,38.161.0"}
P.entries["subzone:wellspring-river"] = {n="涌泉河",s="涌泉河源自泰达希尔内的一处天然泉水，它从涌泉湖向北流淌，最终从巨树的枝叶间倾泻而下，形成一道直落下方大海的巍峨瀑布。这里曾经是世界之树生态系统中一处宁静的淡水来源，但如今受当地野生生物躁动的影响，河岸已变得危机四伏。",h="涌泉河源自泰达希尔内的一处天然泉水，它从涌泉湖向北流淌，最终从巨树的枝叶间倾泻而下，形成一道直落下方大海的巍峨瀑布。这里曾经是世界之树生态系统中一处宁静的淡水来源，但如今受当地野生生物躁动的影响，河岸已变得危机四伏。",kw={"卡多雷","泰达希尔","木喉熊怪","瀑布","涌泉湖","涌泉河"},ang={["class:Druid"]="这条河流原生木喉熊怪的腐化与疯狂状态，是泰达希尔生态系统中日益增长的病态所发出的令人不安的信号。",["race:NightElf"]="从泰达希尔中心流出的淡水水道代表了卡多雷新家园的活力，因此河岸边出现的动荡令他们深感担忧。"},sec={{t="世界之树的泉水",b="Nourished by the deep natural springs nestled in the boughs of Teldrassil, the Wellspring River carries water north from Wellspring Lake across the verdant forest floor before cascading dramatically over the edge of the great tree down into the sea below. Despite the serene surroundings, the riverbanks are increasingly unsafe. The timberlings that dwell along the water have grown crazed and hostile, violently attacking travelers and druids who attempt to draw near the river's edge."}},faq={{q="涌泉河通向哪里？",a="涌泉河从涌泉湖向北流淌。最终，它会到达泰达希尔树冠的边缘，并形成一道巨大的瀑布，一路直落坠入周围的大海。",al={"河流流向","涌泉河终点","涌泉河去向"}},{q="为什么河边的木喉熊怪会攻击人？",a="涌泉河沿岸的木喉熊怪变得反常且疯狂，它们会攻击任何靠近的生物。这种攻击性是泰达希尔野生生物中蔓延的更广泛动荡的一部分，令当地的暗夜精灵德鲁伊感到担忧。",al={"为什么木喉熊怪具有攻击性","疯狂的涌泉河木喉熊怪","为什么木喉熊怪怀有敌意"}},{q="河里的水从哪里来？",a="这条河流直接由涌泉湖补给，而涌泉湖本身则由世界之树树干和枝叶深处涌出的天然淡水泉所维持。",al={"涌泉水源","涌泉水的来源"}}},fx={cd3e3593={q="什么是涌泉河？",a="涌泉河是流经泰达希尔的一条重要淡水河。它发源于世界之树枝杈深处的一处天然泉眼，向北流出涌泉湖，将湖水带向北部峭壁，最终从巨大树冠的边缘倾泻而下，形成壮观的瀑布，流入下方海中。",al={"什么是涌泉河","介绍一下涌泉河","涌泉河的背景"}},fd48f2c1={q="为什么叫涌泉河？",al={"为什么叫涌泉河","涌泉河名称含义","涌泉名称由来"}}},fp="16,318,24.486.0,37.221.0,57.249.0,44.173.0"}
P.entries["subzone:westbrook-garrison"] = {n="西泉要塞",s="西泉要塞是位于艾尔文森林西缘、靠近西部荒野边界的一处暴风城卫兵哨所。在瑞尼尔副队长的指挥下，这里驻扎着一支人手不足、物资匮乏的精简小队，作为王国抵御不断入侵的河爪豺狼人和流寇的第一道防线。",h="西泉要塞是位于艾尔文森林西缘、靠近西部荒野边界的一处暴风城卫兵哨所。在瑞尼尔副队长的指挥下，这里驻扎着一支人手不足、物资匮乏的精简小队，作为王国抵御不断入侵的河爪豺狼人和流寇的第一道防线。",kw={"瑞尼尔副队长","艾尔文森林","林边空地","霍格","治安官杜汉","河爪豺狼人","西泉要塞","西部荒野"},ang={["class:Warrior"]="西泉要塞中那群身陷囹圄的卫兵展现出了王国在兵力透支的情况下，依然凭借坚韧不拔的意志抵御着荒野掠食者的侵袭，这里也提供了大量简单直接、残酷的清理豺狼人作战小队的任务。",["faction:Alliance"]="对于从艾尔文森林出发前往西部荒野的联盟勇士来说，保卫西泉要塞的周边地区并领取霍格的悬赏，对于确保王国腹地西部的边境安全至关重要。"},sec={{t="一座四面楚歌的边境哨所",b="西泉要塞坐落在艾尔文森林向西部荒野过渡的边缘地带，是一处重要但处境艰难的观察点。由于暴风城军队的大部分兵力被派往海外，或者被首都内的政治僵局所牵制，该哨所的兵力严重不足。瑞尼尔副队长和他手下的几名卫兵必须在巡逻西部道路的同时，还要抵御那些胆大妄为的窃贼，以及横行南部森林的凶残的河爪豺狼人。由于无法从闪金镇的治安官杜汉那里获得正式的增援，要塞几乎完全依赖往来的冒险者来确保大道的安全。"},{t="林边空地的威胁",b="西泉要塞面临的主要威胁是聚集在林边空地南部的豺狼人势力。这些豺狼人部族胆大妄为，甚至直接袭击补给线和农场，在臭名昭著的豺狼人首领霍格的组织下不断壮大。由于寡不敌众，且难以招架霍格部下的蛮力，要塞已经在辖区内悬赏重金，急切寻求有能力的战士前往山丘，在这些野兽进一步向东进犯之前将其击溃。"}},faq={{q="为什么西泉要塞的人手如此短缺？",a="暴风城军队的主力已部署在海外，而首都贵族议会内部的政治优柔寡断，导致地区哨所缺乏新鲜的兵源和补给。西泉要塞的指挥官必须极其依赖游历的冒险者来弥补人手不足的问题。",al={"为什么守卫这么少","西泉要塞增援","瑞尼尔副队长人手不足"}},{q="谁在指挥这座要塞？",a="瑞尼尔副队长负责监督西泉要塞的行动。他直接向驻扎在闪金镇的治安官杜汉汇报，但他请求增援士兵的申请大多石沉大海。",al={"谁领导西泉要塞","瑞尼尔副队长的职责","西泉要塞指挥官"}},{q="要塞面临哪些威胁？",a="要塞需要应对从西部荒野流窜出来的流寇，以及潜伏在周围森林中的凶残的河爪豺狼人，它们由危险的首领霍格领导。",al={"西泉要塞面临的威胁","西泉要塞的豺狼人","谁在攻击西泉要塞"}},{q="西泉要塞与西部荒野有何关联？",a="西泉要塞是艾尔文森林沿西行道路在跨过桥梁进入西部荒野前的最后一处哨所，负责守卫边境，抵御从西部蔓延而来的混乱。",al={"西泉要塞在西部荒野吗","西部荒野边界"}}},fx={["2e1647ed"]={q="什么是西泉要塞？",a="西泉要塞是暴风城卫兵的一座营房，位于艾尔文森林西部边境的林边空地附近。它隔河与西部荒野相望，守卫着连接首都腹地与西部平原的主要道路。这座军事前哨设有坚固的警戒塔和营房，如今却只能勉强充当最后一道防线，保护当地农庄免遭亡命徒和野生豺狼人的侵袭。",al={"什么是西泉","艾尔文森林西泉要塞","西泉要塞简介"}},["9e78a278"]={q="西泉要塞危险吗？",a="西泉要塞本身由暴风城卫兵把守，仍是安全的避难所，但周边荒野危机四伏。南面的树林里盘踞着凶残的河爪豺狼人族群，由怪物般的酋长霍格率领。此外，迪菲亚盗贼从西部荒野越境而来，劫掠旅人，因此离开要塞近旁的区域而不受护送十分危险。",al={"西泉危险吗","西泉的危险","西泉要塞安全吗"}}},fp="18,300,25.608.0,27.516.0,42.261.0,34.192.0,36.176.0,52.187.0"}
P.entries["subzone:westfall-lighthouse"] = {n="西部荒野灯塔",s="西部荒野灯塔坐落在西部荒野西南海岸外的一座岩石小岛上，曾指引过往船只避开无尽之海危险的浅滩。如今，这里已经没有活着的守塔人，他们都在臭名昭著的鱼人老瞎眼所领导的一场残酷袭击中丧生，只留下葛瑞森船长的灵魂继续守护着灯火。",h="西部荒野灯塔坐落在西部荒野西南海岸外的一座岩石小岛上，曾指引过往船只避开无尽之海危险的浅滩。如今，这里已经没有活着的守塔人，他们都在臭名昭著的鱼人老瞎眼所领导的一场残酷袭击中丧生，只留下葛瑞森船长的灵魂继续守护着灯火。",kw={"灯塔","葛瑞森船长","海岸","火焰","鱼人","老瞎眼","西部荒野"},ang={["faction:Alliance"]="这座灯塔是暴风城影响力衰退的鲜明象征，象征着那些孤立的王国仆从在没有军事支援的情况下，被遗弃给了野蛮的海岸野兽。"},sec={{t="迷雾中的灯塔",b="这座灯塔建在西部荒野险峻的西南峭壁上，长期以来一直为在暴风城附近海岸航行的船只提供安全指引。然而，随着该地区的法律与秩序逐渐崩溃，皇家巡逻队也日益减少，海岸危机四伏。最初是一家人负责照看灯塔，但咄咄逼人的鱼人部落将他们赶入了内陆。尽管他们勇敢地返回并重新点亮了灯塔，但臭名昭著的鱼人袭击者老瞎眼集结同类发动了第二次无情的猛攻，屠杀了那家人并熄灭了灯火。"},{t="幽灵守望者",b="那场悲剧发生后，灯塔并没有完全被遗弃。葛瑞森船长的幽灵如今徘徊在这片岩石露头上，被束缚在他无助地目睹那一家人惨死的地方。因为无法在灯火熄灭且海岸上爬满怪物的情况下安息，葛瑞森便招募过往的冒险者收集收割傀儡身上的油来维持火焰燃烧，并猎杀老瞎眼以替死去的守塔人复仇。"}},faq={{q="为什么西部荒野灯塔会被废弃？",a="原本看守灯塔的一家人类被当地的鱼人赶走了。当他们返回重新点亮灯塔时，老瞎眼领导了第二次袭击，在葛瑞森船长的注视下屠杀了全家人。",al={"守塔人遭遇了什么","谁住在灯塔","为什么它荒废了"}},{q="葛瑞森船长是谁？",a="葛瑞森船长是一个萦绕在灯塔外小岛上的幽灵。在目睹守塔人的死亡后，他因内疚和职责而深受束缚，他委托勇敢的旅者收集燃油来保持灯塔的亮光，并猎杀那些负有罪责的海岸鱼人。",al={"灯塔幽灵","幽灵是谁","葛瑞森船长背景故事"}},{q="老瞎眼是谁？",a="老瞎眼是一个异常狡猾且凶残的鱼人首领，他在西部荒野的海岸线上游荡。他集结了海岸部落占领了灯塔，并屠杀了守塔人。",al={"老瞎眼","鱼人首领","谁杀害了守塔人"}},{q="灯塔还在运作吗？",a="机械灯笼依然可以运作，在夜间向大海投射出一道扫掠的光束，而葛瑞森船长则会向旅者索要维持火焰燃烧所需的燃油。",al={"灯会亮吗","灯塔运作"}}},fx={c45dc608={q="西部荒野灯塔危险吗？",a="葛瑞森船长的幽灵守望着灯塔所在的小岛，岛上相对平静；但周围的海域和海滩遍布凶残的鱼人，其中包括臭名昭著的老瞎眼。毫无戒备的旅人若贸然涉水而过，很容易被鱼人团团围住。",al={"西部荒野灯塔安全吗","西部荒野灯塔危险吗","西部荒野灯塔有敌人吗"}},fe113f6d={q="什么是西部荒野灯塔？",a="西部荒野灯塔是一座孤立的海岸灯塔，矗立在西部荒野西南海岸外的一座岩石岛上。它原本用来为航海者指引方向，使他们安全通过无尽之海的险恶浅滩；如今灯塔大多已荒废，只能俯瞰被凶悍海岸鱼人占据的海岸线。",al={"什么是西部荒野灯塔","西部荒野灯塔","西部荒野灯塔简介"}},db6e5f33={q="西部荒野灯塔发生过什么事？",a="灯塔最初由一名人类看守者和他的家人照料。臭名昭著的鱼人老瞎眼将他们赶走；但当他们勇敢地回来重新点亮灯塔时，老瞎眼又率领鱼人发动了残酷的袭击。全家人在葛瑞森船长的幽灵注视下无力反抗，惨遭屠杀，灯塔也因此无人照料。",al={"西部荒野灯塔历史","这里发生过什么","灯塔惨剧"}}},fp="19,333,20.561.0,17.438.1,41.213.0,23.244.0,20.183.0,35.184.0"}
P.entries["subzone:whelgar-s-excavation-site"] = {n="维尔加挖掘场",s="维尔加挖掘场是位于湿地西侧山脚下的一处矮人考古挖掘点。本次探险旨在发掘古代泰坦遗物和史前秘密，但随着凶猛的斑点迅猛龙占领了采石场，探险队遭遇了灾难性的结局。幸存的挖掘者现在被困在挖掘场上方的一处山脊上，与他们的发掘成果隔绝。",h="维尔加挖掘场是位于湿地西侧山脚下的一处矮人考古挖掘点。本次探险旨在发掘古代泰坦遗物和史前秘密，但随着凶猛的斑点迅猛龙占领了采石场，探险队遭遇了灾难性的结局。幸存的挖掘者现在被困在挖掘场上方的一处山脊上，与他们的发掘成果隔...",kw={"挖掘场","挖掘","化石","迅猛龙","萨尔图斯","湿地","维尔加"},ang={["profession:Mining"]="巨大的露天采石场岩壁和出土的基岩为那些敢于在饥饿迅猛龙的咆哮下工作的矿工提供了绝佳的矿脉。",["race:Dwarf"]="任何被野兽占领而废弃的挖掘点都是对探险者协会的侮辱。收回维尔加的研究成果意味着捍卫你们的遗产，夺回被窃取的泰坦秘密。"},sec={{t="毁于一旦的探险",b="在勘察员的带领下，矮人试图寻找古代化石和土灵的秘密，并在米奈希尔港和丹莫德之间开凿出了一座巨大的采石场。然而，发掘出的史前残骸引来了当地斑点迅猛龙的愤怒。由于寡不敌众且装备不足，考古学家撤退到了挖掘场上方的一处山脊上，留下了帐篷、工具和散落在徘徊猛兽之间的出土文物。"}},faq={{q="挖掘场为何会被废弃？",a="矮人挖掘者无意中侵犯了具有攻击性的斑点迅猛龙的领地。被这些凶残的生物包围后，幸存的船员被迫撤退到挖掘场上方的一处山脊避难。",al={"为何废弃","挖掘场发生了什么","为何离开挖掘场"}},{q="矮人们在这里寻找什么？",a="矮人们在此挖掘史前化石和地下人工制品，希望能揭开关于他们泰坦血统以及世界遥远过去的线索。",al={"他们在挖掘什么","挖掘目的","维尔加挖掘场目标"}},{q="现在挖掘场里有什么威胁？",a="采石场底部和周围的山脊上到处都是斑点迅猛龙，包括可怕的迅猛龙萨尔图斯。",al={"挖掘场里有什么","挖掘场怪物","湿地的迅猛龙"}},{q="幸存的挖掘者去了哪里？",a="包括勘察员维尔加在内的幸存挖掘队被困在挖掘场上方的一处山脊上，他们正在寻求勇敢的冒险者来找回他们丢失的研究成果。",al={"维尔加在哪里","矮人在哪里","挖掘场幸存者位置"}}},fx={["4eb1142c"]={q="维尔加挖掘场是什么地方？",a="维尔加挖掘场是一处矮人考古发掘点，坐落在湿地山麓，位于米奈希尔港以东。矮人探险者在此寻找古代遗物和化石，但凶猛的本地掠食者将工人赶出了挖掘沟，发掘场也因此陷入困境。",al={"维尔加挖掘场","维尔加发掘点","维尔加挖掘场是什么地方"}},["65697e7b"]={q="维尔加挖掘场发生了什么？",a="这项起初前景大好的矮人考古事业，在挖掘惊动当地野生动物后急转直下。凶残的斑点迅猛龙涌入采石场，压制了营地里的人员，幸存的发掘者只得丢下工具、遗物和正在进行的研究，逃往更安全的地方。",al={"维尔加挖掘场的历史","维尔加挖掘场历史","发掘点发生了什么"}},["23dbaaa4"]={q="为什么叫维尔加挖掘场？",a="这处发掘点以率领探险队的矮人勘察员维尔加命名。他和幸存的队员如今躲在一处山脊上，俯瞰着遍布迅猛龙的采石场。",al={"维尔加是谁","维尔加名字的由来","为什么叫维尔加挖掘场"}}},fp="25,349,19.434.0,38.196.0,39.169.0,34.113.0,38.170.0"}
P.entries["subzone:whispering-forest"] = {n="耳语森林",s="耳语森林是一片僻静的山区林地，坐落在丧钟镇以西陡峭悬崖后的隐蔽处。它在很大程度上与提瑞斯法林地的其他地区隔绝，栖息着奇异的野生生物，拥有一处神秘的妖精之环，且深埋于土壤之下的邪恶腐蚀正在沉睡。",h="耳语森林是一片僻静的山区林地，坐落在丧钟镇以西陡峭悬崖后的隐蔽处。它在很大程度上与提瑞斯法林地的其他地区隔绝，栖息着奇异的野生生物，拥有一处神秘的妖精之环，且深埋于土壤之下的邪恶腐蚀正在沉睡。",kw={"班达里安堡","凋零收割者","丧钟镇","妖精之环","影谷","提瑞斯法","耳语森林"},ang={["class:Druid"]="发光的妖精之环是饱受摧残的洛丹伦中仅存的少数自然魔法脉动之一。",["race:Undead"]="这片僻静的林地坐落在丧钟镇之后，由班达里安堡的提尔之卫所监视，隐藏着被遗忘的危险，对幽暗城门口构成了无声的威胁。"},sec={{t="隐秘幽谷",b="耳语森林藏在北面岩石和班达里安堡之后，与周围饱受瘟疫蹂躏的王国显得格格不入。虽然这里有受感染的鹿和四处游荡的掠食者，但也有宁静的湖泊和一圈奇怪的巨型蘑菇，在悬浮的薄雾下散发着诡异的能量。幽灵般的哀伤骑士受誓言所缚，在妖精之环中徘徊，置身于一种似乎在对抗被天灾摧毁的土地的自然魔法之中。"},{t="林木之下的阴影",b="尽管外表奇妙，这片森林却被一种古老的恐惧所玷污。几个世纪前，高等精灵曾试图在提瑞斯法林地定居，但不久后许多人开始发疯；一些人认为某种邪恶蛰伏在这片土地之下，尽管这些传言从未被证实。在当地的湖泊周围，邪鳍鱼人和亡灵鞭笞者“凋零收割者”在水中徘徊，而影谷的废弃定居点则被死灵残留物所摧残。就连整个洛丹伦的疯狂流浪者都在低声发出恐惧的警告，诉说着蛰伏在提瑞斯法根基之下的吞噬黑暗。"}},faq={{q="耳语森林位于哪里？",a="森林位于提瑞斯法林地西部的群山之中，坐落在丧钟镇以西、提尔之陨以南的位置。它被北面岩石，即班达里安堡所在的陡峭山脊所阻隔。",al={"耳语森林位置","耳语森林在哪里","如何前往耳语森林"}},{q="在巨型蘑菇之环发生了什么？",a="巨型蘑菇之环在悬浮的薄雾下散发着奇异的能量。幽灵般的哀伤骑士受誓言所缚，在圆环中徘徊，但圆环的魔法真相仍然无人知晓。",al={"提瑞斯法蘑菇之环","妖精龙之环","妖精之环仪式"}},{q="谁在守护这片森林？",a="俯瞰的高地班达里安堡由提尔之卫把守，这是一个被遗忘者圣骑士组织。在妖精之环附近，幽灵般的哀伤骑士受誓言所缚，在林中徘徊。",al={"谁守卫耳语森林","班达里安堡耳语森林"}},{q="为什么高等精灵很久以前就放弃了这片区域？",a="当高等精灵最初登陆洛丹伦海岸时，他们曾试图在提瑞斯法建立定居点。几年之内，许多人开始发疯。一些人推测有某种邪恶蛰伏在这片土地之下，尽管传言从未得到证实，但精灵们还是放弃了林地并向北迁徙。",al={"提瑞斯法高等精灵","精灵为何离开提瑞斯法","提瑞斯法之下的疯狂"}},{q="什么是影谷？",a="影谷是一座位于森林湖泊西南方的废弃村庄。它被“玷污者”以及受到死灵水晶碎片影响而失去心智的亡灵所占据，这些碎片可追溯到涉及幽暗城的冲突时期。",al={"提瑞斯法影谷","耳语森林废弃村庄"}}},fx={d118db82={q="耳语森林是什么地方？",a="耳语森林是一片隐秘的林地，笼罩在迷雾之中，藏于提瑞斯法林地西部陡峭的群山之外。北面岩石的高处将它与该地区其他地方隔开。这里是一片阴森、未受驯服的荒野，栖息着染病的野兽，散布着神秘的仙灵之环、被遗忘的遗迹，以及与寻常道路隔绝的僻静山湖。",al={"耳语森林是什么地方","耳语森林传说","介绍耳语森林"}},["4326a394"]={q="耳语森林危险吗？",a="危险至极。除了病态的染病野兽，悬崖和水域也遍布被驱逐的邪鳍鱼人，以及名为“疫病剥皮者”的可怕亡灵裂腭龙。再往内陆，毫无心智的亡灵盘踞在影谷遗迹中，徘徊于一块坠落的通灵水晶碎片周围；敌对的褪色教徒则潜伏在遭受腐化的树林间。",al={"耳语森林危险吗","耳语森林安全吗","耳语森林的威胁"}}},fp="17,273,15.481.0,28.566.1,39.205.0,42.216.0,28.197.0,52.311.0,19.221.0"}
P.entries["subzone:whispering-gardens"] = {n="耳语花园",s="耳语花园坐落于提瑞斯法林地东北部，血色修道院南侧的梯田山坡上。这里曾是一处静谧沉思之地，后来却成为早期十字军防御者与大批天灾军团激战的场所。如今，十字军在杂草丛生的路径上巡逻，而逝者的微弱声音依然在空气中回荡。",h="耳语花园坐落于提瑞斯法林地东北部，血色修道院南侧的梯田山坡上。这里曾是一处静谧沉思之地，后来却成为早期十字军防御者与大批天灾军团激战的场所。如今，十字军在杂草丛生的路径上巡逻，而逝者的微弱声音依然在空气中回荡。",kw={"血色十字军","血色修道院","天灾军团","提瑞斯法林地","耳语花园","低语"},ang={["class:Priest"]="走在梯田上的牧师们能感受到那些在对抗天灾军团时惨遭杀戮的神圣防御者所留下的精神残余，他们的灵魂永远被束缚在风中。",["race:Undead"]="对于被遗忘者而言，这些花园代表着在提瑞斯法家门口依然存在的血色狂热抵抗势力，这里深受那场导致洛丹伦毁灭的战争所困扰。"},sec={{t="迷雾中回响的战役",b="在血色十字军完全撤回修道院的堡垒围墙后方之前，一场激烈的战斗曾在这片梯田斜坡上爆发，对抗着一支来犯的亡灵军队。这场冲突令双方都损失惨重。在暮色中，穿行于花园的旅者们称能在风中听到奇怪而轻柔的低语——据信那是为了保卫圣地而牺牲的士兵与牧师们不安的残响。"},{t="十字军前哨",b="尽管这里阴魂不散，血色十字军仍对花园保持着严密的监视。血色侦察兵、法师和卫护者们守卫着小径，以拦截任何从下方的林地接近的入侵者。对于附近修道院里的狂热信徒而言，这些杂草丛生的台阶既是防御壁垒，也是对抗亡灵永无止境战争的庄严警示。"}},faq={{q="耳语花园在哪里？",a="耳语花园位于提瑞斯法林地东北部，覆盖着血色修道院入口正南方的山坡。",al={"耳语花园位置","耳语花园在哪里","如何前往耳语花园"}},{q="为什么这里被称为耳语花园？",a="这个名字来源于暮色空气中听到的微弱、幽灵般的低语，据说那是曾在这片斜坡上的一场血战中阵亡的防御者与亡灵们挥之不去的灵魂。",al={"为什么叫耳语花园","耳语是什么","耳语花园名称"}},{q="这里发生过什么战役？",a="在这里，后来成为血色十字军的早期部队曾与一支入侵的天灾军团军队展开过一场绝望的战斗。天灾军团在修道院外被阻止之前，双方都有无数人丧生。",al={"耳语花园之战","耳语花园发生了什么"}},{q="现在是谁控制着这些花园？",a="血色十字军控制着这片区域。血色侦察兵、卫护者和法师们在梯田上巡逻，以确保他们据点南侧入口的安全。",al={"谁住在耳语花园","耳语花园的怪物"}}},fx={["3774f1a6"]={q="耳语花园是什么地方？",a="耳语花园是提瑞斯法林地东北部的一处肃穆山坡台地，正位于血色修道院入口以南。这片台地曾经宁静祥和，如今却成了血色十字军狂热部队的外围防御哨所和集结地，他们在此俯瞰周围的林地。",al={"耳语花园是什么地方","耳语花园传说"}},["7713d5ca"]={q="耳语花园有多危险？",a="对任何外来者来说，这里都极其危险。血色十字军在整片台地布下严密守卫，沿途驻扎着法师、守护者和斥候。他们被狂热的猜疑所驱使，发现任何未宣誓效忠的人都会当场处决，并将所有外来者都视为携带亡灵瘟疫之人。",al={"耳语花园危险吗","耳语花园的危险","耳语花园的威胁"}}},fp="18,364,28.432.0,16.379.0,41.143.0,43.180.0,28.211.0,29.156.0"}
P.entries["subzone:whispering-shore"] = {n="耳语海岸",s="耳语海岸是一片位于提瑞斯法林地西部，索利丹农场正北方的阴郁海岸线。这里曾经是洛丹伦渔民宁静而富饶的休憩之所，但如今，冰冷的水域已被一群凶暴的鱼人占据。",h="耳语海岸是一片位于提瑞斯法林地西部，索利丹农场正北方的阴郁海岸线。这里曾经是洛丹伦渔民宁静而富饶的休憩之所，但如今，冰冷的水域已被一群凶暴的鱼人占据。",kw={"海岸","垂钓","穆阿德","鱼人","索利丹农场","提瑞斯法林地","耳语海岸"},ang={["race:Undead"]="对于正在巩固提瑞斯法林地西部防线的被遗忘者来说，耳语海岸的鱼人滋扰构成了对其领地边缘的一大不稳定威胁。"},sec={{t="一处废弃的避风港",b="在第三次战争席卷北洛丹伦之前，耳语海岸以其平静的水域和丰富的渔获而闻名，是当地深受青睐的捕鱼港湾。如今，无尽之海冰冷的浪花拍打着空寂的海岸，昔日的宁静已荡然无存。这里的海水变得阴冷幽暗，失去了往日的富饶，任何从山上走下来的不幸旅人都可能遭到领地意识极强的海岸居民的伏击。"},{t="鱼人威胁",b="海滩现在已被一群充满敌意的鱼人牢牢控制，他们无情地攻击任何靠近海岸的人。这些水生拾荒者由一位名叫穆阿德的凶猛酋长领导，他们积极守卫着浅滩和潮间带，对附近的道路和周边的索利丹农场构成了持续的威胁。"}},faq={{q="耳语海岸位于何处？",a="耳语海岸位于提瑞斯法林地的西海岸，就在索利丹农场的正北方。",al={"耳语海岸位置","耳语海岸在哪里","耳语海岸地图"}},{q="天灾军团入侵前，耳语海岸是什么样的地方？",a="在洛丹伦王国时期，这片海岸是深受当地渔民喜爱的一处宁静之地，丰富的沿海水产吸引了许多人前来。",al={"耳语海岸历史","耳语海岸用途","耳语海岸过去"}},{q="现在是谁控制着耳语海岸？",a="一群极具侵略性的鱼人已经占领了这条海岸线。他们由一位名叫穆阿德的残暴鱼人酋长领导，攻击任何靠近水域的人。",al={"耳语海岸居民","耳语海岸敌人","耳语海岸怪物"}},{q="现在还能在耳语海岸安稳地钓鱼吗？",a="这里已不再是曾经那片宁静的避风港。海水变得阴冷幽暗，往日的鱼产已大不如前，且有充满敌意的鱼人在此严加把守。",al={"耳语海岸垂钓","耳语海岸鱼类"}}},fx={a19e4211={q="耳语海岸是什么地方？",a="耳语海岸是提瑞斯法林地西部的一片阴冷黑暗的海岸，位于索利丹农场以北。这里曾是当地渔民熟知的宁静丰饶之地，但遭受腐化的海岸如今已沦为一片废墟和混乱之地，平民昔日享受的宁静海水所剩无几。",al={"耳语海岸传说","耳语海岸是什么地方","介绍耳语海岸"}},["84b8417d"]={q="耳语海岸危险吗？",a="是的，毫无戒备的旅人身处此地会极其危险。如今，一群由凶残的穆阿德率领、贪婪嗜血的鱼人占据了这片海岸。这些生物会猛烈攻击任何靠近浪潮的人，使海岸不再适宜活人定居，也令途经提瑞斯法西部的人面临危险。",al={"耳语海岸安全吗","耳语海岸的威胁","耳语海岸的危险"}},bea21c89={q="耳语海岸为什么被遗弃？",a="洛丹伦沦陷于天灾军团、提瑞斯法林地遭到腐化之后，曾经丰饶的渔场变得阴冷、黑暗而贫瘠。失去安居者维护的海岸很快被掠食性鱼人占据，它们霸占了海岸线，驱逐了所有可能想要返回的人。",al={"耳语海岸为何荒废","是什么毁了耳语海岸","耳语海岸为何被遗弃"}}},fp="16,263,14.468.0,17.299.0,38.111.0,59.136.0,38.171.0,54.183.0"}
P.entries["subzone:whitereach-post"] = {n="白沙岗哨",s="白沙岗哨是位于千针石林尘土飞扬的峡谷小径旁的一个小型部落营地。作为伊索克营地附近的一个小型中转站，它为这条严酷的沙漠公路提供了休憩之所和警惕的守望。对于往返于菲拉斯和盐碱平原的旅行者来说，它是矗立在耸立的砂岩石柱下的一处安全部落哨所。",h="白沙岗哨是位于千针石林尘土飞扬的峡谷小径旁的一个小型部落营地。作为伊索克营地附近的一个小型中转站，它为这条严酷的沙漠公路提供了休憩之所和警惕的守望。对于往返于菲拉斯和盐碱平原的旅行者来说，它是矗立在耸立的砂岩石柱下的一处...",kw={"伊索克营地","部落哨所","卡纳提·灰云","牛头人","千针石林","白沙岗哨"},ang={["faction:Horde"]="白沙岗哨是部落旅行者穿越千针石林险峻峡谷时的重要休息点和斥候驻点。",["race:Tauren"]="牛头人斥候协助守卫这个路边营地，确保往返于莫高雷、菲拉斯和闪光平原的族人有一个安全的地方可以休息。"},sec={{t="峡谷中的中转站",b="白沙岗哨坐落在蜿蜒穿过千针石林深处的既定小径旁，是开辟在崎岖地貌上的几个朴素的部落据点之一。该岗哨驻扎在伊索克营地附近，有助于在峡谷底部维持可靠的军事存在，监控着被风吹拂的台地之间的交通。虽然它不如升降梯或主要的部落定居点那样坚固，但对于穿越这些充满争端的荒野的信使、斥候和冒险者来说，它是一个不可或缺的落脚点。"}},faq={{q="什么是白沙岗哨？",a="白沙岗哨是位于千针石林主峡谷小径旁的一个小型部落哨所，距离伊索克营地不远。",al={"白沙岗哨","白沙岗哨营地","白沙岗哨在哪里"}},{q="哪个阵营控制着白沙岗哨？",a="它由部落控制，主要由负责守望峡谷小径的牛头人斥候维护。",al={"白沙岗哨是部落的吗","白沙岗哨阵营"}},{q="这里驻扎着什么人？",a="该岗哨由当地的部落斥候和流浪者驻守，其中包括看守峡谷通道的牛头人卡纳提·灰云。",al={"白沙岗哨npc","谁住在白沙岗哨"}}},fp="15,351,27.506.0,24.134.0,39.105.0,32.131.0"}
P.entries["subzone:wild-shore"] = {n="蛮荒海岸",s="蛮荒海岸是荆棘谷最南端的海岸线，丛林在此处与南海的波涛相遇。这里是血帆海盗的集结地和锚地，他们的船只停泊在浅滩沿岸。",h="蛮荒海岸是荆棘谷最南端的海岸线，丛林在此处与南海的波涛相遇。这里是血帆海盗的集结地和锚地，他们的船只停泊在浅滩沿岸。",kw={"血帆海盗","藏宝海湾","戈拉什","哈圭罗岛","海盗","南海","荆棘谷","蛮荒海岸"},ang={["class:Rogue"]="血帆海盗的营地和锚泊的船只提供了扒窃的机会，也是研究在热砂港法律之外活动的竞争对手剑客的契机。"},sec={{t="南海之滨",b="Stretching along the bottom tip of the continent, the Wild Shore marks the border where Stranglethorn Vale plunges into the South Seas. To the northwest lies the fortified inlet of Booty Bay, while a shallow ocean strait separates the mainland beach from Jaguero Isle to the east. The beach continues northeast toward the Crystal Shore. Because of its secluded position away from the Blackwater Raiders' direct cannons, the coast has become a hotbed of piratical activity and wild perils."},{t="海盗与巨人",b="这条海岸被血帆海盗重兵占据，他们将木制船只停泊在浪中，并在沙滩上安营扎寨。这些剑客利用海滩进行行动、储存非法货物，并策划针对地精竞争对手的袭击。旅行者还必须应对海岸的自然危害，包括徘徊的野兽，以及在浪中践踏、碾碎任何在潮汐线附近逗留者的巨型海巨人戈拉什。"}},faq={{q="蛮荒海岸位于哪里？",a="蛮荒海岸构成了东部王国荆棘谷的最南端海岸线。它位于藏宝海湾以南，隔着南海眺望哈圭罗岛。",al={"蛮荒海岸位置","蛮荒海岸在哪里","蛮荒海岸地图"}},{q="谁控制着蛮荒海岸？",a="血帆海盗统治着这条海岸线。他们将数艘船只停泊在浅水中，并在沙滩上维持着营地。",al={"谁居住在蛮荒海岸","蛮荒海岸势力","蛮荒海岸海盗"}},{q="戈拉什是谁？",a="戈拉什是一位巨大的海巨人，在蛮荒海岸的浅滩游荡，威胁着毫无防备的水手和行走在海滩上的海盗。",al={"巨人戈拉什","海滩上的巨人是谁","蛮荒海岸戈拉什"}},{q="蛮荒海岸与藏宝海湾有何关联？",a="一处岩石岬角将藏宝海湾与蛮荒海岸隔开。藏宝海湾是黑水强盗和热砂港的据点，使得附近的蛮荒海岸成为他们死敌血帆海盗的天然集结地。",al={"藏宝海湾连接","蛮荒海岸藏宝海湾"}}},fp="10,236,22.488.0,18.462.0,32.178.0,28.153.0,15.141.0,44.249.0"}
P.entries["subzone:wildbend-river"] = {n="急弯河",s="急弯河是一条蜿蜒穿过黑海岸南部森林，流经古树之林附近的受污染水道。它的河水源源不断地从饱受腐蚀的费伍德森林高地流下，将恶魔毒素带向大海，威胁着周边的荒野。",h="急弯河是一条蜿蜒穿过黑海岸南部森林，流经古树之林附近的受污染水道。它的河水源源不断地从饱受腐蚀的费伍德森林高地流下，将恶魔毒素带向大海，威胁着周边的荒野。",kw={"血毒河","黑海岸","费伍德森林","古树之林","受污染的水","急弯河"},ang={["class:Druid"]="研究第三次战争生态后果的德鲁伊们一直警惕地注视着这条河，监测着费伍德森林的腐蚀对下游动植物的影响程度。",["race:NightElf"]="从费伍德森林倾泻而下的受污染河水威胁着黑海岸的古老根系，这使得河岸成为了暗夜精灵守望者们经常关注的问题。"},sec={{t="一条有毒的山间溪流",b="急弯河横穿黑海岸南部，一路向西流过神圣的古树之林，最终汇入大海。它非但没有给林地带来纯净的滋养，反而从山上带来了腐蚀。这条河流是费伍德森林的血毒河的直接延续，它奔流过岩石山脊，将污秽的、腐败的径流带入了黑海岸的生态系统。暗夜精灵严密监控着河岸，警惕着扭曲的野生动物和不断蔓延的恶魔枯萎病。"}},faq={{q="为什么急弯河会受到腐蚀？",a="这条河发源于费伍德森林的高山之中，在那里它被称为血毒河。在第三次战争期间，费伍德森林彻底被恶魔魔法所侵蚀，这些污秽的径流沿着悬崖倾泻而下，进入黑海岸形成了急弯河。",al={"为什么水被污染了","急弯河毒素","黑海岸脏水"}},{q="这条河向哪里流去？",a="河流从隔开费伍德森林和黑海岸的东部山脊倾泻而下，蜿蜒穿过黑海岸南部，流经古树之林附近，最终汇入迷雾之海。",al={"急弯河在哪里","急弯河路径","急弯河位置"}},{q="这条河是否影响古树之林？",a="河流流经古树之林附近，对扎根于此的古老守护者构成了持续的环境威胁。暗夜精灵不知疲倦地努力控制枯萎病，防止被污染的水腐蚀这些神圣的树林。",al={"古树之林水源","古树之林是否受到腐蚀"}}},fx={["842d63ec"]={q="急弯河是什么地方？",a="急弯河是一条遭到腐化的水道，蜿蜒流经黑海岸南部，靠近古树之林。它发源于遭受腐化的费伍德森林高地，作为血毒河的下游延续，从山上奔流而下，最终一路流向大海。",al={"急弯河是什么地方","急弯河","关于急弯河"}},["96fc4b9b"]={q="急弯河危险吗？",a="是的，河水污浊不堪，险象环生。急弯河是费伍德森林血毒河的下游延续，恶魔腐化会从受污染的高地一路流入黑海岸，污染周边环境，并威胁附近的神圣林地。",al={"急弯河危险吗","急弯河的危险","急弯河安全吗"}}},fp="14,267,23.531.0,36.253.0,26.186.0,48.248.0"}
P.entries["subzone:wildmane-water-well"] = {n="蛮鬃水井",s="蛮鬃水井是散布在莫高雷各处的圣泉中最北边的一口，位于雷霆崖台地的正北方。它对于这片平原及其畜群至关重要，如今却成了想要扼杀牛头人生命线的地精投机者们争夺的焦点。",h="蛮鬃水井是散布在莫高雷各处的圣泉中最北边的一口，位于雷霆崖台地的正北方。它对于这片平原及其畜群至关重要，如今却成了想要扼杀牛头人生命线的地精投机者们争夺的焦点。",kw={"莫高雷","圣泉","雷霆崖","荆棘谷地精","水井","蛮鬃"},ang={["class:Druid"]="地精腐蚀莫高雷淡水的企图威胁到了平原上微妙的平衡，需要德鲁伊保持警惕来净化并治愈这片土地。",["race:Tauren"]="莫高雷的圣泉是大地母亲的馈赠。保护蛮鬃水井免受亵渎和毒害，是每一位年轻勇士的神圣职责。"},sec={{t="岌岌可危的生命线",b="世世代代以来，游牧的牛头人一直依赖挖掘在莫高雷金色平原上的圣泉来供养族人和他们漫游的科多兽群。蛮鬃水井守护着雷霆崖阴影之外的北部旷野。由于其至关重要的地位，它成了部落敌人们眼中无法抗拒的目标。荆棘谷地精用毒药污染了这里，试图控制该地区的供水，只有通过牛头人制作的图腾进行净化仪式，才能让泉水恢复纯净。"}},faq={{q="蛮鬃水井位于哪里？",a="蛮鬃水井位于莫高雷的平原上，就在高耸的雷霆崖台地正北方。它是维持该地区生存的圣泉中最靠北的一口。",al={"蛮鬃水井位置","蛮鬃水井在哪里","蛮鬃水井地图"}},{q="为什么这口水井对牛头人很重要？",a="在平原上，淡水就是生命。牛头人将这片土地上的水井视为维系定居点、旅行猎人以及漫游在莫高雷平原上的巨大科多兽群的重要生命线，并对其保持敬畏。",al={"牛头人为什么关心这口水井","蛮鬃水井神圣"}},{q="谁试图破坏或控制这口水井？",a="荆棘谷地精毒害了这口水井，试图控制莫高雷的供水，牛头人必须用神圣的图腾将其净化。",al={"谁袭击了水井","蛮鬃水井的敌人","谁毒害了蛮鬃水井"}}},fx={["6d5f57b0"]={q="蛮鬃水井是什么地方？",a="蛮鬃水井是滋养莫高雷牛头人的神圣水井中最北面的一口，位于雷霆崖下方的峭壁以北。它为平原和牲畜提供洁净而重要的水源，是各部族在这片祖传土地上安居的重要命脉与圣地。",al={"蛮鬃水井是什么地方","蛮鬃水井信息","莫高雷蛮鬃水井"}},["92d8374e"]={q="蛮鬃水井发生了什么？",a="荆棘谷地精公司的地精夺取了这口水井，并用毒药污染井水，企图控制莫高雷的供水。牛头人将他们赶走后，如今必须用神圣图腾净化水井，才能让洁净的水重新流淌。",al={"蛮鬃水井的历史","蛮鬃水井发生了什么"}},d4e90335={q="蛮鬃水井危险吗？",a="危险。水井本身是牛头人的宁静圣地，但井水已被荆棘谷地精公司的毒药污染，草原狼和其他掠食者也在周围的平原上出没。靠近时应保持警惕，并在水井净化之前避免饮用受污染的水。",al={"蛮鬃水井危险吗","蛮鬃水井的危险","蛮鬃水井的威胁"}}},fp="19,292,23.543.0,41.184.0,40.191.0,46.157.0"}
P.entries["subzone:windbreak-canyon"] = {n="风裂峡谷",s="风裂峡谷是位于千针石林北侧的一条蜿蜒峡谷，坐落在乱风岗和闪光平原之间。这里以强劲的气流和锯齿状的岩石而闻名，大量筑巢的风蛇盘踞于此。沿着主路行进的旅人必须在峡谷入口处小心谨慎，以免遭到来自上空的猎食。",h="风裂峡谷是位于千针石林北侧的一条蜿蜒峡谷，坐落在乱风岗和闪光平原之间。这里以强劲的气流和锯齿状的岩石而闻名，大量筑巢的风蛇盘踞于此。沿着主路行进的旅人必须在峡谷入口处小心谨慎，以免遭到来自上空的猎食。",kw={"乱风岗","千针石林","老屋","风蛇","风裂峡谷"},ang={["class:Hunter"]="盘踞在整个峡谷中的风蛇为荒野猎人提供了一个理想的机会，让他们得以研究并驯服这些敏捷且能喷射闪电的野兽。"},sec={{t="石林中的蛇巢",b="风裂峡谷开凿在峡谷底部陡峭的北侧岩壁上，横跨了乱风岗以东的一大片区域。这道峡谷不但无法提供庇护，反而会汇聚气流在石塔间发出呼啸声，为野生的风蛇创造了理想的栖息地。这些掠食者在岩架上产卵，并会袭击那些偏离主路、毫无防备的旅人。勇敢深入峡谷内部的冒险者还能找到通往老屋的蜿蜒小径。"}},faq={{q="风裂峡谷在哪里？",a="风裂峡谷位于千针石林的北侧，大致坐落在乱风岗与通往闪光平原的东侧入口之间。",al={"风裂峡谷位置","风裂峡谷在哪里","风裂地图"}},{q="风裂峡谷里生活着什么生物？",a="峡谷中主要栖息着极具攻击性的野生风蛇，它们在岩壁间筑巢，并会为了保护巢穴而攻击入侵者。",al={"风裂怪物","风裂峡谷里有什么","风裂野怪"}},{q="峡谷内的小径通往何处？",a="沿着峡谷内向上延伸的小径行进，可以将旅人引向位于上方悬崖中的老屋。",al={"风裂路径","风裂峡谷中的小径","风裂通向哪里"}}},fx={["7c7f9a22"]={q="风裂峡谷是什么地方？",al={"风裂峡谷是什么地方","风裂峡谷概况","介绍风裂峡谷"}},["4bddac98"]={q="风裂峡谷危险吗？",a="危险。峡谷岩地和峭壁上到处都是守护巢穴的野生风蛇。任何途经峡谷前往老屋的人都必须保持警惕，因为这些领地意识极强的野兽会迅速袭击任何靠近幼崽的入侵者。",al={"风裂峡谷危险吗","风裂峡谷的危险","风裂峡谷的威胁"}}},fp="16,342,29.499.0,26.143.0,40.124.0,44.116.0"}
P.entries["subzone:windfury-ridge"] = {n="狂风山",s="狂风山是莫高雷牧场边缘的一片崎岖高地。这里以盘踞着凶恶的鹰身人以及捕食性的狼和美洲狮而闻名，对旅行者来说是一处持续的威胁，但同时也为牛头人工匠提供了珍贵的羽毛。",h="狂风山是莫高雷牧场边缘的一片崎岖高地。这里以盘踞着凶恶的鹰身人以及捕食性的狼和美洲狮而闻名，对旅行者来说是一处持续的威胁，但同时也为牛头人工匠提供了珍贵的羽毛。",kw={"美洲狮","羽毛","鹰身人","莫高雷","雷霆崖","狂风","狂风山"},ang={["class:Hunter"]="陡峭的山坡和狡猾的捕食者为追踪、驯兽和野外生存提供了一处极佳的早期试炼场。",["race:Tauren"]="狂风山对年轻的猎人来说既是一个反复出现的麻烦，也是获取用于纪念婚姻和季节性聚会的关键仪式装饰品的来源。"},sec={{t="险峻栖木",b="狂风山高耸于莫高雷宁静的平原之上，是狂风鹰身人的狩猎场。这些凶猛的带翼生物在高耸的峭壁上筑巢，随时准备俯冲攻击任何靠近山脚的粗心漫游者。岩石嶙峋的地形中还栖息着徘徊的草原狼和野生山地美洲狮，使这里成为了牛头人领地中最危险的边界之一。尽管危险重重，勇敢的牛头人战士仍经常猎杀这些鹰身人；它们色彩斑斓、带有虹彩的羽毛在雷霆崖广受欢迎，常被用于装饰庆典和婚礼的礼服。"}},faq={{q="是什么让狂风山如此危险？",a="这里不仅出没着捕食性的美洲狮和草原狼，最主要的威胁还是盘踞在高处的一群群极具侵略性的鹰身人。它们会从峭壁上俯冲而下，捕捉或屠杀任何靠得太近的入侵者。",al={"为什么狂风山很危险","狂风山的危险因素","狂风山的怪物"}},{q="为什么牛头人要猎杀狂风山的鹰身人？",a="除了保护边界免受它们侵扰之外，牛头人猎杀狂风鹰身人还是为了获得它们绚丽的羽毛。这些色彩鲜艳的羽毛通常被采集起来，编织成用于节庆和婚礼的仪式头饰和装饰品。",al={"为什么要猎杀狂风鹰身人","莫高雷鹰身人羽毛","猎杀鹰身人"}},{q="狂风山位于哪里？",a="狂风山位于莫高雷牧场区域的高耸峭壁沿线，处于莫高雷的最北端，雷霆崖之外。",al={"狂风山位置","狂风山在哪里","狂风山地图"}}},fx={d25e422a={q="狂风山是什么地方？",a="狂风山是莫高雷山丘中的一片崎岖高地。这里主要是凶猛鹰身人的栖息地，高地上危机四伏，致命的掠食者时常出没，谨慎的旅人通常会绕道而行。",al={"狂风山是什么地方","狂风山信息","关于狂风山"}},["52a38b39"]={q="谁住在狂风山？",a="狂风鹰身人占据并严密守卫着这片山脊，在峭壁间筑巢。除了这些长着翅膀的食腐者，潜行的美洲狮和野狼也会在山坡上四处游荡，猎食任何靠近山丘的生物。",al={"谁住在狂风山","狂风山的居民","狂风山的生物"}}},fp="14,245,16.644.0,36.267.0,53.250.0,32.131.0"}
P.entries["subzone:windshear-crag"] = {n="狂风峭壁",s="狂风峭壁是位于石爪山脉中部的一处严重受损的山谷，其古老的树木已被荆棘谷地精洗劫一空。这里曾是一片茂密的森林，如今却成了工业荒地，充斥着轰鸣的伐木机、浑浊的径流和咄咄逼人的伐木队。在机械的阴影下，当地的狗头人正在挖掘矿石，而山路将这片满目疮痍的土地与灰谷连接在了一起。",h="狂风峭壁是位于石爪山脉中部的一处严重受损的山谷，其古老的树木已被荆棘谷地精洗劫一空。这里曾是一片茂密的森林，如今却成了工业荒地，充斥着轰鸣的伐木机、浑浊的径流和咄咄逼人的伐木队。在机械的阴影下，当地的狗头人正在挖掘矿石，...",kw={"布劳格·幽魂","峭壁湖","格伦佐·扳手哨","超级收割机6000型","石爪小径","荆棘谷地精","狂风峭壁","狂风矿洞","兹兹·费兹克斯"},ang={["faction:Horde"]="前往灰谷的部落旅行者会在石爪小径附近遇到布劳格·幽魂，他会考验他们对卡利姆多历史的了解。",["profession:Engineering"]="整个峭壁上的工业设备展示了哥布林残酷的商业机密和格伦佐·扳手哨致命的超级收割机设计。"},sec={{t="工业蹂躏",b="不久前，狂风峭壁还是一片环绕在石爪山脉山坡上的茂密原始林。随着荆棘谷地精为了追逐利润来到这里，那片宁静的荒野便消失殆尽。如今，盆地里到处是断木残桩、刺鼻的烟雾和叮当作响的机械。整个伐木项目由格伦佐·扳手哨监管，这名麻风侏儒凭借其工程学天才制造出了超级收割机6000型——一种能在瞬间将巨木化为木柴的机械恐怖。在被污染的峭壁湖上方的一座高台上，格伦佐指挥着一场肆无忌惮的开采行动，将山脉剥得精光，引来了竞争对手和当地居民的敌视。"},{t="矿洞与山路",b="除了活跃的伐木场之外，狂风峭壁还存在着其他危险和交叉路口。东南方是狂风矿洞，领地意识极强的狗头人在那里挖掘岩石以寻找烟熏铁锭，并凶猛地攻击任何靠近他们货物的人。在峭壁的东北部，旅行者可以找到石爪小径，那是一条穿过山脊直通灰谷的地下洞穴隧道。在这一昏暗的入口附近驻守着牛头人长者布劳格·幽魂，他会考验那些冒险穿过这些纷争山峰的部落旅行者的历史知识和决心。"}},faq={{q="这里伐木行动的负责人是谁？",a="伐木项目由格伦佐·扳手哨在现场指挥，他是一位才华横溢但受到感染的麻风侏儒工程师。他在荆棘谷地精的合同下工作，从峭壁湖上方搭建的木制平台上监视着整个峭壁。",al={"谁在负责此地的荆棘谷地精","狂风峭壁的负责人是谁","格伦佐·扳手哨背景故事"}},{q="什么是超级收割机6000型？",a="超级收割机6000型是由格伦佐·扳手哨设计的一种先进机械伐木原型机。它旨在以空前的速度清理木材，能在瞬间将古老的山地树木磨成木屑，从而加速了该公司的滥砍滥伐。",al={"超级收割机6000型","大型伐木机是什么","荆棘谷地精的收割机"}},{q="为什么安德麦技师工会要针对格伦佐？",a="安德麦技师工会的里德尔沃克斯主管想要格伦佐的命，而已经协助窃取了超级收割机6000型设计图的哥布林兹兹·费兹克斯则发出了悬赏令。安德麦的贸易亲王们反对荆棘谷地精与这名侏儒勾结。",al={"为什么要杀格伦佐","兹兹·费兹克斯的动机","技师工会的宿怨"}},{q="东北角的洞穴通向哪里？",a="东北角的洞穴是石爪小径。它穿过山脉的地下根基，提供了一条连接狂风峭壁和灰谷茂密森林的步行路线。",al={"石爪小径的终点","狂风峭壁洞穴出口","狂风峭壁中的隧道"}},{q="在东南方挖掘的狗头人是什么人？",a="狂风狗头人已经占领了峭壁东南角的当地矿洞。他们奋力保卫着自己的地下矿区，挖掘出区域内铁匠所需的烟熏铁锭矿藏。",al={"狂风矿洞的狗头人","狗头人为什么在这里","烟熏铁锭"}}},fx={c9b71aef={q="狂风峭壁是什么地方？",a="狂风峭壁是石爪山脉中的一处深谷，曾以高耸古老的森林闻名。如今，无休止的伐木已将葱郁林地变成满目疮痍的景象，遍布参差不齐的树桩、翻涌的泥浆和有毒的径流。",al={"这是什么地方","狂风峭壁背景","石爪山脉的狂风峭壁"}},f4630a37={q="狂风峭壁发生了什么？",a="第三次战争后的数年间，荆棘谷地精带着重型工业机械进驻山谷。在麻风侏儒格雷伦佐·扳哨的带领下，他们疯狂伐木，还使用巨型伐木机，几乎将原始森林砍伐殆尽，污染了当地水域，并为木材和利润把峭壁剥得寸草不留。",al={"狂风峭壁的历史","狂风峭壁为何被砍伐殆尽","这里发生了什么"}},bab211f4={q="狂风峭壁危险吗？",a="非常危险。荆棘谷地精雇用了凶悍的伐木工、机械师和冷酷无情的伐木机，任何闯入他们领地的人都会遭到攻击。东南方还有敌对的狗头人守卫着狂风矿洞，整个盆地对四处游荡的旅人都充满敌意。",al={"狂风峭壁安全吗","狂风峭壁的威胁","狂风峭壁的危险"}}},fp="14,403,22.687.0,25.571.0,42.252.0,30.259.0,54.272.1,42.194.0,45.204.0"}
P.entries["subzone:winterfall-village"] = {n="寒水村",s="寒水村是一个庞大的熊怪营地，坐落在东部冬泉谷的积雪中，就在永望镇的东面。寒水熊怪曾与卡利姆多的其他熊怪部落有着和平的亲缘关系，但居住在这里的寒水熊怪在寒水酋长的统治下，已经陷入了疯狂和暴力的腐化之中。",h="寒水村是一个庞大的熊怪营地，坐落在东部冬泉谷的积雪中，就在永望镇的东面。寒水熊怪曾与卡利姆多的其他熊怪部落有着和平的亲缘关系，但居住在这里的寒水熊怪在寒水酋长的统治下，已经陷入了疯狂和暴力的腐化之中。",kw={"永望镇","熊怪","寒水酋长","寒水","寒水村","冬泉谷"},ang={["class:Druid"]="目睹寒水部落深陷腐化是一场苦涩的悲剧，因为在被恶魔的疯狂吞噬之前，熊怪曾是暗夜精灵和塞纳里奥议会的古老盟友。",["race:NightElf"]="寒水部落的堕落标志着暗夜精灵与卡利姆多原住民之间古老纽带的又一次痛苦断裂。"},sec={{t="被吞噬的部落",b="Sprawled across the terraced snowbanks east of the goblin trading post Everlook, Winterfall Village serves as the primary bastion of the Winterfall furbolgs in Winterspring. Like their cousins scattered across northern Kalimdor, these bear-folk were warped and driven mad by the lingering foulness of the Burning Legion's invasion. Led by High Chief Winterfall from a secluded cavern atop the settlement's highest tier, the tribe has abandoned its ancestral ways. Instead of communing peacefully with the wild spirits of the snow, the enraged furbolgs now aggressively assault travelers, patrol the mountain passes, and threaten any who come near their frost-bitten home."}},faq={{q="寒水村是什么地方？",a="这是寒水熊怪的主要定居点，位于冬泉谷地精前哨站永望镇以东的雪坡上。",al={"寒水村信息","这是什么地方","冬泉谷熊怪城镇"}},{q="为什么这里的熊怪带有敌意？",a="寒水熊怪在第三次战争后因腐化而堕落。燃烧军团留下的恶魔污染扭曲了他们的思想，剥夺了他们和平的习俗，使他们对所有外来者都充满暴力敌意。",al={"为什么熊怪疯了","腐化的熊怪","为什么发起攻击"}},{q="谁在领导这个村庄？",a="该部落由寒水酋长统治，他从定居点最高峰的一个小洞穴里监视着他的追随者。",al={"谁是首领","寒水首领","酋长"}},{q="为什么永望镇会关心这个村庄？",a="这个村庄的位置距离永望镇近得令人不安。疯狂的熊怪不断袭击路过的商队，扰乱当地的贸易路线，并威胁着地精在整个冬泉谷东部的采矿和商业利益。",al={"永望镇地精","为什么要与寒水作战"}}},fp="18,312,16.671.0,27.142.0,34.235.0,22.141.0,42.222.0"}
P.entries["subzone:winterhoof-water-well"] = {n="冰蹄水井",s="冰蹄水井是位于莫高雷南部草海平原边缘的一处重要淡水源。这口水井对于当地野生动物和游牧的牛头人部族至关重要，但最近它受到了风险投资公司的威胁，这些贪婪的家伙正试图毒害并控制该地区的水源供应。",h="冰蹄水井是位于莫高雷南部草海平原边缘的一处重要淡水源。这口水井对于当地野生动物和游牧的牛头人部族至关重要，但最近它受到了风险投资公司的威胁，这些贪婪的家伙正试图毒害并控制该地区的水源供应。",kw={"净化","莫高雷","穆尔·雷角","草海平原","图腾","荆棘谷地精","水井","冰蹄"},ang={["class:Shaman"]="净化水井需要元素和谐，这实际上展示了如何利用图腾来治愈受损的水之灵。",["race:Tauren"]="保卫和净化祖传的水井是年轻勇士面临的首要考验之一，旨在保护这片土地免受外部剥削。"},sec={{t="岌岌可危的生命线",b="在卡利姆多中部干旱的土地上，水就是生命，莫高雷的地下水井维持着平原上的兽群和牛头人的营地。冰蹄水井以平原上一个受人尊敬的部族命名，它连接着草海平原下方的深层蓄水层。不幸的是，它的战略重要性引起了风险投资公司的贪婪。这个冷酷的地精财团非但没有共享土地或进行协商，反而试图毒害水源，以此来控制周边领土。"},{t="净化与防御",b="为了应对风险投资公司的工业破坏行为，莫高雷的牛头人长者和萨满祭司动员了各地的年轻勇士。穆尔·雷角制作了神圣的图腾，旨在对抗工业毒素并恢复水井的灵性和物质平衡。净化水井不仅仅是为了牛头人的生存，更是一种确保大地及其水源不被外来贪婪所腐蚀的神圣职责。"}},faq={{q="冰蹄水井位于何处？",a="水井位于莫高雷南部，就在血蹄村南面的草海平原边缘。",al={"冰蹄水井位置","冰蹄水井在哪里","寻找冰蹄水井"}},{q="是谁毒害了冰蹄水井？",a="风险投资公司毒害了水井。这个肆无忌惮的地精贸易组织试图污染水源，以企图控制当地资源并削弱当地的牛头人。",al={"谁毒害了冰蹄水井","为什么水井被下毒","谁毁了水源"}},{q="如何净化被毒害的水井？",a="通过使用穆尔·雷角制作的附魔图腾进行的仪式，水井可以被净化，该图腾利用原始魔法从水中清除风险投资公司留下的肮脏毒素。",al={"净化冰蹄水井","修复水井","冰蹄净化"}},{q="为什么水井对牛头人如此神圣？",a="除了为部族和游荡的兽群提供必要的水分外，莫高雷的水源还被视为大地母亲的馈赠。腐蚀水源既被视为一种直接的物理威胁，也被视为一种严重的精神冒犯。",al={"为什么牛头人关心水井","牛头人水井传说"}}},fx={["8e6c4fef"]={q="冰蹄水井是什么地方？",al={"冰蹄水井概况","冰蹄水井是什么","关于冰蹄水井"}},a848edd2={q="冰蹄水井发生了什么？",a="荆棘谷地精的贪婪爪牙用卑劣手段夺取了水井，企图控制当地水源。在此过程中，他们污染并毒化了井水，威胁到草原及依赖水井的畜群的健康。此后，牛头人长老和萨满呼吁勇敢的旅人驱逐污染者，并使用祝圣图腾恢复水源的天然纯净。",al={"冰蹄水井的历史","冰蹄水井发生了什么","冰蹄水井的事件"}},["897a0f7c"]={q="冰蹄水井危险吗？",a="是的。除了渗入地下水的有毒污染，水井周围还盘踞着荆棘谷地精的武装雇佣兵。这些残暴的入侵者极力捍卫自己在此地的利益，任何前来调查或净化水井的牛头人或部落旅人都会遭到他们的猛烈攻击。",al={"冰蹄水井的危险","冰蹄水井安全吗","冰蹄水井的威胁"}}},fp="21,315,21.547.0,24.439.1,43.111.0,39.188.0,38.178.0,44.226.0"}
P.entries["subzone:witch-hill"] = {n="女巫岭",s="女巫岭是尘泥沼泽中心处一片阴郁、终年笼罩在迷雾中的高地，位于通往塞拉摩的道路旁。这里最著名的是僻静的水光庄园、散布在各处的敌对泥鳍鱼人营地，以及关于黑暗幽灵作祟的邪恶传闻。",h="女巫岭是尘泥沼泽中心处一片阴郁、终年笼罩在迷雾中的高地，位于通往塞拉摩的道路旁。这里最著名的是僻静的水光庄园、散布在各处的敌对泥鳍鱼人营地，以及关于黑暗幽灵作祟的邪恶传闻。",kw={"尘泥沼泽","泥鳍","沼泽之眼贾尔","水光庄园","女巫岭"},ang={["class:Warlock"]="路过塞拉摩公路的术士可能会感觉到这片阴郁小丘上挥之不去的黑暗闹鬼传闻。",["faction:Alliance"]="女巫岭毗邻通往塞拉摩岛的主要陆路，这使得它的鱼人部落和黑暗实体成为了旅行者和信使挥之不去的麻烦。"},sec={{t="凋零的高地",b="女巫岭从尘泥沼泽死寂的水域中升起，大约位于通往塞拉摩岛的半岛路程的三分之一处。这片高地无法让旅人躲避沼泽的危险，因为好战的泥鳍鱼人占据了周围的水域。在中心矗立着水光庄园，这是被称为“沼泽之眼”贾尔的隐士那孤独而令人不安的居所。路过的旅人经常报告说，在这座小丘上能看到怪异的现象，并感觉到挥之不去的黑暗存在。"},{t="高地的幽灵",b="在安静而阴郁的外表下，女巫岭沉浸在黑暗的传闻之中。关于闹鬼的故事萦绕在这片荒凉的土地上，加剧了当地人的偏执。那些敢于踏足此地的人，不仅要面对泥鳍鱼人的原始野蛮，还要应对令即使是经验丰富的塞拉摩巡逻队也感到不安的超自然威胁。"}},faq={{q="女巫岭在哪里？",a="女巫岭位于尘泥沼泽，大约位于连接西部沼泽与塞拉摩岛的半岛路程的三分之一处。",al={"女巫岭位置","女巫岭在哪里","如何找到女巫岭"}},{q="谁住在女巫岭？",a="最著名的居民是“沼泽之眼”贾尔，他是一位古怪的隐士，住在小丘中心附近的水光庄园里。周围的低地也被泥鳍鱼人的营地所占据。",al={"这里住着谁","女巫岭居民","水光庄园住户"}},{q="为什么这个地区被称为女巫岭？",a="这座小丘长期以来因黑暗魔法、奇异的光芒和超自然危险而声名狼藉，水光庄园那阴森的孤独感更让这种名声愈演愈烈。",al={"为何叫女巫岭","这里有女巫吗","女巫岭背景故事"}},{q="在女巫岭，旅行者应该提防哪些威胁？",a="旅行者必须提防在小丘周围建立营地的游荡泥鳍鱼人，以及萦绕在小丘上令人不安的闹鬼传闻。",al={"女巫岭危险","女巫岭敌人","女巫岭怪物"}}},fp="10,243,15.515.0,24.315.1,28.146.0,24.195.0,34.151.1,57.154.0"}
P.entries["subzone:witherbark-village"] = {n="枯木村",s="枯木村是位于阿拉希高地东南丘陵深处，一个依傍着隐秘湖泊的森林巨魔定居点。这里居住着充满敌意的枯木部族，它是巨魔袭击者的大本营，这些人不断袭扰着激流堡的联盟残余势力以及落锤镇的部落据点。",h="枯木村是位于阿拉希高地东南丘陵深处，一个依傍着隐秘湖泊的森林巨魔定居点。这里居住着充满敌意的枯木部族，它是巨魔袭击者的大本营，这些人不断袭扰着激流堡的联盟残余势力以及落锤镇的部落据点。",kw={"阿拉希高地","森林巨魔","杀手尼玛尔","枯木","枯木村","扎拉斯·枯木"},ang={["faction:Horde"]="枯木部族对新部落毫无敬意，他们频繁与落锤镇的斥候发生冲突，并威胁着东部山口的通行安全。",["race:Troll"]="暗矛巨魔在这里找不到任何亲缘关系；枯木森林巨魔对丛林巨魔和部落怀有根深蒂固的敌意。"},sec={{t="森林巨魔的堡垒",b="枯木村沿着静谧的高山湖泊修建，是凶猛的枯木部族森林巨魔的家园。当渔夫、投斧手和巫医们在布满小屋的湖畔忙碌时，如扎拉斯·枯木这样的部族领袖和致命的暗影猎手则在定居点后方巨大的洞穴中指挥着一切。枯木部族与阿拉希的巨石拳食人魔维持着一种投机性的联盟关系，他们通力合作，试图在整个高地开辟领地——甚至在激流堡的废墟中建立了一处稳固的据点。他们领地意识极强，会对任何闯入这片盆地的外来者发动猛烈攻击。"}},faq={{q="谁住在枯木村？",a="这个定居点由枯木部族控制，他们是该地区土生土长的森林巨魔。他们派遣猎头者、投斧手、渔夫和巫医来保卫湖泊及周边的道路。",al={"谁是枯木部族","枯木巨魔","谁控制了枯木村"}},{q="村庄后面的大洞穴里有什么？",a="那个洞穴是部族领导层的所在地。枯木酋长扎拉斯·枯木和危险的暗影猎手们就在深处的隧道中协调着部族的袭击与防御。",al={"枯木洞穴","枯木村后面的洞穴","扎拉斯·枯木的位置"}},{q="为什么枯木巨魔要与食人魔合作？",a="枯木部族与当地的巨石拳食人魔达成了一种利益驱动的松散联盟。结合双方的力量，使他们能够向虚弱的激流堡人类防御者施压，并威胁到落锤镇的部落等地区对手。",al={"枯木与食人魔的联盟","巨魔与巨石拳","为什么巨魔要与食人魔结盟"}},{q="枯木部族对部落友好吗？",a="不友好。像大多数阿曼尼血统的森林巨魔一样，枯木部族对现代部落及其暗矛巨魔怀有深仇大恨，他们与落锤镇的部落处于敌对状态。他们会攻击视线范围内的部落旅人。",al={"枯木部族是部落吗","部落能与枯木部族对话吗","枯木部族声望"}}},fp="18,309,31.664.0,32.208.0,49.179.0,49.248.0,41.217.0"}
P.entries["subzone:woodpaw-den"] = {n="木爪巢穴",s="木爪巢穴是一座崎岖的豺狼人要塞，坐落在菲拉斯南部，就在古老的暗雾废墟以北。这处定居点是木爪豺狼人及其最凶猛的阿尔法首领的主要聚集地，使其成为了茂密林冠下一处危险的荒野区域。",h="木爪巢穴是一座崎岖的豺狼人要塞，坐落在菲拉斯南部，就在古老的暗雾废墟以北。这处定居点是木爪豺狼人及其最凶猛的阿尔法首领的主要聚集地，使其成为了茂密林冠下一处危险的荒野区域。",kw={"暗雾废墟","菲拉斯","豺狼人","木爪","木爪阿尔法","木爪巢穴"},ang={["race:NightElf"]="对于以羽月要塞为基地的卡多雷来说，在暗雾废墟等古老先祖遗迹附近不断扩张的豺狼人部族是一个持续的麻烦，需要时刻保持警惕并加以遏制。",["race:Tauren"]="莫沙彻营地的猎手们认为凶残的木爪氏族是他们在菲拉斯原始森林中争夺猎物和领地的危险竞争对手。"},sec={{t="部族之心",b="木爪巢穴坐落在菲拉斯参天大树的枝桠之间，是当地木爪豺狼人的防御腹地。与分散在丛林小径上的小型侦察营地不同，这处营地由部族中经验丰富的阿尔法首领严密防守。这里的豺狼人拼死捍卫自己的领地，抵御入侵的冒险者和不断扩张的荒野。巢穴位于暗雾废墟的暗夜精灵遗迹以北，对于试图穿越该地区中部荒野的旅行者来说，它始终是一个潜伏的掠食者威胁。"}},faq={{q="木爪巢穴是什么地方？",a="木爪巢穴是木爪豺狼人在菲拉斯南部的一处重要定居点和营地，位于暗雾废墟以北。这里居住着大量危险的部族阿尔法首领。",al={"菲拉斯木爪巢穴","菲拉斯豺狼人营地","木爪巢穴在哪里"}},{q="这里居住着什么生物？",a="巢穴中主要居住着木爪豺狼人氏族，尤其是那些强大而令人生畏的木爪阿尔法首领，他们领导并保护着部族免受外来者的侵扰。",al={"这里住着谁","木爪巢穴怪物","木爪巢穴里有什么敌人"}},{q="附近有什么地标？",a="紧邻南面的是被称为暗雾废墟的古老暗夜精灵遗迹。营地本身被菲拉斯中部典型的茂密雨林所环绕。",al={"木爪巢穴附近的地标","木爪巢穴旁边有什么"}}},fp="11,283,17.551.0,20.194.0,25.150.0,26.177.0"}
P.entries["subzone:woodpaw-hills"] = {n="木爪岭",s="木爪岭是菲拉斯东南部一片崎岖的森林地带，被木爪豺狼人所占据。这片丘陵曾经是该部族的主要领地，如今却成了一处交战前线，因为地底挖掘出的虫群恐怖生物和游荡在树冠下的远古山岭巨人令这里战火纷飞。",h="木爪岭是菲拉斯东南部一片崎岖的森林地带，被木爪豺狼人所占据。这片丘陵曾经是该部族的主要领地，如今却成了一处交战前线，因为地底挖掘出的虫群恐怖生物和游荡在树冠下的远古山岭巨人令这里战火纷飞。",kw={"菲拉斯","豺狼人","山岭巨人","木爪","木爪巢穴","木爪岭","痛苦深渊"},ang={["faction:Horde"]="与栖息在西海岸附近的那些中立峭壁巨人不同，在木爪岭巡逻的山岭巨人对冒险进入内陆的部落成员抱有强烈的敌意。"},sec={{t="饱受围困的据点",b="木爪岭茂密的森林是木爪豺狼人氏族历来的领地。虽然这些鬣狗人曾在这片山坡上肆意漫游，但他们的统治地位已在多方压力下土崩瓦解。在他们的东南方，噩梦般的其拉虫群从痛苦深渊破土而出，迫使豺狼人节节败退，并令其族长们不得不撤退到木爪巢穴深处。更危险的是，在第三次战争期间为抵御燃烧军团而被召唤到此的远古山岭巨人，如今正徘徊在林间的山坡上，碾碎任何误入此地的旅者或部落闯入者。"}},faq={{q="谁居住在木爪岭？",a="木爪岭主要由木爪豺狼人氏族居住，他们在树林各处维持着防御营地。远古山岭巨人也在山坡上巡逻，同时侵略性的其拉虫群正从东南边界入侵。",al={"谁居住在木爪岭","木爪岭的敌人","菲拉斯的豺狼人"}},{q="为什么山岭巨人会在森林里游荡？",a="当燃烧军团入侵卡利姆多时，这些山岭巨人最初是从山峰上下来协助暗夜精灵的。虽然恶魔的入侵已被粉碎，但这些庞大的守护者仍留在森林中，严厉地守护着这片荒野，抵御任何入侵。",al={"木爪岭的巨人","为什么这里有巨人","菲拉斯山岭巨人背景"}},{q="豺狼人在这里受到什么威胁？",a="木爪氏族正受到痛苦深渊中突然涌现并建立巢穴的其拉虫群的驱逐。不断扩张的虫群已经将豺狼人赶出了几个营地，迫使他们最强壮的首领固守在木爪巢穴内。",al={"豺狼人在对抗什么","木爪氏族的麻烦","菲拉斯攻击豺狼人的虫子"}},{q="木爪氏族的领袖在哪里？",a="由于其拉虫群在丘陵各处肆虐，部族领导层已经放弃了露天营地。木爪首领们已经撤退到木爪巢穴受庇护的地下洞穴中。",al={"木爪首领位置","菲拉斯豺狼人首领","寻找木爪领袖"}}},fp="13,267,24.645.0,31.233.0,51.279.0,36.267.0,35.199.0"}
P.entries["subzone:workshop-entrance"] = {n="Workshop Entrance",s="Workshop Entrance通常被称为诺莫瑞根的后门，是位于Train Depot之外的一个入口通道。它为经验丰富的冒险者和工程师提供了一条进入这座辐射之城深处的替代路线，可以避开正门，直接通往Engineering Labs附近。",h="Workshop Entrance通常被称为诺莫瑞根的后门，是位于Train...",kw={"后门","engineering labs","诺莫瑞根","loading room","train depot","workshop entrance"},ang={["profession:Engineering"]="这条走廊直通Engineering Labs，对于那些寻找尖端图纸的技工来说，这是一条诱人的渗透路线。",["race:Gnome"]="每一扇通往诺莫瑞根的秘密门扉都是夺回失落车间、从麦克尼尔·瑟玛普拉格的部队手中回收原型机械的潜在突破点。"},sec={{t="通往城市的后门",b="Workshop Entrance位于穿过Train Depot后那片巨大的车间地面对面，提供了一条直达诺莫瑞根工业核心地带的路径。该通道一侧是通往Loading Room的开口，另一侧则直通Engineering Labs，避开了地表附近受麻风侏儒和穴居人争夺的坚固大门。对于试图收复这座地下首都的突袭小队来说，通过这扇侧门绕过最初的外围防线至关重要。"}},faq={{q="Workshop Entrance位于何处？",a="Workshop Entrance坐落在车间地面的远端，穿过诺莫瑞根外围走廊的Train Depot即可到达。从这里看，通往Loading Room的传送门就在你的左侧。",al={"workshop entrance位置","后门在哪里","诺莫瑞根后门位置"}},{q="为什么这个区域被称为后门？",a="它作为进入诺莫瑞根地下城内部的替代入口，可以跳过主要的正面防线，直接将入侵者带向Engineering Labs。",al={"为什么叫后门","诺莫瑞根后门","后方入口"}},{q="这扇门通往城内的什么地方？",a="穿过这道传送门会沿着走廊直接进入诺莫瑞根深处的Engineering Labs区域。",al={"它通向哪里","通过后门的路径","入口后面是什么"}}},fx={bbef9a7d={q="Workshop Entrance是什么地方？",a="Workshop Entrance是位于Train Depot之外的外层工坊另一侧的一处服务通道入口。它俗称诺莫瑞根的后门，是一处设防入口，可直通Engineering Labs，绕过上层城市的仪式性大门。",al={"workshop entrance是什么","诺莫瑞根的workshop entrance","关于workshop entrance"}},["6fa860f5"]={q="Workshop Entrance发生了什么？",a="诺莫瑞根沦陷期间，穴居人在下层区域四处涌现，城市的次要通道和货运线路也随之变成战场。为了防止虫群和有毒的辐射尘失控地蔓延到外围山道，类似这样的通道门被封上，并实施了严格的安全措施。",al={"workshop entrance的历史","这里发生了什么","后门的历史"}},["8f5e07c5"]={q="Workshop Entrance为何破败并被遗弃？",a="为了清除入侵的穴居人群，首席技师梅卡托克下令释放放射性气体，结果计划酿成灾难。致命的辐射尘覆盖了工业设施，使幸存的守军染病，许多人还变成了狂暴的麻风侏儒。如今，这处入口已荒废，堆满残骸和机械，四周还游荡着可怖的怪物。",al={"为何被遗弃","workshop entrance为何破败","被占据的workshop entrance"}},e5f19575={q="Workshop Entrance危险吗？",a="这里极其危险。除了下层设施中残留的辐射，失控的防御自动机、疯癫的麻风侏儒和嗜血的穴居人也在通道中游荡。穿过这道门便会来到城市中动荡的工程实验室附近，那里没有任何理智的防卫力量驻守。",al={"workshop entrance安全吗","workshop entrance的危险","后门有多危险"}}},fp="17,299,24.500.0,39.193.0,37.176.0,45.115.0"}
P.entries["subzone:writhing-deep"] = {n="痛苦深渊",s="痛苦深渊是一个巨大的虫族巢穴，开凿于菲拉斯的东南部。这个地下洞穴居住着祖卡什异种虫，对附近的野生动物和周边的营地构成了日益严重的威胁。这些地下掠食者无休止的扩张已经破坏了这片葱郁森林的区域平衡。",h="痛苦深渊是一个巨大的虫族巢穴，开凿于菲拉斯的东南部。这个地下洞穴居住着祖卡什异种虫，对附近的野生动物和周边的营地构成了日益严重的威胁。这些地下掠食者无休止的扩张已经破坏了这片葱郁森林的区域平衡。",kw={"莫沙彻营地","菲拉斯","虫巢","奇洛特","异种虫","刺鞭者","痛苦深渊","祖卡什"},ang={["faction:Horde"]="从痛苦深渊中扩张出来的异种虫直接威胁着莫沙彻营地，它们将疯狂的豺狼人和游荡的昆虫斥候驱赶向你的补给线。"},sec={{t="祖卡什虫群",b="痛苦深渊隐藏在菲拉斯东南部的潮湿低地中，是祖卡什异种虫的主要聚居地。与山谷中常见的林地野兽不同，这些发出嘶嘶声的昆虫挖掘出了迷宫般的隧道，并严密地守卫着一簇簇树脂卵。巢穴对附近领地的Aggressive Encroachment已经使野生动物群变得不稳定，并激怒了当地的豺狼人部族，将那些流离失所且陷入疯狂的掠食者推向了部落路径和原住民圣地附近，令人感到不安。"}},faq={{q="什么生物栖息在痛苦深渊？",a="这个深渊被祖卡什异种虫所占据，这是一种极具攻击性的巨型昆虫品种，包括工虫、挖掘者、蛰刺者和黄蜂，由诸如刺鞭者和奇洛特等危险的巢穴勇士领导。",al={"痛苦深渊怪物","痛苦深渊里住着什么","菲拉斯的异种虫"}},{q="为什么痛苦深渊对莫沙彻营地构成威胁？",a="随着祖卡什虫群向外扩张，它们挤压了周围豺狼人的狩猎场。惊慌失措的豺狼人被驱赶向北，直奔莫沙彻营地，给这座部落前哨站造成了不断升级的安全危机。",al={"莫沙彻营地与痛苦深渊","为什么攻击部落","菲拉斯的豺狼人"}},{q="痛苦深渊位于哪里？",a="痛苦深渊位于菲拉斯的东南部，主干道以南，高耸的森林山丘以东。",al={"痛苦深渊位置","痛苦深渊在哪里","菲拉斯虫巢位置"}}},fp="13,343,18.510.0,41.199.0,50.221.0,35.131.0"}
P.entries["subzone:writhing-haunt"] = {n="嚎哭鬼屋",s="嚎哭鬼屋是一处位于西瘟疫之地安多哈尔废墟东侧的枯萎农场。这片曾经滋养过洛丹伦的沃土，如今已被天灾军团占据，并被改造成了散播瘟疫毒气的邪恶之地。",h="嚎哭鬼屋是一处位于西瘟疫之地安多哈尔废墟东侧的枯萎农场。这片曾经滋养过洛丹伦的沃土，如今已被天灾军团占据，并被改造成了散播瘟疫毒气的邪恶之地。",kw={"andorhal","大熔炉领主拉扎克","穆格里斯·深河","瘟疫大熔炉","西瘟疫之地","嚎哭鬼屋"},ang={["class:Druid"]="瘟疫毒气对肥沃农田的亵渎，使得嚎哭鬼屋成了对自然秩序的公然挑衅，必须让大熔炉停止运作。",["faction:Alliance"]="看到安多哈尔外的农田在天灾军团的统治下沦为充满瘟疫的荒地，这令人痛苦地回想起洛丹伦的陷落。"},sec={{t="瘟疫之田",b="和安多哈尔周围的许多古老人类家园一样，现在被称为嚎哭鬼屋的农场在第三次战争期间迅速陷落。如今，这些田地里不再生长庄稼，取而代之的是腐烂。天灾军团在耕地的正中央安放了一口巨大的瘟疫大熔炉，不断向空气中排放有毒的瘟疫气体。腐烂食尸鬼、冰冷食尸鬼和恶臭僵尸在杂草丛生的沟壑中游荡，在大熔炉领主拉扎克的指挥下守卫着这台机器。"},{t="废墟中的守望者",b="尽管天灾军团的危险无处不在，且大熔炉散发出令人窒息的瘴气，但这座农场并未完全被遗弃。在一间破败的农舍里，牛头人德鲁伊穆格里斯·深河驻留于此，他来到这片土地是为了治愈自然遭受的创伤。他自己也深受瘟疫折磨，无法治愈那些受苦的野兽，因此他请求有能力的旅行者给那些患病的狼和其他野生动物以迅速而仁慈的解脱。"}},faq={{q="瘟疫爆发前，嚎哭鬼屋是什么地方？",a="第三次战争前，嚎哭鬼屋是一个高产且维持着生计的人类农场，为附近的安多哈尔和更广阔的洛丹伦王国供应谷物和牲畜。",al={"嚎哭鬼屋历史","这个农场曾经是什么","安多哈尔的旧农场"}},{q="为什么田地中央会有一个巨大的大熔炉？",a="这个大熔炉是天灾军团放置的，旨在积极酿造并向周围的乡村散布瘟疫毒气，毒害土壤、水源以及附近的任何生物。",al={"嚎哭鬼屋的瘟疫大熔炉","为什么这里会有大熔炉","绿色烟雾农场"}},{q="谁控制着嚎哭鬼屋？",a="该地点由大熔炉领主拉扎克指挥，他是天灾军团的一名亡灵仆从，与一群食尸鬼和僵尸一起守卫着瘟疫大熔炉。",al={"谁在负责嚎哭鬼屋","嚎哭鬼屋首领","拉扎克"}},{q="谁躲在农舍里？",a="牛头人德鲁伊穆格里斯·深河躲在废弃的农舍里。他来到瘟疫之地是为了治愈自然遭受的创伤，由于瘟疫无法治愈，他请求旅行者让该地区患病的野生动物从痛苦中解脱。",al={"房子里的npc","穆格里斯·深河","谁是穆格里斯"}}},fp="14,246,18.499.0,22.441.0,46.181.0,57.182.0,32.151.0,31.250.0"}
P.entries["subzone:wyrmbog"] = {n="巨龙沼泽",s="巨龙沼泽是尘泥沼泽南部一片危险的广阔区域，位于黑龙谷以南。这里遍布污浊的泥沼和参差的石峰，是黑龙军团的集结地和领地缓冲带。包括龙母奥妮克希亚和长者埃博斯塔夫在内的古龙巢穴，直接开凿在它周围的山脊之中。",h="巨龙沼泽是尘泥沼泽南部一片危险的广阔区域，位于黑龙谷以南。这里遍布污浊的泥沼和参差的石峰，是黑龙军团的集结地和领地缓冲带。包括龙母奥妮克希亚和长者埃博斯塔夫在内的古龙巢穴，直接开凿在它周围的山脊之中。",kw={"黑龙军团","黑龙谷","龙类","尘泥沼泽","埃博斯塔夫","沼泽","奥妮克希亚","巨龙沼泽"},ang={["faction:Alliance"]="对于那些狩猎黑龙军团的联盟勇士来说，巨龙沼泽是到达奥妮克希亚巢穴门槛前最后且最危险的集结地。",["faction:Horde"]="大酋长萨尔的斥候密切监视着巨龙沼泽，因为他们知道这些黑龙在贫瘠之地和塞拉摩附近筑巢，对卡利姆多脆弱的平衡构成了威胁。"},sec={{t="龙群之心",b="巨龙沼泽是卡利姆多南部黑龙势力最猖獗的领地。当尘泥沼泽的开阔水域逐渐被焦黑的淤泥和高耸的龙骨所取代，幼龙和成年龙便会在腐臭的空气中巡逻。这片沼泽充斥着有毒的烟雾，掠食野兽因巨龙的存在而变得狂暴。胆敢误入这些区域的旅行者，会发现自己直接处于奥妮克希亚的巢穴和埃博斯塔夫洞穴的阴影之下。"}},faq={{q="什么是巨龙沼泽？",a="巨龙沼泽是尘泥沼泽南部的一片险恶区域，位于黑龙谷以南。这里盘踞着大量的黑龙军团成员。",al={"巨龙沼泽","什么是巨龙沼泽","巨龙沼泽在哪里"}},{q="哪些巨龙居住在巨龙沼泽？",a="黑龙军团掌控着这片领地。无数的黑龙人、龙类和幼龙在沼泽上空巡逻，而像埃博斯塔夫和龙母奥妮克希亚这样的古龙则在沼泽南缘设有巢穴。",al={"谁住在巨龙沼泽","巨龙沼泽的龙","这里有什么龙"}},{q="奥妮克希亚的巢穴位于巨龙沼泽的什么位置？",a="奥妮克希亚的巢穴入口坐落在巨龙沼泽南缘的岩石尖塔和洞穴开口处。",al={"奥妮克希亚的巢穴位置","奥妮克希亚在哪里","奥妮克希亚巢穴入口"}},{q="谁是埃博斯塔夫？",a="埃博斯塔夫是一头古老的黑龙，居住在开凿于巨龙沼泽岩石结构中的洞穴里，作为龙母领地内的一名强大守护者。",al={"埃博斯塔夫","谁是埃博斯塔夫","埃博斯塔夫的巢穴"}}},fp="7,368,18.455.0,16.160.0,31.218.0,54.122.0,19.174.0"}
P.entries["subzone:xavian"] = {n="萨维亚",s="萨维亚是位于灰谷东北部的一处古老且破败的暗夜精灵神殿遗迹，如今已被萨特占领并宣称主权。这处遗迹是萨特在森林中主要的势力据点，充斥着恶魔的腐化气息，他们在此举行邪恶仪式，以此来祸害这片林地。",h="萨维亚是位于灰谷东北部的一处古老且破败的暗夜精灵神殿遗迹，如今已被萨特占领并宣称主权。这处遗迹是萨特在森林中主要的势力据点，充斥着恶魔的腐化气息，他们在此举行邪恶仪式，以此来祸害这片林地。",kw={"安妮莉亚","灰谷","塞纳留斯的树枝","盖尔塔里斯","拉泽","萨特","萨维亚","萨维斯"},ang={["class:Druid"]="这里的萨特偷走了塞纳留斯的树枝，并利用邪能仪式来腐化大地；德鲁伊们被召唤前来夺回圣物，并治愈林地的精神创伤。",["race:NightElf"]="看到一座古老神殿被上层精灵的扭曲后裔所亵渎，这对任何暗夜精灵来说都是一种苦涩的冒犯，必须予以迅速的报复。"},sec={{t="暗影之座",b="萨维亚坐落在灰谷东北部的群山之中，位于林歌神殿之西，萨提纳尔之北，是该地区萨特力量最强的堡垒。它曾经是一座神圣的精灵神殿，如今其石拱门和露台已被燃烧军团的追随者亵渎。拉泽王子和盖尔塔里斯等萨特首领从这些遗迹中统御着他们的族人。他们在各处举行亵渎仪式，甚至利用窃取的战歌之油来进一步腐化这片神圣的林地。该地区得名于萨维斯，这位上层精灵议员在上古之战中因令萨格拉斯失望，成为了第一个萨特。"},{t="堕落的前锋",b="萨维亚散发的腐化气息并非无人阻挡，但与萨特正面对抗需要付出惨痛的代价。哨兵和林地守护者们密切监视着这座堡垒，因为他们知道，其战略上的邪恶程度远超夜道谷等附近的据点。最近，树妖保卫者们试图潜入遗迹取回神圣的塞纳留斯的树枝，结果损失惨重。踏入外围露台的冒险者可以找到垂死的树妖安妮莉亚，她在试图阻止污染者利用圣物进行邪恶咒语时被击倒。"}},faq={{q="为什么这个地方叫萨维亚？",a="这座堡垒的命名是为了纪念萨维斯领主，他是艾萨拉女王的上层精灵廷臣，在上古之战期间协助燃烧军团进入艾泽拉斯。在令萨格拉斯不悦后，萨维斯被改造成了最初的萨特，这是一种传播给其同类的恶魔诅咒。",al={"萨维亚的起源","萨维亚是以谁命名的","萨维斯与萨维亚"}},{q="萨特在这里做什么？",a="萨特将萨维亚作为他们在灰谷的主要指挥中心。他们进行黑暗仪式，将恶魔腐化传播到整片古老的森林中，并利用被亵渎的神圣遗物（如窃取的塞纳留斯的树枝）以及从战歌兽人那里偷来的机械用油。",al={"他们在萨维亚做什么","萨维亚的萨特仪式"}},{q="躺在地上垂死的树妖是谁？",a="她的名字叫安妮莉亚。她曾参与树妖从萨特手中夺回被窃的塞纳留斯的树枝的行动。她在冲突中受了致命伤，现在躺在废墟中，恳求有人能在圣物彻底腐化之前将其收回。",al={"萨维亚的受伤树妖","安妮莉亚是谁","萨维亚的树妖"}},{q="萨维亚与萨提纳尔或夜道谷有何不同？",a="虽然萨提纳尔和夜道谷是灰谷内著名的萨特营地，但萨维亚是他们在森林中势力的政治和仪式核心。盖尔塔里斯和拉泽王子等高阶萨特首领就以这些遗迹为基地。",al={"萨提纳尔与萨维亚的区别","其他萨特营地","为什么萨维亚很重要"}}},fx={a8b6505e={q="萨维亚是什么地方？",a="萨维亚是一处古老的暗夜精灵神殿群，坐落于灰谷东北部，如今已被萨特占据。它位于萨提纳尔以北、林歌神殿以西，是整个森林中萨特政治势力和黑暗仪式力量的主要据点。",al={"萨维亚是什么","萨维亚背景","关于萨维亚"}},cfe8a8e5={q="萨维亚发生了什么？",a="萨维亚曾是古代暗夜精灵的宁静圣所，在上古之战之后却沦为废墟并遭到腐化。",al={"萨维亚的历史","萨维亚发生了什么","萨维亚之战"}},e57f7c80={q="谁统治着萨维亚？",a="这座据点盘踞着一群凶残的萨特，也是他们在当地的权力中心。拉泽王子和盖尔萨里斯等有影响力的首领居住于此，主持腐化仪式，并指挥灰谷各处邪恶的同族。",al={"谁领导萨维亚","谁住在萨维亚","萨维亚首领"}},["73205fc1"]={q="萨维亚为何沦为废墟？",a="与卡利姆多的许多古老建筑一样，这座神圣的暗夜精灵神殿在一万年前的大分裂和上古之战期间遭到摧毁。腐化的萨特没有重建它，而是住进断壁残垣，将其改造成施展黑暗魔法的堡垒。",al={"萨维亚为何沦为废墟","谁摧毁了萨维亚","萨维亚废墟"}},bc87c8f6={q="萨维亚危险吗？",a="这里极其危险。萨维亚戒备森严，凶悍的萨特教徒在此用偷来的战歌之油举行黑暗仪式，还亵渎塞纳留斯的树枝等圣物。即使是森林守护者中的林妖，也曾在试图闯入此地时遭到伏击并身负致命重伤。",al={"萨维亚危险吗","萨维亚的威胁","萨维亚有多危险"}}},fp="6,267,16.643.0,19.565.1,31.293.0,31.277.0,43.264.0,51.247.0"}
P.entries["subzone:yojamba-isle"] = {n="尤亚姆巴岛",s="尤亚姆巴岛是荆棘谷西北海岸外的一群小型热带岛屿，靠近通往西部荒野的水域。它是博学的赞达拉部族的离岸营地，他们在此建立立足点，以观察丛林中日益加剧的危机。赞达拉人从这些海岸出发，寻求部落和联盟中愿意挺身而出的勇士，去对抗祖尔格拉布中苏醒的远古恐怖。",h="尤亚姆巴岛是荆棘谷西北海岸外的一群小型热带岛屿，靠近通往西部荒野的水域。它是博学的赞达拉部族的离岸营地，他们在此建立立足点，以观察丛林中日益加剧的危机。赞达拉人从这些海岸出发，寻求部落和联盟中愿意挺身而出的勇士，去对抗祖...",kw={"血神","哈卡","荆棘谷","暗礁海","尤亚姆巴岛","赞达拉","赞达拉人","祖尔格拉布"},ang={["faction:Alliance"]="联盟冒险者可能会对在如此靠近西部荒野的地方发现一个和平的巨魔营地感到吃惊，但在夺灵者造成的灾难性威胁面前，赞达拉人抛开了政治偏见。",["race:Troll"]="对于暗矛巨魔来说，会见赞达拉人是一次与巨魔文明远古祖先根源的接触，其传统、威望和要求赢得了深厚的文化敬畏。"},sec={{t="赞达拉使者",b="虽然在荆棘谷各地遇到的大多数巨魔都对外部人员抱有敌意，但居住在尤亚姆巴岛上的赞达拉部族却保持着一种不安的中立态度。作为巨魔文明中古老的祭司和博学者，赞达拉人目睹了祖尔格拉布内的古拉巴什巨魔投靠夺灵者哈卡，心中充满了日益增长的恐惧。深知完全召唤血神所带来的灭世危险，赞达拉人远征离开了他们的祖居地，建立了这处补给基地，并号召任何有能力的冒险者——无论阵营——来协助遏制这一威胁。"},{t="守卫水域",b="该岛静静地坐落在暗礁海西北方的海岸线上，附近的海滩上闹着鬼墟。北面是铁甲湾巨大的隐秘海门，而周围的浅滩常有游荡的海兽出没。尽管位置险要，这座赞达拉营地却是一处宁静的避难所，这里有异域的仪式、神圣的祭坛和古老的知识，为那些准备深入丛林最黑暗废墟的人们提供慰藉与力量。"}},faq={{q="为什么尤亚姆巴岛上的巨魔是友好的？",a="这些巨魔属于赞达拉部族，是巨魔种族中受人尊敬的祭司和历史学家阶层。与内地富有领土意识的血顶或裂颅者部落不同，赞达拉人肩负着阻止祖尔格拉布中夺灵者哈卡的紧急使命，他们意识到要实现这一目标，需要部落和联盟双方外部勇士的帮助。",al={"友好巨魔尤亚姆巴","为什么尤亚姆巴巨魔不攻击","赞达拉友好"}},{q="尤亚姆巴岛位于何处？",a="尤亚姆巴岛位于荆棘谷远西北海域。它坐落在暗礁海西北方的海岸外，靠近南部海域与西部荒野交界的海上边界。",al={"尤亚姆巴岛位置","如何前往尤亚姆巴","尤亚姆巴在哪里"}},{q="赞达拉部族在这里做什么？",a="他们建立了一个前哨营地，以监测祖尔格拉布内夺灵者哈卡的危险复苏。从尤亚姆巴岛出发，他们的使者招募、补给并奖励那些愿意进入这座古老巨魔城市并击败被腐化的祭司的强大冒险者，以此防止哈卡的全部力量被释放到艾泽拉斯。",al={"赞达拉目的","赞达拉人想要什么","赞达拉人为什么在这里"}}},fp="12,441,26.594.0,14.489.0,44.376.0,30.198.0,42.338.0"}
P.entries["subzone:yorgen-farmstead"] = {n="约根农场",s="约根农场是一座位于暮色森林南部的废弃农场，与这片饱受困扰的地区一同陷入了衰败。这里曾属于农民斯温·约根，现已被迪菲亚潜行者的强盗所侵占。",h="约根农场是一座位于暮色森林南部的废弃农场，与这片饱受困扰的地区一同陷入了衰败。这里曾属于农民斯温·约根，现已被迪菲亚潜行者的强盗所侵占。",kw={"暗色河滩","迪菲亚","迪菲亚潜行者","暮色森林","农场","斯温·约根","约根农场"},ang={["class:Rogue"]="潜伏在农场中的迪菲亚刺客使该区域危机四伏，这也表明了这些不法之徒是多么轻易地将荒废的野外建筑变成了隐蔽的藏身处。",["faction:Alliance"]="斯温的农场被迪菲亚潜行者夺走，凸显了这些不法集团对暮色森林的渗透之深，而此时夜色镇的守夜人正苦于维持秩序。"},sec={{t="一座废弃的家园",b="约根农场坐落在暮色森林南部阴郁的林地间，曾是属于斯温·约根的一处经营中的家园。和该地区许多孤立的房产一样，这座农场没能抵挡住这片领土上不断侵蚀的危险。斯温被迫放弃了他的土地，向北撤退到暗色河滩边的一处临时营地。在他离开后，这片荒废的土地被那些寻找立足点以躲避暴风城当局监视的亡命之徒所占据。"},{t="迪菲亚渗透",b="这座农场并没有空置，而是被迪菲亚潜行者改造成了一个集结地。戴着面具的拦路强盗和隐秘的刺客潜伏在腐朽的围栏和风化的外屋之间，利用茂密的树木遮掩踪迹。接近农场的旅行者必须小心行事，因为迪菲亚刺客会在外围巡逻，并伏击任何闯入他们这处新据点的人。"}},faq={{q="谁拥有约根农场？",a="这座农场最初是由斯温·约根建立并耕种的。在家园遭遇悲剧并被不断加剧的危险驱赶后，斯温逃往了位于更北边暗色河滩上的一处孤立营地。",al={"谁曾住在这里","谁拥有约根农场","斯温·约根农场"}},{q="现在是谁占据了农场？",a="迪菲亚潜行者已经侵占了这处废弃的房产。扒手、强盗和潜行的刺客在杂草丛生的庭院和谷仓周围游荡，使得这里变得极其危险，不宜造访。",al={"谁在约根农场","这里有什么敌人","谁现在住在这里"}},{q="斯温·约根去了哪里？",a="斯温放弃了农场，现在住在一个位于暗色河滩边的简陋营地里，那里位于将暮色森林与艾尔文森林隔开的河流北岸。",al={"斯温在哪里","斯温·约根的位置","寻找斯温·约根"}},{q="为什么迪菲亚潜行者会出现在暮色森林？",a="迪菲亚潜行者的活动范围早已超出了西部荒野。混乱的乡村定居点和薄弱的地区防御使他们的特工得以建立秘密营地和据点，逃避暴风城治安官的追捕。",al={"暮色森林的迪菲亚","强盗为什么在这里","迪菲亚潜行者农场"}}},fx={["70ba336a"]={q="约根农场是什么地方？",a="约根农场是位于暮色森林南部的一座废弃农场。它曾是斯温·约根拥有并耕作的宁静家园，如今和这片阴森地区的许多地方一样，早已破败不堪。现在，迪菲亚潜行者已经夺取并占据了这座农场。",al={"约根农场是什么","约根农场信息","介绍约根农场"}},["7755c939"]={q="约根农场危险吗？",a="是的，靠近农场极其危险。迪菲亚潜行者成员遍布此地，其中包括隐秘的刺客，他们在废弃建筑和杂草丛生的田地间暗中巡逻，任何人稍有靠近，他们便会伺机伏击。",al={"约根农场危险吗","约根农场的危险","约根农场的威胁"}}},fp="16,252,18.482.0,19.423.0,30.205.0,31.192.0,25.172.0,42.229.0"}
P.entries["subzone:zalashji-s-den"] = {n="萨拉辛之穴",s="萨拉辛之穴是一处隐藏在塔纳利斯东海岸的隐秘洞穴。它是萨拉辛的独居之所，这位神秘的纳迦远离他蛇人同胞们通常的聚集地，独自栖居于此。",h="萨拉辛之穴是一处隐藏在塔纳利斯东海岸的隐秘洞穴。它是萨拉辛的独居之所，这位神秘的纳迦远离他蛇人同胞们通常的聚集地，独自栖居于此。",kw={"洞穴","海岸","纳迦","塔纳利斯","萨拉辛","萨拉辛之穴"},ang={["race:NightElf"]="对于暗夜精灵来说，卡利姆多的海岸上出现任何被诅咒、变异的纳迦，都是对古代上层精灵和大分裂的残酷提醒。"},sec={{t="独居之所",b="这座沿海洞穴凿刻在塔纳利斯东岸崎岖的峭壁之中，为唯一的居住者萨拉辛提供了庇护所。众所周知，卡利姆多的纳迦通常以严明的战斗小队或沿海据点的形式聚集，然而萨拉辛却完全独自居住于此。人们对他为何将这个远离该地区主要聚居地和沙漠遗迹的孤立洞穴作为自己的领地知之甚少，但任何沿着海浪前行的旅行者在接近洞口时都应保持警惕。"}},faq={{q="萨拉辛之穴位于哪里？",a="该洞穴位于塔纳利斯的东海岸线上，深陷于毗邻海水的多岩峭壁之中。",al={"萨拉辛位置","萨拉辛之穴在哪里","萨拉辛洞穴"}},{q="萨拉辛是谁？",a="萨拉辛是一只个体纳迦，他将这座孤立的沿海洞穴作为自己的家，徘徊在远离大规模纳迦势力的沙漠海岸边。",al={"萨拉辛是谁","萨拉辛背景故事","萨拉辛是什么"}},{q="这个洞穴有相关的任务吗？",a="目前没有任何已知任务会指引冒险者前往萨拉辛之穴。它对于那些在塔纳利斯东部边缘旅行的海岸探险者来说，依然是一个充满好奇的地标。",al={"萨拉辛之穴任务","这里有任务吗","萨拉辛任务"}},{q="为什么会有纳迦独自居住在塔纳利斯？",a="他真正的动机尚不为人知。虽然纳迦通常聚集在沉没的废墟或有组织的营地附近，但萨拉辛却独自守在这个偏僻的海边巢穴里。",al={"为什么萨拉辛是独自一人的","塔纳利斯的纳迦","为什么萨拉辛在这里"}}},fp="14,211,15.496.0,32.117.0,16.142.0,47.162.0,38.165.0"}
P.entries["subzone:zoram-gar-outpost"] = {n="佐拉姆加前哨站",s="佐拉姆加前哨站是部落在灰谷西缘佐拉姆海岸建立的一处坚固桥头堡。作为关键的沿海营地，它不仅让部落能够进入维尔海，还时刻监视着该地区的威胁，例如不断逼近的娜迦和附近邪恶的深渊。",h="佐拉姆加前哨站是部落在灰谷西缘佐拉姆海岸建立的一处坚固桥头堡。作为关键的沿海营地，它不仅让部落能够进入维尔海，还时刻监视着该地区的威胁，例如不断逼近的娜迦和附近邪恶的深渊。",kw={"灰谷","黑暗深渊","部落","娜迦","前哨站","佐拉姆加","佐拉姆海岸"},ang={["faction:Alliance"]="作为部落在灰谷海岸的一处稳固据点，佐拉姆加是靠近暗夜精灵祖地的一处危险的补给落脚点。",["faction:Horde"]="该前哨站是你在灰谷西北部的主要避难所，在危险的荒野中为你提供庇护、休息和双足飞龙运输服务。"},sec={{t="海岸上的堡垒",b="佐拉姆加前哨站坐落于灰谷西北边缘，也就是原始森林没入大海的地方，是部落在佐拉姆海岸上的一处孤立据点。营地内陆被暗夜精灵的领地包围，海上则暗藏各种危险，它充当了侦察兵、猎人和萨满追踪当地威胁的前进基地。前哨站的生活是一场永无止境的守望：娜迦经常在浅滩出没，而潜伏的教徒和原始恐怖生物正从海岸下方的黑暗深渊洞穴系统中源源不断地涌出。"},{t="战略重要性",b="由于其地理位置偏远，佐拉姆加与部落其他关键据点之间保持着飞行航线连接，如碎木岗哨、十字路口和雷霆崖。尽管营地规模不大，但它却稳固了部落在西海岸的补给线。"}},faq={{q="部落为何要建立佐拉姆加前哨站？",a="部落建立该营地是为了在灰谷西海岸站稳脚跟。它负责对佐拉姆海岸进行海上监视，并提供了一个可防守的阵地，以对抗肆虐海岸的侵略性娜迦。",al={"为什么佐拉姆加在这里","佐拉姆加的目的","部落为何建立佐拉姆加"}},{q="该前哨站面临着哪些威胁？",a="直接威胁来自在佐拉姆海岸上滑行的怒鳞娜迦。此外，栖息在附近黑暗深渊神庙遗迹中的暮光教徒和野兽怪物也构成了持续的潜伏危险。",al={"佐拉姆加的威胁","佐拉姆加的敌人"}},{q="从该前哨站可以飞往哪里？",a="佐拉姆加前哨站连接着横跨卡利姆多中部的双足飞龙航线，将旅行者送往碎木岗哨、烈日石居、十字路口以及牛头人的主城雷霆崖。",al={"佐拉姆加的飞行路线","我能从佐拉姆加飞去哪里"}},{q="前哨站与黑暗深渊有什么关系？",a="黑暗深渊位于前哨站以北的海岸遗迹处。驻扎在佐拉姆加的部落部队时刻监视着从这座被淹没的神庙中渗出的腐化气息，并派遣冒险者深入内部，以对抗教徒和他们的野兽——阿库麦尔。",al={"佐拉姆附近的黑暗深渊","黑暗深渊在佐拉姆加附近吗"}}},fx={bbfe9eaf={q="佐拉姆加前哨站是什么地方？",a="佐拉姆加前哨站是部落在佐拉姆海岸的一处设防滩头阵地，位于灰谷西北部，濒临迷雾之海。它为部落提供了通往西海岸的重要通道，是一座沿海营地和军事集结点，孤立地坐落在敌对区域之中。",al={"佐拉姆加前哨站是什么","佐拉姆加前哨站概况","关于佐拉姆海岸前哨站"}},["53f73dc3"]={q="佐拉姆加前哨站危险吗？",a="前哨站本身为部落旅人提供安全、防御和庇护，但周边的佐拉姆海岸危机四伏。凶悍的娜迦在海浪间和附近废墟中巡逻，联盟部队以及潜伏在黑暗深渊中的古老恐怖，也会威胁任何离开营火守护范围的人。",al={"佐拉姆加有多危险","佐拉姆加前哨站的危险","佐拉姆海岸安全吗"}}},fp="17,302,23.568.0,20.255.0,46.229.0,35.235.0,49.185.0,63.250.0"}
P.entries["subzone:zoram-strand"] = {n="佐拉姆海岸",s="佐拉姆海岸是位于灰谷西北边缘的一条沿海海岸线，毗邻雾海。这里曾是一座被大分裂吞噬的古老暗夜精灵城市的所在地，如今海岸上充斥着怒鳍娜迦、沉船残骸和搁浅的海兽。这里也是通往黑暗深渊水下神庙群的入口。",h="佐拉姆海岸是位于灰谷西北边缘的一条沿海海岸线，毗邻雾海。这里曾是一座被大分裂吞噬的古老暗夜精灵城市的所在地，如今海岸上充斥着怒鳍娜迦、沉船残骸和搁浅的海兽。这里也是通往黑暗深渊水下神庙群的入口。",kw={"灰谷","黑暗深渊","娜迦","ruuzel","雾海","怒鳍","佐拉姆","佐拉姆海岸"},ang={["faction:Horde"]="保卫佐拉姆加前哨站的入口对于在灰谷维持北部海军和沿海存在，以对抗无情的怒鳍氏族至关重要。",["race:NightElf"]="这条海岸线是一个令人清醒的提醒，让人想起在大分裂中失落的远古世界，那里神圣的遗迹和供奉艾露恩的地下神庙如今正遭受着娜迦的践踏。"},sec={{t="大分裂海岸的废墟",b="一万年前，在大分裂将卡利姆多撕裂并使这座定居点沉入海底之前，宏伟的暗夜精灵城市佐拉姆曾坐落于此。如今，潮汐不断将远古遗物、破碎的船只残骸和巨大的海洋生物尸体冲上岸边。怒鳍娜迦已经占领了海滩和潮池，凶狠地守卫着这些被淹没的废墟和远古神器，抵御任何胆敢靠近的入侵者。"},{t="充满纷争的海岸线",b="尽管有娜迦的威胁，大陆上的旅行者和海岸漫游者依然被这条海岸线所吸引。在南方，坐落着部落的坚固据点佐拉姆加前哨站，其战士们为了保卫这片海岸在进行着持续不断的战斗。在附近的洞穴深处，坐落着黑暗深渊，这是一座曾经供奉艾露恩的古老神庙，如今却已落入邪恶之手，这使得该海岸成为了勇敢面对风浪的斥候、学者和寻宝者们的聚集地。"}},faq={{q="被摧毁前的佐拉姆是什么样子的？",a="在一万年前的大分裂之前，佐拉姆是一座宏伟的暗夜精灵城市。那场大灾变摧毁了海岸，使这座城市沉入雾海之下，只在岸边留下了锯齿状的废墟和被冲上来的小雕像。",al={"佐拉姆历史","古老的佐拉姆","佐拉姆曾经是什么"}},{q="如今谁控制着佐拉姆海岸？",a="海岸线本身大部分已被怒鳍娜迦占据，它们凶狠地保卫着浅滩和古老的废墟。部落在南部的悬崖边维持着一个坚固的据点佐拉姆加前哨站，而诸如多头蛇和螃蟹等危险的野生生物则在沙滩上游荡。",al={"谁居住在佐拉姆海岸","佐拉姆海岸的敌人","谁控制佐拉姆海岸"}},{q="黑暗深渊的入口在哪里？",a="黑暗深渊的入口位于佐拉姆海岸沿线被淹没的洞穴中。旅行者需深入水边的海岸洞穴，才能抵达通往沉没神庙的入口。",al={"黑暗深渊位置","如何找到黑暗深渊","黑暗深渊佐拉姆入口"}},{q="为什么这里有这么多搁浅的海洋生物？",a="雾海汹涌的潮汐和暗流频繁将巨大的海洋生物冲上岸。双方阵营的研究人员和博物学家经常寻找这些残骸，以调查是什么原因导致这些海洋巨兽在礁石旁丧生。",al={"搁浅的海洋生物任务","佐拉姆海岸的死鲸","搁浅的生物"}}},fx={["449b54c1"]={q="佐拉姆海岸是什么地方？",a="佐拉姆海岸是灰谷西北部一段崎岖的海岸线，濒临迷雾之海。大分裂之前，这里曾是古代暗夜精灵城市的一部分；如今，这片海滩争夺不断，散布着沉船、搁浅的巨兽和废墟。这里既是部落设防前哨站佐拉姆加的所在地，也是通往黑暗深渊地下迷宫的地表入口。",al={"佐拉姆海岸是什么","佐拉姆海岸信息","关于佐拉姆海岸"}},["7861a3b9"]={q="佐拉姆海岸为何会沦为废墟？",a="一万年前，在上古之战期间，古老的暗夜精灵聚居地佐拉姆遭到毁灭，随着薄雾之海水位上涨，大部分城市沉入海底。如今海岸上仅存这座沦陷之城残破的边缘地带，长期任其腐朽，直到蛇形纳迦从海洋深处现身，占据了海岸线及其水下神殿。",al={"佐拉姆为何沦为废墟","佐拉姆发生了什么","佐拉姆海岸的毁灭"}},["3de65288"]={q="佐拉姆海岸危险吗？",a="非常危险。海岸线上遍布凶暴的怒尾纳迦，它们竭力守护废墟，并袭击水边的旅人。敌对的蟹爪怪和凶猛的多头蛇潜伏在浪涛之间以及搁浅的尸骸旁。除了荒野中的威胁，黑暗深渊的通道深处还藏着黑暗教徒和邪恶的恐怖生物，使这片雾气笼罩的海滩对粗心大意的人而言危机四伏。",al={"佐拉姆海岸有多危险","佐拉姆海岸的威胁","佐拉姆海岸沿线的威胁"}},["8dedb8fb"]={q="佐拉姆海岸为何得名？",a="这片海岸以佐拉姆命名，这座古老的暗夜精灵城市在上古之战前曾坐落于此。尽管原城已被摧毁并吞没于海中，幸存的海滩和周边废墟自那以后便一直沿用它的名字。",al={"佐拉姆为何得名","佐拉姆海岸为何得名","佐拉姆海岸的名称含义"}}},fp="12,345,27.453.0,21.453.0,39.239.0,36.269.0,43.202.0,49.251.0"}
P.entries["subzone:zul-farrak"] = {n="祖尔法拉克",s="祖尔法拉克是一座庞大、被太阳炙烤的砂岩城市，坐落在塔纳利斯西北部的悬崖之中。沙怒巨魔长期与世隔绝，他们怀着狂热的激情、运用黑暗巫术以及从沙丘坟墓中复生的亡灵大军，守卫着这座古老的据点。",h="祖尔法拉克是一座庞大、被太阳炙烤的砂岩城市，坐落在塔纳利斯西北部的悬崖之中。沙怒巨魔长期与世隔绝，他们怀着狂热的激情、运用黑暗巫术以及从沙丘坟墓中复生的亡灵大军，守卫着这座古老的据点。",kw={"加基森","加兹瑞拉","沙地巨魔","沙怒","鞭笞者苏萨斯","塔纳利斯","祖尔法拉克"},ang={["faction:Alliance"]="人类和矮人探险家经常被吸引到这里，试图寻回古老的圣物，或是从加基森派遣救援队来营救那些消失在遗迹中的雇佣兵。",["race:Troll"]="沙怒巨魔视暗矛部族为勾结外来征服者的软弱叛徒，而像加德林大师这样的暗矛部族长者，则以忧虑的目光注视着他们堕落的沙漠同族。"},sec={{t="枯萎的残余",b="关于祖尔法拉克的遥远过去，除了巨魔传说外几乎没有留下什么记录，但占据此地的沙怒巨魔长期忍受着塔纳利斯灼热干旱的荒漠环境。他们以残忍无道而在沙漠中闻名，如今他们的祭司们正施行着一种残酷的黑暗神秘主义，挖掘出他们自己的死者，在被太阳晒白的墙垣内建立起一支蹒跚的亡灵军队。"},{t="沙之传说",b="整个加基森都在流传着关于祖尔法拉克严密守卫的城门后所隐藏的宝藏与恐怖的低语。巨魔传说中提到了一把名为鞭笞者苏萨斯的传奇阔剑，它被拆分成了两把不同的刀刃，至今仍隐藏在城市中的某处。更令人警惕的是关于伯利中士带领的一队雇佣兵流浪进入该城并被俘虏的故事，还有传闻称在城市中心的一处圣池中，沉睡着一头古老的多头蛇半神：加兹瑞拉。"}},faq={{q="这里居住着哪个巨魔部落？",a="祖尔法拉克由沙怒部落占据，这群沙地巨魔以其残忍和黑暗神秘主义在整个塔纳利斯广为人知。",al={"谁住在祖尔法拉克","沙地巨魔部落","这是什么巨魔"}},{q="为什么城市里有这么多僵尸和坟墓？",a="在绝望与孤立的边缘，沙怒巫医和暗影猎手转向了黑暗亡灵法术。他们开始复活死去的同胞作为亡灵奴仆，以此增强兵力并在塔纳利斯发动战争。",al={"为什么祖尔法拉克有亡灵","沙怒僵尸","巨魔坟墓"}},{q="城市里沉睡的古老怪物是什么？",a="这只生物是加兹瑞拉，一头巨大的多头蛇半神。它被安置在城市深处的一处圣池中沉睡，受到沙怒巨魔的崇拜。不过有不安的传闻称，通过特定的仪式器具，可以将这只野兽唤醒。",al={"多头蛇首领","水池里的古老生物","加兹瑞拉"}},{q="什么是鞭笞者苏萨斯？",a="鞭笞者苏萨斯是源自古老巨魔传说的一把传奇武器，以能够吸取受害者力量和意志而闻名。很久以前它被震碎成两把不同的剑：狂暴者之剑和反击者之剑，据传这两把剑至今仍被收藏在城内。",al={"沙怒之剑","苏萨斯","祖尔法拉克之剑传说"}}},fp="10,278,20.359.0,19.472.0,32.132.0,48.238.0,49.237.0,30.273.0"}
P.entries["subzone:zul-gurub"] = {n="祖尔格拉布",s="祖尔格拉布是一座古老的寺庙城市，深藏在荆棘谷东北部的丛林中。它曾经是广袤的古拉巴什帝国那辉煌的心脏，如今却成了一座危险的堡垒，丛林巨魔们正在这里密谋将一个古老而可怕的存在召唤到这个世界上。",h="祖尔格拉布是一座古老的寺庙城市，深藏在荆棘谷东北部的丛林中。它曾经是广袤的古拉巴什帝国那辉煌的心脏，如今却成了一座危险的堡垒，丛林巨魔们正在这里密谋将一个古老而可怕的存在召唤到这个世界上。",kw={"阿塔莱","古拉巴什","哈卡","金度","噬魂者","荆棘谷","巨魔首都","祖尔格拉布"},ang={["faction:Horde"]="部落密切关注着祖尔格拉布的黑暗仪式，因为他们意识到这位血神的归来对荆棘谷附近定居点和各部族的安全构成了生存威胁。",["race:Troll"]="对于暗矛部族而言，祖尔格拉布既是他们祖先昔日辉煌陨落的悲剧纪念碑，也是关于侍奉哈卡所带来毁灭性代价的恐怖警示。"},sec={{t="陨落帝国的心脏",b="数千年前，祖尔格拉布曾作为整个古拉巴什帝国的繁荣首都而傲视群雄，将各丛林巨魔部族统一在其宏伟的石质金字塔下。那个黄金时代在黑暗之门开启前约一千五百年时破碎了，一场残酷的内战将帝国撕裂。一个激进的祭司教派，即阿塔莱，试图召唤“噬魂者”哈卡——一位嗜血的古神——以攫取绝对权力。尽管效忠派部族联合起来击败了阿塔莱，并将他们向北流放至悲伤沼泽，但这场浩劫还是摧毁了帝国的脊梁，使祖尔格拉布沦为昔日辉煌的一道残暴阴影。"},{t="噬魂者那迫近的阴影",b="尽管被放逐，哈卡那狂热的信徒们从未放弃过他们黑暗的信仰。他们最终意识到，他们那恐怖的神灵的物理化身只能从祖尔格拉布本身的古老祭坛中被召唤出来。在城市内部，像妖术师金度这样的黑暗施法者一直在试图奴役古拉巴什大祭司，以哈卡的名义举行血祭。环绕废墟的丛林中爬满了极具攻击性的古拉巴什巨魔，他们陷入了嗜杀的狂乱之中，使得这座寺庙城市成了任何胆敢接近其边界的勇士（或傻瓜）心中恐惧的震中。"}},faq={{q="什么是祖尔格拉布？",a="祖尔格拉布是荆棘谷东北部的一座古老寺庙城市。数千年前，它曾是伟大的古拉巴什帝国的首都，但如今它是一座被充满敌意的古拉巴什部族所占据的危险废墟。",al={"祖尔格拉布历史","什么是祖尔格拉布","关于祖尔格拉布"}},{q="谁是“噬魂者”哈卡？",a="“噬魂者”哈卡是一位古老而恐怖的血神。哈卡受到狂热的阿塔莱巨魔教派的崇拜，他渴求无尽的鲜血与祭品，他的邪教徒们长期以来一直密谋通过祖尔格拉布的黑暗仪式，将他的物理化身带到艾泽拉斯。",al={"哈卡","血神","谁是噬魂者"}},{q="古拉巴什帝国为何崩溃？",a="在黑暗之门开启前约一千五百年，帝国因一场毁灭性的内战而四分五裂。激进的阿塔莱祭司试图召唤哈卡，虽然其他巨魔成功将他们驱逐出境，但这场冲突导致帝国永远地土崩瓦解。",al={"古拉巴什为何陨落","古拉巴什内战","祖尔格拉布的陷落"}},{q="探险者能安全探索这些废墟吗？",a="不能。祖尔格拉布极其危险。占据废墟的古拉巴什巨魔极其凶残，并被血腥的狂热所驱使。寻宝者和文物搜寻者经常在这些石墙内失踪，几乎无人能够生还。",al={"祖尔格拉布安全吗","祖尔格拉布宝藏","探索祖尔格拉布"}}},fp="9,278,26.656.0,36.594.1,18.239.0,29.263.0,38.281.0,41.249.0"}
P.entries["subzone:zul-mashar"] = {n="祖玛沙尔",s="祖玛沙尔是一座坐落在东瘟疫之地东北角的古老森林巨魔定居点。这里曾是苔藓剥皮部族的骄傲都城，在与人类王国的连年战争以及亡灵瘟疫的摧残下，已沦为一片荒凉的废墟。如今，其残存的守军正面临着潜移默化的崩溃，天灾军团正从内部蚕食他们，试图将他们转化为不死奴仆。",h="祖玛沙尔是一座坐落在东瘟疫之地东北角的古老森林巨魔定居点。这里曾是苔藓剥皮部族的骄傲都城，在与人类王国的连年战争以及亡灵瘟疫的摧残下，已沦为一片荒凉的废墟。如今，其残存的守军正面临着潜移默化的崩溃，天灾军团正从内部蚕食他...",kw={"东瘟疫之地","森林巨魔","哈梅亚","玛兹拉罗","苔藓剥皮部族","瑟什金","织枝","祖玛沙尔"},ang={["race:Troll"]="对于暗矛巨魔来说，目睹苔藓剥皮巨魔在祖玛沙尔的困境，是对那些在不断变化的世界中不寻找盟友，反而固守古老仇恨的孤立部族的一种严酷警示。",["race:Undead"]="被遗忘者以谨慎的实用主义看待祖玛沙尔，密切关注着日渐腐朽的苔藓剥皮部族究竟是会进行抵抗，还是最终将无可避免地通过注入新鲜的僵尸化森林巨魔来扩充天灾军团的行列。"},sec={{t="陷落的据点",b="早在天灾军团席卷北洛丹伦之前，祖玛沙尔曾是苔藓剥皮森林巨魔的权力中心。与洛丹伦人类不断的边境冲突逐渐削弱了他们的统治地位，使他们的领土变得四分五裂。当亡灵瘟疫覆盖这片地区时，苔藓剥皮巨魔遭受了与他们的凡人宿敌同样无情的打击。虽然玛兹拉罗宏伟的阶梯金字塔依然矗立，但祖玛沙尔如今已是昔日荣耀的一具空壳。在战神瑟什金和祖尔布林·织枝的指挥下，残余的巨魔固执地坚守着他们的家园，却对天灾军团的影响早已渗透进他们的队伍中，悄悄将他们的族人变为腐烂怪物的事实几乎一无所知。"},{t="潜入阴影",b="祖玛沙尔真正面临的危险并非来自天灾军团的直接围攻，而是一种从内部蔓延的腐化。尽管苔藓剥皮巨魔试图守护他们的金字塔，并在破败的北方维持独立，但天灾的代理人和秘密腐化正在他们的人群中扩散。随着像渗透者哈梅亚这样的斥候在废墟中活动，加上他们活着的战士逐渐屈服于亡灵意志，这座曾经引以为傲的据点正处于完全落入巫妖王掌控的边缘，而这一切甚至不需要一场大规模的战役。"}},faq={{q="谁控制着祖玛沙尔？",a="祖玛沙尔由苔藓剥皮森林巨魔部族占据，由战神瑟什金和祖尔布林·织枝共同领导。然而，随着亡灵瘟疫渗透进他们的社会，他们的控制权正在不断流失。",al={"祖玛沙尔的居民","祖玛沙尔统治者","苔藓剥皮部族领导者"}},{q="玛兹拉罗是什么？",a="玛兹拉罗是位于祖玛沙尔内的一座显眼的巨魔阶梯金字塔。它代表了苔藓剥皮部族祖传都城的建筑核心与精神中心。",al={"玛兹拉罗","祖玛沙尔金字塔","东瘟疫之地巨魔金字塔"}},{q="为什么祖玛沙尔会变成废墟？",a="祖玛沙尔在与洛丹伦人类王国的漫长、残酷的冲突中被逐渐消耗，随后又饱受亡灵瘟疫的摧残。瘟疫破坏了周边的土地，使苔藓剥皮部族陷入了孤立与衰弱的境地。",al={"祖玛沙尔为何被毁","祖玛沙尔发生了什么"}},{q="这里的巨魔与天灾军团结盟了吗？",a="没有，活着的苔藓剥皮巨魔对外界怀有敌意，并奋力保护他们的祖地。然而，天灾军团正在秘密感染并将他们转化为亡灵，稳步地从内部掏空这个部族。",al={"苔藓剥皮部族是天灾吗","与天灾军团合作的巨魔"}}},fp="10,422,20.765.0,29.512.1,24.206.0,19.182.0,27.225.0,44.225.0"}
P.entries["topic:agamaggan"] = {n="阿迦玛甘",s="伟大的野猪之神阿迦玛甘是艾泽拉斯远古时期行走于世间的巨型荒野半神之一。在一万年前的上古之战中，他为了对抗燃烧军团而战死沙场，他的牺牲帮助艾泽拉斯免于毁灭。他的鲜血与躯体坠落在大地上，化作了漫山遍野的荆棘，由此诞生了剃刀沼泽，也赋予了他的后裔——野猪人——生命与使命。",h="伟大的野猪之神阿迦玛甘是艾泽拉斯远古时期行走于世间的巨型荒野半神之一。在一万年前的上古之战中，他为了对抗燃烧军团而战死沙场，他的牺牲帮助艾泽拉斯免于毁灭。他的鲜血与躯体坠落在大地上，化作了漫山遍野的荆棘，由此诞生了剃刀沼...",kw={"阿迦玛甘","荒野半神","贫瘠之地","血岩碎片","塞纳留斯","伟大的野猪","野猪人","剃刀沼泽","上古之战"},ang={["class:Druid"]="德鲁伊们十分敬重阿迦玛甘，视其为与塞纳留斯并肩作战的荒野半神之一，并尊崇他在上古之战中的牺牲。",["class:Shaman"]="深入贫瘠之地的萨满祭司可以感受到阿迦玛甘的血液与剃刀沼泽的荆棘中蕴含的强大、残留的大地与灵魂能量。",["faction:Horde"]="部落每天都要与阿迦玛甘的野猪人子嗣们作战，这些野猪人对倒下的神灵有着狂热的崇拜，驱使着他们在贫瘠之地不断发动袭击。",["race:NightElf"]="暗夜精灵铭记着阿迦玛甘，那位在上古之战中为了对抗燃烧军团而献出生命的勇猛半神。"},sec={{t="上古之战",b="一万年前，在上古之战期间，强大的半神阿迦玛甘挺身而出，与燃烧军团作战。这头巨型野猪战斗时凶猛无比，尽管他最终在战斗中倒下，但他的英勇行为帮助艾泽拉斯免遭覆灭。"},{t="剃刀沼泽与血岩碎片",b="阿迦玛甘在南贫瘠之地倒下时，他巨大的尸体改变了这片土地。他流出的鲜血渗入土壤，致使巨大的、坚不可摧的荆棘丛从干燥的大地上破土而出。这些缠绕的丛林被称作剃刀沼泽。野猪人将此地视为最神圣的土地，他们认为剃刀沼泽的迷宫就是阿迦玛甘沉睡的躯体，而剃刀高地则是他张开的头骨。在贫瘠之地各处散落着结晶化的血岩碎片，据信这是半神洒下的鲜血的物理残留，其中涌动着残留的原始能量，野猪人地卜师和萨满祭司正是利用这种力量来施法。"},{t="野猪人之父",b="阿迦玛甘被尊为所有野猪人的神圣始祖。在他们眼中，周围的荆棘不仅是家园，更是造物主留给他们用以抵御敌对邻居的活体盔甲。野猪人部落相信他们神灵的灵魂在守护着他们，为战士注入勇武，为地卜师带来大地魔法。作为回报，他们积极防守荆棘，抵御不断扩张的牛头人、兽人和半人马，坚信守卫这位孕育了他们的野猪之神的遗骸是他们神圣的职责。"}},faq={{q="阿迦玛甘是谁？",a="阿迦玛甘是一位荒野半神，也是艾泽拉斯远古时期就已存在的巨型野猪神。在上古之战中，他与塞纳留斯及暗夜精灵并肩作战对抗燃烧军团，最终为了拯救世界而自我牺牲。",al={"阿迦玛甘背景故事","伟大的野猪是谁","阿迦玛甘起源"}},{q="剃刀沼泽是如何形成的？",a="当阿迦玛甘在对抗燃烧军团的战斗中阵亡时，他巨大的尸体坠落在了如今的南贫瘠之地。凡是他神圣的血液触及地面之处，巨大的荆棘丛便拔地而起，形成了如今众所周知的剃刀沼泽和剃刀高地。",al={"剃刀沼泽如何形成","贫瘠之地为何有巨型荆棘","剃刀沼泽起源"}},{q="阿迦玛甘和野猪人之间有什么联系？",a="野猪人是阿迦玛甘的直系后裔。他们狂热地崇拜这位造物主与神灵，在这些荆棘遗骸中建立定居点，并将萨满仪式奉献给他的记忆。",al={"野猪人与阿迦玛甘有关吗","野猪人之神","谁创造了野猪人"}},{q="什么是血岩碎片？",a="血岩碎片是在贫瘠之地发现的红色结晶石，据称是由阿迦玛甘干燥、浓缩后的血液形成的。它们蕴含着残留的原始魔法，野猪人地卜师和好奇的施法者用它来增强自身力量并辅助仪式。",al={"血岩碎片的作用","血岩碎片背景","阿迦玛甘之血"}},{q="暗夜精灵崇拜阿迦玛甘吗？",a="是的。暗夜精灵尊他为高贵的荒野半神之一，为了保卫卡利姆多免受军团侵害而献出了生命。",al={"暗夜精灵与阿迦玛甘"}},{q="阿迦玛甘的头骨在世界上可见吗？",a="根据野猪人的传说，通往剃刀高地那个巨大的张开的入口，正是阿迦玛甘本人的空头骨和下颚。野猪人相信，这张大嘴会吞噬并毁灭任何不对他们的神灵保持忠诚的闯入者。",al={"剃刀高地头骨","阿迦玛甘的头在哪里","阿迦玛甘入口"}}},fx={f6e0fe38={q="阿迦玛甘有着怎样的历史？",a="阿迦玛甘是原始守护者之一，受到世人尊崇，被称为伟大的野猪。一万年前，在上古之战期间，他挺身而出，与燃烧军团作战。尽管这头巨大的野猪最终战死沙场，他的行动却帮助艾泽拉斯免于毁灭；他的鲜血浸透大地之处，长出了荆棘谷地的巨大荆棘藤蔓。",al={"阿迦玛甘传说","阿迦玛甘的故事","阿迦玛甘如何战死","阿迦玛甘与上古之战"}}},fp="9,415,23.260.0,29.655.0,22.538.0,17.250.0,26.272.0,58.212.0,22.264.0,34.110.0,42.233.0"}
P.entries["topic:alliance"] = {n="联盟",s="联盟是一个由各个凡人种族组成的伟大联合体，他们因共同的荣誉、责任和保卫艾泽拉斯秩序的理想而紧密团结。联盟诞生于北方洛丹伦王国的废墟之上，目前以暴风城为核心，与铁炉堡的矮人、流亡的侏儒以及卡利姆多的暗夜精灵并肩作战。",h="联盟是一个由各个凡人种族组成的伟大联合体，他们因共同的荣誉、责任和保卫艾泽拉斯秩序的理想而紧密团结。联盟诞生于北方洛丹伦王国的废墟之上，目前以暴风城为核心，与铁炉堡的矮人、流亡的侏儒以及卡利姆多的暗夜精灵并肩作战。",kw={"联盟","洛丹伦联盟","安度因·乌瑞恩国王","bolvar fordragon","达纳苏斯","诺莫瑞根","大联盟","铁炉堡","magni bronzebeard","梅卡托克","暴风城"},ang={["faction:Alliance"]="你宣誓效忠的派系在两块大陆上并肩作战，以维护法律、传统和凡人的主权，共同抵御天灾军团、野兽和不断扩张的部落。",["faction:Horde"]="部落认为联盟是一个根深蒂固的扩张主义强权，其自以为是的理想威胁到了部落成员的主权和领土生存。",["race:Dwarf"]="铁炉堡的矮人是人类最坚定和忠诚的盟友，他们为联盟的事业贡献了强大的钢铁、山地步兵以及深厚的友谊。",["race:Gnome"]="作为铁炉堡的难民，侏儒将他们的科学创造力投入到联盟的舰队中，相信相互的忠诚最终将带来解放诺莫瑞根所需的军事力量。",["race:Human"]="作为该派系恢复的主要架构师，人类视联盟为文明和圣光教会的合法捍卫者，对抗着野蛮和恶魔的力量。",["race:NightElf"]="在第三次战争的驱使下走出隐居状态，暗夜精灵与年轻种族之间建立了一种陌生但必要的亲缘关系，以遏制部落在灰谷的领土扩张。"},sec={{t="从洛丹伦到暴风城",b="现代联盟源自最初的洛丹伦联盟，那是第二次战争期间，安度因·洛萨爵士带领暴风城难民北上，联合七大王国、矮人和高等精灵共同对抗旧部落而建立的。虽然天灾军团和第三次战争摧毁了北方，使洛丹伦沦为废墟，并将幸存者驱散到各地进行反抗，但重建的暴风王国崛起填补了这一空白。今天，暴风城已成为人类领导权的主要中心，将荣誉与信仰的旗帜带入这个破碎的世界。"},{t="基于必要性与亲情的联盟",b="联盟在东部王国的根基依赖于人类与国王麦格尼·铜须统治下的铁炉堡矮人之间坚不可摧的纽带。与矮人一同居住的是侏儒，他们因一场毁灭性的石腭怪暴动而被赶出了诺莫瑞根。在大工匠Gelbin Mekkatorque的领导下，流亡的侏儒将他们卓越的工程技术贡献给联盟的战争事业，他们相信联盟的生存对于夺回他们那被辐射污染的家园至关重要。"},{t="卡利姆多前线",b="在无尽之海的彼岸，隐世的暗夜精灵在海加尔山之战后放弃了数千年的孤立。由于失去了永生，且在灰谷因伐木问题与部落发生了激烈的领土冲突，卡多雷与他们新结识的凡人盟友站到了一起。尽管文化摩擦依然存在，而且一些传统主义者谴责人类和矮人出现在古老的森林中，但联盟为保卫卡利姆多免受恶魔残党和部落扩张的侵扰提供了至关重要的军事和外交协作。"},{t="不安的阴影",b="尽管外表强大，但联盟正受到内部压力的困扰。瓦里安·乌瑞恩国王在前往外交峰会的途中神秘失踪，留下了年幼的儿子安度因·乌瑞恩国王，由伯瓦尔·弗塔根公爵摄政。与昔日人类盟友的关系已经破裂：海上王国库尔提拉斯保持着距离，而Sylvanas Windrunner的亡灵被遗忘者现在占据了洛丹伦废墟。"}},faq={{q="联盟由哪些种族组成？",a="核心联盟由四个民族组成：暴风城的人类、铁炉堡的山地矮人、诺莫瑞根的流亡侏儒和卡利姆多的暗夜精灵。",al={"联盟种族","联盟包含哪些种族","可玩联盟种族"}},{q="现在谁领导联盟？",a="整个联盟没有唯一的绝对君主。在人类领土上，随着瓦里安·乌瑞恩国王的失踪，暴风城由少年国王安度因·乌瑞恩国王和他的摄政王伯瓦尔·弗塔根公爵统治。其他成员国由铁炉堡的国王麦格尼·铜须、侏儒的大工匠Gelbin Mekkatorque以及卡利姆多的暗夜精灵领导层领导。",al={"联盟领袖","谁是至高王","谁管理暴风城"}},{q="洛丹伦联盟是如何变成现代联盟的？",a="最初的联盟是由泰瑞纳斯·米奈希尔二世国王和安度因·洛萨爵士建立的，旨在第二次战争期间抵御旧部落。在第三次战争中洛丹伦被天灾军团摧毁后，领导权转移到了南方的重建的暴风王国，并与矮人、侏儒和暗夜精灵缔结了新的盟约。",al={"洛丹伦联盟与现代联盟的区别","洛丹伦发生了什么","联盟起源"}},{q="为什么暗夜精灵加入了联盟？",a="在第三次战争和海加尔山之战后，暗夜精灵失去了永生，无法再继续隐居。随着兽人部落在灰谷的战歌峡谷积极采伐森林，卡多雷与人类和矮人结成了军事同盟，以保卫他们的祖居之地。",al={"为什么暗夜精灵属于联盟","暗夜精灵加入联盟的背景","卡多雷联盟"}},{q="为什么库尔提拉斯现在不是联盟的一部分？",a="库尔提拉斯曾是旧洛丹伦联盟的支柱，但自那个联盟分裂以来，它一直保持中立。其海军上将戴林·普罗德摩尔入侵了杜隆塔尔并被部落杀害，此后这个岛屿王国一直没有加入以暴风城为首的新联盟。",al={"库尔提拉斯在哪里","库尔提拉斯是联盟吗","戴林·普罗德摩尔 库尔提拉斯"}},{q="为什么侏儒在第三次战争期间没有提供帮助？",a="在第三次战争期间，一场地底石腭怪入侵袭击了诺莫瑞根。由于认为地表的天灾军团威胁更大，侏儒向盟友隐瞒了这场危机并独自作战。城市最终因辐射和入侵而陷落，幸存者被迫撤往铁炉堡。",al={"侏儒在魔兽争霸3中在哪里","侏儒 第三次战争","诺莫瑞根陷落"}},{q="联盟对被遗忘者持什么立场？",a="联盟中的许多人视亡灵为畸形之物，以及毁灭洛丹伦的天灾军团的工具，联盟对占据了北方王国的亡灵保持着公开的敌意。",al={"联盟对被遗忘者的看法","为什么憎恨亡灵","被遗忘者与联盟的关系"}}},fx={["90827062"]={q="什么是联盟？",a="联盟是由凡人种族组成的强大联军，致力于维护高尚、荣誉、正义与艾泽拉斯各地的秩序。它由洛丹伦联盟覆灭后的残余势力发展而来，将人类、铁炉堡矮人、侏儒和暗夜精灵团结在共同的目标之下。联盟成员并非只因走投无路才聚在一起，而是由共同的传统、信仰，以及对恶魔腐化的深恶痛绝紧密相连。他们汇聚军事力量、技术专长与古老智慧，保护自己的人民，为饱受战火蹂躏的世界带来光明。",al={"什么是联盟","联盟成员有哪些","伟大的联盟"}},["76fd3754"]={q="联盟为何与部落交战？",a="这场冲突根深蒂固，源于世代相传的流血冲突。联盟铭记第一次和第二次战争的残酷岁月：最初的部落摧毁了暴风城王国，蹂躏了东部王国。即便双方曾在海加尔山短暂联手，和平依然脆弱而苦涩。持续不断的资源争夺，例如战歌氏族仍在灰谷祖传森林中伐木，让敌意始终高涨。在联盟许多人眼中，部落代表着一股野蛮而危险的威胁，必须时刻提防。",al={"为何与部落交战","为何仇视部落","联盟与部落的冲突","为何与部落开战"}},["760e04fc"]={q="为联盟效力意味着什么？",a="拥护联盟，就意味着成为职责、正义与秩序的坚实壁垒，抵御步步逼近的黑暗。无论你来自铁炉堡的大厅、暴风城的高塔、Tinker Town的难民工坊，还是泰达希尔的神圣枝桠，你都立誓保护盟友的土地，使其免受怪物、入侵者和敌人的野蛮侵袭。为联盟效力，意味着将共同利益和崇高理想置于个人得失之上，捍卫神圣传统，并确保艾泽拉斯自由人民得以生存。",al={"为联盟效力","联盟的职责","联盟有何要求"}}},fp="8,327,27.555.0,36.457.0,18.556.0,14.429.0,32.167.0,33.376.0,61.330.0,42.298.0,52.271.0,48.266.0,50.198.0"}
P.entries["topic:alliance-of-lordaeron"] = {n="洛丹伦联盟",s="洛丹伦联盟是历史上伟大的七个人类王国、卡兹莫丹矮人、蛮锤狮鹫骑士、侏儒和高等精灵组成的联盟，旨在第二次战争中抵抗旧部落。在最高指挥官安度因·洛萨的军事领导和泰瑞纳斯·米奈希尔二世国王的外交斡旋下，该联盟粉碎了入侵的兽人部队，并保卫了东部王国。尽管在第三次战争期间，政治分裂和天灾军团的破坏导致联盟分崩离析，但其留下的遗产为当今的联盟奠定了基础。",h="洛丹伦联盟是历史上伟大的七个人类王国、卡兹莫丹矮人、蛮锤狮鹫骑士、侏儒和高等精灵组成的联盟，旨在第二次战争中抵抗旧部落。在最高指挥官安度因·洛萨的军事领导和泰瑞纳斯·米奈希尔二世国王的外交斡旋下，该联盟粉碎了入侵的兽人部...",kw={"洛丹伦联盟","安度因·洛萨","洛丹伦王都","大联盟","第二次战争","七大王国","白银之手","泰瑞纳斯·米奈希尔"},ang={["class:Paladin"]="白银之手骑士团是大主教阿隆索斯·法奥和安度因·洛萨专门为洛丹伦联盟打造的圣光突击部队。",["faction:Alliance"]="洛丹伦联盟的记忆为以暴风城为中心的现代联盟提供了哲学基础和英雄理想。",["race:Dwarf"]="铁炉堡的铜须部族和鹰巢山的蛮锤部族都在第二次战争的战斗中与人类文明建立了现代联系。",["race:Human"]="这个联盟将七大王国汇聚在同一面旗帜下，这是自古代阿拉索帝国以来唯一的一次，在此之后，地区性的琐碎纷争和天灾军团使他们四分五裂。"},sec={{t="灰烬中诞生的联盟",b="第一次战争中暴风城遭受了可怕的洗劫，摄政王安度因·洛萨带着幸存的南方难民越过无尽之海，来到了洛丹伦王都。洛萨在泰瑞纳斯·米奈希尔二世国王面前陈述了他们的处境，说服国王召集人类诸国的统治者召开会议。尽管旧日的敌意和边境冲突积怨已深，但部落的威胁远胜于此。七个人类国家选择了洛萨作为最高指挥官，结成了一份绝望的契约。"},{t="第二次战争与新先锋",b="面对残暴的兽人战士、黑暗术士和巨大的红色巨龙，联盟制定了全新的战争准则。大主教阿隆索斯·法奥和洛萨建立了白银之手骑士团，提拔了像光明使者乌瑟尔这样的圣骑士来对抗部落的黑暗魔法。当战争蔓延到辛特兰并解除了鹰巢山的围困时，库德兰·蛮锤宣誓让其凶猛的狮鹫骑士接管天空。此后不久，铜须矮人和诺莫瑞根的侏儒获得了解放，并与奥蕾莉亚·风行者麾下的高等精灵游侠并肩作战。尽管奥特兰克的佩瑞诺德国王背信弃义，但这支伟大的联盟军仍将部落赶回了黑石塔，彻底粉碎了他们的统治。"},{t="分裂与毁灭",b="胜利带来的不是持久的和平，而是痛苦。为了维持兽人收容所和重建满目疮痍的暴风城，联盟需要高额的税收，这引发了激烈的争执。吉尔尼斯几乎看不到自身利益，于是修建了格雷迈恩之墙并切断了联系；斯托姆加德因领土和战俘纠纷而退出；奎尔萨拉斯也退回到了其魔法符文石的后方。在泰瑞纳斯国王领导下残留的联盟试图度过这场政治风暴，但当The Cult of the Damned和亡灵瘟疫席卷洛丹伦时，联盟在第三次战争中彻底瓦解。阿尔萨斯·米奈希尔的背叛掏空了王国的心脏，终结了北方王国的黄金时代。"}},faq={{q="什么是洛丹伦联盟？",a="这是在第二次战争期间，为了对抗Orgrim Doomhammer领导的部落，由七个人类王国、铁炉堡和鹰巢山的矮人、诺莫瑞根的侏儒以及奎尔萨拉斯的高等精灵组成的军事和政治联盟。",al={"什么是洛丹伦联盟","谁在最初的联盟中","大联盟历史"}},{q="为什么联盟是在洛丹伦王都而不是暴风城成立的？",a="暴风城在第一次战争中已被彻底征服并摧毁。摄政王安度因·洛萨带领幸存的居民乘船北上前往洛丹伦，向泰瑞纳斯·米奈希尔二世国王发出了外来威胁的警告。",al={"为什么是洛丹伦","第二次战争中的暴风城","为什么洛萨向北进军"}},{q="谁领导了洛丹伦联盟？",a="泰瑞纳斯·米奈希尔二世国王主持联盟并指导其政治外交，而安度因·洛萨爵士被任命为所有盟军武装力量的最高指挥官。戴林·普罗德摩尔担任舰队的大海军上将。",al={"洛丹伦联盟领袖","最高指挥官","谁负责指挥"}},{q="为什么奥特兰克背叛了联盟？",a="由于担心兽人部落不可阻挡，奥特兰克国王艾登·佩瑞诺德秘密与大酋长Orgrim Doomhammer达成了一项协议。奥特兰克允许部落从其山口安全通过，以换取不被屠杀。",al={"佩瑞诺德背叛","奥特兰克做了什么","第二次战争中的奥特兰克"}},{q="为什么洛丹伦联盟会解体？",a="第二次战争后，关于收容所维护成本和重建暴风城的开支分歧导致吉尔尼斯、斯托姆加德和奎尔萨拉斯退出。剩下的势力在第三次战争中，随着阿尔萨斯王子和天灾军团摧毁洛丹伦而土崩瓦解。",al={"为什么联盟崩溃","旧联盟发生了什么","为什么吉尔尼斯离开"}},{q="这与今天的联盟有何不同？",a="洛丹伦联盟完全以洛丹伦王都和达拉然为中心的北方王国为核心。今天的联盟以重建后的南方王国暴风城为中心，并纳入了卡利姆多的暗夜精灵，尽管它借鉴了洛萨最初的联盟理念。",al={"旧联盟与新联盟对比","联盟之间的区别","这是现在的联盟吗"}}},fx={dd426ccb={q="哪些势力曾加入洛丹伦联盟？",a="这个联盟联合了七个人类王国：洛丹伦、暴风城、激流堡、库尔提拉斯、达拉然、吉尔尼斯和奥特兰克。随着第二次战争愈演愈烈，铁炉堡的铜须矮人、鹰巢山的蛮锤矮人、诺莫瑞根的侏儒，以及奎尔萨拉斯的高等精灵也加入其中，圣骑士组织白银之手和圣光教会亦是联盟成员。",al={"洛丹伦联盟成员","哪些势力加入洛丹伦联盟","洛丹伦联盟的国家"}},["62444fc6"]={q="洛丹伦联盟是如何成立的？",a="兽人部落在第一次战争中摧毁暴风城后，摄政王安度因·洛萨带领幸存者逃往北方，向泰瑞纳斯·米奈希尔二世国王求援。泰瑞纳斯召集人类诸国的统治者齐聚首都，以应对这场威胁。各王国放下彼此间的宿怨，在洛萨的最高指挥下结成联盟。",al={"洛丹伦联盟历史","洛丹伦联盟如何建立","洛丹伦联盟的成立"}},["913db280"]={q="为什么称为洛丹伦联盟？",a="这个联盟之所以得名，是因为北方王国洛丹伦是联盟的核心与集结之地。洛丹伦国王泰瑞纳斯·米奈希尔二世在首都召集七大王国，共同应对暴风城的陷落；在第二次战争期间，洛丹伦一直是联盟的政治支柱和主要军需来源。",al={"为何称为洛丹伦联盟","洛丹伦联盟名称的含义","为何叫洛丹伦联盟"}}},fp="21,534,25.494.0,35.726.0,17.715.0,35.249.0,65.211.0,34.218.0,36.235.0,45.262.0,49.283.0"}
P.entries["topic:alterac-kingdom"] = {n="奥特兰克（王国）",s="奥特兰克曾是七个人类王国之一，坐落在崎岖的奥特兰克山脉高处。在第二次战争期间，其统治者艾登·佩罗诺尔德国王与旧部落达成了背信弃义的契约，试图保全他的王国，但这导致了该国军事力量的覆灭和彻底的崩溃。如今，它那破败的首都荒废在风雪之中，而流离失所的贵族和亡命之徒则在辛迪加的旗帜下进行着游击战。",h="奥特兰克曾是七个人类王国之一，坐落在崎岖的奥特兰克山脉高处。在第二次战争期间，其统治者艾登·佩罗诺尔德国王与旧部落达成了背信弃义的契约，试图保全他的王国，但这导致了该国军事力量的覆灭和彻底的崩溃。如今，它那破败的首都荒废...",kw={"艾登","阿利登","奥特兰克","背叛","部落","orgrim doomhammer","佩罗诺尔德","第二次战争","七大王国","辛迪加","叛国"},ang={["class:Rogue"]="前奥特兰克的山谷是秘密特工的亡命天堂，这里被辛迪加的贵族暴徒和拉文霍德庄园的神秘刺客所瓜分。",["faction:Alliance"]="对于联盟来说，奥特兰克是那场背叛的痛苦记忆，那次背叛在第二次战争期间几乎让全人类付出了一切。这种记忆加剧了对那些试图夺回祖产的辛迪加强盗的持续敌意。",["race:Human"]="对于北方王国的人类来说，奥特兰克的覆灭是关于懦弱与分裂的惨痛教训，它表明恐惧是多么轻易地就能粉碎为了抵御外敌而建立的团结。"},sec={{t="群山中的国度",b="奥特兰克兴起于几千年前，是巨魔战争后阿拉索的一个城邦。定居者们利用战略性的山口和贸易前哨，最终在帝国分裂时建立了一个独立的王国。尽管奥特兰克地形崎岖多山，但它与繁荣的洛丹伦和希尔斯布莱德接壤。历史上，这里曾涌现出坚韧的山地战士，但由于与索拉斯·托尔贝恩的斯托姆加德长期存在边境摩擦，早在黑暗之门开启之前，这个王国在政治上就已经被邻国孤立了。"},{t="大背叛",b="当安度因·洛萨爵士组建洛丹伦联盟时，艾登·佩罗诺尔德国王加入得非常勉强。当Orgrim Doomhammer率领的部落向北席卷而来时，佩罗诺尔德断定人类在劫难逃，于是暗中与大酋长达成了交易。为了换取奥特兰克的安全，佩罗诺尔德打开了防御森严的山口，密谋对抗联盟军队，甚至派遣士兵和水手协助部落围攻洛丹伦。这次背叛使得兽人远比预期更早地抵达了洛丹伦王都，当真相大白时，整个联盟为之震动。"},{t="废墟与辛迪加",b="报复来得很快。斯托姆加德的军队开进山区，揭露了佩罗诺尔德的叛国行径，并摧毁了奥特兰克的军队。泰瑞纳斯·米奈希尔二世国王对这个沦陷的国家实施了军事管制，而关于谁应该继承王位的争论让联盟的外交官们多年来陷入僵局。王国崩溃后，佩罗诺尔德国王在耻辱中死去。他的儿子，阿利登·佩罗诺尔德领主，集结了心怀怨恨、流离失所的贵族组成了辛迪加。这些强盗和雇佣兵身穿故国标志性的橙色布衣，现在正无情地战斗，试图夺回他们在希尔斯布莱德和奥特兰各地的祖产。"}},faq={{q="奥特兰克王国发生了什么？",a="奥特兰克在第二次战争期间崩溃，此前其国王艾登·佩罗诺尔德背叛了人类，投靠了旧部落。以斯托姆加德为首的联盟军队开进该地，瓦解了王国的军事力量。王权被废除，该地区被置于军事管制之下，其人民也分崩离析，陷入毁灭。",al={"奥特兰克的覆灭","为什么奥特兰克被摧毁","奥特兰克的命运","谁摧毁了奥特兰克"}},{q="佩罗诺尔德国王为什么要背叛联盟？",a="艾登·佩罗诺尔德认为联盟无法战胜入侵的部落。由于害怕他的山地王国彻底覆灭，他秘密地与大酋长Orgrim Doomhammer结盟。Doomhammer承诺，一旦洛丹伦陷落，奥特兰克将不受侵犯并获得主权保护，作为交换，他将开放山区的通行权。",al={"佩罗诺尔德为何背叛","佩罗诺尔德的动机","奥特兰克背叛的原因"}},{q="辛迪加与奥特兰克有什么关系？",a="辛迪加是奥特兰克贵族在犯罪道路上的延续，由佩罗诺尔德国王的儿子阿利登·佩罗诺尔德领主创立。该组织试图通过武力夺回他们在希尔斯布莱德和奥特兰各地的家族庄园和土地。他们标志性的橙色面具与奥特兰克历史上的国旗颜色相呼应。",al={"辛迪加与奥特兰克的关系","谁领导辛迪加","为什么戴橙色面具"}},{q="奥特兰克的传统颜色和象征是什么？",a="奥特兰克的国色是橙色。这种纹章和配色方案在第二次战争期间被其皇家军队所采用，如今被辛迪加所保留，其成员佩戴橙色的面具和兜帽。",al={"奥特兰克旗帜","奥特兰克颜色"}},{q="现在谁控制着奥特兰克城？",a="作为废墟的奥特兰克城首都没有得到承认的君主或合法政府。它在很大程度上已成为一片支离破碎的废墟，被辛迪加的亡命之徒、食人魔和野生山地野兽所占据，没有正式的联盟驻军有能力守卫那些高处的山口。",al={"谁现在统治奥特兰克","奥特兰克城废墟","谁住在奥特兰克城"}}},fx={a8320e62={q="奥特兰克王国是什么？",a="奥特兰克是七个人类古国之一，坐落于奥特兰克山脉高耸崎岖的群峰之中。它最初是古老的阿拉索帝国境内的一座设防城邦，后来发展为独立王国，控制着重要的山口和贸易路线。尽管奥特兰克比洛丹伦和激流堡等邻国弱小，军力也较为薄弱，但它占据着北方王国之间的重要领地，直到第二次战争期间灾难性的背叛永远摧毁了它的地位。",al={"什么是奥特兰克","奥特兰克王国概况","奥特兰克人是谁"}},c0d5a913={q="奥特兰克王国从何而来？",a="奥特兰克最初是古老的人类帝国阿拉索建立的城邦之一。阿拉索分崩离析后，奥特兰克成为独立王国，常与邻近的激流堡发生冲突，后来加入洛丹伦联盟，对抗兽人部落。",al={"奥特兰克历史","奥特兰克的起源","奥特兰克如何建立"}},["6b4d83cf"]={q="如今谁在领导奥特兰克的人民？",a="艾登·匹瑞诺德国王遭到囚禁并去世后，王国本身便没有公认的君主或统一政府。它的残余势力四分五裂：许多失去土地的贵族和民众聚集在艾登之子艾利丹·匹瑞诺德领主麾下，他领导辛迪加，在无法无天的行动中试图夺回祖先的领地。与此同时，饱受摧残的首都仍在野兽和敌对势力之间易手。",al={"谁在领导奥特兰克","奥特兰克国王","奥特兰克领袖"}},["080e3676"]={q="奥特兰克与谁结盟？",a="作为一个获得承认的国家，奥特兰克已无盟友。第二次战争期间，它背弃了与洛丹伦联盟的原有盟约，转而帮助奥格瑞姆·毁灭之锤的部落，因此遭到其他人类王国长期敌视。如今，辛迪加中的残余贵族沦为亡命之徒，与受雇的杀手和盗贼为伍，在与联盟和新部落的斗争中求存。",al={"奥特兰克的盟友","奥特兰克为谁而战","谁支持奥特兰克"}}},fp="17,429,21.544.0,18.579.0,22.621.0,40.314.0,43.342.0,41.301.0,50.202.0,36.245.0"}
P.entries["topic:anduin-lothar"] = {n="安度因·洛萨",s="安度因·洛萨爵士，也就是人们熟知的“暴风雄狮”，是古老的阿拉希血脉的最后一位后裔，也是洛丹伦联盟的最高指挥官。作为莱恩·乌瑞恩国王和守护者麦迪文的童年好友，洛萨带领人类度过了第一次战争的恐怖时期，并在第二次战争期间集结了北方诸国，最终在黑石山阵亡。",h="安度因·洛萨爵士，也就是人们熟知的“暴风雄狮”，是古老的阿拉希血脉的最后一位后裔，也是洛丹伦联盟的最高指挥官。作为莱恩·乌瑞恩国王和守护者麦迪文的童年好友，洛萨带领人类度过了第一次战争的恐怖时期，并在第二次战争期间集结了...",kw={"安度因·洛萨","阿拉希","黑石山","铁马兄弟会","暴风雄狮","莱恩·乌瑞恩","洛萨","最高指挥官"},ang={["class:Paladin"]="在第二次战争期间，洛萨接纳了初创的白银之手骑士团，并信任像图拉扬这样的圣骑士。在洛萨倒下后，图拉扬拿起了他破碎的剑，带领联盟走向了胜利。",["class:Warrior"]="洛萨被认为是史上最优秀的骑士和战场指挥官之一，他对骑兵战术的精通和纯粹的战斗决心激励着整个艾泽拉斯的战士们。",["faction:Alliance"]="洛萨是联盟的奠基人和首任最高指挥官，他联合了精灵、矮人和人类，将部落赶出了东部王国。",["race:Human"]="对于人类来说，洛萨是牺牲与荣誉的终极典范。他的阿拉希血统将四分五裂的人类王国团结在了一起，而他在黑石山的悲剧性死亡也为王国的解放画上了句号。"},sec={{t="雄狮的少年时代",b="洛萨身负阿拉希国王的古老血脉，与莱恩·乌瑞恩王子和麦迪文一同在暴风城王宫中长大。这三人曾在荒野中进行过鲁莽的探险，并在荆棘谷与古拉巴什巨魔发生过小规模战斗。洛萨在暴风城的军队中迅速晋升，加入了国王荣誉卫队，并作为铁马兄弟会的一名骑士而声名鹊起。"},{t="暴风城的陷落",b="当神秘的绿皮入侵者从黑色沼泽涌出时，莱恩国王任命洛萨为“国王的勇士”，负责组织王国的防御。洛萨在西部荒野、赤脊山和艾尔文森林等地对兽人突袭队进行了毁灭性的伏击，成功智胜了黑手大酋长，并打破了暴风城的第一次围攻。然而，背叛从内部摧毁了王国：麦迪文被发现是开启黑暗之门的幕后黑手，这迫使洛萨和学徒卡德加突袭了卡拉赞，处决了被腐化的守护者。当洛萨返回时，发现莱恩国王已被暗杀，暴风城也在燃烧。他集结了幸存者——包括年轻的瓦里安王子——并带领他们向北跨越无尽之海撤离。"},{t="最高指挥官与黑石山",b="抵达洛丹伦海岸后，洛萨向泰瑞纳斯·米奈希尔二世国王陈述了部落带来的严峻现实。他凭借祖传的阿拉希血统和外交威望，将人类诸国、铁炉堡矮人和高等精灵联合成了洛丹伦大联盟。洛萨被任命为联军最高指挥官，领导了将部落向南击退至黑石山脚下的战役。在那里，第二次战争末期的一场决定性战斗中，洛萨被大酋长Orgrim Doomhammer杀害。他的死并没有击垮联盟；相反，它激励了他的副官图拉扬，带领冲锋彻底击溃了部落。"}},faq={{q="安度因·洛萨是谁？",a="安度因·洛萨爵士是暴风城的一名骑士，也是阿拉希血脉的最后一位后裔。他在第一次战争期间担任国王的勇士，后来在第二次战争期间成为洛丹伦联盟的最高指挥官。他被铭记为人类历史上最伟大的英雄和战术家之一。",al={"谁是洛萨","洛萨是谁","暴风雄狮背景"}},{q="洛萨是怎么死的？",a="洛萨在第二次战争的高潮阶段死于黑石山脚下。他与大酋长Orgrim Doomhammer进行了一对一的决斗，在图拉扬率领的联盟军队击溃部落并将其追击至黑暗之门前不久倒下。",al={"洛萨之死","洛萨怎么死的","谁杀了洛萨"}},{q="为什么现任王子叫安度因？",a="瓦里安·乌瑞恩国王以安度因·洛萨爵士的名字为他年幼的儿子安度因·乌瑞恩王子命名。洛萨在暴风城的废墟中救出了还是个孩子的瓦里安，在流亡期间保护了他，并以他在第二次战争中的牺牲为代价收复了他们的家园。",al={"为什么安度因叫安度因","安度因·乌瑞恩名字由来"}},{q="洛萨与麦迪文和莱恩国王有什么关系？",a="洛萨、莱恩·乌瑞恩王子和年轻的法师麦迪文在暴风城王宫中是形影不离的童年好友。他们年轻时一起探索艾泽拉斯，与巨魔和野兽作战。悲剧的是，在发现麦迪文背叛了王国并召唤了部落之后，洛萨后来被迫带领突击队在卡拉赞讨伐麦迪文。",al={"洛萨 麦迪文 莱恩","洛萨的童年好友"}},{q="为什么洛萨被称为“最后的阿拉希人”？",a="洛萨是古老阿拉希血脉的最后一位直系后裔，该王朝数千年前最初统一了人类并建立了阿拉索帝国。这种显赫的出身使他在洛丹伦将争吵不休的北方国王们联合在联盟旗帜下时，拥有了巨大的外交威望。",al={"洛萨的阿拉希血统","阿拉希后裔"}},{q="洛萨在铁马兄弟会中担任什么角色？",a="洛萨在职业生涯早期被授予爵位，并晋升为铁马兄弟会（暴风城的精锐骑兵骑士团）中的一名骑士。在整个第一次战争期间，他利用他们纪律严明的骑兵冲锋，多次包抄并打乱了部落的阵型。",al={"铁马兄弟会 洛萨","暴风城骑士 洛萨"}}},fp="13,379,16.409.0,21.740.1,40.666.0,22.313.0,19.247.0,39.246.0,54.354.0,46.300.0,55.280.0"}
P.entries["topic:argent-dawn"] = {n="银色黎明",s="银色黎明是一个中立的骑士组织，致力于消除艾泽拉斯各地邪恶的威胁，其中最著名的是天灾军团和燃烧军团。它由白银之手骑士团的幸存者组建，他们拒绝了血色十字军狂热的偏执，欢迎任何种族或阵营中尊崇圣光事业的勇士。从他们设防的圣地圣光之愿礼拜堂，到遍布卡利姆多的遥远哨所，他们始终站在对抗黑暗的最前线。",h="银色黎明是一个中立的骑士组织，致力于消除艾泽拉斯各地邪恶的威胁，其中最著名的是天灾军团和燃烧军团。它由白银之手骑士团的幸存者组建，他们拒绝了血色十字军狂热的偏执，欢迎任何种族或阵营中尊崇圣光事业的勇士。从他们设防的圣地圣...",kw={"银色黎明","亡灵壁垒","寒风营地","委托","圣光之愿礼拜堂","玛克斯韦尔·泰罗索斯","瘟疫之地","血色十字军","天灾军团","天灾石","白银之手"},ang={["class:Paladin"]="对于圣战者来说，银色黎明代表了白银之手骑士团未受腐蚀的遗产，当血色十字军屈服于疯狂时，他们坚守着同情、牺牲和职责。",["faction:Alliance"]="银色黎明在暴风城和达纳苏斯设有官方大使馆，为联盟士兵提供了一条从巫妖王手中收复洛丹伦的正义之路。",["faction:Horde"]="虽然是由前洛丹伦骑士建立的，但银色黎明毫无偏见地欢迎部落勇士，这使得他们成为部落英雄直接参与瘟疫之地战役的少数途径之一。",["race:Undead"]="痛恨天灾军团的被遗忘者可以在银色黎明的营地中找到一个罕见的务实避难所，在这里，你对抗克尔苏加德的行动远比你腐烂的肉体更重要。"},sec={{t="信仰的分裂",b="当大领主亚历山德罗斯·莫格莱尼倒下、洛丹伦陷入毁灭时，残破的白银之手骑士团成员产生了激烈的意见分歧。许多幸存者屈服于悲伤和妄想，转变为排外的血色十字军。然而，像玛克斯韦尔·泰罗索斯男爵这样的老兵意识到，他们曾经的同志已经背弃了圣光的真正教义。他们拒绝屈服于疯狂或抛弃亡国，因此分裂出来组建了银色黎明——一个致力于与任何愿意战斗的人（无论是联盟还是部落）并肩保卫艾泽拉斯的组织。"},{t="瘟疫之地的最前线",b="银色黎明的主要据点是位于东瘟疫之地荒芜之地的圣光之愿礼拜堂。在这个神圣的堡垒中，该组织协调着一场针对克尔苏加德的死灵法师和骷髅军团的无休止战争。他们在寒风营地和提瑞斯法林地的亡灵壁垒外设有前哨站，银色黎明的军官会向冒险者发放附魔委托，用从亡灵尸体上缴获的天灾石来支付赏金。尽管缺乏血色十字军那样庞大的人力，但银色黎明凭借毅力、团结和坚定不移的纪律守住了防线。"},{t="艾泽拉斯全境的警惕",b="尽管洛丹伦仍然是他们的主要战场，但银色黎明在卡利姆多和世界各地的首府都保持着活跃的监视。他们在暴风城、达纳苏斯和地精贸易城镇永望镇都保持着外交存在。在更远的地方，像净化者德尔格伦这样的特工在黑海岸和灰谷对抗恶魔崇拜，而凄凉之地和被淹没的黑暗深渊遗迹中的侦察兵则在调查涉及暗影议会和暮光之锤教派的邪恶威胁。"},{t="不安的休战与潜伏的敌人",b="面临被天灾军团消灭的威胁，组织内一个被称为“圣光兄弟会”的务实派系努力与血色十字军维持着脆弱的休战。然而，双方的关系依然十分紧张。像尼古拉斯·兹维伦霍夫公爵这样的高级军官积极批准针对斯坦索姆血色十字军高层的秘密打击，以清除他们眼中异端狂热。更危险的是，黑暗势力不断试图渗透银色黎明的行列——包括秘密潜伏的特工，他们从前线窃取死灵秘密，以供其他地方的叛徒主子使用。"}},faq={{q="银色黎明和血色十字军有什么区别？",a="两个组织都诞生于洛丹伦陷落后白银之手骑士团的残部。血色十字军变得狂热且排外，视所有外人和非人类为潜在的瘟疫携带者。银色黎明拒绝背弃圣光的真正教义，向联盟和部落的种族开放，共同对抗邪恶。",al={"银色黎明与血色十字军","银色黎明为何分裂","黎明与十字军的区别"}},{q="我该怎么处理天灾石？",a="银色黎明的军官接受天灾石作为对抗亡灵的服役证明。这些恐怖的代币象征着战胜天灾军团的战果，也有助于该组织辨认其盟友。",al={"天灾石的用途","银色黎明天灾石","上交天灾石"}},{q="部落玩家可以加入或与银色黎明合作吗？",a="可以。银色黎明是绝对中立的，在政治立场之外运作。他们积极招募兽人、巨魔、牛头人，甚至是被遗忘者，只要他们致力于对抗天灾军团和燃烧军团，并且在提瑞斯法林地的边界设立了像亡灵壁垒这样的招募站。",al={"部落可以加入银色黎明吗","银色黎明是联盟专属吗","银色黎明对部落友好"}},{q="他们在卡利姆多做什么？",a="银色黎明将其使命视为保护整个艾泽拉斯，而不仅仅是洛丹伦。特工们已经前往黑海岸、灰谷和凄凉之地，以消灭暗影议会的崇拜团体，对抗暮光之锤的阴谋家，并防范恶魔的入侵。",al={"卡利姆多的银色黎明","灰谷的银色黎明","银色黎明为何在黑海岸"}},{q="什么是圣光兄弟会？",a="圣光兄弟会是银色黎明内部的一个激进分支，由指挥官埃里戈尔·黎明使者领导。他们致力于与血色十字军保持一种功能性（尽管紧张）的工作关系，以便两个派系都能将怒火集中在克尔苏加德身上，而不是互相争斗。",al={"圣光兄弟会","银色黎明圣光兄弟会","埃里戈尔·黎明使者阵营"}}},fx={a2a95d31={q="什么是银色黎明？",a="银色黎明是一个中立的骑士组织，致力于守护艾泽拉斯免受毁灭性邪恶势力的侵害，其中最主要的敌人便是天灾军团和燃烧军团。与政治阵营或排外教派不同，银色黎明不分种族，欢迎任何种族的成员和勇士加入；他们唯一的共同点，是对圣光的虔诚，以及绝不让世界陷入黑暗的决心。",al={"银色黎明成员","银色黎明组织","银色黎明的职责"}},fb8338d1={q="谁在领导银色黎明？",a="玛克斯韦尔·泰罗索斯男爵领导银色黎明，并在东瘟疫之地的主要圣所圣光之愿礼拜堂指挥他们对抗亡灵的远征。",al={"银色黎明领袖","谁负责领导银色黎明","泰罗索斯领主与银色黎明"}},["7fcb74f5"]={q="银色黎明与谁结盟？",a="银色黎明严守政治中立，将联盟和部落都视为共同对抗邪恶的盟友。他们的军官会招募从暴风城到奥格瑞玛的英雄。尽管银色黎明与血色十字军有着共同的亡灵敌人，偶尔也会通过圣光兄弟会维持脆弱的休战，但他们认为血色十字军狂热的信条是危险的异端邪说。",al={"银色黎明的盟友","银色黎明与部落合作吗","谁与银色黎明合作"}},["7042b727"]={q="银色黎明是如何成立的？",a="洛丹伦沦陷、高阶领主亚历山德罗斯·莫格莱尼遇害后，白银之手的残部四分五裂。许多骑士屈从于狂热的偏执，组建了血色十字军；而那些厌恶日益高涨的极端主义的人则脱离了他们。他们决心不带偏见地坚守圣光的真正教义，于是组建银色黎明，以荣誉之名对抗天灾军团。",al={"银色黎明历史","银色黎明的起源","银色黎明如何成立"}}},fp="11,489,17.588.0,30.596.0,24.503.0,29.576.1,71.356.0,32.182.0,52.287.0,32.260.0,37.283.0"}
P.entries["topic:arthas-menethil"] = {n="阿尔萨斯·米奈希尔",s="阿尔萨斯·米奈希尔曾是洛丹伦的金发王子，也是白银之手骑士团备受赞誉的圣骑士。在第三次战争期间，为了追捕散布瘟疫的恶魔幕后黑手，他误入歧途。在冰封的北方夺取了被诅咒的符文剑霜之哀伤后，他出卖了自己的灵魂，谋杀了他的父亲泰瑞纳斯国王，并以天灾军团黑暗勇士的身份带头摧毁了自己的家园。",h="阿尔萨斯·米奈希尔曾是洛丹伦的金发王子，也是白银之手骑士团备受赞誉的圣骑士。在第三次战争期间，为了追捕散布瘟疫的恶魔幕后黑手，他误入歧途。在冰封的北方夺取了被诅咒的符文剑霜之哀伤后，他出卖了自己的灵魂，谋杀了他的父亲泰瑞...",kw={"阿尔萨斯","霜之哀伤","巫妖王","洛丹伦","米奈希尔","天灾军团","斯坦索姆","泰瑞纳斯"},ang={["class:Paladin"]="阿尔萨斯是白银之手最大的悲剧和耻辱；他的堕落玷污了乌瑟尔竭力灌输的正义与保护信条。",["faction:Alliance"]="阿尔萨斯的叛国行为让洛丹伦联盟失去了其最伟大的王国、其首都，以及那支曾经支撑人类信仰的传奇圣骑士组织。",["race:Human"]="洛丹伦的毁灭将人类分裂成两半，难民散落全球，使得暴风城成为了人类最后的大本营。",["race:Undead"]="被遗忘者对阿尔萨斯怀有无与伦比的仇恨，他们在希尔瓦娜斯女王的领导下挣脱了这位黑暗王子的心智控制，从而为他们的堕落寻求复仇。"},sec={{t="金发王子",b="阿尔萨斯是泰瑞纳斯·米奈希尔二世国王之子，在成长过程中深受洛丹伦联盟理想的熏陶。他由穆拉丁·铜须进行战斗训练，并在光明使者乌瑟尔的教导下加入了白银之手骑士团，被人们视为人类的未来，深受各界敬仰。他勇敢、技艺精湛，且极力维护他的人民，曾顽强地对抗黑石氏族的兽人入侵和森林巨魔战队。然而在他那光鲜亮丽的外表下，却隐藏着绝不妥协的傲慢和对失败的偏执恐惧。"},{t="天灾军团与大清洗",b="当神秘的亡灵瘟疫席卷北洛丹伦时，阿尔萨斯与女法师Jaina Proudmoore并肩驰骋，奔波在乡间以阻止其蔓延。从布瑞尔到Andorhal追踪受污染的谷物时，他杀死了死灵法师克尔苏加德，却发现了一个由恐惧魔王玛尔加尼斯策划的巨大阴谋。在面对被感染的斯坦索姆民众时，阿尔萨斯选择了现实的残酷而非道德的束缚，下令在城中居民异变前将他们全部屠杀。由于被他的疯狂行径所震慑，乌瑟尔和Jaina在城市燃起大火时离他而去。"},{t="堕落与升格",b="复仇心切的阿尔萨斯追踪玛尔加尼斯来到了诺森德的冰封荒原。在那里，他与穆拉丁重逢并发现了符文剑霜之哀伤，他不顾其可怕的诅咒，用它击败了恶魔。这把剑割裂了阿尔萨斯的灵魂，使他成为了巫妖王的傀儡。作为死亡骑士回到王都后，阿尔萨斯将符文剑刺入了他父亲的心脏，让洛丹伦沉没在灰烬与死亡之中。他摧毁了白银之手，围攻了达拉然，并在前往冰封王座与他的黑暗主人合二为一之前，在奎尔萨拉斯留下了一条血腥之路。"}},faq={{q="阿尔萨斯·米奈希尔在堕落前是谁？",a="阿尔萨斯曾是洛丹伦王国的王储，也是泰瑞纳斯·米奈希尔二世国王的继承人。他在十九岁时加入了白银之手骑士团，被广泛认为是王国中最优秀的年轻圣骑士和剑士之一。",al={"阿尔萨斯背景故事","阿尔萨斯王子是谁","洛丹伦王子阿尔萨斯"}},{q="为什么阿尔萨斯要清洗斯坦索姆？",a="城中的居民已经食用了被亡灵瘟疫污染的谷物，注定会变成受玛尔加尼斯控制的无脑亡灵。阿尔萨斯认为仁慈已不可能，遂下令立即屠杀所有民众，以防止一支天灾军团大军崛起。",al={"为什么阿尔萨斯清洗斯坦索姆","斯坦索姆的清洗","斯坦索姆大清洗"}},{q="阿尔萨斯是如何堕落的？",a="出于消灭玛尔加尼斯的执念，阿尔萨斯远赴诺森德，并夺取了由巫妖王锻造的被诅咒的符文剑霜之哀伤。这把剑抽走了他的灵魂，并将他的心智束缚在耐奥祖麾下，使他成为了天灾军团的先锋死亡骑士。",al={"阿尔萨斯如何变邪恶","阿尔萨斯腐化","为什么阿尔萨斯成为死亡骑士"}},{q="泰瑞纳斯国王发生了什么事？",a="在屈服于霜之哀伤后，阿尔萨斯伪装成凯旋的征服者回到了王都。在王座大厅里，伴随着钟声和飘落的玫瑰花瓣，他拔出符文剑，刺穿了自己的父亲。",al={"阿尔萨斯弑父","泰瑞纳斯国王之死","泰瑞纳斯发生了什么"}},{q="阿尔萨斯与Jaina Proudmoore是什么关系？",a="Jaina Proudmoore和阿尔萨斯在年轻时曾有过一段恋情，当他在前线奋战以控制瘟疫时，她曾伴随其左右。但他此后在斯坦索姆展现出的残酷行径迫使她离他而去。",al={"阿尔萨斯和吉安娜","吉安娜爱阿尔萨斯吗","阿尔萨斯恋情"}},{q="阿尔萨斯现在在哪里？",a="在保卫冰封王座抵御恶魔猎手伊利丹之后，阿尔萨斯登上冰冠冰川，粉碎了巫妖王的冰封牢笼，并将自己的本质与耐奥祖合而为一，从诺森德统治着天灾军团。",al={"阿尔萨斯在哪里","阿尔萨斯现状","阿尔萨斯还活着吗"}}},fx={b80d5fb0={q="谁在领导阿尔萨斯·米奈希尔？",a="阿尔萨斯效忠于巫妖王，后者是亡灵天灾的最高主宰。阿尔萨斯最初为复仇前往诺森德，随后拿起受诅咒的符文剑霜之哀伤，将自己的灵魂献给了它的黑暗低语。他彻底交出了自己的意志，成为耐奥祖麾下最强大的死亡骑士与勇士，以主人的名义统率军队，之后返回冰封王座，与巫妖王本人融为一体。",al={"阿尔萨斯效忠于谁","阿尔萨斯的领袖","谁控制着阿尔萨斯"}},["8c3ad81e"]={q="阿尔萨斯·米奈希尔与谁结盟？",a="阿尔萨斯统率天灾军团，这是一支由无意识的亡灵、通灵师和恐怖生物组成的怪物大军，皆由亡灵瘟疫创造。他最重要的副官之一是复生的巫妖克尔苏加德。阿尔萨斯曾在克尔苏加德生前将其杀死，后来又将他复活，让他负责监督洛丹伦废墟。阿尔萨斯只为天灾军团和巫妖王效力，与艾泽拉斯所有生灵建立的国度都处于激烈敌对状态。",al={"阿尔萨斯的盟友","阿尔萨斯与谁共事","阿尔萨斯所属阵营"}}},fp="15,401,17.537.0,27.586.1,23.589.2,40.244.0,32.293.0,32.257.0,30.220.0,53.176.0,26.218.0"}
P.entries["topic:black-dragonflight"] = {n="黑龙军团",s="黑龙军团曾是泰坦任命的坚定的大地守护者，负责守护艾泽拉斯深邃的地底疆域，但后来堕入了疯狂与背叛。在被囚禁的上古之神那阴险低语的腐蚀下，他们的领袖耐萨里奥变成了死亡之翼，将他的族群变成了这颗星球上最具破坏力且最令人憎恶的势力之一。如今，幸存的龙裔在阴影中编织阴谋，向凡人王国发动秘密战争。",h="黑龙军团曾是泰坦任命的坚定的大地守护者，负责守护艾泽拉斯深邃的地底疆域，但后来堕入了疯狂与背叛。在被囚禁的上古之神那阴险低语的腐蚀下，他们的领袖耐萨里奥变成了死亡之翼，将他的族群变成了这颗星球上最具破坏力且最令人憎恶的势...",kw={"黑龙人","黑龙","deathwing","龙军团","大地守护者","卡兹格罗斯","奈法利安","耐萨里奥","奥妮克希亚"},ang={["class:Shaman"]="萨满怀着深切的悲伤和厌恶看待黑龙，因为他们知道黑龙挥舞神圣的大地元素之力并不是为了维持和谐，而是将岩石和熔岩扭曲成了折磨的工具。",["faction:Alliance"]="联盟必须时刻警惕政治颠覆，因为黑龙军团屡次试图腐化人类贵族，并利用人类宫廷中的贵族野心。",["faction:Horde"]="部落对黑龙军团的阴谋怀有长久的怨恨，因为在之前的战争中，部落深受其操纵性的干涉之苦，并且在卡利姆多和东部王国的群山中屡屡面对他们地底族群的威胁。"},sec={{t="堕落的守护者",b="很久以前，泰坦卡兹格罗斯将他的祝福赐予了耐萨里奥，创造了黑龙军团来守护大地，造就群山，并保卫艾泽拉斯的深层洞穴。在漫长的岁月中，他们与其他军团并肩作战，作为耐心且坚毅的守护者。然而，他们与世界地底基石的紧密联系却成了他们毁灭的原因。他们栖息在最深处的空洞中，危险地接近着上古之神的沉没监狱。几个世纪以来，黑暗的低语侵蚀了这位高贵的大地守护者的心智，驱使他陷入疯狂，并将他整个族群扭曲成了残酷的毁灭工具。"},{t="背叛与火焰",b="在上古之战时期，耐萨里奥以毁灭者死亡之翼的身份背叛了族人，彻底瓦解了巨龙的团结。从那时起，黑龙军团就一直对红龙、蓝龙、绿龙和青铜龙军团发动无情的、充满恶意的战争，这些军团将他们的残忍视为对生命绝对的亵渎。黑龙不再照料土地，而是挥舞着熔岩、黑魔法和灼热的硫磺去焚烧他们曾经滋养的土地，并以在凡人国度中播撒混乱、苦难和无尽的争端为乐。"},{t="人类伪装与凡人阴谋",b="与许多仅依靠利爪和火焰的野兽不同，黑龙是操纵大师。他们经常采用人形——通常是目光犀利、黑发修养良好的外表——来渗透皇室法庭和议会。通过诱导领导者走向傲慢，在贵族世家间挑拨离间，并向脆弱的耳朵低语致命的建议，黑龙军团从内部策划了凡人文明的衰落，他们更倾向于让王国分崩离析，然后再派遣巨龙去焚毁残骸。"}},faq={{q="为什么黑龙是邪恶的？",a="他们古老的职责将他们与艾泽拉斯的地底深处紧密相连，而那里正是上古之神被封印的地方。几千年来，这些实体疯狂的低语渗入了耐萨里奥的思维，将他的保护本能扭曲为偏执和恶意，直到他的整个族群都跟随他走向腐化。",al={"黑龙为什么变坏","谁腐化了死亡之翼","黑龙的疯狂"}},{q="黑龙拥有什么样的力量？",a="由于被泰坦卡兹格罗斯授予了统治大地的力量，他们掌控着岩石、熔岩和深层的地底力量。在堕落状态下，他们挥舞着被称为黑魔法的动荡地元素之力，呼出灼热的火焰和熔岩，同时他们厚重的鳞片不断散发着强烈的热量。",al={"黑龙魔法","黑龙军团能力","黑龙能做什么"}},{q="黑龙会使用伪装吗？",a="是的。黑龙擅长渗透和政治操纵。他们偏爱的人形伪装通常是富有魅力、黑发黑眼的高贵人类，这使他们能够自由地混迹于法庭中，操纵君主，并引发内乱，而不暴露其真实的巨龙本性。",al={"巨龙会化为人形吗","黑龙的凡人伪装","伪装成人类的黑龙"}},{q="如何辨别黑龙的名字？",a="黑龙军团的成员通常遵循特定的命名传统：男性名字的后缀通常为“-ion”（如耐萨里奥），而女性名字的后缀通常为“-ia”（如奥妮克希亚）。许多黑龙还会采用唤起灰烬、阴影、石头或毁灭意象的词汇。",al={"黑龙命名习惯","黑龙的名字","黑龙如何命名"}},{q="为什么其他龙军团憎恨他们？",a="在上古之战中，大地守护者背叛了其他军团，屠杀了成千上万的族人。红龙军团尤其蔑视他们，将他们火热的恶意和腐蚀性的影响视为对生命本身的不自然亵渎。",al={"红龙军团与黑龙军团","为什么巨龙互相争斗","巨龙军团内战"}},{q="现在谁领导着黑龙军团？",a="他们的古老守护巨龙死亡之翼在过去的失败后已淡出公众视野，留下他危险的族群分散成破碎的派系。如今，像奈法利安和奥妮克希亚这样杰出的后代，都在追求他们自己冷酷的野心，企图奴役对手、颠覆王国并繁育黑暗的造物。",al={"黑龙领袖是谁","死亡之翼在哪里","谁统治黑龙"}}},fx={["0af770e1"]={q="什么是黑龙军团？",a="黑龙军团是由龙类、龙人和龙兽组成的族群，最初受到泰坦卡兹格罗斯的祝福，肩负着坚定守护大地的职责。黑龙军团曾被尊为艾泽拉斯深层领域、群山与地下洞窟的高贵守护者；然而，当它们古老的领袖屈服于上古之神的黑暗低语后，整个军团都陷入了疯狂。",al={"黑龙是谁","黑龙是什么","什么是黑龙军团"}},["146344cc"]={q="黑龙军团来自哪里？",a="无数个千年以前，泰坦赋予伟大的守护巨龙、岩石守护者奈法利安及其黑龙族群掌控岩石与熔岩的力量。长久以来，它们与其他龙军团和谐共处，一同塑造群山与山谷。然而，它们与大地深处的紧密联系，使它们暴露在被囚禁的上古之神的低语之下。奈法利安和他的子嗣彻底陷入疯狂，背弃神圣职责，将元素之力用于毁灭与恐怖。",al={"黑龙军团历史","黑龙起源","黑龙的历史"}}},fp="18,450,21.607.0,17.534.0,33.551.1,27.329.0,35.302.0,31.302.0,39.259.0,41.265.0,37.306.0"}
P.entries["topic:blackrock-clan"] = {n="黑石氏族",s="黑石氏族是一个以严格的军事纪律、无与伦比的锻造技术以及在第一次和第二次战争中的核心地位而闻名的尚武兽人氏族。如今，该氏族分裂严重：一些老兵追随萨尔加入了新部落，而一个名为黑部落的邪恶叛乱分支则在雷德·黑手的领导下占据了黑石山的高处。",h="黑石氏族是一个以严格的军事纪律、无与伦比的锻造技术以及在第一次和第二次战争中的核心地位而闻名的尚武兽人氏族。如今，该氏族分裂严重：一些老兵追随萨尔加入了新部落，而一个名为黑部落的邪恶叛乱分支则在雷德·黑手的领导下占据了黑...",kw={"黑手","黑石","黑部落","毁灭之锤","伊崔格","雷德","尖塔"},ang={["faction:Alliance"]="从暴风城的燃烧到黑石山和卡兹莫丹的血腥围攻，联盟军队在三场战争中与黑石氏族进行了对抗。",["faction:Horde"]="萨尔将雷德的黑石极端分子视为对新部落和平与荣誉的生存威胁，称他们为沉迷于恶魔奴役的叛徒。",["profession:Blacksmithing"]="黑石氏族传奇般的金属加工工艺塑造了现代兽人的攻城战术和重型板甲，这是源于几个世纪以来在元素熔炉中冶炼独特矿石的结晶。",["race:Orc"]="黑石氏族诞生了兽人历史上两位最伟大的大酋长，然而他们在东部王国的残党却成了血腥旧部落痛苦的记忆。"},sec={{t="旧部落的铁砧",b="黑石氏族来自德拉诺，以严苛的阶级制度、重型盔甲和精湛的锻造技术而闻名。在酋长黑手的领导下，他们成为了旧部落入侵艾泽拉斯期间的残酷核心，并对暴风城展开了围攻。当Orgrim Doomhammer击杀黑手以清除古尔丹对部落的直接操控后，在第二次战争的艰苦战役中，氏族和部落的领导权依然牢牢掌握在黑石氏族手中。"},{t="分裂的遗产",b="Following the Horde's catastrophic defeat at Blackrock Mountain, the clan shattered. Many warriors were rounded up and placed in Alliance internment camps, later to be liberated by Thrall and inducted into his reformed New Horde. However, unrepentant elements rallied behind Blackhand's sons, Rend and Maim. This faction retreated into the heights of Blackrock Spire, forming the hostile Dark Horde alongside remnants of the Dragonmaw and other rogue clans."},{t="黑石塔的威胁",b="如今，雷德·黑手在黑石塔的宝座上宣称自己才是真正的大酋长。黑部落与潜伏在下方熔岩深处的黑铁矮人维持着一种不安且充满背叛的休战状态，同时对联盟和萨尔的部落发起战争。在洛丹伦，人们也发现了该氏族那些受到恶魔腐蚀、顽固不化的残党，他们正试图复兴黑暗的祭祀仪式。"}},faq={{q="黑石兽人属于萨尔的部落吗？",a="部分属于，但绝大多数在东部王国遇到的黑石兽人并不属于。虽然像伊崔格这样受人尊敬的黑石老兵在卡利姆多效忠于萨尔，但驻扎在黑石山的大部分氏族成员追随雷德·黑手，并将萨尔的新部落视为软弱的叛徒。",al={"黑石氏族属于部落吗","黑石兽人友好吗","萨尔与黑石氏族"}},{q="目前谁在领导黑石氏族？",a="在黑石山，达尔·雷德（雷德）·黑手领导着黑部落分裂派系，并自称是其父曾经统帅的氏族的领导者。那些融入新部落的黑石兽人则直接听命于萨尔大酋长。",al={"黑石氏族领袖","谁领导黑石氏族","雷德·黑手领袖"}},{q="什么是黑部落？",a="黑部落是一个占据黑石塔上层的流亡派系，由顽固的黑石兽人、黑牙氏族老兵以及结盟的龙喉氏族兽人组成。在雷德·黑手的领导下，他们拒绝承认萨尔的权威，并试图在旧部落的旗帜下征服艾泽拉斯。",al={"什么是黑部落","雷德的部落","黑石黑部落"}},{q="黑手怎么了？",a="第一次战争期间，Orgrim Doomhammer向大酋长黑手发起了玛克戈拉决斗，旨在剥夺暗影议会对傀儡统治者的控制。Orgrim用毁灭之锤击碎了黑手的头骨，不仅夺取了大酋长的头衔，还获得了黑石氏族的领导权。",al={"黑手怎么死的","谁杀了黑手","orgrim击杀黑手"}},{q="为什么洛丹伦会有黑石兽人？",a="第二次战争后，该氏族的分裂势力向北逃窜或潜伏在洛丹伦。其中一些战团重新转向了恶魔崇拜和黑暗祭祀，引来了联盟的愤怒，后来在第三次战争中又招致了天灾军团的敌意。",al={"奥特兰克的黑石兽人","洛丹伦的黑石兽人","崇拜恶魔的黑石兽人"}}},fx={["2b76c337"]={q="什么是黑石氏族？",a="黑石氏族是德拉诺最负盛名、纪律最严明的兽人氏族之一。他们以精湛的锻造技艺和钢铁般的意志闻名。在第一、第二次战争期间，他们在酋长黑手和Orgrim Doomhammer的率领下，构成了旧部落的核心力量。后来，部分成员追随萨尔加入他建立的新部落，但大多数人仍是盘踞在黑石山的叛变传统派。",al={"黑石兽人是谁","黑石氏族传说","什么是黑石氏族"}},["77427c0a"]={q="为什么黑石兽人会敌视旅人？",a="自由行动的黑石兽人仍执迷于旧部落的血腥征服，拒绝接受萨尔的和平理念。他们以武力为荣，深深憎恨联盟和萨尔的部落，视任何闯入其领地的人——尤其是黑石山和赤脊山一带——为入侵者，必欲杀之或奴役之。",al={"黑石兽人为什么攻击","黑石氏族敌对","黑石氏族为什么邪恶"}},["2a83fd4b"]={q="黑石氏族与谁结盟？",a="追随雷德·黑手的黑石兽人从黑石塔统领黑暗部落。为了增强实力，对抗黑铁矮人和联盟，他们与龙喉氏族的残部、当地的森林巨魔、食人魔以及黑龙军团结盟。",al={"黑石氏族的盟友","黑石兽人与谁合作","黑暗部落的盟友"}}},fp="14,380,26.476.0,18.457.0,23.422.0,46.266.0,44.239.0,23.278.0,27.265.0,42.255.0"}
P.entries["topic:bronzebeard-clan"] = {n="铜须氏族",s="铜须氏族是铁炉堡的统治者，也是那里的主要矮人部族。在远古的三锤之战中获胜后，他们与人类和侏儒建立了稳固的盟友关系。如今，在国王麦格尼·铜须的领导下，他们已成为联盟的中流砥柱。",h="铜须氏族是铁炉堡的统治者，也是那里的主要矮人部族。在远古的三锤之战中获胜后，他们与人类和侏儒建立了稳固的盟友关系。如今，在国王麦格尼·铜须的领导下，他们已成为联盟的中流砥柱。",kw={"铜须","high seat","铁炉堡","卡兹莫丹","麦多兰","麦格尼","穆拉丁","三锤"},ang={["profession:Blacksmithing"]="铜须氏族以其无与伦比的冶炼、武器制造和重型护甲工艺在艾泽拉斯享有盛誉。",["race:Dwarf"]="每一位可玩的矮人角色都来自铜须王国或服从于该王国，他们作为卡兹莫丹的坚定捍卫者效忠于麦格尼国王。",["race:Gnome"]="当诺莫瑞根被穴居人入侵陷落时，铜须氏族在铁炉堡的工匠区提供了无条件的庇护。",["race:Human"]="人类与铜须矮人保持着长期的联系，他们因共同的尚武传统和贸易往来而紧密结合。"},sec={{t="三锤之战",b="很久以前，铁炉堡的矮人社会在至高王莫迪姆斯·安威玛尔的统治下繁荣昌盛。大约230年前，这位国王因年老去世，原本潜藏的矛盾演变成了内战。塞恩麦多兰·铜须指挥着铁炉堡内传统的守备军和最大的常备军队，成功将蛮锤氏族和黑铁氏族赶出了山脉。当黑铁部族的索瑞森大帝发动进攻试图夺取卡兹莫丹时，麦多兰·铜须率领他的氏族进行了一场决定性的战役，粉碎了黑铁军队，巩固了铜须氏族在铁炉堡的统治地位。"},{t="联盟的支柱",b="人类王国在近两千年前首次接触到铜须矮人，双方通过在金属工艺、贸易和对战斗的热情方面的共同造诣建立了相互尊重。当兽人部落在第二次战争中横扫大陆时，国王麦格尼·铜须将他的王国带入了洛丹伦联盟。尽管在地下堡垒中抵御了残酷的围攻，但铜须氏族的工程师、枪手和爆破手提供了关键的火力与武器，帮助扭转了战争的局势。"},{t="高台之上的悲伤",b="如今，麦格尼国王在Great Forge的High Seat执政，但他的统治笼罩在失去亲人的阴影之下。他的弟弟穆拉丁·铜须作为联盟特使前往洛丹伦，却与阿尔萨斯·米奈希尔王子一同消失在诺森德的冰天雪地中，人们推测他在王子拿到那把被诅咒的剑“霜之哀伤”时已经遇难。雪上加霜的是，麦格尼的女儿，莫伊拉公主也失踪了，这使得氏族的继承问题变得扑朔迷离，而氏族成员仍在探索远古泰坦遗迹，试图寻找他们起源的线索。"}},faq={{q="谁统治着铜须氏族？",a="麦格尼·铜须国王坐在Great Forge内的High Seat上。作为第二次战争的亲历者和锻造大师，他领导着他的氏族以及卡兹莫丹的盟友矮人。",al={"铜须领袖","谁是铁炉堡国王","现任铜须国王"}},{q="铜须氏族是如何夺取铁炉堡控制权的？",a="大约230年前，至高王莫迪姆斯·安威玛尔去世后，三大部族之间爆发了内战。身为铁炉堡中央常备军的指挥官，塞恩麦多兰·铜须将蛮锤和黑铁部族驱逐出了山脉，随后又击溃了索瑞森入侵的黑铁大军。",al={"三锤之战","矮人内战","铜须为何统治"}},{q="铜须氏族与其他矮人氏族有什么区别？",a="铜须氏族居住在铁炉堡，代表了传统的山脉矮人，他们擅长重甲、火器和地下建筑。相比之下，蛮锤部族居住在悬崖和天空之中，以狮鹫骑士闻名；而敌对的黑铁部族则精通黑魔法和火法，居住在黑石山之下。",al={"矮人部族区别","铁炉堡与蛮锤","矮人类型"}},{q="穆拉丁·铜须发生了什么事？",a="穆拉丁·铜须作为联盟特使和探险家前往了诺森德。他引导阿尔萨斯·米奈希尔王子寻找符文剑“霜之哀伤”，当这把被诅咒的武器从基座上被拔出时，据报他已经遇难。",al={"穆拉丁在哪里","穆拉丁还活着吗","穆拉丁的命运"}},{q="为什么铜须氏族如此热衷于考古挖掘？",a="铜须氏族的学者们发现了将他们的祖先与远古石造土灵联系起来的遗物。为了探寻种族的起源，该氏族资助了遍布艾泽拉斯的挖掘和探险活动。",al={"为什么矮人要挖掘","矮人考古挖掘","土灵起源"}},{q="铜须王室的权力中心在哪里？",a="皇室王座，即High Seat，位于铁炉堡中心，沿Great Forge而建。麦格尼国王在此处理国家事务，周围有议员和皇家卫队守卫。",al={"王座厅在哪里","high seat位置","铜须王座"}}},fx={["177e0e99"]={q="铜须氏族的盟友有哪些？",a="铜须氏族是大联盟坚定的创始支柱。他们与人类的关系最为密切，这段情谊可以追溯到约十八个世纪以前：当时，来自阿拉索的人类探险者首次南下进入卡兹莫丹，并发现了铁炉堡。两个种族因锻造、工程和讲述故事的共同爱好结成了持久的伙伴关系。他们还与附近诺莫瑞根的侏儒关系密切；尽管过去曾发生内战，他们也早已与鹰巢山的蛮锤族亲戚重建了友好关系。",al={"铜须氏族的盟友","铜须氏族与谁结盟","铁炉堡的盟友"}}},fp="16,288,28.587.0,24.508.0,22.541.1,31.177.0,54.306.0,67.316.0,37.228.0,59.200.0,54.185.0"}
P.entries["topic:brotherhood-of-northshire"] = {n="北郡兄弟会",s="北郡兄弟会是一个致力于圣光教会的人类神圣牧师教团，其基地位于艾尔文森林的北郡修道院。该教团最初被称为北郡牧师，在第一次战争中遭受了毁灭性的打击，之后在大主教阿隆索斯·法奥的领导下进行了重组。如今，北郡兄弟会既是一个精神避难所，也是联盟新手保卫者们的主要训练基地。",h="北郡兄弟会是一个致力于圣光教会的人类神圣牧师教团，其基地位于艾尔文森林的北郡修道院。该教团最初被称为北郡牧师，在第一次战争中遭受了毁灭性的打击，之后在大主教阿隆索斯·法奥的领导下进行了重组。如今，北郡兄弟会既是一个精神避...",kw={"阿隆索斯·法奥","修士帕克斯顿","北郡兄弟会","圣光教会","北郡牧师","艾尔文森林","北郡修道院","女牧师安妮塔"},ang={["class:Paladin"]="在第一次战争期间，北郡未着护甲的牧师所遭受的悲惨屠杀，直接促使大主教法奥创建了白银之手骑士团。",["class:Priest"]="北郡修道院是暴风城牧师传统的摇篮，早在第一次战争前，这里就培育出了治愈、忏悔和圣光的古老纪律。",["race:Human"]="对于几代暴风城公民而言，兄弟会曾在苦难中提供过精神慰藉，而其修道院更是王国最伟大冠军们卑微的起点。"},sec={{t="第一次战争时期的牧师",b="几个世纪前，虔诚的传教士们从洛丹伦向南前往暴风城王国，建立了北郡修道院，通过圣光来侍奉人民并安抚王国。他们最初被称为北郡圣职教团，他们的慈悲心肠是传奇般的——在过去的边境战争中，他们甚至会照料受伤的豺狼人和丛林巨魔。当兽人部落穿过黑暗之门时，牧师们勇敢地挺进前线，在没有盔甲或武器保护的情况下救治倒下的士兵。因为他们的治疗维系了暴风城军队，兽人对他们进行了无情的攻击。教团被屠杀殆尽，修道院被洗劫并焚毁，幸存的牧师们被迫跟随安度因·洛萨爵士向北越过无尽之海逃往南海镇。"},{t="圣骑士的火种",b="北郡牧师的惨遭屠杀震惊了各个人类王国。大主教阿隆索斯·法奥意识到，仅凭信仰而没有盔甲和军事纪律是无法抵挡战斧的，于是他决定创造出一批既拥有圣光的神圣力量，又具备骑士军事素养的战士。法奥召集了幸存的牧师和虔诚的骑士，组建了白银之手骑士团，从而诞生了人类的第一批圣骑士。就这样，北郡牺牲的治疗者们成为了在第二次战争中击溃部落的神圣战士们的基石。"},{t="重建与当下的职责",b="在收复暴风城并摧毁黑暗之门后，大主教法奥监督了北郡修道院的重建，并将该教团重组为北郡兄弟会。现在是黑暗之门后25年，北郡修道院矗立在那里，成为一个安静而重要的中心，新兵们聚集在这里开始为王国效力。在女牧师安妮塔、修士萨穆尔和修士帕克斯顿等人的带领下，北郡兄弟会致力于维护山谷的精神健康，在图书馆保存古代文献，并训练下一代保卫者去对抗遍布艾尔文森林的强盗、狼群和不断聚集的阴影。"}},faq={{q="什么是北郡兄弟会？",a="他们是圣光教会内部的一个修道教团，基地位于艾尔文森林的北郡修道院。他们曾被称为北郡牧师，负责提供精神引导、医治伤员，并训练刚刚开启冒险旅程的联盟新人们。",al={"北郡兄弟会是什么","北郡兄弟会的历史","北郡牧师"}},{q="在第一次战争中，最初的牧师们遭遇了什么？",a="牧师们作为没有护甲的战场治疗者投入了第一次战争。兽人意识到，只要有圣光的加持，人类士兵就不易被击败，因此他们将残杀牧师列为首要目标。修道院被攻陷并摧毁，只有少数幸存者越过无尽之海逃往了洛丹伦。",al={"第一次战争时期的北郡牧师","修道院发生了什么","北郡修道院的毁灭"}},{q="北郡牧师是如何启发圣骑士的？",a="大主教阿隆索斯·法奥目睹了没有护甲的牧师在部落的攻势下是如何轻易被杀害的，他意识到联盟需要能够在残酷战斗中生存下来的神圣战士。他将牧师的精神奉献与骑士的军事素养相结合，锻造出了白银之手骑士团。",al={"圣骑士的起源","白银之手骑士团的起源","阿隆索斯·法奥与圣骑士"}},{q="如今谁在北郡修道院领导或训练人员？",a="修道院是北郡兄弟会几位重要成员的所在地，包括负责物资补给并为图书馆抄写文献的修士帕克斯顿、指导渴望成为牧师之人的女牧师安妮塔，以及引导圣骑士新手的修士萨穆尔。",al={"谁在北郡修道院","北郡修道院的训练师","修士帕克斯顿"}},{q="第一次战争期间前往死亡矿井的远征是为了什么？",a="一位名叫图洛克的食人魔酋长从北郡偷走了神圣的《神圣之书》。安度因·洛萨爵士带领一支远征队进入了西部荒野的死亡矿井去取回它，但却被困在了里面，直到暴风城军队救出了他并确保了这本书被送回修道院。",al={"死亡矿井的神圣之书","安度因·洛萨与死亡矿井","图洛克与死亡矿井"}},{q="他们与迪菲亚潜行者有联系吗？",a="没有，他们完全对立。虽然两者名字中都有“兄弟会”一词，但北郡兄弟会是一个忠于暴风城的神圣宗教团体，而迪菲亚潜行者是一个祸害乡里的不法之徒和强盗组成的犯罪团伙。",al={"北郡兄弟会与迪菲亚潜行者","他们是迪菲亚潜行者吗"}}},fx={["5eaf3832"]={q="为什么北郡兄弟会驻扎在北郡山谷？",a="数百年前，圣光教会的牧师从洛丹伦南下，在暴风城建立了北郡修道院，作为他们的精神家园。第一次战争期间，兽人部落夷平了最初的修道院；战争结束后，大主教阿隆索斯·法奥主持重建了修道院。这片山谷至今仍是他们的祖传圣地，如今也是训练和招募之地，为王国培养新的守护者。",al={"他们为什么在北郡","为什么是北郡山谷","北郡兄弟会的位置"}},["24abd8af"]={q="北郡兄弟会与谁结盟？",a="北郡兄弟会是圣光教会的一个组织，直接服务于暴风城王国和大联盟。历史上，在豺狼人战争和古拉巴什战争等重大冲突期间，兄弟会的牧师曾照料暴风城的军队；如今，重建后的兄弟会直接招募并训练新晋勇士，守护王国。",al={"北郡兄弟会的盟友","北郡兄弟会为谁效力","北郡兄弟会的效忠对象"}}},fp="25,437,28.769.0,25.601.0,27.628.0,38.260.0,59.298.0,52.294.0,53.246.0,62.254.0,45.251.0"}
P.entries["topic:burning-blade-clan"] = {n="火刃氏族",s="火刃氏族曾是一个古老的兽人氏族，以致命的剑圣而闻名，在早期的战争中因陷入混乱的狂乱而丧失心智。如今，火刃氏族已演变成一个阴险的恶魔崇拜邪教。在暗影议会的指使下，他们渗透进杜隆塔尔和贫瘠之地，其教徒威胁着该地区脆弱的和平。与此同时，少数荣誉剑圣已经摒弃了恶魔的腐化，转而在新部落中为萨尔酋长效力。",h="火刃氏族曾是一个古老的兽人氏族，以致命的剑圣而闻名，在早期的战争中因陷入混乱的狂乱而丧失心智。如今，火刃氏族已演变成一个阴险的恶魔崇拜邪教。在暗影议会的指使下，他们渗透进杜隆塔尔和贫瘠之地，其教徒威胁着该地区脆弱的和平。...",kw={"剑圣","火刃氏族","cleft of shadow","杜隆塔尔","灼刃氏族","暗影议会","骷髅石","佐莫多尔"},ang={["class:Warlock"]="该邪教是鲁莽且被恶魔奴役的典型，这也迫使像在大断崖师从尼鲁·火刃的那些部落术士被迫转入地下，并受到极度的怀疑。",["faction:Horde"]="火刃氏族代表了部落腐化的恶魔过去所留下的挥之不去的阴影，从内部直接威胁着杜隆塔尔和贫瘠之地。",["race:Orc"]="该氏族的堕落是血之诅咒带来的沉痛提醒，这与那些在萨尔麾下寻求救赎、坚守荣誉的剑圣形成了鲜明的对比。"},sec={{t="从氏族到元素之怒",b="火刃氏族起源于德拉诺，与战歌氏族等其他氏族同源，长期以来一直因其剑圣的致命传承而备受尊重。然而，当他们在第一次战争期间饮下玛诺洛斯之血，并穿过黑暗之门踏入艾泽拉斯时，该氏族的精神便开始分崩离析。到了第二次战争时，他们几乎不再是一个有组织的社会，而表现得如同一种狂暴的自然力量。他们游牧且疯狂，在战斗中全然不顾生死，需要食人魔压制，直到被释放出来。最终，他们在黑暗之门附近遭到了联盟的重创和击溃。"},{t="杜隆塔尔的威胁",b="现代的邪教在整个卡利姆多各地建立秘密集会所，从兽人和暗矛巨魔初抵试炼谷之日起，就一直困扰着他们。火刃术士占据了雷霆山，并在奥格瑞玛东门附近的骷髅石内驻扎了一个主要据点。他们的邪教徒围绕着恶魔之种等黑暗圣物聚集，为恶魔仪式收割灵魂，这使他们成为新部落在杜隆塔尔和贫瘠之地立足的主要内部威胁。"},{t="大断崖的叛徒",b="在萨尔致力于建立新部落的同时，该邪教的主谋就潜伏在他的眼皮底下。尼鲁·火刃，这位表面上居住在大断崖的部落术士，实际上是暗影议会的特工，秘密领导着火刃氏族。尼鲁利用爪牙，包括怒焰裂谷中那些炮灰般的灼刃氏族成员，来维持他作为一名协助酋长的善良研究者的伪装。尼鲁并不知道，萨尔早已识破了他那背叛的效忠，并对他严密监视。"},{t="分裂的遗产",b="第二次战争结束后，火刃氏族的幸存残部发生了剧烈的分裂。一支纪律严明的剑圣小队立下庄严誓言，要将族人从恶魔的奴役中解放出来，并将他们的刀刃直接献给萨尔酋长，作为他的私人荣誉卫队。然而，该氏族中规模庞大得多的一部分却完全落入了燃烧军团和暗影议会的掌控，演变成一个潜伏在整个卡利姆多的术士、邪能教徒和阴谋家的秘密邪教。"}},faq={{q="火刃氏族是什么？",a="火刃氏族最初是一个来自德拉诺的兽人氏族，以精英剑圣而闻名，在第一次和第二次战争期间因嗜血而沉沦。今天，这个名字主要指代一个代表暗影议会在卡利姆多各地活动的恶魔崇拜邪教，尽管仍有少数改邪归正的剑圣为萨尔的部落效力。",al={"火刃氏族背景","火刃氏族是谁","火刃氏族由来"}},{q="到底是谁在领导火刃氏族？",a="该邪教听命于暗影议会，其在杜隆塔尔和贫瘠之地的集会所由术士和恶魔召唤师管理，他们隐瞒了真正的幕后主使。流言称，指挥链的源头距离奥格瑞玛本身竟近得令人不安。",al={"火刃氏族领袖","火刃氏族的领导者是谁"}},{q="他们为什么要攻击试炼谷的新生兽人？",a="火刃氏族在试炼谷的北部洞穴中建立了一个集会所，意图干扰正在进行试炼仪式年轻兽人和巨魔。他们利用卑劣的爪牙和黑暗徽记，在部落土地的核心地带播种邪能腐化。",al={"试炼谷的火刃氏族","为什么邪教徒在试炼谷"}},{q="火刃氏族和灼刃氏族有什么区别？",a="灼刃氏族是一个以奥格瑞玛地下深处的怒焰裂谷为基地的派系。它是一个较小的分支，而火刃氏族则是活跃于杜隆塔尔和贫瘠之地的更广泛的邪教。调查怒焰裂谷就能揭开究竟是谁在指挥该派系。",al={"灼刃氏族与火刃氏族","火刃氏族和灼刃氏族的区别"}},{q="所有火刃氏族成员都是崇拜恶魔的邪教徒吗？",a="不。虽然邪教分子占了大多数，但在第三次战争之前，原始氏族中一些骄傲的剑圣脱离了出去。他们发誓要让族人从恶魔奴役中得到救赎，如今作为萨尔的私人荣誉卫队，忠诚地为新部落而战。",al={"火刃氏族都是坏人吗","火刃氏族的剑圣是好人吗"}}},fx={["59650569"]={q="为什么火刃氏族敌视旅人？",a="火刃氏族听命于燃烧军团和暗影议会的恶魔意志。自从氏族在早期战争中被恶魔的嗜血欲望吞噬后，他们便抛弃了真正的效忠对象与荣誉。如今，他们已重组为隐秘的末日邪教，将外来者、忠于部落的成员和好奇的旅人都视作对其秘密集会的直接威胁，或是恶魔血祭的祭品。",al={"火刃氏族为什么攻击","火刃氏族敌对","火刃氏族为什么战斗"}},d02d80de={q="火刃氏族与谁结盟？",a="这个邪教是邪恶的暗影议会的直属爪牙，在卡利姆多各地执行其黑暗计划。他们经常与其他崇拜恶魔的盟友和分支势力合作，例如潜伏在奥格瑞玛地下的炽炎之刃，以及东部王国的阿古斯之潮。最重要的是，他们宣誓效忠燃烧军团，召唤恶魔并搜集堕落神器，以加快主人的计划。",al={"火刃氏族的盟友","火刃氏族为谁效力","火刃氏族和暗影议会"}},["7b15f473"]={q="火刃氏族来自哪里？",a="火刃氏族最初是德拉诺一个古老的兽人氏族，以可怕的剑圣闻名。他们加入旧部落，并在第一次战争期间穿越黑暗之门来到艾泽拉斯。恶魔腐化侵蚀了他们的心智，使他们在第二次战争期间变得鲁莽而疯狂，最终彻底分崩离析。后来，一些恪守荣誉的剑圣宣誓效忠萨尔的新部落；剩余的族人则转变为如今威胁卡利姆多的黑暗恶魔邪教。",al={"火刃氏族的起源","火刃氏族传说","火刃氏族的历史"}}},fp="18,452,27.647.0,21.475.0,24.500.1,14.507.1,31.336.1,37.241.1,56.249.0,67.245.1,56.253.0"}
P.entries["topic:burning-legion"] = {n="燃烧军团",s="燃烧军团是由堕落泰坦萨格拉斯领导的一支无穷无尽、带来末日的恶魔大军，致力于从创造物中抹除一切生命。在一万年前粉碎了古老的卡利姆多之后，这些恶魔依然是艾泽拉斯最无情的宿敌，一手策划了兽人的堕落和第三次战争的恐怖。",h="燃烧军团是由堕落泰坦萨格拉斯领导的一支无穷无尽、带来末日的恶魔大军，致力于从创造物中抹除一切生命。在一万年前粉碎了古老的卡利姆多之后，这些恶魔依然是艾泽拉斯最无情的宿敌，一手策划了兽人的堕落和第三次战争的恐怖。",kw={"阿克蒙德","燃烧军团","恶魔","艾瑞达","邪能","海加尔","基尔加丹","马诺洛斯","萨格拉斯","天崩地裂","扭曲虚空","永恒之井"},ang={["class:Paladin"]="圣骑士将燃烧军团视为圣光的对立面，他们致力于通过誓言和正义的力量，在任何恶魔滋生的地方将其净化。",["class:Warlock"]="术士行走在刀锋之上，尽管面临不断的猜疑和时刻存在的堕落威胁，他们仍将原始的邪能魔法和顺从的军团恶魔折服于自己的凡人意志之下。",["race:NightElf"]="暗夜精灵承受着燃烧军团入侵带来的最深创伤；他们的古老帝国在天崩地裂中破碎，而最近在海加尔山牺牲世界之树，让他们失去了不朽。",["race:Orc"]="兽人与燃烧军团有着一段痛苦的过往，他们曾因马诺洛斯的恶魔血契而被奴役，直到格罗玛什·地狱咆哮牺牲自己彻底打破了诅咒。"},sec={{t="军团的起源",b="很久以前，萨格拉斯曾是泰坦的捍卫者，负责追捕并囚禁那些祸害宇宙的恶魔。在与邪恶斗争了无数个岁月后，他感到幻灭，认为创造本身存在致命的缺陷，必须在烈焰中重塑。为了实施他的远征，他释放了曾经囚禁的恶魔，通过邪能魔法将他们纳入麾下。他利用堕落艾瑞达的智慧增强了恶魔的混乱力量，提升阿克蒙德和基尔加丹作为他的首席副官，并锻造了一台不可阻挡的宇宙毁灭引擎。"},{t="上古之战",b="一万年前，上层精灵鲁莽的魔法将燃烧军团的目光引向了艾泽拉斯。萨格拉斯通过永恒之井低语，用将世界重塑为天堂的诺言诱惑了艾萨拉女王和她的顾问萨维斯。然而，传送门开启后释放了诸如马诺洛斯和阿克蒙德这样的指挥官，以及成群的末日守卫、邪犬和燃烧的地狱火。随后的战争将卡利姆多的文明摧毁殆尽，直到暗夜精灵、巨龙军团和半神组成的联军关闭了传送门。灾难性的内爆在天崩地裂中撕裂了超级大陆，将残破的土地抛向了广阔的新海洋。"},{t="笼罩艾泽拉斯的阴影",b="尽管被驱逐回了扭曲虚空，燃烧军团从未放弃艾泽拉斯。基尔加丹认为直接入侵只会导致失败，于是从远处策划了代行灾难。这位欺诈者通过恶魔血契束缚了德拉诺的兽人，派遣部落冲过黑暗之门以削弱凡人的防御。当计划失败后，军团锻造了巫妖王，并在洛丹伦释放了亡灵天灾军团，为阿克蒙德在第三次战争中的回归铺平了道路。即使在阿克蒙德于海加尔山战败后，燃烧军团的残党依然盘踞在费伍德森林、诅咒之地以及世界各地的隐秘教派中。"}},faq={{q="什么是燃烧军团？",a="燃烧军团是由堕落泰坦萨格拉斯锻造的一支由恶魔、堕落种族和毁灭性恐怖生物组成的无穷大军。其唯一目标就是燃烧远征：从宇宙中抹除一切生命和有序的存在。",al={"谁是燃烧军团","什么是燃烧军团","军团恶魔","什么是恶魔"}},{q="谁领导燃烧军团？",a="军团的终极主宰是堕落泰坦萨格拉斯。在他之下是艾瑞达恶魔领主，其中最著名的是污染者阿克蒙德，他曾在海加尔山战死前带头进行军事突袭；还有欺诈者基尔加丹，他在世界各地策划阴险的阴谋。",al={"谁统治军团","军团领袖","谁是恶魔之王","阿克蒙德首领"}},{q="为什么军团想要摧毁艾泽拉斯？",a="艾泽拉斯一再对抗燃烧军团，是已知唯一一个成功击退其进攻的世界。",al={"恶魔为何攻击","军团动机","为何入侵艾泽拉斯","萨格拉斯的目标"}},{q="恶魔最初是如何来到艾泽拉斯的？",a="一万年前，艾萨拉女王和她的上层精灵引导了永恒之井的巨大能量，无意中吸引了萨格拉斯。在上层精灵受到无限力量的诱惑后，他们在宫殿下方开启了一个巨大的传送门，使军团得以入侵卡利姆多。",al={"第一次恶魔入侵","军团如何来到这里","永恒之井传送门","艾萨拉女王与恶魔"}},{q="第三次战争期间军团发生了什么？",a="使用麦迪文之书被召唤回艾泽拉斯后，阿克蒙德横扫洛丹伦，并向西航行以吞噬世界之树诺达希尔。在海加尔山，凡人种族为玛法里奥·怒风争取了时间，让他得以召唤先祖之灵，引爆了世界之树的力量并彻底消灭了阿克蒙德。",al={"第三次战争中的恶魔","海加尔山之战","军团在第三次战争中失败了吗","阿克蒙德发生了什么"}},{q="现在恶魔仍然是威胁吗？",a="是的。虽然他们的主力军在阿克蒙德战败后分崩离析，但危险的残党依然盘踞在艾泽拉斯各地。恐惧魔王、地狱火和徘徊的恶魔占据了费伍德森林和诅咒之地等堕落区域，而暗影议会等凡人教派则在暗中活动。",al={"恶魔还在吗","军团残党","经典旧世的恶魔","恶魔现在在哪里"}}},fx={["5561206b"]={q="为什么燃烧军团敌视所有人？",a="燃烧军团的终极目标，就是彻底毁灭宇宙中所有凡人生灵与造物。在堕落泰坦萨格拉斯的指挥下，恶魔所求的不是征服、共存或投降；它们将凡人的世界视为有缺陷的残骸，必须用魔火净化。它们在艾泽拉斯遇到的任何旅人或生灵，都只是魔法的燃料或待消灭的猎物。",al={"燃烧军团为什么敌对","燃烧军团为什么攻击","燃烧军团敌对的原因"}},c3b2191d={q="谁与燃烧军团并肩作战或为其效力？",a="军团依靠无穷无尽的恶魔种族，包括巨大的深渊领主、狡诈的恐惧魔王、贪婪的恶魔猎犬和高耸的地狱火。除了纯粹的恶魔，他们还会腐化凡人种族，将其当作棋子和先锋。过去，他们曾诱使艾萨拉女王的上层精灵巫师倒向自己，通过恶魔之血腐化德拉诺的兽人，并制造天灾军团，在入侵前削弱凡人的抵抗。",al={"燃烧军团的盟友","谁为军团效力","谁效忠燃烧军团"}},["9252264e"]={q="为什么艾泽拉斯各地仍有恶魔残党？",a="阿克蒙德在海加尔山之战中落败后，恶魔军团统一的攻势土崩瓦解，幸存的恶魔四散藏匿。如今，残留的恶魔和叛变的恐惧魔王潜伏在凄凉之地、费伍德森林和诅咒之地等荒凉区域。此外，暗影议会的术士等堕落凡人密谋通过隐秘的黑暗传送门召唤新的援军，继续执行军团的计划。",al={"为什么艾泽拉斯仍有恶魔","为什么军团恶魔还在这里","燃烧军团在艾泽拉斯的据点"}}},fp="14,335,19.576.0,23.648.0,20.628.0,27.231.0,29.286.0,44.107.0,43.282.0,49.298.0,36.283.0"}
P.entries["topic:cenarion-circle"] = {n="塞纳里奥议会",s="塞纳里奥议会是一个古老而独立的德鲁伊组织，由玛法里奥·怒风在半神塞纳留斯的指引下创立。他们以月光林地的圣地为基地，致力于维护自然平衡，守护翡翠梦境，并修复艾泽拉斯受损的土地。尽管从历史上看，成员大多是暗夜精灵，但最近他们也接纳了牛头人加入，跨越了阵营的界限来保卫这个生灵世界。",h="塞纳里奥议会是一个古老而独立的德鲁伊组织，由玛法里奥·怒风在半神塞纳留斯的指引下创立。他们以月光林地的圣地为基地，致力于维护自然平衡，守护翡翠梦境，并修复艾泽拉斯受损的土地。尽管从历史上看，成员大多是暗夜精灵，但最近他们...",kw={"塞纳里奥议会","塞纳里奥要塞","塞纳留斯","德鲁伊","翡翠梦境","范达尔·鹿盔","哈缪尔·符文图腾","玛法里奥","月光林地","永夜港"},ang={["class:Druid"]="塞纳里奥议会是你们的组织和精神权威。无论你的教导源自达纳苏斯还是莫高雷的平原，所有的德鲁伊力量、试炼和召唤都源于议会在月光林地的仪式。",["profession:Herbalism"]="塞纳里奥议会的德鲁伊对艾泽拉斯的植物生命以及培育珍稀魔法植被的微妙生态系统有着无与伦比的理解。",["race:NightElf"]="在一万年的时间里，你们族群中的男性主要是在兽穴中沉睡，为议会服务，而哨兵部队则守卫着你们的边界；议会与荒野的深厚羁绊塑造了卡多雷文化的方方面面。",["race:Tauren"]="通过哈缪尔·符文图腾与玛法里奥·怒风的友谊，你们族人重新找回了与大地母亲直接相连的古老传统，从而在议会中赢得了一席之地。"},sec={{t="议会的起源",b="塞纳里奥议会的根源可以追溯到数千年前，源于德鲁伊的守护者塞纳留斯的教导，他指导了第一位凡人德鲁伊玛法里奥·怒风。大分裂后，玛法里奥将那些希望学习自然之道的人团结在了一起。该组织在月光林地的神圣山谷中安家落户，从那时起，议会便一直守护着艾泽拉斯的野性之地。"},{t="神圣的中立",b="虽然塞纳里奥议会与暗夜精灵的历史有着深刻的渊源，但它独立于达纳苏斯和The Sisterhood of Elune存在。他们的核心依然是迷人的月光林地，以宁静的永夜港为中心。在这里，武器必须收起，凡人的战争也无法触及。这种古老的中立性在第三次战争后得到了再次证明，当时玛法里奥与牛头人长者哈缪尔·符文图腾结为了挚友。议会认识到牛头人对大地母亲的深刻精神崇拜，正式接纳了哈缪尔，并在数千年后重新将德鲁伊教义传回了他的种族。"},{t="紧张局势与缺席的大德鲁伊",b="海加尔山之战后，玛法里奥陷入了某种反常且无法破解的昏迷，被困在兽穴深处，导致德鲁伊们群龙无首。在他缺席期间，大德鲁伊范达尔·鹿盔实际接管了议会的领导权。范达尔利用玛法里奥的沉寂，为培育泰达希尔争取支持，希望以此恢复卡多雷失去的不朽。然而，龙王们拒绝祝福这棵新树，而且它的枝叶中开始滋生出诡异的腐化。如今，随着范达尔以铁腕统治，议会内部的意见分歧日益加剧，而古老的守护者们已能感觉到某种正在从希利苏斯和翡翠梦境蔓延而来的黑暗。"}},faq={{q="什么是塞纳里奥议会？",a="塞纳里奥议会是一个古老的德鲁伊社会，致力于维护自然平衡、研究野性之道并照料翡翠梦境。该组织以半神塞纳留斯的名字命名，由玛法里奥·怒风创立，以月光林地的圣地为基地，管理着艾泽拉斯各地的德鲁伊教义。",al={"塞纳里奥议会背景","塞纳里奥议会是谁","什么是塞纳里奥议会"}},{q="塞纳里奥议会的总部在哪里？",a="议会总部位于月光照耀的隐秘避难所——月光林地，具体地点围绕着永夜港村庄和月神湖湖畔。他们在卡利姆多的各地都设有较小的哨所和兽穴，包括在希利苏斯的荒漠中设立的一处重要据点：塞纳里奥要塞。",al={"塞纳里奥议会基地","塞纳里奥德鲁伊基地在哪里","永夜港塞纳里奥"}},{q="为什么牛头人会加入塞纳里奥议会？",a="在第三次战争期间，牛头人长者哈缪尔·符文图腾曾在海加尔山与玛法里奥·怒风并肩作战。两人建立了相互尊重的友谊，玛法里奥将深奥的德鲁伊秘术传授给了哈缪尔。哈缪尔成为了几千年来第一位牛头人德鲁伊，并被热情地接纳进入议会，使牛头人和暗夜精灵德鲁伊建立了难得的伙伴关系。",al={"为什么有牛头人德鲁伊","哈缪尔塞纳里奥议会","牛头人暗夜精灵德鲁伊"}},{q="谁领导着塞纳里奥议会？",a="从历史上看，玛法里奥·怒风曾与资深大德鲁伊共同领导该组织。由于玛法里奥目前被困在一种无法解释的兽穴昏迷中，领导权实际上已交由达纳苏斯的范达尔·鹿盔大德鲁伊掌控，不过哈缪尔·符文图腾等受人尊敬的长者和月光林地的守护者们依然在各自的派系中发挥着引导作用。",al={"塞纳里奥议会领袖","谁是大德鲁伊","大德鲁伊领袖"}},{q="塞纳里奥议会是联盟的一部分吗？",a="不是。塞纳里奥议会完全中立。虽然其成员一度仅限于暗夜精灵，但他们首要的誓言是效忠自然，而非凡人的王权。在月光林地和其他塞纳里奥营地，联盟和部落的德鲁伊可以并肩行走，而不会发生冲突。",al={"塞纳里奥议会是联盟吗","塞纳里奥议会阵营","塞纳里奥德鲁伊是中立的吗"}},{q="甲虫之墙在希利苏斯发生了什么？",a="一千年前，在流沙之战中，范达尔·鹿盔大德鲁伊率领暗夜精灵和议会对抗虫群其拉虫人，并得到了巨龙军团的援助。最终，青铜龙阿纳克洛斯及其盟友筑起了甲虫之墙将虫巢封印，而议会则建立了塞纳里奥要塞，负责守护这道封印。",al={"塞纳里奥要塞希利苏斯","流沙之战","德鲁伊甲虫之墙"}}},fx={["93dd49b8"]={q="塞纳里奥议会为什么叫这个名字？",a="这个组织以森林之主、半神塞纳留斯的名字命名，并受到他的祝福。塞纳留斯是荒野的守护者，曾教导玛法里奥·怒风——艾泽拉斯第一位凡人德鲁伊。玛法里奥和其他修行者聚集起来，整理传承并守护自然平衡时，便以这位半神的名字为组织命名，以此尊崇他们神圣的导师。",al={"塞纳里奥议会名称的由来","为什么叫塞纳里奥","塞纳里奥议会以谁命名"}},["975f0135"]={q="塞纳里奥议会来自哪里？",a="大分裂之后，玛法里奥·怒风在月光林地创建了塞纳里奥议会，并召集早期的暗夜精灵德鲁伊，制定他们的准则和传统。在漫长守望的数千年间，议会与绿龙军团一同漫步于翡翠梦境，维持平衡并治愈艾泽拉斯各地遭恶魔侵蚀的伤痕。",al={"塞纳里奥议会的历史","塞纳里奥议会的起源","塞纳里奥议会如何建立"}}},fp="15,457,21.400.0,19.613.0,32.688.1,28.304.0,49.291.0,38.352.0,30.321.0,44.257.0,45.358.0"}
P.entries["topic:cenarius"] = {n="塞纳留斯",s="塞纳留斯，森林之王，是月神艾露恩和玛洛恩生下的古老半神，他将德鲁伊教的秘密传授给了暗夜精灵。几千年来，他一直担任凡人德鲁伊的伟大导师和荒野的守护者，直到在第三次战争中战死沙场。",h="塞纳留斯，森林之王，是月神艾露恩和玛洛恩生下的古老半神，他将德鲁伊教的秘密传授给了暗夜精灵。几千年来，他一直担任凡人德鲁伊的伟大导师和荒野的守护者，直到在第三次战争中战死沙场。",kw={"灰谷","塞纳里奥","塞纳留斯","德鲁伊","艾露恩","玛法里奥","玛洛恩","remulos","伊瑟拉"},ang={["class:Druid"]="每一位德鲁伊都可以将他们的修行之道直接追溯到塞纳留斯，这位永恒的守护者对玛法里奥的教导确立了德鲁伊的修习之道。",["race:NightElf"]="卡多雷视塞纳留斯为神圣的向导与盟友，他死于战歌兽人之手的惨剧至今仍让人无法原谅。",["race:Orc"]="格罗玛什·地狱咆哮杀害塞纳留斯一事，成为了一项严酷的警示，提醒着人们血之诅咒以及臣服于恶魔所带来的毁灭性代价。",["race:Tauren"]="牛头人德鲁伊尊崇塞纳留斯的教诲，与塞纳里奥议会的暗夜精灵一起走在他的道路上。"},sec={{t="天地之子",b="塞纳留斯是月亮女神艾露恩和伟大的白鹿半神玛洛恩的后代。由于塞纳留斯与凡世有着宿命的联系，艾露恩将他托付给了玛洛恩照料，而梦境之王伊瑟拉则将他收为养子，引导他踏入翡翠梦境那无穷无尽的道路。塞纳留斯拥有掌控生灵草木与大地的力量，他不仅繁衍了丛林守护者和树妖一族，更使自己的血脉与卡利姆多的荒野永远联系在了一起。"},{t="第一位德鲁伊",b="几千年前，三位年轻人——玛法里奥·怒风、他的孪生兄弟伊利丹，以及泰兰德·语风——一同去寻找这位传说中的半神。塞纳留斯发现了玛法里奥拥有一颗非凡的心，并将他培养成了第一位凡人德鲁伊。当艾萨拉女王和她的上层精灵在上古之战期间释放燃烧军团时，塞纳留斯集结了卡利姆多的荒野半神们，与凡人守卫者并肩作战。"},{t="灰谷的陨落",b="在大分裂发生后的那一万年里，塞纳留斯一直在守护着卡利姆多，并与玛法里奥共同培育着塞纳里奥议会。这份警惕的守护在第三次战争期间划上了句号，当时战歌氏族开始在灰谷采伐林木。塞纳留斯对神圣林地的破坏感到愤怒，于是他将入侵者击退，直到格罗玛什·地狱咆哮和他的战士们饮下了玛诺洛斯的恶魔之血。被恶魔之怒灌注的腐化兽人们压倒了这位半神并将他击杀，在自然守卫者的心中投下了黑暗的阴影。"}},faq={{q="塞纳留斯是谁？",a="塞纳留斯是一位古老的自然半神，德鲁伊的守护圣徒，也是艾泽拉斯荒野的守护者。他由月亮女神艾露恩和半神玛洛恩所生，由龙王伊瑟拉抚养长大，成为了荒野之地的最高领袖。",al={"塞纳留斯是谁","塞纳留斯背景故事","塞纳留斯背景"}},{q="塞纳留斯的后代有哪些？",a="他的儿子们是丛林守护者，例如Remulos和Ordanus，而他的女儿们则是林间的树妖。半人马种族的血统可以追溯到他的儿子Zaetar，因此塞纳留斯也是他们的祖父。",al={"塞纳留斯的后代","丛林守护者之父","塞纳留斯的女儿"}},{q="玛法里奥是如何从塞纳留斯那里学会德鲁伊之道的？",a="在上古之战前，玛法里奥与伊利丹和泰兰德一起寻找这位神话中的半神。塞纳留斯认可了玛法里奥那难得的奉献精神与平衡感，将自然的圣神之道传授给了他，使他成为了第一位凡人德鲁伊。",al={"玛法里奥第一位德鲁伊","玛法里奥如何学习德鲁伊之道"}},{q="塞纳留斯在第三次战争中遭遇了什么？",a="在第三次战争期间，兽人的战歌氏族在灰谷采伐林木，激怒了塞纳留斯。为了击败这位半神的力量，酋长格罗玛什·地狱咆哮绝望中饮下了被玛诺洛斯之血污染的池水，获得了恶魔般的力量，最终杀死了塞纳留斯。",al={"塞纳留斯如何死亡","谁杀死了塞纳留斯","塞纳留斯之死"}},{q="塞纳留斯与牛头人有什么联系？",a="牛头人德鲁伊遵循着塞纳留斯最初传授给玛法里奥·怒风的道路，通过哈缪尔·符文图腾在塞纳里奥议会中的地位，牛头人现在正与暗夜精灵一起学习他的教诲。",al={"牛头人与塞纳留斯","塞纳留斯教导过牛头人吗"}},{q="什么是塞纳里奥议会？",a="塞纳里奥议会是一个致力于维护自然平衡、研究翡翠梦境以及守护神圣森林的德鲁伊僧侣教团。它是由塞纳留斯的弟子玛法里奥·怒风为纪念塞纳留斯而创立的。",al={"什么是塞纳里奥议会","谁创立了塞纳里奥议会"}}},fx={["19f1e731"]={q="塞纳留斯来自哪里？",a="塞纳留斯是月亮女神艾露恩与白鹿半神玛洛恩结合所生。由于他更属于凡世而非天界，艾露恩便将他的抚养之责交给了玛洛恩和沉睡者伊瑟拉。伊瑟拉在翡翠梦境中抚养塞纳留斯，教导他其中深奥的奥秘。数千年来，这位森林之主漫游于艾泽拉斯的荒野，向古老的族群传授自然之道，并在上古之战等灾难性冲突中与凡人守护者并肩作战。",al={"塞纳留斯的起源","塞纳留斯的历史","塞纳留斯的诞生"}}},fp="8,281,23.470.0,15.400.0,21.537.0,16.261.0,28.206.1,47.246.0,43.271.0,44.193.0,28.227.0"}
P.entries["topic:centaur"] = {n="半人马",s="半人马是一个残暴的、拥有马身体的人形种族，他们的游牧氏族统治着卡利姆多中部干旱的平原。他们诞生于半神塞塔和大地公主瑟莱德丝之间那段悲剧性的结合，在兽人部落新到之前，他们花费了几个世纪的时间将牛头人逼向了灭绝的边缘。",h="半人马是一个残暴的、拥有马身体的人形种族，他们的游牧氏族统治着卡利姆多中部干旱的平原。他们诞生于半神塞塔和大地公主瑟莱德丝之间那段悲剧性的结合，在兽人部落新到之前，他们花费了几个世纪的时间将牛头人逼向了灭绝的边缘。",kw={"贫瘠之地","半人马","凄凉之地","可汗","考格雷","玛拉顿","瑟莱德丝","塞塔"},ang={["class:Druid"]="半人马代表了对自然平衡的悲剧性扭曲，他们通过堕落的塞塔与塞纳留斯拥有共同的血脉，但所到之处却只带来了荒凉与屠杀。",["faction:Horde"]="在贫瘠之地和杜隆塔尔防御半人马的入侵关乎生存，也是为了纪念萨尔与凯恩·血蹄所达成的建盟契约。",["race:Tauren"]="对于你们的人民来说，半人马不仅仅是野兽；他们是那些曾经差点灭绝你们祖先、并驱逐你们在贫瘠之地流浪数个世纪，直到部落带来救赎的远古折磨者。"},sec={{t="被诅咒的血脉",b="半人马的传说将这个种族的起源追溯到凄凉之地地下的玛拉顿洞穴。在那里，半神塞纳留斯的不朽之子塞塔，与元素领主瑟拉塞恩之女瑟莱德丝公主，孕育了第一批半人马。在他们出生后，这些野蛮的后代背叛并杀死了他们的父亲。悲痛欲绝的瑟莱德丝将塞塔的灵魂困在了玛拉顿蜿蜒的洞穴中，但她庇护了她那凶残的孩子们，这些后代迅速在卡利姆多繁衍开来。"},{t="几个世纪的屠杀",b="在诞生之后，半人马从凄凉之地向外扩张，对卡利姆多的本土种族发动了残酷的消耗战。游牧的牛头人遭受的苦难最深：他们被驱逐出了肥沃的祖居地莫高雷，并在贫瘠之地遭到了无情的追杀。半人马战团将牛头人视为猎物，烧毁他们的定居点，并将狩猎他们作为消遣。到了第三次战争时期，几个世纪无休止的追逐已将牛头人逼到了灭绝的边缘，使他们只能绝望地在稀树草原上四处躲避无尽的掠夺者。"},{t="局势的扭转",b="当萨尔大酋长和新抵达的兽人部落在卡利姆多登陆时，一切都改变了。萨尔与凯恩·血蹄达成了契约，将兽人的钢铁意志与牛头人的力量结合在了一起。他们联手击溃了侵略成性的考格雷战团，打破了他们对平原的控制，使牛头人得以安全地建立雷霆崖并收复莫高雷。这一联盟终结了牛头人四处流浪的放逐生涯，并建立起了一种血与荣耀的羁绊，使他们永久地加入了部落。"},{t="破碎的威胁",b="尽管遭受了惨重的失败，半人马仍然是卡利姆多中部的一大威胁。他们的社会分裂为相互征战的氏族——主要是考格雷、吉尔吉斯、玛格拉姆和玛洛迪——每个氏族由一位可汗领导，并因领土和水源问题陷入永无止境的血腥仇杀中。虽然内部的纠纷阻碍了他们联合成一股不可阻挡的部落大军，但充满侵略性的突袭小队仍然不断袭击杜隆塔尔、贫瘠之地、千针石林和莫高雷边境上的贸易商队与定居点。"}},faq={{q="半人马从何而来？",a="他们诞生于塞纳留斯之子塞塔和大地元素公主瑟莱德丝的结合。残暴的第一代半人马杀死了他们的父亲，随后瑟莱德丝将他的灵魂囚禁在神圣的玛拉顿洞穴中。",al={"半人马起源","谁创造了半人马","半人马起源传说"}},{q="为什么半人马如此仇恨牛头人？",a="半人马从凄凉之地开始疯狂扩张，并在平原上对土著居民进行了几代人的掠夺。他们以猎杀牛头人为乐，并将他们赶出莫高雷，使其在贫瘠之地陷入无尽的流浪，在兽人干预之前，他们几乎灭绝了整个种族。",al={"牛头人与半人马的世仇","为什么半人马猎杀牛头人","牛头人与半人马战争"}},{q="半人马属于哪些氏族？",a="卡利姆多主要的氏族包括考格雷、吉尔吉斯、玛格拉姆、玛洛迪和加拉克。每一个氏族都可以追溯到最初建立他们的可汗，并且经常彼此之间进行血腥的争斗。",al={"半人马部族","半人马氏族名称","半人马阵营"}},{q="今天在哪里可以遇到半人马？",a="他们领土的核心是凄凉之地的荒原，那里坐落着他们的圣地玛拉顿。然而，好战的战团和前哨站仍然游荡在贫瘠之地、杜隆塔尔和千针石林。",al={"哪里能找到半人马","半人马位置","半人马区域"}},{q="半人马可以交流或结盟吗？",a="总的来说，半人马将所有其他种族视为可以奴役或消灭的弱小猎物。然而，敌对氏族之间的激烈竞争有时可以被利用；例如，凄凉之地的玛格拉姆氏族或吉尔吉斯氏族有时会接受外来者的帮助，以消灭他们所仇恨的同类。",al={"半人马友好吗","可以与半人马结盟吗","友好的半人马"}},{q="瑟莱德丝公主对半人马来说是谁？",a="瑟莱德丝是他们的母亲和受人尊敬的守护者。在玛拉顿深处，她守护着他们被谋杀的父亲塞塔的灵魂，并周期性地将元素之怒注入她的后裔体内，激励他们去征服卡利姆多的新领土。",al={"半人马之母","瑟莱德丝与半人马","瑟莱德丝公主传说"}}},fx={f5a4aa83={q="什么是半人马？",a="半人马是一个好战而原始的种族，上半身是人类的躯干和手臂，下半身则是马的身体和四条腿。他们天性野蛮，过着游牧生活，漫游于卡利姆多中部干旱的平原和山谷。他们组成了领地意识极强的氏族，崇尚蛮力，袭击邻近的聚居地，并驱逐任何接近其猎场和水源的外来者。",al={"什么是半人马","半人马是谁","半人马种族"}},["5b0a3e11"]={q="为什么半人马如此敌视旅人？",a="敌意深植于半人马的天性之中。他们生来便身负诅咒，充满自我厌恶与愤怒，在诞生后不久就杀害了自己的父亲。从那以后，他们便以暴力和征服的眼光看待世界。他们认为卡利姆多中部理应属于自己，将任何路过的商队、旅人或聚居地都视为入侵者，必欲杀之、奴役之或驱逐之。",al={"半人马为什么攻击","半人马为什么好斗","半人马敌对"}},["9cda8173"]={q="谁领导半人马？",a="半人马没有统一的统治者，而是分成彼此纷争的独立氏族，例如科卡尔、吉尔吉斯、玛格拉姆、玛洛迪和加拉克氏族，每个氏族都由自己的可汗统治。这些可汗以残酷的武力和狡诈手段维持统治；各氏族耗费在彼此间血腥领土战争上的精力，几乎不亚于袭击外敌。",al={"半人马领袖","谁统治半人马","半人马可汗"}}},fp="7,311,16.484.0,22.569.0,14.483.0,18.507.0,28.259.0,39.289.0,36.209.0,36.200.0,39.295.0,41.250.0"}
P.entries["topic:church-of-the-holy-light"] = {n="圣光教会",s="圣光教会是人类主要的宗教机构，通过慈悲、正义和虔诚的美德来指引凡人的灵魂。它最初的中心位于已沦陷的北方王国洛丹伦，但在天灾军团的破坏之后，其领导核心如今已驻扎在暴风城的宏伟圣光大教堂内。",h="圣光教会是人类主要的宗教机构，通过慈悲、正义和虔诚的美德来指引凡人的灵魂。它最初的中心位于已沦陷的北方王国洛丹伦，但在天灾军团的破坏之后，其领导核心如今已驻扎在暴风城的宏伟圣光大教堂内。",kw={"阿隆萨斯·法奥","本尼迪塔斯","cathedral of light","教会","圣光","洛丹伦","北郡","圣骑士","牧师","白银之手","暴风城"},ang={["class:Paladin"]="你的神圣誓言源于阿隆萨斯·法奥大主教在第二次战争期间的契约，将骑士精神与圣光的恢复和惩戒之恩结合在一起。",["class:Priest"]="无论是为伤者提供慰藉，还是研究光辉与暗影之间艰难的平衡，你的职业都属于人类几千年来虔诚信仰的传承。",["faction:Alliance"]="圣光教会为联盟提供了道德上的团结和战地医疗救护，成为了对抗黑暗的永恒希望象征。",["race:Dwarf"]="长期以来与人类国度结盟，许多铁炉堡的矮人在圣光的布道和神圣大厅中找到了共同点和共同的美德。",["race:Human"]="几代以来，教会通过危机和瘟疫祝福着人类王国，它在暴风城的地位依然是你文明的精神支柱。"},sec={{t="起源与圣光信条",b="教会的起源可以追溯到一千多年前，那时圣光信仰在阿拉索的人类中扎根，教导他们引导神圣力量来治愈伤痛并净化苦难。在仁慈、正义以及“圣光存在于所有思考生命之中”这一基本信念的驱动下，这些教义最终凝聚成了一种有组织的信仰。洛丹伦王国成为了该教义的宗教中心，并在北方各地建立了受人尊敬的圣所，包括斯坦索姆、安多哈尔、提尔之手和圣光之愿礼拜堂。"},{t="伟大战争中的盾牌",b="在第一次战争中，北郡的兄弟会响应战斗的号召，治疗在前线对抗入侵兽人部落的倒下守卫者。由于他们缺乏武器或重甲，这些前线牧师在兽人手中伤亡惨重。大主教阿隆萨斯·法奥在认识到需要能够引导神圣愤怒并能在物理战斗中生存的神圣战士后，在第二次战争期间与最高指挥官安度因·洛萨商议建立了白银之手骑士团。圣骑士和牧师们一同成为了洛丹伦联盟的道德与军事堡垒，保护人类免于彻底灭绝。"},{t="北方的陷落与南方的避难所",b="第三次战争给信徒们带来了巨大的悲痛。当亡灵瘟疫在洛丹伦蔓延时，教会不知疲倦地救助病人并试图遏制污染，但当王国从内部崩溃时，他们还是被淹没了。随着洛丹伦变成了一片被天灾军团困扰的荒野，教会的驻地转移到了南方。在大主教本尼迪塔斯的管理下，教会在暴风城新建的圣光大教堂内重组了等级制度，为饱受折磨的联盟幸存者提供了慰藉、精神指引和军事目标。"}},faq={{q="圣光教会的核心哲学是什么？",a="教会教导说，一种统一的神圣能量连接着所有生命。修行者培养个人的正直、利他和慈悲，寻求改善自我以及周围的世界。信徒相信，以美德、正义和自我牺牲行事，就能体现圣光最纯粹的本质。",al={"圣光信仰","教会的信仰","圣光信条","教会哲学"}},{q="现在是谁在领导教会？",a="大主教本尼迪塔斯担任圣光教会的精神领袖。在大主教阿隆萨斯·法奥去世和北方洛丹伦王国沦陷后，本尼迪塔斯在位于暴风城中心的宏伟圣光大教堂内组织了祭司阶层。",al={"教会领袖","大主教是谁","教会首脑"}},{q="圣骑士教团是如何形成的？",a="在第一次战争期间，北郡未穿盔甲的教士被部落蓄意针对并屠杀。为了确保神圣施法者能在前线战争中生存，大主教阿隆萨斯·法奥在第二次战争前创立了白银之手骑士团，赋予骑士般的作战人员以神圣施法能力。",al={"圣骑士起源","圣骑士是如何创立的","阿隆萨斯·法奥圣骑士","白银之手成立"}},{q="教会最神圣的地方在哪里？",a="从历史上看，教会最古老的圣地位于洛丹伦的东威尔德，包括安多哈尔、斯坦索姆、提尔之手和圣光之愿礼拜堂。在天灾军团摧毁了北方之后，暴风城的圣光大教堂成为了该信仰最重要的圣所和权力中心。",al={"圣地","神圣场所","重要圣所"}},{q="教会在对抗亡灵瘟疫中发挥了什么作用？",a="在第三次战争期间，牧师和教士们投入到洛丹伦各地的战地医院中，试图净化受害者并阻止瘟疫蔓延。可悲的是，神圣魔法无法完全逆转这种超自然的腐蚀，许多神职人员在他们的病人死亡并作为天灾怪物复活时倒下了。",al={"教会的瘟疫角色","圣光治愈瘟疫","天灾与教会"}},{q="除了人类之外，还有其他种族信仰教会吗？",a="是的。铁炉堡的矮人在几个世纪前就接受了教会的教义，建立了他们自己虔诚的牧师和圣骑士教团。奎尔萨拉斯的高等精灵也采纳了这一哲学，掌握了恢复性治疗魔法，并后来将其与人类教士分享。",al={"非人类圣光信徒","矮人是否信仰圣光","高等精灵牧师"}}},fx={["1109d54d"]={q="什么是圣光教会？",al={"什么是圣光教会","谁是圣光教会成员","圣光教会"}},e7672a04={q="圣光教会起源于何处？",a="教会的根源可追溯到阿拉索人之间传播的圣光信仰。数百年后，迁徙者建立了洛丹伦王国，使其成为圣洁苦修者与朝圣者的中心。洛丹伦的领袖最终将这些信仰组织成统一的教会体系，并在各个人类王国建立圣所、修道院和礼拜堂。",al={"圣光教会的起源","圣光教会的历史","圣光教会如何建立"}},["12379874"]={q="圣光教会与谁结盟？",a="圣光教会与联盟有着密不可分的联系。第二次战争期间，大主教阿隆苏斯·法奥尔承诺教会将提供精神与军事支持，帮助击退部落，并建立了白银之手骑士团，让他们奔赴前线作战。洛丹伦陷落后，教会在暴风城的 Cathedral of Light 重建了总部，与暴风城王国及其盟友并肩行动。",al={"圣光教会势力","圣光教会支持谁","圣光教会与联盟"}}},fp="24,352,29.583.0,26.638.0,40.606.0,60.331.0,27.296.0,37.332.0,42.295.0,60.336.0,45.274.0"}
P.entries["topic:cult-of-the-damned"] = {n="The Cult of the Damned",s="The Cult of the Damned是一个由凡人狂热者、死灵法师和贵族组成的秘密结社，他们效忠于Lich King。该教派在Lordaeron北部成立于Third War之前，其成员通过毒害谷物供应，催生了Scourge，并一手策划了人类最伟大王国的毁灭。如今，幸存的教徒们管理着Plaguelands各处的瘟疫锅和死灵学院，同时积极渗透活人的城市。",h="The Cult of the Damned是一个由凡人狂热者、死灵法师和贵族组成的秘密结社，他们效忠于Lich King。该教派在Lordaeron北部成立于Third...",kw={"andorhal","凯尔达隆","锅炉领主","the cult of the damned","kel'thuzad","lich king","plague of undeath","plaguelands","通灵学院","scourge"},ang={["class:Mage"]="该邪教是肯瑞托荣誉上的一块痛苦污点，因为它是由达拉然自身受人尊敬的大法师之一Kel'Thuzad所创立。",["class:Paladin"]="The Cult of the Damned代表了对Holy Light的终极亵渎，他们运用污秽的死灵法术腐蚀活人，并扰乱死者的永恒安息。",["faction:Alliance"]="Alliance的斥候和士兵必须时刻保持警惕，因为邪教渗透者仍在试图在暴风城这样的活人城市内散布瘟疫和混乱。",["race:Human"]="每个活着的人都记得Lordaeron的崩溃；The Cult of the Damned作为一个痛苦的提醒，让人意识到人类不仅是被恶魔所征服，更是被他们自己城市和庄园内部的叛徒所出卖。",["race:Undead"]="对Forsaken来说，邪教徒是可悲的走狗，他们自愿将自由献给那个主人，而Forsaken曾为了粉碎其精神枷锁而奋力抗争。"},sec={{t="灵魂中的疾病",b="The Cult of the Damned是由流亡的大法师Kel'Thuzad在回应来自Frozen Throne的Lich King的心灵低语后建立的。Kel'Thuzad带着巨额财富和被禁止的黑暗魔法回到了Lordaeron，并提出了两种虚假的福音：对于绝望、贫困的下层阶级，他承诺社会平等和摆脱苦难的自由；对于像House of Barov这样的富有地主，他承诺永恒的生命和对领地不可动摇的掌控。事实上，无论是赤贫者还是富有者，都只是待宰的牲畜，被束缚在这个旨在从内部背叛家园的死亡邪教之中。"},{t="受污染的收成",b="邪教徒在凯尔达隆下方的地下城中完全秘密地行动，磨练他们的死灵法术，制造巨大的憎恶，并完善了从Northrend带到南方的Plague of Undeath。他们袭击了Lordaeron的粮仓，污染了Andorhal的谷物储备。随着受污染的面粉通过常规贸易路线传送到Eastweald各地的家庭，平民在几天内生病并死亡，随后在Lich King的心灵鞭笞下复活，成为蹒跚的奴仆。当王子Arthas在Andorhal击杀Kel'Thuzad时，邪教网络已经根深蒂固，王国的毁灭已成定局。"},{t="当前的威胁",b="虽然Arthas航行到了Northrend并登上了Frozen Throne，但The Cult of the Damned在复活的巫妖Kel'Thuzad的指挥下，在Lordaeron北部依然完全运作。在斯坦索姆的阴影和通灵学院的大厅里，活着的邪教徒执行黑暗仪式，维护散布在废弃农庄中的有毒瘟疫锅，并试图刺杀Scarlet Crusaders和Forsaken。因为他们仍有呼吸，这些侍僧可以在活人的定居点中行走而不被察觉，投毒水井，破坏补给线，并培养新兵以供养Scourge的机器。"}},faq={{q="为什么活着的凡人会加入一个将人变成亡灵的邪教？",a="Kel'Thuzad利用了凡人的弱点。他向贫困的下层阶级提供了绝对平等的全新秩序，让他们摆脱苦难；同时向Baron Rivendare和Barov家族这样的富有贵族承诺永生和永恒的力量。大多数入会者在一切太迟无法回头之前，都不知道瘟疫的真实且可怕的本质。",al={"为什么加入the cult of the damned","邪教徒动机","为什么效忠scourge"}},{q="为什么邪教徒被允许活着，而不是被杀死并复活？",a="活着的代理人对Lich King来说具有巨大的实际价值。他们可以不被察觉地穿过人类定居点，沿着标准的贸易路线进行贸易，购买物资，并从内部颠覆王国。在邪教教义中，亡灵化也被视为一种必须通过忠诚服务才能获得的无上光荣。",al={"为什么邪教徒是人类","他们为什么不是亡灵","活着的邪教徒"}},{q="The Cult of the Damned的基地在哪里？",a="他们主要的学术和精神堡垒是通灵学院，位于凯尔达隆下方的地下墓穴中。除了这所学院，大量的邪教徒在斯坦索姆的废墟、Western Plaguelands和Eastern Plaguelands的瘟疫锅周围，以及隐藏在活人定居点中的秘密据点内活动。",al={"邪教总部","邪教在哪里","邪教主基地"}},{q="谁创立了The Cult of the Damned？",a="大法师Kel'Thuzad，曾是达拉然肯瑞托的高阶成员。在因其被禁止的死灵研究受到谴责后，他前往北方与Lich King交流，Lich King赋予了他巨大的力量，并将他送回Lordaeron，以组织Scourge的凡人先锋队。",al={"谁创立了the cult of the damned","邪教创始人","kel'thuzad邪教"}},{q="The Cult of the Damned今天是如何传播瘟疫的？",a="虽然他们最初通过来自Andorhal的受污染谷物运输来传播瘟疫，但现在他们主要依靠遍布Plaguelands农场的巨大瘟疫锅。邪教徒锅炉领主酿造污秽的试剂，以持续释放毒害土地并唤醒死尸的有害枯萎云雾。",al={"瘟疫如何传播","瘟疫锅","邪教如何攻击"}},{q="该邪教与Forsaken的关系是什么？",a="他们是死敌。Forsaken摆脱了Lich King的心灵控制，并寻求对Scourge的复仇。邪教徒将Forsaken视为被窃取的财产和异端，不断寻求消灭他们，或为Frozen Throne夺回Lordaeron的废墟。",al={"邪教与forsaken","forsaken与the cult of the damned"}}},fx={["13254224"]={q="什么是 The Cult of the Damned？",a="The Cult of the Damned 是一个由活人组成的秘密组织，他们效忠于巫妖王，是天灾军团在人世间的根基。成员主要是狂热的人类，也包括其他种族。他们渗透各地聚居地，研习黑暗通灵术，并不懈地为活人王国带去死亡与瘟疫，以换取永生与力量的承诺。",al={"什么是 the cult of the damned","the cult of the damned 的成员","the cult of the damned 是什么组织"}},["3f52b63c"]={q="谁领导 The Cult of the Damned？",a="在艾泽拉斯，邪巫妖克尔苏加德指挥着这个教团。他曾是达拉然的大法师，也是教团的创始人。在他之上，巫妖王本人统治着一切。他被束缚在诺森德的冰封王座上，所有教徒都尊奉他为黑暗的主宰与神明。",al={"谁领导 the cult of the damned","the cult of the damned 的首领","教团的首领是谁"}},["3a452ce2"]={q="The Cult of the Damned 与谁结盟？",a="这个教团直接为巫妖王效力，与亡灵天灾军团并肩作战。第三次战争期间，他们曾协助燃烧军团降临，但他们绝对效忠于诺森德王座及其巫妖指挥官克尔苏加德。",al={"the cult of the damned 的盟友","教团为谁效力","the cult of the damned 与谁结盟"}},["3250aa21"]={q="The Cult of the Damned 起源于何处？",a="第三次战争前数年，巫妖王从诺森德以心灵感应联系大法师克尔苏加德，用通灵力量引诱他。克尔苏加德回到洛丹伦，凭借财富与煽动手段，招募了心怀不满的平民和渴求权力的贵族。他们以凯尔达隆的地下墓穴为秘密据点，研制亡灵瘟疫，在安多哈尔及洛丹伦北部散播受污染的谷物，为王国的灾难性覆灭铺平了道路。",al={"the cult of the damned 的历史","教团如何建立"}},af150ded={q="为什么 The Cult of the Damned 会敌视旅行者？",a="教徒将所有不属于他们的活人视为通灵实验的原料，或是天灾军团未来的士兵。他们一见到外来者便会发动攻击，以守护秘密实验室和瘟疫锅炉，并消灭任何可能扰乱黑暗仪式的人。",al={"为什么教徒会敌视他人","为什么教团会攻击你","the cult of the damned 敌对"}}},fp="18,457,22.652.0,20.632.0,18.609.0,62.368.0,74.313.0,38.324.0,35.291.0,56.309.0,48.283.0"}
P.entries["topic:dark-iron-clan"] = {n="黑铁部族",s="黑铁部族是一个古老的灰肤矮人派系，统治着黑石山火山深处的领地。在三锤之战中被逐出铁炉堡后，他们意外召唤了炎魔拉格纳罗斯，导致整个帝国沦为奴隶。如今，在达格兰·索瑞森大帝的统治下，他们一方面效忠于那位火元素领主，一方面对联盟和部落发动暗影战争。",h="黑铁部族是一个古老的灰肤矮人派系，统治着黑石山火山深处的领地。在三锤之战中被逐出铁炉堡后，他们意外召唤了炎魔拉格纳罗斯，导致整个帝国沦为奴隶。如今，在达格兰·索瑞森大帝的统治下，他们一方面效忠于那位火元素领主，一方面对联...",kw={"黑石","铜须","黑铁","弗莱拉斯","莫德古德","茉艾拉","拉格纳罗斯","暗炉","术士领主","索瑞森"},ang={["faction:Alliance"]="联盟将黑铁部族视为紧迫的生存威胁，这不仅因为他们不断的边境突袭，还因为他们绑架了铁炉堡的皇储茉艾拉·铜须公主。",["faction:Horde"]="部落在荒芜之地和燃烧平原与黑铁军队积极交战，因为双方都在争夺对黑石塔周围废墟的统治权。",["profession:Blacksmithing"]="黑铁工匠是火元素冶金术中无可匹敌的大师；他们在黑石深渊深处的专业黑铁铁砧和熔炉是锻造传奇武器所必需的。",["race:Dwarf"]="对于铜须部族来说，黑铁矮人是祖辈的叛徒和术士，他们古老的仇恨至今仍威胁着铁炉堡从洛克莫丹到丹莫罗的边境。",["race:Gnome"]="在沦陷的诺莫瑞根深处发现黑铁大师，这引起了人们对该部族参与诺莫瑞根沦陷的怀疑。"},sec={{t="三锤之战",b="很久以前，三个矮人派系在至高王莫迪姆斯·安威玛尔的统治下共同居住在铁炉堡。国王死后，内战爆发。铜须部族击败了两个敌对派系，将蛮锤部族和术士领主索瑞森的黑铁部族驱逐出境。为了复仇，索瑞森在赤脊山建立了定居点，而他的女巫妻子莫德古德则率军进攻格瑞姆巴托。当两次进攻都失败，且铜须和蛮锤联军兵临城下时，索瑞森试图释放一个世界末日般的地下实体来拯救自己。他的仪式撕裂了世界核心，并释放了炎魔拉格纳罗斯。"},{t="破碎的土地与束缚",b="The rebirth of Ragnaros violently shattered the surrounding peaks, carving out the blazing caldera of Blackrock Mountain flanked by the Searing Gorge and the Burning Steppes. The sorcerer-thane perished in the cataclysm, and the surviving Dark Irons found themselves bound into perpetual servitude to the Firelord. Over centuries within the lower chambers of the mountain, they constructed the sprawling subterranean capital of Shadowforge City. Their artisans and sorcerers became masters of stone golems, dark sorceries, and steam-driven siege machinery, weaponizing the molten elements around them under the gaze of flamewakers and elemental overlords."},{t="蔓延的暗影",b="在黑暗之门后25年，达格兰·索瑞森大帝在黑石深渊深处的帝国宝座上统治着整个部族。虽然索瑞森暗中策划利用所有矮人领地的联合力量推翻拉格纳罗斯，但他依然服从炎魔的命令，为全面战争做准备。黑铁渗透者和突袭小队在远离黑石山的地方发动打击，入侵了洛克莫丹、丹莫罗、荒芜之地和湿地。甚至可以在诺莫瑞根内部发现他们的军队和一位黑铁大师，尽管他们在诺莫瑞根沦陷中的具体角色尚不明确。"},{t="被劫持的公主",b="当麦格尼国王的女儿兼唯一继承人茉艾拉·铜须公主在前往湖畔镇的途中被黑铁特工劫持时，局势达到了沸点。麦格尼认为他的女儿被施了魔法，作为人质被扣押在黑石深渊中。从暗炉城流出的谣言描绘了一幅更为复杂的图景：公主已经成为了大帝的新娘，在父亲所鄙视的矮人中占据了一席之地。"}},faq={{q="黑铁部族的首都位于何处？",a="他们的首都是暗炉城，深凿于黑石山下的黑石深渊地下洞穴中。那里拥有宏伟的石造建筑、参议院大厅、军营以及大帝的帝国宝座。",al={"黑铁矮人住在哪","黑铁部族家园","黑铁部族首都是哪里","暗炉城位置"}},{q="为什么黑铁矮人有黑色的皮肤和发光的眼睛？",a="黑铁矮人有着灰烬般灰暗或黑色的皮肤，以及发光的红眼。他们生活在黑石山下，但他们这种外貌的确切成因尚不明确。",al={"为什么黑铁矮人外貌不同","黑铁矮人外观","为什么他们是灰色的"}},{q="谁是达格兰·索瑞森大帝？",a="达格兰·索瑞森大帝是最初的术士领主索瑞森的直系后裔。他在黑石深渊统治着黑铁部族，并直接听命于元素领主拉格纳罗斯，尽管他私下里梦想着从炎魔的束缚中挣脱出来。",al={"达格兰·索瑞森","谁领导黑铁部族","黑铁国王"}},{q="黑铁部族为什么要召唤拉格纳罗斯？",a="在三锤之战中，当铁炉堡和格瑞姆巴托的联军兵临城下时，术士领主索瑞森面临着注定的失败。为了寻找一种毁灭敌人的武器，他不顾一切地进行了一场古老的仪式，意外地释放了沉睡的炎魔，这导致了山脉破碎，并使他的人民沦为奴隶。",al={"拉格纳罗斯是如何被召唤的","索瑞森召唤拉格纳罗斯","为什么要召唤炎魔"}},{q="什么是瑟银兄弟会？",a="瑟银兄弟会是黑铁部族的一群工匠分裂出来的派系，他们脱离了部族和炎魔的统治。他们以灼热峡谷的瑟银哨塔为基地，与外来者进行贸易，寻求属于自己的财富，这使他们遭到了昔日族人的永久敌视。",al={"瑟银兄弟会与黑铁部族","瑟银兄弟会是黑铁矮人吗","友好的黑铁矮人"}},{q="为什么黑铁矮人在诺莫瑞根作战？",a="黑铁部队，包括黑铁大师，可以被发现在沦陷的诺莫瑞根内部。他们的存在表明他们与麦克尼尔·瑟玛普拉格有关，但他们在灾难中的具体角色尚不明确。",al={"诺莫瑞根的黑铁矮人","诺莫瑞根的黑铁大师","为什么黑铁矮人与穴居人在一起"}},{q="黑铁矮人与黑石兽人结盟了吗？",a="没有。虽然他们曾经容忍旧部落占据上层黑石塔，但现在黑铁矮人与上层的黑石兽人正在进行激烈的领土争夺战。黑铁矮人占据着深处，而雷德·黑手的兽人则控制着上层堡垒。",al={"黑铁矮人与兽人结盟","黑铁部族对抗黑石氏族","谁拥有黑石山"}},{q="黑铁矮人为什么要攻击格瑞姆巴托？",a="在三锤之战中，女巫莫德古德率领黑铁军队去摧毁格瑞姆巴托的蛮锤部族。尽管莫德古德被卡德罗斯·蛮锤所杀，但她邪恶的法术深深地诅咒了这座要塞，使蛮锤部族再也无法居住在那里。",al={"莫德古德与格瑞姆巴托","格瑞姆巴托为何被废弃","格瑞姆巴托的诅咒"}}},fx={["2c9aae62"]={q="什么是黑铁氏族？",a="黑铁氏族是矮人三大势力之一，与铜须氏族和蛮锤氏族齐名。他们以擅长巫术、野心勃勃且精于石作而闻名，居住在黑石山深处，以暗炉城为首都。他们受制于炎魔拉格纳罗斯，向联盟和部落双方开战。",al={"黑铁矮人是谁","黑铁矮人","黑铁矮人是什么"}},afe1d736={q="为什么黑铁矮人会敌视旅行者？",a="数百年来对铁炉堡积压的仇恨，以及拉格纳罗斯的烈焰暴政，使黑铁矮人将所有外来者视为敌人或工具。在炎魔的命令下，达格兰·索瑞森皇帝正准备率军征服一切，悍然袭击邻近土地，并屠杀任何擅闯其领地的人。",al={"为什么黑铁矮人会攻击","黑铁矮人的敌意","黑铁矮人是邪恶的吗"}},["627d3f57"]={q="黑铁氏族与谁结盟？",a="自黑铁氏族的巫师意外召唤出炎魔拉格纳罗斯以来，他们便受其麾下元素大军所制，饱受严酷奴役。他们与占据上层尖塔的黑石兽人维持着险恶的对立关系；他们的部队也出现在沦陷的诺莫瑞根，但具体职责尚不明确。",al={"黑铁矮人的盟友","黑铁矮人为谁效力","黑铁矮人的主宰"}}},fp="14,398,28.659.0,27.655.0,16.538.1,19.449.1,39.218.0,61.166.0,33.269.0,43.340.0,32.276.0,49.207.0,50.245.0,41.270.0"}
P.entries["topic:dark-iron-dwarf"] = {n="黑铁矮人",s="黑铁矮人是一个独特的矮人亚种，他们有着灰白的皮肤、炽热的红眼以及与生俱来的对火焰的亲和力。在三锤之战后，他们被驱逐出铁炉堡，居住在黑石山深处，他们的社会也落入了火元素领主拉格纳罗斯的暴政统治之下。",h="黑铁矮人是一个独特的矮人亚种，他们有着灰白的皮肤、炽热的红眼以及与生俱来的对火焰的亲和力。在三锤之战后，他们被驱逐出铁炉堡，居住在黑石山深处，他们的社会也落入了火元素领主拉格纳罗斯的暴政统治之下。",kw={"黑石深渊","黑铁","矮人","铁索","拉格纳罗斯","暗炉","索瑞森","瑟银兄弟会"},ang={["faction:Alliance"]="联盟的侦察兵警惕地监视着黑铁矮人，他们认识到这支帝国军队是一个咄咄逼人的扩张威胁，正压迫在铁炉堡领地的南大门外。",["faction:Horde"]="部落视黑铁矮人为占据黑石山的危险狂热分子，他们直接威胁着部落穿过荒芜之地及周边关口的补给路线。",["profession:Blacksmithing"]="黑铁工匠是传奇的铁匠，他们对黑铁矿拥有独家掌控权，这种矿石需要黑石山黑铁砧的炽热高温才能熔化和塑形。",["race:Dwarf"]="对于铁炉堡的铜须矮人来说，黑铁矮人代表着一场持久的家族仇恨已演变为生存威胁，这可以追溯到他们在三锤之战期间的血腥叛乱。"},sec={{t="火之遗产与流亡",b="与他们的铜须和蛮锤表亲不同，黑铁矮人拥有深灰色或煤黑色的皮肤，眼睛像发光的余烬一样燃烧。他们的历史在三锤之战中破裂，当时他们的索瑞森大帝试图征服铁炉堡。在战败并被驱逐到南部的赤脊山后，索瑞森试图召唤黑暗力量来复仇，却无意中释放了火元素领主拉格纳罗斯。这次灾难性的召唤将周围的山峰震碎，变成了黑石山的火山废墟，并将黑铁矮人一族束缚在火之奴役中。"},{t="在火元素领主的阴影下",b="在地底深处的暗炉城，生活是残酷且无情的。虽然黑铁矮人曾经只是雄心勃勃且狡猾，但在黑石山下，在拉格纳罗斯压迫性的光环影响下，几代人的时间已经将他们的大部分文化扭曲为残酷、偏执和暴政。黑铁法律对违规者只有一种判决：在残酷的律法之环中接受决斗审判。下毒和政治阴谋非常普遍，以至于黑铁矮人的旅行者通常会自己准备口粮，而不是信任陌生人的食物。"},{t="分裂与放逐",b="并非所有的黑铁矮人都效忠于达格兰·索瑞森大帝和拉格纳罗斯的邪教。持不同政见的派系已经脱离出来追求自己的目标。其中最著名的是瑟银兄弟会，这是一个由大师级铁匠组成的行会，总部位于灼热峡谷的瑟银哨塔，他们已经脱离了主族，雇佣外部冒险者来对抗他们曾经的主人。其他人则作为雇佣兵、间谍或贸易工程师与像荆棘谷地精这样的中立组织并肩工作。"}},faq={{q="为什么黑铁矮人有灰色的皮肤和红色的眼睛？",a="他们深灰色的皮肤和炽热、发光的红色眼睛是区分他们与山脉矮人和丘陵矮人的自然特征。他们深处地下的生活方式以及几个世纪以来生活在拉格纳罗斯的元素之火附近，进一步强调了他们的火山特性。",al={"黑铁矮人外貌","为什么黑铁矮人长这样","黑铁矮人红眼"}},{q="所有的黑铁矮人都是邪恶的吗？",a="不一定。虽然帝国黑铁社会充满背叛并受拉格纳罗斯意志的统治，但像传说中的建筑师弗兰克罗恩·铸铁这样的历史人物以及像反叛的瑟银兄弟会这样的组织，展现了荣誉、勇气以及独立于火元素领主腐化之外的意志。",al={"黑铁矮人都是坏的吗","善良的黑铁矮人","黑铁矮人可以是好的吗"}},{q="黑铁矮人的首都在哪里？",a="他们的文明中心位于暗炉城，就在黑石山内黑石深渊的地底洞穴深处。达格兰·索瑞森大帝从那里在熔火之心的阴影下统治着他的帝国。",al={"黑铁矮人首都","黑铁矮人住哪里","黑铁城市"}},{q="什么是律法之环？",a="律法之环是执行黑铁审判的竞技场。在黑铁社会中，针对氏族的犯罪判决是死刑。被告被强迫通过与成群的凶猛野兽和角斗士战斗来支付血的代价，这几乎没有囚犯能生还。",al={"律法之环","黑铁竞技场","暗炉审判"}},{q="什么是瑟银兄弟会？",a="瑟银兄弟会是一个由黑铁工匠组成的流氓派系，他们脱离了拉格纳罗斯的统治。他们驻扎在灼热峡谷的瑟银哨塔，将他们无与伦比的炽热冶金知识和黑铁锻造秘诀出售给愿意削弱帝国氏族的冒险者。",al={"瑟银兄弟会背景","瑟银兄弟会是谁","瑟银哨塔矮人"}}},fx={["95842395"]={q="什么是黑铁矮人？",a="黑铁矮人是一个独特的矮人族群，主要来自黑铁氏族。他们以灰烬般的肤色、火红的双眼，以及对巫术与工艺的精通而闻名，意志坚强，脾气也出了名的暴烈。大多数黑铁矮人居住在黑石山下的地下领地，也有人加入瑟银兄弟会等独立势力或佣兵组织。",al={"黑铁矮人是谁","黑铁矮人","什么是黑铁矮人"}},["25c6bc58"]={q="为什么黑铁矮人会敌视旅行者？",a="数百年的孤立、内部背叛，以及炎魔拉格纳罗斯的腐化影响，使黑铁氏族变得善于操纵、残忍且极度猜疑外人。他们对冒犯氏族的行为极其严苛，会处死擅闯者和罪犯，或让他们在审判竞技场中浴血厮杀。",al={"为什么黑铁矮人会攻击","黑铁矮人有攻击性吗","为什么黑铁矮人会敌视他人"}},["606deda9"]={q="谁领导黑铁矮人？",a="黑铁氏族由达格兰·索瑞森皇帝统治，他在黑石深渊深处的暗炉城中设有王座。",al={"黑铁矮人首领","谁是黑铁矮人皇帝","黑铁矮人统治者"}},d8b686f4={q="黑铁矮人与谁结盟或为谁效力？",a="黑铁氏族的大多数成员都受制于元素炎魔拉格纳罗斯，他的烈焰影响渗透着整个社会。许多黑铁矮人也与元素势力和黑暗教团并肩行动，而瑟银兄弟会等独立分支则与氏族领袖为敌。",al={"黑铁矮人为谁效力","黑铁矮人的盟友","黑铁矮人与拉格纳罗斯"}},["7edffefb"]={q="黑铁矮人起源于何处？",a="黑铁矮人曾是铁炉堡三大统治氏族之一。三锤之战后，他们的巫师酋长索瑞森向南逃亡，并在无意间将炎魔拉格纳罗斯召唤到艾泽拉斯。这场大灾变粉碎了赤脊山，造就了黑石山，也使黑铁氏族受制于炎魔的意志。",al={"黑铁矮人的起源","黑铁矮人的历史","三锤之战"}}},fp="15,328,24.618.0,27.536.0,22.482.0,53.271.0,31.303.0,46.226.0,28.293.0,32.295.0"}
P.entries["topic:dark-riders"] = {n="黑暗骑手",s="黑暗骑手是一群神秘的兜帽骑兵，他们让暮色森林陷入恐惧。作为冷酷无情的魔法圣物猎人，他们总是从暗处突袭，所到之处只留下杀戮。",h="黑暗骑手是一群神秘的兜帽骑兵，他们让暮色森林陷入恐惧。作为冷酷无情的魔法圣物猎人，他们总是从暗处突袭，所到之处只留下杀戮。",kw={"阿雷登","黑骑手","黑暗骑手","逆风小径","暮色森林","基特斯","艾露恩之镰","斯温·约根"},ang={["class:Druid"]="黑暗骑手对艾露恩之镰的无情搜寻对平衡构成了严重威胁，因为这把武器所蕴含的野性力量可能会在暮色森林中引发巨大的浩劫。",["class:Mage"]="这些魔法圣物的冷酷猎手，用鲜血向世人证明了追逐奥术力量所需要付出的代价。",["faction:Alliance"]="这些骑手在暴风城边境之外发动袭击，屠杀像斯温·约根一家这样的无辜定居者，证明了王国的边境已经彻底失控。"},sec={{t="暗影猎手",b="关于黑暗骑手的起源，人们知之甚少。目击者描述说，这些兜帽骑兵说话的声音既刺耳又尖锐。有人曾目击其中一名骑手使用一颗小宝石来听从一个被称为“主人”的家伙的命令。他们在王国各地搜寻拥有魔法力量的物品，斩杀任何阻挡他们获得战利品的人。"},{t="农场大屠杀",b="最近，黑暗骑手涌入了暮色森林，他们是被艾露恩之镰所散发出的扭曲空间的震动所吸引。他们不知道的是，矿工基特斯已经在罗兰之墓内发现了这根古老的法杖，却又迅速弄丢了它。骑手们追踪着魔法痕迹来到了附近的约根农场，向斯温·约根的家人索要这件神器。当惊恐的定居者无法回答他们的问题时，骑手们冷血地屠杀了斯温的妻子和孩子，这让斯温陷入了复仇的疯狂之中。"},{t="暮色森林的阴影",b="暮色森林中的流言将骑手们的邪恶狩猎与堕落的死灵法师摩本特·费尔联系在了一起，尽管没有人知道是什么将他们联系在一起，或者骑手们所效忠的“主人”到底是谁。"}},faq={{q="黑暗骑手是什么人？",a="他们是一群兜帽骑兵，专门搜寻拥有魔法力量的物品，并屠杀任何阻挡他们前进的人。他们的起源，以及他们所侍奉的主人的身份，至今仍是个谜。",al={"黑骑手","什么是黑暗骑手","暮色森林的骑手是谁"}},{q="他们对斯温·约根的家人做了什么？",a="他们在寻找艾露恩之镰，这把武器之前在附近被出土。当他们审问斯温·约根的妻子和孩子，发现他们对这件神器一无所知时，骑手们便毫不留情地杀害了他们。",al={"斯温农场惨案","约根农场发生了什么","骑手为什么要杀斯温一家"}},{q="黑暗骑手为什么会出现在暮色森林？",a="他们被艾露恩之镰所引发的时间和魔法扰动吸引到了这片黑暗的森林，这是一件在罗兰之墓中出土的古老神器。",al={"为什么黑暗骑手在暮色森林","黑暗骑手与艾露恩之镰","他们在猎杀什么"}},{q="黑暗骑手是亡灵吗？",a="没人知道。他们说话的声音既刺耳又尖锐，总是从暗处突袭，但他们兜帽下的真面目依然是个谜。",al={"黑暗骑手是幽灵吗","黑暗骑手是亡灵吗","黑暗骑手的真面目"}},{q="他们是在和摩本特·费尔合作吗？",a="守夜人注意到黑暗骑手与暮色森林的死灵法师摩本特·费尔之间存在可疑的往来，尽管他们结盟的具体条款尚不为人知。",al={"摩本特·费尔与黑暗骑手","摩本特·费尔的盟友"}}},fx={["18495474"]={q="为什么黑暗骑士会敌视旅行者？",a="黑暗骑士不惜一切代价猎取拥有魔力的物品。任何挡住他们去路，或掌握他们所寻圣物线索的人，都会被视为必须审问或杀死的障碍。斯温·约根一家在农庄遭遇的正是如此。",al={"为什么黑暗骑士会攻击","黑暗骑士的敌意","黑暗骑士有攻击性吗"}},c7ab6d4f={q="黑暗骑士有着怎样的历史？",a="关于他们的历史，所知甚少。他们曾在暮色森林现身，搜寻月神镰刀；农夫说不出它的下落，于是他们杀害了斯温·约根一家。夜色镇守卫认为他们与通灵师莫尔本特·费尔有关。有人曾看见其中一人通过一颗小宝石接受自称“主人”的命令。",al={"黑暗骑士的起源","黑暗骑士来自哪里","黑暗骑士如何出现"}}},fp="11,182,19.329.0,26.494.1,21.186.1,24.190.0,41.214.1,36.154.0,27.133.1,34.171.1"}
P.entries["topic:darkspear-tribe"] = {n="暗矛部族",s="暗矛巨魔是一个丛林巨魔部族，在被迫逃离他们位于荆棘谷的祖居地，并从无尽之海的一位娜迦海巫手中获救后，加入了萨尔的部落。在暗影猎手沃金的领导下，他们以森金村为临时避难所，现在已成为活跃在卡利姆多和东部王国的部落核心成员。尽管达成了联盟，但他们目前仍处于困境，试图从叛变的巫医扎拉赞手中夺回他们的新家园——回音群岛。",h="暗矛巨魔是一个丛林巨魔部族，在被迫逃离他们位于荆棘谷的祖居地，并从无尽之海的一位娜迦海巫手中获救后，加入了萨尔的部落。在暗影猎手沃金的领导下，他们以森金村为临时避难所，现在已成为活跃在卡利姆多和东部王国的部落核心成员。尽...",kw={"暗矛","回音群岛","古拉巴什","洛阿","玛拉卡金","森金","葬影","沃金","扎拉赞"},ang={["class:Shaman"]="暗矛萨满祭司将对原始洛阿灵魂的古老崇拜与从兽人和牛头人盟友那里学到的元素教义结合起来，耶努萨克雷就是该部族在大地之环中的代表人物。",["faction:Horde"]="从保卫天空的蝙蝠骑士到在石爪山脉酿造药剂的草药师，暗矛部族提供了神秘的狡黠和隐秘手段，平衡了部落纯粹的武力。",["race:Orc"]="兽人和巨魔之间的纽带是在第三次战争的血火中锻造出来的。萨尔将沃金视为他最亲密的战友，暗矛的斥候和巫医们在杜隆塔尔的战士部族身边忠诚地服役。",["race:Troll"]="作为一名暗矛巨魔，你背负着流亡民族在异国海岸重建的重担。每一次在回音群岛打击扎拉赞，或是在荆棘谷打击你那些残酷的古拉巴什同族，都在帮助确保你部族的生存。"},sec={{t="流亡与救赎",b="暗矛部族最初是破碎的荆棘谷古拉巴什帝国中一个规模较小、不那么残忍的部族，他们忍受了数个世纪与血顶和裂颅者部族等野蛮邻居之间的战争和饥荒。在被迫出海后，他们定居在偏远的岛屿上，却又面临水生鱼人、库尔提拉斯水手和一位娜迦海巫的威胁。他们的长老森金在深海之下的黑暗祭祀仪式中被俘并杀害，但在临死前，他预言兽人酋长萨尔将带领暗矛部族走向新的命运。萨尔率领的船队救下了他们，幸存者们向新部落宣誓效忠，并航行向西，抵达了卡利姆多。"},{t="回音群岛的陷落",b="抵达杜隆塔尔后，暗矛部族在靠近大陆海岸的热带回音群岛上建立了家园。但这种和平十分短暂。首先，戴林·普罗德摩尔上将的舰队迫使他们暂时撤退到尘泥沼泽的沼泽地中，直到部落军队消灭了入侵者。随后发生了更严重的内部背叛。一位名叫扎拉赞的杰出巫医拥抱了扭曲的巫毒教，控制了他族人的心智。为了保全自由的族人，森金的儿子兼继任者沃金下令再次撤离。如今，暗矛巨魔居住在沿海的营地森金村，并派遣勇士渡海去消灭扎拉赞，以此解放他们被奴役的兄弟。"},{t="巫毒与新部落",b="与他们同类食人的丛林亲戚不同，暗矛部族迅速适应了部落的荣誉价值观，并在石爪山脉建立了玛拉卡金，在凄凉之地建立了葬影村，并在灰谷建立了佐拉姆加前哨站等飞地。在奥格瑞玛，他们以精神谷作为他们的精神家园，在那里暗影猎手和巫医与洛阿神灵沟通。尽管他们因斥候、蝙蝠骑士和强大的妖术而受到尊重，但古老的传统依然根深蒂固；一些被他们的盟友所不齿的古老仪式仍在暗处悄然进行。"}},faq={{q="为什么暗矛巨魔会加入部落？",a="在第三次战争期间，兽人酋长萨尔的船队在强风暴中躲避到了暗矛群岛。当一位娜迦海巫和她的鱼人爪牙俘虏了巨魔和兽人时，萨尔解放了他们。尽管森金酋长在逃脱过程中牺牲，但他临终的幻象预言了萨尔将指引暗矛部族走向安全。为了报恩，森金的儿子沃金向部落宣誓效忠。",al={"巨魔为什么要加入部落","暗矛萨尔起源","巨魔如何加入部落"}},{q="现在是谁在领导暗矛部族？",a="该部族由沃金领导，他是受人尊敬的已故酋长森金之子。沃金是一位狡黠的暗影猎手，也是兽人酋长萨尔最亲近、最值得信赖的知己之一，他从奥格瑞玛的智慧谷为部落提供建议，并监督收复回音群岛的斗争。",al={"暗矛首领","谁是巨魔领袖","巨魔酋长"}},{q="为什么暗矛巨魔住在森金村而不是回音群岛？",a="回音群岛本应是该部族在杜隆塔尔的永久避难所，但他们遭到了内部背叛。一位丧心病狂的巫医扎拉赞使用黑暗魔法奴役了他巨魔同胞的心智。沃金没有选择屠杀被施了法的族人，而是下令自由的暗矛巨魔撤退到大陆海岸，建立森金村作为反击的基地。",al={"为什么森金村","回音群岛发生了什么","为什么回音群岛是敌对的"}},{q="暗矛部族最初来自哪里？",a="暗矛部族起源于荆棘谷的丛林，是破碎的古拉巴什帝国的一部分。由于比起血顶和裂颅者等敌对部族，他们规模较小且不那么残忍，他们遭受了持续的战争和饥荒，直到最后被完全逐出东部王国。",al={"暗矛最初的家园","暗矛荆棘谷","暗矛从哪里来"}},{q="暗矛巨魔还在实行食人习俗吗？",a="官方上是没有。为了与萨尔的部落和谐共处并尊重他们的联盟，暗矛部族将放弃食人和猎头作为部族政策。然而，几个世纪的丛林传承并不会在一夜之间消失，私下里仍有传言称，在远离窥探目光的暗处，一些黑暗的传统仪式仍在进行。",al={"暗矛会吃人吗","巨魔食人 部落","部落巨魔吃人吗"}},{q="暗矛巨魔崇拜什么神灵？",a="暗矛巨魔尊崇洛阿，它们是强大的原始灵魂和动物之神。他们的信仰围绕着一个庞大的神系，并通过他们巫医和暗影猎手的巫毒仪式来向其致敬。",al={"暗矛信仰","暗矛神灵","巨魔洛阿"}}},fx={f751a05c={q="什么是暗矛部族？",a="暗矛巨魔是丛林巨魔部族，也是萨尔部落的核心成员。他们曾被逐出荆棘谷的古老家园，历经流亡、危机四伏的海上航行，以及故乡的背叛，最终幸存下来。他们以适应力与狡诈著称，接纳了部落的荣誉准则，同时保留着影子魔法、巫毒和洛阿崇拜等传统。",al={"暗矛巨魔是谁","暗矛巨魔是什么","暗矛部族"}}},fp="15,479,19.674.0,26.687.1,24.559.0,42.396.0,40.289.0,71.376.0,45.301.0,47.315.0,38.190.0"}
P.entries["topic:defias-brotherhood"] = {n="迪菲亚潜行者",s="迪菲亚潜行者是一个遍布各地的犯罪网络，由强盗、劫匪和刺客组成，在地下对暴风城王国发动叛乱。大多数人都不知道他们的起源，他们已沦为暴徒，在南部农田一带肆虐。从一处隐秘据点出发，他们企图推翻腐败的贵族议会，并摧毁整个王国。",h="迪菲亚潜行者是一个遍布各地的犯罪网络，由强盗、劫匪和刺客组成，在地下对暴风城王国发动叛乱。大多数人都不知道他们的起源，他们已沦为暴徒，在南部农田一带肆虐。从一处隐秘据点出发，他们企图推翻腐败的贵族议会，并摧毁整个王国。",kw={"头巾","兄弟会","死亡矿井","迪菲亚","艾尔文","无畏舰","月溪镇","石匠","范克里夫","西部荒野"},ang={["class:Paladin"]="白银之手骑士团和像达索瑞恩·拉尔这样的教会领袖号召圣骑士们保卫像达芙妮·斯迪威尔这样手无寸铁的家园定居者，抵御西部荒野中冷酷的迪菲亚匪徒。",["class:Rogue"]="马迪亚斯·肖尔大师和军情七处严密监视着迪菲亚潜行者，因为范克里夫的特工在开锁、潜行和致命的地下伏击方面足以与皇家侦察兵相媲美。",["faction:Alliance"]="这场起义威胁着整个王国的稳定，切断了来自西部荒野的谷物供应，破坏了金矿的稳定，并动摇了公众对暴风城领导层的信心。",["race:Human"]="对于王国的人类来说，迪菲亚潜行者是暴风城内部腐烂的一个苦涩提醒——这是一场悲剧，诚实的城市建设者因为贵族的贪婪而变成了亡命之徒。"},sec={{t="阴谋之网",b="迪菲亚潜行者早已不再只是一个简单的流离失所的劳工团体。范克里夫招募了地精雇佣兵来负责军备，与河爪豺狼人和艾尔文森林的狗头人结盟，并与血帆海盗这样的亡命海盗进行交易。迪菲亚强盗洗劫了艾尔文森林各处的黄金运输队，他们的特工甚至在暮色森林建立了立足点，并从罗兰之墓中挖掘出了一件被诅咒的文物。更糟糕的是，迪菲亚潜行者的势力触角已经伸到了首都的核心地带，不仅享受着贵族议会中背叛者贵族的暗中支持，还策划了针对联盟最高权势机构的绑架事件。"},{t="死亡矿井中的无畏舰",b="月溪镇下方是铁甲湾，范克里夫的地精工程师们正在那里秘密组装一艘巨大的铁甲战舰，即迪菲亚无畏舰。这位工会领袖打算驾驭这座浮动要塞，通过地下的沿海水道驶出，从海上轰炸暴风城，将他自己亲手构建的宏伟建筑夷为平地。这场阴谋甚至延伸到了王室宫廷内部：像格雷戈尔·莱斯科瓦勋爵这样的腐败贵族充当了起义军的耳目，而女伯爵卡特拉娜·普瑞斯托的宫廷阴谋则故意让王国四分五裂，并使其对西部荒野下正在集结的舰队一无所知。"},{t="从石匠到掠夺者",b="第二次战争结束后，石匠工会受雇将暴风城的废墟重建为一座宏伟的石质首都。当他们的杰作完成后，贵族议会以沉重的战时债务为由，拒绝支付承诺的酬劳。工会领袖艾德温·范克里夫代表工人们发声，要求获得公正的赔偿，但贵族们的回应却是下令解散石匠工会。随之而来的城市街头骚乱，导致劳工们被驱逐出暴风城，流离失所。失去生计并被宣布为非法组织的范克里夫和绝望的工人们团结在一起，他们用红丝巾蒙住脸，象征着受冤屈者的鲜血，并开始通过拦路抢劫来索取他们认为自己应得的东西。"},{t="西部荒野的阴影",b="由于皇家军队兵力捉襟见肘，范克里夫将荒废的西部荒野农田变成了迪菲亚潜行者的行动基地。强盗们占领了月溪镇，并征用了死亡矿井中废弃的地下隧道。迪菲亚特工夺取了当地的矿井，用被重新编程的收割傀儡将农民们从家园中驱逐，并向土地撒盐，试图饿死该地区。由于王室无法或不愿派遣士兵保护乡村公民，当地农民在哨兵岭组建了人民民兵，与如今在人数和装备上都占优的敌人展开了一场绝望的消耗战。"}},faq={{q="为什么迪菲亚潜行者要戴红色头巾？",a="红色丝绸头巾是艾德温·范克里夫和流亡的石匠们采用的，作为一种反抗的象征。它代表了重建暴风城却遭到贵族背信弃义、暴力相待并最终被流放的受压迫工人阶级所流下的鲜血。",al={"迪菲亚面具含义","为什么是红丝巾","红色头巾的含义"}},{q="为什么潜行者要攻击无辜的农民而不是贵族？",a="虽然潜行者建立的初衷是对贵族有着真正的怨恨，但多年的无法无天的流亡生活将其变成了一个残酷的犯罪帝国。绝望、贪婪，以及招募了冷酷的凶徒和地精，使他们转向掠夺当地家园、焚烧农作物并夺取矿井，以资助他们的战争机器。",al={"为什么迪菲亚攻击农民","为什么要伤害西部荒野","迪菲亚的动机"}},{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫是石匠工会才华横溢的工会领袖，他负责监督了第二次战争后暴风城的重建工作。他精通潜行和诡计，在贵族议会拒绝支付工人工资后，他创立了迪菲亚潜行者。现在，他正在死亡矿井深处指挥他们的行动。",al={"范克里夫是谁","艾德温·范克里夫背景故事","迪菲亚领袖"}},{q="为什么暴风城不派遣军队去对付迪菲亚潜行者？",a="王国的财政已经严重枯竭，而暴风城军队因在荆棘谷等遥远领土驻扎据点而兵力不足。贵族议会内部的政治僵局进一步使王座瘫痪，导致乡村的西部荒野和暮色森林不得不依靠志愿民兵来保卫自己。",al={"暴风城军队在哪里","为什么西部荒野没有卫兵","为什么有人民民兵"}},{q="什么是人民民兵？",a="人民民兵是由格里安·斯托曼和哨兵岭受困的农民们组织的一支志愿防御部队。由于暴风城几乎没有提供任何士兵来清除西部荒野的迪菲亚潜行者，当地公民拿起武器来保卫自己的土地。",al={"西部荒野人民民兵","格里安·斯托曼民兵","哨兵岭军队"}},{q="迪菲亚潜行者在死亡矿井里建造什么？",a="隐藏在被称为铁甲湾的地下洞穴中，地精工程师和流氓工匠们正在建造迪菲亚无畏舰，这是一艘巨大的铁甲战舰。范克里夫打算将这艘战舰驶入暴风城港口，并摧毁这座首都。",al={"死亡矿井的战舰","他们在死亡矿井建造什么","迪菲亚无畏舰"}},{q="迪菲亚潜行者与国王的失踪有关吗？",a="瓦里安·乌瑞恩国王的下落仍然是一个谜。他在前往塞拉摩参加和平峰会的途中失踪，将年幼的安杜因留在了摄政王统治下的王座上。",al={"迪菲亚绑架了瓦里安吗","失踪的国王与迪菲亚","失踪的外交官与迪菲亚"}}},fx={d3e0b685={q="什么是迪菲亚潜行者？",a="迪菲亚潜行者是一个庞大的犯罪组织与反叛团体，成员包括昔日的石匠、盗贼、强盗和佣兵。这个组织最初源于一场激烈争端：重建暴风城的工匠与拒绝支付报酬的腐败贵族之间爆发了冲突。如今，他们已发展成一支地下武装力量，誓要推翻暴风城王国。",al={"什么是迪菲亚潜行者","迪菲亚成员是谁","迪菲亚潜行者简介"}},["5e60415a"]={q="迪菲亚潜行者是如何形成的？",a="第二次战争结束后，石匠公会重建了暴风城。工程完工后，贵族议会以背负军费债务为由拒绝支付报酬。公会会长艾德温·范克里夫带领民众抗议，石匠们却被驱逐，只得流亡。他们在西部荒野避难，并诉诸劫掠以讨回承诺的工钱；罪犯和亡命之徒不断加入，队伍日益壮大。",al={"迪菲亚起源","迪菲亚历史","迪菲亚如何兴起","石匠公会与迪菲亚"}},a3005855={q="迪菲亚潜行者为何在西部荒野和艾尔文森林活动？",a="迪菲亚潜行者的主要据点位于西部荒野的死亡矿井，在月溪镇地下。西部荒野贫困不堪，也遭到暴风城军方忽视。他们以此为基地，在西部荒野、艾尔文森林和暮色森林扩张势力，夺取有价值的矿井、袭击补给线，并牵制暴风城捉襟见肘的防御力量，同时暗中筹备对首都发动毁灭性打击。",al={"迪菲亚为何在西部荒野","迪菲亚为何在艾尔文森林","迪菲亚在哪里"}},b1c3d7cc={q="迪菲亚潜行者与谁结盟？",a="迪菲亚潜行者已与南方各地势力建立联系。在艾尔文森林，他们雇用狗头人看守夺取的矿井，并与西部荒野的河爪豺狼人合作。他们还雇佣地精工程师制造致命的收割魔像，与血帆海盗交易以获取海上作战经验，并暗中勾结首都内部的叛变者。",al={"迪菲亚盟友","与迪菲亚合作的势力","迪菲亚潜行者的同伙"}}},fp="18,375,21.670.1,33.630.2,24.754.1,24.622.1,36.256.1,68.328.0,22.332.1,60.306.2,29.267.0,50.264.1,66.169.2"}
P.entries["topic:dragonmaw-clan"] = {n="龙喉氏族",s="龙喉氏族是一个声名狼藉的兽人派系，因在第二次战争期间奴役并骑乘红龙而臭名昭著。在黑暗神器和邪恶魔法的指引下，他们将红龙女王阿莱克丝塔萨囚禁在格瑞姆巴托的诅咒大厅中，直到她重获自由并彻底粉碎了他们的统治。如今，他们四散的残党潜伏在卡兹莫丹的湿地和群山之中，对联盟和萨尔的新部落都怀有敌意。",h="龙喉氏族是一个声名狼藉的兽人派系，因在第二次战争期间奴役并骑乘红龙而臭名昭著。在黑暗神器和邪恶魔法的指引下，他们将红龙女王阿莱克丝塔萨囚禁在格瑞姆巴托的诅咒大厅中，直到她重获自由并彻底粉碎了他们的统治。如今，他们四散的残...",kw={"阿莱克丝塔萨","deathwing","恶魔之魂","巨龙之魂","龙喉氏族","格瑞姆巴托","耐克鲁斯·碎颅者","红龙军团","湿地","祖鲁希德"},ang={["class:Warlock"]="术士们研究着耐克鲁斯·碎颅者的历史，他对恶魔之魂的掌控证明了邪能是如何将艾泽拉斯最伟大的生物也变得屈服。",["faction:Alliance"]="联盟依然记得龙喉氏族在第二次战争中对他们的舰队和军队所带来的恐怖火雨；任何在卡兹莫丹发现他们的迹象，都会立即遭到军事响应。",["race:Dwarf"]="对于矮人来说，龙喉氏族是一种亵渎：他们玷污了古老的格瑞姆巴托要塞，并继续在卡兹莫丹的山路上为非作歹。",["race:Orc"]="对于萨尔的新部落的兽人来说，龙喉氏族体现了旧部落那给他们的族人带来毁灭的残忍与邪能腐化。"},sec={{t="从德拉诺到艾泽拉斯",b="龙喉氏族来自德拉诺，并跟随旧部落穿过了黑暗之门。在艾泽拉斯，他们将自己的才干用在了奴役当地长着翅膀的恐怖生物上。"},{t="恶魔之魂与格瑞姆巴托",b="在黑龙Deathwing低语的指引下，氏族酋长祖鲁希德找到了一个古老的金色圆盘：巨龙之魂。祖鲁希德将此圣物交给了他麾下最伟大的术士耐克鲁斯·碎颅者，后者利用其中的邪能将其改造为恶魔之魂。利用这件神器令人痛苦的力量，耐克鲁斯成功俘获了生命缚誓者阿莱克丝塔萨。龙喉氏族加固了废弃的矮人堡垒格瑞姆巴托，将红龙女王囚禁在黑暗之中，并迫使她的红龙军团在第二次战争期间作为旧部落的空中战列舰服役。"},{t="龙喉骑士的覆灭",b="当恶魔之魂最终被摧毁，红龙女王阿莱克丝塔萨和她的龙族摆脱了精神上的折磨，龙喉氏族的统治也随之终结。阿莱克丝塔萨吞噬了耐克鲁斯·碎颅者，她那复仇心切的龙族大军将格瑞姆巴托夷为平地，彻底摧毁了该氏族的根基。溃败且恐惧的龙喉残党四散逃往湿地的泥沼和格瑞姆巴托周边的崎岖山峰。留在艾泽拉斯的余部如今过着绝望且野蛮的流亡生活，拼命守卫着他们日渐缩减的营地，抵御着矮人巡逻队和复仇心切的巨龙。"}},faq={{q="既然龙喉氏族来自德拉诺，为什么他们叫这个名字？",a="这个名字反映了他们在艾泽拉斯臭名昭著的原因：在第二次战争期间为旧部落奴役并骑乘红龙。",al={"龙喉氏族名称由来","兽人名称"}},{q="他们是如何控制巨大的红龙的？",a="他们利用了恶魔之魂，这件古老的神器是黑龙之王Deathwing间接提供的。术士耐克鲁斯·碎颅者用它对红龙女王阿莱克丝塔萨施加了极大的痛苦，从而迫使她和她整个龙族在被毁灭的威胁下屈服。",al={"他们如何控制巨龙","恶魔之魂奴役","阿莱克丝塔萨是如何被俘的"}},{q="龙喉氏族是萨尔领导的部落的一部分吗？",a="不是。龙喉氏族效忠于黑手及其子嗣领导的旧部落。萨尔领导的新部落拒绝了恶魔崇拜和奴役巨龙的行为，使得龙喉氏族成为了对部落和联盟都怀有敌意的流亡者。",al={"龙喉氏族在部落内吗","龙喉与新部落","萨尔与龙喉氏族"}},{q="第二次战争后，这个氏族发生了什么？",a="当恶魔之魂被摧毁后，重获自由的红龙对龙喉氏族展开了反击，摧毁了他们在格瑞姆巴托的据点。耐克鲁斯被杀，幸存的兽人逃入了湿地和邻近的山区，他们至今仍在那里作为好战的掠夺者盘踞着。",al={"龙喉氏族现在的下落","第二次战争后的龙喉氏族","格瑞姆巴托发生了什么"}},{q="祖鲁希德是谁？",a="祖鲁希德是龙喉氏族的年长萨满和酋长，也是最初从Deathwing那里接收到骑龙异象的人。",al={"祖鲁希德","龙喉氏族酋长","谁领导龙喉氏族"}},{q="现在能在哪里找到龙喉兽人？",a="在艾泽拉斯，他们主要出现在湿地，潜伏在怒牙营地和通往格瑞姆巴托的阴森道路附近。他们不断与米奈希尔港的矮人和蛮锤氏族发生冲突。",al={"龙喉氏族所在地","去哪里寻找龙喉氏族","龙喉湿地"}}},fx={["27e0e992"]={q="龙喉氏族是什么？",a="龙喉氏族是来自德拉诺的兽人氏族。第二次战争期间，他们利用恶魔之魂奴役龙后阿莱克丝塔萨，迫使红龙军团为旧部落作战，因此臭名昭著。在格瑞姆巴托失去对巨龙的控制后，氏族遭受重创，如今仍是东部大陆一支危险的叛乱残部。",al={"龙喉氏族是什么人","龙喉氏族介绍","龙喉氏族是什么"}},ef3e041c={q="龙喉氏族为何敌视旅人？",a="龙喉氏族是旧部落中执迷不悟的残党，拒绝接受萨尔倡导的和平新路。失去被奴役的巨龙，又被赶出格瑞姆巴托后，他们靠暴力劫掠为生，与当地的蛮锤矮人、联盟旅人以及任何接近其设防营地的人激烈冲突。",al={"龙喉氏族为何攻击","龙喉氏族是邪恶的吗","龙喉氏族为何敌对"}},["2417d206"]={q="龙喉氏族与谁结盟？",a="湿地的龙喉氏族残部不受萨尔的新部落管辖。在碎颅者耐克鲁斯的领导下，他们抵御附近的敌人，守卫营地，并向摧毁他们在格瑞姆巴托势力的巨龙复仇。",al={"龙喉氏族的盟友","龙喉氏族为谁效力","龙喉氏族阵营"}}},fp="14,433,23.159.0,29.590.0,29.540.0,59.137.0,53.289.0,41.237.0,47.277.0,27.128.0,44.231.0"}
P.entries["topic:druid"] = {n="德鲁伊",s="德鲁伊是自然世界的守护者，他们直接从野生之灵、天体以及翡翠梦境中汲取力量。他们是变形大师，通过化身为原始野兽来保护土地或治愈创伤。这种修行最初由暗夜精灵开展，近期在牛头人中重新兴起，并由Skyborne传承至今。对德鲁伊而言，保护自然高于一切凡间的忠诚。",h="德鲁伊是自然世界的守护者，他们直接从野生之灵、天体以及翡翠梦境中汲取力量。他们是变形大师，通过化身为原始野兽来保护土地或治愈创伤。这种修行最初由暗夜精灵开展，近期在牛头人中重新兴起，并由Skyborne传承至今。对德鲁伊...",kw={"熊形态","猫形态","塞纳里奥议会","塞纳留斯","德鲁伊","翡翠梦境","哈缪尔","玛法里奥","月光林地","变形者"},ang={["class:Druid"]="作为平衡的守护者，德鲁伊游走于野兽的狂怒、治愈性的生命魔法与天体毁灭力量的微妙界限之间，直接从塞纳留斯和翡翠梦境中汲取智慧。",["race:NightElf"]="在一万年的时间里，卡多雷德鲁伊作为卡利姆多安静的沉睡守护者，在玛法里奥·怒风和半神塞纳留斯的指引下维护着自然的平衡。",["race:Skyborne"]="Skyborne的德鲁伊源于Eldre'Thalas中在Shal'nan起义期间拾起自然魔法的平民；影风森林的夜爪德鲁伊至今仍遵循着那条道路。",["race:Tauren"]="在大德鲁伊哈缪尔·符文图腾的领导下，牛头人重燃了与荒野的古老联系，加入了神圣月光林地的塞纳里奥议会，践行大地母亲的道路。"},sec={{t="自然之守护者",b="德鲁伊之道远不止是一种武艺；这是一种古老的生活方式，深深扎根于与自然和半神塞纳留斯的交流之中。德鲁伊驾驭纯粹的自然能量，指挥藤蔓纠缠敌人，引导月亮与群星的天体光辉，并召唤复苏的植物来愈合骨肉。他们的职责是维护宇宙平衡，保护不受拘束的荒野免受开发与腐蚀。"},{t="变形的天赋",b="德鲁伊的标志性特征是超自然的变形艺术。通过精神上的虔诚，修行者能够引导艾泽拉斯野兽的原始特质。他们披上熊的厚皮来抵御猛烈的攻击，化身为矫健的猫科捕食者从阴影中发动突袭，或者采取水栖和飞禽形态来横跨海洋与天空。在变形状态下，他们的兽口很难发出凡人的语言，但其身体素质足以与荒野中的顶级掠食者媲美。"},{t="塞纳里奥议会",b="一万年前，半神塞纳留斯首次将德鲁伊教义传授给了玛法里奥·怒风，随后凡人德鲁伊教义在塞纳里奥议会下正式确立。议会总部设在神圣的月光林地，监管着整个卡利姆多的德鲁伊修行，独立于凡人阵营和政治纷争之外。长期以来，议会仅由在翡翠梦境中沉睡了数世纪的暗夜精灵男性主导，但在第三次战争之后，暗夜精灵女性和牛头人都受到了欢迎，加入了这一行列。"},{t="Skyborne的德鲁伊",b="德鲁伊之道很久以前就传到了Skyborne。当Eldre'Thalas的Shal'nan反抗军崛起对抗Tortheldrin王子时，加入其中的平民拾起了自然魔法，这受到北方塞纳里奥议会的影响，而Tortheldrin则对此嗤之以鼻，认为这不符合上层精灵的身份。他们的后裔至今仍在修习这种魔法：泽风岛影风森林的夜爪德鲁伊大多与世隔绝，不与其他Skyborne派系来往。"}},faq={{q="谁是第一位凡人德鲁伊？",a="玛法里奥·怒风是第一位在半神塞纳留斯的直接指导下掌握德鲁伊艺术的凡人，这发生在上古之战前大约一万年。",al={"第一位德鲁伊","谁创立了德鲁伊教义","玛法里奥第一位德鲁伊"}},{q="牛头人是如何成为德鲁伊的？",a="牛头人德鲁伊在雷霆崖的大德鲁伊哈缪尔·符文图腾的指导下学习荒野之道，现在牛头人已与暗夜精灵一起加入了塞纳里奥议会。",al={"牛头人德鲁伊背景","为什么会有牛头人德鲁伊","哈缪尔·符文图腾德鲁伊"}},{q="什么是塞纳里奥议会？",a="塞纳里奥议会是艾泽拉斯德鲁伊的管理组织，旨在规范荒野修行并保护自然。它独立于联盟和部落运作，成员听命于议会的大德鲁伊，并聚集在神圣的月光林地。",al={"塞纳里奥议会背景","什么是月光林地组织"}},{q="德鲁伊在动物形态下能说话吗？",a="通常不能。当变形为野兽时，德鲁伊的发声器官会反映该动物的构造，使得正常的凡人语言无法发出，尽管极少数强大且罕见的个体找到了规避这一限制的魔法途径。",al={"德鲁伊在熊形态下能说话吗","变形语言背景"}},{q="什么是翡翠梦境？",a="翡翠梦境是一个翠绿、原始的位面，它如镜子般映射着未曾受文明触及的艾泽拉斯。暗夜精灵德鲁伊长期以来会进入长达数世纪的冬眠，以漫步其间并与自然之灵交流。",al={"翡翠梦境背景","德鲁伊在哪里睡觉"}},{q="为什么德鲁伊最初要沉睡数世纪？",a="在世界之树诺达希尔受到祝福后，暗夜精灵德鲁伊进入兽穴，花费数世纪在翡翠梦境中徘徊，协助伊瑟拉的绿龙军团培育艾泽拉斯的精神生态系统，直到第三次战争迫使他们苏醒。",al={"德鲁伊冬眠","兽穴沉睡","长眠"}},{q="哪些种族可以成为德鲁伊？",a="暗夜精灵和牛头人，两者都隶属于塞纳里奥议会，还有Skyborne，其夜爪德鲁伊在泽风岛保持着自己的传统。",al={"谁能成为德鲁伊","德鲁伊种族","skyborne德鲁伊"}}},fp="5,410,20.432.0,25.508.0,19.487.0,22.436.0,31.183.0,29.170.0,28.270.0,38.242.0,26.232.0,50.252.0,26.142.0"}
P.entries["topic:druids-of-the-fang"] = {n="尖牙德鲁伊",s="尖牙德鲁伊是一个扎根于哀嚎洞穴迷宫深处的邪恶教派。这些背叛的暗夜精灵切断了与塞纳里奥议会的一切联系，并在自封为瑟芬迪斯大人的指挥下，采取了蛇类形态。虽然他们黑暗结社的真正起源对外部观察者来说仍然是个谜，但他们无情地追求着他们的宏伟计划：占领地下水域，并将贫瘠之地改造成他们自己扭曲的乐园。",h="尖牙德鲁伊是一个扎根于哀嚎洞穴迷宫深处的邪恶教派。这些背叛的暗夜精灵切断了与塞纳里奥议会的一切联系，并在自封为瑟芬迪斯大人的指挥下，采取了蛇类形态。虽然他们黑暗结社的真正起源对外部观察者来说仍然是个谜，但他们无情地追求着...",kw={"贫瘠之地","尖牙德鲁伊","翡翠梦境","纳拉·蛮鬃","纳拉雷克斯","梦魇","瑟芬迪斯","蛇形态","哀嚎洞穴"},ang={["class:Druid"]="尖牙德鲁伊代表了翡翠梦境被腐化的严重危险，展示了当德鲁伊放弃塞纳里奥式的和谐，转而采用扭曲、不正统的动物形态时会发生什么。",["race:NightElf"]="在卡利姆多中心地带，看着卡多雷同胞堕落成一个野性难驯、充满梦魇的蛇类邪教，这对暗夜精灵的传统来说是一种痛苦的哀伤和耻辱。",["race:Tauren"]="纳拉·蛮鬃和雷霆崖的牛头人深深致力于终结尖牙的威胁，他们认为尖牙德鲁伊对贫瘠之地水源的玷污是对大地母亲的亵渎。"},sec={{t="崇高的愿景沦为剧毒",b="贫瘠之地并非一直是一片荒芜的废土，纳拉雷克斯曾试图将其恢复为往昔郁郁葱葱、绿意盎然的圣地。纳拉雷克斯带领着一支由年轻德鲁伊组成的忠诚队伍进入了哀嚎洞穴的地下深处，利用天然的地下裂隙和地下泉水。通过进入一种诱导睡眠状态，纳拉雷克斯希望将翡翠梦境的生命能量引导至水道中，从而使上方焦灼的草原恢复勃勃生机。"},{t="堕入梦魇",b="纳拉雷克斯的入定过程中出了大岔子。纳拉雷克斯的睡眠中没有引导翡翠梦境的纯净安宁，反而被一种邪恶、扭曲的梦魇所侵蚀。这种黑暗通过洞穴向外蔓延，迅速扭曲了当地的野生动物，并污染了地下泉水。纳拉雷克斯的追随者们没有逃走去寻求塞纳里奥议会的帮助，而是被梦魇的力量所淹没，他们的心智和灵魂随着地下生态系统一起发生了变异。"},{t="尖牙的崛起",b="纳拉雷克斯曾经最得意的学生抛弃了他导师最初的教诲，以瑟芬迪斯大人的名义拥抱了腐化。瑟芬迪斯将堕落的追随者们集结起来，组成了尖牙德鲁伊，并采用了毒蛇和蟒蛇的原始毒辣形态，而不是塞纳留斯所认可的传统熊和猫形态。这个教派实际上囚禁了他们沉睡的导师，一心想以他的梦魇为食，通过暴力将贫瘠之地改造成他们统治下的蛇类乐园。"}},faq={{q="谁是尖牙德鲁伊？",a="他们是一群腐化的暗夜精灵德鲁伊，在纳拉雷克斯的带领下进入了哀嚎洞穴。当纳拉雷克斯的入定触碰到黑暗梦魇时，他们不仅没能治愈贫瘠之地，反而陷入了疯狂，变成了狂热崇拜蛇类的叛徒。",al={"尖牙德鲁伊背景故事","尖牙德鲁伊是什么","哀嚎洞穴的德鲁伊"}},{q="他们最初为什么要进入哀嚎洞穴？",a="纳拉雷克斯和他的追随者们试图利用洞穴中丰富的地下泉水。通过将翡翠梦境的盎然生命力引导至水系中，他们希望将干旱的贫瘠之地变回繁茂的绿色森林。",al={"他们为什么在哀嚎洞穴","纳拉雷克斯的目标","为什么要治疗贫瘠之地"}},{q="谁领导着尖牙德鲁伊？",a="他们由瑟芬迪斯大人领导。瑟芬迪斯曾是纳拉雷克斯最出色、最聪明的学生，在梦魇降临时彻底陷入疯狂，并自封为新成立的尖牙德鲁伊的领袖。",al={"尖牙德鲁伊的领袖","瑟芬迪斯背景故事","谁领导他们"}},{q="他们采取什么样的动物形态？",a="与塞纳里奥议会中采用熊、猫或风暴乌鸦形态的传统德鲁伊不同，尖牙德鲁伊利用毒蛇和蟒蛇的力量，拥抱蛇类魔法和邪恶的蛇形变形。",al={"蛇形态德鲁伊","尖牙德鲁伊变形","蛇形态"}},{q="塞纳里奥议会如何看待他们？",a="塞纳里奥议会将尖牙德鲁伊视为一种危险的异端和邪教。像雷霆崖的纳拉·蛮鬃这样的长者以及纳拉雷克斯剩下的一些忠实追随者正在紧急行动，试图在腐化摧毁这片土地之前，消灭尖牙的领袖并净化这些腐化。",al={"塞纳里奥议会的看法","他们是塞纳里奥议会的一部分吗","哈缪尔对尖牙德鲁伊的看法"}},{q="纳拉雷克斯发生了什么事？",a="纳拉雷克斯仍然被困在哀嚎洞穴中心的一场深沉而痛苦的睡眠中。他的门徒将他囚禁起来，利用他持续不断的梦魇作为源源不断的能量，来扭曲洞穴以及他们自己的魔法。",al={"纳拉雷克斯死了吗","纳拉雷克斯的状态","纳拉雷克斯在哪里"}}},fx={f17ecb7b={q="尖牙德鲁伊为何充满敌意？",a="纳拉雷克斯汲取翡翠梦境的力量，试图治愈贫瘠之地时，他的愿景逐渐腐化成蔓延的噩梦。这场噩梦扭曲了弟子们的心智与灵魂，使他们陷入疯狂。如今，他们已堕落为尖牙德鲁伊，会猛烈攻击任何闯入者，以保护被腐化的领地，并迫使周围的世界映照出他们噩梦般的幻象。",al={"尖牙德鲁伊为何攻击","尖牙德鲁伊为何好斗","尖牙德鲁伊的敌人"}},["1c4e8a0d"]={q="尖牙德鲁伊是如何形成的？",a="他们原本是一支高贵的暗夜精灵德鲁伊教团，追随纳拉雷克斯深入哀嚎洞穴的地下泉水。他们怀着善意，想要引导翡翠梦境的力量，让贫瘠之地这片干旱之地重现繁茂生机。然而，梦境在纳拉雷克斯周围扭曲成疯狂，腐化了他的追随者，也使他最出色的弟子瑟芬迪斯领主陷入黑暗而狂热的崇拜。",al={"尖牙德鲁伊的起源","尖牙德鲁伊如何兴起","尖牙德鲁伊的历史"}},d5ccf0b1={q="他们为何被称为尖牙德鲁伊？",a="这些堕落的德鲁伊没有选择熊或猫等传统德鲁伊形态，而是拥抱了毒蛇的形象。在瑟芬迪斯领主及蛇形首领的引领下，他们变形成蝰蛇、使用致命毒液，并饲养凶险的爬行动物作为伙伴；他们背弃了传统的塞纳里奥之道，以毒牙为自身象征。",al={"尖牙德鲁伊为何如此","尖牙德鲁伊名称含义","尖牙之名的由来"}}},fp="18,474,31.468.0,22.515.1,18.519.1,31.259.1,50.231.0,33.214.1,31.222.0,39.270.0,25.215.1"}
P.entries["topic:dwarf"] = {n="矮人",s="矮人是一个坚韧不拔的种族，他们是由古代泰坦造物土灵化身而成，现居于卡兹莫丹及以外的雪山王国之中。他们以精湛的石匠工艺、冶金技术和强大的正面作战能力而闻名，是联盟最坚定、最可靠的中流砥柱之一。在国王麦格尼·铜须的统治下，他们庞大的地底都城铁炉堡成为了矮人社会的心脏。",h="矮人是一个坚韧不拔的种族，他们是由古代泰坦造物土灵化身而成，现居于卡兹莫丹及以外的雪山王国之中。他们以精湛的石匠工艺、冶金技术和强大的正面作战能力而闻名，是联盟最坚定、最可靠的中流砥柱之一。在国王麦格尼·铜须的统治下，他...",kw={"铜须","黑铁","丹莫罗","矮人","土灵","铁炉堡","卡兹莫丹","麦格尼","奥达曼","蛮锤"},ang={["class:Paladin"]="矮人圣骑士带着山脉般坚定的意志信仰圣光，将人类的神学与卡兹莫丹不可动摇的军事纪律融为一体。",["faction:Alliance"]="铁炉堡丰富的矿产资源、无与伦比的攻城工程技术和坚韧不拔的步兵构成了联盟的北方堡垒。",["profession:Blacksmithing"]="矮人以艾泽拉斯最优秀的铁匠而闻名，他们利用Great Forge的火山热能来锻造传奇的武器和盔甲。",["profession:Mining"]="矮人诞生于岩石，天生就拥有一双敏锐的眼睛，能发掘地底深处埋藏的富矿脉和古代宝石。",["race:Dwarf"]="每个矮人都承载着石灵遗产的重担，在氏族间古老的血海深仇中穿行，同时发掘着定义你们存在的泰坦秘密。",["race:Gnome"]="矮人是你们最古老、最真诚的盟友，他们曾协助建造了诺莫瑞根最初的石砌建筑，现在又在Tinker Town为你们的人民提供了避难所。"},sec={{t="山脉之子",b="很久以前，被称为土灵的地底泰坦造物从奥达曼的穹顶中苏醒，由于血肉诅咒的影响，他们转化为了血肉之躯。他们自称为矮人，收复了卡兹莫丹——这个名字是为了纪念泰坦卡兹格罗——的高耸山峦，并在丹莫罗的山峰之下开凿了宏伟的地底堡垒铁炉堡。矮人拥有令人难以置信的天生韧性，对矿石和岩石有着敏锐的洞察力，并且钟情于温暖的炉火和香醇的麦芽酒，他们对待工艺和战争的态度同样坚韧顽强。"},{t="三锤之战",b="几个世纪前，随着至高王莫迪姆斯·安威玛尔的逝世，矮人的统一局面分崩离析。铁炉堡在三个敌对派系之间爆发了内战：铜须氏族、蛮锤氏族和黑铁氏族。在铜须氏族占据了山脉并驱逐了他们的族人之后，黑铁氏族的索瑞森大帝对两个对手发动了灾难性的复仇战争。在赤脊山下陷入绝境时，索瑞森意外召唤了炎魔拉格纳罗斯，将他自己的疆域焚烧成了灼热峡谷和燃烧平原的火山废土。幸存的黑铁矮人沦为了黑石山下的奴隶，而饱受蹂躏的蛮锤矮人则向北迁移到了辛特兰的鹰巢山。"},{t="联盟的坚盾",b="在第二次战争期间，当兽人部落横扫大陆时，国王麦格尼·铜须关闭了铁炉堡的大门，抵御了残酷的围攻，同时矮人军队与洛丹伦联盟并肩作战。矮人战士以重型板甲、致命的火枪和无畏的狮鹫骑士而闻名，在击溃部落的过程中发挥了至关重要的作用。如今，铁炉堡王国依然是联盟最忠诚的捍卫者之一，他们不仅接纳流离失所的侏儒盟友，还积极发掘卡兹莫丹的泰坦遗迹，以揭开他们古老起源的奥秘。"}},faq={{q="矮人最初来自哪里？",a="矮人是土灵的后裔，这是由泰坦守护者创造的古老岩石生命。土灵被封印在奥达曼的地底穹顶中，在数千年的时光里受到了血肉诅咒的影响，苏醒后成为了凡人矮人，随后他们便外出探索并在卡兹莫丹的山脉中定居。",al={"矮人起源","矮人背景知识","矮人是如何诞生的","土灵"}},{q="现在是谁在统治矮人？",a="国王麦格尼·铜须在Great Forge统治着铁炉堡王国和铜须氏族。他带领他的人民度过了第二次和第三次战争，至今仍是联盟的核心基石之一。",al={"谁是矮人国王","矮人领袖","铁炉堡国王","magni bronzebeard"}},{q="三大矮人氏族是什么？",a="三大主要氏族分别是统治铁炉堡和丹莫罗的铜须氏族；居住在辛特兰的露天环境中并骑乘狮鹫的蛮锤氏族；以及居住在黑石山深处、受拉格纳罗斯的烈焰统治的黑铁氏族。",al={"矮人氏族","三锤之战","铜须 蛮锤 黑铁","铁炉堡的氏族"}},{q="为什么黑铁矮人是敌人？",a="在三锤之战期间，黑铁氏族试图消灭铜须氏族和蛮锤氏族。在面临失败时，他们的索瑞森大帝召唤了炎魔拉格纳罗斯，这摧毁了他们的家园，并将整个氏族束缚在黑石山下，沦为元素火焰与暗影的奴仆。",al={"为什么黑铁矮人是邪恶的","黑铁氏族背景","暗炉城矮人"}},{q="为什么侏儒会住在铁炉堡里？",a="矮人和侏儒自几个世纪前第一次见面以来就结下了深厚的情谊，他们以石匠工艺的秘密交换机械工程学的知识。当诺莫瑞根在穴居人入侵和有毒辐射中陷落时，国王麦格尼在Tinker Town为大工匠Gelbin Mekkatorque和他的难民提供了避难所。",al={"为什么侏儒在铁炉堡","铁炉堡的侏儒","诺莫瑞根发生了什么"}},{q="矮人崇拜圣光吗？",a="是的。许多铁炉堡矮人信仰人类引入的圣光。矮人牧师保留了他们自己对圣光的教义，最近也有许多意志坚定的矮人作为圣骑士加入了白银之手骑士团。",al={"矮人宗教","矮人与圣光","矮人信仰圣光吗"}},{q="矮人可以选择哪些职业？",a="矮人可以训练成为战士、圣骑士、猎人、潜行者、牧师和萨满祭司。",al={"矮人职业","矮人可以选择什么职业","矮人可以成为萨满吗"}}},fp="5,471,20.582.0,28.742.0,32.603.0,43.312.0,32.224.0,38.259.0,38.306.0,39.297.0,34.255.0,29.73.0"}
P.entries["topic:earth-mother"] = {n="大地母亲",s="大地母亲是牛头人所崇拜的至高无上的仁慈创世神，被尊为艾泽拉斯大地与元素的化身及缔造者。在牛头人的神话中，她塑造了群山、平原与季节，并将太阳与月亮高悬于天际，作为她时刻注视大地的双眼。她的存在渗透在牛头人日常生活的方方面面，指引着他们对自然的崇敬、对元素的责任以及对来世的希冀。",h="大地母亲是牛头人所崇拜的至高无上的仁慈创世神，被尊为艾泽拉斯大地与元素的化身及缔造者。在牛头人的神话中，她塑造了群山、平原与季节，并将太阳与月亮高悬于天际，作为她时刻注视大地的双眼。她的存在渗透在牛头人日常生活的方方面面...",kw={"安舍","创世","大地母亲","穆沙","莫高雷","舒哈鲁","牛头人"},ang={["class:Druid"]="牛头人德鲁伊将他们与自然的圣洁纽带视为与大地母亲的身体直接沟通，响应她古老的呼唤以维持大地的平衡。",["class:Shaman"]="牛头人萨满在尊崇元素之灵的同时，也尊崇大地母亲，铭记着风、水、火与石是她最早的同伴。",["faction:Horde"]="通过与莫高雷的联盟，兽人与丛林巨魔已对牛头人崇敬大地母亲的习俗耳濡目染，常将其名号作为一种恭敬的祝福来使用。",["race:Tauren"]="舒哈鲁社会的每一个侧面——从游牧民对猎物的尊重，到酋长议会的决策——皆根植于大地母亲的律法、牺牲与永恒的爱。"},sec={{t="创世之初",b="牛头人的创世神话说，在昼夜更替出现之前，大地母亲就开始着手塑造艾泽拉斯，将其作为她即将到来的子民们的庇护所。她用指甲在刚刚隆起的山脉上刻画，迸发出了世界上的第一簇火焰；她的双手开凿了河流与海床。她的笑声赋予了风以呼吸，随着她将原始的迷雾抬升至天空，她降下了第一场雨，令草木、森林与谷物从土壤中破土而出。"},{t="太阳、月亮与舒哈鲁",b="在大地母亲的感召下，友善的元素们协助她诞下了双子：太阳安舍（An'she）与月亮穆沙（Mu'sha）。为了在守护他们的同时小憩片刻，她将这对光芒万丈的子嗣安置于自己的双眼中，当她开合眼睑时，便创造了昼夜与四季的循环。后来，她将心口紧贴肥沃的土地，向大地吹入生命的歌谣，从而创造了舒哈鲁，也就是第一批牛头人。她嘱托双子与元素们教导这些年轻的凡人如何狩猎、建造、舞蹈，并与荒野和谐共生。"},{t="苍穹之眼",b="久而久之，大地母亲将安舍与穆沙安置在天空之中，太阳与月亮昼夜不息地守护着这片大地。牛头人相信，她的灵魂如今栖息在世界的河流、树木、平原与群山之中，而每一个较小的自然之灵皆由她所生，并终将回归于她。"},{t="永恒的遗产",b="牛头人相信她的灵魂至今仍怀抱着艾泽拉斯。她倾听着风，以此聆听孩子们的祈祷；她的心脏则在深邃的岩石中跳动。牛头人的猎手、萨满与德鲁伊在每一次狩猎与收获后都会向她致谢，因为他们相信所有生命皆源自她的拥抱，而每个牛头人的灵魂在死后都会回归她的怀抱。"}},faq={{q="大地母亲是谁？",a="大地母亲是牛头人信仰核心中的那位仁慈创世神。根据他们的神话，她雕琢了艾泽拉斯的地理景观，诞生了太阳与月亮，并用土壤创造了牛头人一族。",al={"大地母亲是什么","大地母亲传说","牛头人神祇"}},{q="天空中的眼睛是什么？",a="她的右眼是安舍，即太阳，为世界带来光明与温暖。她的左眼是穆沙，即白夫人月亮，带来宁静与安眠。牛头人神话称，她将它们安置在苍穹之上，用以看顾大地。",al={"安舍与穆沙","牛头人的太阳与月亮","大地母亲之眼"}},{q="大地母亲是真实存在的实体吗？",a="对牛头人而言，她是一个活跃且充满爱意的精神存在，她的本质渗透在自然世界、岩石与风中。萨满与德鲁伊通过她的祝福沟通自然与元素之灵，但她究竟是原始的巨人、世界之魂，还是某种象征意义的隐喻，始终是信仰的问题。",al={"大地母亲是真的吗","大地母亲存在吗","大地母亲是谁"}},{q="其他种族也崇拜大地母亲吗？",a="虽然牛头人是她主要的崇拜者，但其他与大地沟通的种族也承认她的存在。一些兽人萨满和半人马会怀着敬意祈祷她的名字，而在部落之中，她的祝福也常被人们相互传递。",al={"兽人与大地母亲","谁崇拜大地母亲","巨魔信仰大地母亲吗"}},{q="牛头人相信死后会发生什么？",a="牛头人相信，既然万物皆生于大地母亲慈爱的抚触，每个灵魂在死后都会回归她。传统的葬礼将逝者送还给大地，信任他们的灵魂能在她永恒的拥抱中安息。",al={"牛头人的死后世界","牛头人的葬礼信仰","回归大地母亲"}}},fx={dbad9a55={q="大地母亲如何创造世界和牛头人？",a="根据牛头人的创世神话，大地母亲在记忆的曙光到来之前塑造了山川、海洋与天空。她生下双生子安舍与穆莎，也就是太阳与月亮，之后赋予平原生命，并创造了最初的牛头人，对他们疼爱有加。牛头人相信，她的灵魂至今仍栖居于世间的每一条河流、每一棵树、每一片平原和每一座山脉之中。",al={"大地母亲创世故事","大地母亲如何创造世界","大地母亲的历史"}}},fp="12,417,20.438.0,27.543.0,19.308.0,13.367.0,24.227.0,29.224.0,44.296.0,40.226.0,43.253.0"}
